(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("rep-e",[{"sp":"N","t":"Σωκράτης κατέβην χθὲς εἰς Πειραιᾶ μετὰ Γλαύκωνος τοῦ Ἀρίστωνος προσευξόμενός τε τῇ θεῷ καὶ ἅμα τὴν ἑορτὴν βουλόμενος θεάσασθαι τίνα τρόπον ποιήσουσιν ἅτε νῦν πρῶτον ἄγοντες. καλὴ μὲν οὖν μοι καὶ ἡ τῶν ἐπιχωρίων πομπὴ ἔδοξεν εἶναι, οὐ μέντοι ἧττον ἐφαίνετο πρέπειν ἣν οἱ Θρᾷκες ἔπεμπον.","st":"327a"},{"sp":"N","t":"προσευξάμενοι δὲ καὶ θεωρήσαντες ἀπῇμεν πρὸς τὸ ἄστυ. κατιδὼν οὖν πόρρωθεν ἡμᾶς οἴκαδε ὡρμημένους Πολέμαρχος ὁ Κεφάλου ἐκέλευσε δραμόντα τὸν παῖδα περιμεῖναί ἑ κελεῦσαι. καί μου ὄπισθεν ὁ παῖς λαβόμενος τοῦ ἱματίου, κελεύει ὑμᾶς, ἔφη, Πολέμαρχος περιμεῖναι. καὶ ἐγὼ μετεστράφην τε καὶ ἠρόμην ὅπου αὐτὸς εἴη. οὗτος, ἔφη, ὄπισθεν προσέρχεται· ἀλλὰ περιμένετε. ἀλλὰ περιμενοῦμεν, ἦ δ’ ὃς ὁ Γλαύκων.","st":"327b"},{"sp":"N","t":"καὶ ὀλίγῳ ὕστερον ὅ τε Πολέμαρχος ἧκε καὶ Ἀδείμαντος ὁ τοῦ Γλαύκωνος ἀδελφὸς καὶ Νικήρατος ὁ Νικίου καὶ ἄλλοι τινὲς ὡς ἀπὸ τῆς πομπῆς.","st":"327c"},{"sp":"N","t":"Σωκράτης, Γλαύκων, Πολέμαρχος, Αδείμαντος","st":"327c"},{"sp":"N","t":"ὁ οὖν Πολέμαρχος ἔφη· ὦ Σώκρατες, δοκεῖτέ μοι πρὸς ἄστυ ὡρμῆσθαι ὡς ἀπιόντες.","st":"327c"},{"sp":"N","t":"οὐ γὰρ κακῶς δοξάζεις, ἦν δ’ ἐγώ.","st":"327c"},{"sp":"N","t":"ὁρᾷς οὖν ἡμᾶς, ἔφη, ὅσοι ἐσμέν;","st":"327c"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"327c"},{"sp":"N","t":"ἢ τοίνυν τούτων, ἔφη, κρείττους γένεσθε ἢ μένετ’ αὐτοῦ.","st":"327c"},{"sp":"N","t":"οὐκοῦν, ἦν δ’ ἐγώ, ἔτι ἓν λείπεται, τὸ ἢν πείσωμεν ὑμᾶς ὡς χρὴ ἡμᾶς ἀφεῖναι;","st":"327c"},{"sp":"N","t":"ἦ καὶ δύναισθ’ ἄν, ἦ δ’ ὅς, πεῖσαι μὴ ἀκούοντας;","st":"327c"},{"sp":"N","t":"οὐδαμῶς, ἔφη ὁ Γλαύκων.","st":"327c"},{"sp":"N","t":"ὡς τοίνυν μὴ ἀκουσομένων, οὕτω διανοεῖσθε.","st":"327c"},{"sp":"N","t":"καὶ ὁ Ἀδείμαντος, ἆρά γε, ἦ δ’ ὅς, οὐδ’ ἴστε ὅτι λαμπὰς ἔσται πρὸς ἑσπέραν ἀφ’ ἵππων τῇ θεῷ;","st":"328a"},{"sp":"N","t":"ἀφ’ ἵππων; ἦν δ’ ἐγώ· καινόν γε τοῦτο. λαμπάδια ἔχοντες διαδώσουσιν ἀλλήλοις ἁμιλλώμενοι τοῖς ἵπποις; ἢ πῶς λέγεις;","st":"328a"},{"sp":"N","t":"οὕτως, ἔφη ὁ Πολέμαρχος. καὶ πρός γε παννυχίδα ποιήσουσιν, ἣν ἄξιον θεάσασθαι· ἐξαναστησόμεθα γὰρ μετὰ τὸ δεῖπνον καὶ τὴν παννυχίδα θεασόμεθα. καὶ συνεσόμεθά τε πολλοῖς τῶν νέων αὐτόθι καὶ διαλεξόμεθα. ἀλλὰ μένετε","st":"328a"},{"sp":"N","t":"καὶ μὴ ἄλλως ποιεῖτε.","st":"328b"},{"sp":"N","t":"καὶ ὁ Γλαύκων, ἔοικεν, ἔφη, μενετέον εἶναι.","st":"328b"},{"sp":"N","t":"ἀλλ’ εἰ δοκεῖ, ἦν δ’ ἐγώ, οὕτω χρὴ ποιεῖν.","st":"328b"},{"sp":"N","t":"Σωκράτης, Γλαύκων, Κέφαλος","st":"328b"},{"sp":"N","t":"ἦιμεν οὖν οἴκαδε εἰς τοῦ Πολεμάρχου, καὶ Λυσίαν τε αὐτόθι κατελάβομεν καὶ Εὐθύδημον, τοὺς τοῦ Πολεμάρχου ἀδελφούς, καὶ δὴ καὶ Θρασύμαχον τὸν Καλχηδόνιον καὶ Χαρμαντίδην τὸν Παιανιᾶ καὶ Κλειτοφῶντα τὸν Ἀριστωνύμου· ἦν δ’ ἔνδον καὶ ὁ πατὴρ ὁ τοῦ Πολεμάρχου Κέφαλος. καὶ μάλα πρεσβύτης μοι ἔδοξεν εἶναι· διὰ χρόνου γὰρ καὶ","st":"328b"},{"sp":"N","t":"ἑωράκη αὐτόν. καθῆστο δὲ ἐστεφανωμένος ἐπί τινος προσκεφαλαίου τε καὶ δίφρου· τεθυκὼς γὰρ ἐτύγχανεν ἐν τῇ αὐλῇ. ἐκαθεζόμεθα οὖν παρ’ αὐτόν· ἔκειντο γὰρ δίφροι τινὲς αὐτόθι κύκλῳ.","st":"328c"},{"sp":"N","t":"εὐθὺς οὖν με ἰδὼν ὁ Κέφαλος ἠσπάζετό τε καὶ εἶπεν· ὦ Σώκρατες, οὐ δὲ θαμίζεις ἡμῖν καταβαίνων εἰς τὸν Πειραιᾶ. χρῆν μέντοι. εἰ μὲν γὰρ ἐγὼ ἔτι ἐν δυνάμει ἦ τοῦ ῥᾳδίως πορεύεσθαι πρὸς τὸ ἄστυ, οὐδὲν ἂν σὲ ἔδει δεῦρο","st":"328c"},{"sp":"N","t":"ἰέναι, ἀλλ’ ἡμεῖς ἂν παρὰ σὲ ᾖμεν· νῦν δέ σε χρὴ πυκνότερον δεῦρο ἰέναι. ὡς εὖ ἴσθι ὅτι ἔμοιγε ὅσον αἱ ἄλλαι αἱ κατὰ τὸ σῶμα ἡδοναὶ ἀπομαραίνονται, τοσοῦτον αὔξονται αἱ περὶ τοὺς λόγους ἐπιθυμίαι τε καὶ ἡδοναί. μὴ οὖν ἄλλως ποίει, ἀλλὰ τοῖσδέ τε τοῖς νεανίσκοις σύνισθι καὶ δεῦρο παρ’ ἡμᾶς φοίτα ὡς παρὰ φίλους τε καὶ πάνυ οἰκείους.","st":"328d"},{"sp":"N","t":"καὶ μήν, ἦν δ’ ἐγώ, ὦ Κέφαλε, χαίρω γε διαλεγόμενος","st":"328d"},{"sp":"N","t":"τοῖς σφόδρα πρεσβύταις· δοκεῖ γάρ μοι χρῆναι παρ’ αὐτῶν πυνθάνεσθαι, ὥσπερ τινὰ ὁδὸν προεληλυθότων ἣν καὶ ἡμᾶς ἴσως δεήσει πορεύεσθαι, ποία τίς ἐστιν, τραχεῖα καὶ χαλεπή, ἢ ῥᾳδία καὶ εὔπορος. καὶ δὴ καὶ σοῦ ἡδέως ἂν πυθοίμην ὅτι σοι φαίνεται τοῦτο, ἐπειδὴ ἐνταῦθα ἤδη εἶ τῆς ἡλικίας ὃ δὴ “ἐπὶ γήραος οὐδῷ” φασιν εἶναι οἱ ποιηταί, πότερον χαλεπὸν τοῦ βίου, ἢ πῶς σὺ αὐτὸ ἐξαγγέλλεις.","st":"328e"},{"sp":"N","t":"ἐγώ σοι, ἔφη, νὴ τὸν Δία ἐρῶ, ὦ Σώκρατες, οἷόν γέ μοι φαίνεται. πολλάκις γὰρ συνερχόμεθά τινες εἰς ταὐτὸν παραπλησίαν ἡλικίαν ἔχοντες, διασῴζοντες τὴν παλαιὰν παροιμίαν· οἱ οὖν πλεῖστοι ἡμῶν ὀλοφύρονται συνιόντες, τὰς ἐν τῇ νεότητι ἡδονὰς ποθοῦντες καὶ ἀναμιμνῃσκόμενοι περί τε τἀφροδίσια καὶ περὶ πότους τε καὶ εὐωχίας καὶ ἄλλ’ ἄττα ἃ τῶν τοιούτων ἔχεται, καὶ ἀγανακτοῦσιν ὡς μεγάλων τινῶν ἀπεστερημένοι καὶ τότε μὲν εὖ ζῶντες, νῦν δὲ οὐδὲ ζῶντες.","st":"329a"},{"sp":"N","t":"ἔνιοι δὲ καὶ τὰς τῶν οἰκείων προπηλακίσεις τοῦ γήρως ὀδύρονται, καὶ ἐπὶ τούτῳ δὴ τὸ γῆρας ὑμνοῦσιν ὅσων κακῶν σφίσιν αἴτιον. ἐμοὶ δὲ δοκοῦσιν, ὦ Σώκρατες, οὗτοι οὐ τὸ αἴτιον αἰτιᾶσθαι. εἰ γὰρ ἦν τοῦτ’ αἴτιον, κἂν ἐγὼ τὰ αὐτὰ ταῦτα ἐπεπόνθη, ἕνεκά γε γήρως, καὶ οἱ ἄλλοι πάντες ὅσοι ἐνταῦθα ἦλθον ἡλικίας. νῦν δ’ ἔγωγε ἤδη ἐντετύχηκα οὐχ οὕτως ἔχουσιν καὶ ἄλλοις, καὶ δὴ καὶ Σοφοκλεῖ ποτε τῷ ποιητῇ παρεγενόμην ἐρωτωμένῳ ὑπό τινος· “πῶς,” ἔφη,","st":"329b"},{"sp":"N","t":"“ὦ Σοφόκλεις, ἔχεις πρὸς τἀφροδίσια; ἔτι οἷός τε εἶ γυναικὶ συγγίγνεσθαι”; καὶ ὅς, “εὐφήμει,” ἔφη, “ὦ ἄνθρωπε· ἁσμενέστατα μέντοι αὐτὸ ἀπέφυγον, ὥσπερ λυττῶντά τινα καὶ ἄγριον δεσπότην ἀποδράς.” εὖ οὖν μοι καὶ τότε ἔδοξεν ἐκεῖνος εἰπεῖν, καὶ νῦν οὐχ ἧττον. παντάπασι γὰρ τῶν γε τοιούτων ἐν τῷ γήρᾳ πολλὴ εἰρήνη γίγνεται καὶ ἐλευθερία· ἐπειδὰν αἱ ἐπιθυμίαι παύσωνται κατατείνουσαι καὶ χαλάσωσιν, παντάπασιν τὸ τοῦ Σοφοκλέους γίγνεται,","st":"329c"},{"sp":"N","t":"δεσποτῶν πάνυ πολλῶν ἐστι καὶ μαινομένων ἀπηλλάχθαι. ἀλλὰ καὶ τούτων πέρι καὶ τῶν γε πρὸς τοὺς οἰκείους μία τις αἰτία ἐστίν, οὐ τὸ γῆρας, ὦ Σώκρατες, ἀλλ’ ὁ τρόπος τῶν ἀνθρώπων. ἂν μὲν γὰρ κόσμιοι καὶ εὔκολοι ὦσιν, καὶ τὸ γῆρας μετρίως ἐστὶν ἐπίπονον· εἰ δὲ μή, καὶ γῆρας, ὦ Σώκρατες, καὶ νεότης χαλεπὴ τῷ τοιούτῳ συμβαίνει.","st":"329d"},{"sp":"N","t":"καὶ ἐγὼ ἀγασθεὶς αὐτοῦ εἰπόντος ταῦτα, βουλόμενος ἔτι","st":"329d"},{"sp":"N","t":"λέγειν αὐτὸν ἐκίνουν καὶ εἶπον· ὦ Κέφαλε, οἶμαί σου τοὺς πολλούς, ὅταν ταῦτα λέγῃς, οὐκ ἀποδέχεσθαι ἀλλ’ ἡγεῖσθαί σε ῥᾳδίως τὸ γῆρας φέρειν οὐ διὰ τὸν τρόπον ἀλλὰ διὰ τὸ πολλὴν οὐσίαν κεκτῆσθαι· τοῖς γὰρ πλουσίοις πολλὰ παραμύθιά φασιν εἶναι.","st":"329e"},{"sp":"N","t":"ἀληθῆ, ἔφη, λέγεις· οὐ γὰρ ἀποδέχονται. καὶ λέγουσι μέν τι, οὐ μέντοι γε ὅσον οἴονται· ἀλλὰ τὸ τοῦ Θεμιστοκλέους εὖ ἔχει, ὃς τῷ Σεριφίῳ λοιδορουμένῳ καὶ λέγοντι","st":"329e"},{"sp":"N","t":"ὅτι οὐ δι’ αὑτὸν ἀλλὰ διὰ τὴν πόλιν εὐδοκιμοῖ, ἀπεκρίνατο ὅτι οὔτ’ ἂν αὐτὸς Σερίφιος ὢν ὀνομαστὸς ἐγένετο οὔτ’ ἐκεῖνος Ἀθηναῖος. καὶ τοῖς δὴ μὴ πλουσίοις, χαλεπῶς δὲ τὸ γῆρας φέρουσιν, εὖ ἔχει ὁ αὐτὸς λόγος, ὅτι οὔτ’ ἂν ὁ ἐπιεικὴς πάνυ τι ῥᾳδίως γῆρας μετὰ πενίας ἐνέγκοι οὔθ’ ὁ μὴ ἐπιεικὴς πλουτήσας εὔκολός ποτ’ ἂν ἑαυτῷ γένοιτο.","st":"330a"},{"sp":"N","t":"πότερον δέ, ἦν δ’ ἐγώ, ὦ Κέφαλε, ὧν κέκτησαι τὰ πλείω παρέλαβες ἢ ἐπεκτήσω;","st":"330a"},{"sp":"N","t":"ποῖ’ ἐπεκτησάμην, ἔφη, ὦ Σώκρατες; μέσος τις γέγονα χρηματιστὴς τοῦ τε πάππου καὶ τοῦ πατρός. ὁ μὲν γὰρ πάππος τε καὶ ὁμώνυμος ἐμοὶ σχεδόν τι ὅσην ἐγὼ νῦν οὐσίαν κέκτημαι παραλαβὼν πολλάκις τοσαύτην ἐποίησεν, Λυσανίας δὲ ὁ πατὴρ ἔτι ἐλάττω αὐτὴν ἐποίησε τῆς νῦν οὔσης· ἐγὼ δὲ ἀγαπῶ ἐὰν μὴ ἐλάττω καταλίπω τούτοισιν, ἀλλὰ βραχεῖ γέ τινι πλείω ἢ παρέλαβον.","st":"330b"},{"sp":"N","t":"οὗ τοι ἕνεκα ἠρόμην, ἦν δ’ ἐγώ, ὅτι μοι ἔδοξας οὐ σφόδρα","st":"330b"},{"sp":"N","t":"ἀγαπᾶν τὰ χρήματα, τοῦτο δὲ ποιοῦσιν ὡς τὸ πολὺ οἳ ἂν μὴ αὐτοὶ κτήσωνται· οἱ δὲ κτησάμενοι διπλῇ ἢ οἱ ἄλλοι ἀσπάζονται αὐτά. ὥσπερ γὰρ οἱ ποιηταὶ τὰ αὑτῶν ποιήματα καὶ οἱ πατέρες τοὺς παῖδας ἀγαπῶσιν, ταύτῃ τε δὴ καὶ οἱ χρηματισάμενοι περὶ τὰ χρήματα σπουδάζουσιν ὡς ἔργον ἑαυτῶν, καὶ κατὰ τὴν χρείαν ᾗπερ οἱ ἄλλοι. χαλεποὶ οὖν καὶ συγγενέσθαι εἰσίν, οὐδὲν ἐθέλοντες ἐπαινεῖν ἀλλ’ ἢ τὸν πλοῦτον. ἀληθῆ, ἔφη, λέγεις.","st":"330c"},{"sp":"N","t":"πάνυ μὲν οὖν, ἦν δ’ ἐγώ. ἀλλά μοι ἔτι τοσόνδε εἰπέ· τί μέγιστον οἴει ἀγαθὸν ἀπολελαυκέναι τοῦ πολλὴν οὐσίαν κεκτῆσθαι;","st":"330d"},{"sp":"N","t":"ὅ, ἦ δ’ ὅς, ἴσως οὐκ ἂν πολλοὺς πείσαιμι λέγων. εὖ γὰρ ἴσθι, ἔφη, ὦ Σώκρατες, ὅτι, ἐπειδάν τις ἐγγὺς ᾖ τοῦ οἴεσθαι τελευτήσειν, εἰσέρχεται αὐτῷ δέος καὶ φροντὶς περὶ ὧν ἔμπροσθεν οὐκ εἰσῄει. οἵ τε γὰρ λεγόμενοι μῦθοι περὶ τῶν ἐν Ἅιδου, ὡς τὸν ἐνθάδε ἀδικήσαντα δεῖ ἐκεῖ διδόναι","st":"330d"},{"sp":"N","t":"δίκην, καταγελώμενοι τέως, τότε δὴ στρέφουσιν αὐτοῦ τὴν ψυχὴν μὴ ἀληθεῖς ὦσιν· καὶ αὐτός — ἤτοι ὑπὸ τῆς τοῦ γήρως ἀσθενείας ἢ καὶ ὥσπερ ἤδη ἐγγυτέρω ὢν τῶν ἐκεῖ μᾶλλόν τι καθορᾷ αὐτά — ὑποψίας δ’ οὖν καὶ δείματος μεστὸς γίγνεται καὶ ἀναλογίζεται ἤδη καὶ σκοπεῖ εἴ τινά τι ἠδίκησεν. ὁ μὲν οὖν εὑρίσκων ἑαυτοῦ ἐν τῷ βίῳ πολλὰ ἀδικήματα καὶ ἐκ τῶν ὕπνων, ὥσπερ οἱ παῖδες, θαμὰ ἐγειρόμενος δειμαίνει","st":"330e"},{"sp":"N","t":"καὶ ζῇ μετὰ κακῆς ἐλπίδος· τῷ δὲ μηδὲν ἑαυτῷ ἄδικον συνειδότι ἡδεῖα ἐλπὶς ἀεὶ πάρεστι καὶ ἀγαθὴ γηροτρόφος, ὡς καὶ Πίνδαρος λέγει. χαριέντως γάρ τοι, ὦ Σώκρατες, τοῦτ’ ἐκεῖνος εἶπεν, ὅτι ὃς ἂν δικαίως καὶ ὁσίως τὸν βίον διαγάγῃ,","st":"331a"},{"sp":"N","t":"γλυκεῖά οἱ καρδίαν","st":"331a"},{"sp":"N","t":"ἀτάλλοισα γηροτρόφος συναορεῖ","st":"331a"},{"sp":"N","t":"ἐλπὶς ἃ μάλιστα θνατῶν πολύστροφον","st":"331a"},{"sp":"N","t":"γνώμαν κυβερνᾷ.","st":"331a"},{"sp":"N","t":"εὖ οὖν λέγει θαυμαστῶς ὡς σφόδρα. πρὸς δὴ τοῦτ’ ἔγωγε τίθημι τὴν τῶν χρημάτων κτῆσιν πλείστου ἀξίαν εἶναι, οὔ","st":"331a"},{"sp":"N","t":"τι παντὶ ἀνδρὶ ἀλλὰ τῷ ἐπιεικεῖ καὶ κοσμίῳ. τὸ γὰρ μηδὲ ἄκοντά τινα ἐξαπατῆσαι ἢ ψεύσασθαι, μηδ’ αὖ ὀφείλοντα ἢ θεῷ θυσίας τινὰς ἢ ἀνθρώπῳ χρήματα ἔπειτα ἐκεῖσε ἀπιέναι δεδιότα, μέγα μέρος εἰς τοῦτο ἡ τῶν χρημάτων κτῆσις συμβάλλεται. ἔχει δὲ καὶ ἄλλας χρείας πολλάς· ἀλλὰ ἕν γε ἀνθ’ ἑνὸς οὐκ ἐλάχιστον ἔγωγε θείην ἂν εἰς τοῦτο ἀνδρὶ νοῦν ἔχοντι, ὦ Σώκρατες, πλοῦτον χρησιμώτατον εἶναι.","st":"331b"},{"sp":"N","t":"παγκάλως, ἦν δ’ ἐγώ, λέγεις, ὦ Κέφαλε. τοῦτο δ’ αὐτό, τὴν δικαιοσύνην, πότερα τὴν ἀλήθειαν αὐτὸ φήσομεν εἶναι ἁπλῶς οὕτως καὶ τὸ ἀποδιδόναι ἄν τίς τι παρά του λάβῃ, ἢ καὶ αὐτὰ ταῦτα ἔστιν ἐνίοτε μὲν δικαίως, ἐνίοτε δὲ ἀδίκως ποιεῖν; οἷον τοιόνδε λέγω· πᾶς ἄν που εἴποι, εἴ τις λάβοι παρὰ φίλου ἀνδρὸς σωφρονοῦντος ὅπλα, εἰ μανεὶς ἀπαιτοῖ, ὅτι οὔτε χρὴ τὰ τοιαῦτα ἀποδιδόναι, οὔτε δίκαιος ἂν εἴη ὁ ἀποδιδούς, οὐδ’ αὖ πρὸς τὸν οὕτως ἔχοντα πάντα ἐθέλων τἀληθῆ λέγειν.","st":"331c"},{"sp":"N","t":"ὀρθῶς, ἔφη, λέγεις.","st":"331d"},{"sp":"N","t":"οὐκ ἄρα οὗτος ὅρος ἐστὶν δικαιοσύνης, ἀληθῆ τε λέγειν καὶ ἃ ἂν λάβῃ τις ἀποδιδόναι.","st":"331d"},{"sp":"N","t":"Σωκράτης, Κέφαλος, Πολέμαρχος","st":"331d"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη, ὦ Σώκρατες, ὑπολαβὼν ὁ Πολέμαρχος, εἴπερ γέ τι χρὴ Σιμωνίδῃ πείθεσθαι.","st":"331d"},{"sp":"N","t":"καὶ μέντοι, ἔφη ὁ Κέφαλος, καὶ παραδίδωμι ὑμῖν τὸν λόγον· δεῖ γάρ με ἤδη τῶν ἱερῶν ἐπιμεληθῆναι.","st":"331d"},{"sp":"N","t":"οὐκοῦν, ἔφη, ἐγώ, ὁ Πολέμαρχος, τῶν γε σῶν κληρονόμος;","st":"331d"},{"sp":"N","t":"πάνυ γε, ἦ δ’ ὃς γελάσας, καὶ ἅμα ᾔει πρὸς τὰ ἱερά.","st":"331d"},{"sp":"N","t":"Σωκράτης, Πολέμαρχος","st":"331d"},{"sp":"N","t":"λέγε δή, εἶπον ἐγώ, σὺ ὁ τοῦ λόγου κληρονόμος, τί φῂς τὸν Σιμωνίδην λέγοντα ὀρθῶς λέγειν περὶ δικαιοσύνης;","st":"331e"},{"sp":"N","t":"ὅτι, ἦ δ’ ὅς, τὸ τὰ ὀφειλόμενα ἑκάστῳ ἀποδιδόναι δίκαιόν ἐστι· τοῦτο λέγων δοκεῖ ἔμοιγε καλῶς λέγειν.","st":"331e"},{"sp":"N","t":"ἀλλὰ μέντοι, ἦν δ’ ἐγώ, Σιμωνίδῃ γε οὐ ῥᾴδιον ἀπιστεῖν — σοφὸς γὰρ καὶ θεῖος ἀνήρ — τοῦτο μέντοι ὅτι ποτὲ λέγει, σὺ μέν, ὦ Πολέμαρχε, ἴσως γιγνώσκεις, ἐγὼ δὲ ἀγνοῶ· δῆλον γὰρ ὅτι οὐ τοῦτο λέγει, ὅπερ ἄρτι ἐλέγομεν, τό τινος παρακαταθεμένου τι ὁτῳοῦν μὴ σωφρόνως ἀπαιτοῦντι","st":"331e"},{"sp":"N","t":"ἀποδιδόναι. καίτοι γε ὀφειλόμενόν πού ἐστιν τοῦτο ὃ παρακατέθετο· ἦ γάρ;","st":"332a"},{"sp":"N","t":"ναί. ἀποδοτέον δέ γε οὐδ’ ὁπωστιοῦν τότε ὁπότε τις μὴ σωφρόνως ἀπαιτοῖ;","st":"332a"},{"sp":"N","t":"ἀληθῆ, ἦ δ’ ὅς.","st":"332a"},{"sp":"N","t":"ἄλλο δή τι ἢ τὸ τοιοῦτον, ὡς ἔοικεν, λέγει Σιμωνίδης τὸ τὰ ὀφειλόμενα δίκαιον εἶναι ἀποδιδόναι.","st":"332a"},{"sp":"N","t":"ἄλλο μέντοι νὴ Δί’, ἔφη· τοῖς γὰρ φίλοις οἴεται ὀφείλειν τοὺς φίλους ἀγαθὸν μέν τι δρᾶν, κακὸν δὲ μηδέν.","st":"332a"},{"sp":"N","t":"μανθάνω, ἦν δ’ ἐγώ — ὅτι οὐ τὰ ὀφειλόμενα ἀποδίδωσιν ὃς ἄν τῳ χρυσίον ἀποδῷ παρακαταθεμένῳ, ἐάνπερ ἡ ἀπόδοσις","st":"332a"},{"sp":"N","t":"καὶ ἡ λῆψις βλαβερὰ γίγνηται, φίλοι δὲ ὦσιν ὅ τε ἀπολαμβάνων καὶ ὁ ἀποδιδούς — οὐχ οὕτω λέγειν φῂς τὸν Σιμωνίδην;","st":"332b"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"332b"},{"sp":"N","t":"τί δέ; τοῖς ἐχθροῖς ἀποδοτέον ὅτι ἂν τύχῃ ὀφειλόμενον;","st":"332b"},{"sp":"N","t":"παντάπασι μὲν οὖν, ἔφη, ὅ γε ὀφείλεται αὐτοῖς, ὀφείλεται δέ γε οἶμαι παρά γε τοῦ ἐχθροῦ τῷ ἐχθρῷ ὅπερ καὶ προσήκει, κακόν τι.","st":"332b"},{"sp":"N","t":"ἠινίξατο ἄρα, ἦν δ’ ἐγώ, ὡς ἔοικεν, ὁ Σιμωνίδης ποιητικῶς","st":"332b"},{"sp":"N","t":"τὸ δίκαιον ὃ εἴη. διενοεῖτο μὲν γάρ, ὡς φαίνεται, ὅτι τοῦτ’ εἴη δίκαιον, τὸ προσῆκον ἑκάστῳ ἀποδιδόναι, τοῦτο δὲ ὠνόμασεν ὀφειλόμενον.","st":"332c"},{"sp":"N","t":"ἀλλὰ τί οἴει; ἔφη.","st":"332c"},{"sp":"N","t":"ὦ πρὸς Διός, ἦν δ’ ἐγώ, εἰ οὖν τις αὐτὸν ἤρετο· “ὦ Σιμωνίδη, ἡ τίσιν οὖν τί ἀποδιδοῦσα ὀφειλόμενον καὶ προσῆκον τέχνη ἰατρικὴ καλεῖται;” τί ἂν οἴει ἡμῖν αὐτὸν ἀποκρίνασθαι;","st":"332c"},{"sp":"N","t":"δῆλον ὅτι, ἔφη, ἡ σώμασιν φάρμακά τε καὶ σιτία καὶ ποτά.","st":"332c"},{"sp":"N","t":"ἡ δὲ τίσιν τί ἀποδιδοῦσα ὀφειλόμενον καὶ προσῆκον τέχνη μαγειρικὴ καλεῖται;","st":"332c"},{"sp":"N","t":"ἡ τοῖς ὄψοις τὰ ἡδύσματα.","st":"332d"},{"sp":"N","t":"εἶεν· ἡ οὖν δὴ τίσιν τί ἀποδιδοῦσα τέχνη δικαιοσύνη ἂν καλοῖτο;","st":"332d"},{"sp":"N","t":"εἰ μέν τι, ἔφη, δεῖ ἀκολουθεῖν, ὦ Σώκρατες, τοῖς ἔμπροσθεν εἰρημένοις, ἡ τοῖς φίλοις τε καὶ ἐχθροῖς ὠφελίας τε καὶ βλάβας ἀποδιδοῦσα.","st":"332d"},{"sp":"N","t":"τὸ τοὺς φίλους ἄρα εὖ ποιεῖν καὶ τοὺς ἐχθροὺς κακῶς δικαιοσύνην λέγει;","st":"332d"},{"sp":"N","t":"δοκεῖ μοι.","st":"332d"},{"sp":"N","t":"τίς οὖν δυνατώτατος κάμνοντας φίλους εὖ ποιεῖν καὶ ἐχθροὺς κακῶς πρὸς νόσον καὶ ὑγίειαν;","st":"332d"},{"sp":"N","t":"ἰατρός.","st":"332d"},{"sp":"N","t":"τίς δὲ πλέοντας πρὸς τὸν τῆς θαλάττης κίνδυνον;","st":"332e"},{"sp":"N","t":"κυβερνήτης.","st":"332e"},{"sp":"N","t":"τί δὲ ὁ δίκαιος; ἐν τίνι πράξει καὶ πρὸς τί ἔργον δυνατώτατος φίλους ὠφελεῖν καὶ ἐχθροὺς βλάπτειν;","st":"332e"},{"sp":"N","t":"ἐν τῷ προσπολεμεῖν καὶ ἐν τῷ συμμαχεῖν, ἔμοιγε δοκεῖ.","st":"332e"},{"sp":"N","t":"εἶεν· μὴ κάμνουσί γε μήν, ὦ φίλε Πολέμαρχε, ἰατρὸς ἄχρηστος.","st":"332e"},{"sp":"N","t":"ἀληθῆ.","st":"332e"},{"sp":"N","t":"καὶ μὴ πλέουσι δὴ κυβερνήτης.","st":"332e"},{"sp":"N","t":"ναί.","st":"332e"},{"sp":"N","t":"ἆρα καὶ τοῖς μὴ πολεμοῦσιν ὁ δίκαιος ἄχρηστος;","st":"332e"},{"sp":"N","t":"οὐ πάνυ μοι δοκεῖ τοῦτο.","st":"332e"},{"sp":"N","t":"χρήσιμον ἄρα καὶ ἐν εἰρήνῃ δικαιοσύνη;","st":"332e"},{"sp":"N","t":"χρήσιμον.","st":"333a"},{"sp":"N","t":"καὶ γὰρ γεωργία· ἢ οὔ;","st":"333a"},{"sp":"N","t":"ναί.","st":"333a"},{"sp":"N","t":"πρός γε καρποῦ κτῆσιν;","st":"333a"},{"sp":"N","t":"ναί.","st":"333a"},{"sp":"N","t":"καὶ μὴν καὶ σκυτοτομική;","st":"333a"},{"sp":"N","t":"ναί.","st":"333a"},{"sp":"N","t":"πρός γε ὑποδημάτων ἂν οἶμαι φαίης κτῆσιν;","st":"333a"},{"sp":"N","t":"πάνυ γε.","st":"333a"},{"sp":"N","t":"τί δὲ δή; τὴν δικαιοσύνην πρὸς τίνος χρείαν ἢ κτῆσιν ἐν εἰρήνῃ φαίης ἂν χρήσιμον εἶναι;","st":"333a"},{"sp":"N","t":"πρὸς τὰ συμβόλαια, ὦ Σώκρατες.","st":"333a"},{"sp":"N","t":"συμβόλαια δὲ λέγεις κοινωνήματα ἤ τι ἄλλο;","st":"333a"},{"sp":"N","t":"κοινωνήματα δῆτα.","st":"333a"},{"sp":"N","t":"ἆρ’ οὖν ὁ δίκαιος ἀγαθὸς καὶ χρήσιμος κοινωνὸς εἰς πεττῶν θέσιν, ἢ ὁ πεττευτικός;","st":"333b"},{"sp":"N","t":"ὁ πεττευτικός.","st":"333b"},{"sp":"N","t":"ἀλλ’ εἰς πλίνθων καὶ λίθων θέσιν ὁ δίκαιος χρησιμώτερός τε καὶ ἀμείνων κοινωνὸς τοῦ οἰκοδομικοῦ;","st":"333b"},{"sp":"N","t":"οὐδαμῶς.","st":"333b"},{"sp":"N","t":"ἀλλ’ εἰς τίνα δὴ κοινωνίαν ὁ δίκαιος ἀμείνων κοινωνὸς τοῦ οἰκοδομικοῦ τε καὶ κιθαριστικοῦ, ὥσπερ ὁ κιθαριστικὸς τοῦ δικαίου εἰς κρουμάτων;","st":"333b"},{"sp":"N","t":"εἰς ἀργυρίου, ἔμοιγε δοκεῖ.","st":"333b"},{"sp":"N","t":"πλήν γ’ ἴσως, ὦ Πολέμαρχε, πρὸς τὸ χρῆσθαι ἀργυρίῳ, ὅταν δέῃ ἀργυρίου κοινῇ πρίασθαι ἢ ἀποδόσθαι ἵππον· τότε","st":"333b"},{"sp":"N","t":"δέ, ὡς ἐγὼ οἶμαι, ὁ ἱππικός. ἦ γάρ;","st":"333c"},{"sp":"N","t":"φαίνεται.","st":"333c"},{"sp":"N","t":"καὶ μὴν ὅταν γε πλοῖον, ὁ ναυπηγὸς ἢ ὁ κυβερνήτης;","st":"333c"},{"sp":"N","t":"ἔοικεν.","st":"333c"},{"sp":"N","t":"ὅταν οὖν τί δέῃ ἀργυρίῳ ἢ χρυσίῳ κοινῇ χρῆσθαι, ὁ δίκαιος χρησιμώτερος τῶν ἄλλων;","st":"333c"},{"sp":"N","t":"ὅταν παρακαταθέσθαι καὶ σῶν εἶναι, ὦ Σώκρατες.","st":"333c"},{"sp":"N","t":"οὐκοῦν λέγεις ὅταν μηδὲν δέῃ αὐτῷ χρῆσθαι ἀλλὰ κεῖσθαι;","st":"333c"},{"sp":"N","t":"πάνυ γε.","st":"333c"},{"sp":"N","t":"ὅταν ἄρα ἄχρηστον ᾖ ἀργύριον, τότε χρήσιμος ἐπ’ αὐτῷ","st":"333c"},{"sp":"N","t":"ἡ δικαιοσύνη;","st":"333d"},{"sp":"N","t":"κινδυνεύει.","st":"333d"},{"sp":"N","t":"καὶ ὅταν δὴ δρέπανον δέῃ φυλάττειν, ἡ δικαιοσύνη χρήσιμος καὶ κοινῇ καὶ ἰδίᾳ· ὅταν δὲ χρῆσθαι, ἡ ἀμπελουργική;","st":"333d"},{"sp":"N","t":"φαίνεται.","st":"333d"},{"sp":"N","t":"φήσεις δὲ καὶ ἀσπίδα καὶ λύραν ὅταν δέῃ φυλάττειν καὶ μηδὲν χρῆσθαι, χρήσιμον εἶναι τὴν δικαιοσύνην, ὅταν δὲ χρῆσθαι, τὴν ὁπλιτικὴν καὶ τὴν μουσικήν;","st":"333d"},{"sp":"N","t":"ἀνάγκη.","st":"333d"},{"sp":"N","t":"καὶ περὶ τἆλλα δὴ πάντα ἡ δικαιοσύνη ἑκάστου ἐν μὲν χρήσει ἄχρηστος, ἐν δὲ ἀχρηστίᾳ χρήσιμος;","st":"333d"},{"sp":"N","t":"κινδυνεύει.","st":"333d"},{"sp":"N","t":"οὐκ ἂν οὖν, ὦ φίλε, πάνυ γέ τι σπουδαῖον εἴη ἡ δικαιοσύνη, εἰ πρὸς τὰ ἄχρηστα χρήσιμον ὂν τυγχάνει. τόδε δὲ σκεψώμεθα. ἆρ’ οὐχ ὁ πατάξαι δεινότατος ἐν μάχῃ εἴτε πυκτικῇ εἴτε τινὶ καὶ ἄλλῃ, οὗτος καὶ φυλάξασθαι;","st":"333e"},{"sp":"N","t":"πάνυ γε.","st":"333e"},{"sp":"N","t":"ἆρ’ οὖν καὶ νόσον ὅστις δεινὸς φυλάξασθαι, καὶ λαθεῖν οὗτος δεινότατος ἐμποιήσας;","st":"333e"},{"sp":"N","t":"ἔμοιγε δοκεῖ.","st":"333e"},{"sp":"N","t":"ἀλλὰ μὴν στρατοπέδου γε ὁ αὐτὸς φύλαξ ἀγαθός, ὅσπερ καὶ τὰ τῶν πολεμίων κλέψαι καὶ βουλεύματα καὶ τὰς ἄλλας πράξεις;","st":"334a"},{"sp":"N","t":"πάνυ γε.","st":"334a"},{"sp":"N","t":"ὅτου τις ἄρα δεινὸς φύλαξ, τούτου καὶ φὼρ δεινός.","st":"334a"},{"sp":"N","t":"ἔοικεν.","st":"334a"},{"sp":"N","t":"εἰ ἄρα ὁ δίκαιος ἀργύριον δεινὸς φυλάττειν, καὶ κλέπτειν δεινός.","st":"334a"},{"sp":"N","t":"ὡς γοῦν ὁ λόγος, ἔφη, σημαίνει.","st":"334a"},{"sp":"N","t":"κλέπτης ἄρα τις ὁ δίκαιος, ὡς ἔοικεν, ἀναπέφανται, καὶ κινδυνεύεις παρ’ Ὁμήρου μεμαθηκέναι αὐτό· καὶ γὰρ ἐκεῖνος","st":"334a"},{"sp":"N","t":"τὸν τοῦ Ὀδυσσέως πρὸς μητρὸς πάππον Αὐτόλυκον ἀγαπᾷ τε καί φησιν αὐτὸν πάντας ἀνθρώπους κεκάσθαι κλεπτοσύνῃ θ’ ὅρκῳ τε. ἔοικεν οὖν ἡ δικαιοσύνη καὶ κατὰ σὲ καὶ καθ’ Ὅμηρον καὶ κατὰ Σιμωνίδην κλεπτική τις εἶναι, ἐπ’ ὠφελίᾳ μέντοι τῶν φίλων καὶ ἐπὶ βλάβῃ τῶν ἐχθρῶν. οὐχ οὕτως ἔλεγες;","st":"334b"},{"sp":"N","t":"οὐ μὰ τὸν Δί’, ἔφη, ἀλλ’ οὐκέτι οἶδα ἔγωγε ὅτι ἔλεγον· τοῦτο μέντοι ἔμοιγε δοκεῖ ἔτι, ὠφελεῖν μὲν τοὺς φίλους ἡ δικαιοσύνη, βλάπτειν δὲ τοὺς ἐχθρούς.","st":"334b"},{"sp":"N","t":"φίλους δὲ λέγεις εἶναι πότερον τοὺς δοκοῦντας ἑκάστῳ χρηστοὺς εἶναι, ἢ τοὺς ὄντας, κἂν μὴ δοκῶσι, καὶ ἐχθροὺς ὡσαύτως;","st":"334c"},{"sp":"N","t":"εἰκὸς μέν, ἔφη, οὓς ἄν τις ἡγῆται χρηστοὺς φιλεῖν, οὓς δ’ ἂν πονηροὺς μισεῖν.","st":"334c"},{"sp":"N","t":"ἆρ’ οὖν οὐχ ἁμαρτάνουσιν οἱ ἄνθρωποι περὶ τοῦτο, ὥστε δοκεῖν αὐτοῖς πολλοὺς μὲν χρηστοὺς εἶναι μὴ ὄντας, πολλοὺς δὲ τοὐναντίον;","st":"334c"},{"sp":"N","t":"ἁμαρτάνουσιν.","st":"334c"},{"sp":"N","t":"τούτοις ἄρα οἱ μὲν ἀγαθοὶ ἐχθροί, οἱ δὲ κακοὶ φίλοι;","st":"334c"},{"sp":"N","t":"πάνυ γε.","st":"334c"},{"sp":"N","t":"ἀλλ’ ὅμως δίκαιον τότε τούτοις τοὺς μὲν πονηροὺς","st":"334c"},{"sp":"N","t":"ὠφελεῖν, τοὺς δὲ ἀγαθοὺς βλάπτειν;","st":"334d"},{"sp":"N","t":"φαίνεται.","st":"334d"},{"sp":"N","t":"ἀλλὰ μὴν οἵ γε ἀγαθοὶ δίκαιοί τε καὶ οἷοι μὴ ἀδικεῖν;","st":"334d"},{"sp":"N","t":"ἀληθῆ.","st":"334d"},{"sp":"N","t":"κατὰ δὴ τὸν σὸν λόγον τοὺς μηδὲν ἀδικοῦντας δίκαιον κακῶς ποιεῖν.","st":"334d"},{"sp":"N","t":"μηδαμῶς, ἔφη, ὦ Σώκρατες· πονηρὸς γὰρ ἔοικεν εἶναι ὁ λόγος.","st":"334d"},{"sp":"N","t":"τοὺς ἀδίκους ἄρα, ἦν δ’ ἐγώ, δίκαιον βλάπτειν, τοὺς δὲ δικαίους ὠφελεῖν;","st":"334d"},{"sp":"N","t":"οὗτος ἐκείνου καλλίων φαίνεται.","st":"334d"},{"sp":"N","t":"πολλοῖς ἄρα, ὦ Πολέμαρχε, συμβήσεται, ὅσοι διημαρτήκασιν","st":"334d"},{"sp":"N","t":"τῶν ἀνθρώπων, δίκαιον εἶναι τοὺς μὲν φίλους βλάπτειν — πονηροὶ γὰρ αὐτοῖς εἰσιν — τοὺς δ’ ἐχθροὺς ὠφελεῖν — ἀγαθοὶ γάρ· καὶ οὕτως ἐροῦμεν αὐτὸ τοὐναντίον ἢ τὸν Σιμωνίδην ἔφαμεν λέγειν.","st":"334e"},{"sp":"N","t":"καὶ μάλα, ἔφη, οὕτω συμβαίνει. ἀλλὰ μεταθώμεθα· κινδυνεύομεν γὰρ οὐκ ὀρθῶς τὸν φίλον καὶ ἐχθρὸν θέσθαι.","st":"334e"},{"sp":"N","t":"πῶς θέμενοι, ὦ Πολέμαρχε;","st":"334e"},{"sp":"N","t":"τὸν δοκοῦντα χρηστόν, τοῦτον φίλον εἶναι.","st":"334e"},{"sp":"N","t":"νῦν δὲ πῶς, ἦν δ’ ἐγώ, μεταθώμεθα;","st":"334e"},{"sp":"N","t":"τὸν δοκοῦντά τε, ἦ δ’ ὅς, καὶ τὸν ὄντα χρηστὸν φίλον","st":"334e"},{"sp":"N","t":"τὸν δὲ δοκοῦντα μέν, ὄντα δὲ μή, δοκεῖν ἀλλὰ μὴ εἶναι φίλον. καὶ περὶ τοῦ ἐχθροῦ δὲ ἡ αὐτὴ θέσις.","st":"335a"},{"sp":"N","t":"φίλος μὲν δή, ὡς ἔοικε, τούτῳ τῷ λόγῳ ὁ ἀγαθὸς ἔσται, ἐχθρὸς δὲ ὁ πονηρός.","st":"335a"},{"sp":"N","t":"ναί.","st":"335a"},{"sp":"N","t":"κελεύεις δὴ ἡμᾶς προσθεῖναι τῷ δικαίῳ ἢ ὡς τὸ πρῶτον ἐλέγομεν, λέγοντες δίκαιον εἶναι τὸν μὲν φίλον εὖ ποιεῖν, τὸν δ’ ἐχθρὸν κακῶς· νῦν πρὸς τούτῳ ὧδε λέγειν, ὅτι ἔστιν δίκαιον τὸν μὲν φίλον ἀγαθὸν ὄντα εὖ ποιεῖν, τὸν δ’ ἐχθρὸν κακὸν ὄντα βλάπτειν;","st":"335a"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη, οὕτως ἄν μοι δοκεῖ καλῶς λέγεσθαι.","st":"335b"},{"sp":"N","t":"ἔστιν ἄρα, ἦν δ’ ἐγώ, δικαίου ἀνδρὸς βλάπτειν καὶ ὁντινοῦν ἀνθρώπων;","st":"335b"},{"sp":"N","t":"καὶ πάνυ γε, ἔφη· τούς γε πονηρούς τε καὶ ἐχθροὺς δεῖ βλάπτειν.","st":"335b"},{"sp":"N","t":"βλαπτόμενοι δ’ ἵπποι βελτίους ἢ χείρους γίγνονται;","st":"335b"},{"sp":"N","t":"χείρους.","st":"335b"},{"sp":"N","t":"ἆρα εἰς τὴν τῶν κυνῶν ἀρετήν, ἢ εἰς τὴν τῶν ἵππων;","st":"335b"},{"sp":"N","t":"εἰς τὴν τῶν ἵππων.","st":"335b"},{"sp":"N","t":"ἆρ’ οὖν καὶ κύνες βλαπτόμενοι χείρους γίγνονται εἰς τὴν τῶν κυνῶν ἀλλ’ οὐκ εἰς τὴν τῶν ἵππων ἀρετήν;","st":"335b"},{"sp":"N","t":"ἀνάγκη.","st":"335b"},{"sp":"N","t":"ἀνθρώπους δέ, ὦ ἑταῖρε, μὴ οὕτω φῶμεν, βλαπτομένους εἰς τὴν ἀνθρωπείαν ἀρετὴν χείρους γίγνεσθαι;","st":"335c"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"335c"},{"sp":"N","t":"ἀλλ’ ἡ δικαιοσύνη οὐκ ἀνθρωπεία ἀρετή;","st":"335c"},{"sp":"N","t":"καὶ τοῦτ’ ἀνάγκη.","st":"335c"},{"sp":"N","t":"καὶ τοὺς βλαπτομένους ἄρα, ὦ φίλε, τῶν ἀνθρώπων ἀνάγκη ἀδικωτέρους γίγνεσθαι.","st":"335c"},{"sp":"N","t":"ἔοικεν.","st":"335c"},{"sp":"N","t":"ἆρ’ οὖν τῇ μουσικῇ οἱ μουσικοὶ ἀμούσους δύνανται ποιεῖν;","st":"335c"},{"sp":"N","t":"ἀδύνατον.","st":"335c"},{"sp":"N","t":"ἀλλὰ τῇ ἱππικῇ οἱ ἱππικοὶ ἀφίππους;","st":"335c"},{"sp":"N","t":"οὐκ ἔστιν.","st":"335c"},{"sp":"N","t":"ἀλλὰ τῇ δικαιοσύνῃ δὴ οἱ δίκαιοι ἀδίκους; ἢ καὶ","st":"335c"},{"sp":"N","t":"συλλήβδην ἀρετῇ οἱ ἀγαθοὶ κακούς;","st":"335d"},{"sp":"N","t":"ἀλλὰ ἀδύνατον.","st":"335d"},{"sp":"N","t":"οὐ γὰρ θερμότητος οἶμαι ἔργον ψύχειν ἀλλὰ τοῦ ἐναντίου.","st":"335d"},{"sp":"N","t":"ναί.","st":"335d"},{"sp":"N","t":"οὐδὲ ξηρότητος ὑγραίνειν ἀλλὰ τοῦ ἐναντίου.","st":"335d"},{"sp":"N","t":"πάνυ γε.","st":"335d"},{"sp":"N","t":"οὐδὲ δὴ τοῦ ἀγαθοῦ βλάπτειν ἀλλὰ τοῦ ἐναντίου.","st":"335d"},{"sp":"N","t":"φαίνεται.","st":"335d"},{"sp":"N","t":"ὁ δέ γε δίκαιος ἀγαθός;","st":"335d"},{"sp":"N","t":"πάνυ γε.","st":"335d"},{"sp":"N","t":"οὐκ ἄρα τοῦ δικαίου βλάπτειν ἔργον, ὦ Πολέμαρχε, οὔτε φίλον οὔτ’ ἄλλον οὐδένα, ἀλλὰ τοῦ ἐναντίου, τοῦ ἀδίκου.","st":"335d"},{"sp":"N","t":"παντάπασί μοι δοκεῖς ἀληθῆ λέγειν, ἔφη, ὦ Σώκρατες.","st":"335d"},{"sp":"N","t":"εἰ ἄρα τὰ ὀφειλόμενα ἑκάστῳ ἀποδιδόναι φησίν τις δίκαιον εἶναι, τοῦτο δὲ δὴ νοεῖ αὐτῷ τοῖς μὲν ἐχθροῖς βλάβην ὀφείλεσθαι παρὰ τοῦ δικαίου ἀνδρός, τοῖς δὲ φίλοις ὠφελίαν, οὐκ ἦν σοφὸς ὁ ταῦτα εἰπών. οὐ γὰρ ἀληθῆ ἔλεγεν· οὐδαμοῦ γὰρ δίκαιον οὐδένα ἡμῖν ἐφάνη ὂν βλάπτειν.","st":"335e"},{"sp":"N","t":"συγχωρῶ, ἦ δ’ ὅς.","st":"335e"},{"sp":"N","t":"μαχούμεθα ἄρα, ἦν δ’ ἐγώ, κοινῇ ἐγώ τε καὶ σύ, ἐάν τις αὐτὸ φῇ ἢ Σιμωνίδην ἢ Βίαντα ἢ Πιττακὸν εἰρηκέναι ἤ τιν’ ἄλλον τῶν σοφῶν τε καὶ μακαρίων ἀνδρῶν.","st":"335e"},{"sp":"N","t":"ἐγὼ γοῦν, ἔφη, ἕτοιμός εἰμι κοινωνεῖν τῆς μάχης.","st":"335e"},{"sp":"N","t":"ἀλλ’ οἶσθα, ἦν δ’ ἐγώ, οὗ μοι δοκεῖ εἶναι τὸ ῥῆμα, τὸ φάναι δίκαιον εἶναι τοὺς μὲν φίλους ὠφελεῖν, τοὺς δ’ ἐχθροὺς βλάπτειν;","st":"336a"},{"sp":"N","t":"τίνος; ἔφη.","st":"336a"},{"sp":"N","t":"οἶμαι αὐτὸ Περιάνδρου εἶναι ἢ Περδίκκου ἢ Ξέρξου ἢ Ἰσμηνίου τοῦ Θηβαίου ἤ τινος ἄλλου μέγα οἰομένου δύνασθαι πλουσίου ἀνδρός.","st":"336a"},{"sp":"N","t":"ἀληθέστατα, ἔφη, λέγεις.","st":"336a"},{"sp":"N","t":"εἶεν, ἦν δ’ ἐγώ· ἐπειδὴ δὲ οὐδὲ τοῦτο ἐφάνη ἡ δικαιοσύνη ὂν οὐδὲ τὸ δίκαιον, τί ἂν ἄλλο τις αὐτὸ φαίη εἶναι;","st":"336a"},{"sp":"N","t":"καὶ ὁ Θρασύμαχος πολλάκις μὲν καὶ διαλεγομένων ἡμῶν μεταξὺ ὥρμα ἀντιλαμβάνεσθαι τοῦ λόγου, ἔπειτα ὑπὸ τῶν παρακαθημένων διεκωλύετο βουλομένων διακοῦσαι τὸν λόγον· ὡς δὲ διεπαυσάμεθα καὶ ἐγὼ ταῦτ’ εἶπον, οὐκέτι ἡσυχίαν ἦγεν, ἀλλὰ συστρέψας ἑαυτὸν ὥσπερ θηρίον ἧκεν ἐφ’ ἡμᾶς ὡς διαρπασόμενος.","st":"336b"},{"sp":"N","t":"Σωκράτης, Πολέμαρχος, Θρασύμαχος","st":"336b"},{"sp":"N","t":"καὶ ἐγώ τε καὶ ὁ Πολέμαρχος δείσαντες διεπτοήθημεν· ὁ δ’ εἰς τὸ μέσον φθεγξάμενος, τίς, ἔφη, ὑμᾶς πάλαι φλυαρία","st":"336b"},{"sp":"N","t":"ἔχει, ὦ Σώκρατες; καὶ τί εὐηθίζεσθε πρὸς ἀλλήλους ὑποκατακλινόμενοι ὑμῖν αὐτοῖς; ἀλλ’ εἴπερ ὡς ἀληθῶς βούλει εἰδέναι τὸ δίκαιον ὅτι ἔστι, μὴ μόνον ἐρώτα μηδὲ φιλοτιμοῦ ἐλέγχων ἐπειδάν τίς τι ἀποκρίνηται, ἐγνωκὼς τοῦτο, ὅτι ῥᾷον ἐρωτᾶν ἢ ἀποκρίνεσθαι, ἀλλὰ καὶ αὐτὸς ἀπόκριναι καὶ εἰπὲ τί φῂς εἶναι τὸ δίκαιον. καὶ ὅπως μοι μὴ ἐρεῖς ὅτι τὸ","st":"336c"},{"sp":"N","t":"δέον ἐστὶν μηδ’ ὅτι τὸ ὠφέλιμον μηδ’ ὅτι τὸ λυσιτελοῦν μηδ’ ὅτι τὸ κερδαλέον μηδ’ ὅτι τὸ συμφέρον, ἀλλὰ σαφῶς μοι καὶ ἀκριβῶς λέγε ὅτι ἂν λέγῃς· ὡς ἐγὼ οὐκ ἀποδέξομαι ἐὰν ὕθλους τοιούτους λέγῃς.","st":"336d"},{"sp":"N","t":"καὶ ἐγὼ ἀκούσας ἐξεπλάγην καὶ προσβλέπων αὐτὸν ἐφοβούμην, καί μοι δοκῶ, εἰ μὴ πρότερος ἑωράκη αὐτὸν ἢ ἐκεῖνος ἐμέ, ἄφωνος ἂν γενέσθαι. νῦν δὲ ἡνίκα ὑπὸ τοῦ λόγου ἤρχετο ἐξαγριαίνεσθαι, προσέβλεψα αὐτὸν πρότερος,","st":"336d"},{"sp":"N","t":"ὥστε αὐτῷ οἷός τ’ ἐγενόμην ἀποκρίνασθαι, καὶ εἶπον ὑποτρέμων· ὦ Θρασύμαχε, μὴ χαλεπὸς ἡμῖν ἴσθι· εἰ γάρ τι ἐξαμαρτάνομεν ἐν τῇ τῶν λόγων σκέψει ἐγώ τε καὶ ὅδε, εὖ ἴσθι ὅτι ἄκοντες ἁμαρτάνομεν. μὴ γὰρ δὴ οἴου, εἰ μὲν χρυσίον ἐζητοῦμεν, οὐκ ἄν ποτε ἡμᾶς ἑκόντας εἶναι ὑποκατακλίνεσθαι ἀλλήλοις ἐν τῇ ζητήσει καὶ διαφθείρειν τὴν εὕρεσιν αὐτοῦ, δικαιοσύνην δὲ ζητοῦντας, πρᾶγμα πολλῶν χρυσίων τιμιώτερον, ἔπειθ’ οὕτως ἀνοήτως ὑπείκειν ἀλλήλοις καὶ οὐ σπουδάζειν ὅτι μάλιστα φανῆναι αὐτό. οἴου γε σύ, ὦ φίλε. ἀλλ’ οἶμαι οὐ δυνάμεθα· ἐλεεῖσθαι οὖν ἡμᾶς πολὺ","st":"336e"},{"sp":"N","t":"μᾶλλον εἰκός ἐστίν που ὑπὸ ὑμῶν τῶν δεινῶν ἢ χαλεπαίνεσθαι.","st":"337a"},{"sp":"N","t":"καὶ ὃς ἀκούσας ἀνεκάγχασέ τε μάλα σαρδάνιον καὶ εἶπεν· ὦ Ἡράκλεις, ἔφη, αὕτη ‘κείνη ἡ εἰωθυῖα εἰρωνεία Σωκράτους, καὶ ταῦτ’ ἐγὼ ᾔδη τε καὶ τούτοις προύλεγον, ὅτι σὺ ἀποκρίνασθαι μὲν οὐκ ἐθελήσοις, εἰρωνεύσοιο δὲ καὶ πάντα μᾶλλον ποιήσοις ἢ ἀποκρινοῖο, εἴ τίς τί σε ἐρωτᾷ.","st":"337a"},{"sp":"N","t":"σοφὸς γὰρ εἶ, ἦν δ’ ἐγώ, ὦ Θρασύμαχε· εὖ οὖν ᾔδησθα ὅτι εἴ τινα ἔροιο ὁπόσα ἐστὶν τὰ δώδεκα, καὶ ἐρόμενος προείποις","st":"337a"},{"sp":"N","t":"αὐτῷ—”ὅπως μοι, ὦ ἄνθρωπε, μὴ ἐρεῖς ὅτι ἔστιν τὰ δώδεκα δὶς ἓξ μηδ’ ὅτι τρὶς τέτταρα μηδ’ ὅτι ἑξάκις δύο μηδ’ ὅτι τετράκις τρία· ὡς οὐκ ἀποδέξομαί σου ἐὰν τοιαῦτα φλυαρῇς” — δῆλον οἶμαί σοι ἦν ὅτι οὐδεὶς ἀποκρινοῖτο τῷ οὕτως πυνθανομένῳ. ἀλλ’ εἴ σοι εἶπεν· “ὦ Θρασύμαχε, πῶς λέγεις; μὴ ἀποκρίνωμαι ὧν προεῖπες μηδέν; πότερον, ὦ θαυμάσιε, μηδ’ εἰ τούτων τι τυγχάνει ὄν, ἀλλ’ ἕτερον εἴπω τι","st":"337b"},{"sp":"N","t":"τοῦ ἀληθοῦς; ἢ πῶς λέγεις;” τί ἂν αὐτῷ εἶπες πρὸς ταῦτα;","st":"337c"},{"sp":"N","t":"εἶεν, ἔφη· ὡς δὴ ὅμοιον τοῦτο ἐκείνῳ.","st":"337c"},{"sp":"N","t":"οὐδέν γε κωλύει, ἦν δ’ ἐγώ· εἰ δ’ οὖν καὶ μὴ ἔστιν ὅμοιον, φαίνεται δὲ τῷ ἐρωτηθέντι τοιοῦτον, ἧττόν τι αὐτὸν οἴει ἀποκρινεῖσθαι τὸ φαινόμενον ἑαυτῷ, ἐάντε ἡμεῖς ἀπαγορεύωμεν ἐάντε μή;","st":"337c"},{"sp":"N","t":"ἄλλο τι οὖν, ἔφη, καὶ σὺ οὕτω ποιήσεις· ὧν ἐγὼ ἀπεῖπον, τούτων τι ἀποκρινῇ;","st":"337c"},{"sp":"N","t":"οὐκ ἂν θαυμάσαιμι, ἦν δ’ ἐγώ· εἴ μοι σκεψαμένῳ οὕτω δόξειεν.","st":"337c"},{"sp":"N","t":"τί οὖν, ἔφη, ἂν ἐγὼ δείξω ἑτέραν ἀπόκρισιν παρὰ πάσας ταύτας περὶ δικαιοσύνης, βελτίω τούτων; τί ἀξιοῖς παθεῖν;","st":"337d"},{"sp":"N","t":"τί ἄλλο, ἦν δ’ ἐγώ, ἢ ὅπερ προσήκει πάσχειν τῷ μὴ εἰδότι; προσήκει δέ που μαθεῖν παρὰ τοῦ εἰδότος· καὶ ἐγὼ οὖν τοῦτο ἀξιῶ παθεῖν.","st":"337d"},{"sp":"N","t":"ἡδὺς γὰρ εἶ, ἔφη· ἀλλὰ πρὸς τῷ μαθεῖν καὶ ἀπότεισον ἀργύριον.","st":"337d"},{"sp":"N","t":"οὐκοῦν ἐπειδάν μοι γένηται, εἶπον.","st":"337d"},{"sp":"N","t":"Σωκράτης, Θρασύμαχος, Γλαύκων","st":"337d"},{"sp":"N","t":"ἀλλ’ ἔστιν, ἔφη ὁ Γλαύκων. ἀλλ’ ἕνεκα ἀργυρίου, ὦ Θρασύμαχε, λέγε· πάντες γὰρ ἡμεῖς Σωκράτει εἰσοίσομεν.","st":"337d"},{"sp":"N","t":"πάνυ γε οἶμαι, ἦ δ’ ὅς· ἵνα Σωκράτης τὸ εἰωθὸς διαπράξηται· αὐτὸς μὲν μὴ ἀποκρίνηται, ἄλλου δ’ ἀποκρινομένου λαμβάνῃ λόγον καὶ ἐλέγχῃ. πῶς γὰρ ἄν, ἔφην ἐγώ, ὦ βέλτιστε, τὶς ἀποκρίναιτο πρῶτον μὲν μὴ εἰδὼς μηδὲ φάσκων εἰδέναι, ἔπειτα, εἴ τι καὶ οἴεται, περὶ τούτων ἀπειρημένον αὐτῷ εἴη ὅπως μηδὲν ἐρεῖ ὧν ἡγεῖται ὑπ’ ἀνδρὸς οὐ φαύλου; ἀλλὰ σὲ δὴ μᾶλλον","st":"337e"},{"sp":"N","t":"εἰκὸς λέγειν· σὺ γὰρ δὴ φῂς εἰδέναι καὶ ἔχειν εἰπεῖν. μὴ οὖν ἄλλως ποίει, ἀλλὰ ἐμοί τε χαρίζου ἀποκρινόμενος καὶ μὴ φθονήσῃς καὶ Γλαύκωνα τόνδε διδάξαι καὶ τοὺς ἄλλους.","st":"338a"},{"sp":"N","t":"εἰπόντος δέ μου ταῦτα, ὅ τε Γλαύκων καὶ οἱ ἄλλοι ἐδέοντο αὐτοῦ μὴ ἄλλως ποιεῖν. καὶ ὁ Θρασύμαχος φανερὸς μὲν ἦν ἐπιθυμῶν εἰπεῖν ἵν’ εὐδοκιμήσειεν, ἡγούμενος ἔχειν ἀπόκρισιν παγκάλην· προσεποιεῖτο δὲ φιλονικεῖν πρὸς τὸ ἐμὲ εἶναι τὸν ἀποκρινόμενον. τελευτῶν δὲ συνεχώρησεν,","st":"338a"},{"sp":"N","t":"κἄπειτα, αὕτη δή, ἔφη, ἡ Σωκράτους σοφία· αὐτὸν μὲν μὴ ἐθέλειν διδάσκειν, παρὰ δὲ τῶν ἄλλων περιιόντα μανθάνειν καὶ τούτων μηδὲ χάριν ἀποδιδόναι.","st":"338b"},{"sp":"N","t":"ὅτι μέν, ἦν δ’ ἐγώ, μανθάνω παρὰ τῶν ἄλλων, ἀληθῆ εἶπες, ὦ Θρασύμαχε, ὅτι δὲ οὔ με φῂς χάριν ἐκτίνειν, ψεύδῃ· ἐκτίνω γὰρ ὅσην δύναμαι. δύναμαι δὲ ἐπαινεῖν μόνον· χρήματα γὰρ οὐκ ἔχω. ὡς δὲ προθύμως τοῦτο δρῶ, ἐάν τίς μοι δοκῇ εὖ λέγειν, εὖ εἴσῃ αὐτίκα δὴ μάλα, ἐπειδὰν ἀποκρίνῃ· οἶμαι γάρ σε εὖ ἐρεῖν.","st":"338b"},{"sp":"N","t":"ἄκουε δή, ἦ δ’ ὅς. φημὶ γὰρ ἐγὼ εἶναι τὸ δίκαιον οὐκ ἄλλο τι ἢ τὸ τοῦ κρείττονος συμφέρον. ἀλλὰ τί οὐκ ἐπαινεῖς; ἀλλ’ οὐκ ἐθελήσεις.","st":"338c"},{"sp":"N","t":"ἐὰν μάθω γε πρῶτον, ἔφην, τί λέγεις· νῦν γὰρ οὔπω οἶδα. τὸ τοῦ κρείττονος φῂς συμφέρον δίκαιον εἶναι. καὶ τοῦτο, ὦ Θρασύμαχε, τί ποτε λέγεις; οὐ γάρ που τό γε τοιόνδε φῄς· εἰ Πουλυδάμας ἡμῶν κρείττων ὁ παγκρατιαστὴς καὶ αὐτῷ συμφέρει τὰ βόεια κρέα πρὸς τὸ σῶμα, τοῦτο τὸ","st":"338c"},{"sp":"N","t":"σιτίον εἶναι καὶ ἡμῖν τοῖς ἥττοσιν ἐκείνου συμφέρον ἅμα καὶ δίκαιον.","st":"338d"},{"sp":"N","t":"βδελυρὸς γὰρ εἶ, ἔφη, ὦ Σώκρατες, καὶ ταύτῃ ὑπολαμβάνεις ᾗ ἂν κακουργήσαις μάλιστα τὸν λόγον.","st":"338d"},{"sp":"N","t":"οὐδαμῶς, ὦ ἄριστε, ἦν δ’ ἐγώ· ἀλλὰ σαφέστερον εἰπὲ τί λέγεις.","st":"338d"},{"sp":"N","t":"εἶτ’ οὐκ οἶσθ’, ἔφη, ὅτι τῶν πόλεων αἱ μὲν τυραννοῦνται, αἱ δὲ δημοκρατοῦνται, αἱ δὲ ἀριστοκρατοῦνται;","st":"338d"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"338d"},{"sp":"N","t":"οὐκοῦν τοῦτο κρατεῖ ἐν ἑκάστῃ πόλει, τὸ ἄρχον;","st":"338d"},{"sp":"N","t":"πάνυ γε.","st":"338d"},{"sp":"N","t":"τίθεται δέ γε τοὺς νόμους ἑκάστη ἡ ἀρχὴ πρὸς τὸ αὑτῇ συμφέρον, δημοκρατία μὲν δημοκρατικούς, τυραννὶς δὲ τυραννικούς, καὶ αἱ ἄλλαι οὕτως· θέμεναι δὲ ἀπέφηναν τοῦτο δίκαιον τοῖς ἀρχομένοις εἶναι, τὸ σφίσι συμφέρον, καὶ τὸν τούτου ἐκβαίνοντα κολάζουσιν ὡς παρανομοῦντά τε καὶ ἀδικοῦντα. τοῦτ’ οὖν ἐστιν, ὦ βέλτιστε, ὃ λέγω ἐν ἁπάσαις","st":"338e"},{"sp":"N","t":"ταῖς πόλεσιν ταὐτὸν εἶναι δίκαιον, τὸ τῆς καθεστηκυίας ἀρχῆς συμφέρον· αὕτη δέ που κρατεῖ, ὥστε συμβαίνει τῷ ὀρθῶς λογιζομένῳ πανταχοῦ εἶναι τὸ αὐτὸ δίκαιον, τὸ τοῦ κρείττονος συμφέρον.","st":"339a"},{"sp":"N","t":"νῦν, ἦν δ’ ἐγώ, ἔμαθον ὃ λέγεις· εἰ δὲ ἀληθὲς ἢ μή, πειράσομαι μαθεῖν. τὸ συμφέρον μὲν οὖν, ὦ Θρασύμαχε, καὶ σὺ ἀπεκρίνω δίκαιον εἶναι — καίτοι ἔμοιγε ἀπηγόρευες ὅπως μὴ τοῦτο ἀποκρινοίμην — πρόσεστιν δὲ δὴ αὐτόθι τὸ “τοῦ κρείττονος.”","st":"339a"},{"sp":"N","t":"σμικρά γε ἴσως, ἔφη, προσθήκη.","st":"339b"},{"sp":"N","t":"οὔπω δῆλον οὐδ’ εἰ μεγάλη· ἀλλ’ ὅτι μὲν τοῦτο σκεπτέον εἰ ἀληθῆ λέγεις, δῆλον. ἐπειδὴ γὰρ συμφέρον γέ τι εἶναι καὶ ἐγὼ ὁμολογῶ τὸ δίκαιον, σὺ δὲ προστιθεῖς καὶ αὐτὸ φῂς εἶναι τὸ τοῦ κρείττονος, ἐγὼ δὲ ἀγνοῶ, σκεπτέον δή.","st":"339b"},{"sp":"N","t":"σκόπει, ἔφη.","st":"339b"},{"sp":"N","t":"ταῦτ’ ἔσται, ἦν δ’ ἐγώ. καί μοι εἰπέ· οὐ καὶ πείθεσθαι μέντοι τοῖς ἄρχουσιν δίκαιον φῂς εἶναι;","st":"339b"},{"sp":"N","t":"ἔγωγε.","st":"339b"},{"sp":"N","t":"πότερον δὲ ἀναμάρτητοί εἰσιν οἱ ἄρχοντες ἐν ταῖς πόλεσιν ἑκάσταις ἢ οἷοί τι καὶ ἁμαρτεῖν;","st":"339c"},{"sp":"N","t":"πάντως που, ἔφη, οἷοί τι καὶ ἁμαρτεῖν.","st":"339c"},{"sp":"N","t":"οὐκοῦν ἐπιχειροῦντες νόμους τιθέναι τοὺς μὲν ὀρθῶς τιθέασιν, τοὺς δέ τινας οὐκ ὀρθῶς;","st":"339c"},{"sp":"N","t":"οἶμαι ἔγωγε.","st":"339c"},{"sp":"N","t":"τὸ δὲ ὀρθῶς ἆρα τὸ τὰ συμφέροντά ἐστι τίθεσθαι ἑαυτοῖς, τὸ δὲ μὴ ὀρθῶς ἀσύμφορα; ἢ πῶς λέγεις;","st":"339c"},{"sp":"N","t":"οὕτως.","st":"339c"},{"sp":"N","t":"ἃ δ’ ἂν θῶνται ποιητέον τοῖς ἀρχομένοις, καὶ τοῦτό ἐστι τὸ δίκαιον;","st":"339c"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"339c"},{"sp":"N","t":"οὐ μόνον ἄρα δίκαιόν ἐστιν κατὰ τὸν σὸν λόγον τὸ τοῦ κρείττονος συμφέρον ποιεῖν ἀλλὰ καὶ τοὐναντίον, τὸ μὴ συμφέρον.","st":"339d"},{"sp":"N","t":"τί λέγεις σύ; ἔφη.","st":"339d"},{"sp":"N","t":"ἃ σὺ λέγεις, ἔμοιγε δοκῶ· σκοπῶμεν δὲ βέλτιον. οὐχ ὡμολόγηται τοὺς ἄρχοντας τοῖς ἀρχομένοις προστάττοντας ποιεῖν ἄττα ἐνίοτε διαμαρτάνειν τοῦ ἑαυτοῖς βελτίστου, ἃ δ’ ἂν προστάττωσιν οἱ ἄρχοντες δίκαιον εἶναι τοῖς ἀρχομένοις ποιεῖν; ταῦτ’ οὐχ ὡμολόγηται;","st":"339d"},{"sp":"N","t":"οἶμαι ἔγωγε, ἔφη.","st":"339d"},{"sp":"N","t":"οἴου τοίνυν, ἦν δ’ ἐγώ, καὶ τὸ ἀσύμφορα ποιεῖν τοῖς ἄρχουσί τε καὶ κρείττοσι δίκαιον εἶναι ὡμολογῆσθαί σοι, ὅταν οἱ μὲν ἄρχοντες ἄκοντες κακὰ αὑτοῖς προστάττωσιν, τοῖς δὲ δίκαιον εἶναι φῇς ταῦτα ποιεῖν ἃ ἐκεῖνοι προσέταξαν — ἆρα τότε, ὦ σοφώτατε Θρασύμαχε, οὐκ ἀναγκαῖον συμβαίνειν αὐτὸ οὑτωσί, δίκαιον εἶναι ποιεῖν τοὐναντίον ἢ ὃ σὺ λέγεις; τὸ γὰρ τοῦ κρείττονος ἀσύμφορον δήπου προστάττεται τοῖς ἥττοσιν ποιεῖν.","st":"339e"},{"sp":"N","t":"ναὶ μὰ Δί’, ἔφη, ὦ Σώκρατες, ὁ Πολέμαρχος, σαφέστατά γε.","st":"340a"},{"sp":"N","t":"Σωκράτης, Κλειτοφών, Πολέμαρχος, Θρασύμαχος","st":"340a"},{"sp":"N","t":"ἐὰν σύ γ’, ἔφη, αὐτῷ μαρτυρήσῃς, ὁ Κλειτοφῶν ὑπολαβών.","st":"340a"},{"sp":"N","t":"καὶ τί, ἔφη, δεῖται μάρτυρος; αὐτὸς γὰρ Θρασύμαχος ὁμολογεῖ τοὺς μὲν ἄρχοντας ἐνίοτε ἑαυτοῖς κακὰ προστάττειν, τοῖς δὲ δίκαιον εἶναι ταῦτα ποιεῖν. τὸ γὰρ τὰ κελευόμενα ποιεῖν, ὦ Πολέμαρχε, ὑπὸ τῶν ἀρχόντων δίκαιον εἶναι ἔθετο Θρασύμαχος.","st":"340a"},{"sp":"N","t":"καὶ γὰρ τὸ τοῦ κρείττονος, ὦ Κλειτοφῶν, συμφέρον","st":"340a"},{"sp":"N","t":"δίκαιον εἶναι ἔθετο. ταῦτα δὲ ἀμφότερα θέμενος ὡμολόγησεν αὖ ἐνίοτε τοὺς κρείττους τὰ αὑτοῖς ἀσύμφορα κελεύειν τοὺς ἥττους τε καὶ ἀρχομένους ποιεῖν. ἐκ δὲ τούτων τῶν ὁμολογιῶν οὐδὲν μᾶλλον τὸ τοῦ κρείττονος συμφέρον δίκαιον ἂν εἴη ἢ τὸ μὴ συμφέρον.","st":"340b"},{"sp":"N","t":"ἀλλ’, ἔφη ὁ Κλειτοφῶν, τὸ τοῦ κρείττονος συμφέρον ἔλεγεν ὃ ἡγοῖτο ὁ κρείττων αὑτῷ συμφέρειν· τοῦτο ποιητέον εἶναι τῷ ἥττονι, καὶ τὸ δίκαιον τοῦτο ἐτίθετο.","st":"340b"},{"sp":"N","t":"ἀλλ’ οὐχ οὕτως, ἦ δ’ ὃς ὁ Πολέμαρχος, ἐλέγετο.","st":"340b"},{"sp":"N","t":"Σωκράτης, Θρασύμαχος","st":"340b"},{"sp":"N","t":"οὐδέν, ἦν δ’ ἐγώ, ὦ Πολέμαρχε, διαφέρει, ἀλλ’ εἰ νῦν οὕτω λέγει Θρασύμαχος, οὕτως αὐτοῦ ἀποδεχώμεθα. καί μοι εἰπέ, ὦ Θρασύμαχε· τοῦτο ἦν ὃ ἐβούλου λέγειν τὸ δίκαιον, τὸ τοῦ κρείττονος συμφέρον δοκοῦν εἶναι τῷ κρείττονι, ἐάντε συμφέρῃ ἐάντε μή; οὕτω σε φῶμεν λέγειν;","st":"340c"},{"sp":"N","t":"ἥκιστά γε, ἔφη· ἀλλὰ κρείττω με οἴει καλεῖν τὸν ἐξαμαρτάνοντα ὅταν ἐξαμαρτάνῃ;","st":"340c"},{"sp":"N","t":"ἔγωγε, εἶπον, ᾤμην σε τοῦτο λέγειν ὅτε τοὺς ἄρχοντας ὡμολόγεις οὐκ ἀναμαρτήτους εἶναι ἀλλά τι καὶ ἐξαμαρτάνειν.","st":"340c"},{"sp":"N","t":"συκοφάντης γὰρ εἶ, ἔφη, ὦ Σώκρατες, ἐν τοῖς λόγοις· ἐπεὶ αὐτίκα ἰατρὸν καλεῖς σὺ τὸν ἐξαμαρτάνοντα περὶ τοὺς κάμνοντας κατ’ αὐτὸ τοῦτο ὃ ἐξαμαρτάνει; ἢ λογιστικόν, ὃς ἂν ἐν λογισμῷ ἁμαρτάνῃ, τότε ὅταν ἁμαρτάνῃ, κατὰ ταύτην τὴν ἁμαρτίαν; ἀλλ’ οἶμαι λέγομεν τῷ ῥήματι οὕτως, ὅτι ὁ ἰατρὸς ἐξήμαρτεν καὶ ὁ λογιστὴς ἐξήμαρτεν καὶ ὁ γραμματιστής· τὸ δ’ οἶμαι ἕκαστος τούτων, καθ’ ὅσον τοῦτ’ ἔστιν","st":"340d"},{"sp":"N","t":"ὃ προσαγορεύομεν αὐτόν, οὐδέποτε ἁμαρτάνει· ὥστε κατὰ τὸν ἀκριβῆ λόγον, ἐπειδὴ καὶ σὺ ἀκριβολογῇ, οὐδεὶς τῶν δημιουργῶν ἁμαρτάνει. ἐπιλειπούσης γὰρ ἐπιστήμης ὁ ἁμαρτάνων ἁμαρτάνει, ἐν ᾧ οὐκ ἔστι δημιουργός· ὥστε δημιουργὸς ἢ σοφὸς ἢ ἄρχων οὐδεὶς ἁμαρτάνει τότε ὅταν ἄρχων ᾖ, ἀλλὰ πᾶς γ’ ἂν εἴποι ὅτι ὁ ἰατρὸς ἥμαρτεν καὶ ὁ ἄρχων ἥμαρτεν. τοιοῦτον οὖν δή σοι καὶ ἐμὲ ὑπόλαβε νυνδὴ ἀποκρίνεσθαι· τὸ δὲ ἀκριβέστατον ἐκεῖνο τυγχάνει ὄν, τὸν ἄρχοντα, καθ’","st":"340e"},{"sp":"N","t":"ὅσον ἄρχων ἐστίν, μὴ ἁμαρτάνειν, μὴ ἁμαρτάνοντα δὲ τὸ αὑτῷ βέλτιστον τίθεσθαι, τοῦτο δὲ τῷ ἀρχομένῳ ποιητέον. ὥστε ὅπερ ἐξ ἀρχῆς ἔλεγον δίκαιον λέγω, τὸ τοῦ κρείττονος ποιεῖν συμφέρον.","st":"341a"},{"sp":"N","t":"εἶεν, ἦν δ’ ἐγώ, ὦ Θρασύμαχε· δοκῶ σοι συκοφαντεῖν;","st":"341a"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη.","st":"341a"},{"sp":"N","t":"οἴει γάρ με ἐξ ἐπιβουλῆς ἐν τοῖς λόγοις κακουργοῦντά σε ἐρέσθαι ὡς ἠρόμην;","st":"341a"},{"sp":"N","t":"εὖ μὲν οὖν οἶδα, ἔφη. καὶ οὐδέν γέ σοι πλέον ἔσται","st":"341a"},{"sp":"N","t":"οὔτε γὰρ ἄν με λάθοις κακουργῶν, οὔτε μὴ λαθὼν βιάσασθαι τῷ λόγῳ δύναιο.","st":"341b"},{"sp":"N","t":"οὐδέ γ’ ἂν ἐπιχειρήσαιμι, ἦν δ’ ἐγώ, ὦ μακάριε. ἀλλ’ ἵνα μὴ αὖθις ἡμῖν τοιοῦτον ἐγγένηται, διόρισαι ποτέρως λέγεις τὸν ἄρχοντά τε καὶ τὸν κρείττονα, τὸν ὡς ἔπος εἰπεῖν ἢ τὸν ἀκριβεῖ λόγῳ, ὃ νυνδὴ ἔλεγες, οὗ τὸ συμφέρον κρείττονος ὄντος δίκαιον ἔσται τῷ ἥττονι ποιεῖν.","st":"341b"},{"sp":"N","t":"τὸν τῷ ἀκριβεστάτῳ, ἔφη, λόγῳ ἄρχοντα ὄντα. πρὸς ταῦτα κακούργει καὶ συκοφάντει, εἴ τι δύνασαι — οὐδέν σου παρίεμαι — ἀλλ’ οὐ μὴ οἷός τ’ ᾖς.","st":"341b"},{"sp":"N","t":"οἴει γὰρ ἄν με, εἶπον, οὕτω μανῆναι ὥστε ξυρεῖν ἐπιχειρεῖν λέοντα καὶ συκοφαντεῖν Θρασύμαχον;","st":"341c"},{"sp":"N","t":"νῦν γοῦν, ἔφη, ἐπεχείρησας, οὐδὲν ὢν καὶ ταῦτα.","st":"341c"},{"sp":"N","t":"ἅδην, ἦν δ’ ἐγώ, τῶν τοιούτων. ἀλλ’ εἰπέ μοι· ὁ τῷ ἀκριβεῖ λόγῳ ἰατρός, ὃν ἄρτι ἔλεγες, πότερον χρηματιστής ἐστιν ἢ τῶν καμνόντων θεραπευτής; καὶ λέγε τὸν τῷ ὄντι ἰατρὸν ὄντα.","st":"341c"},{"sp":"N","t":"τῶν καμνόντων, ἔφη, θεραπευτής.","st":"341c"},{"sp":"N","t":"τί δὲ κυβερνήτης; ὁ ὀρθῶς κυβερνήτης ναυτῶν ἄρχων ἐστὶν ἢ ναύτης;","st":"341c"},{"sp":"N","t":"ναυτῶν ἄρχων.","st":"341c"},{"sp":"N","t":"οὐδὲν οἶμαι τοῦτο ὑπολογιστέον, ὅτι πλεῖ ἐν τῇ νηί, οὐδ’ ἐστὶν κλητέος ναύτης· οὐ γὰρ κατὰ τὸ πλεῖν κυβερνήτης καλεῖται, ἀλλὰ κατὰ τὴν τέχνην καὶ τὴν τῶν ναυτῶν ἀρχήν.","st":"341d"},{"sp":"N","t":"ἀληθῆ, ἔφη.","st":"341d"},{"sp":"N","t":"οὐκοῦν ἑκάστῳ τούτων ἔστιν τι συμφέρον;","st":"341d"},{"sp":"N","t":"πάνυ γε.","st":"341d"},{"sp":"N","t":"οὐ καὶ ἡ τέχνη, ἦν δ’ ἐγώ, ἐπὶ τούτῳ πέφυκεν, ἐπὶ τῷ τὸ συμφέρον ἑκάστῳ ζητεῖν τε καὶ ἐκπορίζειν;","st":"341d"},{"sp":"N","t":"ἐπὶ τούτῳ, ἔφη.","st":"341d"},{"sp":"N","t":"ἆρ’ οὖν καὶ ἑκάστῃ τῶν τεχνῶν ἔστιν τι συμφέρον ἄλλο ἢ ὅτι μάλιστα τελέαν εἶναι;","st":"341d"},{"sp":"N","t":"πῶς τοῦτο ἐρωτᾷς;","st":"341e"},{"sp":"N","t":"ὥσπερ, ἔφην ἐγώ, εἴ με ἔροιο εἰ ἐξαρκεῖ σώματι εἶναι σώματι ἢ προσδεῖταί τινος, εἴποιμ’ ἂν ὅτι “παντάπασι μὲν οὖν προσδεῖται. διὰ ταῦτα καὶ ἡ τέχνη ἐστὶν ἡ ἰατρικὴ νῦν ηὑρημένη, ὅτι σῶμά ἐστιν πονηρὸν καὶ οὐκ ἐξαρκεῖ αὐτῷ τοιούτῳ εἶναι. τούτῳ οὖν ὅπως ἐκπορίζῃ τὰ συμφέροντα, ἐπὶ τούτῳ παρεσκευάσθη ἡ τέχνη.” ἦ ὀρθῶς σοι δοκῶ, ἔφην, ἂν εἰπεῖν οὕτω λέγων, ἢ οὔ;","st":"341e"},{"sp":"N","t":"ὀρθῶς, ἔφη.","st":"341e"},{"sp":"N","t":"τί δὲ δή; αὐτὴ ἡ ἰατρική ἐστιν πονηρά, ἢ ἄλλη τις τέχνη ἔσθ’ ὅτι προσδεῖταί τινος ἀρετῆς — ὥσπερ ὀφθαλμοὶ ὄψεως καὶ ὦτα ἀκοῆς καὶ διὰ ταῦτα ἐπ’ αὐτοῖς δεῖ τινος τέχνης τῆς τὸ συμφέρον εἰς αὐτὰ ταῦτα σκεψομένης τε καὶ ἐκποριούσης — ἆρα καὶ ἐν αὐτῇ τῇ τέχνῃ ἔνι τις πονηρία, καὶ δεῖ ἑκάστῃ τέχνῃ ἄλλης τέχνης ἥτις αὐτῇ τὸ συμφέρον σκέψεται, καὶ τῇ σκοπουμένῃ ἑτέρας αὖ τοιαύτης, καὶ τοῦτ’ ἔστιν ἀπέραντον;","st":"342a"},{"sp":"N","t":"ἢ αὐτὴ αὑτῇ τὸ συμφέρον σκέψεται; ἢ οὔτε αὑτῆς οὔτε ἄλλης προσδεῖται ἐπὶ τὴν αὑτῆς πονηρίαν τὸ συμφέρον σκοπεῖν· οὔτε γὰρ πονηρία οὔτε ἁμαρτία οὐδεμία οὐδεμιᾷ τέχνῃ πάρεστιν, οὐδὲ προσήκει τέχνῃ ἄλλῳ τὸ συμφέρον ζητεῖν ἢ ἐκείνῳ οὗ τέχνη ἐστίν, αὐτὴ δὲ ἀβλαβὴς καὶ ἀκέραιός ἐστιν ὀρθὴ οὖσα, ἕωσπερ ἂν ᾖ ἑκάστη ἀκριβὴς ὅλη ἥπερ ἐστίν; καὶ σκόπει ἐκείνῳ τῷ ἀκριβεῖ λόγῳ· οὕτως ἢ ἄλλως ἔχει;","st":"342b"},{"sp":"N","t":"οὕτως, ἔφη, φαίνεται.","st":"342b"},{"sp":"N","t":"οὐκ ἄρα, ἦν δ’ ἐγώ, ἰατρικὴ ἰατρικῇ τὸ συμφέρον σκοπεῖ ἀλλὰ σώματι.","st":"342c"},{"sp":"N","t":"ναί, ἔφη.","st":"342c"},{"sp":"N","t":"οὐδὲ ἱππικὴ ἱππικῇ ἀλλ’ ἵπποις· οὐδὲ ἄλλη τέχνη οὐδεμία ἑαυτῇ — οὐδὲ γὰρ προσδεῖται — ἀλλ’ ἐκείνῳ οὗ τέχνη ἐστίν.","st":"342c"},{"sp":"N","t":"φαίνεται, ἔφη, οὕτως.","st":"342c"},{"sp":"N","t":"ἀλλὰ μήν, ὦ Θρασύμαχε, ἄρχουσί γε αἱ τέχναι καὶ κρατοῦσιν ἐκείνου οὗπέρ εἰσιν τέχναι.","st":"342c"},{"sp":"N","t":"συνεχώρησεν ἐνταῦθα καὶ μάλα μόγις.","st":"342c"},{"sp":"N","t":"οὐκ ἄρα ἐπιστήμη γε οὐδεμία τὸ τοῦ κρείττονος συμφέρον σκοπεῖ οὐδ’ ἐπιτάττει, ἀλλὰ τὸ τοῦ ἥττονός τε καὶ ἀρχομένου","st":"342c"},{"sp":"N","t":"ὑπὸ ἑαυτῆς.","st":"342d"},{"sp":"N","t":"συνωμολόγησε μὲν καὶ ταῦτα τελευτῶν, ἐπεχείρει δὲ περὶ αὐτὰ μάχεσθαι· ἐπειδὴ δὲ ὡμολόγησεν, ἄλλο τι οὖν, ἦν δ’ ἐγώ, οὐδὲ ἰατρὸς οὐδείς, καθ’ ὅσον ἰατρός, τὸ τῷ ἰατρῷ συμφέρον σκοπεῖ οὐδ’ ἐπιτάττει, ἀλλὰ τὸ τῷ κάμνοντι; ὡμολόγηται γὰρ ὁ ἀκριβὴς ἰατρὸς σωμάτων εἶναι ἄρχων ἀλλ’ οὐ χρηματιστής. ἢ οὐχ ὡμολόγηται;","st":"342d"},{"sp":"N","t":"συνέφη.","st":"342d"},{"sp":"N","t":"οὐκοῦν καὶ ὁ κυβερνήτης ὁ ἀκριβὴς ναυτῶν εἶναι ἄρχων ἀλλ’ οὐ ναύτης;","st":"342d"},{"sp":"N","t":"ὡμολόγηται.","st":"342e"},{"sp":"N","t":"οὐκ ἄρα ὅ γε τοιοῦτος κυβερνήτης τε καὶ ἄρχων τὸ τῷ κυβερνήτῃ συμφέρον σκέψεταί τε καὶ προστάξει, ἀλλὰ τὸ τῷ ναύτῃ τε καὶ ἀρχομένῳ.","st":"342e"},{"sp":"N","t":"συνέφησε μόγις.","st":"342e"},{"sp":"N","t":"οὐκοῦν, ἦν δ’ ἐγώ, ὦ Θρασύμαχε, οὐδὲ ἄλλος οὐδεὶς ἐν οὐδεμιᾷ ἀρχῇ, καθ’ ὅσον ἄρχων ἐστίν, τὸ αὑτῷ συμφέρον σκοπεῖ οὐδ’ ἐπιτάττει, ἀλλὰ τὸ τῷ ἀρχομένῳ καὶ ᾧ ἂν αὐτὸς δημιουργῇ, καὶ πρὸς ἐκεῖνο βλέπων καὶ τὸ ἐκείνῳ συμφέρον καὶ πρέπον, καὶ λέγει ἃ λέγει καὶ ποιεῖ ἃ ποιεῖ ἅπαντα.","st":"342e"},{"sp":"N","t":"ἐπειδὴ οὖν ἐνταῦθα ἦμεν τοῦ λόγου καὶ πᾶσι καταφανὲς ἦν ὅτι ὁ τοῦ δικαίου λόγος εἰς τοὐναντίον περιειστήκει, ὁ Θρασύμαχος ἀντὶ τοῦ ἀποκρίνεσθαι, εἰπέ μοι, ἔφη, ὦ Σώκρατες, τίτθη σοι ἔστιν;","st":"343a"},{"sp":"N","t":"τί δέ; ἦν δ’ ἐγώ· οὐκ ἀποκρίνεσθαι χρῆν μᾶλλον ἢ τοιαῦτα ἐρωτᾶν;","st":"343a"},{"sp":"N","t":"ὅτι τοί σε, ἔφη, κορυζῶντα περιορᾷ καὶ οὐκ ἀπομύττει δεόμενον, ὅς γε αὐτῇ οὐδὲ πρόβατα οὐδὲ ποιμένα γιγνώσκεις.","st":"343a"},{"sp":"N","t":"ὅτι δὴ τί μάλιστα; ἦν δ’ ἐγώ.","st":"343a"},{"sp":"N","t":"ὅτι οἴει τοὺς ποιμένας ἢ τοὺς βουκόλους τὸ τῶν προβάτων ἢ τὸ τῶν βοῶν ἀγαθὸν σκοπεῖν καὶ παχύνειν αὐτοὺς καὶ θεραπεύειν πρὸς ἄλλο τι βλέποντας ἢ τὸ τῶν δεσποτῶν ἀγαθὸν καὶ τὸ αὑτῶν, καὶ δὴ καὶ τοὺς ἐν ταῖς πόλεσιν ἄρχοντας, οἳ ὡς ἀληθῶς ἄρχουσιν, ἄλλως πως ἡγῇ διανοεῖσθαι πρὸς τοὺς ἀρχομένους ἢ ὥσπερ ἄν τις πρὸς πρόβατα διατεθείη, καὶ ἄλλο τι σκοπεῖν αὐτοὺς διὰ νυκτὸς καὶ ἡμέρας ἢ τοῦτο,","st":"343b"},{"sp":"N","t":"ὅθεν αὐτοὶ ὠφελήσονται. καὶ οὕτω πόρρω εἶ περί τε τοῦ δικαίου καὶ δικαιοσύνης καὶ ἀδίκου τε καὶ ἀδικίας, ὥστε ἀγνοεῖς ὅτι ἡ μὲν δικαιοσύνη καὶ τὸ δίκαιον ἀλλότριον ἀγαθὸν τῷ ὄντι, τοῦ κρείττονός τε καὶ ἄρχοντος συμφέρον, οἰκεία δὲ τοῦ πειθομένου τε καὶ ὑπηρετοῦντος βλάβη, ἡ δὲ ἀδικία τοὐναντίον, καὶ ἄρχει τῶν ὡς ἀληθῶς εὐηθικῶν τε καὶ δικαίων, οἱ δ’ ἀρχόμενοι ποιοῦσιν τὸ ἐκείνου συμφέρον κρείττονος ὄντος, καὶ εὐδαίμονα ἐκεῖνον ποιοῦσιν ὑπηρετοῦντες","st":"343c"},{"sp":"N","t":"αὐτῷ, ἑαυτοὺς δὲ οὐδ’ ὁπωστιοῦν. σκοπεῖσθαι δέ, ὦ εὐηθέστατε Σώκρατες, οὑτωσὶ χρή, ὅτι δίκαιος ἀνὴρ ἀδίκου πανταχοῦ ἔλαττον ἔχει. πρῶτον μὲν ἐν τοῖς πρὸς ἀλλήλους συμβολαίοις, ὅπου ἂν ὁ τοιοῦτος τῷ τοιούτῳ κοινωνήσῃ, οὐδαμοῦ ἂν εὕροις ἐν τῇ διαλύσει τῆς κοινωνίας πλέον ἔχοντα τὸν δίκαιον τοῦ ἀδίκου ἀλλ’ ἔλαττον· ἔπειτα ἐν τοῖς πρὸς τὴν πόλιν, ὅταν τέ τινες εἰσφοραὶ ὦσιν, ὁ μὲν δίκαιος ἀπὸ τῶν ἴσων πλέον εἰσφέρει, ὁ δ’ ἔλαττον, ὅταν τε λήψεις,","st":"343d"},{"sp":"N","t":"ὁ μὲν οὐδέν, ὁ δὲ πολλὰ κερδαίνει. καὶ γὰρ ὅταν ἀρχήν τινα ἄρχῃ ἑκάτερος, τῷ μὲν δικαίῳ ὑπάρχει, καὶ εἰ μηδεμία ἄλλη ζημία, τά γε οἰκεῖα δι’ ἀμέλειαν μοχθηροτέρως ἔχειν, ἐκ δὲ τοῦ δημοσίου μηδὲν ὠφελεῖσθαι διὰ τὸ δίκαιον εἶναι, πρὸς δὲ τούτοις ἀπεχθέσθαι τοῖς τε οἰκείοις καὶ τοῖς γνωρίμοις, ὅταν μηδὲν ἐθέλῃ αὐτοῖς ὑπηρετεῖν παρὰ τὸ δίκαιον· τῷ δὲ ἀδίκῳ πάντα τούτων τἀναντία ὑπάρχει. λέγω γὰρ","st":"343e"},{"sp":"N","t":"ὅνπερ νυνδὴ ἔλεγον, τὸν μεγάλα δυνάμενον πλεονεκτεῖν· τοῦτον οὖν σκόπει, εἴπερ βούλει κρίνειν ὅσῳ μᾶλλον συμφέρει ἰδίᾳ αὑτῷ ἄδικον εἶναι ἢ τὸ δίκαιον. πάντων δὲ ῥᾷστα μαθήσῃ, ἐὰν ἐπὶ τὴν τελεωτάτην ἀδικίαν ἔλθῃς, ἣ τὸν μὲν ἀδικήσαντα εὐδαιμονέστατον ποιεῖ, τοὺς δὲ ἀδικηθέντας καὶ ἀδικῆσαι οὐκ ἂν ἐθέλοντας ἀθλιωτάτους. ἔστιν δὲ τοῦτο τυραννίς, ἣ οὐ κατὰ σμικρὸν τἀλλότρια καὶ λάθρᾳ καὶ βίᾳ ἀφαιρεῖται, καὶ ἱερὰ καὶ ὅσια καὶ ἴδια καὶ δημόσια, ἀλλὰ","st":"344a"},{"sp":"N","t":"συλλήβδην· ὧν ἐφ’ ἑκάστῳ μέρει ὅταν τις ἀδικήσας μὴ λάθῃ, ζημιοῦταί τε καὶ ὀνείδη ἔχει τὰ μέγιστα — καὶ γὰρ ἱερόσυλοι καὶ ἀνδραποδισταὶ καὶ τοιχωρύχοι καὶ ἀποστερηταὶ καὶ κλέπται οἱ κατὰ μέρη ἀδικοῦντες τῶν τοιούτων κακουργημάτων καλοῦνται — ἐπειδὰν δέ τις πρὸς τοῖς τῶν πολιτῶν χρήμασιν καὶ αὐτοὺς ἀνδραποδισάμενος δουλώσηται, ἀντὶ τούτων τῶν αἰσχρῶν ὀνομάτων εὐδαίμονες καὶ μακάριοι","st":"344b"},{"sp":"N","t":"κέκληνται, οὐ μόνον ὑπὸ τῶν πολιτῶν ἀλλὰ καὶ ὑπὸ τῶν ἄλλων ὅσοι ἂν πύθωνται αὐτὸν τὴν ὅλην ἀδικίαν ἠδικηκότα· οὐ γὰρ τὸ ποιεῖν τὰ ἄδικα ἀλλὰ τὸ πάσχειν φοβούμενοι ὀνειδίζουσιν οἱ ὀνειδίζοντες τὴν ἀδικίαν. οὕτως, ὦ Σώκρατες, καὶ ἰσχυρότερον καὶ ἐλευθεριώτερον καὶ δεσποτικώτερον ἀδικία δικαιοσύνης ἐστὶν ἱκανῶς γιγνομένη, καὶ ὅπερ ἐξ ἀρχῆς ἔλεγον, τὸ μὲν τοῦ κρείττονος συμφέρον τὸ δίκαιον τυγχάνει ὄν, τὸ δ’ ἄδικον ἑαυτῷ λυσιτελοῦν τε καὶ συμφέρον.","st":"344c"},{"sp":"N","t":"ταῦτα εἰπὼν ὁ Θρασύμαχος ἐν νῷ εἶχεν ἀπιέναι, ὥσπερ βαλανεὺς ἡμῶν καταντλήσας κατὰ τῶν ὤτων ἁθρόον καὶ πολὺν τὸν λόγον· οὐ μὴν εἴασάν γε αὐτὸν οἱ παρόντες, ἀλλ’ ἠνάγκασαν ὑπομεῖναί τε καὶ παρασχεῖν τῶν εἰρημένων λόγον. καὶ δὴ ἔγωγε καὶ αὐτὸς πάνυ ἐδεόμην τε καὶ εἶπον· ὦ δαιμόνιε Θρασύμαχε, οἷον ἐμβαλὼν λόγον ἐν νῷ ἔχεις ἀπιέναι πρὶν διδάξαι ἱκανῶς ἢ μαθεῖν εἴτε οὕτως εἴτε ἄλλως","st":"344d"},{"sp":"N","t":"ἔχει; ἢ σμικρὸν οἴει ἐπιχειρεῖν πρᾶγμα διορίζεσθαι ὅλου βίου διαγωγήν, ᾗ ἂν διαγόμενος ἕκαστος ἡμῶν λυσιτελεστάτην ζωὴν ζῴη;","st":"344e"},{"sp":"N","t":"ἐγὼ γὰρ οἶμαι, ἔφη ὁ Θρασύμαχος, τουτὶ ἄλλως ἔχειν;","st":"344e"},{"sp":"N","t":"ἔοικας, ἦν δ’ ἐγώ — ἤτοι ἡμῶν γε οὐδὲν κήδεσθαι, οὐδέ τι φροντίζειν εἴτε χεῖρον εἴτε βέλτιον βιωσόμεθα ἀγνοοῦντες ὃ σὺ φῂς εἰδέναι. ἀλλ’, ὠγαθέ, προθυμοῦ καὶ ἡμῖν ἐνδείξασθαι — οὔτοι","st":"344e"},{"sp":"N","t":"κακῶς σοι κείσεται ὅτι ἂν ἡμᾶς τοσούσδε ὄντας εὐεργετήσῃς — ἐγὼ γὰρ δή σοι λέγω τό γ’ ἐμόν, ὅτι οὐ πείθομαι οὐδ’ οἶμαι ἀδικίαν δικαιοσύνης κερδαλεώτερον εἶναι, οὐδ’ ἐὰν ἐᾷ τις αὐτὴν καὶ μὴ διακωλύῃ πράττειν ἃ βούλεται. ἀλλ’, ὠγαθέ, ἔστω μὲν ἄδικος, δυνάσθω δὲ ἀδικεῖν ἢ τῷ λανθάνειν ἢ τῷ διαμάχεσθαι, ὅμως ἐμέ γε οὐ πείθει ὡς ἔστι τῆς δικαιοσύνης κερδαλεώτερον. ταῦτ’ οὖν","st":"345a"},{"sp":"N","t":"καὶ ἕτερος ἴσως τις ἡμῶν πέπονθεν, οὐ μόνος ἐγώ· πεῖσον οὖν, ὦ μακάριε, ἱκανῶς ἡμᾶς ὅτι οὐκ ὀρθῶς βουλευόμεθα δικαιοσύνην ἀδικίας περὶ πλείονος ποιούμενοι.","st":"345b"},{"sp":"N","t":"καὶ πῶς, ἔφη, σὲ πείσω; εἰ γὰρ οἷς νυνδὴ ἔλεγον μὴ πέπεισαι, τί σοι ἔτι ποιήσω; ἢ εἰς τὴν ψυχὴν φέρων ἐνθῶ τὸν λόγον;","st":"345b"},{"sp":"N","t":"μὰ Δί’, ἦν δ’ ἐγώ, μὴ σύ γε· ἀλλὰ πρῶτον μέν, ἃ ἂν εἴπῃς, ἔμμενε τούτοις, ἢ ἐὰν μετατιθῇ, φανερῶς μετατίθεσο καὶ ἡμᾶς μὴ ἐξαπάτα. νῦν δὲ ὁρᾷς, ὦ Θρασύμαχε — ἔτι","st":"345b"},{"sp":"N","t":"γὰρ τὰ ἔμπροσθεν ἐπισκεψώμεθα — ὅτι τὸν ὡς ἀληθῶς ἰατρὸν τὸ πρῶτον ὁριζόμενος τὸν ὡς ἀληθῶς ποιμένα οὐκέτι ᾤου δεῖν ὕστερον ἀκριβῶς φυλάξαι, ἀλλὰ πιαίνειν οἴει αὐτὸν τὰ πρόβατα, καθ’ ὅσον ποιμήν ἐστιν, οὐ πρὸς τὸ τῶν προβάτων βέλτιστον βλέποντα ἀλλ’, ὥσπερ δαιτυμόνα τινὰ καὶ μέλλοντα ἑστιάσεσθαι, πρὸς τὴν εὐωχίαν, ἢ αὖ πρὸς τὸ","st":"345c"},{"sp":"N","t":"ἀποδόσθαι, ὥσπερ χρηματιστὴν ἀλλ’ οὐ ποιμένα. τῇ δὲ ποιμενικῇ οὐ δήπου ἄλλου του μέλει ἢ ἐφ’ ᾧ τέτακται, ὅπως τούτῳ τὸ βέλτιστον ἐκποριεῖ — ἐπεὶ τά γε αὑτῆς ὥστ’ εἶναι βελτίστη ἱκανῶς δήπου ἐκπεπόρισται, ἕως γ’ ἂν μηδὲν ἐνδέῃ τοῦ ποιμενικὴ εἶναι — οὕτω δὲ ᾤμην ἔγωγε νυνδὴ ἀναγκαῖον εἶναι ἡμῖν ὁμολογεῖν πᾶσαν ἀρχήν, καθ’ ὅσον ἀρχή, μηδενὶ ἄλλῳ τὸ βέλτιστον σκοπεῖσθαι ἢ ἐκείνῳ, τῷ","st":"345d"},{"sp":"N","t":"ἀρχομένῳ τε καὶ θεραπευομένῳ, ἔν τε πολιτικῇ καὶ ἰδιωτικῇ ἀρχῇ. σὺ δὲ τοὺς ἄρχοντας ἐν ταῖς πόλεσιν, τοὺς ὡς ἀληθῶς ἄρχοντας, ἑκόντας οἴει ἄρχειν;","st":"345e"},{"sp":"N","t":"μὰ Δί’ οὔκ, ἔφη, ἀλλ’ εὖ οἶδα. τί δέ, ἦν δ’ ἐγώ, ὦ Θρασύμαχε; τὰς ἄλλας ἀρχὰς οὐκ ἐννοεῖς ὅτι οὐδεὶς ἐθέλει ἄρχειν ἑκών, ἀλλὰ μισθὸν αἰτοῦσιν, ὡς οὐχὶ αὐτοῖσιν ὠφελίαν ἐσομένην ἐκ τοῦ ἄρχειν ἀλλὰ","st":"345e"},{"sp":"N","t":"τοῖς ἀρχομένοις; ἐπεὶ τοσόνδε εἰπέ· οὐχὶ ἑκάστην μέντοι φαμὲν ἑκάστοτε τῶν τεχνῶν τούτῳ ἑτέραν εἶναι, τῷ ἑτέραν τὴν δύναμιν ἔχειν; καί, ὦ μακάριε, μὴ παρὰ δόξαν ἀποκρίνου, ἵνα τι καὶ περαίνωμεν.","st":"346a"},{"sp":"N","t":"ἀλλὰ τούτῳ, ἔφη, ἑτέρα.","st":"346a"},{"sp":"N","t":"οὐκοῦν καὶ ὠφελίαν ἑκάστη τούτων ἰδίαν τινὰ ἡμῖν παρέχεται ἀλλ’ οὐ κοινήν, οἷον ἰατρικὴ μὲν ὑγίειαν, κυβερνητικὴ δὲ σωτηρίαν ἐν τῷ πλεῖν, καὶ αἱ ἄλλαι οὕτω;","st":"346a"},{"sp":"N","t":"πάνυ γε.","st":"346a"},{"sp":"N","t":"οὐκοῦν καὶ μισθωτικὴ μισθόν; αὕτη γὰρ αὐτῆς ἡ δύναμις· ἢ τὴν ἰατρικὴν σὺ καὶ τὴν κυβερνητικὴν τὴν αὐτὴν καλεῖς; ἢ ἐάνπερ βούλῃ ἀκριβῶς διορίζειν, ὥσπερ ὑπέθου, οὐδέν τι μᾶλλον, ἐάν τις κυβερνῶν ὑγιὴς γίγνηται διὰ τὸ συμφέρον αὐτῷ πλεῖν ἐν τῇ θαλάττῃ, ἕνεκα τούτου καλεῖς μᾶλλον αὐτὴν ἰατρικήν;","st":"346b"},{"sp":"N","t":"οὐ δῆτα, ἔφη.","st":"346b"},{"sp":"N","t":"οὐδέ γ’, οἶμαι, τὴν μισθωτικήν, ἐὰν ὑγιαίνῃ τις μισθαρνῶν.","st":"346b"},{"sp":"N","t":"οὐ δῆτα.","st":"346b"},{"sp":"N","t":"τί δέ; τὴν ἰατρικὴν μισθαρνητικήν, ἐὰν ἰώμενός τις μισθαρνῇ;","st":"346b"},{"sp":"N","t":"οὐκ ἔφη.","st":"346c"},{"sp":"N","t":"οὐκοῦν τήν γε ὠφελίαν ἑκάστης τῆς τέχνης ἰδίαν ὡμολογήσαμεν εἶναι;","st":"346c"},{"sp":"N","t":"ἔστω, ἔφη.","st":"346c"},{"sp":"N","t":"ἥντινα ἄρα ὠφελίαν κοινῇ ὠφελοῦνται πάντες οἱ δημιουργοί, δῆλον ὅτι κοινῇ τινι τῷ αὐτῷ προσχρώμενοι ἀπ’ ἐκείνου ὠφελοῦνται.","st":"346c"},{"sp":"N","t":"ἔοικεν, ἔφη.","st":"346c"},{"sp":"N","t":"φαμὲν δέ γε τὸ μισθὸν ἀρνυμένους ὠφελεῖσθαι τοὺς δημιουργοὺς ἀπὸ τοῦ προσχρῆσθαι τῇ μισθωτικῇ τέχνῃ γίγνεσθαι αὐτοῖς.","st":"346c"},{"sp":"N","t":"συνέφη μόγις.","st":"346c"},{"sp":"N","t":"οὐκ ἄρα ἀπὸ τῆς αὑτοῦ τέχνης ἑκάστῳ αὕτη ἡ ὠφελία ἐστίν, ἡ τοῦ μισθοῦ λῆψις, ἀλλ’, εἰ δεῖ ἀκριβῶς σκοπεῖσθαι, ἡ μὲν ἰατρικὴ ὑγίειαν ποιεῖ, ἡ δὲ μισθαρνητικὴ μισθόν, καὶ ἡ μὲν οἰκοδομικὴ οἰκίαν, ἡ δὲ μισθαρνητικὴ αὐτῇ ἑπομένη μισθόν, καὶ αἱ ἄλλαι πᾶσαι οὕτως τὸ αὑτῆς ἑκάστη ἔργον ἐργάζεται καὶ ὠφελεῖ ἐκεῖνο ἐφ’ ᾧ τέτακται. ἐὰν δὲ μὴ μισθὸς αὐτῇ προσγίγνηται, ἔσθ’ ὅτι ὠφελεῖται ὁ δημιουργὸς ἀπὸ τῆς τέχνης;","st":"346d"},{"sp":"N","t":"οὐ φαίνεται, ἔφη.","st":"346d"},{"sp":"N","t":"ἆρ’ οὖν οὐδ’ ὠφελεῖ τότε, ὅταν προῖκα ἐργάζηται;","st":"346e"},{"sp":"N","t":"οἶμαι ἔγωγε.","st":"346e"},{"sp":"N","t":"οὐκοῦν, ὦ Θρασύμαχε, τοῦτο ἤδη δῆλον, ὅτι οὐδεμία τέχνη οὐδὲ ἀρχὴ τὸ αὑτῇ ὠφέλιμον παρασκευάζει, ἀλλ’, ὅπερ πάλαι ἐλέγομεν, τὸ τῷ ἀρχομένῳ καὶ παρασκευάζει καὶ ἐπιτάττει, τὸ ἐκείνου συμφέρον ἥττονος ὄντος σκοποῦσα, ἀλλ’ οὐ τὸ τοῦ κρείττονος. διὰ δὴ ταῦτα ἔγωγε, ὦ φίλε Θρασύμαχε, καὶ ἄρτι ἔλεγον μηδένα ἐθέλειν ἑκόντα ἄρχειν καὶ τὰ ἀλλότρια κακὰ μεταχειρίζεσθαι ἀνορθοῦντα,","st":"346e"},{"sp":"N","t":"ἀλλὰ μισθὸν αἰτεῖν, ὅτι ὁ μέλλων καλῶς τῇ τέχνῃ πράξειν οὐδέποτε αὑτῷ τὸ βέλτιστον πράττει οὐδ’ ἐπιτάττει κατὰ τὴν τέχνην ἐπιτάττων, ἀλλὰ τῷ ἀρχομένῳ· ὧν δὴ ἕνεκα, ὡς ἔοικε, μισθὸν δεῖν ὑπάρχειν τοῖς μέλλουσιν ἐθελήσειν ἄρχειν, ἢ ἀργύριον ἢ τιμήν, ἢ ζημίαν ἐὰν μὴ ἄρχῃ.","st":"347a"},{"sp":"N","t":"Σωκράτης, Γλαύκων","st":"347a"},{"sp":"N","t":"πῶς τοῦτο λέγεις, ὦ Σώκρατες; ἔφη ὁ Γλαύκων· τοὺς μὲν γὰρ δύο μισθοὺς γιγνώσκω, τὴν δὲ ζημίαν ἥντινα λέγεις καὶ ὡς ἐν μισθοῦ μέρει εἴρηκας, οὐ συνῆκα.","st":"347a"},{"sp":"N","t":"τὸν τῶν βελτίστων ἄρα μισθόν, ἔφην, οὐ συνιεῖς, δι’ ὃν","st":"347a"},{"sp":"N","t":"ἄρχουσιν οἱ ἐπιεικέστατοι, ὅταν ἐθέλωσιν ἄρχειν. ἢ οὐκ οἶσθα ὅτι τὸ φιλότιμόν τε καὶ φιλάργυρον εἶναι ὄνειδος λέγεταί τε καὶ ἔστιν;","st":"347b"},{"sp":"N","t":"ἔγωγε, ἔφη.","st":"347b"},{"sp":"N","t":"διὰ ταῦτα τοίνυν, ἦν δ’ ἐγώ, οὔτε χρημάτων ἕνεκα ἐθέλουσιν ἄρχειν οἱ ἀγαθοὶ οὔτε τιμῆς· οὔτε γὰρ φανερῶς πραττόμενοι τῆς ἀρχῆς ἕνεκα μισθὸν μισθωτοὶ βούλονται κεκλῆσθαι, οὔτε λάθρᾳ αὐτοὶ ἐκ τῆς ἀρχῆς λαμβάνοντες κλέπται. οὐδ’ αὖ τιμῆς ἕνεκα· οὐ γάρ εἰσι φιλότιμοι. δεῖ δὴ","st":"347b"},{"sp":"N","t":"αὐτοῖς ἀνάγκην προσεῖναι καὶ ζημίαν, εἰ μέλλουσιν ἐθέλειν ἄρχειν — ὅθεν κινδυνεύει τὸ ἑκόντα ἐπὶ τὸ ἄρχειν ἰέναι ἀλλὰ μὴ ἀνάγκην περιμένειν αἰσχρὸν νενομίσθαι — τῆς δὲ ζημίας μεγίστη τὸ ὑπὸ πονηροτέρου ἄρχεσθαι, ἐὰν μὴ αὐτὸς ἐθέλῃ ἄρχειν· ἣν δείσαντές μοι φαίνονται ἄρχειν, ὅταν ἄρχωσιν, οἱ ἐπιεικεῖς, καὶ τότε ἔρχονται ἐπὶ τὸ ἄρχειν οὐχ ὡς ἐπ’ ἀγαθόν τι ἰόντες οὐδ’ ὡς εὐπαθήσοντες ἐν αὐτῷ, ἀλλ’","st":"347c"},{"sp":"N","t":"ὡς ἐπ’ ἀναγκαῖον καὶ οὐκ ἔχοντες ἑαυτῶν βελτίοσιν ἐπιτρέψαι οὐδὲ ὁμοίοις. ἐπεὶ κινδυνεύει πόλις ἀνδρῶν ἀγαθῶν εἰ γένοιτο, περιμάχητον ἂν εἶναι τὸ μὴ ἄρχειν ὥσπερ νυνὶ τὸ ἄρχειν, καὶ ἐνταῦθ’ ἂν καταφανὲς γενέσθαι ὅτι τῷ ὄντι ἀληθινὸς ἄρχων οὐ πέφυκε τὸ αὑτῷ συμφέρον σκοπεῖσθαι ἀλλὰ τὸ τῷ ἀρχομένῳ· ὥστε πᾶς ἂν ὁ γιγνώσκων τὸ ὠφελεῖσθαι μᾶλλον ἕλοιτο ὑπ’ ἄλλου ἢ ἄλλον ὠφελῶν πράγματα ἔχειν. τοῦτο μὲν οὖν ἔγωγε οὐδαμῇ συγχωρῶ","st":"347d"},{"sp":"N","t":"Θρασυμάχῳ, ὡς τὸ δίκαιόν ἐστιν τὸ τοῦ κρείττονος συμφέρον. ἀλλὰ τοῦτο μὲν δὴ καὶ εἰς αὖθις σκεψόμεθα· πολὺ δέ μοι δοκεῖ μεῖζον εἶναι ὃ νῦν λέγει Θρασύμαχος, τὸν τοῦ ἀδίκου βίον φάσκων εἶναι κρείττω ἢ τὸν τοῦ δικαίου. σὺ οὖν ποτέρως, ἦν δ’ ἐγώ, ὦ Γλαύκων, αἱρῇ; καὶ πότερον ἀληθεστέρως δοκεῖ σοι λέγεσθαι;","st":"347e"},{"sp":"N","t":"τὸν τοῦ δικαίου ἔγωγε λυσιτελέστερον βίον εἶναι.","st":"347e"},{"sp":"N","t":"ἤκουσας, ἦν δ’ ἐγώ, ὅσα ἄρτι Θρασύμαχος ἀγαθὰ διῆλθεν τῷ τοῦ ἀδίκου;","st":"348a"},{"sp":"N","t":"ἤκουσα, ἔφη, ἀλλ’ οὐ πείθομαι.","st":"348a"},{"sp":"N","t":"βούλει οὖν αὐτὸν πείθωμεν, ἂν δυνώμεθά πῃ ἐξευρεῖν, ὡς οὐκ ἀληθῆ λέγει;","st":"348a"},{"sp":"N","t":"πῶς γὰρ οὐ βούλομαι; ἦ δ’ ὅς.","st":"348a"},{"sp":"N","t":"ἂν μὲν τοίνυν, ἦν δ’ ἐγώ, ἀντικατατείναντες λέγωμεν αὐτῷ λόγον παρὰ λόγον, ὅσα αὖ ἀγαθὰ ἔχει τὸ δίκαιον εἶναι, καὶ αὖθις οὗτος, καὶ ἄλλον ἡμεῖς, ἀριθμεῖν δεήσει","st":"348a"},{"sp":"N","t":"τἀγαθὰ καὶ μετρεῖν ὅσα ἑκάτεροι ἐν ἑκατέρῳ λέγομεν, καὶ ἤδη δικαστῶν τινων τῶν διακρινούντων δεησόμεθα· ἂν δὲ ὥσπερ ἄρτι ἀνομολογούμενοι πρὸς ἀλλήλους σκοπῶμεν, ἅμα αὐτοί τε δικασταὶ καὶ ῥήτορες ἐσόμεθα.","st":"348b"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη.","st":"348b"},{"sp":"N","t":"ὁποτέρως οὖν σοι, ἦν δ’ ἐγώ, ἀρέσκει.","st":"348b"},{"sp":"N","t":"οὕτως, ἔφη.","st":"348b"},{"sp":"N","t":"ἴθι δή, ἦν δ’ ἐγώ, ὦ Θρασύμαχε, ἀπόκριναι ἡμῖν ἐξ ἀρχῆς. τὴν τελέαν ἀδικίαν τελέας οὔσης δικαιοσύνης λυσιτελεστέραν φῂς εἶναι;","st":"348b"},{"sp":"N","t":"Σωκράτης, Γλαύκων, Θρασύμαχος","st":"348b"},{"sp":"N","t":"πάνυ μὲν οὖν καὶ φημί, ἔφη, καὶ δι’ ἅ, εἴρηκα.","st":"348c"},{"sp":"N","t":"φέρε δή, τὸ τοιόνδε περὶ αὐτῶν πῶς λέγεις; τὸ μέν που ἀρετὴν αὐτοῖν καλεῖς, τὸ δὲ κακίαν;","st":"348c"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"348c"},{"sp":"N","t":"οὐκοῦν τὴν μὲν δικαιοσύνην ἀρετήν, τὴν δὲ ἀδικίαν κακίαν;","st":"348c"},{"sp":"N","t":"εἰκός γ’, ἔφη, ὦ ἥδιστε, ἐπειδή γε καὶ λέγω ἀδικίαν μὲν λυσιτελεῖν, δικαιοσύνην δ’ οὔ.","st":"348c"},{"sp":"N","t":"ἀλλὰ τί μήν;","st":"348c"},{"sp":"N","t":"τοὐναντίον, ἦ δ’ ὅς.","st":"348c"},{"sp":"N","t":"ἦ τὴν δικαιοσύνην κακίαν;","st":"348c"},{"sp":"N","t":"οὔκ, ἀλλὰ πάνυ γενναίαν εὐήθειαν.","st":"348c"},{"sp":"N","t":"τὴν ἀδικίαν ἄρα κακοήθειαν καλεῖς;","st":"348d"},{"sp":"N","t":"οὔκ, ἀλλ’ εὐβουλίαν, ἔφη.","st":"348d"},{"sp":"N","t":"ἦ καὶ φρόνιμοί σοι, ὦ Θρασύμαχε, δοκοῦσιν εἶναι καὶ ἀγαθοὶ οἱ ἄδικοι;","st":"348d"},{"sp":"N","t":"οἵ γε τελέως, ἔφη, οἷοί τε ἀδικεῖν, πόλεις τε καὶ ἔθνη δυνάμενοι ἀνθρώπων ὑφ’ ἑαυτοὺς ποιεῖσθαι· σὺ δὲ οἴει με ἴσως τοὺς τὰ βαλλάντια ἀποτέμνοντας λέγειν. λυσιτελεῖ μὲν οὖν, ἦ δ’ ὅς, καὶ τὰ τοιαῦτα, ἐάνπερ λανθάνῃ· ἔστι δὲ οὐκ ἄξια λόγου, ἀλλ’ ἃ νυνδὴ ἔλεγον.","st":"348d"},{"sp":"N","t":"τοῦτο μέν, ἔφην, οὐκ ἀγνοῶ ὃ βούλει λέγειν, ἀλλὰ τόδε ἐθαύμασα, εἰ ἐν ἀρετῆς καὶ σοφίας τιθεῖς μέρει τὴν ἀδικίαν, τὴν δὲ δικαιοσύνην ἐν τοῖς ἐναντίοις.","st":"348e"},{"sp":"N","t":"ἀλλὰ πάνυ οὕτω τίθημι.","st":"348e"},{"sp":"N","t":"τοῦτο, ἦν δ’ ἐγώ, ἤδη στερεώτερον, ὦ ἑταῖρε, καὶ οὐκέτι ῥᾴδιον ἔχειν ὅτι τις εἴπῃ. εἰ γὰρ λυσιτελεῖν μὲν τὴν ἀδικίαν ἐτίθεσο, κακίαν μέντοι ἢ αἰσχρὸν αὐτὸ ὡμολόγεις εἶναι ὥσπερ ἄλλοι τινές, εἴχομεν ἄν τι λέγειν κατὰ τὰ νομιζόμενα λέγοντες· νῦν δὲ δῆλος εἶ ὅτι φήσεις αὐτὸ καὶ καλὸν καὶ ἰσχυρὸν εἶναι καὶ τἆλλα αὐτῷ πάντα προσθήσεις","st":"348e"},{"sp":"N","t":"ἃ ἡμεῖς τῷ δικαίῳ προσετίθεμεν, ἐπειδή γε καὶ ἐν ἀρετῇ αὐτὸ καὶ σοφίᾳ ἐτόλμησας θεῖναι.","st":"349a"},{"sp":"N","t":"ἀληθέστατα, ἔφη, μαντεύῃ.","st":"349a"},{"sp":"N","t":"ἀλλ’ οὐ μέντοι, ἦν δ’ ἐγώ, ἀποκνητέον γε τῷ λόγῳ ἐπεξελθεῖν σκοπούμενον, ἕως ἄν σε ὑπολαμβάνω λέγειν ἅπερ διανοῇ. ἐμοὶ γὰρ δοκεῖς σύ, ὦ Θρασύμαχε, ἀτεχνῶς νῦν οὐ σκώπτειν, ἀλλὰ τὰ δοκοῦντα περὶ τῆς ἀληθείας λέγειν.","st":"349a"},{"sp":"N","t":"τί δέ σοι, ἔφη, τοῦτο διαφέρει, εἴτε μοι δοκεῖ εἴτε μή, ἀλλ’ οὐ τὸν λόγον ἐλέγχεις;","st":"349a"},{"sp":"N","t":"οὐδέν, ἦν δ’ ἐγώ. ἀλλὰ τόδε μοι πειρῶ ἔτι πρὸς τούτοις ἀποκρίνασθαι· ὁ δίκαιος τοῦ δικαίου δοκεῖ τί σοι ἂν ἐθέλειν πλέον ἔχειν;","st":"349b"},{"sp":"N","t":"οὐδαμῶς, ἔφη· οὐ γὰρ ἂν ἦν ἀστεῖος, ὥσπερ νῦν, καὶ εὐήθης.","st":"349b"},{"sp":"N","t":"τί δέ; τῆς δικαίας πράξεως;","st":"349b"},{"sp":"N","t":"οὐδὲ τῆς δικαίας, ἔφη.","st":"349b"},{"sp":"N","t":"τοῦ δὲ ἀδίκου πότερον ἀξιοῖ ἂν πλεονεκτεῖν καὶ ἡγοῖτο δίκαιον εἶναι, ἢ οὐκ ἂν ἡγοῖτο;","st":"349b"},{"sp":"N","t":"ἡγοῖτ’ ἄν, ἦ δ’ ὅς, καὶ ἀξιοῖ, ἀλλ’ οὐκ ἂν δύναιτο.","st":"349b"},{"sp":"N","t":"ἀλλ’ οὐ τοῦτο, ἦν δ’ ἐγώ, ἐρωτῶ, ἀλλ’ εἰ τοῦ μὲν","st":"349b"},{"sp":"N","t":"δικαίου μὴ ἀξιοῖ πλέον ἔχειν μηδὲ βούλεται ὁ δίκαιος, τοῦ δὲ ἀδίκου;","st":"349c"},{"sp":"N","t":"ἀλλ’ οὕτως, ἔφη, ἔχει.","st":"349c"},{"sp":"N","t":"τί δὲ δὴ ὁ ἄδικος; ἆρα ἀξιοῖ τοῦ δικαίου πλεονεκτεῖν καὶ τῆς δικαίας πράξεως;","st":"349c"},{"sp":"N","t":"πῶς γὰρ οὔκ; ἔφη, ὅς γε πάντων πλέον ἔχειν ἀξιοῖ;","st":"349c"},{"sp":"N","t":"οὐκοῦν καὶ ἀδίκου γε ἀνθρώπου τε καὶ πράξεως ὁ ἄδικος πλεονεκτήσει καὶ ἁμιλλήσεται ὡς ἁπάντων πλεῖστον αὐτὸς λάβῃ;","st":"349c"},{"sp":"N","t":"ἔστι ταῦτα.","st":"349c"},{"sp":"N","t":"ὧδε δὴ λέγωμεν, ἔφην· ὁ δίκαιος τοῦ μὲν ὁμοίου οὐ πλεονεκτεῖ, τοῦ δὲ ἀνομοίου, ὁ δὲ ἄδικος τοῦ τε ὁμοίου καὶ","st":"349c"},{"sp":"N","t":"τοῦ ἀνομοίου;","st":"349d"},{"sp":"N","t":"ἄριστα, ἔφη, εἴρηκας.","st":"349d"},{"sp":"N","t":"ἔστιν δέ γε, ἔφην, φρόνιμός τε καὶ ἀγαθὸς ὁ ἄδικος, ὁ δὲ δίκαιος οὐδέτερα;","st":"349d"},{"sp":"N","t":"καὶ τοῦτ’, ἔφη, εὖ.","st":"349d"},{"sp":"N","t":"οὐκοῦν, ἦν δ’ ἐγώ, καὶ ἔοικε τῷ φρονίμῳ καὶ τῷ ἀγαθῷ ὁ ἄδικος, ὁ δὲ δίκαιος οὐκ ἔοικεν;","st":"349d"},{"sp":"N","t":"πῶς γὰρ οὐ μέλλει, ἔφη, ὁ τοιοῦτος ὢν καὶ ἐοικέναι τοῖς τοιούτοις, ὁ δὲ μὴ ἐοικέναι;","st":"349d"},{"sp":"N","t":"καλῶς. τοιοῦτος ἄρα ἐστὶν ἑκάτερος αὐτῶν οἷσπερ ἔοικεν;","st":"349d"},{"sp":"N","t":"ἀλλὰ τί μέλλει; ἔφη.","st":"349d"},{"sp":"N","t":"εἶεν, ὦ Θρασύμαχε· μουσικὸν δέ τινα λέγεις, ἕτερον δὲ","st":"349d"},{"sp":"N","t":"ἄμουσον;","st":"349e"},{"sp":"N","t":"ἔγωγε.","st":"349e"},{"sp":"N","t":"πότερον φρόνιμον καὶ πότερον ἄφρονα;","st":"349e"},{"sp":"N","t":"τὸν μὲν μουσικὸν δήπου φρόνιμον, τὸν δὲ ἄμουσον ἄφρονα.","st":"349e"},{"sp":"N","t":"οὐκοῦν καὶ ἅπερ φρόνιμον, ἀγαθόν, ἃ δὲ ἄφρονα, κακόν;","st":"349e"},{"sp":"N","t":"ναί.","st":"349e"},{"sp":"N","t":"τί δὲ ἰατρικόν; οὐχ οὕτως;","st":"349e"},{"sp":"N","t":"οὕτως.","st":"349e"},{"sp":"N","t":"δοκεῖ ἂν οὖν τίς σοι, ὦ ἄριστε, μουσικὸς ἀνὴρ ἁρμοττόμενος λύραν ἐθέλειν μουσικοῦ ἀνδρὸς ἐν τῇ ἐπιτάσει καὶ ἀνέσει τῶν χορδῶν πλεονεκτεῖν ἢ ἀξιοῦν πλέον ἔχειν;","st":"349e"},{"sp":"N","t":"οὐκ ἔμοιγε.","st":"349e"},{"sp":"N","t":"τί δέ; ἀμούσου;","st":"349e"},{"sp":"N","t":"ἀνάγκη, ἔφη.","st":"349e"},{"sp":"N","t":"τί δὲ ἰατρικός; ἐν τῇ ἐδωδῇ ἢ πόσει ἐθέλειν ἄν τι ἰατρικοῦ πλεονεκτεῖν ἢ ἀνδρὸς ἢ πράγματος;","st":"350a"},{"sp":"N","t":"οὐ δῆτα.","st":"350a"},{"sp":"N","t":"μὴ ἰατρικοῦ δέ;","st":"350a"},{"sp":"N","t":"ναί.","st":"350a"},{"sp":"N","t":"περὶ πάσης δὴ ὅρα ἐπιστήμης τε καὶ ἀνεπιστημοσύνης εἴ τίς σοι δοκεῖ ἐπιστήμων ὁστισοῦν πλείω ἂν ἐθέλειν αἱρεῖσθαι ἢ ὅσα ἄλλος ἐπιστήμων ἢ πράττειν ἢ λέγειν, καὶ οὐ ταὐτὰ τῷ ὁμοίῳ ἑαυτῷ εἰς τὴν αὐτὴν πρᾶξιν.","st":"350a"},{"sp":"N","t":"ἀλλ’ ἴσως, ἔφη, ἀνάγκη τοῦτό γε οὕτως ἔχειν.","st":"350a"},{"sp":"N","t":"τί δὲ ὁ ἀνεπιστήμων; οὐχὶ ὁμοίως μὲν ἐπιστήμονος","st":"350a"},{"sp":"N","t":"πλεονεκτήσειεν ἄν, ὁμοίως δὲ ἀνεπιστήμονος;","st":"350b"},{"sp":"N","t":"ἴσως.","st":"350b"},{"sp":"N","t":"ὁ δὲ ἐπιστήμων σοφός;","st":"350b"},{"sp":"N","t":"φημί.","st":"350b"},{"sp":"N","t":"ὁ δὲ σοφὸς ἀγαθός;","st":"350b"},{"sp":"N","t":"φημί.","st":"350b"},{"sp":"N","t":"ὁ ἄρα ἀγαθός τε καὶ σοφὸς τοῦ μὲν ὁμοίου οὐκ ἐθελήσει πλεονεκτεῖν, τοῦ δὲ ἀνομοίου τε καὶ ἐναντίου.","st":"350b"},{"sp":"N","t":"ἔοικεν, ἔφη.","st":"350b"},{"sp":"N","t":"ὁ δὲ κακός τε καὶ ἀμαθὴς τοῦ τε ὁμοίου καὶ τοῦ ἐναντίου.","st":"350b"},{"sp":"N","t":"φαίνεται.","st":"350b"},{"sp":"N","t":"οὐκοῦν, ὦ Θρασύμαχε, ἦν δ’ ἐγώ, ὁ ἄδικος ἡμῖν τοῦ ἀνομοίου τε καὶ ὁμοίου πλεονεκτεῖ; ἢ οὐχ οὕτως ἔλεγες;","st":"350b"},{"sp":"N","t":"ἔγωγε, ἔφη.","st":"350b"},{"sp":"N","t":"ὁ δέ γε δίκαιος τοῦ μὲν ὁμοίου οὐ πλεονεκτήσει, τοῦ δὲ ἀνομοίου;","st":"350c"},{"sp":"N","t":"ναί.","st":"350c"},{"sp":"N","t":"ἔοικεν ἄρα, ἦν δ’ ἐγώ, ὁ μὲν δίκαιος τῷ σοφῷ καὶ ἀγαθῷ, ὁ δὲ ἄδικος τῷ κακῷ καὶ ἀμαθεῖ.","st":"350c"},{"sp":"N","t":"κινδυνεύει.","st":"350c"},{"sp":"N","t":"ἀλλὰ μὴν ὡμολογοῦμεν, ᾧ γε ὅμοιος ἑκάτερος εἴη, τοιοῦτον καὶ ἑκάτερον εἶναι.","st":"350c"},{"sp":"N","t":"ὡμολογοῦμεν γάρ.","st":"350c"},{"sp":"N","t":"ὁ μὲν ἄρα δίκαιος ἡμῖν ἀναπέφανται ὢν ἀγαθός τε καὶ σοφός, ὁ δὲ ἄδικος ἀμαθής τε καὶ κακός.","st":"350c"},{"sp":"N","t":"ὁ δὴ Θρασύμαχος ὡμολόγησε μὲν πάντα ταῦτα, οὐχ","st":"350c"},{"sp":"N","t":"ὡς ἐγὼ νῦν ῥᾳδίως λέγω, ἀλλ’ ἑλκόμενος καὶ μόγις, μετὰ ἱδρῶτος θαυμαστοῦ ὅσου, ἅτε καὶ θέρους ὄντος — τότε καὶ εἶδον ἐγώ, πρότερον δὲ οὔπω, Θρασύμαχον ἐρυθριῶντα — ἐπειδὴ δὲ οὖν διωμολογησάμεθα τὴν δικαιοσύνην ἀρετὴν εἶναι καὶ σοφίαν, τὴν δὲ ἀδικίαν κακίαν τε καὶ ἀμαθίαν, εἶεν, ἦν δ’ ἐγώ, τοῦτο μὲν ἡμῖν οὕτω κείσθω, ἔφαμεν δὲ δὴ καὶ ἰσχυρὸν εἶναι τὴν ἀδικίαν. ἢ οὐ μέμνησαι, ὦ Θρασύμαχε;","st":"350d"},{"sp":"N","t":"μέμνημαι, ἔφη· ἀλλ’ ἔμοιγε οὐδὲ ἃ νῦν λέγεις ἀρέσκει, καὶ ἔχω περὶ αὐτῶν λέγειν. εἰ οὖν λέγοιμι, εὖ οἶδ’ ὅτι","st":"350d"},{"sp":"N","t":"δημηγορεῖν ἄν με φαίης. ἢ οὖν ἔα με εἰπεῖν ὅσα βούλομαι, ἤ, εἰ βούλει ἐρωτᾶν, ἐρώτα· ἐγὼ δέ σοι, ὥσπερ ταῖς γραυσὶν ταῖς τοὺς μύθους λεγούσαις, “εἶεν” ἐρῶ καὶ κατανεύσομαι καὶ ἀνανεύσομαι.","st":"350e"},{"sp":"N","t":"μηδαμῶς, ἦν δ’ ἐγώ, παρά γε τὴν σαυτοῦ δόξαν.","st":"350e"},{"sp":"N","t":"ὥστε σοί, ἔφη, ἀρέσκειν, ἐπειδήπερ οὐκ ἐᾷς λέγειν. καίτοι τί ἄλλο βούλει;","st":"350e"},{"sp":"N","t":"οὐδὲν μὰ Δία, ἦν δ’ ἐγώ, ἀλλ’ εἴπερ τοῦτο ποιήσεις, ποίει· ἐγὼ δὲ ἐρωτήσω.","st":"350e"},{"sp":"N","t":"ἐρώτα δή.","st":"350e"},{"sp":"N","t":"τοῦτο τοίνυν ἐρωτῶ, ὅπερ ἄρτι, ἵνα καὶ ἑξῆς διασκεψώμεθα","st":"350e"},{"sp":"N","t":"τὸν λόγον, ὁποῖόν τι τυγχάνει ὂν δικαιοσύνη πρὸς ἀδικίαν. ἐλέχθη γάρ που ὅτι καὶ δυνατώτερον καὶ ἰσχυρότερον εἴη ἀδικία δικαιοσύνης· νῦν δέ γ’, ἔφην, εἴπερ σοφία τε καὶ ἀρετή ἐστιν δικαιοσύνη, ῥᾳδίως οἶμαι φανήσεται καὶ ἰσχυρότερον ἀδικίας, ἐπειδήπερ ἐστὶν ἀμαθία ἡ ἀδικία — οὐδεὶς ἂν ἔτι τοῦτο ἀγνοήσειεν — ἀλλ’ οὔ τι οὕτως ἁπλῶς, ὦ Θρασύμαχε, ἔγωγε ἐπιθυμῶ, ἀλλὰ τῇδέ πῃ σκέψασθαι","st":"351a"},{"sp":"N","t":"πόλιν φαίης ἂν ἄδικον εἶναι καὶ ἄλλας πόλεις ἐπιχειρεῖν δουλοῦσθαι ἀδίκως καὶ καταδεδουλῶσθαι, πολλὰς δὲ καὶ ὑφ’ ἑαυτῇ ἔχειν δουλωσαμένην;","st":"351b"},{"sp":"N","t":"πῶς γὰρ οὔκ; ἔφη. καὶ τοῦτό γε ἡ ἀρίστη μάλιστα ποιήσει καὶ τελεώτατα οὖσα ἄδικος.","st":"351b"},{"sp":"N","t":"μανθάνω, ἔφην, ὅτι σὸς οὗτος ἦν ὁ λόγος. ἀλλὰ τόδε περὶ αὐτοῦ σκοπῶ· πότερον ἡ κρείττων γιγνομένη πόλις πόλεως ἄνευ δικαιοσύνης τὴν δύναμιν ταύτην ἕξει, ἢ ἀνάγκη αὐτῇ μετὰ δικαιοσύνης;","st":"351b"},{"sp":"N","t":"εἰ μέν, ἔφη, ὡς σὺ ἄρτι ἔλεγες ἔχει — ἡ δικαιοσύνη σοφία — μετὰ δικαιοσύνης· εἰ δ’ ὡς ἐγὼ ἔλεγον, μετὰ ἀδικίας.","st":"351c"},{"sp":"N","t":"πάνυ ἄγαμαι, ἦν δ’ ἐγώ, ὦ Θρασύμαχε, ὅτι οὐκ ἐπινεύεις μόνον καὶ ἀνανεύεις, ἀλλὰ καὶ ἀποκρίνῃ πάνυ καλῶς.","st":"351c"},{"sp":"N","t":"σοὶ γάρ, ἔφη, χαρίζομαι.","st":"351c"},{"sp":"N","t":"εὖ γε σὺ ποιῶν· ἀλλὰ δὴ καὶ τόδε μοι χάρισαι καὶ λέγε· δοκεῖς ἂν ἢ πόλιν ἢ στρατόπεδον ἢ λῃστὰς ἢ κλέπτας ἢ ἄλλο τι ἔθνος, ὅσα κοινῇ ἐπί τι ἔρχεται ἀδίκως, πρᾶξαι ἄν τι δύνασθαι, εἰ ἀδικοῖεν ἀλλήλους;","st":"351c"},{"sp":"N","t":"οὐ δῆτα, ἦ δ’ ὅς.","st":"351d"},{"sp":"N","t":"τί δ’ εἰ μὴ ἀδικοῖεν; οὐ μᾶλλον;","st":"351d"},{"sp":"N","t":"πάνυ γε.","st":"351d"},{"sp":"N","t":"στάσεις γάρ που, ὦ Θρασύμαχε, ἥ γε ἀδικία καὶ μίση καὶ μάχας ἐν ἀλλήλοις παρέχει, ἡ δὲ δικαιοσύνη ὁμόνοιαν καὶ φιλίαν· ἦ γάρ;","st":"351d"},{"sp":"N","t":"ἔστω, ἦ δ’ ὅς, ἵνα σοι μὴ διαφέρωμαι.","st":"351d"},{"sp":"N","t":"ἀλλ’ εὖ γε σὺ ποιῶν, ὦ ἄριστε. τόδε δέ μοι λέγε· ἆρα εἰ τοῦτο ἔργον ἀδικίας, μῖσος ἐμποιεῖν ὅπου ἂν ἐνῇ, οὐ καὶ ἐν ἐλευθέροις τε καὶ δούλοις ἐγγιγνομένη μισεῖν ποιήσει ἀλλήλους καὶ στασιάζειν καὶ ἀδυνάτους εἶναι κοινῇ μετ’","st":"351d"},{"sp":"N","t":"ἀλλήλων πράττειν;","st":"351e"},{"sp":"N","t":"πάνυ γε.","st":"351e"},{"sp":"N","t":"τί δὲ ἂν ἐν δυοῖν ἐγγένηται; οὐ διοίσονται καὶ μισήσουσιν καὶ ἐχθροὶ ἔσονται ἀλλήλοις τε καὶ τοῖς δικαίοις;","st":"351e"},{"sp":"N","t":"ἔσονται, ἔφη.","st":"351e"},{"sp":"N","t":"ἐὰν δὲ δή, ὦ θαυμάσιε, ἐν ἑνὶ ἐγγένηται ἀδικία, μῶν μὴ ἀπολεῖ τὴν αὑτῆς δύναμιν, ἢ οὐδὲν ἧττον ἕξει;","st":"351e"},{"sp":"N","t":"μηδὲν ἧττον ἐχέτω, ἔφη.","st":"351e"},{"sp":"N","t":"οὐκοῦν τοιάνδε τινὰ φαίνεται ἔχουσα τὴν δύναμιν, οἵαν, ᾧ ἂν ἐγγένηται, εἴτε πόλει τινὶ εἴτε γένει εἴτε στρατοπέδῳ εἴτε","st":"351e"},{"sp":"N","t":"ἄλλῳ ὁτῳοῦν, πρῶτον μὲν ἀδύνατον αὐτὸ ποιεῖν πράττειν μεθ’ αὑτοῦ διὰ τὸ στασιάζειν καὶ διαφέρεσθαι, ἔτι δ’ ἐχθρὸν εἶναι ἑαυτῷ τε καὶ τῷ ἐναντίῳ παντὶ καὶ τῷ δικαίῳ; οὐχ οὕτως;","st":"352a"},{"sp":"N","t":"πάνυ γε.","st":"352a"},{"sp":"N","t":"καὶ ἐν ἑνὶ δὴ οἶμαι ἐνοῦσα ταὐτὰ ταῦτα ποιήσει ἅπερ πέφυκεν ἐργάζεσθαι· πρῶτον μὲν ἀδύνατον αὐτὸν πράττειν ποιήσει στασιάζοντα καὶ οὐχ ὁμονοοῦντα αὐτὸν ἑαυτῷ, ἔπειτα ἐχθρὸν καὶ ἑαυτῷ καὶ τοῖς δικαίοις· ἦ γάρ;","st":"352a"},{"sp":"N","t":"ναί.","st":"352a"},{"sp":"N","t":"δίκαιοι δέ γ’ εἰσίν, ὦ φίλε, καὶ οἱ θεοί;","st":"352a"},{"sp":"N","t":"ἔστω, ἔφη.","st":"352a"},{"sp":"N","t":"καὶ θεοῖς ἄρα ἐχθρὸς ἔσται ὁ ἄδικος, ὦ Θρασύμαχε, ὁ δὲ δίκαιος φίλος.","st":"352b"},{"sp":"N","t":"εὐωχοῦ τοῦ λόγου, ἔφη, θαρρῶν· οὐ γὰρ ἔγωγέ σοι ἐναντιώσομαι, ἵνα μὴ τοῖσδε ἀπέχθωμαι.","st":"352b"},{"sp":"N","t":"ἴθι δή, ἦν δ’ ἐγώ, καὶ τὰ λοιπά μοι τῆς ἑστιάσεως ἀποπλήρωσον ἀποκρινόμενος ὥσπερ καὶ νῦν. ὅτι μὲν γὰρ καὶ σοφώτεροι καὶ ἀμείνους καὶ δυνατώτεροι πράττειν οἱ δίκαιοι φαίνονται, οἱ δὲ ἄδικοι οὐδὲ πράττειν μετ’ ἀλλήλων οἷοί","st":"352b"},{"sp":"N","t":"τε — ἀλλὰ δὴ καὶ οὕς φαμεν ἐρρωμένως πώποτέ τι μετ’ ἀλλήλων κοινῇ πρᾶξαι ἀδίκους ὄντας, τοῦτο οὐ παντάπασιν ἀληθὲς λέγομεν· οὐ γὰρ ἂν ἀπείχοντο ἀλλήλων κομιδῇ ὄντες ἄδικοι, ἀλλὰ δῆλον ὅτι ἐνῆν τις αὐτοῖς δικαιοσύνη, ἣ αὐτοὺς ἐποίει μήτοι καὶ ἀλλήλους γε καὶ ἐφ’ οὓς ᾖσαν ἅμα ἀδικεῖν, δι’ ἣν ἔπραξαν ἃ ἔπραξαν, ὥρμησαν δὲ ἐπὶ τὰ ἄδικα ἀδικίᾳ ἡμιμόχθηροι ὄντες, ἐπεὶ οἵ γε παμπόνηροι καὶ τελέως ἄδικοι τελέως εἰσὶ καὶ πράττειν ἀδύνατοι — ταῦτα","st":"352c"},{"sp":"N","t":"μὲν οὖν ὅτι οὕτως ἔχει μανθάνω, ἀλλ’ οὐχ ὡς σὺ τὸ πρῶτον ἐτίθεσο· εἰ δὲ καὶ ἄμεινον ζῶσιν οἱ δίκαιοι τῶν ἀδίκων καὶ εὐδαιμονέστεροί εἰσιν, ὅπερ τὸ ὕστερον προυθέμεθα σκέψασθαι, σκεπτέον. φαίνονται μὲν οὖν καὶ νῦν, ὥς γέ μοι δοκεῖ, ἐξ ὧν εἰρήκαμεν· ὅμως δ’ ἔτι βέλτιον σκεπτέον. οὐ γὰρ περὶ τοῦ ἐπιτυχόντος ὁ λόγος, ἀλλὰ περὶ τοῦ ὅντινα τρόπον χρὴ ζῆν.","st":"352d"},{"sp":"N","t":"σκόπει δή, ἔφη.","st":"352d"},{"sp":"N","t":"σκοπῶ, ἦν δ’ ἐγώ. καί μοι λέγε· δοκεῖ τί σοι εἶναι ἵππου ἔργον;","st":"352d"},{"sp":"N","t":"ἔμοιγε.","st":"352e"},{"sp":"N","t":"ἆρ’ οὖν τοῦτο ἂν θείης καὶ ἵππου καὶ ἄλλου ὁτουοῦν ἔργον, ὃ ἂν ἢ μόνῳ ἐκείνῳ ποιῇ τις ἢ ἄριστα;","st":"352e"},{"sp":"N","t":"οὐ μανθάνω, ἔφη.","st":"352e"},{"sp":"N","t":"ἀλλ’ ὧδε· ἔσθ’ ὅτῳ ἂν ἄλλῳ ἴδοις ἢ ὀφθαλμοῖς;","st":"352e"},{"sp":"N","t":"οὐ δῆτα.","st":"352e"},{"sp":"N","t":"τί δέ; ἀκούσαις ἄλλῳ ἢ ὠσίν;","st":"352e"},{"sp":"N","t":"οὐδαμῶς.","st":"352e"},{"sp":"N","t":"οὐκοῦν δικαίως [ἂν] ταῦτα τούτων φαμὲν ἔργα εἶναι;","st":"352e"},{"sp":"N","t":"πάνυ γε.","st":"352e"},{"sp":"N","t":"τί δέ; μαχαίρᾳ ἂν ἀμπέλου κλῆμα ἀποτέμοις καὶ σμίλῃ καὶ ἄλλοις πολλοῖς;","st":"353a"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"353a"},{"sp":"N","t":"ἀλλ’ οὐδενί γ’ ἂν οἶμαι οὕτω καλῶς ὡς δρεπάνῳ τῷ ἐπὶ τούτῳ ἐργασθέντι.","st":"353a"},{"sp":"N","t":"ἀληθῆ.","st":"353a"},{"sp":"N","t":"ἆρ’ οὖν οὐ τοῦτο τούτου ἔργον θήσομεν;","st":"353a"},{"sp":"N","t":"θήσομεν μὲν οὖν.","st":"353a"},{"sp":"N","t":"νῦν δὴ οἶμαι ἄμεινον ἂν μάθοις ὃ ἄρτι ἠρώτων, πυνθανόμενος εἰ οὐ τοῦτο ἑκάστου εἴη ἔργον ὃ ἂν ἢ μόνον τι ἢ κάλλιστα τῶν ἄλλων ἀπεργάζηται.","st":"353a"},{"sp":"N","t":"ἀλλά, ἔφη, μανθάνω τε καί μοι δοκεῖ τοῦτο ἑκάστου","st":"353a"},{"sp":"N","t":"πράγματος ἔργον εἶναι.","st":"353b"},{"sp":"N","t":"εἶεν, ἦν δ’ ἐγώ. οὐκοῦν καὶ ἀρετὴ δοκεῖ σοι εἶναι ἑκάστῳ ᾧπερ καὶ ἔργον τι προστέτακται; ἴωμεν δὲ ἐπὶ τὰ αὐτὰ πάλιν· ὀφθαλμῶν, φαμέν, ἔστι τι ἔργον;","st":"353b"},{"sp":"N","t":"ἔστιν.","st":"353b"},{"sp":"N","t":"ἆρ’ οὖν καὶ ἀρετὴ ὀφθαλμῶν ἔστιν;","st":"353b"},{"sp":"N","t":"καὶ ἀρετή.","st":"353b"},{"sp":"N","t":"τί δέ; ὤτων ἦν τι ἔργον;","st":"353b"},{"sp":"N","t":"ναί.","st":"353b"},{"sp":"N","t":"οὐκοῦν καὶ ἀρετή;","st":"353b"},{"sp":"N","t":"καὶ ἀρετή.","st":"353b"},{"sp":"N","t":"τί δὲ πάντων πέρι τῶν ἄλλων; οὐχ οὕτω;","st":"353b"},{"sp":"N","t":"οὕτω.","st":"353b"},{"sp":"N","t":"Ἔχε δή· ἆρ’ ἄν ποτε ὄμματα τὸ αὑτῶν ἔργον καλῶς","st":"353b"},{"sp":"N","t":"ἀπεργάσαιντο μὴ ἔχοντα τὴν αὑτῶν οἰκείαν ἀρετήν, ἀλλ’ ἀντὶ τῆς ἀρετῆς κακίαν;","st":"353c"},{"sp":"N","t":"καὶ πῶς ἄν; ἔφη· τυφλότητα γὰρ ἴσως λέγεις ἀντὶ τῆς ὄψεως.","st":"353c"},{"sp":"N","t":"ἥτις, ἦν δ’ ἐγώ, αὐτῶν ἡ ἀρετή· οὐ γάρ πω τοῦτο ἐρωτῶ, ἀλλ’ εἰ τῇ οἰκείᾳ μὲν ἀρετῇ τὸ αὑτῶν ἔργον εὖ ἐργάσεται τὰ ἐργαζόμενα, κακίᾳ δὲ κακῶς.","st":"353c"},{"sp":"N","t":"ἀληθές, ἔφη, τοῦτό γε λέγεις.","st":"353c"},{"sp":"N","t":"οὐκοῦν καὶ ὦτα στερόμενα τῆς αὑτῶν ἀρετῆς κακῶς τὸ αὑτῶν ἔργον ἀπεργάσεται;","st":"353c"},{"sp":"N","t":"πάνυ γε.","st":"353c"},{"sp":"N","t":"τίθεμεν οὖν καὶ τἆλλα πάντα εἰς τὸν αὐτὸν λόγον;","st":"353d"},{"sp":"N","t":"ἔμοιγε δοκεῖ.","st":"353d"},{"sp":"N","t":"ἴθι δή, μετὰ ταῦτα τόδε σκέψαι. ψυχῆς ἔστιν τι ἔργον ὃ ἄλλῳ τῶν ὄντων οὐδ’ ἂν ἑνὶ πράξαις, οἷον τὸ τοιόνδε· τὸ ἐπιμελεῖσθαι καὶ ἄρχειν καὶ βουλεύεσθαι καὶ τὰ τοιαῦτα πάντα, ἔσθ’ ὅτῳ ἄλλῳ ἢ ψυχῇ δικαίως ἂν αὐτὰ ἀποδοῖμεν καὶ φαῖμεν ἴδια ἐκείνης εἶναι;","st":"353d"},{"sp":"N","t":"οὐδενὶ ἄλλῳ.","st":"353d"},{"sp":"N","t":"τί δ’ αὖ τὸ ζῆν; οὐ ψυχῆς φήσομεν ἔργον εἶναι;","st":"353d"},{"sp":"N","t":"μάλιστά γ’, ἔφη.","st":"353d"},{"sp":"N","t":"οὐκοῦν καὶ ἀρετήν φαμέν τινα ψυχῆς εἶναι;","st":"353d"},{"sp":"N","t":"φαμέν.","st":"353d"},{"sp":"N","t":"ἆρ’ οὖν ποτε, ὦ Θρασύμαχε, ψυχὴ τὰ αὑτῆς ἔργα εὖ ἀπεργάσεται στερομένη τῆς οἰκείας ἀρετῆς, ἢ ἀδύνατον;","st":"353e"},{"sp":"N","t":"ἀδύνατον.","st":"353e"},{"sp":"N","t":"ἀνάγκη ἄρα κακῇ ψυχῇ κακῶς ἄρχειν καὶ ἐπιμελεῖσθαι, τῇ δὲ ἀγαθῇ πάντα ταῦτα εὖ πράττειν.","st":"353e"},{"sp":"N","t":"ἀνάγκη.","st":"353e"},{"sp":"N","t":"οὐκοῦν ἀρετήν γε συνεχωρήσαμεν ψυχῆς εἶναι δικαιοσύνην, κακίαν δὲ ἀδικίαν;","st":"353e"},{"sp":"N","t":"συνεχωρήσαμεν γάρ.","st":"353e"},{"sp":"N","t":"ἡ μὲν ἄρα δικαία ψυχὴ καὶ ὁ δίκαιος ἀνὴρ εὖ βιώσεται, κακῶς δὲ ὁ ἄδικος.","st":"353e"},{"sp":"N","t":"φαίνεται, ἔφη, κατὰ τὸν σὸν λόγον.","st":"353e"},{"sp":"N","t":"ἀλλὰ μὴν ὅ γε εὖ ζῶν μακάριός τε καὶ εὐδαίμων, ὁ δὲ μὴ τἀναντία.","st":"354a"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"354a"},{"sp":"N","t":"ὁ μὲν δίκαιος ἄρα εὐδαίμων, ὁ δ’ ἄδικος ἄθλιος.","st":"354a"},{"sp":"N","t":"ἔστω, ἔφη.","st":"354a"},{"sp":"N","t":"ἀλλὰ μὴν ἄθλιόν γε εἶναι οὐ λυσιτελεῖ, εὐδαίμονα δέ.","st":"354a"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"354a"},{"sp":"N","t":"οὐδέποτ’ ἄρα, ὦ μακάριε Θρασύμαχε, λυσιτελέστερον ἀδικία δικαιοσύνης.","st":"354a"},{"sp":"N","t":"ταῦτα δή σοι, ἔφη, ὦ Σώκρατες, εἱστιάσθω ἐν τοῖς Βενδιδίοις.","st":"354a"},{"sp":"N","t":"ὑπὸ σοῦ γε, ἦν δ’ ἐγώ, ὦ Θρασύμαχε, ἐπειδή μοι πρᾷος ἐγένου καὶ χαλεπαίνων ἐπαύσω. οὐ μέντοι καλῶς γε","st":"354a"},{"sp":"N","t":"εἱστίαμαι, δι’ ἐμαυτὸν ἀλλ’ οὐ διὰ σέ· ἀλλ’ ὥσπερ οἱ λίχνοι τοῦ ἀεὶ παραφερομένου ἀπογεύονται ἁρπάζοντες, πρὶν τοῦ προτέρου μετρίως ἀπολαῦσαι, καὶ ἐγώ μοι δοκῶ οὕτω, πρὶν ὃ τὸ πρῶτον ἐσκοποῦμεν εὑρεῖν, τὸ δίκαιον ὅτι ποτ’ ἐστίν, ἀφέμενος ἐκείνου ὁρμῆσαι ἐπὶ τὸ σκέψασθαι περὶ αὐτοῦ εἴτε κακία ἐστὶν καὶ ἀμαθία, εἴτε σοφία καὶ ἀρετή, καὶ ἐμπεσόντος αὖ ὕστερον λόγου, ὅτι λυσιτελέστερον ἡ ἀδικία τῆς δικαιοσύνης, οὐκ ἀπεσχόμην τὸ μὴ οὐκ ἐπὶ τοῦτο ἐλθεῖν ἀπ’ ἐκείνου, ὥστε μοι νυνὶ γέγονεν ἐκ τοῦ διαλόγου μηδὲν","st":"354b"},{"sp":"N","t":"εἰδέναι· ὁπότε γὰρ τὸ δίκαιον μὴ οἶδα ὅ ἐστιν, σχολῇ εἴσομαι εἴτε ἀρετή τις οὖσα τυγχάνει εἴτε καὶ οὔ, καὶ πότερον ὁ ἔχων αὐτὸ οὐκ εὐδαίμων ἐστὶν ἢ εὐδαίμων.","st":"354c"},{"sp":"N","t":"ΠΊΝΑΚΑς ΠΕΡΙΕΧΟΜΈΝΩΝ","st":"354c"},{"sp":"N","t":"Σωκράτης, Γλαύκων","st":"354c"},{"sp":"N","t":"Ἐγὼ μὲν οὖν ταῦτα εἰπὼν ᾤμην λόγου ἀπηλλάχθαι· τὸ δ’ ἦν ἄρα, ὡς ἔοικε, προοίμιον. ὁ γὰρ Γλαύκων ἀεί τε δὴ ἀνδρειότατος ὢν τυγχάνει πρὸς ἅπαντα, καὶ δὴ καὶ τότε τοῦ Θρασυμάχου τὴν ἀπόρρησιν οὐκ ἀπεδέξατο, ἀλλ’ ἔφη· Ὦ Σώκρατες, πότερον ἡμᾶς βούλει δοκεῖν πεπεικέναι ἢ ὡς","st":"357a"},{"sp":"N","t":"ἀληθῶς πεῖσαι ὅτι παντὶ τρόπῳ ἄμεινόν ἐστιν δίκαιον εἶναι ἢ ἄδικον;","st":"357b"},{"sp":"N","t":"Ὡς ἀληθῶς, εἶπον, ἔγωγ’ ἂν ἑλοίμην, εἰ ἐπ’ ἐμοὶ εἴη.","st":"357b"},{"sp":"N","t":"Οὐ τοίνυν, ἔφη, ποιεῖς ὃ βούλει. λέγε γάρ μοι· ἆρά σοι δοκεῖ τοιόνδε τι εἶναι ἀγαθόν, ὃ δεξαίμεθ’ ἂν ἔχειν οὐ τῶν ἀποβαινόντων ἐφιέμενοι, ἀλλ’ αὐτὸ αὑτοῦ ἕνεκα ἀσπαζόμενοι, οἷον τὸ χαίρειν καὶ αἱ ἡδοναὶ ὅσαι ἀβλαβεῖς καὶ μηδὲν εἰς τὸν ἔπειτα χρόνον διὰ ταύτας γίγνεται ἄλλο ἢ χαίρειν ἔχοντα;","st":"357b"},{"sp":"N","t":"Ἔμοιγε, ἦν δ’ ἐγώ, δοκεῖ τι εἶναι τοιοῦτον.","st":"357b"},{"sp":"N","t":"Τί δέ; ὃ αὐτό τε αὑτοῦ χάριν ἀγαπῶμεν καὶ τῶν ἀπ’ αὐτοῦ γιγνομένων, οἷον αὖ τὸ φρονεῖν καὶ τὸ ὁρᾶν καὶ τὸ ὑγιαίνειν; τὰ γὰρ τοιαῦτά που δι’ ἀμφότερα ἀσπαζόμεθα.","st":"357c"},{"sp":"N","t":"Ναί, εἶπον.","st":"357c"},{"sp":"N","t":"Τρίτον δὲ ὁρᾷς τι, ἔφη, εἶδος ἀγαθοῦ, ἐν ᾧ τὸ γυμνάζεσθαι καὶ τὸ κάμνοντα ἰατρεύεσθαι καὶ ἰάτρευσίς τε καὶ ὁ ἄλλος χρηματισμός; ταῦτα γὰρ ἐπίπονα φαῖμεν ἄν, ὠφελεῖν δὲ ἡμᾶς, καὶ αὐτὰ μὲν ἑαυτῶν ἕνεκα οὐκ ἂν δεξαίμεθα ἔχειν,","st":"357c"},{"sp":"N","t":"τῶν δὲ μισθῶν τε χάριν καὶ τῶν ἄλλων ὅσα γίγνεται ἀπ’ αὐτῶν.","st":"357d"},{"sp":"N","t":"Ἔστιν γὰρ οὖν, ἔφην, καὶ τοῦτο τρίτον. ἀλλὰ τί δή;","st":"357d"},{"sp":"N","t":"Ἐν ποίῳ, ἔφη, τούτων τὴν δικαιοσύνην τιθεῖς;","st":"357d"},{"sp":"N","t":"Ἐγὼ μὲν οἶμαι, ἦν δ’ ἐγώ, ἐν τῷ καλλίστῳ, ὃ καὶ δι’ αὑτὸ καὶ διὰ τὰ γιγνόμενα ἀπ’ αὐτοῦ ἀγαπητέον τῷ μέλλοντι μακαρίῳ ἔσεσθαι.","st":"358a"},{"sp":"N","t":"Οὐ τοίνυν δοκεῖ, ἔφη, τοῖς πολλοῖς, ἀλλὰ τοῦ ἐπιπόνου εἴδους, ὃ μισθῶν θ’ ἕνεκα καὶ εὐδοκιμήσεων διὰ δόξαν ἐπιτηδευτέον, αὐτὸ δὲ δι’ αὑτὸ φευκτέον ὡς ὂν χαλεπόν. Οἶδα, ἦν δ’ ἐγώ, ὅτι δοκεῖ οὕτω καὶ πάλαι ὑπὸ Θρασυμάχου ὡς τοιοῦτον ὂν ψέγεται, ἀδικία δ’ ἐπαινεῖται· ἀλλ’ ἐγώ τις, ὡς ἔοικε, δυσμαθής.","st":"358a"},{"sp":"N","t":"Ἴθι δή, ἔφη, ἄκουσον καὶ ἐμοῦ, ἐάν σοι ἔτι ταὐτὰ δοκῇ. Θρασύμαχος γάρ μοι φαίνεται πρῳαίτερον τοῦ δέοντος ὑπὸ σοῦ ὥσπερ ὄφις κηληθῆναι, ἐμοὶ δὲ οὔπω κατὰ νοῦν ἡ ἀπόδειξις γέγονεν περὶ ἑκατέρου· ἐπιθυμῶ γὰρ ἀκοῦσαι τί τ’ ἔστιν ἑκάτερον καὶ τίνα ἔχει δύναμιν αὐτὸ καθ’ αὑτὸ ἐνὸν ἐν τῇ ψυχῇ, τοὺς δὲ μισθοὺς καὶ τὰ γιγνόμενα ἀπ’ αὐτῶν ἐᾶσαι χαίρειν. οὑτωσὶ οὖν ποιήσω, ἐὰν καὶ σοὶ δοκῇ· ἐπανανεώσομαι","st":"358b"},{"sp":"N","t":"τὸν Θρασυμάχου λόγον, καὶ πρῶτον μὲν ἐρῶ δικαιοσύνην οἷον εἶναί φασιν καὶ ὅθεν γεγονέναι, δεύτερον δὲ ὅτι πάντες αὐτὸ οἱ ἐπιτηδεύοντες ἄκοντες ἐπιτηδεύουσιν ὡς ἀναγκαῖον ἀλλ’ οὐχ ὡς ἀγαθόν, τρίτον δὲ ὅτι εἰκότως αὐτὸ δρῶσι· πολὺ γὰρ ἀμείνων ἄρα ὁ τοῦ ἀδίκου ἢ ὁ τοῦ δικαίου βίος, ὡς λέγουσιν. ἐπεὶ ἔμοιγε, ὦ Σώκρατες, οὔ τι δοκεῖ οὕτως· ἀπορῶ μέντοι διατεθρυλημένος τὰ ὦτα ἀκούων Θρασυμάχου καὶ μυρίων ἄλλων, τὸν δὲ ὑπὲρ τῆς δικαιοσύνης λόγον, ὡς","st":"358c"},{"sp":"N","t":"ἄμεινον ἀδικίας, οὐδενός πω ἀκήκοα ὡς βούλομαι — βούλομαι δὲ αὐτὸ καθ’ αὑτὸ ἐγκωμιαζόμενον ἀκοῦσαι — μάλιστα δ’ οἶμαι ἂν σοῦ πυθέσθαι. διὸ κατατείνας ἐρῶ τὸν ἄδικον βίον ἐπαινῶν, εἰπὼν δὲ ἐνδείξομαί σοι ὃν τρόπον αὖ βούλομαι καὶ σοῦ ἀκούειν ἀδικίαν μὲν ψέγοντος, δικαιοσύνην δὲ ἐπαινοῦντος. ἀλλ’ ὅρα εἴ σοι βουλομένῳ ἃ λέγω.","st":"358d"},{"sp":"N","t":"Πάντων μάλιστα, ἦν δ’ ἐγώ· περὶ γὰρ τίνος ἂν μᾶλλον πολλάκις τις νοῦν ἔχων χαίροι λέγων καὶ ἀκούων;","st":"358d"},{"sp":"N","t":"Κάλλιστα, ἔφη, λέγεις· καὶ ὃ πρῶτον ἔφην ἐρεῖν, περὶ τούτου ἄκουε, τί ὄν τε καὶ ὅθεν γέγονε δικαιοσύνη.","st":"358e"},{"sp":"N","t":"<span class=\"speaker-label\">Γλαύκων:<\/span> Πεφυκέναι γὰρ δή φασιν τὸ μὲν ἀδικεῖν ἀγαθόν, τὸ δὲ ἀδικεῖσθαι κακόν, πλέονι δὲ κακῷ ὑπερβάλλειν τὸ ἀδικεῖσθαι ἢ ἀγαθῷ τὸ ἀδικεῖν, ὥστ’ ἐπειδὰν ἀλλήλους ἀδικῶσί τε καὶ ἀδικῶνται καὶ ἀμφοτέρων γεύωνται, τοῖς μὴ δυναμένοις τὸ","st":"358e"},{"sp":"N","t":"μὲν ἐκφεύγειν τὸ δὲ αἱρεῖν δοκεῖ λυσιτελεῖν συνθέσθαι ἀλλήλοις μήτ’ ἀδικεῖν μήτ’ ἀδικεῖσθαι· καὶ ἐντεῦθεν δὴ ἄρξασθαι νόμους τίθεσθαι καὶ συνθήκας αὑτῶν, καὶ ὀνομάσαι τὸ ὑπὸ τοῦ νόμου ἐπίταγμα νόμιμόν τε καὶ δίκαιον· καὶ εἶναι δὴ ταύτην γένεσίν τε καὶ οὐσίαν δικαιοσύνης, μεταξὺ οὖσαν τοῦ μὲν ἀρίστου ὄντος, ἐὰν ἀδικῶν μὴ διδῷ δίκην, τοῦ δὲ κακίστου, ἐὰν ἀδικούμενος τιμωρεῖσθαι ἀδύνατος ᾖ· τὸ δὲ δίκαιον ἐν μέσῳ ὂν τούτων ἀμφοτέρων ἀγαπᾶσθαι οὐχ ὡς","st":"359a"},{"sp":"N","t":"ἀγαθόν, ἀλλ’ ὡς ἀρρωστίᾳ τοῦ ἀδικεῖν τιμώμενον· ἐπεὶ τὸν δυνάμενον αὐτὸ ποιεῖν καὶ ὡς ἀληθῶς ἄνδρα οὐδ’ ἂν ἑνί ποτε συνθέσθαι τὸ μήτε ἀδικεῖν μήτε ἀδικεῖσθαι· μαίνεσθαι γὰρ ἄν. ἡ μὲν οὖν δὴ φύσις δικαιοσύνης, ὦ Σώκρατες, αὕτη τε καὶ τοιαύτη, καὶ ἐξ ὧν πέφυκε τοιαῦτα, ὡς ὁ λόγος.","st":"359b"},{"sp":"N","t":"Ὡς δὲ καὶ οἱ ἐπιτηδεύοντες ἀδυναμίᾳ τοῦ ἀδικεῖν ἄκοντες αὐτὸ ἐπιτηδεύουσι, μάλιστ’ ἂν αἰσθοίμεθα, εἰ τοιόνδε ποιήσαιμεν","st":"359b"},{"sp":"N","t":"τῇ διανοίᾳ· δόντες ἐξουσίαν ἑκατέρῳ ποιεῖν ὅτι ἂν βούληται, τῷ τε δικαίῳ καὶ τῷ ἀδίκῳ, εἶτ’ ἐπακολουθήσαιμεν θεώμενοι ποῖ ἡ ἐπιθυμία ἑκάτερον ἄξει. ἐπ’ αὐτοφώρῳ οὖν λάβοιμεν ἂν τὸν δίκαιον τῷ ἀδίκῳ εἰς ταὐτὸν ἰόντα διὰ τὴν πλεονεξίαν, ὃ πᾶσα φύσις διώκειν πέφυκεν ὡς ἀγαθόν, νόμῳ δὲ βίᾳ παράγεται ἐπὶ τὴν τοῦ ἴσου τιμήν. εἴη δ’ ἂν ἡ ἐξουσία ἣν λέγω τοιάδε μάλιστα, εἰ αὐτοῖς γένοιτο οἵαν","st":"359c"},{"sp":"N","t":"ποτέ φασιν δύναμιν τῷ [Γύγου] τοῦ Λυδοῦ προγόνῳ γενέσθαι. εἶναι μὲν γὰρ αὐτὸν ποιμένα θητεύοντα παρὰ τῷ τότε Λυδίας ἄρχοντι, ὄμβρου δὲ πολλοῦ γενομένου καὶ σεισμοῦ ῥαγῆναί τι τῆς γῆς καὶ γενέσθαι χάσμα κατὰ τὸν τόπον ᾗ ἔνεμεν. ἰδόντα δὲ καὶ θαυμάσαντα καταβῆναι καὶ ἰδεῖν ἄλλα τε δὴ ἃ μυθολογοῦσιν θαυμαστὰ καὶ ἵππον χαλκοῦν, κοῖλον, θυρίδας ἔχοντα, καθ’ ἃς ἐγκύψαντα ἰδεῖν ἐνόντα νεκρόν, ὡς φαίνεσθαι μείζω ἢ κατ’ ἄνθρωπον, τοῦτον δὲ ἄλλο μὲν οὐδέν, περὶ δὲ","st":"359d"},{"sp":"N","t":"τῇ χειρὶ χρυσοῦν δακτύλιον ὄν⟨τα⟩ περιελόμενον ἐκβῆναι. συλλόγου δὲ γενομένου τοῖς ποιμέσιν εἰωθότος, ἵν’ ἐξαγγέλλοιεν κατὰ μῆνα τῷ βασιλεῖ τὰ περὶ τὰ ποίμνια, ἀφικέσθαι καὶ ἐκεῖνον ἔχοντα τὸν δακτύλιον· καθήμενον οὖν μετὰ τῶν ἄλλων τυχεῖν τὴν σφενδόνην τοῦ δακτυλίου περιαγαγόντα πρὸς ἑαυτὸν εἰς τὸ εἴσω τῆς χειρός, τούτου δὲ γενομένου","st":"359e"},{"sp":"N","t":"ἀφανῆ αὐτὸν γενέσθαι τοῖς παρακαθημένοις, καὶ διαλέγεσθαι ὡς περὶ οἰχομένου. καὶ τὸν θαυμάζειν τε καὶ πάλιν ἐπιψηλαφῶντα τὸν δακτύλιον στρέψαι ἔξω τὴν σφενδόνην, καὶ στρέψαντα φανερὸν γενέσθαι. καὶ τοῦτο ἐννοήσαντα ἀποπειρᾶσθαι τοῦ δακτυλίου εἰ ταύτην ἔχοι τὴν δύναμιν, καὶ αὐτῷ οὕτω συμβαίνειν, στρέφοντι μὲν εἴσω τὴν σφενδόνην ἀδήλῳ γίγνεσθαι, ἔξω δὲ δήλῳ· αἰσθόμενον δὲ εὐθὺς διαπράξασθαι τῶν ἀγγέλων γενέσθαι τῶν παρὰ τὸν βασιλέα, ἐλθόντα","st":"360a"},{"sp":"N","t":"δὲ καὶ τὴν γυναῖκα αὐτοῦ μοιχεύσαντα, μετ’ ἐκείνης ἐπιθέμενον τῷ βασιλεῖ ἀποκτεῖναι καὶ τὴν ἀρχὴν οὕτω κατασχεῖν. εἰ οὖν δύο τοιούτω δακτυλίω γενοίσθην, καὶ τὸν μὲν ὁ δίκαιος περιθεῖτο, τὸν δὲ ὁ ἄδικος, οὐδεὶς ἂν γένοιτο, ὡς δόξειεν, οὕτως ἀδαμάντινος, ὃς ἂν μείνειεν ἐν τῇ δικαιοσύνῃ καὶ τολμήσειεν ἀπέχεσθαι τῶν ἀλλοτρίων καὶ μὴ ἅπτεσθαι, ἐξὸν αὐτῷ καὶ ἐκ τῆς ἀγορᾶς ἀδεῶς ὅτι βούλοιτο λαμβάνειν,","st":"360b"},{"sp":"N","t":"καὶ εἰσιόντι εἰς τὰς οἰκίας συγγίγνεσθαι ὅτῳ βούλοιτο, καὶ ἀποκτεινύναι καὶ ἐκ δεσμῶν λύειν οὕστινας βούλοιτο, καὶ τἆλλα πράττειν ἐν τοῖς ἀνθρώποις ἰσόθεον ὄντα. οὕτω δὲ δρῶν οὐδὲν ἂν διάφορον τοῦ ἑτέρου ποιοῖ, ἀλλ’ ἐπὶ ταὔτ’ ἂν ἴοιεν ἀμφότεροι. καίτοι μέγα τοῦτο τεκμήριον ἂν φαίη τις ὅτι οὐδεὶς ἑκὼν δίκαιος ἀλλ’ ἀναγκαζόμενος, ὡς οὐκ ἀγαθοῦ ἰδίᾳ ὄντος, ἐπεὶ ὅπου γ’ ἂν οἴηται ἕκαστος οἷός τε ἔσεσθαι ἀδικεῖν, ἀδικεῖν. λυσιτελεῖν γὰρ δὴ οἴεται πᾶς ἀνὴρ πολὺ","st":"360c"},{"sp":"N","t":"μᾶλλον ἰδίᾳ τὴν ἀδικίαν τῆς δικαιοσύνης, ἀληθῆ οἰόμενος, ὡς φήσει ὁ περὶ τοῦ τοιούτου λόγου λέγων· ἐπεὶ εἴ τις τοιαύτης ἐξουσίας ἐπιλαβόμενος μηδέν ποτε ἐθέλοι ἀδικῆσαι μηδὲ ἅψαιτο τῶν ἀλλοτρίων, ἀθλιώτατος μὲν ἂν δόξειεν εἶναι τοῖς αἰσθανομένοις καὶ ἀνοητότατος, ἐπαινοῖεν δ’ ἂν αὐτὸν ἀλλήλων ἐναντίον ἐξαπατῶντες ἀλλήλους διὰ τὸν τοῦ ἀδικεῖσθαι φόβον. ταῦτα μὲν οὖν δὴ οὕτω.","st":"360d"},{"sp":"N","t":"Τὴν δὲ κρίσιν αὐτὴν τοῦ βίου πέρι ὧν λέγομεν, ἐὰν διαστησώμεθα τόν τε δικαιότατον καὶ τὸν ἀδικώτατον, οἷοί τ’ ἐσόμεθα κρῖναι ὀρθῶς· εἰ δὲ μή, οὔ. τίς οὖν δὴ ἡ διάστασις; ἥδε· μηδὲν ἀφαιρῶμεν μήτε τοῦ ἀδίκου ἀπὸ τῆς ἀδικίας, μήτε τοῦ δικαίου ἀπὸ τῆς δικαιοσύνης, ἀλλὰ τέλεον ἑκάτερον εἰς τὸ ἑαυτοῦ ἐπιτήδευμα τιθῶμεν. πρῶτον μὲν οὖν ὁ ἄδικος ὥσπερ οἱ δεινοὶ δημιουργοὶ ποιείτω — οἷον κυβερνήτης ἄκρος ἢ ἰατρὸς τά τε ἀδύνατα ἐν τῇ τέχνῃ καὶ τὰ δυνατὰ διαισθάνεται,","st":"360e"},{"sp":"N","t":"καὶ τοῖς μὲν ἐπιχειρεῖ, τὰ δὲ ἐᾷ· ἔτι δὲ ἐὰν ἄρα πῃ σφαλῇ, ἱκανὸς ἐπανορθοῦσθαι — οὕτω καὶ ὁ ἄδικος ἐπιχειρῶν ὀρθῶς τοῖς ἀδικήμασιν λανθανέτω, εἰ μέλλει σφόδρα ἄδικος εἶναι. τὸν ἁλισκόμενον δὲ φαῦλον ἡγητέον· ἐσχάτη γὰρ ἀδικία δοκεῖν δίκαιον εἶναι μὴ ὄντα. δοτέον οὖν τῷ τελέως ἀδίκῳ τὴν τελεωτάτην ἀδικίαν, καὶ οὐκ ἀφαιρετέον ἀλλ’ ἐατέον τὰ μέγιστα ἀδικοῦντα τὴν μεγίστην δόξαν αὑτῷ","st":"361a"},{"sp":"N","t":"παρεσκευακέναι εἰς δικαιοσύνην, καὶ ἐὰν ἄρα σφάλληταί τι, ἐπανορθοῦσθαι δυνατῷ εἶναι, λέγειν τε ἱκανῷ ὄντι πρὸς τὸ πείθειν, ἐάν τι μηνύηται τῶν ἀδικημάτων, καὶ βιάσασθαι ὅσα ἂν βίας δέηται, διά τε ἀνδρείαν καὶ ῥώμην καὶ διὰ παρασκευὴν φίλων καὶ οὐσίας. τοῦτον δὲ τοιοῦτον θέντες τὸν δίκαιον αὖ παρ’ αὐτὸν ἱστῶμεν τῷ λόγῳ, ἄνδρα ἁπλοῦν καὶ γενναῖον, κατ’ Αἰσχύλον οὐ δοκεῖν ἀλλ’ εἶναι ἀγαθὸν ἐθέλοντα. ἀφαιρετέον δὴ τὸ δοκεῖν. εἰ γὰρ δόξει δίκαιος","st":"361b"},{"sp":"N","t":"εἶναι, ἔσονται αὐτῷ τιμαὶ καὶ δωρεαὶ δοκοῦντι τοιούτῳ εἶναι· ἄδηλον οὖν εἴτε τοῦ δικαίου εἴτε τῶν δωρεῶν τε καὶ τιμῶν ἕνεκα τοιοῦτος εἴη. γυμνωτέος δὴ πάντων πλὴν δικαιοσύνης καὶ ποιητέος ἐναντίως διακείμενος τῷ προτέρῳ· μηδὲν γὰρ ἀδικῶν δόξαν ἐχέτω τὴν μεγίστην ἀδικίας, ἵνα ᾖ βεβασανισμένος εἰς δικαιοσύνην τῷ μὴ τέγγεσθαι ὑπὸ κακοδοξίας καὶ τῶν ὑπ’ αὐτῆς γιγνομένων, ἀλλὰ ἴτω ἀμετάστατος μέχρι","st":"361c"},{"sp":"N","t":"θανάτου, δοκῶν μὲν εἶναι ἄδικος διὰ βίου, ὢν δὲ δίκαιος, ἵνα ἀμφότεροι εἰς τὸ ἔσχατον ἐληλυθότες, ὁ μὲν δικαιοσύνης, ὁ δὲ ἀδικίας, κρίνωνται ὁπότερος αὐτοῖν εὐδαιμονέστερος.","st":"361d"},{"sp":"N","t":"Σωκράτης, Γλαύκων","st":"361d"},{"sp":"N","t":"Βαβαῖ, ἦν δ’ ἐγώ, ὦ φίλε Γλαύκων, ὡς ἐρρωμένως ἑκάτερον ὥσπερ ἀνδριάντα εἰς τὴν κρίσιν ἐκκαθαίρεις τοῖν ἀνδροῖν.","st":"361d"},{"sp":"N","t":"Ὡς μάλιστ’, ἔφη, δύναμαι. ὄντοιν δὲ τοιούτοιν, οὐδὲν ἔτι, ὡς ἐγᾦμαι, χαλεπὸν ἐπεξελθεῖν τῷ λόγῳ οἷος ἑκάτερον","st":"361d"},{"sp":"N","t":"βίος ἐπιμένει. λεκτέον οὖν· καὶ δὴ κἂν ἀγροικοτέρως λέγηται, μὴ ἐμὲ οἴου λέγειν, ὦ Σώκρατες, ἀλλὰ τοὺς ἐπαινοῦντας πρὸ δικαιοσύνης ἀδικίαν. ἐροῦσι δὲ τάδε, ὅτι οὕτω διακείμενος ὁ δίκαιος μαστιγώσεται, στρεβλώσεται, δεδήσεται,","st":"361e"},{"sp":"N","t":"ἐκκαυθήσεται τὠφθαλμώ, τελευτῶν πάντα κακὰ παθὼν ἀνασχινδυλευθήσεται καὶ γνώσεται ὅτι οὐκ εἶναι δίκαιον ἀλλὰ δοκεῖν δεῖ ἐθέλειν. τὸ δὲ τοῦ Αἰσχύλου πολὺ ἦν ἄρα ὀρθότερον λέγειν κατὰ τοῦ ἀδίκου. τῷ ὄντι γὰρ φήσουσι τὸν ἄδικον, ἅτε ἐπιτηδεύοντα πρᾶγμα ἀληθείας ἐχόμενον καὶ οὐ πρὸς δόξαν ζῶντα, οὐ δοκεῖν ἄδικον ἀλλ’ εἶναι ἐθέλειν,","st":"362a"},{"sp":"N","t":"βαθεῖαν ἄλοκα διὰ φρενὸς καρπούμενον,","st":"362a"},{"sp":"N","t":"ἐξ ἧς τὰ κεδνὰ βλαστάνει βουλεύματα,","st":"362b"},{"sp":"N","t":"πρῶτον μὲν ἄρχειν ἐν τῇ πόλει δοκοῦντι δικαίῳ εἶναι, ἔπειτα γαμεῖν ὁπόθεν ἂν βούληται, ἐκδιδόναι εἰς οὓς ἂν βούληται, συμβάλλειν, κοινωνεῖν οἷς ἂν ἐθέλῃ, καὶ παρὰ ταῦτα πάντα ὠφελεῖσθαι κερδαίνοντα τῷ μὴ δυσχεραίνειν τὸ ἀδικεῖν· εἰς ἀγῶνας τοίνυν ἰόντα καὶ ἰδίᾳ καὶ δημοσίᾳ περιγίγνεσθαι καὶ πλεονεκτεῖν τῶν ἐχθρῶν, πλεονεκτοῦντα δὲ πλουτεῖν καὶ","st":"362b"},{"sp":"N","t":"τούς τε φίλους εὖ ποιεῖν καὶ τοὺς ἐχθροὺς βλάπτειν, καὶ θεοῖς θυσίας καὶ ἀναθήματα ἱκανῶς καὶ μεγαλοπρεπῶς θύειν τε καὶ ἀνατιθέναι, καὶ θεραπεύειν τοῦ δικαίου πολὺ ἄμεινον τοὺς θεοὺς καὶ τῶν ἀνθρώπων οὓς ἂν βούληται, ὥστε καὶ θεοφιλέστερον αὐτὸν εἶναι μᾶλλον προσήκειν ἐκ τῶν εἰκότων ἢ τὸν δίκαιον. οὕτω φασίν, ὦ Σώκρατες, παρὰ θεῶν καὶ παρ’ ἀνθρώπων τῷ ἀδίκῳ παρεσκευάσθαι τὸν βίον ἄμεινον ἢ τῷ δικαίῳ.","st":"362c"},{"sp":"N","t":"Σωκράτης, Αδείμαντος","st":"362c"},{"sp":"N","t":"Ταῦτ’ εἰπόντος τοῦ Γλαύκωνος ἐγὼ μὲν αὖ ἐν νῷ εἶχόν τι λέγειν πρὸς ταῦτα, ὁ δὲ ἀδελφὸς αὐτοῦ Ἀδείμαντος, Οὔ τί που οἴει, ἔφη, ὦ Σώκρατες, ἱκανῶς εἰρῆσθαι περὶ τοῦ λόγου;","st":"362d"},{"sp":"N","t":"Ἀλλὰ τί μήν; εἶπον.","st":"362d"},{"sp":"N","t":"Αὐτό, ἦ δ’ ὅς, οὐκ εἴρηται ὃ μάλιστα ἔδει ῥηθῆναι.","st":"362d"},{"sp":"N","t":"Οὐκοῦν, ἦν δ’ ἐγώ, τὸ λεγόμενον, ἀδελφὸς ἀνδρὶ παρείη· ὥστε καὶ σύ, εἴ τι ὅδε ἐλλείπει, ἐπάμυνε. καίτοι ἐμέ γε ἱκανὰ καὶ τὰ ὑπὸ τούτου ῥηθέντα καταπαλαῖσαι καὶ ἀδύνατον ποιῆσαι βοηθεῖν δικαιοσύνῃ.","st":"362d"},{"sp":"N","t":"<span class=\"speaker-label\">Αδείμαντος:<\/span> Καὶ ὅς, Οὐδέν, ἔφη, λέγεις· ἀλλ’ ἔτι καὶ τάδε ἄκουε. δεῖ γὰρ διελθεῖν ἡμᾶς καὶ τοὺς ἐναντίους λόγους ὧν ὅδε εἶπεν, οἳ δικαιοσύνην μὲν ἐπαινοῦσιν, ἀδικίαν δὲ ψέγουσιν, ἵν’ ᾖ σαφέστερον ὅ μοι δοκεῖ βούλεσθαι Γλαύκων. λέγουσι δέ που καὶ παρακελεύονται πατέρες τε ὑέσιν, καὶ πάντες οἱ","st":"362e"},{"sp":"N","t":"τινῶν κηδόμενοι, ὡς χρὴ δίκαιον εἶναι, οὐκ αὐτὸ δικαιοσύνην ἐπαινοῦντες ἀλλὰ τὰς ἀπ’ αὐτῆς εὐδοκιμήσεις, ἵνα δοκοῦντι δικαίῳ εἶναι γίγνηται ἀπὸ τῆς δόξης ἀρχαί τε καὶ γάμοι καὶ ὅσαπερ Γλαύκων διῆλθεν ἄρτι, ἀπὸ τοῦ εὐδοκιμεῖν ὄντα τῷ δικαίῳ. ἐπὶ πλέον δὲ οὗτοι τὰ τῶν δοξῶν λέγουσιν. τὰς γὰρ παρὰ θεῶν εὐδοκιμήσεις ἐμβάλλοντες ἄφθονα ἔχουσι λέγειν ἀγαθά, τοῖς ὁσίοις ἅ φασι θεοὺς διδόναι· ὥσπερ ὁ γενναῖος Ἡσίοδός τε καὶ Ὅμηρός φασιν, ὁ μὲν τὰς δρῦς","st":"363a"},{"sp":"N","t":"τοῖς δικαίοις τοὺς θεοὺς ποιεῖν ἄκρας μέν τε φέρειν βαλάνους, μέσσας δὲ μελίσσας· εἰροπόκοι δ’ ὄιες, φησίν, μαλλοῖς καταβεβρίθασι, καὶ ἄλλα δὴ πολλὰ ἀγαθὰ τούτων ἐχόμενα. παραπλήσια δὲ καὶ ὁ ἕτερος· ὥς τέ τευ γάρ φησιν","st":"363b"},{"sp":"N","t":"ἢ βασιλῆος ἀμύμονος ὅς τε θεουδὴς","st":"363b"},{"sp":"N","t":"εὐδικίας ἀνέχῃσι, φέρῃσι δὲ γαῖα μέλαινα","st":"363b"},{"sp":"N","t":"πυροὺς καὶ κριθάς, βρίθῃσι δὲ δένδρεα καρπῷ,","st":"363c"},{"sp":"N","t":"τίκτῃ δ’ ἔμπεδα μῆλα, θάλασσα δὲ παρέχῃ ἰχθῦς.","st":"363c"},{"sp":"N","t":"Μουσαῖος δὲ τούτων νεανικώτερα τἀγαθὰ καὶ ὁ ὑὸς αὐτοῦ παρὰ θεῶν διδόασιν τοῖς δικαίοις· εἰς Ἅιδου γὰρ ἀγαγόντες τῷ λόγῳ καὶ κατακλίναντες καὶ συμπόσιον τῶν ὁσίων κατασκευάσαντες ἐστεφανωμένους ποιοῦσιν τὸν ἅπαντα χρόνον","st":"363c"},{"sp":"N","t":"ἤδη διάγειν μεθύοντας, ἡγησάμενοι κάλλιστον ἀρετῆς μισθὸν μέθην αἰώνιον. οἱ δ’ ἔτι τούτων μακροτέρους ἀποτείνουσιν μισθοὺς παρὰ θεῶν· παῖδας γὰρ παίδων φασὶ καὶ γένος κατόπισθεν λείπεσθαι τοῦ ὁσίου καὶ εὐόρκου. ταῦτα δὴ καὶ ἄλλα τοιαῦτα ἐγκωμιάζουσιν δικαιοσύνην· τοὺς δὲ ἀνοσίους αὖ καὶ ἀδίκους εἰς πηλόν τινα κατορύττουσιν ἐν Ἅιδου καὶ κοσκίνῳ ὕδωρ ἀναγκάζουσι φέρειν, ἔτι τε ζῶντας","st":"363d"},{"sp":"N","t":"εἰς κακὰς δόξας ἄγοντες, ἅπερ Γλαύκων περὶ τῶν δικαίων δοξαζομένων δὲ ἀδίκων διῆλθε τιμωρήματα, ταῦτα περὶ τῶν ἀδίκων λέγουσιν, ἄλλα δὲ οὐκ ἔχουσιν. ὁ μὲν οὖν ἔπαινος καὶ ὁ ψόγος οὗτος ἑκατέρων.","st":"363e"},{"sp":"N","t":"Πρὸς δὲ τούτοις σκέψαι, ὦ Σώκρατες, ἄλλο αὖ εἶδος λόγων περὶ δικαιοσύνης τε καὶ ἀδικίας ἰδίᾳ τε λεγόμενον","st":"363e"},{"sp":"N","t":"καὶ ὑπὸ ποιητῶν. πάντες γὰρ ἐξ ἑνὸς στόματος ὑμνοῦσιν ὡς καλὸν μὲν ἡ σωφροσύνη τε καὶ δικαιοσύνη, χαλεπὸν μέντοι καὶ ἐπίπονον, ἀκολασία δὲ καὶ ἀδικία ἡδὺ μὲν καὶ εὐπετὲς κτήσασθαι, δόξῃ δὲ μόνον καὶ νόμῳ αἰσχρόν· λυσιτελέστερα δὲ τῶν δικαίων τὰ ἄδικα ὡς ἐπὶ τὸ πλῆθος λέγουσι, καὶ πονηροὺς πλουσίους καὶ ἄλλας δυνάμεις ἔχοντας εὐδαιμονίζειν καὶ τιμᾶν εὐχερῶς ἐθέλουσιν δημοσίᾳ τε καὶ ἰδίᾳ, τοὺς δὲ ἀτιμάζειν καὶ ὑπερορᾶν, οἳ ἄν πῃ ἀσθενεῖς τε","st":"364a"},{"sp":"N","t":"καὶ πένητες ὦσιν, ὁμολογοῦντες αὐτοὺς ἀμείνους εἶναι τῶν ἑτέρων. τούτων δὲ πάντων οἱ περὶ θεῶν τε λόγοι καὶ ἀρετῆς θαυμασιώτατοι λέγονται, ὡς ἄρα καὶ θεοὶ πολλοῖς μὲν ἀγαθοῖς δυστυχίας τε καὶ βίον κακὸν ἔνειμαν, τοῖς δ’ ἐναντίοις ἐναντίαν μοῖραν. ἀγύρται δὲ καὶ μάντεις ἐπὶ πλουσίων θύρας ἰόντες πείθουσιν ὡς ἔστι παρὰ σφίσι δύναμις ἐκ θεῶν ποριζομένη θυσίαις τε καὶ ἐπῳδαῖς, εἴτε τι","st":"364b"},{"sp":"N","t":"ἀδίκημά του γέγονεν αὐτοῦ ἢ προγόνων, ἀκεῖσθαι μεθ’ ἡδονῶν τε καὶ ἑορτῶν, ἐάν τέ τινα ἐχθρὸν πημῆναι ἐθέλῃ, μετὰ σμικρῶν δαπανῶν ὁμοίως δίκαιον ἀδίκῳ βλάψει ἐπαγωγαῖς τισιν καὶ καταδέσμοις, τοὺς θεούς, ὥς φασιν, πείθοντές σφισιν ὑπηρετεῖν. τούτοις δὲ πᾶσιν τοῖς λόγοις μάρτυρας ποιητὰς ἐπάγονται οἱ μὲν κακίας πέρι, εὐπετείας διδόντες, ὡς","st":"364c"},{"sp":"N","t":"τὴν μὲν κακότητα καὶ ἰλαδὸν ἔστιν ἑλέσθαι","st":"364c"},{"sp":"N","t":"ῥηϊδίως· λείη μὲν ὁδός, μάλα δ’ ἐγγύθι ναίει","st":"364d"},{"sp":"N","t":"τῆς δ’ ἀρετῆς ἱδρῶτα θεοὶ προπάροιθεν ἔθηκαν","st":"364d"},{"sp":"N","t":"καί τινα ὁδὸν μακράν τε καὶ τραχεῖαν καὶ ἀνάντη· οἱ δὲ τῆς τῶν θεῶν ὑπ’ ἀνθρώπων παραγωγῆς τὸν Ὅμηρον μαρτύρονται, ὅτι καὶ ἐκεῖνος εἶπεν —","st":"364d"},{"sp":"N","t":"λιστοὶ δέ τε καὶ θεοὶ αὐτοί,","st":"364d"},{"sp":"N","t":"καὶ τοὺς μὲν θυσίαισι καὶ εὐχωλαῖς ἀγαναῖσιν","st":"364d"},{"sp":"N","t":"λοιβῇ τε κνίσῃ τε παρατρωπῶσ’ ἄνθρωποι","st":"364e"},{"sp":"N","t":"λισσόμενοι, ὅτε κέν τις ὑπερβήῃ καὶ ἁμάρτῃ.","st":"364e"},{"sp":"N","t":"βίβλων δὲ ὅμαδον παρέχονται Μουσαίου καὶ Ὀρφέως, Σελήνης τε καὶ Μουσῶν ἐκγόνων, ὥς φασι, καθ’ ἃς θυηπολοῦσιν, πείθοντες οὐ μόνον ἰδιώτας ἀλλὰ καὶ πόλεις, ὡς ἄρα λύσεις τε καὶ καθαρμοὶ ἀδικημάτων διὰ θυσιῶν καὶ","st":"364e"},{"sp":"N","t":"παιδιᾶς ἡδονῶν εἰσι μὲν ἔτι ζῶσιν, εἰσὶ δὲ καὶ τελευτήσασιν, ἃς δὴ τελετὰς καλοῦσιν, αἳ τῶν ἐκεῖ κακῶν ἀπολύουσιν ἡμᾶς, μὴ θύσαντας δὲ δεινὰ περιμένει.","st":"365a"},{"sp":"N","t":"Ταῦτα πάντα, ἔφη, ὦ φίλε Σώκρατες, τοιαῦτα καὶ τοσαῦτα λεγόμενα ἀρετῆς πέρι καὶ κακίας, ὡς ἄνθρωποι καὶ θεοὶ περὶ αὐτὰ ἔχουσι τιμῆς, τί οἰόμεθα ἀκουούσας νέων ψυχὰς ποιεῖν, ὅσοι εὐφυεῖς καὶ ἱκανοὶ ἐπὶ πάντα τὰ λεγόμενα ὥσπερ ἐπιπτόμενοι συλλογίσασθαι ἐξ αὐτῶν ποῖός τις ἂν","st":"365a"},{"sp":"N","t":"ὢν καὶ πῇ πορευθεὶς τὸν βίον ὡς ἄριστα διέλθοι; λέγοι γὰρ ἂν ἐκ τῶν εἰκότων πρὸς αὑτὸν κατὰ Πίνδαρον ἐκεῖνο τὸ Πότερον δίκᾳ τεῖχος ὕψιον ἢ σκολιαῖς ἀπάταις ἀναβὰς καὶ ἐμαυτὸν οὕτω περιφράξας διαβιῶ; τὰ μὲν γὰρ λεγόμενα δικαίῳ μὲν ὄντι μοι, ἐὰν μὴ καὶ δοκῶ ὄφελος οὐδέν φασιν εἶναι, πόνους δὲ καὶ ζημίας φανεράς· ἀδίκῳ δὲ δόξαν δικαιοσύνης παρεσκευασμένῳ θεσπέσιος βίος λέγεται.","st":"365b"},{"sp":"N","t":"οὐκοῦν, ἐπειδὴ τὸ δοκεῖν, ὡς δηλοῦσί μοι οἱ σοφοί, καὶ τὰν ἀλάθειαν βιᾶται καὶ κύριον εὐδαιμονίας, ἐπὶ τοῦτο δὴ τρεπτέον ὅλως· πρόθυρα μὲν καὶ σχῆμα κύκλῳ περὶ ἐμαυτὸν σκιαγραφίαν ἀρετῆς περιγραπτέον, τὴν δὲ τοῦ σοφωτάτου Ἀρχιλόχου ἀλώπεκα ἑλκτέον ἐξόπισθεν κερδαλέαν καὶ ποικίλην. “Ἀλλὰ γάρ, φησί τις, οὐ ῥᾴδιον ἀεὶ λανθάνειν κακὸν ὄντα.” Οὐδὲ γὰρ ἄλλο οὐδὲν εὐπετές,","st":"365c"},{"sp":"N","t":"φήσομεν, τῶν μεγάλων· ἀλλ’ ὅμως, εἰ μέλλομεν εὐδαιμονήσειν, ταύτῃ ἰτέον, ὡς τὰ ἴχνη τῶν λόγων φέρει. ἐπὶ γὰρ τὸ λανθάνειν συνωμοσίας τε καὶ ἑταιρίας συνάξομεν, εἰσίν τε πειθοῦς διδάσκαλοι σοφίαν δημηγορικήν τε καὶ δικανικὴν διδόντες, ἐξ ὧν τὰ μὲν πείσομεν, τὰ δὲ βιασόμεθα, ὡς πλεονεκτοῦντες δίκην μὴ διδόναι. “Ἀλλὰ δὴ θεοὺς οὔτε λανθάνειν οὔτε βιάσασθαι δυνατόν.” Οὐκοῦν, εἰ μὲν μὴ εἰσὶν ἢ μηδὲν αὐτοῖς τῶν ἀνθρωπίνων μέλει, τί καὶ ἡμῖν","st":"365d"},{"sp":"N","t":"μελητέον τοῦ λανθάνειν; εἰ δὲ εἰσί τε καὶ ἐπιμελοῦνται, οὐκ ἄλλοθέν τοι αὐτοὺς ἴσμεν ἢ ἀκηκόαμεν ἢ ἔκ τε τῶν νόμων καὶ τῶν γενεαλογησάντων ποιητῶν, οἱ δὲ αὐτοὶ οὗτοι λέγουσιν ὡς εἰσὶν οἷοι θυσίαις τε καὶ εὐχωλαῖς ἀγανῇσιν καὶ ἀναθήμασιν παράγεσθαι ἀναπειθόμενοι, οἷς ἢ ἀμφότερα ἢ οὐδέτερα πειστέον. εἰ δ’ οὖν πειστέον, ἀδικητέον καὶ θυτέον","st":"365e"},{"sp":"N","t":"ἀπὸ τῶν ἀδικημάτων. δίκαιοι μὲν γὰρ ὄντες ἀζήμιοι μόνον ὑπὸ θεῶν ἐσόμεθα, τὰ δ’ ἐξ ἀδικίας κέρδη ἀπωσόμεθα· ἄδικοι δὲ κερδανοῦμέν τε καὶ λισσόμενοι ὑπερβαίνοντες καὶ ἁμαρτάνοντες, πείθοντες αὐτοὺς ἀζήμιοι ἀπαλλάξομεν. “Ἀλλὰ γὰρ ἐν Ἅιδου δίκην δώσομεν ὧν ἂν ἐνθάδε ἀδικήσωμεν, ἢ αὐτοὶ ἢ παῖδες παίδων.” Ἀλλ’, ὦ φίλε, φήσει λογιζόμενος, αἱ τελεταὶ αὖ μέγα δύνανται καὶ οἱ λύσιοι θεοί, ὡς αἱ","st":"366a"},{"sp":"N","t":"μέγισται πόλεις λέγουσι καὶ οἱ θεῶν παῖδες ποιηταὶ καὶ προφῆται τῶν θεῶν γενόμενοι, οἳ ταῦτα οὕτως ἔχειν μηνύουσιν.","st":"366b"},{"sp":"N","t":"Κατὰ τίνα οὖν ἔτι λόγον δικαιοσύνην ἂν πρὸ μεγίστης ἀδικίας αἱροίμεθ’ ἄν, ἣν ἐὰν μετ’ εὐσχημοσύνης κιβδήλου κτησώμεθα, καὶ παρὰ θεοῖς καὶ παρ’ ἀνθρώποις πράξομεν κατὰ νοῦν ζῶντές τε καὶ τελευτήσαντες, ὡς ὁ τῶν πολλῶν τε καὶ ἄκρων λεγόμενος λόγος; ἐκ δὴ πάντων τῶν εἰρημένων","st":"366b"},{"sp":"N","t":"τίς μηχανή, ὦ Σώκρατες, δικαιοσύνην τιμᾶν ἐθέλειν ᾧ τις δύναμις ὑπάρχει ψυχῆς ἢ χρημάτων ἢ σώματος ἢ γένους, ἀλλὰ μὴ γελᾶν ἐπαινουμένης ἀκούοντα; ὡς δή τοι εἴ τις ἔχει ψευδῆ μὲν ἀποφῆναι ἃ εἰρήκαμεν, ἱκανῶς δὲ ἔγνωκεν ὅτι ἄριστον δικαιοσύνη, πολλήν που συγγνώμην ἔχει καὶ οὐκ ὀργίζεται τοῖς ἀδίκοις, ἀλλ’ οἶδεν ὅτι πλὴν εἴ τις θείᾳ φύσει δυσχεραίνων τὸ ἀδικεῖν ἢ ἐπιστήμην λαβὼν","st":"366c"},{"sp":"N","t":"ἀπέχεται αὐτοῦ, τῶν γε ἄλλων οὐδεὶς ἑκὼν δίκαιος, ἀλλ’ ὑπὸ ἀνανδρίας ἢ γήρως ἤ τινος ἄλλης ἀσθενείας ψέγει τὸ ἀδικεῖν, ἀδυνατῶν αὐτὸ δρᾶν. ὡς δέ, δῆλον· ὁ γὰρ πρῶτος τῶν τοιούτων εἰς δύναμιν ἐλθὼν πρῶτος ἀδικεῖ, καθ’ ὅσον ἂν οἷός τ’ ᾖ. καὶ τούτων ἁπάντων οὐδὲν ἄλλο αἴτιον ἢ ἐκεῖνο, ὅθενπερ ἅπας ὁ λόγος οὗτος ὥρμησεν καὶ τῷδε καὶ ἐμοὶ πρὸς σέ, ὦ Σώκρατες, εἰπεῖν, ὅτι “Ὦ θαυμάσιε, πάντων","st":"366d"},{"sp":"N","t":"ὑμῶν, ὅσοι ἐπαινέται φατὲ δικαιοσύνης εἶναι, ἀπὸ τῶν ἐξ ἀρχῆς ἡρώων ἀρξάμενοι, ὅσων λόγοι λελειμμένοι, μέχρι τῶν νῦν ἀνθρώπων οὐδεὶς πώποτε ἔψεξεν ἀδικίαν οὐδ’ ἐπῄνεσεν δικαιοσύνην ἄλλως ἢ δόξας τε καὶ τιμὰς καὶ δωρεὰς τὰς ἀπ’ αὐτῶν γιγνομένας· αὐτὸ δ’ ἑκάτερον τῇ αὑτοῦ δυνάμει τί δρᾷ, τῇ τοῦ ἔχοντος ψυχῇ ἐνόν, καὶ λανθάνον θεούς τε καὶ ἀνθρώπους, οὐδεὶς πώποτε οὔτ’ ἐν ποιήσει οὔτ’ ἐν ἰδίοις λόγοις ἐπεξῆλθεν ἱκανῶς τῷ λόγῳ ὡς τὸ μὲν μέγιστον κακῶν ὅσα ἴσχει ψυχὴ ἐν αὑτῇ, δικαιοσύνη δὲ μέγιστον ἀγαθόν.","st":"366e"},{"sp":"N","t":"εἰ γὰρ οὕτως ἐλέγετο ἐξ ἀρχῆς ὑπὸ πάντων ὑμῶν καὶ ἐκ νέων ἡμᾶς ἐπείθετε, οὐκ ἂν ἀλλήλους ἐφυλάττομεν μὴ ἀδικεῖν, ἀλλ’ αὐτὸς αὑτοῦ ἦν ἕκαστος ἄριστος φύλαξ, δεδιὼς μὴ ἀδικῶν τῷ μεγίστῳ κακῷ σύνοικος ᾖ.”","st":"367a"},{"sp":"N","t":"Ταῦτα, ὦ Σώκρατες, ἴσως δὲ καὶ ἔτι τούτων πλείω Θρασύμαχός τε καὶ ἄλλος πού τις ὑπὲρ δικαιοσύνης τε καὶ ἀδικίας λέγοιεν ἄν, μεταστρέφοντες αὐτοῖν τὴν δύναμιν φορτικῶς, ὥς γέ μοι δοκεῖ. ἀλλ’ ἐγώ, οὐδὲν γάρ σε","st":"367a"},{"sp":"N","t":"δέομαι ἀποκρύπτεσθαι, σοῦ ἐπιθυμῶν ἀκοῦσαι τἀναντία, ὡς δύναμαι μάλιστα κατατείνας λέγω. μὴ οὖν ἡμῖν μόνον ἐνδείξῃ τῷ λόγῳ ὅτι δικαιοσύνη ἀδικίας κρεῖττον, ἀλλὰ τί ποιοῦσα ἑκατέρα τὸν ἔχοντα αὐτὴ δι’ αὑτὴν ἡ μὲν κακόν, ἡ δὲ ἀγαθόν ἐστιν· τὰς δὲ δόξας ἀφαίρει, ὥσπερ Γλαύκων διεκελεύσατο. εἰ γὰρ μὴ ἀφαιρήσεις ἑκατέρωθεν τὰς ἀληθεῖς, τὰς δὲ ψευδεῖς προσθήσεις, οὐ τὸ δίκαιον φήσομεν ἐπαινεῖν σε ἀλλὰ τὸ δοκεῖν, οὐδὲ τὸ ἄδικον εἶναι","st":"367b"},{"sp":"N","t":"ψέγειν ἀλλὰ τὸ δοκεῖν, καὶ παρακελεύεσθαι ἄδικον ὄντα λανθάνειν, καὶ ὁμολογεῖν Θρασυμάχῳ ὅτι τὸ μὲν δίκαιον ἀλλότριον ἀγαθόν, συμφέρον τοῦ κρείττονος, τὸ δὲ ἄδικον αὑτῷ μὲν συμφέρον καὶ λυσιτελοῦν, τῷ δὲ ἥττονι ἀσύμφορον. ἐπειδὴ οὖν ὡμολόγησας τῶν μεγίστων ἀγαθῶν εἶναι δικαιοσύνην, ἃ τῶν τε ἀποβαινόντων ἀπ’ αὐτῶν ἕνεκα ἄξια κεκτῆσθαι, πολὺ δὲ μᾶλλον αὐτὰ αὑτῶν, οἷον ὁρᾶν,","st":"367c"},{"sp":"N","t":"ἀκούειν, φρονεῖν, καὶ ὑγιαίνειν δή, καὶ ὅσ’ ἄλλα ἀγαθὰ γόνιμα τῇ αὑτῶν φύσει ἀλλ’ οὐ δόξῃ ἐστίν, τοῦτ’ οὖν αὐτὸ ἐπαίνεσον δικαιοσύνης, ὃ αὐτὴ δι’ αὑτὴν τὸν ἔχοντα ὀνίνησιν καὶ ἀδικία βλάπτει, μισθοὺς δὲ καὶ δόξας πάρες ἄλλοις ἐπαινεῖν· ὡς ἐγὼ τῶν μὲν ἄλλων ἀποδεχοίμην ἂν οὕτως ἐπαινούντων δικαιοσύνην καὶ ψεγόντων ἀδικίαν, δόξας τε περὶ αὐτῶν καὶ μισθοὺς ἐγκωμιαζόντων καὶ λοιδορούντων, σοῦ δὲ οὐκ ἄν, εἰ μὴ σὺ κελεύοις, διότι πάντα τὸν βίον","st":"367d"},{"sp":"N","t":"οὐδὲν ἄλλο σκοπῶν διελήλυθας ἢ τοῦτο. μὴ οὖν ἡμῖν ἐνδείξῃ μόνον τῷ λόγῳ ὅτι δικαιοσύνη ἀδικίας κρεῖττον, ἀλλὰ καὶ τί ποιοῦσα ἑκατέρα τὸν ἔχοντα αὐτὴ δι’ αὑτήν, ἐάντε λανθάνῃ ἐάντε μὴ θεούς τε καὶ ἀνθρώπους, ἡ μὲν ἀγαθόν, ἡ δὲ κακόν ἐστι.","st":"367e"},{"sp":"N","t":"Σωκράτης, Αδείμαντος","st":"367e"},{"sp":"N","t":"Καὶ ἐγὼ ἀκούσας, ἀεὶ μὲν δὴ τὴν φύσιν τοῦ τε Γλαύκωνος καὶ τοῦ Ἀδειμάντου ἠγάμην, ἀτὰρ οὖν καὶ τότε πάνυ γε","st":"367e"},{"sp":"N","t":"ἥσθην καὶ εἶπον· Οὐ κακῶς εἰς ὑμᾶς, ὦ παῖδες ἐκείνου τοῦ ἀνδρός, τὴν ἀρχὴν τῶν ἐλεγείων ἐποίησεν ὁ Γλαύκωνος ἐραστής, εὐδοκιμήσαντας περὶ τὴν Μεγαροῖ μάχην, εἰπών —","st":"368a"},{"sp":"N","t":"παῖδες Ἀρίστωνος, κλεινοῦ θεῖον γένος ἀνδρός","st":"368a"},{"sp":"N","t":"τοῦτό μοι, ὦ φίλοι, εὖ δοκεῖ ἔχειν· πάνυ γὰρ θεῖον πεπόνθατε, εἰ μὴ πέπεισθε ἀδικίαν δικαιοσύνης ἄμεινον εἶναι, οὕτω δυνάμενοι εἰπεῖν ὑπὲρ αὐτοῦ. δοκεῖτε δή μοι ὡς","st":"368a"},{"sp":"N","t":"ἀληθῶς οὐ πεπεῖσθαι — τεκμαίρομαι δὲ ἐκ τοῦ ἄλλου τοῦ ὑμετέρου τρόπου, ἐπεὶ κατά γε αὐτοὺς τοὺς λόγους ἠπίστουν ἂν ὑμῖν — ὅσῳ δὲ μᾶλλον πιστεύω, τοσούτῳ μᾶλλον ἀπορῶ ὅτι χρήσωμαι. οὔτε γὰρ ὅπως βοηθῶ ἔχω· δοκῶ γάρ μοι ἀδύνατος εἶναι — σημεῖον δέ μοι, ὅτι ἃ πρὸς Θρασύμαχον λέγων ᾤμην ἀποφαίνειν ὡς ἄμεινον δικαιοσύνη ἀδικίας, οὐκ ἀπεδέξασθέ μου — οὔτ’ αὖ ὅπως μὴ βοηθήσω ἔχω· δέδοικα γὰρ μὴ οὐδ’ ὅσιον ᾖ παραγενόμενον δικαιοσύνῃ κακηγορουμένῃ","st":"368b"},{"sp":"N","t":"ἀπαγορεύειν καὶ μὴ βοηθεῖν ἔτι ἐμπνέοντα καὶ δυνάμενον φθέγγεσθαι. κράτιστον οὖν οὕτως ὅπως δύναμαι ἐπικουρεῖν αὐτῇ.","st":"368c"},{"sp":"N","t":"Ὅ τε οὖν Γλαύκων καὶ οἱ ἄλλοι ἐδέοντο παντὶ τρόπῳ βοηθῆσαι καὶ μὴ ἀνεῖναι τὸν λόγον, ἀλλὰ διερευνήσασθαι τί τέ ἐστιν ἑκάτερον καὶ περὶ τῆς ὠφελίας αὐτοῖν τἀληθὲς ποτέρως ἔχει. εἶπον οὖν ὅπερ ἐμοὶ ἔδοξεν, ὅτι Τὸ ζήτημα ᾧ ἐπιχειροῦμεν οὐ φαῦλον ἀλλ’ ὀξὺ βλέποντος, ὡς ἐμοὶ","st":"368c"},{"sp":"N","t":"φαίνεται. ἐπειδὴ οὖν ἡμεῖς οὐ δεινοί, δοκῶ μοι, ἦν δ’ ἐγώ, τοιαύτην ποιήσασθαι ζήτησιν αὐτοῦ, οἵανπερ ἂν εἰ προσέταξέ τις γράμματα σμικρὰ πόρρωθεν ἀναγνῶναι μὴ πάνυ ὀξὺ βλέπουσιν, ἔπειτά τις ἐνενόησεν, ὅτι τὰ αὐτὰ γράμματα ἔστι που καὶ ἄλλοθι μείζω τε καὶ ἐν μείζονι, ἕρμαιον ἂν ἐφάνη οἶμαι ἐκεῖνα πρῶτον ἀναγνόντας οὕτως ἐπισκοπεῖν τὰ ἐλάττω, εἰ τὰ αὐτὰ ὄντα τυγχάνει.","st":"368d"},{"sp":"N","t":"Πάνυ μὲν οὖν, ἔφη ὁ Ἀδείμαντος· ἀλλὰ τί τοιοῦτον, ὦ","st":"368d"},{"sp":"N","t":"Σώκρατες, ἐν τῇ περὶ τὸ δίκαιον ζητήσει καθορᾷς;","st":"368e"},{"sp":"N","t":"Ἐγώ σοι, ἔφην, ἐρῶ. δικαιοσύνη, φαμέν, ἔστι μὲν ἀνδρὸς ἑνός, ἔστι δέ που καὶ ὅλης πόλεως;","st":"368e"},{"sp":"N","t":"Πάνυ γε, ἦ δ’ ὅς.","st":"368e"},{"sp":"N","t":"Οὐκοῦν μεῖζον πόλις ἑνὸς ἀνδρός;","st":"368e"},{"sp":"N","t":"Μεῖζον, ἔφη.","st":"368e"},{"sp":"N","t":"Ἴσως τοίνυν πλείων ἂν δικαιοσύνη ἐν τῷ μείζονι ἐνείη καὶ ῥᾴων καταμαθεῖν. εἰ οὖν βούλεσθε, πρῶτον ἐν ταῖς","st":"368e"},{"sp":"N","t":"πόλεσι ζητήσωμεν ποῖόν τί ἐστιν· ἔπειτα οὕτως ἐπισκεψώμεθα καὶ ἐν ἑνὶ ἑκάστῳ, τὴν τοῦ μείζονος ὁμοιότητα ἐν τῇ τοῦ ἐλάττονος ἰδέᾳ ἐπισκοποῦντες.","st":"369a"},{"sp":"N","t":"Ἀλλά μοι δοκεῖς, ἔφη, καλῶς λέγειν.","st":"369a"},{"sp":"N","t":"Ἆρ’ οὖν, ἦν δ’ ἐγώ, εἰ γιγνομένην πόλιν θεασαίμεθα λόγῳ, καὶ τὴν δικαιοσύνην αὐτῆς ἴδοιμεν ἂν γιγνομένην καὶ τὴν ἀδικίαν;","st":"369a"},{"sp":"N","t":"Τάχ’ ἄν, ἦ δ’ ὅς.","st":"369a"},{"sp":"N","t":"Οὐκοῦν γενομένου αὐτοῦ ἐλπὶς εὐπετέστερον ἰδεῖν ὃ ζητοῦμεν;","st":"369a"},{"sp":"N","t":"Πολύ γε.","st":"369b"},{"sp":"N","t":"Δοκεῖ οὖν χρῆναι ἐπιχειρῆσαι περαίνειν; οἶμαι μὲν γὰρ οὐκ ὀλίγον ἔργον αὐτὸ εἶναι· σκοπεῖτε οὖν.","st":"369b"},{"sp":"N","t":"Ἔσκεπται, ἔφη ὁ Ἀδείμαντος· ἀλλὰ μὴ ἄλλως ποίει.","st":"369b"},{"sp":"N","t":"Γίγνεται τοίνυν, ἦν δ’ ἐγώ, πόλις, ὡς ἐγᾦμαι, ἐπειδὴ τυγχάνει ἡμῶν ἕκαστος οὐκ αὐτάρκης, ἀλλὰ πολλῶν ⟨ὢν⟩ ἐνδεής· ἢ τίν’ οἴει ἀρχὴν ἄλλην πόλιν οἰκίζειν;","st":"369b"},{"sp":"N","t":"Οὐδεμίαν, ἦ δ’ ὅς.","st":"369b"},{"sp":"N","t":"Οὕτω δὴ ἄρα παραλαμβάνων ἄλλος ἄλλον, ἐπ’ ἄλλου, τὸν δ’ ἐπ’ ἄλλου χρείᾳ, πολλῶν δεόμενοι, πολλοὺς εἰς μίαν οἴκησιν ἀγείραντες κοινωνούς τε καὶ βοηθούς, ταύτῃ τῇ συνοικίᾳ ἐθέμεθα πόλιν ὄνομα· ἦ γάρ;","st":"369c"},{"sp":"N","t":"Πάνυ μὲν οὖν.","st":"369c"},{"sp":"N","t":"Μεταδίδωσι δὴ ἄλλος ἄλλῳ, εἴ τι μεταδίδωσιν, ἢ μεταλαμβάνει, οἰόμενος αὑτῷ ἄμεινον εἶναι;","st":"369c"},{"sp":"N","t":"Πάνυ γε.","st":"369c"},{"sp":"N","t":"Ἴθι δή, ἦν δ’ ἐγώ, τῷ λόγῳ ἐξ ἀρχῆς ποιῶμεν πόλιν· ποιήσει δὲ αὐτήν, ὡς ἔοικεν, ἡ ἡμετέρα χρεία.","st":"369c"},{"sp":"N","t":"Πῶς δ’ οὔ;","st":"369c"},{"sp":"N","t":"Ἀλλὰ μὴν πρώτη γε καὶ μεγίστη τῶν χρειῶν ἡ τῆς τροφῆς παρασκευὴ τοῦ εἶναί τε καὶ ζῆν ἕνεκα.","st":"369d"},{"sp":"N","t":"Παντάπασί γε.","st":"369d"},{"sp":"N","t":"Δευτέρα δὴ οἰκήσεως, τρίτη δὲ ἐσθῆτος καὶ τῶν τοιούτων.","st":"369d"},{"sp":"N","t":"Ἔστι ταῦτα.","st":"369d"},{"sp":"N","t":"Φέρε δή, ἦν δ’ ἐγώ, πῶς ἡ πόλις ἀρκέσει ἐπὶ τοσαύτην παρασκευήν; ἄλλο τι γεωργὸς μὲν εἷς, ὁ δὲ οἰκοδόμος, ἄλλος δέ τις ὑφάντης; ἢ καὶ σκυτοτόμον αὐτόσε προσθήσομεν ἤ τιν’ ἄλλον τῶν περὶ τὸ σῶμα θεραπευτήν;","st":"369d"},{"sp":"N","t":"Πάνυ γε.","st":"369d"},{"sp":"N","t":"Εἴη δ’ ἂν ἥ γε ἀναγκαιοτάτη πόλις ἐκ τεττάρων ἢ πέντε ἀνδρῶν.","st":"369d"},{"sp":"N","t":"Φαίνεται.","st":"369e"},{"sp":"N","t":"Τί δὴ οὖν; ἕνα ἕκαστον τούτων δεῖ τὸ αὑτοῦ ἔργον ἅπασι κοινὸν κατατιθέναι, οἷον τὸν γεωργὸν ἕνα ὄντα παρασκευάζειν σιτία τέτταρσιν καὶ τετραπλάσιον χρόνον τε καὶ πόνον ἀναλίσκειν ἐπὶ σίτου παρασκευῇ καὶ ἄλλοις κοινωνεῖν, ἢ ἀμελήσαντα ἑαυτῷ μόνον τέταρτον μέρος ποιεῖν τούτου τοῦ","st":"369e"},{"sp":"N","t":"σίτου ἐν τετάρτῳ μέρει τοῦ χρόνου, τὰ δὲ τρία, τὸ μὲν ἐπὶ τῇ τῆς οἰκίας παρασκευῇ διατρίβειν, τὸ δὲ ἱματίου, τὸ δὲ ὑποδημάτων, καὶ μὴ ἄλλοις κοινωνοῦντα πράγματα ἔχειν, ἀλλ’ αὐτὸν δι’ αὑτὸν τὰ αὑτοῦ πράττειν;","st":"370a"},{"sp":"N","t":"Καὶ ὁ Ἀδείμαντος ἔφη· Ἀλλ’ ἴσως, ὦ Σώκρατες, οὕτω ῥᾷον ἢ ‘κείνως.","st":"370a"},{"sp":"N","t":"Οὐδέν, ἦν δ’ ἐγώ, μὰ Δία ἄτοπον. ἐννοῶ γὰρ καὶ αὐτὸς εἰπόντος σοῦ, ὅτι πρῶτον μὲν ἡμῶν φύεται ἕκαστος οὐ πάνυ","st":"370a"},{"sp":"N","t":"ὅμοιος ἑκάστῳ, ἀλλὰ διαφέρων τὴν φύσιν, ἄλλος ἐπ’ ἄλλου ἔργου πράξει. ἢ οὐ δοκεῖ σοι;","st":"370b"},{"sp":"N","t":"Ἔμοιγε.","st":"370b"},{"sp":"N","t":"Τί δέ; πότερον κάλλιον πράττοι ἄν τις εἷς ὢν πολλὰς τέχνας ἐργαζόμενος, ἢ ὅταν μίαν εἷς;","st":"370b"},{"sp":"N","t":"Ὅταν, ἦ δ’ ὅς, εἷς μίαν.","st":"370b"},{"sp":"N","t":"Ἀλλὰ μὴν οἶμαι καὶ τόδε δῆλον, ὡς, ἐάν τίς τινος παρῇ ἔργου καιρόν, διόλλυται.","st":"370b"},{"sp":"N","t":"Δῆλον γάρ.","st":"370b"},{"sp":"N","t":"Οὐ γὰρ οἶμαι ἐθέλει τὸ πραττόμενον τὴν τοῦ πράττοντος σχολὴν περιμένειν, ἀλλ’ ἀνάγκη τὸν πράττοντα τῷ πραττομένῳ","st":"370b"},{"sp":"N","t":"ἐπακολουθεῖν μὴ ἐν παρέργου μέρει.","st":"370c"},{"sp":"N","t":"Ἀνάγκη.","st":"370c"},{"sp":"N","t":"Ἐκ δὴ τούτων πλείω τε ἕκαστα γίγνεται καὶ κάλλιον καὶ ῥᾷον, ὅταν εἷς ἓν κατὰ φύσιν καὶ ἐν καιρῷ, σχολὴν τῶν ἄλλων ἄγων, πράττῃ.","st":"370c"},{"sp":"N","t":"Παντάπασι μὲν οὖν.","st":"370c"},{"sp":"N","t":"Πλειόνων δή, ὦ Ἀδείμαντε, δεῖ πολιτῶν ἢ τεττάρων ἐπὶ τὰς παρασκευὰς ὧν ἐλέγομεν. ὁ γὰρ γεωργός, ὡς ἔοικεν, οὐκ αὐτὸς ποιήσεται ἑαυτῷ τὸ ἄροτρον, εἰ μέλλει καλὸν εἶναι,","st":"370c"},{"sp":"N","t":"οὐδὲ σμινύην, οὐδὲ τἆλλα ὄργανα ὅσα περὶ γεωργίαν. οὐδ’ αὖ ὁ οἰκοδόμος· πολλῶν δὲ καὶ τούτῳ δεῖ. ὡσαύτως δ’ ὁ ὑφάντης τε καὶ ὁ σκυτοτόμος· ἢ οὔ;","st":"370d"},{"sp":"N","t":"Ἀληθῆ.","st":"370d"},{"sp":"N","t":"Τέκτονες δὴ καὶ χαλκῆς καὶ τοιοῦτοί τινες πολλοὶ δημιουργοί, κοινωνοὶ ἡμῖν τοῦ πολιχνίου γιγνόμενοι, συχνὸν αὐτὸ ποιοῦσιν.","st":"370d"},{"sp":"N","t":"Πάνυ μὲν οὖν.","st":"370d"},{"sp":"N","t":"Ἀλλ’ οὐκ ἄν πω πάνυ γε μέγα τι εἴη, εἰ αὐτοῖς βουκόλους τε καὶ ποιμένας τούς τε ἄλλους νομέας προσθεῖμεν, ἵνα οἵ τε","st":"370d"},{"sp":"N","t":"γεωργοὶ ἐπὶ τὸ ἀροῦν ἔχοιεν βοῦς, οἵ τε οἰκοδόμοι πρὸς τὰς ἀγωγὰς μετὰ τῶν γεωργῶν χρῆσθαι ὑποζυγίοις, ὑφάνται δὲ καὶ σκυτοτόμοι δέρμασίν τε καὶ ἐρίοις.","st":"370e"},{"sp":"N","t":"Οὐδέ γε, ἦ δ’ ὅς, σμικρὰ πόλις ἂν εἴη ἔχουσα πάντα ταῦτα.","st":"370e"},{"sp":"N","t":"Ἀλλὰ μήν, ἦν δ’ ἐγώ, κατοικίσαι γε αὐτὴν τὴν πόλιν εἰς τοιοῦτον τόπον οὗ ἐπεισαγωγίμων μὴ δεήσεται, σχεδόν τι ἀδύνατον.","st":"370e"},{"sp":"N","t":"Ἀδύνατον γάρ.","st":"370e"},{"sp":"N","t":"Προσδεήσει ἄρα ἔτι καὶ ἄλλων, οἳ ἐξ ἄλλης πόλεως αὐτῇ κομιοῦσιν ὧν δεῖται.","st":"370e"},{"sp":"N","t":"Δεήσει.","st":"370e"},{"sp":"N","t":"Καὶ μὴν κενὸς ἂν ἴῃ ὁ διάκονος, μηδὲν ἄγων ὧν ἐκεῖνοι","st":"370e"},{"sp":"N","t":"δέονται παρ’ ὧν ἂν κομίζωνται ὧν ἂν αὐτοῖς χρεία, κενὸς ἄπεισιν. ἦ γάρ;","st":"371a"},{"sp":"N","t":"Δοκεῖ μοι.","st":"371a"},{"sp":"N","t":"Δεῖ δὴ τὰ οἴκοι μὴ μόνον ἑαυτοῖς ποιεῖν ἱκανά, ἀλλὰ καὶ οἷα καὶ ὅσα ἐκείνοις ὧν ἂν δέωνται.","st":"371a"},{"sp":"N","t":"Δεῖ γάρ.","st":"371a"},{"sp":"N","t":"Πλειόνων δὴ γεωργῶν τε καὶ τῶν ἄλλων δημιουργῶν δεῖ ἡμῖν τῇ πόλει.","st":"371a"},{"sp":"N","t":"Πλειόνων γάρ.","st":"371a"},{"sp":"N","t":"Καὶ δὴ καὶ τῶν ἄλλων διακόνων που τῶν τε εἰσαξόντων καὶ ἐξαξόντων ἕκαστα. οὗτοι δέ εἰσιν ἔμποροι· ἦ γάρ;","st":"371a"},{"sp":"N","t":"Ναί.","st":"371a"},{"sp":"N","t":"Καὶ ἐμπόρων δὴ δεησόμεθα.","st":"371a"},{"sp":"N","t":"Πάνυ γε","st":"371a"},{"sp":"N","t":"Καὶ ἐὰν μέν γε κατὰ θάλατταν ἡ ἐμπορία γίγνηται, συχνῶν","st":"371a"},{"sp":"N","t":"καὶ ἄλλων προσδεήσεται τῶν ἐπιστημόνων τῆς περὶ τὴν θάλατταν ἐργασίας.","st":"371b"},{"sp":"N","t":"Συχνῶν μέντοι.","st":"371b"},{"sp":"N","t":"Τί δὲ δή; ἐν αὐτῇ τῇ πόλει πῶς ἀλλήλοις μεταδώσουσιν ὧν ἂν ἕκαστοι ἐργάζωνται; ὧν δὴ ἕνεκα καὶ κοινωνίαν ποιησάμενοι πόλιν ᾠκίσαμεν.","st":"371b"},{"sp":"N","t":"Δῆλον δή, ἦ δ’ ὅς, ὅτι πωλοῦντες καὶ ὠνούμενοι.","st":"371b"},{"sp":"N","t":"Ἀγορὰ δὴ ἡμῖν καὶ νόμισμα σύμβολον τῆς ἀλλαγῆς ἕνεκα γενήσεται ἐκ τούτου.","st":"371b"},{"sp":"N","t":"Πάνυ μὲν οὖν.","st":"371b"},{"sp":"N","t":"Ἂν οὖν κομίσας ὁ γεωργὸς εἰς τὴν ἀγοράν τι ὧν ποιεῖ, ἤ τις ἄλλος τῶν δημιουργῶν, μὴ εἰς τὸν αὐτὸν χρόνον ἥκῃ τοῖς δεομένοις τὰ παρ’ αὐτοῦ ἀλλάξασθαι, ἀργήσει τῆς αὑτοῦ δημιουργίας καθήμενος ἐν ἀγορᾷ;","st":"371c"},{"sp":"N","t":"Οὐδαμῶς, ἦ δ’ ὅς, ἀλλὰ εἰσὶν οἳ τοῦτο ὁρῶντες ἑαυτοὺς ἐπὶ τὴν διακονίαν τάττουσιν ταύτην, ἐν μὲν ταῖς ὀρθῶς οἰκουμέναις πόλεσι σχεδόν τι οἱ ἀσθενέστατοι τὰ σώματα καὶ ἀχρεῖοί τι ἄλλο ἔργον πράττειν. αὐτοῦ γὰρ δεῖ μένοντας","st":"371c"},{"sp":"N","t":"αὐτοὺς περὶ τὴν ἀγορὰν τὰ μὲν ἀντ’ ἀργυρίου ἀλλάξασθαι τοῖς τι δεομένοις ἀποδόσθαι, τοῖς δὲ ἀντὶ αὖ ἀργυρίου διαλλάττειν ὅσοι τι δέονται πρίασθαι.","st":"371d"},{"sp":"N","t":"Αὕτη ἄρα, ἦν δ’ ἐγώ, ἡ χρεία καπήλων ἡμῖν γένεσιν ἐμποιεῖ τῇ πόλει. ἢ οὐ καπήλους καλοῦμεν τοὺς πρὸς ὠνήν τε καὶ πρᾶσιν διακονοῦντας ἱδρυμένους ἐν ἀγορᾷ, τοὺς δὲ πλανήτας ἐπὶ τὰς πόλεις ἐμπόρους;","st":"371d"},{"sp":"N","t":"Πάνυ μὲν οὖν.","st":"371d"},{"sp":"N","t":"Ἔτι δή τινες, ὡς ἐγᾦμαι, εἰσὶ καὶ ἄλλοι διάκονοι, οἳ ἂν τὰ μὲν τῆς διανοίας μὴ πάνυ ἀξιοκοινώνητοι ὦσιν, τὴν δὲ τοῦ σώματος ἰσχὺν ἱκανὴν ἐπὶ τοὺς πόνους ἔχωσιν· οἳ δὴ πωλοῦντες τὴν τῆς ἰσχύος χρείαν, τὴν τιμὴν ταύτην μισθὸν καλοῦντες, κέκληνται, ὡς ἐγᾦμαι, μισθωτοί· ἦ γάρ;","st":"371e"},{"sp":"N","t":"Πάνυ μὲν οὖν.","st":"371e"},{"sp":"N","t":"Πλήρωμα δὴ πόλεώς εἰσιν, ὡς ἔοικε, καὶ μισθωτοί.","st":"371e"},{"sp":"N","t":"Δοκεῖ μοι.","st":"371e"},{"sp":"N","t":"Ἆρ’ οὖν, ὦ Ἀδείμαντε, ἤδη ἡμῖν ηὔξηται ἡ πόλις, ὥστ’ εἶναι τελέα;","st":"371e"},{"sp":"N","t":"Ἴσως.","st":"371e"},{"sp":"N","t":"Ποῦ οὖν ἄν ποτε ἐν αὐτῇ εἴη ἥ τε δικαιοσύνη καὶ ἡ ἀδικία; καὶ τίνι ἅμα ἐγγενομένη ὧν ἐσκέμμεθα;","st":"371e"},{"sp":"N","t":"Ἐγὼ μέν, ἔφη, οὐκ ἐννοῶ, ὦ Σώκρατες, εἰ μή που ἐν αὐτῶν τούτων χρείᾳ τινὶ τῇ πρὸς ἀλλήλους.","st":"372a"},{"sp":"N","t":"Ἀλλ’ ἴσως, ἦν δ’ ἐγώ, καλῶς λέγεις· καὶ σκεπτέον γε καὶ οὐκ ἀποκνητέον.","st":"372a"},{"sp":"N","t":"Πρῶτον οὖν σκεψώμεθα τίνα τρόπον διαιτήσονται οἱ οὕτω παρεσκευασμένοι. ἄλλο τι ἢ σῖτόν τε ποιοῦντες καὶ οἶνον καὶ ἱμάτια καὶ ὑποδήματα; καὶ οἰκοδομησάμενοι οἰκίας, θέρους μὲν τὰ πολλὰ γυμνοί τε καὶ ἀνυπόδητοι ἐργάσονται, τοῦ δὲ","st":"372a"},{"sp":"N","t":"χειμῶνος ἠμφιεσμένοι τε καὶ ὑποδεδεμένοι ἱκανῶς· θρέψονται δὲ ἐκ μὲν τῶν κριθῶν ἄλφιτα σκευαζόμενοι, ἐκ δὲ τῶν πυρῶν ἄλευρα, τὰ μὲν πέψαντες, τὰ δὲ μάξαντες, μάζας γενναίας καὶ ἄρτους ἐπὶ κάλαμόν τινα παραβαλλόμενοι ἢ φύλλα καθαρά, κατακλινέντες ἐπὶ στιβάδων ἐστρωμένων μίλακί τε καὶ μυρρίναις, εὐωχήσονται αὐτοί τε καὶ τὰ παιδία, ἐπιπίνοντες τοῦ οἴνου, ἐστεφανωμένοι καὶ ὑμνοῦντες τοὺς θεούς, ἡδέως συνόντες ἀλλήλοις, οὐχ ὑπὲρ τὴν οὐσίαν ποιούμενοι","st":"372b"},{"sp":"N","t":"τοὺς παῖδας, εὐλαβούμενοι πενίαν ἢ πόλεμον.","st":"372c"},{"sp":"N","t":"Σωκράτης, Γλαύκων","st":"372c"},{"sp":"N","t":"Καὶ ὁ Γλαύκων ὑπολαβών, Ἄνευ ὄψου, ἔφη, ὡς ἔοικας, ποιεῖς τοὺς ἄνδρας ἑστιωμένους.","st":"372c"},{"sp":"N","t":"Ἀληθῆ, ἦν δ’ ἐγώ, λέγεις. ἐπελαθόμην ὅτι καὶ ὄψον ἕξουσιν, ἅλας τε δῆλον ὅτι καὶ ἐλάας καὶ τυρόν, καὶ βολβοὺς καὶ λάχανά γε, οἷα δὴ ἐν ἀγροῖς ἑψήματα, ἑψήσονται. καὶ τραγήματά που παραθήσομεν αὐτοῖς τῶν τε σύκων καὶ ἐρεβίνθων καὶ κυάμων, καὶ μύρτα καὶ φηγοὺς σποδιοῦσιν","st":"372c"},{"sp":"N","t":"πρὸς τὸ πῦρ, μετρίως ὑποπίνοντες· καὶ οὕτω διάγοντες τὸν βίον ἐν εἰρήνῃ μετὰ ὑγιείας, ὡς εἰκός, γηραιοὶ τελευτῶντες ἄλλον τοιοῦτον βίον τοῖς ἐκγόνοις παραδώσουσιν.","st":"372d"},{"sp":"N","t":"Καὶ ὅς, Εἰ δὲ ὑῶν πόλιν, ὦ Σώκρατες, ἔφη, κατεσκεύαζες, τί ἂν αὐτὰς ἄλλο ἢ ταῦτα ἐχόρταζες;","st":"372d"},{"sp":"N","t":"Ἀλλὰ πῶς χρή, ἦν δ’ ἐγώ, ὦ Γλαύκων;","st":"372d"},{"sp":"N","t":"Ἅπερ νομίζεται, ἔφη· ἐπί τε κλινῶν κατακεῖσθαι οἶμαι τοὺς μέλλοντας μὴ ταλαιπωρεῖσθαι, καὶ ἀπὸ τραπεζῶν","st":"372d"},{"sp":"N","t":"δειπνεῖν, καὶ ὄψα ἅπερ καὶ οἱ νῦν ἔχουσι καὶ τραγήματα.","st":"372e"},{"sp":"N","t":"Εἶεν, ἦν δ’ ἐγώ· μανθάνω. οὐ πόλιν, ὡς ἔοικε, σκοποῦμεν μόνον ὅπως γίγνεται, ἀλλὰ καὶ τρυφῶσαν πόλιν. ἴσως οὖν οὐδὲ κακῶς ἔχει· σκοποῦντες γὰρ καὶ τοιαύτην τάχ’ ἂν κατίδοιμεν τήν τε δικαιοσύνην καὶ ἀδικίαν ὅπῃ ποτὲ ταῖς πόλεσιν ἐμφύονται. ἡ μὲν οὖν ἀληθινὴ πόλις δοκεῖ μοι εἶναι ἣν διεληλύθαμεν, ὥσπερ ὑγιής τις· εἰ δ’ αὖ βούλεσθε, καὶ φλεγμαίνουσαν πόλιν θεωρήσωμεν· οὐδὲν ἀποκωλύει.","st":"372e"},{"sp":"N","t":"ταῦτα γὰρ δή τισιν, ὡς δοκεῖ, οὐκ ἐξαρκέσει, οὐδὲ αὕτη ἡ δίαιτα, ἀλλὰ κλῖναί τε προσέσονται καὶ τράπεζαι καὶ τἆλλα σκεύη, καὶ ὄψα δὴ καὶ μύρα καὶ θυμιάματα καὶ ἑταῖραι καὶ πέμματα, καὶ ἕκαστα τούτων παντοδαπά. καὶ δὴ καὶ ἃ τὸ πρῶτον ἐλέγομεν οὐκέτι τἀναγκαῖα θετέον, οἰκίας τε καὶ ἱμάτια καὶ ὑποδήματα, ἀλλὰ τήν τε ζωγραφίαν κινητέον καὶ τὴν ποικιλίαν, καὶ χρυσὸν καὶ ἐλέφαντα καὶ πάντα τὰ τοιαῦτα κτητέον. ἦ γάρ;","st":"373a"},{"sp":"N","t":"Ναί, ἔφη.","st":"373b"},{"sp":"N","t":"Οὐκοῦν μείζονά τε αὖ τὴν πόλιν δεῖ ποιεῖν· ἐκείνη γὰρ ἡ ὑγιεινὴ οὐκέτι ἱκανή, ἀλλ’ ἤδη ὄγκου ἐμπληστέα καὶ πλήθους, ἃ οὐκέτι τοῦ ἀναγκαίου ἕνεκά ἐστιν ἐν ταῖς πόλεσιν, οἷον οἵ τε θηρευταὶ πάντες οἵ τε μιμηταί, πολλοὶ μὲν οἱ περὶ τὰ σχήματά τε καὶ χρώματα, πολλοὶ δὲ οἱ περὶ μουσικήν, ποιηταί τε καὶ τούτων ὑπηρέται, ῥαψῳδοί, ὑποκριταί, χορευταί, ἐργολάβοι, σκευῶν τε παντοδαπῶν δημιουργοί, τῶν τε ἄλλων","st":"373b"},{"sp":"N","t":"καὶ τῶν περὶ τὸν γυναικεῖον κόσμον. καὶ δὴ καὶ διακόνων πλειόνων δεησόμεθα· ἢ οὐ δοκεῖ δεήσειν παιδαγωγῶν, τιτθῶν, τροφῶν, κομμωτριῶν, κουρέων, καὶ αὖ ὀψοποιῶν τε καὶ μαγείρων; ἔτι δὲ καὶ συβωτῶν προσδεησόμεθα· τοῦτο γὰρ ἡμῖν ἐν τῇ προτέρᾳ πόλει οὐκ ἐνῆν — ἔδει γὰρ οὐδέν — ἐν δὲ ταύτῃ καὶ τούτου προσδεήσει. δεήσει δὲ καὶ τῶν ἄλλων βοσκημάτων παμπόλλων, εἴ τις αὐτὰ ἔδεται· ἦ γάρ;","st":"373c"},{"sp":"N","t":"Πῶς γὰρ οὔ;","st":"373c"},{"sp":"N","t":"Οὐκοῦν καὶ ἰατρῶν ἐν χρείαις ἐσόμεθα πολὺ μᾶλλον οὕτω διαιτώμενοι ἢ ὡς τὸ πρότερον;","st":"373d"},{"sp":"N","t":"Πολύ γε.","st":"373d"},{"sp":"N","t":"Καὶ ἡ χώρα γέ που, ἡ τότε ἱκανὴ τρέφειν τοὺς τότε, σμικρὰ δὴ ἐξ ἱκανῆς ἔσται. ἢ πῶς λέγομεν;","st":"373d"},{"sp":"N","t":"Οὕτως, ἔφη.","st":"373d"},{"sp":"N","t":"Οὐκοῦν τῆς τῶν πλησίον χώρας ἡμῖν ἀποτμητέον, εἰ μέλλομεν ἱκανὴν ἕξειν νέμειν τε καὶ ἀροῦν, καὶ ἐκείνοις αὖ τῆς ἡμετέρας, ἐὰν καὶ ἐκεῖνοι ἀφῶσιν αὑτοὺς ἐπὶ χρημάτων κτῆσιν ἄπειρον, ὑπερβάντες τὸν τῶν ἀναγκαίων ὅρον;","st":"373d"},{"sp":"N","t":"Πολλὴ ἀνάγκη, ἔφη, ὦ Σώκρατες.","st":"373e"},{"sp":"N","t":"Πολεμήσομεν δὴ τὸ μετὰ τοῦτο, ὦ Γλαύκων; ἢ πῶς ἔσται;","st":"373e"},{"sp":"N","t":"Οὕτως, ἔφη.","st":"373e"},{"sp":"N","t":"Καὶ μηδέν γέ πω λέγωμεν, ἦν δ’ ἐγώ, μήτ’ εἴ τι κακὸν μήτ’ εἰ ἀγαθὸν ὁ πόλεμος ἐργάζεται, ἀλλὰ τοσοῦτον μόνον, ὅτι πολέμου αὖ γένεσιν ηὑρήκαμεν, ἐξ ὧν μάλιστα ταῖς πόλεσιν καὶ ἰδίᾳ καὶ δημοσίᾳ κακὰ γίγνεται, ὅταν γίγνηται.","st":"373e"},{"sp":"N","t":"Πάνυ μὲν οὖν.","st":"373e"},{"sp":"N","t":"Ἔτι δή, ὦ φίλε, μείζονος τῆς πόλεως δεῖ οὔ τι σμικρῷ,","st":"373e"},{"sp":"N","t":"ἀλλ’ ὅλῳ στρατοπέδῳ, ὃ ἐξελθὸν ὑπὲρ τῆς οὐσίας ἁπάσης καὶ ὑπὲρ ὧν νυνδὴ ἐλέγομεν διαμαχεῖται τοῖς ἐπιοῦσιν.","st":"374a"},{"sp":"N","t":"Τί δέ; ἦ δ’ ὅς· αὐτοὶ οὐχ ἱκανοί;","st":"374a"},{"sp":"N","t":"Οὔκ, εἰ σύ γε, ἦν δ’ ἐγώ, καὶ ἡμεῖς ἅπαντες ὡμολογήσαμεν καλῶς, ἡνίκα ἐπλάττομεν τὴν πόλιν· ὡμολογοῦμεν δέ που, εἰ μέμνησαι, ἀδύνατον ἕνα πολλὰς καλῶς ἐργάζεσθαι τέχνας.","st":"374a"},{"sp":"N","t":"Ἀληθῆ λέγεις, ἔφη.","st":"374a"},{"sp":"N","t":"Τί οὖν; ἦν δ’ ἐγώ· ἡ περὶ τὸν πόλεμον ἀγωνία οὐ τεχνικὴ δοκεῖ εἶναι;","st":"374b"},{"sp":"N","t":"Καὶ μάλα, ἔφη.","st":"374b"},{"sp":"N","t":"Ἦ οὖν τι σκυτικῆς δεῖ μᾶλλον κήδεσθαι ἢ πολεμικῆς;","st":"374b"},{"sp":"N","t":"Οὐδαμῶς.","st":"374b"},{"sp":"N","t":"Ἀλλ’ ἄρα τὸν μὲν σκυτοτόμον διεκωλύομεν μήτε γεωργὸν ἐπιχειρεῖν εἶναι ἅμα μήτε ὑφάντην μήτε οἰκοδόμον ἀλλὰ σκυτοτόμον, ἵνα δὴ ἡμῖν τὸ τῆς σκυτικῆς ἔργον καλῶς γίγνοιτο, καὶ τῶν ἄλλων ἑνὶ ἑκάστῳ ὡσαύτως ἓν ἀπεδίδομεν, πρὸς ὃ ἐπεφύκει ἕκαστος καὶ ἐφ’ ᾧ ἔμελλε τῶν ἄλλων","st":"374b"},{"sp":"N","t":"σχολὴν ἄγων διὰ βίου αὐτὸ ἐργαζόμενος οὐ παριεὶς τοὺς καιροὺς καλῶς ἀπεργάσεσθαι· τὰ δὲ δὴ περὶ τὸν πόλεμον πότερον οὐ περὶ πλείστου ἐστὶν εὖ ἀπεργασθέντα; ἢ οὕτω ῥᾴδιον, ὥστε καὶ γεωργῶν τις ἅμα πολεμικὸς ἔσται καὶ σκυτοτομῶν καὶ ἄλλην τέχνην ἡντινοῦν ἐργαζόμενος, πεττευτικὸς δὲ ἢ κυβευτικὸς ἱκανῶς οὐδ’ ἂν εἷς γένοιτο μὴ αὐτὸ τοῦτο ἐκ παιδὸς ἐπιτηδεύων, ἀλλὰ παρέργῳ χρώμενος;","st":"374c"},{"sp":"N","t":"καὶ ἀσπίδα μὲν λαβὼν ἤ τι ἄλλο τῶν πολεμικῶν ὅπλων τε καὶ ὀργάνων αὐθημερὸν ὁπλιτικῆς ἤ τινος ἄλλης μάχης τῶν κατὰ πόλεμον ἱκανὸς ἔσται ἀγωνιστής, τῶν δὲ ἄλλων ὀργάνων οὐδὲν οὐδένα δημιουργὸν οὐδὲ ἀθλητὴν ληφθὲν ποιήσει, οὐδ’ ἔσται χρήσιμον τῷ μήτε τὴν ἐπιστήμην ἑκάστου λαβόντι μήτε τὴν μελέτην ἱκανὴν παρασχομένῳ;","st":"374d"},{"sp":"N","t":"Πολλοῦ γὰρ ἄν, ἦ δ’ ὅς, τὰ ὄργανα ἦν ἄξια.","st":"374d"},{"sp":"N","t":"Οὐκοῦν, ἦν δ’ ἐγώ, ὅσῳ μέγιστον τὸ τῶν φυλάκων ἔργον,","st":"374d"},{"sp":"N","t":"τοσούτῳ σχολῆς τε τῶν ἄλλων πλείστης ἂν εἴη καὶ αὖ τέχνης τε καὶ ἐπιμελείας μεγίστης δεόμενον. Οἶμαι ἔγωγε, ἦ δ’ ὅς.","st":"374e"},{"sp":"N","t":"Ἆρ’ οὖν οὐ καὶ φύσεως ἐπιτηδείας εἰς αὐτὸ τὸ ἐπιτήδευμα;","st":"374e"},{"sp":"N","t":"Πῶς δ’ οὔ;","st":"374e"},{"sp":"N","t":"Ἡμέτερον δὴ ἔργον ἂν εἴη, ὡς ἔοικεν, εἴπερ οἷοί τ’ ἐσμέν, ἐκλέξασθαι τίνες τε καὶ ποῖαι φύσεις ἐπιτήδειαι εἰς πόλεως φυλακήν.","st":"374e"},{"sp":"N","t":"Ἡμέτερον μέντοι.","st":"374e"},{"sp":"N","t":"Μὰ Δία, ἦν δ’ ἐγώ, οὐκ ἄρα φαῦλον πρᾶγμα ἠράμεθα· ὅμως δὲ οὐκ ἀποδειλιατέον, ὅσον γ’ ἂν δύναμις παρείκῃ.","st":"374e"},{"sp":"N","t":"Οὐ γὰρ οὖν, ἔφη.","st":"375a"},{"sp":"N","t":"Οἴει οὖν τι, ἦν δ’ ἐγώ, διαφέρειν φύσιν γενναίου σκύλακος εἰς φυλακὴν νεανίσκου εὐγενοῦς;","st":"375a"},{"sp":"N","t":"Τὸ ποῖον λέγεις;","st":"375a"},{"sp":"N","t":"Οἷον ὀξύν τέ που δεῖ αὐτοῖν ἑκάτερον εἶναι πρὸς αἴσθησιν καὶ ἐλαφρὸν πρὸς τὸ αἰσθανόμενον διωκάθειν, καὶ ἰσχυρὸν αὖ, ἐὰν δέῃ ἑλόντα διαμάχεσθαι.","st":"375a"},{"sp":"N","t":"Δεῖ γὰρ οὖν, ἔφη, πάντων τούτων.","st":"375a"},{"sp":"N","t":"Καὶ μὴν ἀνδρεῖόν γε, εἴπερ εὖ μαχεῖται.","st":"375a"},{"sp":"N","t":"Πῶς δ’ οὔ;","st":"375a"},{"sp":"N","t":"Ἀνδρεῖος δὲ εἶναι ἆρα ἐθελήσει ὁ μὴ θυμοειδὴς εἴτε ἵππος εἴτε κύων ἢ ἄλλο ὁτιοῦν ζῷον; ἢ οὐκ ἐννενόηκας ὡς","st":"375a"},{"sp":"N","t":"ἄμαχόν τε καὶ ἀνίκητον θυμός, οὗ παρόντος ψυχὴ πᾶσα πρὸς πάντα ἄφοβός τέ ἐστι καὶ ἀήττητος;","st":"375b"},{"sp":"N","t":"Ἐννενόηκα.","st":"375b"},{"sp":"N","t":"Τὰ μὲν τοίνυν τοῦ σώματος οἷον δεῖ τὸν φύλακα εἶναι, δῆλα.","st":"375b"},{"sp":"N","t":"Ναί.","st":"375b"},{"sp":"N","t":"Καὶ μὴν καὶ τὰ τῆς ψυχῆς, ὅτι γε θυμοειδῆ.","st":"375b"},{"sp":"N","t":"Καὶ τοῦτο.","st":"375b"},{"sp":"N","t":"Πῶς οὖν, ἦν δ’ ἐγώ, ὦ Γλαύκων, οὐκ ἄγριοι ἀλλήλοις τε ἔσονται καὶ τοῖς ἄλλοις πολίταις, ὄντες τοιοῦτοι τὰς φύσεις;","st":"375b"},{"sp":"N","t":"Μὰ Δία, ἦ δ’ ὅς, οὐ ῥᾳδίως.","st":"375b"},{"sp":"N","t":"Ἀλλὰ μέντοι δεῖ γε πρὸς μὲν τοὺς οἰκείους πρᾴους αὐτοὺς εἶναι, πρὸς δὲ τοὺς πολεμίους χαλεπούς· εἰ δὲ μή, οὐ περιμενοῦσιν ἄλλους σφᾶς διολέσαι, ἀλλ’ αὐτοὶ φθήσονται","st":"375c"},{"sp":"N","t":"αὐτὸ δράσαντες.","st":"375c"},{"sp":"N","t":"Ἀληθῆ, ἔφη.","st":"375c"},{"sp":"N","t":"Τί οὖν, ἦν δ’ ἐγώ, ποιήσομεν; πόθεν ἅμα πρᾷον καὶ μεγαλόθυμον ἦθος εὑρήσομεν; ἐναντία γάρ που θυμοειδεῖ πρᾳεῖα φύσις.","st":"375c"},{"sp":"N","t":"Φαίνεται.","st":"375c"},{"sp":"N","t":"Ἀλλὰ μέντοι τούτων γε ὁποτέρου ἂν στέρηται, φύλαξ ἀγαθὸς οὐ μὴ γένηται· ταῦτα δὲ ἀδυνάτοις ἔοικεν, καὶ οὕτω","st":"375c"},{"sp":"N","t":"δὴ συμβαίνει ἀγαθὸν φύλακα ἀδύνατον γενέσθαι.","st":"375d"},{"sp":"N","t":"Κινδυνεύει, ἔφη.","st":"375d"},{"sp":"N","t":"Καὶ ἐγὼ ἀπορήσας τε καὶ ἐπισκεψάμενος τὰ ἔμπροσθεν, Δικαίως γε, ἦν δ’ ἐγώ, ὦ φίλε, ἀποροῦμεν· ἧς γὰρ προυθέμεθα εἰκόνος ἀπελείφθημεν.","st":"375d"},{"sp":"N","t":"Πῶς λέγεις;","st":"375d"},{"sp":"N","t":"Οὐκ ἐννενοήκαμεν ὅτι εἰσὶν ἄρα φύσεις οἵας ἡμεῖς οὐκ ᾠήθημεν, ἔχουσαι τἀναντία ταῦτα.","st":"375d"},{"sp":"N","t":"Ποῦ δή;","st":"375d"},{"sp":"N","t":"Ἴδοι μὲν ἄν τις καὶ ἐν ἄλλοις ζῴοις, οὐ μεντἂν ἥκιστα","st":"375d"},{"sp":"N","t":"ἐν ᾧ ἡμεῖς παρεβάλλομεν τῷ φύλακι. οἶσθα γάρ που τῶν γενναίων κυνῶν, ὅτι τοῦτο φύσει αὐτῶν τὸ ἦθος, πρὸς μὲν τοὺς συνήθεις τε καὶ γνωρίμους ὡς οἷόν τε πρᾳοτάτους εἶναι, πρὸς δὲ τοὺς ἀγνῶτας τοὐναντίον.","st":"375e"},{"sp":"N","t":"Οἶδα μέντοι.","st":"375e"},{"sp":"N","t":"Τοῦτο μὲν ἄρα, ἦν δ’ ἐγώ, δυνατόν, καὶ οὐ παρὰ φύσιν ζητοῦμεν τοιοῦτον εἶναι τὸν φύλακα.","st":"375e"},{"sp":"N","t":"Οὐκ ἔοικεν.","st":"375e"},{"sp":"N","t":"Ἆρ’ οὖν σοι δοκεῖ ἔτι τοῦδε προσδεῖσθαι ὁ φυλακικὸς ἐσόμενος, πρὸς τῷ θυμοειδεῖ ἔτι προσγενέσθαι φιλόσοφος τὴν φύσιν;","st":"375e"},{"sp":"N","t":"Πῶς δή; ἔφη· οὐ γὰρ ἐννοῶ.","st":"376a"},{"sp":"N","t":"Καὶ τοῦτο, ἦν δ’ ἐγώ, ἐν τοῖς κυσὶν κατόψει, ὃ καὶ ἄξιον θαυμάσαι τοῦ θηρίου.","st":"376a"},{"sp":"N","t":"Τὸ ποῖον;","st":"376a"},{"sp":"N","t":"Ὅτι ὃν μὲν ἂν ἴδῃ ἀγνῶτα, χαλεπαίνει, οὐδὲ ἓν κακὸν προπεπονθώς· ὃν δ’ ἂν γνώριμον, ἀσπάζεται, κἂν μηδὲν πώποτε ὑπ’ αὐτοῦ ἀγαθὸν πεπόνθῃ. ἢ οὔπω τοῦτο ἐθαύμασας; Οὐ πάνυ, ἔφη, μέχρι τούτου προσέσχον τὸν νοῦν· ὅτι δέ που δρᾷ ταῦτα, δῆλον.","st":"376a"},{"sp":"N","t":"Ἀλλὰ μὴν κομψόν γε φαίνεται τὸ πάθος αὐτοῦ τῆς","st":"376a"},{"sp":"N","t":"φύσεως καὶ ὡς ἀληθῶς φιλόσοφον.","st":"376b"},{"sp":"N","t":"Πῇ δή;","st":"376b"},{"sp":"N","t":"Ἧι, ἦν δ’ ἐγώ, ὄψιν οὐδενὶ ἄλλῳ φίλην καὶ ἐχθρὰν διακρίνει ἢ τῷ τὴν μὲν καταμαθεῖν, τὴν δὲ ἀγνοῆσαι. καίτοι πῶς οὐκ ἂν φιλομαθὲς εἴη συνέσει τε καὶ ἀγνοίᾳ ὁριζόμενον τό τε οἰκεῖον καὶ τὸ ἀλλότριον;","st":"376b"},{"sp":"N","t":"Οὐδαμῶς, ἦ δ’ ὅς, ὅπως οὔ.","st":"376b"},{"sp":"N","t":"Ἀλλὰ μέντοι, εἶπον ἐγώ, τό γε φιλομαθὲς καὶ φιλόσοφον ταὐτόν;","st":"376b"},{"sp":"N","t":"Ταὐτὸν γάρ, ἔφη.","st":"376b"},{"sp":"N","t":"Οὐκοῦν θαρροῦντες τιθῶμεν καὶ ἐν ἀνθρώπῳ, εἰ μέλλει","st":"376b"},{"sp":"N","t":"πρὸς τοὺς οἰκείους καὶ γνωρίμους πρᾷός τις ἔσεσθαι, φύσει φιλόσοφον καὶ φιλομαθῆ αὐτὸν δεῖν εἶναι; Τιθῶμεν, ἔφη.","st":"376c"},{"sp":"N","t":"Φιλόσοφος δὴ καὶ θυμοειδὴς καὶ ταχὺς καὶ ἰσχυρὸς ἡμῖν τὴν φύσιν ἔσται ὁ μέλλων καλὸς κἀγαθὸς ἔσεσθαι φύλαξ πόλεως.","st":"376c"},{"sp":"N","t":"Παντάπασι μὲν οὖν, ἔφη.","st":"376c"},{"sp":"N","t":"Οὗτος μὲν δὴ ἂν οὕτως ὑπάρχοι. θρέψονται δὲ δὴ ἡμῖν οὗτοι καὶ παιδευθήσονται τίνα τρόπον; καὶ ἆρά τι προὔργου ἡμῖν ἐστιν αὐτὸ σκοποῦσι πρὸς τὸ κατιδεῖν οὗπερ ἕνεκα","st":"376c"},{"sp":"N","t":"πάντα σκοποῦμεν, δικαιοσύνην τε καὶ ἀδικίαν τίνα τρόπον ἐν πόλει γίγνεται; ἵνα μὴ ἐῶμεν ἱκανὸν λόγον ἢ συχνὸν διεξίωμεν.","st":"376d"},{"sp":"N","t":"Σωκράτης, Αδείμαντος","st":"376d"},{"sp":"N","t":"Καὶ ὁ τοῦ Γλαύκωνος ἀδελφός, Πάνυ μὲν οὖν, ἔφη, ἔγωγε προσδοκῶ προὔργου εἶναι εἰς τοῦτο ταύτην τὴν σκέψιν.","st":"376d"},{"sp":"N","t":"Μὰ Δία, ἦν δ’ ἐγώ, ὦ φίλε Ἀδείμαντε, οὐκ ἄρα ἀφετέον, οὐδ’ εἰ μακροτέρα τυγχάνει οὖσα.","st":"376d"},{"sp":"N","t":"Οὐ γὰρ οὖν.","st":"376d"},{"sp":"N","t":"Ἴθι οὖν, ὥσπερ ἐν μύθῳ μυθολογοῦντές τε καὶ σχολὴν ἄγοντες λόγῳ παιδεύωμεν τοὺς ἄνδρας.","st":"376d"},{"sp":"N","t":"Ἀλλὰ χρή.","st":"376e"},{"sp":"N","t":"Τίς οὖν ἡ παιδεία; ἢ χαλεπὸν εὑρεῖν βελτίω τῆς ὑπὸ τοῦ πολλοῦ χρόνου ηὑρημένης; ἔστιν δέ που ἡ μὲν ἐπὶ σώμασι γυμναστική, ἡ δ’ ἐπὶ ψυχῇ μουσική.","st":"376e"},{"sp":"N","t":"Ἔστιν γάρ.","st":"376e"},{"sp":"N","t":"Ἆρ’ οὖν οὐ μουσικῇ πρότερον ἀρξόμεθα παιδεύοντες ἢ γυμναστικῇ;","st":"376e"},{"sp":"N","t":"Πῶς δ’ οὔ;","st":"376e"},{"sp":"N","t":"Μουσικῆς δ’, εἶπον, τιθεῖς λόγους, ἢ οὔ;","st":"376e"},{"sp":"N","t":"Ἔγωγε.","st":"376e"},{"sp":"N","t":"Λόγων δὲ διττὸν εἶδος, τὸ μὲν ἀληθές, ψεῦδος δ’ ἕτερον;","st":"376e"},{"sp":"N","t":"Ναί.","st":"376e"},{"sp":"N","t":"Παιδευτέον δ’ ἐν ἀμφοτέροις, πρότερον δ’ ἐν τοῖς ψευδέσιν;","st":"377a"},{"sp":"N","t":"Οὐ μανθάνω, ἔφη, πῶς λέγεις.","st":"377a"},{"sp":"N","t":"Οὐ μανθάνεις, ἦν δ’ ἐγώ, ὅτι πρῶτον τοῖς παιδίοις μύθους λέγομεν; τοῦτο δέ που ὡς τὸ ὅλον εἰπεῖν ψεῦδος, ἔνι δὲ καὶ ἀληθῆ. πρότερον δὲ μύθοις πρὸς τὰ παιδία ἢ γυμνασίοις χρώμεθα.","st":"377a"},{"sp":"N","t":"Ἔστι ταῦτα.","st":"377a"},{"sp":"N","t":"Τοῦτο δὴ ἔλεγον, ὅτι μουσικῆς πρότερον ἁπτέον ἢ γυμναστικῆς.","st":"377a"},{"sp":"N","t":"Ὀρθῶς, ἔφη.","st":"377a"},{"sp":"N","t":"Οὐκοῦν οἶσθ’ ὅτι ἀρχὴ παντὸς ἔργου μέγιστον, ἄλλως","st":"377a"},{"sp":"N","t":"τε δὴ καὶ νέῳ καὶ ἁπαλῷ ὁτῳοῦν; μάλιστα γὰρ δὴ τότε πλάττεται, καὶ ἐνδύεται τύπος ὃν ἄν τις βούληται ἐνσημήνασθαι ἑκάστῳ.","st":"377b"},{"sp":"N","t":"Κομιδῇ μὲν οὖν.","st":"377b"},{"sp":"N","t":"Ἆρ’ οὖν ῥᾳδίως οὕτω παρήσομεν τοὺς ἐπιτυχόντας ὑπὸ τῶν ἐπιτυχόντων μύθους πλασθέντας ἀκούειν τοὺς παῖδας καὶ λαμβάνειν ἐν ταῖς ψυχαῖς ὡς ἐπὶ τὸ πολὺ ἐναντίας δόξας ἐκείναις ἅς, ἐπειδὰν τελεωθῶσιν, ἔχειν οἰησόμεθα δεῖν αὐτούς;","st":"377b"},{"sp":"N","t":"Οὐδ’ ὁπωστιοῦν παρήσομεν.","st":"377b"},{"sp":"N","t":"Πρῶτον δὴ ἡμῖν, ὡς ἔοικεν, ἐπιστατητέον τοῖς μυθοποιοῖς,","st":"377b"},{"sp":"N","t":"καὶ ὃν μὲν ἂν καλὸν [μῦθον] ποιήσωσιν, ἐγκριτέον, ὃν δ’ ἂν μή, ἀποκριτέον. τοὺς δ’ ἐγκριθέντας πείσομεν τὰς τροφούς τε καὶ μητέρας λέγειν τοῖς παισίν, καὶ πλάττειν τὰς ψυχὰς αὐτῶν τοῖς μύθοις πολὺ μᾶλλον ἢ τὰ σώματα ταῖς χερσίν· ὧν δὲ νῦν λέγουσι τοὺς πολλοὺς ἐκβλητέον.","st":"377c"},{"sp":"N","t":"Ποίους δή; ἔφη.","st":"377c"},{"sp":"N","t":"Ἐν τοῖς μείζοσιν, ἦν δ’ ἐγώ, μύθοις ὀψόμεθα καὶ τοὺς ἐλάττους. δεῖ γὰρ δὴ τὸν αὐτὸν τύπον εἶναι καὶ ταὐτὸν","st":"377c"},{"sp":"N","t":"δύνασθαι τούς τε μείζους καὶ τοὺς ἐλάττους. ἢ οὐκ οἴει;","st":"377d"},{"sp":"N","t":"Ἔγωγ’, ἔφη· ἀλλ’ οὐκ ἐννοῶ οὐδὲ τοὺς μείζους τίνας λέγεις.","st":"377d"},{"sp":"N","t":"Οὓς Ἡσίοδός τε, εἶπον, καὶ Ὅμηρος ἡμῖν ἐλεγέτην καὶ οἱ ἄλλοι ποιηταί. οὗτοι γάρ που μύθους τοῖς ἀνθρώποις ψευδεῖς συντιθέντες ἔλεγόν τε καὶ λέγουσι.","st":"377d"},{"sp":"N","t":"Ποίους δή, ἦ δ’ ὅς, καὶ τί αὐτῶν μεμφόμενος λέγεις;","st":"377d"},{"sp":"N","t":"Ὅπερ, ἦν δ’ ἐγώ, χρὴ καὶ πρῶτον καὶ μάλιστα μέμφεσθαι, ἄλλως τε καὶ ἐάν τις μὴ καλῶς ψεύδηται.","st":"377d"},{"sp":"N","t":"Τί τοῦτο;","st":"377d"},{"sp":"N","t":"Ὅταν εἰκάζῃ τις κακῶς [οὐσίαν] τῷ λόγῳ, περὶ θεῶν τε καὶ ἡρώων οἷοί εἰσιν, ὥσπερ γραφεὺς μηδὲν ἐοικότα γράφων οἷς ἂν ὅμοια βουληθῇ γράψαι. Καὶ γάρ, ἔφη, ὀρθῶς ἔχει τά γε τοιαῦτα μέμφεσθαι. ἀλλὰ πῶς δὴ λέγομεν καὶ ποῖα;","st":"377e"},{"sp":"N","t":"Πρῶτον μέν, ἦν δ’ ἐγώ, τὸ μέγιστον καὶ περὶ τῶν μεγίστων ψεῦδος ὁ εἰπὼν οὐ καλῶς ἐψεύσατο ὡς Οὐρανός τε ἠργάσατο ἅ φησι δρᾶσαι αὐτὸν Ἡσίοδος, ὅ τε αὖ Κρόνος","st":"377e"},{"sp":"N","t":"ὡς ἐτιμωρήσατο αὐτόν. τὰ δὲ δὴ τοῦ Κρόνου ἔργα καὶ πάθη ὑπὸ τοῦ ὑέος, οὐδ’ ἂν εἰ ἦν ἀληθῆ ᾤμην δεῖν ῥᾳδίως οὕτως λέγεσθαι πρὸς ἄφρονάς τε καὶ νέους, ἀλλὰ μάλιστα μὲν σιγᾶσθαι, εἰ δὲ ἀνάγκη τις ἦν λέγειν, δι’ ἀπορρήτων ἀκούειν ὡς ὀλιγίστους, θυσαμένους οὐ χοῖρον ἀλλά τι μέγα καὶ ἄπορον θῦμα, ὅπως ὅτι ἐλαχίστοις συνέβη ἀκοῦσαι.","st":"378a"},{"sp":"N","t":"Καὶ γάρ, ἦ δ’ ὅς, οὗτοί γε οἱ λόγοι χαλεποί.","st":"378a"},{"sp":"N","t":"Καὶ οὐ λεκτέοι γ’, ἔφην, ὦ Ἀδείμαντε, ἐν τῇ ἡμετέρᾳ πόλει. οὐδὲ λεκτέον νέῳ ἀκούοντι ὡς ἀδικῶν τὰ ἔσχατα οὐδὲν ἂν θαυμαστὸν ποιοῖ, οὐδ’ αὖ ἀδικοῦντα πατέρα κολάζων παντὶ τρόπῳ, ἀλλὰ δρῴη ἂν ὅπερ θεῶν οἱ πρῶτοί τε καὶ μέγιστοι.","st":"378b"},{"sp":"N","t":"Οὐ μὰ τὸν Δία, ἦ δ’ ὅς, οὐδὲ αὐτῷ μοι δοκεῖ ἐπιτήδεια εἶναι λέγειν.","st":"378b"},{"sp":"N","t":"Οὐδέ γε, ἦν δ’ ἐγώ, τὸ παράπαν ὡς θεοὶ θεοῖς πολεμοῦσί","st":"378b"},{"sp":"N","t":"τε καὶ ἐπιβουλεύουσι καὶ μάχονται — οὐδὲ γὰρ ἀληθῆ — εἴ γε δεῖ ἡμῖν τοὺς μέλλοντας τὴν πόλιν φυλάξειν αἴσχιστον νομίζειν τὸ ῥᾳδίως ἀλλήλοις ἀπεχθάνεσθαι — πολλοῦ δεῖ γιγαντομαχίας τε μυθολογητέον αὐτοῖς καὶ ποικιλτέον, καὶ ἄλλας ἔχθρας πολλὰς καὶ παντοδαπὰς θεῶν τε καὶ ἡρώων πρὸς συγγενεῖς τε καὶ οἰκείους αὐτῶν — ἀλλ’ εἴ πως μέλλομεν πείσειν ὡς οὐδεὶς πώποτε πολίτης ἕτερος ἑτέρῳ ἀπήχθετο οὐδ’ ἔστιν τοῦτο ὅσιον, τοιαῦτα λεκτέα μᾶλλον πρὸς","st":"378c"},{"sp":"N","t":"τὰ παιδία εὐθὺς καὶ γέρουσι καὶ γραυσί, καὶ πρεσβυτέροις γιγνομένοις καὶ τοὺς ποιητὰς ἐγγὺς τούτων ἀναγκαστέον λογοποιεῖν. Ἥρας δὲ δεσμοὺς ὑπὸ ὑέος καὶ Ἡφαίστου ῥίψεις ὑπὸ πατρός, μέλλοντος τῇ μητρὶ τυπτομένῃ ἀμυνεῖν, καὶ θεομαχίας ὅσας Ὅμηρος πεποίηκεν οὐ παραδεκτέον εἰς τὴν πόλιν, οὔτ’ ἐν ὑπονοίαις πεποιημένας οὔτε ἄνευ ὑπονοιῶν. ὁ γὰρ νέος οὐχ οἷός τε κρίνειν ὅτι τε ὑπόνοια καὶ ὃ μή, ἀλλ’ ἃ ἂν τηλικοῦτος ὢν λάβῃ ἐν ταῖς δόξαις δυσέκνιπτά","st":"378d"},{"sp":"N","t":"τε καὶ ἀμετάστατα φιλεῖ γίγνεσθαι· ὧν δὴ ἴσως ἕνεκα περὶ παντὸς ποιητέον ἃ πρῶτα ἀκούουσιν ὅτι κάλλιστα μεμυθολογημένα πρὸς ἀρετὴν ἀκούειν. Ἔχει γάρ, ἔφη, λόγον. ἀλλ’ εἴ τις αὖ καὶ ταῦτα ἐρωτῴη ἡμᾶς, ταῦτα ἅττα τ’ ἐστὶν καὶ τίνες οἱ μῦθοι, τίνας ἂν φαῖμεν;","st":"378e"},{"sp":"N","t":"Καὶ ἐγὼ εἶπον· Ὦ Ἀδείμαντε, οὐκ ἐσμὲν ποιηταὶ ἐγώ τε","st":"378e"},{"sp":"N","t":"καὶ σὺ ἐν τῷ παρόντι, ἀλλ’ οἰκισταὶ πόλεως· οἰκισταῖς δὲ τοὺς μὲν τύπους προσήκει εἰδέναι ἐν οἷς δεῖ μυθολογεῖν τοὺς ποιητάς, παρ’ οὓς ἐὰν ποιῶσιν οὐκ ἐπιτρεπτέον, οὐ μὴν αὐτοῖς γε ποιητέον μύθους.","st":"379a"},{"sp":"N","t":"Ὀρθῶς, ἔφη· ἀλλ’ αὐτὸ δὴ τοῦτο, οἱ τύποι περὶ θεολογίας τίνες ἂν εἶεν;","st":"379a"},{"sp":"N","t":"Τοιοίδε πού τινες, ἦν δ’ ἐγώ· οἷος τυγχάνει ὁ θεὸς ὤν, ἀεὶ δήπου ἀποδοτέον, ἐάντέ τις αὐτὸν ἐν ἔπεσιν ποιῇ ἐάντε ἐν μέλεσιν ἐάντε ἐν τραγῳδίᾳ.","st":"379a"},{"sp":"N","t":"Δεῖ γάρ.","st":"379a"},{"sp":"N","t":"Οὐκοῦν ἀγαθὸς ὅ γε θεὸς τῷ ὄντι τε καὶ λεκτέον οὕτω;","st":"379b"},{"sp":"N","t":"Τί μήν;","st":"379b"},{"sp":"N","t":"Ἀλλὰ μὴν οὐδέν γε τῶν ἀγαθῶν βλαβερόν· ἦ γάρ;","st":"379b"},{"sp":"N","t":"Οὔ μοι δοκεῖ.","st":"379b"},{"sp":"N","t":"Ἆρ’ οὖν ὃ μὴ βλαβερὸν βλάπτει;","st":"379b"},{"sp":"N","t":"Οὐδαμῶς.","st":"379b"},{"sp":"N","t":"Ὃ δὲ μὴ βλάπτει κακόν τι ποιεῖ;","st":"379b"},{"sp":"N","t":"Οὐδὲ τοῦτο.","st":"379b"},{"sp":"N","t":"Ὃ δέ γε μηδὲν κακὸν ποιεῖ οὐδ’ ἄν τινος εἴη κακοῦ αἴτιον;","st":"379b"},{"sp":"N","t":"Πῶς γάρ;","st":"379b"},{"sp":"N","t":"Τί δέ; ὠφέλιμον τὸ ἀγαθόν;","st":"379b"},{"sp":"N","t":"Ναί.","st":"379b"},{"sp":"N","t":"Αἴτιον ἄρα εὐπραγίας;","st":"379b"},{"sp":"N","t":"Ναί.","st":"379b"},{"sp":"N","t":"Οὐκ ἄρα πάντων γε αἴτιον τὸ ἀγαθόν, ἀλλὰ τῶν μὲν εὖ ἐχόντων αἴτιον, τῶν δὲ κακῶν ἀναίτιον.","st":"379b"},{"sp":"N","t":"Παντελῶς γ’, ἔφη.","st":"379c"},{"sp":"N","t":"Οὐδ’ ἄρα, ἦν δ’ ἐγώ, ὁ θεός, ἐπειδὴ ἀγαθός, πάντων ἂν εἴη αἴτιος, ὡς οἱ πολλοὶ λέγουσιν, ἀλλὰ ὀλίγων μὲν τοῖς ἀνθρώποις αἴτιος, πολλῶν δὲ ἀναίτιος· πολὺ γὰρ ἐλάττω τἀγαθὰ τῶν κακῶν ἡμῖν, καὶ τῶν μὲν ἀγαθῶν οὐδένα ἄλλον αἰτιατέον, τῶν δὲ κακῶν ἄλλ’ ἄττα δεῖ ζητεῖν τὰ αἴτια, ἀλλ’ οὐ τὸν θεόν.","st":"379c"},{"sp":"N","t":"Ἀληθέστατα, ἔφη, δοκεῖς μοι λέγειν.","st":"379c"},{"sp":"N","t":"Οὐκ ἄρα, ἦν δ’ ἐγώ, ἀποδεκτέον οὔτε Ὁμήρου οὔτ’ ἄλλου","st":"379c"},{"sp":"N","t":"ποιητοῦ ταύτην τὴν ἁμαρτίαν περὶ τοὺς θεοὺς ἀνοήτως ἁμαρτάνοντος καὶ λέγοντος —","st":"379d"},{"sp":"N","t":"ὡς δοιοί τε πίθοι κατακείαται ἐν Διὸς οὔδει","st":"379d"},{"sp":"N","t":"κηρῶν ἔμπλειοι, ὁ μὲν ἐσθλῶν, αὐτὰρ ὃ δειλῶν","st":"379d"},{"sp":"N","t":"καὶ ᾧ μὲν ἂν μείξας ὁ Ζεὺς δῷ ἀμφοτέρων,","st":"379d"},{"sp":"N","t":"ἄλλοτε μέν τε κακῷ ὅ γε κύρεται, ἄλλοτε δ’ ἐσθλῷ","st":"379d"},{"sp":"N","t":"ᾧ δ’ ἂν μή, ἀλλ’ ἄκρατα τὰ ἕτερα,","st":"379d"},{"sp":"N","t":"τὸν δὲ κακὴ βούβρωστις ἐπὶ χθόνα δῖαν ἐλαύνει","st":"379d"},{"sp":"N","t":"οὐδ’ ὡς ταμίας ἡμῖν Ζεὺς —","st":"379e"},{"sp":"N","t":"ἀγαθῶν τε κακῶν τε τέτυκται.","st":"379e"},{"sp":"N","t":"τὴν δὲ τῶν ὅρκων καὶ σπονδῶν σύγχυσιν, ἣν ὁ Πάνδαρος συνέχεεν, ἐάν τις φῇ δι’ Ἀθηνᾶς τε καὶ Διὸς γεγονέναι, οὐκ ἐπαινεσόμεθα, οὐδὲ θεῶν ἔριν τε καὶ κρίσιν","st":"379e"},{"sp":"N","t":"διὰ Θέμιτός τε καὶ Διός, οὐδ’ αὖ, ὡς Αἰσχύλος λέγει, ἐατέον ἀκούειν τοὺς νέους, ὅτι —","st":"380a"},{"sp":"N","t":"θεὸς μὲν αἰτίαν φύει βροτοῖς,","st":"380a"},{"sp":"N","t":"ὅταν κακῶσαι δῶμα παμπήδην θέλῃ.","st":"380a"},{"sp":"N","t":"ἀλλ’ ἐάν τις ποιῇ ἐν οἷς ταῦτα τὰ ἰαμβεῖα ἔνεστιν, τὰ τῆς Νιόβης πάθη, ἢ τὰ Πελοπιδῶν ἢ τὰ Τρωικὰ ἤ τι ἄλλο τῶν τοιούτων, ἢ οὐ θεοῦ ἔργα ἐατέον αὐτὰ λέγειν, ἢ εἰ θεοῦ, ἐξευρετέον αὐτοῖς σχεδὸν ὃν νῦν ἡμεῖς λόγον ζητοῦμεν, καὶ","st":"380a"},{"sp":"N","t":"λεκτέον ὡς ὁ μὲν θεὸς δίκαιά τε καὶ ἀγαθὰ ἠργάζετο, οἱ δὲ ὠνίναντο κολαζόμενοι· ὡς δὲ ἄθλιοι μὲν οἱ δίκην διδόντες, ἦν δὲ δὴ ὁ δρῶν ταῦτα θεός, οὐκ ἐατέον λέγειν τὸν ποιητήν. ἀλλ’ εἰ μὲν ὅτι ἐδεήθησαν κολάσεως λέγοιεν ὡς ἄθλιοι οἱ κακοί, διδόντες δὲ δίκην ὠφελοῦντο ὑπὸ τοῦ θεοῦ, ἐατέον· κακῶν δὲ αἴτιον φάναι θεόν τινι γίγνεσθαι ἀγαθὸν ὄντα, διαμαχετέον παντὶ τρόπῳ μήτε τινὰ λέγειν ταῦτα ἐν τῇ αὑτοῦ πόλει, εἰ μέλλει εὐνομήσεσθαι, μήτε τινὰ ἀκούειν,","st":"380b"},{"sp":"N","t":"μήτε νεώτερον μήτε πρεσβύτερον, μήτ’ ἐν μέτρῳ μήτε ἄνευ μέτρου μυθολογοῦντα, ὡς οὔτε ὅσια ἂν λεγόμενα εἰ λέγοιτο, οὔτε σύμφορα ἡμῖν οὔτε σύμφωνα αὐτὰ αὑτοῖς.","st":"380c"},{"sp":"N","t":"Σύμψηφός σοί εἰμι, ἔφη, τούτου τοῦ νόμου, καί μοι ἀρέσκει.","st":"380c"},{"sp":"N","t":"Οὗτος μὲν τοίνυν, ἦν δ’ ἐγώ, εἷς ἂν εἴη τῶν περὶ θεοὺς νόμων τε καὶ τύπων, ἐν ᾧ δεήσει τούς τε λέγοντας λέγειν καὶ τοὺς ποιοῦντας ποιεῖν, μὴ πάντων αἴτιον τὸν θεὸν ἀλλὰ τῶν ἀγαθῶν.","st":"380c"},{"sp":"N","t":"Καὶ μάλ’, ἔφη, ἀπόχρη.","st":"380c"},{"sp":"N","t":"Τί δὲ δὴ ὁ δεύτερος ὅδε; ἆρα γόητα τὸν θεὸν οἴει εἶναι καὶ οἷον ἐξ ἐπιβουλῆς φαντάζεσθαι ἄλλοτε ἐν ἄλλαις ἰδέαις τοτὲ μὲν αὐτὸν γιγνόμενον, [καὶ] ἀλλάττοντα τὸ αὑτοῦ εἶδος εἰς πολλὰς μορφάς, τοτὲ δὲ ἡμᾶς ἀπατῶντα καὶ ποιοῦντα περὶ αὑτοῦ τοιαῦτα δοκεῖν, ἢ ἁπλοῦν τε εἶναι καὶ πάντων ἥκιστα τῆς ἑαυτοῦ ἰδέας ἐκβαίνειν;","st":"380d"},{"sp":"N","t":"Οὐκ ἔχω, ἔφη, νῦν γε οὕτως εἰπεῖν.","st":"380d"},{"sp":"N","t":"Τί δὲ τόδε; οὐκ ἀνάγκη, εἴπερ τι ἐξίσταιτο τῆς αὑτοῦ","st":"380d"},{"sp":"N","t":"ἰδέας, ἢ αὐτὸ ὑφ’ ἑαυτοῦ μεθίστασθαι ἢ ὑπ’ ἄλλου;","st":"380e"},{"sp":"N","t":"Ἀνάγκη.","st":"380e"},{"sp":"N","t":"Οὐκοῦν ὑπὸ μὲν ἄλλου τὰ ἄριστα ἔχοντα ἥκιστα ἀλλοιοῦταί τε καὶ κινεῖται; οἷον σῶμα ὑπὸ σιτίων τε καὶ ποτῶν καὶ πόνων, καὶ πᾶν φυτὸν ὑπὸ εἱλήσεών τε καὶ ἀνέμων καὶ τῶν τοιούτων παθημάτων, οὐ τὸ ὑγιέστατον καὶ ἰσχυρότατον","st":"380e"},{"sp":"N","t":"ἥκιστα ἀλλοιοῦται;","st":"381a"},{"sp":"N","t":"Πῶς δ’ οὔ;","st":"381a"},{"sp":"N","t":"Ψυχὴν δὲ οὐ τὴν ἀνδρειοτάτην καὶ φρονιμωτάτην ἥκιστ’ ἄν τι ἔξωθεν πάθος ταράξειέν τε καὶ ἀλλοιώσειεν;","st":"381a"},{"sp":"N","t":"Ναί.","st":"381a"},{"sp":"N","t":"Καὶ μήν που καὶ τά γε σύνθετα πάντα σκεύη τε καὶ οἰκοδομήματα καὶ ἀμφιέσματα κατὰ τὸν αὐτὸν λόγον τὰ εὖ εἰργασμένα καὶ εὖ ἔχοντα ὑπὸ χρόνου τε καὶ τῶν ἄλλων παθημάτων ἥκιστα ἀλλοιοῦται.","st":"381a"},{"sp":"N","t":"Ἔστι δὴ ταῦτα.","st":"381a"},{"sp":"N","t":"Πᾶν δὴ τὸ καλῶς ἔχον ἢ φύσει ἢ τέχνῃ ἢ ἀμφοτέροις ἐλαχίστην μεταβολὴν ὑπ’ ἄλλου ἐνδέχεται.","st":"381b"},{"sp":"N","t":"Ἔοικεν.","st":"381b"},{"sp":"N","t":"Ἀλλὰ μὴν ὁ θεός γε καὶ τὰ τοῦ θεοῦ πάντῃ ἄριστα ἔχει.","st":"381b"},{"sp":"N","t":"Πῶς δ’ οὔ;","st":"381b"},{"sp":"N","t":"Ταύτῃ μὲν δὴ ἥκιστα ἂν πολλὰς μορφὰς ἴσχοι ὁ θεός.","st":"381b"},{"sp":"N","t":"Ἥκιστα δῆτα.","st":"381b"},{"sp":"N","t":"Ἀλλ’ ἆρα αὐτὸς αὑτὸν μεταβάλλοι ἂν καὶ ἀλλοιοῖ;","st":"381b"},{"sp":"N","t":"Δῆλον, ἔφη, ὅτι, εἴπερ ἀλλοιοῦται.","st":"381b"},{"sp":"N","t":"Πότερον οὖν ἐπὶ τὸ βέλτιόν τε καὶ κάλλιον μεταβάλλει ἑαυτὸν ἢ ἐπὶ τὸ χεῖρον καὶ τὸ αἴσχιον ἑαυτοῦ;","st":"381b"},{"sp":"N","t":"Ἀνάγκη, ἔφη, ἐπὶ τὸ χεῖρον, εἴπερ ἀλλοιοῦται· οὐ γάρ που ἐνδεᾶ γε φήσομεν τὸν θεὸν κάλλους ἢ ἀρετῆς εἶναι.","st":"381c"},{"sp":"N","t":"Ὀρθότατα, ἦν δ’ ἐγώ, λέγεις. καὶ οὕτως ἔχοντος δοκεῖ ἄν τίς σοι, ὦ Ἀδείμαντε, ἑκὼν αὑτὸν χείρω ποιεῖν ὁπῃοῦν ἢ θεῶν ἢ ἀνθρώπων;","st":"381c"},{"sp":"N","t":"Ἀδύνατον, ἔφη.","st":"381c"},{"sp":"N","t":"Ἀδύνατον ἄρα, ἔφην, καὶ θεῷ ἐθέλειν αὑτὸν ἀλλοιοῦν, ἀλλ’ ὡς ἔοικε, κάλλιστος καὶ ἄριστος ὢν εἰς τὸ δυνατὸν ἕκαστος αὐτῶν μένει ἀεὶ ἁπλῶς ἐν τῇ αὑτοῦ μορφῇ.","st":"381c"},{"sp":"N","t":"Ἅπασα, ἔφη, ἀνάγκη ἔμοιγε δοκεῖ.","st":"381c"},{"sp":"N","t":"Μηδεὶς ἄρα, ἦν δ’ ἐγώ, ὦ ἄριστε, λεγέτω ἡμῖν τῶν ποιητῶν, ὡς —","st":"381d"},{"sp":"N","t":"θεοὶ ξείνοισιν ἐοικότες ἀλλοδαποῖσι,","st":"381d"},{"sp":"N","t":"παντοῖοι τελέθοντες, ἐπιστρωφῶσι πόληας","st":"381d"},{"sp":"N","t":"μηδὲ Πρωτέως καὶ Θέτιδος καταψευδέσθω μηδείς, μηδ’ ἐν τραγῳδίαις μηδ’ ἐν τοῖς ἄλλοις ποιήμασιν εἰσαγέτω Ἥραν ἠλλοιωμένην, ὡς ἱέρειαν ἀγείρουσαν —","st":"381d"},{"sp":"N","t":"Ἰνάχου Ἀργείου ποταμοῦ παισὶν βιοδώροις","st":"381d"},{"sp":"N","t":"καὶ ἄλλα τοιαῦτα πολλὰ μὴ ἡμῖν ψευδέσθων. μηδ’ αὖ ὑπὸ τούτων ἀναπειθόμεναι αἱ μητέρες τὰ παιδία ἐκδειματούντων, λέγουσαι τοὺς μύθους κακῶς, ὡς ἄρα θεοί τινες περιέρχονται νύκτωρ πολλοῖς ξένοις καὶ παντοδαποῖς ἰνδαλλόμενοι, ἵνα μὴ ἅμα μὲν εἰς θεοὺς βλασφημῶσιν, ἅμα δὲ τοὺς παῖδας ἀπεργάζωνται δειλοτέρους. Μὴ γάρ, ἔφη.","st":"381e"},{"sp":"N","t":"Ἀλλ’ ἆρα, ἦν δ’ ἐγώ, αὐτοὶ μὲν οἱ θεοί εἰσιν οἷοι μὴ μεταβάλλειν, ἡμῖν δὲ ποιοῦσιν δοκεῖν σφᾶς παντοδαποὺς φαίνεσθαι, ἐξαπατῶντες καὶ γοητεύοντες;","st":"381e"},{"sp":"N","t":"Ἴσως, ἔφη.","st":"381e"},{"sp":"N","t":"Τί δέ; ἦν δ’ ἐγώ· ψεύδεσθαι θεὸς ἐθέλοι ἂν ἢ λόγῳ ἢ ἔργῳ φάντασμα προτείνων;","st":"382a"},{"sp":"N","t":"Οὐκ οἶδα, ἦ δ’ ὅς.","st":"382a"},{"sp":"N","t":"Οὐκ οἶσθα, ἦν δ’ ἐγώ, ὅτι τό γε ὡς ἀληθῶς ψεῦδος, εἰ οἷόν τε τοῦτο εἰπεῖν, πάντες θεοί τε καὶ ἄνθρωποι μισοῦσιν;","st":"382a"},{"sp":"N","t":"Πῶς, ἔφη, λέγεις;","st":"382a"},{"sp":"N","t":"Οὕτως, ἦν δ’ ἐγώ, ὅτι τῷ κυριωτάτῳ που ἑαυτῶν ψεύδεσθαι καὶ περὶ τὰ κυριώτατα οὐδεὶς ἑκὼν ἐθέλει, ἀλλὰ πάντων μάλιστα φοβεῖται ἐκεῖ αὐτὸ κεκτῆσθαι.","st":"382a"},{"sp":"N","t":"Οὐδὲ νῦν πω, ἦ δ’ ὅς, μανθάνω.","st":"382a"},{"sp":"N","t":"Οἴει γάρ τί με, ἔφην, σεμνὸν λέγειν· ἐγὼ δὲ λέγω ὅτι τῇ ψυχῇ περὶ τὰ ὄντα ψεύδεσθαί τε καὶ ἐψεῦσθαι καὶ ἀμαθῆ εἶναι καὶ ἐνταῦθα ἔχειν τε καὶ κεκτῆσθαι τὸ ψεῦδος πάντες ἥκιστα ἂν δέξαιντο, καὶ μισοῦσι μάλιστα αὐτὸ ἐν τῷ τοιούτῳ.","st":"382b"},{"sp":"N","t":"Πολύ γε, ἔφη.","st":"382b"},{"sp":"N","t":"Ἀλλὰ μὴν ὀρθότατά γ’ ἄν, ὃ νυνδὴ ἔλεγον, τοῦτο ὡς ἀληθῶς ψεῦδος καλοῖτο, ἡ ἐν τῇ ψυχῇ ἄγνοια ἡ τοῦ ἐψευσμένου· ἐπεὶ τό γε ἐν τοῖς λόγοις μίμημά τι τοῦ ἐν τῇ ψυχῇ ἐστὶν παθήματος καὶ ὕστερον γεγονὸς εἴδωλον, οὐ πάνυ","st":"382b"},{"sp":"N","t":"ἄκρατον ψεῦδος. ἢ οὐχ οὕτω;","st":"382c"},{"sp":"N","t":"Πάνυ μὲν οὖν.","st":"382c"},{"sp":"N","t":"Τὸ μὲν δὴ τῷ ὄντι ψεῦδος οὐ μόνον ὑπὸ θεῶν ἀλλὰ καὶ ὑπ’ ἀνθρώπων μισεῖται.","st":"382c"},{"sp":"N","t":"Δοκεῖ μοι.","st":"382c"},{"sp":"N","t":"Τί δὲ δὴ τὸ ἐν τοῖς λόγοις [ψεῦδος]; πότε καὶ τῷ χρήσιμον, ὥστε μὴ ἄξιον εἶναι μίσους; ἆρ’ οὐ πρός τε τοὺς πολεμίους καὶ τῶν καλουμένων φίλων, ὅταν διὰ μανίαν ἤ τινα ἄνοιαν κακόν τι ἐπιχειρῶσιν πράττειν, τότε ἀποτροπῆς ἕνεκα ὡς φάρμακον χρήσιμον γίγνεται; καὶ ἐν αἷς νυνδὴ","st":"382c"},{"sp":"N","t":"ἐλέγομεν ταῖς μυθολογίαις, διὰ τὸ μὴ εἰδέναι ὅπῃ τἀληθὲς ἔχει περὶ τῶν παλαιῶν, ἀφομοιοῦντες τῷ ἀληθεῖ τὸ ψεῦδος ὅτι μάλιστα, οὕτω χρήσιμον ποιοῦμεν;","st":"382d"},{"sp":"N","t":"Καὶ μάλα, ἦ δ’ ὅς, οὕτως ἔχει.","st":"382d"},{"sp":"N","t":"Κατὰ τί δὴ οὖν τούτων τῷ θεῷ τὸ ψεῦδος χρήσιμον; πότερον διὰ τὸ μὴ εἰδέναι τὰ παλαιὰ ἀφομοιῶν ἂν ψεύδοιτο;","st":"382d"},{"sp":"N","t":"Γελοῖον μεντἂν εἴη, ἔφη.","st":"382d"},{"sp":"N","t":"Ποιητὴς μὲν ἄρα ψευδὴς ἐν θεῷ οὐκ ἔνι.","st":"382d"},{"sp":"N","t":"Οὔ μοι δοκεῖ.","st":"382d"},{"sp":"N","t":"Ἀλλὰ δεδιὼς τοὺς ἐχθροὺς ψεύδοιτο;","st":"382d"},{"sp":"N","t":"Πολλοῦ γε δεῖ.","st":"382e"},{"sp":"N","t":"Ἀλλὰ δι’ οἰκείων ἄνοιαν ἢ μανίαν;","st":"382e"},{"sp":"N","t":"Ἀλλ’ οὐδείς, ἔφη, τῶν ἀνοήτων καὶ μαινομένων θεοφιλής.","st":"382e"},{"sp":"N","t":"Οὐκ ἄρα ἔστιν οὗ ἕνεκα ἂν θεὸς ψεύδοιτο.","st":"382e"},{"sp":"N","t":"Οὐκ ἔστιν.","st":"382e"},{"sp":"N","t":"Πάντῃ ἄρα ἀψευδὲς τὸ δαιμόνιόν τε καὶ τὸ θεῖον.","st":"382e"},{"sp":"N","t":"Παντάπασι μὲν οὖν, ἔφη.","st":"382e"},{"sp":"N","t":"Κομιδῇ ἄρα ὁ θεὸς ἁπλοῦν καὶ ἀληθὲς ἔν τε ἔργῳ καὶ λόγῳ, καὶ οὔτε αὐτὸς μεθίσταται οὔτε ἄλλους ἐξαπατᾷ, οὔτε κατὰ φαντασίας οὔτε κατὰ λόγους οὔτε κατὰ σημείων πομπάς, οὔθ’ ὕπαρ οὐδ’ ὄναρ.","st":"382e"},{"sp":"N","t":"Οὕτως, ἔφη, ἔμοιγε καὶ αὐτῷ φαίνεται σοῦ λέγοντος.","st":"383a"},{"sp":"N","t":"Συγχωρεῖς ἄρα, ἔφην, τοῦτον δεύτερον τύπον εἶναι ἐν ᾧ δεῖ περὶ θεῶν καὶ λέγειν καὶ ποιεῖν, ὡς μήτε αὐτοὺς γόητας ὄντας τῷ μεταβάλλειν ἑαυτοὺς μήτε ἡμᾶς ψεύδεσι παράγειν ἐν λόγῳ ἢ ἐν ἔργῳ;","st":"383a"},{"sp":"N","t":"Συγχωρῶ.","st":"383a"},{"sp":"N","t":"Πολλὰ ἄρα Ὁμήρου ἐπαινοῦντες, ἀλλὰ τοῦτο οὐκ ἐπαινεσόμεθα, τὴν τοῦ ἐνυπνίου πομπὴν ὑπὸ Διὸς τῷ Ἀγαμέμνονι· οὐδὲ Αἰσχύλου, ὅταν φῇ ἡ Θέτις τὸν Ἀπόλλω ἐν τοῖς αὑτῆς","st":"383a"},{"sp":"N","t":"γάμοις ᾄδοντα ἐνδατεῖσθαι τὰς ἑὰς εὐπαιδίας —","st":"383b"},{"sp":"N","t":"νόσων τ’ ἀπείρους καὶ μακραίωνας βίους,","st":"383b"},{"sp":"N","t":"ξύμπαντά τ’ εἰπὼν θεοφιλεῖς ἐμὰς τύχας","st":"383b"},{"sp":"N","t":"παιᾶν’ ἐπηυφήμησεν, εὐθυμῶν ἐμέ.","st":"383b"},{"sp":"N","t":"κἀγὼ τὸ Φοίβου θεῖον ἀψευδὲς στόμα","st":"383b"},{"sp":"N","t":"ἤλπιζον εἶναι, μαντικῇ βρύον τέχνῃ","st":"383b"},{"sp":"N","t":"ὁ δ’, αὐτὸς ὑμνῶν, αὐτὸς ἐν θοίνῃ παρών,","st":"383b"},{"sp":"N","t":"αὐτὸς τάδ’ εἰπών, αὐτός ἐστιν ὁ κτανὼν","st":"383b"},{"sp":"N","t":"τὸν παῖδα τὸν ἐμόν —","st":"383b"},{"sp":"N","t":"ὅταν τις τοιαῦτα λέγῃ περὶ θεῶν, χαλεπανοῦμέν τε καὶ χορὸν οὐ δώσομεν, οὐδὲ τοὺς διδασκάλους ἐάσομεν ἐπὶ παιδείᾳ χρῆσθαι τῶν νέων, εἰ μέλλουσιν ἡμῖν οἱ φύλακες θεοσεβεῖς τε καὶ θεῖοι γίγνεσθαι, καθ’ ὅσον ἀνθρώπῳ ἐπὶ πλεῖστον οἷόν τε.","st":"383c"},{"sp":"N","t":"Παντάπασιν, ἔφη, ἔγωγε τοὺς τύπους τούτους συγχωρῶ, καὶ ὡς νόμοις ἂν χρῴμην.","st":"383c"},{"sp":"N","t":"ΣΩΚΡΆΤΗς, ΑΔΕΊΜΑΝΤΟς","st":"383c"},{"sp":"N","t":"Τὰ μὲν δὴ περὶ θεούς, ἦν δ’ ἐγώ, τοιαῦτ’ ἄττα, ὡς ἔοικεν, ἀκουστέον τε καὶ οὐκ ἀκουστέον εὐθὺς ἐκ παίδων τοῖς θεούς τε τιμήσουσιν καὶ γονέας τήν τε ἀλλήλων φιλίαν μὴ περὶ σμικροῦ ποιησομένοις.","st":"386a"},{"sp":"N","t":"Καὶ οἶμαί γ’, ἔφη, ὀρθῶς ἡμῖν φαίνεσθαι.","st":"386a"},{"sp":"N","t":"Τί δὲ δὴ εἰ μέλλουσιν εἶναι ἀνδρεῖοι; ἆρα οὐ ταῦτά τε λεκτέον καὶ οἷα αὐτοὺς ποιῆσαι ἥκιστα τὸν θάνατον δεδιέναι;","st":"386a"},{"sp":"N","t":"ἢ ἡγῇ τινά ποτ’ ἂν γενέσθαι ἀνδρεῖον ἔχοντα ἐν αὑτῷ τοῦτο τὸ δεῖμα;","st":"386b"},{"sp":"N","t":"Μὰ Δία, ἦ δ’ ὅς, οὐκ ἔγωγε.","st":"386b"},{"sp":"N","t":"Τί δέ; τἀν Ἅιδου ἡγούμενον εἶναί τε καὶ δεινὰ εἶναι οἴει τινὰ θανάτου ἀδεῆ ἔσεσθαι καὶ ἐν ταῖς μάχαις αἱρήσεσθαι πρὸ ἥττης τε καὶ δουλείας θάνατον;","st":"386b"},{"sp":"N","t":"Οὐδαμῶς.","st":"386b"},{"sp":"N","t":"Δεῖ δή, ὡς ἔοικεν, ἡμᾶς ἐπιστατεῖν καὶ περὶ τούτων τῶν μύθων τοῖς ἐπιχειροῦσιν λέγειν, καὶ δεῖσθαι μὴ λοιδορεῖν ἁπλῶς οὕτως τὰ ἐν Ἅιδου ἀλλὰ μᾶλλον ἐπαινεῖν, ὡς οὔτε ἀληθῆ","st":"386b"},{"sp":"N","t":"ἂν λέγοντας οὔτε ὠφέλιμα τοῖς μέλλουσιν μαχίμοις ἔσεσθαι.","st":"386c"},{"sp":"N","t":"Δεῖ μέντοι, ἔφη.","st":"386c"},{"sp":"N","t":"Ἐξαλείψομεν ἄρα, ἦν δ’ ἐγώ, ἀπὸ τοῦδε τοῦ ἔπους ἀρξάμενοι πάντα τὰ τοιαῦτα —","st":"386c"},{"sp":"N","t":"βουλοίμην κ’ ἐπάρουρος ἐὼν θητευέμεν ἄλλῳ","st":"386c"},{"sp":"N","t":"ἀνδρὶ παρ’ ἀκλήρῳ, ᾧ μὴ βίοτος πολὺς εἴη","st":"386c"},{"sp":"N","t":"ἢ πᾶσιν νεκύεσσι καταφθιμένοισιν ἀνάσσειν","st":"386c"},{"sp":"N","t":"καὶ τὸ —","st":"386c"},{"sp":"N","t":"οἰκία δὲ θνητοῖσι καὶ ἀθανάτοισι φανείη","st":"386d"},{"sp":"N","t":"σμερδαλέ’, εὐρώεντα, τά τε στυγέουσι θεοί περ","st":"386d"},{"sp":"N","t":"καὶ —","st":"386d"},{"sp":"N","t":"ὢ πόποι, ἦ ῥά τις ἔστι καὶ εἰν Ἀΐδαο δόμοισιν","st":"386d"},{"sp":"N","t":"ψυχὴ καὶ εἴδωλον, ἀτὰρ φρένες οὐκ ἔνι πάμπαν","st":"386d"},{"sp":"N","t":"καὶ τὸ —","st":"386d"},{"sp":"N","t":"οἴῳ πεπνῦσθαι, ταὶ δὲ σκιαὶ ἀΐσσουσι","st":"386d"},{"sp":"N","t":"καὶ —","st":"386d"},{"sp":"N","t":"ψυχὴ δ’ ἐκ ῥεθέων πταμένη Ἄϊδόσδε βεβήκει,","st":"386d"},{"sp":"N","t":"ὃν πότμον γοόωσα, λιποῦσ’ ἀνδροτῆτα καὶ ἥβην","st":"386d"},{"sp":"N","t":"καὶ τὸ ψυχὴ δὲ κατὰ χθονός, ἠΰτε καπνός,","st":"387a"},{"sp":"N","t":"ᾤχετο τετριγυῖα","st":"387a"},{"sp":"N","t":"καὶ —","st":"387a"},{"sp":"N","t":"ὡς δ’ ὅτε νυκτερίδες μυχῷ ἄντρου θεσπεσίοιο","st":"387a"},{"sp":"N","t":"τρίζουσαι ποτέονται, ἐπεί κέ τις ἀποπέσῃσιν","st":"387a"},{"sp":"N","t":"ὁρμαθοῦ ἐκ πέτρης, ἀνά τ’ ἀλλήλῃσιν ἔχονται,","st":"387a"},{"sp":"N","t":"ὣς αἳ τετριγυῖαι ἅμ’ ᾔεσαν.","st":"387a"},{"sp":"N","t":"ταῦτα καὶ τὰ τοιαῦτα πάντα παραιτησόμεθα Ὅμηρόν τε καὶ τοὺς ἄλλους ποιητὰς μὴ χαλεπαίνειν ἂν διαγράφωμεν, οὐχ ὡς οὐ ποιητικὰ καὶ ἡδέα τοῖς πολλοῖς ἀκούειν, ἀλλ’ ὅσῳ ποιητικώτερα, τοσούτῳ ἧττον ἀκουστέον παισὶ καὶ ἀνδράσιν οὓς δεῖ ἐλευθέρους εἶναι, δουλείαν θανάτου μᾶλλον πεφοβημένους.","st":"387b"},{"sp":"N","t":"Παντάπασι μὲν οὖν.","st":"387b"},{"sp":"N","t":"Οὐκοῦν ἔτι καὶ τὰ περὶ ταῦτα ὀνόματα πάντα τὰ δεινά τε καὶ φοβερὰ ἀποβλητέα, Κωκυτούς τε καὶ Στύγας καὶ","st":"387b"},{"sp":"N","t":"ἐνέρους καὶ ἀλίβαντας, καὶ ἄλλα ὅσα τούτου τοῦ τύπου ὀνομαζόμενα φρίττειν δὴ ποιεῖ ὡς οἴεται† πάντας τοὺς ἀκούοντας. καὶ ἴσως εὖ ἔχει πρὸς ἄλλο τι· ἡμεῖς δὲ ὑπὲρ τῶν φυλάκων φοβούμεθα μὴ ἐκ τῆς τοιαύτης φρίκης θερμότεροι καὶ μαλακώτεροι τοῦ δέοντος γένωνται ἡμῖν.","st":"387c"},{"sp":"N","t":"Καὶ ὀρθῶς γ’, ἔφη, φοβούμεθα.","st":"387c"},{"sp":"N","t":"Ἀφαιρετέα ἄρα;","st":"387c"},{"sp":"N","t":"Ναί.","st":"387c"},{"sp":"N","t":"Τὸν δὲ ἐναντίον τύπον τούτοις λεκτέον τε καὶ ποιητέον;","st":"387c"},{"sp":"N","t":"Δῆλα δή.","st":"387c"},{"sp":"N","t":"Καὶ τοὺς ὀδυρμοὺς ἄρα ἐξαιρήσομεν καὶ τοὺς οἴκτους τοὺς τῶν ἐλλογίμων ἀνδρῶν;","st":"387d"},{"sp":"N","t":"Ἀνάγκη, ἔφη, εἴπερ καὶ τὰ πρότερα.","st":"387d"},{"sp":"N","t":"Σκόπει δή, ἦν δ’ ἐγώ, εἰ ὀρθῶς ἐξαιρήσομεν ἢ οὔ. φαμὲν δὲ δὴ ὅτι ὁ ἐπιεικὴς ἀνὴρ τῷ ἐπιεικεῖ, οὗπερ καὶ ἑταῖρός ἐστιν, τὸ τεθνάναι οὐ δεινὸν ἡγήσεται. Φαμὲν γάρ.","st":"387d"},{"sp":"N","t":"Οὐκ ἄρα ὑπέρ γ’ ἐκείνου ὡς δεινόν τι πεπονθότος ὀδύροιτ’ ἄν.","st":"387d"},{"sp":"N","t":"Οὐ δῆτα.","st":"387d"},{"sp":"N","t":"Ἀλλὰ μὴν καὶ τόδε λέγομεν, ὡς ὁ τοιοῦτος μάλιστα αὐτὸς αὑτῷ αὐτάρκης πρὸς τὸ εὖ ζῆν καὶ διαφερόντως τῶν","st":"387d"},{"sp":"N","t":"ἄλλων ἥκιστα ἑτέρου προσδεῖται.","st":"387e"},{"sp":"N","t":"Ἀληθῆ, ἔφη.","st":"387e"},{"sp":"N","t":"Ἥκιστα ἄρ’ αὐτῷ δεινὸν στερηθῆναι ὑέος ἢ ἀδελφοῦ ἢ χρημάτων ἢ ἄλλου του τῶν τοιούτων.","st":"387e"},{"sp":"N","t":"Ἥκιστα μέντοι.","st":"387e"},{"sp":"N","t":"Ἥκιστ’ ἄρα καὶ ὀδύρεσθαι, φέρειν δὲ ὡς πρᾳότατα, ὅταν τις αὐτὸν τοιαύτη συμφορὰ καταλάβῃ.","st":"387e"},{"sp":"N","t":"Πολύ γε.","st":"387e"},{"sp":"N","t":"Ὀρθῶς ἄρ’ ἂν ἐξαιροῖμεν τοὺς θρήνους τῶν ὀνομαστῶν ἀνδρῶν, γυναιξὶ δὲ ἀποδιδοῖμεν, καὶ οὐδὲ ταύταις σπουδαίαις,","st":"387e"},{"sp":"N","t":"καὶ ὅσοι κακοὶ τῶν ἀνδρῶν, ἵνα ἡμῖν δυσχεραίνωσιν ὅμοια τούτοις ποιεῖν οὓς δή φαμεν ἐπὶ φυλακῇ τῆς χώρας τρέφειν.","st":"388a"},{"sp":"N","t":"Ὀρθῶς, ἔφη.","st":"388a"},{"sp":"N","t":"Πάλιν δὴ Ὁμήρου τε δεησόμεθα καὶ τῶν ἄλλων ποιητῶν μὴ ποιεῖν Ἀχιλλέα θεᾶς παῖδα —","st":"388a"},{"sp":"N","t":"ἄλλοτ’ ἐπὶ πλευρᾶς κατακείμενον, ἄλλοτε δ’ αὖτε","st":"388a"},{"sp":"N","t":"ὕπτιον, ἄλλοτε δὲ πρηνῆ,","st":"388a"},{"sp":"N","t":"τοτὲ δ’ ὀρθὸν ἀναστάντα πλωΐζοντ’ ἀλύοντ’ ἐπὶ","st":"388a"},{"sp":"N","t":"θῖν’ ἁλὸς ἀτρυγέτοιο, μηδὲ ἀμφοτέραισιν χερσὶν ἑλόντα κόνιν αἰθαλόεσσαν χευάμενον κὰκ κεφαλῆς, μηδὲ ἄλλα κλαίοντά τε καὶ ὀδυρόμενον ὅσα καὶ οἷα ἐκεῖνος ἐποίησε, μηδὲ Πρίαμον ἐγγὺς θεῶν γεγονότα λιτανεύοντά τε καὶ κυλινδόμενον κατὰ κόπρον, ἐξονομακλήδην ὀνομάζοντ’ ἄνδρα ἕκαστον.","st":"388b"},{"sp":"N","t":"πολὺ δ’ ἔτι τούτων μᾶλλον δεησόμεθα μήτοι θεούς γε ποιεῖν ὀδυρομένους καὶ λέγοντας —","st":"388b"},{"sp":"N","t":"ὤμοι ἐγὼ δειλή, ὤμοι δυσαριστοτόκεια","st":"388c"},{"sp":"N","t":"εἰ δ’ οὖν θεούς, μήτοι τόν γε μέγιστον τῶν θεῶν τολμῆσαι οὕτως ἀνομοίως μιμήσασθαι, ὥστε","st":"388c"},{"sp":"N","t":"ὢ πόποι, φάναι, ἦ φίλον ἄνδρα διωκόμενον περὶ ἄστυ","st":"388c"},{"sp":"N","t":"ὀφθαλμοῖσιν ὁρῶμαι, ἐμὸν δ’ ὀλοφύρεται ἦτορ","st":"388c"},{"sp":"N","t":"καὶ —","st":"388c"},{"sp":"N","t":"αἲ αἲ ἐγών, ὅ τέ μοι Σαρπηδόνα φίλτατον ἀνδρῶν","st":"388c"},{"sp":"N","t":"μοῖρ’ ὑπὸ Πατρόκλοιο Μενοιτιάδαο δαμῆναι.","st":"388d"},{"sp":"N","t":"εἰ γάρ, ὦ φίλε Ἀδείμαντε, τὰ τοιαῦτα ἡμῖν οἱ νέοι σπουδῇ ἀκούοιεν καὶ μὴ καταγελῷεν ὡς ἀναξίως λεγομένων, σχολῇ ἂν ἑαυτόν γέ τις ἄνθρωπον ὄντα ἀνάξιον ἡγήσαιτο τούτων καὶ ἐπιπλήξειεν, εἰ καὶ ἐπίοι αὐτῷ τι τοιοῦτον ἢ λέγειν ἢ ποιεῖν, ἀλλ’ οὐδὲν αἰσχυνόμενος οὐδὲ καρτερῶν πολλοὺς ἐπὶ σμικροῖσιν παθήμασιν θρήνους ἂν ᾄδοι καὶ ὀδυρμούς.","st":"388d"},{"sp":"N","t":"Ἀληθέστατα, ἔφη, λέγεις.","st":"388e"},{"sp":"N","t":"Δεῖ δέ γε οὔχ, ὡς ἄρτι ἡμῖν ὁ λόγος ἐσήμαινεν· ᾧ πειστέον, ἕως ἄν τις ἡμᾶς ἄλλῳ καλλίονι πείσῃ.","st":"388e"},{"sp":"N","t":"Οὐ γὰρ οὖν δεῖ.","st":"388e"},{"sp":"N","t":"Ἀλλὰ μὴν οὐδὲ φιλογέλωτάς γε δεῖ εἶναι. σχεδὸν γὰρ ὅταν τις ἐφιῇ ἰσχυρῷ γέλωτι, ἰσχυρὰν καὶ μεταβολὴν ζητεῖ τὸ τοιοῦτον.","st":"388e"},{"sp":"N","t":"Δοκεῖ μοι, ἔφη.","st":"388e"},{"sp":"N","t":"Οὔτε ἄρα ἀνθρώπους ἀξίους λόγου κρατουμένους ὑπὸ","st":"388e"},{"sp":"N","t":"γέλωτος ἄν τις ποιῇ, ἀποδεκτέον, πολὺ δὲ ἧττον, ἐὰν θεούς.","st":"389a"},{"sp":"N","t":"Πολὺ μέντοι, ἦ δ’ ὅς.","st":"389a"},{"sp":"N","t":"Οὐκοῦν Ὁμήρου οὐδὲ τὰ τοιαῦτα ἀποδεξόμεθα περὶ θεῶν —","st":"389a"},{"sp":"N","t":"ἄσβεστος δ’ ἄρ’ ἐνῶρτο γέλως μακάρεσσι θεοῖσιν,","st":"389a"},{"sp":"N","t":"ὡς ἴδον Ἥφαιστον διὰ δώματα ποιπνύοντα","st":"389a"},{"sp":"N","t":"οὐκ ἀποδεκτέον κατὰ τὸν σὸν λόγον.","st":"389a"},{"sp":"N","t":"Εἰ σύ, ἔφη, βούλει ἐμὸν τιθέναι· οὐ γὰρ οὖν δὴ","st":"389a"},{"sp":"N","t":"ἀποδεκτέον.","st":"389b"},{"sp":"N","t":"Ἀλλὰ μὴν καὶ ἀλήθειάν γε περὶ πολλοῦ ποιητέον. εἰ γὰρ ὀρθῶς ἐλέγομεν ἄρτι, καὶ τῷ ὄντι θεοῖσι μὲν ἄχρηστον ψεῦδος, ἀνθρώποις δὲ χρήσιμον ὡς ἐν φαρμάκου εἴδει, δῆλον ὅτι τό γε τοιοῦτον ἰατροῖς δοτέον, ἰδιώταις δὲ οὐχ ἁπτέον.","st":"389b"},{"sp":"N","t":"Δῆλον, ἔφη.","st":"389b"},{"sp":"N","t":"Τοῖς ἄρχουσιν δὴ τῆς πόλεως, εἴπερ τισὶν ἄλλοις, προσήκει ψεύδεσθαι ἢ πολεμίων ἢ πολιτῶν ἕνεκα ἐπ’ ὠφελίᾳ τῆς πόλεως, τοῖς δὲ ἄλλοις πᾶσιν οὐχ ἁπτέον τοῦ τοιούτου","st":"389b"},{"sp":"N","t":"ἀλλὰ πρός γε δὴ τοὺς τοιούτους ἄρχοντας ἰδιώτῃ ψεύσασθαι ταὐτὸν καὶ μεῖζον ἁμάρτημα φήσομεν ἢ κάμνοντι πρὸς ἰατρὸν ἢ ἀσκοῦντι πρὸς παιδοτρίβην περὶ τῶν τοῦ αὑτοῦ σώματος παθημάτων μὴ τἀληθῆ λέγειν, ἢ πρὸς κυβερνήτην περὶ τῆς νεώς τε καὶ τῶν ναυτῶν μὴ τὰ ὄντα λέγοντι ὅπως ἢ αὐτὸς ἤ τις τῶν συνναυτῶν πράξεως ἔχει.","st":"389c"},{"sp":"N","t":"Ἀληθέστατα, ἔφη.","st":"389c"},{"sp":"N","t":"Ἂν ἄρ’ ἄλλον τινὰ λαμβάνῃ ψευδόμενον ἐν τῇ πόλει τῶν οἳ δημιοεργοὶ ἔασι, μάντιν ἢ ἰητῆρα κακῶν ἢ τέκτονα δούρων,","st":"389d"},{"sp":"N","t":"κολάσει ὡς ἐπιτήδευμα εἰσάγοντα πόλεως ὥσπερ νεὼς ἀνατρεπτικόν τε καὶ ὀλέθριον.","st":"389d"},{"sp":"N","t":"Ἐάνπερ, ἦ δ’ ὅς, ἐπί γε λόγῳ ἔργα τελῆται.","st":"389d"},{"sp":"N","t":"Τί δέ; σωφροσύνης ἆρα οὐ δεήσει ἡμῖν τοῖς νεανίαις;","st":"389d"},{"sp":"N","t":"Πῶς δ’ οὔ;","st":"389d"},{"sp":"N","t":"Σωφροσύνης δὲ ὡς πλήθει οὐ τὰ τοιάδε μέγιστα, ἀρχόντων","st":"389d"},{"sp":"N","t":"μὲν ὑπηκόους εἶναι, αὐτοὺς δὲ ἄρχοντας τῶν περὶ πότους καὶ ἀφροδίσια καὶ περὶ ἐδωδὰς ἡδονῶν; Ἔμοιγε δοκεῖ.","st":"389e"},{"sp":"N","t":"Τὰ δὴ τοιάδε φήσομεν οἶμαι καλῶς λέγεσθαι, οἷα καὶ Ὁμήρῳ Διομήδης λέγει —","st":"389e"},{"sp":"N","t":"τέττα, σιωπῇ ἧσο, ἐμῷ δ’ ἐπιπείθεο μύθῳ,","st":"389e"},{"sp":"N","t":"καὶ τὰ τούτων ἐχόμενα, τὰ ἴσαν μένεα πνείοντες Ἀχαιοί,","st":"389e"},{"sp":"N","t":"σιγῇ δειδιότες σημάντορας,","st":"389e"},{"sp":"N","t":"καὶ ὅσα ἄλλα τοιαῦτα.","st":"389e"},{"sp":"N","t":"Καλῶς.","st":"389e"},{"sp":"N","t":"Τί δέ; τὰ τοιάδε —","st":"389e"},{"sp":"N","t":"οἰνοβαρές, κυνὸς ὄμματ’ ἔχων, κραδίην δ’ ἐλάφοιο","st":"389e"},{"sp":"N","t":"καὶ τὰ τούτων ἑξῆς ἆρα καλῶς, καὶ ὅσα ἄλλα τις ἐν λόγῳ ἢ ἐν ποιήσει εἴρηκε νεανιεύματα ἰδιωτῶν εἰς ἄρχοντας;","st":"390a"},{"sp":"N","t":"Οὐ καλῶς.","st":"390a"},{"sp":"N","t":"Οὐ γὰρ οἶμαι εἴς γε σωφροσύνην νέοις ἐπιτήδεια ἀκούειν· εἰ δέ τινα ἄλλην ἡδονὴν παρέχεται, θαυμαστὸν οὐδέν. ἢ πῶς σοι φαίνεται;","st":"390a"},{"sp":"N","t":"Οὕτως, ἔφη.","st":"390a"},{"sp":"N","t":"Τί δέ; ποιεῖν ἄνδρα τὸν σοφώτατον λέγοντα ὡς δοκεῖ αὐτῷ κάλλιστον εἶναι πάντων, ὅταν παρὰ πλεῖαι ὦσι τράπεζαι","st":"390a"},{"sp":"N","t":"σίτου καὶ κρειῶν, μέθυ δ’ ἐκ κρητῆρος ἀφύσσων","st":"390b"},{"sp":"N","t":"οἰνοχόος φορέῃσι καὶ ἐγχείῃ δεπάεσσι,","st":"390b"},{"sp":"N","t":"δοκεῖ σοι ἐπιτήδειον εἶναι πρὸς ἐγκράτειαν ἑαυτοῦ ἀκούειν νέῳ; ἢ τὸ λιμῷ δ’ οἴκτιστον θανέειν καὶ πότμον ἐπισπεῖν;","st":"390b"},{"sp":"N","t":"ἢ Δία, καθευδόντων τῶν ἄλλων θεῶν τε καὶ ἀνθρώπων ὡς, μόνος ἐγρηγορὼς ἃ ἐβουλεύσατο, τούτων πάντων ῥᾳδίως","st":"390b"},{"sp":"N","t":"ἐπιλανθανόμενον διὰ τὴν τῶν ἀφροδισίων ἐπιθυμίαν, καὶ οὕτως ἐκπλαγέντα ἰδόντα τὴν Ἥραν, ὥστε μηδ’ εἰς τὸ δωμάτιον ἐθέλειν ἐλθεῖν, ἀλλ’ αὐτοῦ βουλόμενον χαμαὶ συγγίγνεσθαι, λέγοντα ὡς οὕτως ὑπὸ ἐπιθυμίας ἔχεται, ὡς οὐδ’ ὅτε τὸ πρῶτον ἐφοίτων πρὸς ἀλλήλους φίλους λήθοντε τοκῆας· οὐδὲ Ἄρεώς τε καὶ Ἀφροδίτης ὑπὸ Ἡφαίστου δεσμὸν δι’ ἕτερα τοιαῦτα. Οὐ μὰ τὸν Δία, ἦ δ’ ὅς, οὔ μοι φαίνεται ἐπιτήδειον.","st":"390c"},{"sp":"N","t":"Ἀλλ’ εἴ πού τινες, ἦν δ’ ἐγώ, καρτερίαι πρὸς ἅπαντα καὶ λέγονται καὶ πράττονται ὑπὸ ἐλλογίμων ἀνδρῶν, θεατέον τε καὶ ἀκουστέον, οἷον καὶ τὸ —","st":"390d"},{"sp":"N","t":"στῆθος δὲ πλήξας κραδίην ἠνίπαπε μύθῳ","st":"390d"},{"sp":"N","t":"τέτλαθι δή, κραδίη· καὶ κύντερον ἄλλο ποτ’ ἔτλης.","st":"390d"},{"sp":"N","t":"Παντάπασι μὲν οὖν, ἔφη.","st":"390d"},{"sp":"N","t":"Οὐ μὲν δὴ δωροδόκους γε ἐατέον εἶναι τοὺς ἄνδρας οὐδὲ","st":"390d"},{"sp":"N","t":"φιλοχρημάτους.","st":"390d"},{"sp":"N","t":"Οὐδαμῶς.","st":"390e"},{"sp":"N","t":"Οὐδ’ ᾀστέον αὐτοῖς ὅτι δῶρα θεοὺς πείθει, δῶρ’ αἰδοίους βασιλῆας","st":"390e"},{"sp":"N","t":"οὐδὲ τὸν τοῦ Ἀχιλλέως παιδαγωγὸν Φοίνικα ἐπαινετέον ὡς μετρίως ἔλεγε συμβουλεύων αὐτῷ δῶρα μὲν λαβόντι ἐπαμύνειν τοῖς Ἀχαιοῖς, ἄνευ δὲ δώρων μὴ ἀπαλλάττεσθαι τῆς μήνιος. οὐδ’ αὐτὸν τὸν Ἀχιλλέα ἀξιώσομεν οὐδ’ ὁμολογήσομεν οὕτω φιλοχρήματον εἶναι, ὥστε παρὰ τοῦ Ἀγαμέμνονος δῶρα λαβεῖν, καὶ τιμὴν αὖ λαβόντα νεκροῦ","st":"390e"},{"sp":"N","t":"ἀπολύειν, ἄλλως δὲ μὴ ‘θέλειν.","st":"391a"},{"sp":"N","t":"Οὔκουν δίκαιόν γε, ἔφη, ἐπαινεῖν τὰ τοιαῦτα.","st":"391a"},{"sp":"N","t":"Ὀκνῶ δέ γε, ἦν δ’ ἐγώ, δι’ Ὅμηρον λέγειν ὅτι οὐδ’ ὅσιον ταῦτά γε κατὰ Ἀχιλλέως φάναι καὶ ἄλλων λεγόντων πείθεσθαι, καὶ αὖ ὡς πρὸς τὸν Ἀπόλλω εἶπεν —","st":"391a"},{"sp":"N","t":"ἔβλαψάς μ’ ἑκάεργε, θεῶν ὀλοώτατε πάντων","st":"391a"},{"sp":"N","t":"ἦ σ’ ἂν τισαίμην, εἴ μοι δύναμίς γε παρείη","st":"391a"},{"sp":"N","t":"καὶ ὡς πρὸς τὸν ποταμόν, θεὸν ὄντα, ἀπειθῶς εἶχεν καὶ μάχεσθαι ἕτοιμος ἦν, καὶ αὖ τὰς τοῦ ἑτέρου ποταμοῦ Σπερχειοῦ ἱερὰς τρίχας Πατρόκλῳ ἥρωϊ, ἔφη, κόμην ὀπάσαιμι φέρεσθαι, νεκρῷ ὄντι, καὶ ὡς ἔδρασεν τοῦτο, οὐ πειστέον· τάς τε αὖ Ἕκτορος ἕλξεις περὶ τὸ σῆμα τὸ Πατρόκλου καὶ τὰς τῶν ζωγρηθέντων σφαγὰς εἰς τὴν πυράν, σύμπαντα ταῦτα οὐ φήσομεν ἀληθῆ εἰρῆσθαι, οὐδ’ ἐάσομεν","st":"391b"},{"sp":"N","t":"πείθεσθαι τοὺς ἡμετέρους ὡς Ἀχιλλεύς, θεᾶς ὢν παῖς καὶ Πηλέως, σωφρονεστάτου τε καὶ τρίτου ἀπὸ Διός, καὶ ὑπὸ τῷ σοφωτάτῳ Χείρωνι τεθραμμένος, τοσαύτης ἦν ταραχῆς πλέως, ὥστ’ ἔχειν ἐν αὑτῷ νοσήματε δύο ἐναντίω ἀλλήλοιν, ἀνελευθερίαν μετὰ φιλοχρηματίας καὶ αὖ ὑπερηφανίαν θεῶν τε καὶ ἀνθρώπων.","st":"391c"},{"sp":"N","t":"Ὀρθῶς, ἔφη, λέγεις.","st":"391c"},{"sp":"N","t":"Μὴ τοίνυν, ἦν δ’ ἐγώ, μηδὲ τάδε πειθώμεθα μηδ’ ἐῶμεν λέγειν, ὡς Θησεὺς Ποσειδῶνος ὑὸς Πειρίθους τε Διὸς","st":"391c"},{"sp":"N","t":"ὥρμησαν οὕτως ἐπὶ δεινὰς ἁρπαγάς, μηδέ τιν’ ἄλλον θεοῦ παῖδά τε καὶ ἥρω τολμῆσαι ἂν δεινὰ καὶ ἀσεβῆ ἐργάσασθαι, οἷα νῦν καταψεύδονται αὐτῶν· ἀλλὰ προσαναγκάζωμεν τοὺς ποιητὰς ἢ μὴ τούτων αὐτὰ ἔργα φάναι ἢ τούτους μὴ εἶναι θεῶν παῖδας, ἀμφότερα δὲ μὴ λέγειν, μηδὲ ἡμῖν ἐπιχειρεῖν πείθειν τοὺς νέους ὡς οἱ θεοὶ κακὰ γεννῶσιν, καὶ ἥρωες ἀνθρώπων οὐδὲν βελτίους· ὅπερ γὰρ ἐν τοῖς πρόσθεν ἐλέγομεν,","st":"391d"},{"sp":"N","t":"οὔθ’ ὅσια ταῦτα οὔτε ἀληθῆ· ἐπεδείξαμεν γάρ που ὅτι ἐκ θεῶν κακὰ γίγνεσθαι ἀδύνατον.","st":"391e"},{"sp":"N","t":"Πῶς γὰρ οὔ;","st":"391e"},{"sp":"N","t":"Καὶ μὴν τοῖς γε ἀκούουσιν βλαβερά· πᾶς γὰρ ἑαυτῷ συγγνώμην ἕξει κακῷ ὄντι, πεισθεὶς ὡς ἄρα τοιαῦτα πράττουσίν τε καὶ ἔπραττον καὶ οἱ θεῶν ἀγχίσποροι,","st":"391e"},{"sp":"N","t":"⟨οἱ⟩ Ζηνὸς ἐγγύς, ὧν κατ’ Ἰδαῖον πάγον","st":"391e"},{"sp":"N","t":"Διὸς πατρῴου βωμός ἐστ’ ἐν αἰθέρι,","st":"391e"},{"sp":"N","t":"καὶ —","st":"391e"},{"sp":"N","t":"οὔ πώ σφιν ἐξίτηλον αἷμα δαιμόνων.","st":"391e"},{"sp":"N","t":"ὧν ἕνεκα παυστέον τοὺς τοιούτους μύθους, μὴ ἡμῖν πολλὴν","st":"391e"},{"sp":"N","t":"εὐχέρειαν ἐντίκτωσι τοῖς νέοις πονηρίας.","st":"392a"},{"sp":"N","t":"Κομιδῇ μὲν οὖν, ἔφη.","st":"392a"},{"sp":"N","t":"Τί οὖν, ἦν δ’ ἐγώ, ἡμῖν ἔτι λοιπὸν εἶδος λόγων πέρι ὁριζομένοις οἵους τε λεκτέον καὶ μή; περὶ γὰρ θεῶν ὡς δεῖ λέγεσθαι εἴρηται, καὶ περὶ δαιμόνων τε καὶ ἡρώων καὶ τῶν ἐν Ἅιδου.","st":"392a"},{"sp":"N","t":"Πάνυ μὲν οὖν.","st":"392a"},{"sp":"N","t":"Οὐκοῦν καὶ περὶ ἀνθρώπων τὸ λοιπὸν εἴη ἄν;","st":"392a"},{"sp":"N","t":"Δῆλα δή.","st":"392a"},{"sp":"N","t":"Ἀδύνατον δή, ὦ φίλε, ἡμῖν τοῦτό γε ἐν τῷ παρόντι τάξαι.","st":"392a"},{"sp":"N","t":"Πῶς;","st":"392a"},{"sp":"N","t":"Ὅτι οἶμαι ἡμᾶς ἐρεῖν ὡς ἄρα καὶ ποιηταὶ καὶ λογοποιοὶ","st":"392a"},{"sp":"N","t":"κακῶς λέγουσιν περὶ ἀνθρώπων τὰ μέγιστα, ὅτι εἰσὶν ἄδικοι μὲν εὐδαίμονες πολλοί, δίκαιοι δὲ ἄθλιοι, καὶ ὡς λυσιτελεῖ τὸ ἀδικεῖν, ἐὰν λανθάνῃ, ἡ δὲ δικαιοσύνη ἀλλότριον μὲν ἀγαθόν, οἰκεία δὲ ζημία· καὶ τὰ μὲν τοιαῦτα ἀπερεῖν λέγειν, τὰ δ’ ἐναντία τούτων προστάξειν ᾄδειν τε καὶ μυθολογεῖν. ἢ οὐκ οἴει;","st":"392b"},{"sp":"N","t":"Εὖ μὲν οὖν, ἔφη, οἶδα.","st":"392b"},{"sp":"N","t":"Οὐκοῦν ἐὰν ὁμολογῇς ὀρθῶς με λέγειν, φήσω σε ὡμολογηκέναι ἃ πάλαι ζητοῦμεν;","st":"392b"},{"sp":"N","t":"Ὀρθῶς, ἔφη, ὑπέλαβες.","st":"392b"},{"sp":"N","t":"Οὐκοῦν περί γε ἀνθρώπων ὅτι τοιούτους δεῖ λόγους λέγεσθαι, τότε διομολογησόμεθα, ὅταν εὕρωμεν οἷόν ἐστιν δικαιοσύνη καὶ ὡς φύσει λυσιτελοῦν τῷ ἔχοντι, ἐάντε δοκῇ ἐάντε μὴ τοιοῦτος εἶναι;","st":"392c"},{"sp":"N","t":"Ἀληθέστατα, ἔφη.","st":"392c"},{"sp":"N","t":"Τὰ μὲν δὴ λόγων πέρι ἐχέτω τέλος· τὸ δὲ λέξεως, ὡς ἐγὼ οἶμαι, μετὰ τοῦτο σκεπτέον, καὶ ἡμῖν ἅ τε λεκτέον καὶ ὡς λεκτέον παντελῶς ἐσκέψεται.","st":"392c"},{"sp":"N","t":"Καὶ ὁ Ἀδείμαντος, Τοῦτο, ἦ δ’ ὅς, οὐ μανθάνω ὅτι λέγεις.","st":"392c"},{"sp":"N","t":"Ἀλλὰ μέντοι, ἦν δ’ ἐγώ, δεῖ γε· ἴσως οὖν τῇδε μᾶλλον εἴσῃ. ἆρ’ οὐ πάντα ὅσα ὑπὸ μυθολόγων ἢ ποιητῶν λέγεται διήγησις οὖσα τυγχάνει ἢ γεγονότων ἢ ὄντων ἢ μελλόντων;","st":"392d"},{"sp":"N","t":"Τί γάρ, ἔφη, ἄλλο;","st":"392d"},{"sp":"N","t":"Ἆρ’ οὖν οὐχὶ ἤτοι ἁπλῇ διηγήσει ἢ διὰ μιμήσεως γιγνομένῃ ἢ δι’ ἀμφοτέρων περαίνουσιν;","st":"392d"},{"sp":"N","t":"Καὶ τοῦτο, ἦ δ’ ὅς, ἔτι δέομαι σαφέστερον μαθεῖν.","st":"392d"},{"sp":"N","t":"Γελοῖος, ἦν δ’ ἐγώ, ἔοικα διδάσκαλος εἶναι καὶ ἀσαφής· ὥσπερ οὖν οἱ ἀδύνατοι λέγειν, οὐ κατὰ ὅλον ἀλλ’ ἀπολαβὼν","st":"392d"},{"sp":"N","t":"μέρος τι πειράσομαί σοι ἐν τούτῳ δηλῶσαι ὃ βούλομαι. καί μοι εἰπέ· ἐπίστασαι τῆς Ἰλιάδος τὰ πρῶτα, ἐν οἷς ὁ ποιητής φησι τὸν μὲν Χρύσην δεῖσθαι τοῦ Ἀγαμέμνονος ἀπολῦσαι τὴν θυγατέρα, τὸν δὲ χαλεπαίνειν, τὸν δέ, ἐπειδὴ","st":"392e"},{"sp":"N","t":"οὐκ ἐτύγχανεν, κατεύχεσθαι τῶν Ἀχαιῶν πρὸς τὸν θεόν;","st":"393a"},{"sp":"N","t":"Ἔγωγε.","st":"393a"},{"sp":"N","t":"Οἶσθ’ οὖν ὅτι μέχρι μὲν τούτων τῶν ἐπῶν καὶ ἐλίσσετο πάντας Ἀχαιούς,","st":"393a"},{"sp":"N","t":"Ἀτρείδα δὲ μάλιστα δύω, κοσμήτορε λαῶν","st":"393a"},{"sp":"N","t":"λέγει τε αὐτὸς ὁ ποιητὴς καὶ οὐδὲ ἐπιχειρεῖ ἡμῶν τὴν διάνοιαν ἄλλοσε τρέπειν ὡς ἄλλος τις ὁ λέγων ἢ αὐτός· τὰ δὲ μετὰ ταῦτα ὥσπερ αὐτὸς ὢν ὁ Χρύσης λέγει καὶ πειρᾶται","st":"393a"},{"sp":"N","t":"ἡμᾶς ὅτι μάλιστα ποιῆσαι μὴ Ὅμηρον δοκεῖν εἶναι τὸν λέγοντα ἀλλὰ τὸν ἱερέα, πρεσβύτην ὄντα. καὶ τὴν ἄλλην δὴ πᾶσαν σχεδόν τι οὕτω πεποίηται διήγησιν περί τε τῶν ἐν Ἰλίῳ καὶ περὶ τῶν ἐν Ἰθάκῃ καὶ ὅλῃ Ὀδυσσείᾳ παθημάτων.","st":"393b"},{"sp":"N","t":"Πάνυ μὲν οὖν, ἔφη.","st":"393b"},{"sp":"N","t":"Οὐκοῦν διήγησις μέν ἐστιν καὶ ὅταν τὰς ῥήσεις ἑκάστοτε λέγῃ καὶ ὅταν τὰ μεταξὺ τῶν ῥήσεων;","st":"393b"},{"sp":"N","t":"Πῶς γὰρ οὔ;","st":"393b"},{"sp":"N","t":"Ἀλλ’ ὅταν γέ τινα λέγῃ ῥῆσιν ὥς τις ἄλλος ὤν, ἆρ’ οὐ τότε ὁμοιοῦν αὐτὸν φήσομεν ὅτι μάλιστα τὴν αὑτοῦ λέξιν ἑκάστῳ ὃν ἂν προείπῃ ὡς ἐροῦντα;","st":"393c"},{"sp":"N","t":"Φήσομεν· τί γάρ;","st":"393c"},{"sp":"N","t":"Οὐκοῦν τό γε ὁμοιοῦν ἑαυτὸν ἄλλῳ ἢ κατὰ φωνὴν ἢ κατὰ σχῆμα μιμεῖσθαί ἐστιν ἐκεῖνον ᾧ ἄν τις ὁμοιοῖ;","st":"393c"},{"sp":"N","t":"Τί μήν;","st":"393c"},{"sp":"N","t":"Ἐν δὴ τῷ τοιούτῳ, ὡς ἔοικεν, οὗτός τε καὶ οἱ ἄλλοι ποιηταὶ διὰ μιμήσεως τὴν διήγησιν ποιοῦνται.","st":"393c"},{"sp":"N","t":"Πάνυ μὲν οὖν.","st":"393c"},{"sp":"N","t":"Εἰ δέ γε μηδαμοῦ ἑαυτὸν ἀποκρύπτοιτο ὁ ποιητής, πᾶσα","st":"393c"},{"sp":"N","t":"ἂν αὐτῷ ἄνευ μιμήσεως ἡ ποίησίς τε καὶ διήγησις γεγονυῖα εἴη. ἵνα δὲ μὴ εἴπῃς ὅτι οὐκ αὖ μανθάνεις, ὅπως ἂν τοῦτο γένοιτο ἐγὼ φράσω. εἰ γὰρ Ὅμηρος εἰπὼν ὅτι ἦλθεν ὁ Χρύσης τῆς τε θυγατρὸς λύτρα φέρων καὶ ἱκέτης τῶν Ἀχαιῶν, μάλιστα δὲ τῶν βασιλέων, μετὰ τοῦτο μὴ ὡς Χρύσης γενόμενος ἔλεγεν ἀλλ’ ἔτι ὡς Ὅμηρος, οἶσθ’ ὅτι οὐκ ἂν μίμησις ἦν ἀλλὰ ἁπλῆ διήγησις. εἶχε δ’ ἂν ὧδε πως — φράσω δὲ ἄνευ μέτρου· οὐ γάρ εἰμι ποιητικός — Ἐλθὼν","st":"393d"},{"sp":"N","t":"ὁ ἱερεὺς ηὔχετο ἐκείνοις μὲν τοὺς θεοὺς δοῦναι ἑλόντας τὴν Τροίαν αὐτοὺς σωθῆναι, τὴν δὲ θυγατέρα οἱ λῦσαι δεξαμένους ἄποινα καὶ τὸν θεὸν αἰδεσθέντας. ταῦτα δὲ εἰπόντος αὐτοῦ οἱ μὲν ἄλλοι ἐσέβοντο καὶ συνῄνουν, ὁ δὲ Ἀγαμέμνων ἠγρίαινεν ἐντελλόμενος νῦν τε ἀπιέναι καὶ αὖθις μὴ ἐλθεῖν, μὴ αὐτῷ τό τε σκῆπτρον καὶ τὰ τοῦ θεοῦ στέμματα οὐκ ἐπαρκέσοι· πρὶν δὲ λυθῆναι αὐτοῦ τὴν θυγατέρα, ἐν Ἄργει ἔφη γηράσειν μετὰ οὗ· ἀπιέναι δ’ ἐκέλευεν καὶ μὴ ἐρεθίζειν,","st":"393e"},{"sp":"N","t":"ἵνα σῶς οἴκαδε ἔλθοι. ὁ δὲ πρεσβύτης ἀκούσας ἔδεισέν τε καὶ ἀπῄει σιγῇ, ἀποχωρήσας δὲ ἐκ τοῦ στρατοπέδου πολλὰ τῷ Ἀπόλλωνι ηὔχετο, τάς τε ἐπωνυμίας τοῦ θεοῦ ἀνακαλῶν καὶ ὑπομιμνῄσκων καὶ ἀπαιτῶν, εἴ τι πώποτε ἢ ἐν ναῶν οἰκοδομήσεσιν ἢ ἐν ἱερῶν θυσίαις κεχαρισμένον δωρήσαιτο· ὧν δὴ χάριν κατηύχετο τεῖσαι τοὺς Ἀχαιοὺς τὰ ἃ δάκρυα τοῖς ἐκείνου βέλεσιν. οὕτως, ἦν δ’ ἐγώ, ὦ ἑταῖρε, ἄνευ","st":"394a"},{"sp":"N","t":"μιμήσεως ἁπλῆ διήγησις γίγνεται.","st":"394b"},{"sp":"N","t":"Μανθάνω, ἔφη.","st":"394b"},{"sp":"N","t":"Μάνθανε τοίνυν, ἦν δ’ ἐγώ, ὅτι ταύτης αὖ ἐναντία γίγνεται, ὅταν τις τὰ τοῦ ποιητοῦ τὰ μεταξὺ τῶν ῥήσεων ἐξαιρῶν τὰ ἀμοιβαῖα καταλείπῃ.","st":"394b"},{"sp":"N","t":"Καὶ τοῦτο, ἔφη, μανθάνω, ὅτι ἔστιν τὸ περὶ τὰς τραγῳδίας τοιοῦτον.","st":"394b"},{"sp":"N","t":"Ὀρθότατα, ἔφην, ὑπέλαβες, καὶ οἶμαί σοι ἤδη δηλοῦν ὃ ἔμπροσθεν οὐχ οἷός τ’ ἦ, ὅτι τῆς ποιήσεώς τε καὶ μυθολογίας","st":"394b"},{"sp":"N","t":"ἡ μὲν διὰ μιμήσεως ὅλη ἐστίν, ὥσπερ σὺ λέγεις, τραγῳδία τε καὶ κωμῳδία, ἡ δὲ δι’ ἀπαγγελίας αὐτοῦ τοῦ ποιητοῦ — εὕροις δ’ ἂν αὐτὴν μάλιστά που ἐν διθυράμβοις — ἡ δ’ αὖ δι’ ἀμφοτέρων ἔν τε τῇ τῶν ἐπῶν ποιήσει, πολλαχοῦ δὲ καὶ ἄλλοθι, εἴ μοι μανθάνεις.","st":"394c"},{"sp":"N","t":"Ἀλλὰ συνίημι, ἔφη, ὃ τότε ἐβούλου λέγειν.","st":"394c"},{"sp":"N","t":"Καὶ τὸ πρὸ τούτου δὴ ἀναμνήσθητι, ὅτι ἔφαμεν ἃ μὲν λεκτέον ἤδη εἰρῆσθαι, ὡς δὲ λεκτέον ἔτι σκεπτέον εἶναι.","st":"394c"},{"sp":"N","t":"Ἀλλὰ μέμνημαι.","st":"394c"},{"sp":"N","t":"Τοῦτο τοίνυν αὐτὸ ἦν ὃ ἔλεγον, ὅτι χρείη διομολογήσασθαι πότερον ἐάσομεν τοὺς ποιητὰς μιμουμένους ἡμῖν τὰς διηγήσεις ποιεῖσθαι ἢ τὰ μὲν μιμουμένους, τὰ δὲ μή, καὶ ὁποῖα ἑκάτερα, ἢ οὐδὲ μιμεῖσθαι.","st":"394d"},{"sp":"N","t":"Μαντεύομαι, ἔφη, σκοπεῖσθαί σε εἴτε παραδεξόμεθα τραγῳδίαν τε καὶ κωμῳδίαν εἰς τὴν πόλιν, εἴτε καὶ οὔ.","st":"394d"},{"sp":"N","t":"Ἴσως, ἦν δ’ ἐγώ, ἴσως δὲ καὶ πλείω ἔτι τούτων· οὐ γὰρ δὴ ἔγωγέ πω οἶδα, ἀλλ’ ὅπῃ ἂν ὁ λόγος ὥσπερ πνεῦμα φέρῃ, ταύτῃ ἰτέον.","st":"394d"},{"sp":"N","t":"Καὶ καλῶς γ’, ἔφη, λέγεις.","st":"394d"},{"sp":"N","t":"Τόδε τοίνυν, ὦ Ἀδείμαντε, ἄθρει, πότερον μιμητικοὺς ἡμῖν δεῖ εἶναι τοὺς φύλακας ἢ οὔ· ἢ καὶ τοῦτο τοῖς ἔμπροσθεν ἕπεται, ὅτι εἷς ἕκαστος ἓν μὲν ἂν ἐπιτήδευμα καλῶς ἐπιτηδεύοι, πολλὰ δ’ οὔ, ἀλλ’ εἰ τοῦτο ἐπιχειροῖ, πολλῶν ἐφαπτόμενος πάντων ἀποτυγχάνοι ἄν, ὥστ’ εἶναί που ἐλλόγιμος;","st":"394e"},{"sp":"N","t":"Τί δ’ οὐ μέλλει;","st":"394e"},{"sp":"N","t":"Οὐκοῦν καὶ περὶ μιμήσεως ὁ αὐτὸς λόγος, ὅτι πολλὰ ὁ αὐτὸς μιμεῖσθαι εὖ ὥσπερ ἓν οὐ δυνατός;","st":"394e"},{"sp":"N","t":"Οὐ γὰρ οὖν.","st":"394e"},{"sp":"N","t":"Σχολῇ ἄρα ἐπιτηδεύσει γέ τι ἅμα τῶν ἀξίων λόγου ἐπιτηδευμάτων καὶ πολλὰ μιμήσεται καὶ ἔσται μιμητικός, ἐπεί που οὐδὲ τὰ δοκοῦντα ἐγγὺς ἀλλήλων εἶναι δύο μιμήματα δύνανται οἱ αὐτοὶ ἅμα εὖ μιμεῖσθαι, οἷον κωμῳδίαν καὶ τραγῳδίαν ποιοῦντες. ἢ οὐ μιμήματε ἄρτι τούτω ἐκάλεις;","st":"395a"},{"sp":"N","t":"Ἔγωγε· καὶ ἀληθῆ γε λέγεις, ὅτι οὐ δύνανται οἱ αὐτοί.","st":"395a"},{"sp":"N","t":"Οὐδὲ μὴν ῥαψῳδοί γε καὶ ὑποκριταὶ ἅμα.","st":"395a"},{"sp":"N","t":"Ἀληθῆ.","st":"395a"},{"sp":"N","t":"Ἀλλ’ οὐδέ τοι ὑποκριταὶ κωμῳδοῖς τε καὶ τραγῳδοῖς οἱ","st":"395a"},{"sp":"N","t":"αὐτοί· πάντα δὲ ταῦτα μιμήματα. ἢ οὔ;","st":"395b"},{"sp":"N","t":"Μιμήματα.","st":"395b"},{"sp":"N","t":"Καὶ ἔτι γε τούτων, ὦ Ἀδείμαντε, φαίνεταί μοι εἰς σμικρότερα κατακεκερματίσθαι ἡ τοῦ ἀνθρώπου φύσις, ὥστε ἀδύνατος εἶναι πολλὰ καλῶς μιμεῖσθαι ἢ αὐτὰ ἐκεῖνα πράττειν ὧν δὴ καὶ τὰ μιμήματά ἐστιν ἀφομοιώματα.","st":"395b"},{"sp":"N","t":"Ἀληθέστατα, ἦ δ’ ὅς.","st":"395b"},{"sp":"N","t":"Εἰ ἄρα τὸν πρῶτον λόγον διασώσομεν, τοὺς φύλακας ἡμῖν τῶν ἄλλων πασῶν δημιουργιῶν ἀφειμένους δεῖν εἶναι","st":"395b"},{"sp":"N","t":"δημιουργοὺς ἐλευθερίας τῆς πόλεως πάνυ ἀκριβεῖς καὶ μηδὲν ἄλλο ἐπιτηδεύειν ὅτι μὴ εἰς τοῦτο φέρει, οὐδὲν δὴ δέοι ἂν αὐτοὺς ἄλλο πράττειν οὐδὲ μιμεῖσθαι· ἐὰν δὲ μιμῶνται, μιμεῖσθαι τὰ τούτοις προσήκοντα εὐθὺς ἐκ παίδων, ἀνδρείους, σώφρονας, ὁσίους, ἐλευθέρους, καὶ τὰ τοιαῦτα πάντα, τὰ δὲ ἀνελεύθερα μήτε ποιεῖν μήτε δεινοὺς εἶναι μιμήσασθαι, μηδὲ ἄλλο μηδὲν τῶν αἰσχρῶν, ἵνα μὴ ἐκ τῆς μιμήσεως τοῦ εἶναι","st":"395c"},{"sp":"N","t":"ἀπολαύσωσιν. ἢ οὐκ ᾔσθησαι ὅτι αἱ μιμήσεις, ἐὰν ἐκ νέων πόρρω διατελέσωσιν, εἰς ἔθη τε καὶ φύσιν καθίστανται καὶ κατὰ σῶμα καὶ φωνὰς καὶ κατὰ τὴν διάνοιαν;","st":"395d"},{"sp":"N","t":"Καὶ μάλα, ἦ δ’ ὅς.","st":"395d"},{"sp":"N","t":"Οὐ δὴ ἐπιτρέψομεν, ἦν δ’ ἐγώ, ὧν φαμὲν κήδεσθαι καὶ δεῖν αὐτοὺς ἄνδρας ἀγαθοὺς γενέσθαι, γυναῖκα μιμεῖσθαι ἄνδρας ὄντας, ἢ νέαν ἢ πρεσβυτέραν, ἢ ἀνδρὶ λοιδορουμένην ἢ πρὸς θεοὺς ἐρίζουσάν τε καὶ μεγαλαυχουμένην, οἰομένην","st":"395d"},{"sp":"N","t":"εὐδαίμονα εἶναι, ἢ ἐν συμφοραῖς τε καὶ πένθεσιν καὶ θρήνοις ἐχομένην· κάμνουσαν δὲ ἢ ἐρῶσαν ἢ ὠδίνουσαν, πολλοῦ καὶ δεήσομεν.","st":"395e"},{"sp":"N","t":"Παντάπασι μὲν οὖν, ἦ δ’ ὅς.","st":"395e"},{"sp":"N","t":"Οὐδέ γε δούλας τε καὶ δούλους πράττοντας ὅσα δούλων.","st":"395e"},{"sp":"N","t":"Οὐδὲ τοῦτο.","st":"395e"},{"sp":"N","t":"Οὐδέ γε ἄνδρας κακούς, ὡς ἔοικεν, δειλούς τε καὶ τὰ ἐναντία πράττοντας ὧν νυνδὴ εἴπομεν, κακηγοροῦντάς τε καὶ κωμῳδοῦντας ἀλλήλους καὶ αἰσχρολογοῦντας, μεθύοντας ἢ","st":"395e"},{"sp":"N","t":"καὶ νήφοντας, ἢ καὶ ἄλλα ὅσα οἱ τοιοῦτοι καὶ ἐν λόγοις καὶ ἐν ἔργοις ἁμαρτάνουσιν εἰς αὑτούς τε καὶ εἰς ἄλλους, οἶμαι δὲ οὐδὲ μαινομένοις ἐθιστέον ἀφομοιοῦν αὑτοὺς ἐν λόγοις οὐδὲ ἐν ἔργοις· γνωστέον μὲν γὰρ καὶ μαινομένους καὶ πονηροὺς ἄνδρας τε καὶ γυναῖκας, ποιητέον δὲ οὐδὲν τούτων οὐδὲ μιμητέον.","st":"396a"},{"sp":"N","t":"Ἀληθέστατα, ἔφη.","st":"396a"},{"sp":"N","t":"Τί δέ; ἦν δ’ ἐγώ· χαλκεύοντας ἤ τι ἄλλο δημιουργοῦντας,","st":"396a"},{"sp":"N","t":"ἢ ἐλαύνοντας τριήρεις ἢ κελεύοντας τούτοις, ἤ τι ἄλλο τῶν περὶ ταῦτα μιμητέον;","st":"396b"},{"sp":"N","t":"Καὶ πῶς; ἔφη, οἷς γε οὐδὲ προσέχειν τὸν νοῦν τούτων οὐδενὶ ἐξέσται;","st":"396b"},{"sp":"N","t":"Τί δέ; ἵππους χρεμετίζοντας καὶ ταύρους μυκωμένους καὶ ποταμοὺς ψοφοῦντας καὶ θάλατταν κτυποῦσαν καὶ βροντὰς καὶ πάντα αὖ τὰ τοιαῦτα ἦ μιμήσονται;","st":"396b"},{"sp":"N","t":"Ἀλλ’ ἀπείρηται αὐτοῖς, ἔφη, μήτε μαίνεσθαι μήτε μαινομένοις ἀφομοιοῦσθαι.","st":"396b"},{"sp":"N","t":"Εἰ ἄρα, ἦν δ’ ἐγώ, μανθάνω ἃ σὺ λέγεις, ἔστιν τι εἶδος λέξεώς τε καὶ διηγήσεως ἐν ᾧ ἂν διηγοῖτο ὁ τῷ ὄντι καλὸς","st":"396b"},{"sp":"N","t":"κἀγαθός, ὁπότε τι δέοι αὐτὸν λέγειν, καὶ ἕτερον αὖ ἀνόμοιον τούτῳ εἶδος, οὗ ἂν ἔχοιτο ἀεὶ καὶ ἐν ᾧ διηγοῖτο ὁ ἐναντίως ἐκείνῳ φύς τε καὶ τραφείς.","st":"396c"},{"sp":"N","t":"Ποῖα δή, ἔφη, ταῦτα;","st":"396c"},{"sp":"N","t":"Ὁ μέν μοι δοκεῖ, ἦν δ’ ἐγώ, μέτριος ἀνήρ, ἐπειδὰν ἀφίκηται ἐν τῇ διηγήσει ἐπὶ λέξιν τινὰ ἢ πρᾶξιν ἀνδρὸς ἀγαθοῦ, ἐθελήσειν ὡς αὐτὸς ὢν ἐκεῖνος ἀπαγγέλλειν καὶ οὐκ αἰσχυνεῖσθαι ἐπὶ τῇ τοιαύτῃ μιμήσει, μάλιστα μὲν μιμούμενος","st":"396c"},{"sp":"N","t":"τὸν ἀγαθὸν ἀσφαλῶς τε καὶ ἐμφρόνως πράττοντα, ἐλάττω δὲ καὶ ἧττον ἢ ὑπὸ νόσων ἢ ὑπὸ ἐρώτων ἐσφαλμένον ἢ καὶ ὑπὸ μέθης ἤ τινος ἄλλης συμφορᾶς· ὅταν δὲ γίγνηται κατά τινα ἑαυτοῦ ἀνάξιον, οὐκ ἐθελήσειν σπουδῇ ἀπεικάζειν ἑαυτὸν τῷ χείρονι, εἰ μὴ ἄρα κατὰ βραχύ, ὅταν τι χρηστὸν ποιῇ, ἀλλ’ αἰσχυνεῖσθαι, ἅμα μὲν ἀγύμναστος ὢν τοῦ μιμεῖσθαι τοὺς τοιούτους, ἅμα δὲ καὶ δυσχεραίνων αὑτὸν ἐκμάττειν τε καὶ","st":"396d"},{"sp":"N","t":"ἐνιστάναι εἰς τοὺς τῶν κακιόνων τύπους, ἀτιμάζων τῇ διανοίᾳ, ὅτι μὴ παιδιᾶς χάριν.","st":"396e"},{"sp":"N","t":"Εἰκός, ἔφη.","st":"396e"},{"sp":"N","t":"Οὐκοῦν διηγήσει χρήσεται οἵᾳ ἡμεῖς ὀλίγον πρότερον διήλθομεν περὶ τὰ τοῦ Ὁμήρου ἔπη, καὶ ἔσται αὐτοῦ ἡ λέξις μετέχουσα μὲν ἀμφοτέρων, μιμήσεώς τε καὶ τῆς ἄλλης διηγήσεως, σμικρὸν δέ τι μέρος ἐν πολλῷ λόγῳ τῆς μιμήσεως; ἢ οὐδὲν λέγω;","st":"396e"},{"sp":"N","t":"Καὶ μάλα, ἔφη, οἷόν γε ἀνάγκη τὸν τύπον εἶναι τοῦ τοιούτου ῥήτορος.","st":"396e"},{"sp":"N","t":"Οὐκοῦν, ἦν δ’ ἐγώ, ὁ μὴ τοιοῦτος αὖ, ὅσῳ ἂν φαυλότερος ᾖ, πάντα τε μᾶλλον διηγήσεται καὶ οὐδὲν ἑαυτοῦ ἀνάξιον οἰήσεται εἶναι, ὥστε πάντα ἐπιχειρήσει μιμεῖσθαι σπουδῇ τε καὶ ἐναντίον πολλῶν, καὶ ἃ νυνδὴ ἐλέγομεν, βροντάς τε καὶ ψόφους ἀνέμων τε καὶ χαλαζῶν καὶ ἀξόνων τε καὶ τροχιλιῶν, καὶ σαλπίγγων καὶ αὐλῶν καὶ συρίγγων καὶ πάντων ὀργάνων φωνάς, καὶ ἔτι κυνῶν καὶ προβάτων καὶ ὀρνέων φθόγγους","st":"397a"},{"sp":"N","t":"καὶ ἔσται δὴ ἡ τούτου λέξις ἅπασα διὰ μιμήσεως φωναῖς τε καὶ σχήμασιν, ἢ σμικρόν τι διηγήσεως ἔχουσα;","st":"397b"},{"sp":"N","t":"Ἀνάγκη, ἔφη, καὶ τοῦτο.","st":"397b"},{"sp":"N","t":"Ταῦτα τοίνυν, ἦν δ’ ἐγώ, ἔλεγον τὰ δύο εἴδη τῆς λέξεως.","st":"397b"},{"sp":"N","t":"Καὶ γὰρ ἔστιν, ἔφη.","st":"397b"},{"sp":"N","t":"Οὐκοῦν αὐτοῖν τὸ μὲν σμικρὰς τὰς μεταβολὰς ἔχει, καὶ ἐάν τις ἀποδιδῷ πρέπουσαν ἁρμονίαν καὶ ῥυθμὸν τῇ λέξει, ὀλίγου πρὸς τὴν αὐτὴν γίγνεται λέγειν τῷ ὀρθῶς λέγοντι καὶ ἐν μιᾷ ἁρμονίᾳ — σμικραὶ γὰρ αἱ μεταβολαί — καὶ δὴ καὶ ἐν","st":"397b"},{"sp":"N","t":"ῥυθμῷ ὡσαύτως παραπλησίῳ τινί;","st":"397c"},{"sp":"N","t":"Κομιδῇ μὲν οὖν, ἔφη, οὕτως ἔχει.","st":"397c"},{"sp":"N","t":"Τί δὲ τὸ τοῦ ἑτέρου εἶδος; οὐ τῶν ἐναντίων δεῖται, πασῶν μὲν ἁρμονιῶν, πάντων δὲ ῥυθμῶν, εἰ μέλλει αὖ οἰκείως λέγεσθαι, διὰ τὸ παντοδαπὰς μορφὰς τῶν μεταβολῶν ἔχειν;","st":"397c"},{"sp":"N","t":"Καὶ σφόδρα γε οὕτως ἔχει.","st":"397c"},{"sp":"N","t":"Ἆρ’ οὖν πάντες οἱ ποιηταὶ καὶ οἵ τι λέγοντες ἢ τῷ ἑτέρῳ τούτων ἐπιτυγχάνουσιν τύπῳ τῆς λέξεως ἢ τῷ ἑτέρῳ ἢ ἐξ ἀμφοτέρων τινὶ συγκεραννύντες;","st":"397c"},{"sp":"N","t":"Ἀνάγκη, ἔφη.","st":"397c"},{"sp":"N","t":"Τί οὖν ποιήσομεν; ἦν δ’ ἐγώ· πότερον εἰς τὴν πόλιν πάντας τούτους παραδεξόμεθα ἢ τῶν ἀκράτων τὸν ἕτερον ἢ τὸν κεκραμένον;","st":"397d"},{"sp":"N","t":"Ἐὰν ἡ ἐμή, ἔφη, νικᾷ, τὸν τοῦ ἐπιεικοῦς μιμητὴν ἄκρατον.","st":"397d"},{"sp":"N","t":"Ἀλλὰ μήν, ὦ Ἀδείμαντε, ἡδύς γε καὶ ὁ κεκραμένος, πολὺ δὲ ἥδιστος παισί τε καὶ παιδαγωγοῖς ὁ ἐναντίος οὗ σὺ αἱρῇ καὶ τῷ πλείστῳ ὄχλῳ.","st":"397d"},{"sp":"N","t":"Ἥδιστος γάρ.","st":"397d"},{"sp":"N","t":"Ἀλλ’ ἴσως, ἦν δ’ ἐγώ, οὐκ ἂν αὐτὸν ἁρμόττειν φαίης τῇ","st":"397d"},{"sp":"N","t":"ἡμετέρᾳ πολιτείᾳ, ὅτι οὐκ ἔστιν διπλοῦς ἀνὴρ παρ’ ἡμῖν οὐδὲ πολλαπλοῦς, ἐπειδὴ ἕκαστος ἓν πράττει.","st":"397e"},{"sp":"N","t":"Οὐ γὰρ οὖν ἁρμόττει.","st":"397e"},{"sp":"N","t":"Οὐκοῦν διὰ ταῦτα ἐν μόνῃ τῇ τοιαύτῃ πόλει τόν τε σκυτοτόμον σκυτοτόμον εὑρήσομεν καὶ οὐ κυβερνήτην πρὸς τῇ σκυτοτομίᾳ, καὶ τὸν γεωργὸν γεωργὸν καὶ οὐ δικαστὴν πρὸς τῇ γεωργίᾳ, καὶ τὸν πολεμικὸν πολεμικὸν καὶ οὐ χρηματιστὴν πρὸς τῇ πολεμικῇ, καὶ πάντας οὕτω;","st":"397e"},{"sp":"N","t":"Ἀληθῆ, ἔφη.","st":"397e"},{"sp":"N","t":"Ἄνδρα δή, ὡς ἔοικε, δυνάμενον ὑπὸ σοφίας παντοδαπὸν γίγνεσθαι καὶ μιμεῖσθαι πάντα χρήματα, εἰ ἡμῖν ἀφίκοιτο εἰς τὴν πόλιν αὐτός τε καὶ τὰ ποιήματα βουλόμενος ἐπιδείξασθαι, προσκυνοῖμεν ἂν αὐτὸν ὡς ἱερὸν καὶ θαυμαστὸν καὶ ἡδύν, εἴποιμεν δ’ ἂν ὅτι οὐκ ἔστιν τοιοῦτος ἀνὴρ ἐν τῇ πόλει παρ’ ἡμῖν οὔτε θέμις ἐγγενέσθαι, ἀποπέμποιμέν τε εἰς ἄλλην πόλιν μύρον κατὰ τῆς κεφαλῆς καταχέαντες καὶ ἐρίῳ στέψαντες, αὐτοὶ δ’ ἂν τῷ αὐστηροτέρῳ καὶ ἀηδεστέρῳ ποιητῇ","st":"398a"},{"sp":"N","t":"χρῴμεθα καὶ μυθολόγῳ ὠφελίας ἕνεκα, ὃς ἡμῖν τὴν τοῦ ἐπιεικοῦς λέξιν μιμοῖτο καὶ τὰ λεγόμενα λέγοι ἐν ἐκείνοις τοῖς τύποις οἷς κατ’ ἀρχὰς ἐνομοθετησάμεθα, ὅτε τοὺς στρατιώτας ἐπεχειροῦμεν παιδεύειν.","st":"398b"},{"sp":"N","t":"Καὶ μάλ’, ἔφη, οὕτως ἂν ποιοῖμεν, εἰ ἐφ’ ἡμῖν εἴη.","st":"398b"},{"sp":"N","t":"Νῦν δή, εἶπον ἐγώ, ὦ φίλε, κινδυνεύει ἡμῖν τῆς μουσικῆς","st":"398b"},{"sp":"N","t":"τὸ περὶ λόγους τε καὶ μύθους παντελῶς διαπεπεράνθαι· ἅ τε γὰρ λεκτέον καὶ ὡς λεκτέον εἴρηται.","st":"398b"},{"sp":"N","t":"Καὶ αὐτῷ μοι δοκεῖ, ἔφη.","st":"398b"},{"sp":"N","t":"Οὐκοῦν μετὰ τοῦτο, ἦν δ’ ἐγώ, τὸ περὶ ᾠδῆς τρόπου καὶ μελῶν λοιπόν;","st":"398c"},{"sp":"N","t":"Δῆλα δή.","st":"398c"},{"sp":"N","t":"Ἆρ’ οὖν οὐ πᾶς ἤδη ἂν εὕροι ἃ ἡμῖν λεκτέον περὶ αὐτῶν οἷα δεῖ εἶναι, εἴπερ μέλλομεν τοῖς προειρημένοις συμφωνήσειν;","st":"398c"},{"sp":"N","t":"Καὶ ὁ Γλαύκων ἐπιγελάσας, Ἐγὼ τοίνυν, ἔφη, ὦ Σώκρατες, κινδυνεύω ἐκτὸς τῶν πάντων εἶναι· οὔκουν ἱκανῶς γε ἔχω ἐν τῷ παρόντι συμβαλέσθαι ποῖα ἄττα δεῖ ἡμᾶς λέγειν· ὑποπτεύω μέντοι.","st":"398c"},{"sp":"N","t":"Πάντως δήπου, ἦν δ’ ἐγώ, πρῶτον μὲν τόδε ἱκανῶς ἔχεις","st":"398c"},{"sp":"N","t":"λέγειν, ὅτι τὸ μέλος ἐκ τριῶν ἐστιν συγκείμενον, λόγου τε καὶ ἁρμονίας καὶ ῥυθμοῦ.","st":"398d"},{"sp":"N","t":"Ναί, ἔφη, τοῦτό γε.","st":"398d"},{"sp":"N","t":"Οὐκοῦν ὅσον γε αὐτοῦ λόγος ἐστίν, οὐδὲν δήπου διαφέρει τοῦ μὴ ᾀδομένου λόγου πρὸς τὸ ἐν τοῖς αὐτοῖς δεῖν τύποις λέγεσθαι οἷς ἄρτι προείπομεν καὶ ὡσαύτως;","st":"398d"},{"sp":"N","t":"Ἀληθῆ, ἔφη.","st":"398d"},{"sp":"N","t":"Καὶ μὴν τήν γε ἁρμονίαν καὶ ῥυθμὸν ἀκολουθεῖν δεῖ τῷ λόγῳ.","st":"398d"},{"sp":"N","t":"Πῶς δ’ οὔ;","st":"398d"},{"sp":"N","t":"Ἀλλὰ μέντοι θρήνων γε καὶ ὀδυρμῶν ἔφαμεν ἐν λόγοις οὐδὲν προσδεῖσθαι.","st":"398d"},{"sp":"N","t":"Οὐ γὰρ οὖν.","st":"398d"},{"sp":"N","t":"Τίνες οὖν θρηνώδεις ἁρμονίαι; λέγε μοι· σὺ γὰρ μουσικός.","st":"398e"},{"sp":"N","t":"Μειξολυδιστί, ἔφη, καὶ συντονολυδιστὶ καὶ τοιαῦταί τινες.","st":"398e"},{"sp":"N","t":"Οὐκοῦν αὗται, ἦν δ’ ἐγώ, ἀφαιρετέαι; ἄχρηστοι γὰρ καὶ γυναιξὶν ἃς δεῖ ἐπιεικεῖς εἶναι, μὴ ὅτι ἀνδράσι.","st":"398e"},{"sp":"N","t":"Πάνυ γε.","st":"398e"},{"sp":"N","t":"Ἀλλὰ μὴν μέθη γε φύλαξιν ἀπρεπέστατον καὶ μαλακία καὶ ἀργία.","st":"398e"},{"sp":"N","t":"Πῶς γὰρ οὔ;","st":"398e"},{"sp":"N","t":"Τίνες οὖν μαλακαί τε καὶ συμποτικαὶ τῶν ἁρμονιῶν;","st":"398e"},{"sp":"N","t":"Ἰαστί, ἦ δ’ ὅς, καὶ λυδιστὶ αὖ τινες χαλαραὶ καλοῦνται.","st":"398e"},{"sp":"N","t":"Ταύταις οὖν, ὦ φίλε, ἐπὶ πολεμικῶν ἀνδρῶν ἔσθ’ ὅτι χρήσῃ;","st":"399a"},{"sp":"N","t":"Οὐδαμῶς, ἔφη· ἀλλὰ κινδυνεύει σοι δωριστὶ λείπεσθαι καὶ φρυγιστί.","st":"399a"},{"sp":"N","t":"Οὐκ οἶδα, ἔφην ἐγώ, τὰς ἁρμονίας, ἀλλὰ κατάλειπε ἐκείνην τὴν ἁρμονίαν, ἣ ἔν τε πολεμικῇ πράξει ὄντος ἀνδρείου καὶ ἐν πάσῃ βιαίῳ ἐργασίᾳ πρεπόντως ἂν μιμήσαιτο φθόγγους τε καὶ προσῳδίας, καὶ ἀποτυχόντος ἢ εἰς τραύματα ἢ εἰς","st":"399a"},{"sp":"N","t":"θανάτους ἰόντος ἢ εἴς τινα ἄλλην συμφορὰν πεσόντος, ἐν πᾶσι τούτοις παρατεταγμένως καὶ καρτερούντως ἀμυνομένου τὴν τύχην· καὶ ἄλλην αὖ ἐν εἰρηνικῇ τε καὶ μὴ βιαίῳ ἀλλ’ ἐν ἑκουσίᾳ πράξει ὄντος, ἢ τινά τι πείθοντός τε καὶ δεομένου, ἢ εὐχῇ θεὸν ἢ διδαχῇ καὶ νουθετήσει ἄνθρωπον, ἢ τοὐναντίον ἄλλῳ δεομένῳ ἢ διδάσκοντι ἢ μεταπείθοντι ἑαυτὸν ἐπέχοντα, καὶ ἐκ τούτων πράξαντα κατὰ νοῦν, καὶ μὴ ὑπερηφάνως ἔχοντα, ἀλλὰ σωφρόνως τε καὶ μετρίως ἐν πᾶσι τούτοις","st":"399b"},{"sp":"N","t":"πράττοντά τε καὶ τὰ ἀποβαίνοντα ἀγαπῶντα. ταύτας δύο ἁρμονίας, βίαιον, ἑκούσιον, δυστυχούντων, εὐτυχούντων, σωφρόνων, ἀνδρείων [ἁρμονίας] αἵτινες φθόγγους μιμήσονται κάλλιστα, ταύτας λεῖπε.","st":"399c"},{"sp":"N","t":"Ἀλλ’, ἦ δ’ ὅς, οὐκ ἄλλας αἰτεῖς λείπειν ἢ ἃς νυνδὴ ἐγὼ ἔλεγον.","st":"399c"},{"sp":"N","t":"Οὐκ ἄρα, ἦν δ’ ἐγώ, πολυχορδίας γε οὐδὲ παναρμονίου ἡμῖν δεήσει ἐν ταῖς ᾠδαῖς τε καὶ μέλεσιν.","st":"399c"},{"sp":"N","t":"Οὔ μοι, ἔφη, φαίνεται.","st":"399c"},{"sp":"N","t":"Τριγώνων ἄρα καὶ πηκτίδων καὶ πάντων ὀργάνων ὅσα","st":"399c"},{"sp":"N","t":"πολύχορδα καὶ πολυαρμόνια, δημιουργοὺς οὐ θρέψομεν.","st":"399d"},{"sp":"N","t":"Οὐ φαινόμεθα.","st":"399d"},{"sp":"N","t":"Τί δέ; αὐλοποιοὺς ἢ αὐλητὰς παραδέξῃ εἰς τὴν πόλιν; ἢ οὐ τοῦτο πολυχορδότατον, καὶ αὐτὰ τὰ παναρμόνια αὐλοῦ τυγχάνει ὄντα μίμημα;","st":"399d"},{"sp":"N","t":"Δῆλα δή, ἦ δ’ ὅς.","st":"399d"},{"sp":"N","t":"Λύρα δή σοι, ἦν δ’ ἐγώ, καὶ κιθάρα λείπεται [καὶ] κατὰ πόλιν χρήσιμα· καὶ αὖ κατ’ ἀγροὺς τοῖς νομεῦσι σύριγξ ἄν τις εἴη.","st":"399d"},{"sp":"N","t":"Ὡς γοῦν, ἔφη, ὁ λόγος ἡμῖν σημαίνει.","st":"399d"},{"sp":"N","t":"Οὐδέν γε, ἦν δ’ ἐγώ, καινὸν ποιοῦμεν, ὦ φίλε, κρίνοντες τὸν Ἀπόλλω καὶ τὰ τοῦ Ἀπόλλωνος ὄργανα πρὸ Μαρσύου τε καὶ τῶν ἐκείνου ὀργάνων. Μὰ Δία, ἦ δ’ ὅς, οὔ μοι φαινόμεθα.","st":"399e"},{"sp":"N","t":"Καὶ νὴ τὸν κύνα, εἶπον, λελήθαμέν γε διακαθαίροντες πάλιν ἣν ἄρτι τρυφᾶν ἔφαμεν πόλιν.","st":"399e"},{"sp":"N","t":"Σωφρονοῦντές γε ἡμεῖς, ἦ δ’ ὅς.","st":"399e"},{"sp":"N","t":"Ἴθι δή, ἔφην, καὶ τὰ λοιπὰ καθαίρωμεν. ἑπόμενον γὰρ δὴ ταῖς ἁρμονίαις ἂν ἡμῖν εἴη τὸ περὶ ῥυθμούς, μὴ ποικίλους αὐτοὺς διώκειν μηδὲ παντοδαπὰς βάσεις, ἀλλὰ βίου ῥυθμοὺς ἰδεῖν κοσμίου τε καὶ ἀνδρείου τίνες εἰσίν· οὓς ἰδόντα τὸν","st":"399e"},{"sp":"N","t":"πόδα τῷ τοῦ τοιούτου λόγῳ ἀναγκάζειν ἕπεσθαι καὶ τὸ μέλος, ἀλλὰ μὴ λόγον ποδί τε καὶ μέλει. οἵτινες δ’ ἂν εἶεν οὗτοι οἱ ῥυθμοί, σὸν ἔργον, ὥσπερ τὰς ἁρμονίας, φράσαι.","st":"400a"},{"sp":"N","t":"Ἀλλὰ μὰ Δί’, ἔφη, οὐκ ἔχω λέγειν. ὅτι μὲν γὰρ τρί’ ἄττα ἐστὶν εἴδη ἐξ ὧν αἱ βάσεις πλέκονται, ὥσπερ ἐν τοῖς φθόγγοις τέτταρα, ὅθεν αἱ πᾶσαι ἁρμονίαι, τεθεαμένος ἂν εἴποιμι· ποῖα δὲ ὁποίου βίου μιμήματα, λέγειν οὐκ ἔχω.","st":"400a"},{"sp":"N","t":"Ἀλλὰ ταῦτα μέν, ἦν δ’ ἐγώ, καὶ μετὰ Δάμωνος βουλευσόμεθα, τίνες τε ἀνελευθερίας καὶ ὕβρεως ἢ μανίας καὶ ἄλλης κακίας πρέπουσαι βάσεις, καὶ τίνας τοῖς ἐναντίοις λειπτέον ῥυθμούς· οἶμαι δέ με ἀκηκοέναι οὐ σαφῶς ἐνόπλιόν τέ τινα ὀνομάζοντος αὐτοῦ σύνθετον καὶ δάκτυλον καὶ ἡρῷόν γε, οὐκ οἶδα ὅπως διακοσμοῦντος καὶ ἴσον ἄνω καὶ κάτω τιθέντος, εἰς βραχύ τε καὶ μακρὸν γιγνόμενον, καί, ὡς ἐγὼ οἶμαι, ἴαμβον καί τιν’ ἄλλον τροχαῖον ὠνόμαζε, μήκη δὲ καὶ","st":"400b"},{"sp":"N","t":"βραχύτητας προσῆπτε. καὶ τούτων τισὶν οἶμαι τὰς ἀγωγὰς τοῦ ποδὸς αὐτὸν οὐχ ἧττον ψέγειν τε καὶ ἐπαινεῖν ἢ τοὺς ῥυθμοὺς αὐτούς — ἤτοι συναμφότερόν τι· οὐ γὰρ ἔχω λέγειν — ἀλλὰ ταῦτα μέν, ὥσπερ εἶπον, εἰς Δάμωνα ἀναβεβλήσθω· διελέσθαι γὰρ οὐ σμικροῦ λόγου. ἢ σὺ οἴει;","st":"400c"},{"sp":"N","t":"Μὰ Δί’, οὐκ ἔγωγε.","st":"400c"},{"sp":"N","t":"Ἀλλὰ τόδε γε, ὅτι τὸ τῆς εὐσχημοσύνης τε καὶ ἀσχημοσύνης τῷ εὐρύθμῳ τε καὶ ἀρρύθμῳ ἀκολουθεῖ, δύνασαι διελέσθαι;","st":"400c"},{"sp":"N","t":"Πῶς δ’ οὔ;","st":"400c"},{"sp":"N","t":"Ἀλλὰ μὴν τὸ εὔρυθμόν γε καὶ τὸ ἄρρυθμον τὸ μὲν τῇ καλῇ λέξει ἕπεται ὁμοιούμενον, τὸ δὲ τῇ ἐναντίᾳ, καὶ τὸ εὐάρμοστον καὶ ἀνάρμοστον ὡσαύτως, εἴπερ ῥυθμός γε καὶ ἁρμονία λόγῳ, ὥσπερ ἄρτι ἐλέγετο, ἀλλὰ μὴ λόγος τούτοις.","st":"400d"},{"sp":"N","t":"Ἀλλὰ μήν, ἦ δ’ ὅς, ταῦτά γε λόγῳ ἀκολουθητέον.","st":"400d"},{"sp":"N","t":"Τί δ’ ὁ τρόπος τῆς λέξεως, ἦν δ’ ἐγώ, καὶ ὁ λόγος; οὐ","st":"400d"},{"sp":"N","t":"τῷ τῆς ψυχῆς ἤθει ἕπεται;","st":"400d"},{"sp":"N","t":"Πῶς γὰρ οὔ;","st":"400d"},{"sp":"N","t":"Τῇ δὲ λέξει τὰ ἄλλα;","st":"400d"},{"sp":"N","t":"Ναί.","st":"400d"},{"sp":"N","t":"Εὐλογία ἄρα καὶ εὐαρμοστία καὶ εὐσχημοσύνη καὶ εὐρυθμία","st":"400d"},{"sp":"N","t":"εὐηθείᾳ ἀκολουθεῖ, οὐχ ἣν ἄνοιαν οὖσαν ὑποκοριζόμενοι καλοῦμεν [ὡς εὐήθειαν], ἀλλὰ τὴν ὡς ἀληθῶς εὖ τε καὶ καλῶς τὸ ἦθος κατεσκευασμένην διάνοιαν.","st":"400e"},{"sp":"N","t":"Παντάπασι μὲν οὖν, ἔφη.","st":"400e"},{"sp":"N","t":"Ἆρ’ οὖν οὐ πανταχοῦ ταῦτα διωκτέα τοῖς νέοις, εἰ μέλλουσι τὸ αὑτῶν πράττειν;","st":"400e"},{"sp":"N","t":"Διωκτέα μὲν οὖν.","st":"400e"},{"sp":"N","t":"Ἔστιν δέ γέ που πλήρης μὲν γραφικὴ αὐτῶν καὶ πᾶσα ἡ τοιαύτη δημιουργία, πλήρης δὲ ὑφαντικὴ καὶ ποικιλία καὶ οἰκοδομία καὶ πᾶσα αὖ ἡ τῶν ἄλλων σκευῶν ἐργασία, ἔτι δὲ ἡ τῶν σωμάτων φύσις καὶ ἡ τῶν ἄλλων φυτῶν· ἐν πᾶσι γὰρ τούτοις ἔνεστιν εὐσχημοσύνη ἢ ἀσχημοσύνη. καὶ ἡ μὲν ἀσχημοσύνη καὶ ἀρρυθμία καὶ ἀναρμοστία κακολογίας καὶ κακοηθείας ἀδελφά, τὰ δ’ ἐναντία τοῦ ἐναντίου, σώφρονός τε καὶ ἀγαθοῦ ἤθους, ἀδελφά τε καὶ μιμήματα.","st":"401a"},{"sp":"N","t":"Παντελῶς μὲν οὖν, ἔφη.","st":"401a"},{"sp":"N","t":"Ἆρ’ οὖν τοῖς ποιηταῖς ἡμῖν μόνον ἐπιστατητέον καὶ προσαναγκαστέον τὴν τοῦ ἀγαθοῦ εἰκόνα ἤθους ἐμποιεῖν τοῖς ποιήμασιν ἢ μὴ παρ’ ἡμῖν ποιεῖν, ἢ καὶ τοῖς ἄλλοις δημιουργοῖς ἐπιστατητέον καὶ διακωλυτέον τὸ κακόηθες τοῦτο καὶ ἀκόλαστον καὶ ἀνελεύθερον καὶ ἄσχημον μήτε ἐν εἰκόσι ζῴων μήτε ἐν οἰκοδομήμασι μήτε ἐν ἄλλῳ μηδενὶ δημιουργουμένῳ ἐμποιεῖν, ἢ ὁ μὴ οἷός τε ὢν οὐκ ἐατέος παρ’ ἡμῖν δημιουργεῖν, ἵνα μὴ ἐν κακίας εἰκόσι τρεφόμενοι ἡμῖν οἱ","st":"401b"},{"sp":"N","t":"φύλακες ὥσπερ ἐν κακῇ βοτάνῃ, πολλὰ ἑκάστης ἡμέρας κατὰ σμικρὸν ἀπὸ πολλῶν δρεπόμενοί τε καὶ νεμόμενοι, ἕν τι συνιστάντες λανθάνωσιν κακὸν μέγα ἐν τῇ αὑτῶν ψυχῇ, ἀλλ’ ἐκείνους ζητητέον τοὺς δημιουργοὺς τοὺς εὐφυῶς δυναμένους ἰχνεύειν τὴν τοῦ καλοῦ τε καὶ εὐσχήμονος φύσιν, ἵνα ὥσπερ ἐν ὑγιεινῷ τόπῳ οἰκοῦντες οἱ νέοι ἀπὸ παντὸς ὠφελῶνται, ὁπόθεν ἂν αὐτοῖς ἀπὸ τῶν καλῶν ἔργων ἢ πρὸς ὄψιν ἢ πρὸς ἀκοήν τι προσβάλῃ, ὥσπερ αὔρα φέρουσα ἀπὸ","st":"401c"},{"sp":"N","t":"χρηστῶν τόπων ὑγίειαν, καὶ εὐθὺς ἐκ παίδων λανθάνῃ εἰς ὁμοιότητά τε καὶ φιλίαν καὶ συμφωνίαν τῷ καλῷ λόγῳ ἄγουσα;","st":"401d"},{"sp":"N","t":"Πολὺ γὰρ ἄν, ἔφη, κάλλιστα οὕτω τραφεῖεν.","st":"401d"},{"sp":"N","t":"Ἆρ’ οὖν, ἦν δ’ ἐγώ, ὦ Γλαύκων, τούτων ἕνεκα κυριωτάτη ἐν μουσικῇ τροφή, ὅτι μάλιστα καταδύεται εἰς τὸ ἐντὸς τῆς ψυχῆς ὅ τε ῥυθμὸς καὶ ἁρμονία, καὶ ἐρρωμενέστατα ἅπτεται αὐτῆς φέροντα τὴν εὐσχημοσύνην, καὶ ποιεῖ εὐσχήμονα,","st":"401d"},{"sp":"N","t":"ἐάν τις ὀρθῶς τραφῇ, εἰ δὲ μή, τοὐναντίον; καὶ ὅτι αὖ τῶν παραλειπομένων καὶ μὴ καλῶς δημιουργηθέντων ἢ μὴ καλῶς φύντων ὀξύτατ’ ἂν αἰσθάνοιτο ὁ ἐκεῖ τραφεὶς ὡς ἔδει, καὶ ὀρθῶς δὴ δυσχεραίνων τὰ μὲν καλὰ ἐπαινοῖ καὶ χαίρων καὶ καταδεχόμενος εἰς τὴν ψυχὴν τρέφοιτ’ ἂν ἀπ’ αὐτῶν καὶ","st":"401e"},{"sp":"N","t":"γίγνοιτο καλός τε κἀγαθός, τὰ δ’ αἰσχρὰ ψέγοι τ’ ἂν ὀρθῶς καὶ μισοῖ ἔτι νέος ὤν, πρὶν λόγον δυνατὸς εἶναι λαβεῖν, ἐλθόντος δὲ τοῦ λόγου ἀσπάζοιτ’ ἂν αὐτὸν γνωρίζων δι’ οἰκειότητα μάλιστα ὁ οὕτω τραφείς; Ἐμοὶ γοῦν δοκεῖ, ἔφη, τῶν τοιούτων ἕνεκα ἐν μουσικῇ εἶναι ἡ τροφή. Ὥσπερ ἄρα, ἦν δ’ ἐγώ, γραμμάτων πέρι τότε ἱκανῶς εἴχομεν, ὅτε τὰ στοιχεῖα μὴ λανθάνοι ἡμᾶς ὀλίγα ὄντα ἐν ἅπασιν οἷς ἔστιν περιφερόμενα, καὶ οὔτ’ ἐν σμικρῷ οὔτ’ ἐν","st":"402a"},{"sp":"N","t":"μεγάλῳ ἠτιμάζομεν αὐτά, ὡς οὐ δέοι αἰσθάνεσθαι, ἀλλὰ πανταχοῦ προυθυμούμεθα διαγιγνώσκειν, ὡς οὐ πρότερον ἐσόμενοι γραμματικοὶ πρὶν οὕτως ἔχοιμεν — Ἀληθῆ.","st":"402b"},{"sp":"N","t":"Οὐκοῦν καὶ εἰκόνας γραμμάτων, εἴ που ἢ ἐν ὕδασιν ἢ ἐν κατόπτροις ἐμφαίνοιντο, οὐ πρότερον γνωσόμεθα, πρὶν ἂν αὐτὰ γνῶμεν, ἀλλ’ ἔστιν τῆς αὐτῆς τέχνης τε καὶ μελέτης;","st":"402b"},{"sp":"N","t":"Παντάπασι μὲν οὖν.","st":"402b"},{"sp":"N","t":"Ἆρ’ οὖν, ὃ λέγω, πρὸς θεῶν, οὕτως οὐδὲ μουσικοὶ πρότερον","st":"402b"},{"sp":"N","t":"ἐσόμεθα, οὔτε αὐτοὶ οὔτε οὕς φαμεν ἡμῖν παιδευτέον εἶναι τοὺς φύλακας, πρὶν ἂν τὰ τῆς σωφροσύνης εἴδη καὶ ἀνδρείας καὶ ἐλευθεριότητος καὶ μεγαλοπρεπείας καὶ ὅσα τούτων ἀδελφὰ καὶ τὰ τούτων αὖ ἐναντία πανταχοῦ περιφερόμενα γνωρίζωμεν καὶ ἐνόντα ἐν οἷς ἔνεστιν αἰσθανώμεθα καὶ αὐτὰ καὶ εἰκόνας αὐτῶν, καὶ μήτε ἐν σμικροῖς μήτε ἐν μεγάλοις ἀτιμάζωμεν, ἀλλὰ τῆς αὐτῆς οἰώμεθα τέχνης εἶναι καὶ μελέτης;","st":"402c"},{"sp":"N","t":"Πολλὴ ἀνάγκη, ἔφη.","st":"402c"},{"sp":"N","t":"Οὐκοῦν, ἦν δ’ ἐγώ, ὅτου ἂν συμπίπτῃ ἔν τε τῇ ψυχῇ καλὰ ἤθη ἐνόντα καὶ ἐν τῷ εἴδει ὁμολογοῦντα ἐκείνοις καὶ συμφωνοῦντα, τοῦ αὐτοῦ μετέχοντα τύπου, τοῦτ’ ἂν εἴη κάλλιστον θέαμα τῷ δυναμένῳ θεᾶσθαι;","st":"402d"},{"sp":"N","t":"Πολύ γε.","st":"402d"},{"sp":"N","t":"Καὶ μὴν τό γε κάλλιστον ἐρασμιώτατον;","st":"402d"},{"sp":"N","t":"Πῶς δ’ οὔ;","st":"402d"},{"sp":"N","t":"Τῶν δὴ ὅτι μάλιστα τοιούτων ἀνθρώπων ὅ γε μουσικὸς ἐρῴη ἄν· εἰ δὲ ἀσύμφωνος εἴη, οὐκ ἂν ἐρῴη.","st":"402d"},{"sp":"N","t":"Οὐκ ἄν, εἴ γέ τι, ἔφη, κατὰ τὴν ψυχὴν ἐλλείποι· εἰ μέντοι τι κατὰ τὸ σῶμα, ὑπομείνειεν ἂν ὥστε ἐθέλειν","st":"402d"},{"sp":"N","t":"ἀσπάζεσθαι.","st":"402e"},{"sp":"N","t":"Μανθάνω, ἦν δ’ ἐγώ· ὅτι ἔστιν σοι ἢ γέγονεν παιδικὰ τοιαῦτα, καὶ συγχωρῶ. ἀλλὰ τόδε μοι εἰπέ· σωφροσύνῃ καὶ ἡδονῇ ὑπερβαλλούσῃ ἔστι τις κοινωνία;","st":"402e"},{"sp":"N","t":"Καὶ πῶς; ἔφη, ἥ γε ἔκφρονα ποιεῖ οὐχ ἧττον ἢ λύπη;","st":"402e"},{"sp":"N","t":"Ἀλλὰ τῇ ἄλλῃ ἀρετῇ;","st":"402e"},{"sp":"N","t":"Οὐδαμῶς.","st":"403a"},{"sp":"N","t":"Τί δέ; ὕβρει τε καὶ ἀκολασίᾳ;","st":"403a"},{"sp":"N","t":"Πάντων μάλιστα.","st":"403a"},{"sp":"N","t":"Μείζω δέ τινα καὶ ὀξυτέραν ἔχεις εἰπεῖν ἡδονὴν τῆς περὶ τὰ ἀφροδίσια;","st":"403a"},{"sp":"N","t":"Οὐκ ἔχω, ἦ δ’ ὅς, οὐδέ γε μανικωτέραν.","st":"403a"},{"sp":"N","t":"Ὁ δὲ ὀρθὸς ἔρως πέφυκε κοσμίου τε καὶ καλοῦ σωφρόνως τε καὶ μουσικῶς ἐρᾶν;","st":"403a"},{"sp":"N","t":"Καὶ μάλα, ἦ δ’ ὅς.","st":"403a"},{"sp":"N","t":"Οὐδὲν ἄρα προσοιστέον μανικὸν οὐδὲ συγγενὲς ἀκολασίας τῷ ὀρθῷ ἔρωτι;","st":"403a"},{"sp":"N","t":"Οὐ προσοιστέον.","st":"403a"},{"sp":"N","t":"Οὐ προσοιστέον ἄρα αὕτη ἡ ἡδονή, οὐδὲ κοινωνητέον αὐτῆς ἐραστῇ τε καὶ παιδικοῖς ὀρθῶς ἐρῶσί τε καὶ ἐρωμένοις;","st":"403b"},{"sp":"N","t":"Οὐ μέντοι μὰ Δί’, ἔφη, ὦ Σώκρατες, προσοιστέον.","st":"403b"},{"sp":"N","t":"Οὕτω δή, ὡς ἔοικε, νομοθετήσεις ἐν τῇ οἰκιζομένῃ πόλει φιλεῖν μὲν καὶ συνεῖναι καὶ ἅπτεσθαι ὥσπερ ὑέος παιδικῶν ἐραστήν, τῶν καλῶν χάριν, ἐὰν πείθῃ, τὰ δ’ ἄλλα οὕτως ὁμιλεῖν πρὸς ὅν τις σπουδάζοι, ὅπως μηδέποτε δόξει μακρότερα","st":"403b"},{"sp":"N","t":"τούτων συγγίγνεσθαι· εἰ δὲ μή, ψόγον ἀμουσίας καὶ ἀπειροκαλίας ὑφέξοντα.","st":"403c"},{"sp":"N","t":"Οὕτως, ἔφη.","st":"403c"},{"sp":"N","t":"Ἆρ’ οὖν, ἦν δ’ ἐγώ, καὶ σοὶ φαίνεται τέλος ἡμῖν ἔχειν ὁ περὶ μουσικῆς λόγος; οἷ γοῦν δεῖ τελευτᾶν, τετελεύτηκεν· δεῖ δέ που τελευτᾶν τὰ μουσικὰ εἰς τὰ τοῦ καλοῦ ἐρωτικά.","st":"403c"},{"sp":"N","t":"Σύμφημι, ἦ δ’ ὅς.","st":"403c"},{"sp":"N","t":"Μετὰ δὴ μουσικὴν γυμναστικῇ θρεπτέοι οἱ νεανίαι.","st":"403c"},{"sp":"N","t":"Τί μήν;","st":"403c"},{"sp":"N","t":"Δεῖ μὲν δὴ καὶ ταύτῃ ἀκριβῶς τρέφεσθαι ἐκ παίδων διὰ","st":"403c"},{"sp":"N","t":"βίου. ἔχει δέ πως, ὡς ἐγᾦμαι, ὧδε· σκόπει δὲ καὶ σύ. ἐμοὶ μὲν γὰρ οὐ φαίνεται, ὃ ἂν χρηστὸν ᾖ σῶμα, τοῦτο τῇ αὑτοῦ ἀρετῇ ψυχὴν ἀγαθὴν ποιεῖν, ἀλλὰ τοὐναντίον ψυχὴ ἀγαθὴ τῇ αὑτῆς ἀρετῇ σῶμα παρέχειν ὡς οἷόν τε βέλτιστον· σοὶ δὲ πῶς φαίνεται;","st":"403d"},{"sp":"N","t":"Καὶ ἐμοί, ἔφη, οὕτως.","st":"403d"},{"sp":"N","t":"Οὐκοῦν εἰ τὴν διάνοιαν ἱκανῶς θεραπεύσαντες παραδοῖμεν αὐτῇ τὰ περὶ τὸ σῶμα ἀκριβολογεῖσθαι, ἡμεῖς δὲ ὅσον τοὺς","st":"403d"},{"sp":"N","t":"τύπους ὑφηγησαίμεθα, ἵνα μὴ μακρολογῶμεν, ὀρθῶς ἂν ποιοῖμεν;","st":"403e"},{"sp":"N","t":"Πάνυ μὲν οὖν.","st":"403e"},{"sp":"N","t":"Μέθης μὲν δὴ εἴπομεν ὅτι ἀφεκτέον αὐτοῖς· παντὶ γάρ που μᾶλλον ἐγχωρεῖ ἢ φύλακι μεθυσθέντι μὴ εἰδέναι ὅπου γῆς ἐστιν.","st":"403e"},{"sp":"N","t":"Γελοῖον γάρ, ἦ δ’ ὅς, τόν γε φύλακα φύλακος δεῖσθαι.","st":"403e"},{"sp":"N","t":"Τί δὲ δὴ σίτων πέρι; ἀθληταὶ μὲν γὰρ οἱ ἄνδρες τοῦ μεγίστου ἀγῶνος. ἢ οὐχί;","st":"403e"},{"sp":"N","t":"Ναί.","st":"403e"},{"sp":"N","t":"Ἆρ’ οὖν ἡ τῶνδε τῶν ἀσκητῶν ἕξις προσήκουσ’ ἂν εἴη τούτοις;","st":"404a"},{"sp":"N","t":"Ἴσως.","st":"404a"},{"sp":"N","t":"Ἀλλ’, ἦν δ’ ἐγώ, ὑπνώδης αὕτη γέ τις καὶ σφαλερὰ πρὸς ὑγίειαν. ἢ οὐχ ὁρᾷς ὅτι καθεύδουσί τε τὸν βίον καί, ἐὰν σμικρὰ ἐκβῶσιν τῆς τεταγμένης διαίτης, μεγάλα καὶ σφόδρα νοσοῦσιν οὗτοι οἱ ἀσκηταί;","st":"404a"},{"sp":"N","t":"Ὁρῶ.","st":"404a"},{"sp":"N","t":"Κομψοτέρας δή τινος, ἦν δ’ ἐγώ, ἀσκήσεως δεῖ τοῖς πολεμικοῖς ἀθληταῖς, οὕς γε ὥσπερ κύνας ἀγρύπνους τε ἀνάγκη εἶναι καὶ ὅτι μάλιστα ὀξὺ ὁρᾶν καὶ ἀκούειν καὶ πολλὰς μεταβολὰς ἐν ταῖς στρατείαις μεταβάλλοντας ὑδάτων τε καὶ τῶν ἄλλων σίτων καὶ εἱλήσεων καὶ χειμώνων μὴ ἀκροσφαλεῖς εἶναι πρὸς ὑγίειαν.","st":"404a"},{"sp":"N","t":"Φαίνεταί μοι.","st":"404a"},{"sp":"N","t":"Ἆρ’ οὖν ἡ βελτίστη γυμναστικὴ ἀδελφή τις ἂν εἴη τῆς ἁπλῆς μουσικῆς ἣν ὀλίγον πρότερον διῇμεν;","st":"404a"},{"sp":"N","t":"Πῶς λέγεις;","st":"404a"},{"sp":"N","t":"Ἁπλῆ που καὶ ἐπιεικὴς γυμναστική, καὶ μάλιστα ἡ τῶν περὶ τὸν πόλεμον.","st":"404a"},{"sp":"N","t":"Πῇ δή;","st":"404a"},{"sp":"N","t":"Καὶ παρ’ Ὁμήρου, ἦν δ’ ἐγώ, τά γε τοιαῦτα μάθοι ἄν τις. οἶσθα γὰρ ὅτι ἐπὶ στρατιᾶς ἐν ταῖς τῶν ἡρώων ἑστιάσεσιν οὔτε ἰχθύσιν αὐτοὺς ἑστιᾷ, καὶ ταῦτα ἐπὶ","st":"404a"},{"sp":"N","t":"θαλάττῃ ἐν Ἑλλησπόντῳ ὄντας, οὔτε ἑφθοῖς κρέασιν ἀλλὰ μόνον ὀπτοῖς, ἃ δὴ μάλιστ’ ἂν εἴη στρατιώταις εὔπορα· πανταχοῦ γὰρ ὡς ἔπος εἰπεῖν αὐτῷ τῷ πυρὶ χρῆσθαι εὐπορώτερον ἢ ἀγγεῖα συμπεριφέρειν.","st":"404c"},{"sp":"N","t":"Καὶ μάλα.","st":"404c"},{"sp":"N","t":"Οὐδὲ μὴν ἡδυσμάτων, ὡς ἐγᾦμαι, Ὅμηρος πώποτε ἐμνήσθη. ἢ τοῦτο μὲν καὶ οἱ ἄλλοι ἀσκηταὶ ἴσασιν, ὅτι τῷ μέλλοντι σώματι εὖ ἕξειν ἀφεκτέον τῶν τοιούτων ἁπάντων;","st":"404c"},{"sp":"N","t":"Καὶ ὀρθῶς γε, ἔφη, ἴσασί τε καὶ ἀπέχονται.","st":"404c"},{"sp":"N","t":"Συρακοσίαν δέ, ὦ φίλε, τράπεζαν καὶ Σικελικὴν ποικιλίαν ὄψου, ὡς ἔοικας, οὐκ αἰνεῖς, εἴπερ σοι ταῦτα δοκεῖ ὀρθῶς ἔχειν.","st":"404d"},{"sp":"N","t":"Οὔ μοι δοκῶ.","st":"404d"},{"sp":"N","t":"Ψέγεις ἄρα καὶ Κορινθίαν κόρην φίλην εἶναι ἀνδράσιν μέλλουσιν εὖ σώματος ἕξειν.","st":"404d"},{"sp":"N","t":"Παντάπασι μὲν οὖν.","st":"404d"},{"sp":"N","t":"Οὐκοῦν καὶ Ἀττικῶν πεμμάτων τὰς δοκούσας εἶναι εὐπαθείας;","st":"404d"},{"sp":"N","t":"Ἀνάγκη.","st":"404d"},{"sp":"N","t":"Ὅλην γὰρ οἶμαι τὴν τοιαύτην σίτησιν καὶ δίαιταν τῇ μελοποιίᾳ τε καὶ ᾠδῇ τῇ ἐν τῷ παναρμονίῳ καὶ ἐν πᾶσι","st":"404d"},{"sp":"N","t":"ῥυθμοῖς πεποιημένῃ ἀπεικάζοντες ὀρθῶς ἂν ἀπεικάζοιμεν.","st":"404e"},{"sp":"N","t":"Πῶς γὰρ οὔ;","st":"404e"},{"sp":"N","t":"Οὐκοῦν ἐκεῖ μὲν ἀκολασίαν ἡ ποικιλία ἐνέτικτεν, ἐνταῦθα δὲ νόσον, ἡ δὲ ἁπλότης κατὰ μὲν μουσικὴν ἐν ψυχαῖς","st":"404e"},{"sp":"N","t":"σωφροσύνην, κατὰ δὲ γυμναστικὴν ἐν σώμασιν ὑγίειαν;","st":"404e"},{"sp":"N","t":"Ἀληθέστατα, ἔφη.","st":"404e"},{"sp":"N","t":"Ἀκολασίας δὲ καὶ νόσων πληθυουσῶν ἐν πόλει ἆρ’ οὐ δικαστήριά τε καὶ ἰατρεῖα πολλὰ ἀνοίγεται, καὶ δικανική τε καὶ ἰατρικὴ σεμνύνονται, ὅταν δὴ καὶ ἐλεύθεροι πολλοὶ καὶ σφόδρα περὶ αὐτὰ σπουδάζωσιν;","st":"405a"},{"sp":"N","t":"Τί γὰρ οὐ μέλλει;","st":"405a"},{"sp":"N","t":"Τῆς δὲ κακῆς τε καὶ αἰσχρᾶς παιδείας ἐν πόλει ἆρα μή τι μεῖζον ἕξεις λαβεῖν τεκμήριον ἢ τὸ δεῖσθαι ἰατρῶν καὶ δικαστῶν ἄκρων μὴ μόνον τοὺς φαύλους τε καὶ χειροτέχνας, ἀλλὰ καὶ τοὺς ἐν ἐλευθέρῳ σχήματι προσποιουμένους τεθράφθαι;","st":"405a"},{"sp":"N","t":"ἢ οὐκ αἰσχρὸν δοκεῖ καὶ ἀπαιδευσίας μέγα τεκμήριον τὸ ἐπακτῷ παρ’ ἄλλων, ὡς δεσποτῶν τε καὶ κριτῶν, τῷ δικαίῳ ἀναγκάζεσθαι χρῆσθαι, καὶ ἀπορίᾳ οἰκείων;","st":"405b"},{"sp":"N","t":"Πάντων μὲν οὖν, ἔφη, αἴσχιστον.","st":"405b"},{"sp":"N","t":"Ἦ δοκεῖ σοι, ἦν δ’ ἐγώ, τούτου αἴσχιον εἶναι τοῦτο, ὅταν δή τις μὴ μόνον τὸ πολὺ τοῦ βίου ἐν δικαστηρίοις φεύγων τε καὶ διώκων κατατρίβηται, ἀλλὰ καὶ ὑπὸ ἀπειροκαλίας ἐπ’ αὐτῷ δὴ τούτῳ πεισθῇ καλλωπίζεσθαι, ὡς δεινὸς","st":"405b"},{"sp":"N","t":"ὢν περὶ τὸ ἀδικεῖν καὶ ἱκανὸς πάσας μὲν στροφὰς στρέφεσθαι, πάσας δὲ διεξόδους διεξελθὼν ἀποστραφῆναι λυγιζόμενος, ὥστε μὴ παρασχεῖν δίκην, καὶ ταῦτα σμικρῶν τε καὶ οὐδενὸς ἀξίων ἕνεκα, ἀγνοῶν ὅσῳ κάλλιον καὶ ἄμεινον τὸ παρασκευάζειν τὸν βίον αὑτῷ μηδὲν δεῖσθαι νυστάζοντος δικαστοῦ;","st":"405c"},{"sp":"N","t":"Οὔκ, ἀλλὰ τοῦτ’, ἔφη, ἐκείνου ἔτι αἴσχιον.","st":"405c"},{"sp":"N","t":"Τὸ δὲ ἰατρικῆς, ἦν δ’ ἐγώ, δεῖσθαι ὅτι μὴ τραυμάτων ἕνεκα ἤ τινων ἐπετείων νοσημάτων ἐπιπεσόντων, ἀλλὰ δι’","st":"405c"},{"sp":"N","t":"ἀργίαν τε καὶ δίαιταν οἵαν διήλθομεν, ῥευμάτων τε καὶ πνευμάτων ὥσπερ λίμνας ἐμπιμπλαμένους φύσας τε καὶ κατάρρους νοσήμασιν ὀνόματα τίθεσθαι ἀναγκάζειν τοὺς κομψοὺς Ἀσκληπιάδας, οὐκ αἰσχρὸν δοκεῖ; Καὶ μάλ’, ἔφη· ὡς ἀληθῶς καινὰ ταῦτα καὶ ἄτοπα νοσημάτων ὀνόματα.","st":"405d"},{"sp":"N","t":"Οἷα, ἦν δ’ ἐγώ, ὡς οἶμαι, οὐκ ἦν ἐπ’ Ἀσκληπιοῦ.","st":"405d"},{"sp":"N","t":"τεκμαίρομαι δέ, ὅτι αὐτοῦ οἱ ὑεῖς ἐν Τροίᾳ Εὐρυπύλῳ τετρωμένῳ ἐπ’ οἶνον Πράμνειον ἄλφιτα πολλὰ ἐπιπασθέντα","st":"405e"},{"sp":"N","t":"καὶ τυρὸν ἐπιξυσθέντα, ἃ δὴ δοκεῖ φλεγματώδη εἶναι, οὐκ ἐμέμψαντο τῇ δούσῃ πιεῖν, οὐδὲ Πατρόκλῳ τῷ ἰωμένῳ ἐπετίμησαν.","st":"406a"},{"sp":"N","t":"Καὶ μὲν δή, ἔφη, ἄτοπόν γε τὸ πῶμα οὕτως ἔχοντι.","st":"406a"},{"sp":"N","t":"Οὔκ, εἴ γ’ ἐννοεῖς, εἶπον, ὅτι τῇ παιδαγωγικῇ τῶν νοσημάτων ταύτῃ τῇ νῦν ἰατρικῇ πρὸ τοῦ Ἀσκληπιάδαι οὐκ ἐχρῶντο, ὥς φασι, πρὶν Ἡρόδικον γενέσθαι· Ἡρόδικος δὲ παιδοτρίβης ὢν καὶ νοσώδης γενόμενος, μείξας γυμναστικὴν","st":"406a"},{"sp":"N","t":"ἰατρικῇ, ἀπέκναισε πρῶτον μὲν καὶ μάλιστα ἑαυτόν, ἔπειτ’ ἄλλους ὕστερον πολλούς.","st":"406b"},{"sp":"N","t":"Πῇ δή; ἔφη.","st":"406b"},{"sp":"N","t":"Μακρόν, ἦν δ’ ἐγώ, τὸν θάνατον αὑτῷ ποιήσας. παρακολουθῶν γὰρ τῷ νοσήματι θανασίμῳ ὄντι οὔτε ἰάσασθαι οἶμαι οἷός τ’ ἦν ἑαυτόν, ἐν ἀσχολίᾳ τε πάντων ἰατρευόμενος διὰ βίου ἔζη, ἀποκναιόμενος εἴ τι τῆς εἰωθυίας διαίτης ἐκβαίη, δυσθανατῶν δὲ ὑπὸ σοφίας εἰς γῆρας ἀφίκετο.","st":"406b"},{"sp":"N","t":"Καλὸν ἄρα τὸ γέρας, ἔφη, τῆς τέχνης ἠνέγκατο.","st":"406b"},{"sp":"N","t":"Οἷον εἰκός, ἦν δ’ ἐγώ, τὸν μὴ εἰδότα ὅτι Ἀσκληπιὸς οὐκ ἀγνοίᾳ οὐδὲ ἀπειρίᾳ τούτου τοῦ εἴδους τῆς ἰατρικῆς τοῖς ἐκγόνοις οὐ κατέδειξεν αὐτό, ἀλλ’ εἰδὼς ὅτι πᾶσι τοῖς εὐνομουμένοις ἔργον τι ἑκάστῳ ἐν τῇ πόλει προστέτακται, ὃ ἀναγκαῖον ἐργάζεσθαι, καὶ οὐδενὶ σχολὴ διὰ βίου κάμνειν ἰατρευομένῳ. ὃ ἡμεῖς γελοίως ἐπὶ μὲν τῶν δημιουργῶν αἰσθανόμεθα, ἐπὶ δὲ τῶν πλουσίων τε καὶ εὐδαιμόνων δοκούντων εἶναι οὐκ αἰσθανόμεθα.","st":"406c"},{"sp":"N","t":"Πῶς; ἔφη.","st":"406c"},{"sp":"N","t":"Τέκτων μέν, ἦν δ’ ἐγώ, κάμνων ἀξιοῖ παρὰ τοῦ ἰατροῦ φάρμακον πιὼν ἐξεμέσαι τὸ νόσημα, ἢ κάτω καθαρθεὶς ἢ καύσει ἢ τομῇ χρησάμενος ἀπηλλάχθαι· ἐὰν δέ τις αὐτῷ μακρὰν δίαιταν προστάττῃ, πιλίδιά τε περὶ τὴν κεφαλὴν περιτιθεὶς καὶ τὰ τούτοις ἑπόμενα, ταχὺ εἶπεν ὅτι οὐ σχολὴ κάμνειν οὐδὲ λυσιτελεῖ οὕτω ζῆν, νοσήματι τὸν νοῦν προσέχοντα, τῆς δὲ προκειμένης ἐργασίας ἀμελοῦντα. καὶ μετὰ ταῦτα χαίρειν","st":"406d"},{"sp":"N","t":"εἰπὼν τῷ τοιούτῳ ἰατρῷ, εἰς τὴν εἰωθυῖαν δίαιταν ἐμβάς, ὑγιὴς γενόμενος ζῇ τὰ ἑαυτοῦ πράττων· ἐὰν δὲ μὴ ἱκανὸν ᾖ τὸ σῶμα ὑπενεγκεῖν, τελευτήσας πραγμάτων ἀπηλλάγη.","st":"406e"},{"sp":"N","t":"Καὶ τῷ τοιούτῳ μέν γ’, ἔφη, δοκεῖ πρέπειν οὕτω ἰατρικῇ χρῆσθαι.","st":"406e"},{"sp":"N","t":"Ἆρα, ἦν δ’ ἐγώ, ὅτι ἦν τι αὐτῷ ἔργον, ὃ εἰ μὴ πράττοι, οὐκ ἐλυσιτέλει ζῆν;","st":"407a"},{"sp":"N","t":"Δῆλον, ἔφη.","st":"407a"},{"sp":"N","t":"Ὁ δὲ δὴ πλούσιος, ὥς φαμεν, οὐδὲν ἔχει τοιοῦτον ἔργον προκείμενον, οὗ ἀναγκαζομένῳ ἀπέχεσθαι ἀβίωτον.","st":"407a"},{"sp":"N","t":"Οὔκουν δὴ λέγεταί γε.","st":"407a"},{"sp":"N","t":"Φωκυλίδου γάρ, ἦν δ’ ἐγώ, οὐκ ἀκούεις πῶς φησι δεῖν, ὅταν τῳ ἤδη βίος ᾖ, ἀρετὴν ἀσκεῖν.","st":"407a"},{"sp":"N","t":"Οἶμαι δέ γε, ἔφη, καὶ πρότερον.","st":"407a"},{"sp":"N","t":"Μηδέν, εἶπον, περὶ τούτου αὐτῷ μαχώμεθα, ἀλλ’ ἡμᾶς αὐτοὺς διδάξωμεν πότερον μελετητέον τοῦτο τῷ πλουσίῳ","st":"407a"},{"sp":"N","t":"καὶ ἀβίωτον τῷ μὴ μελετῶντι, ἢ νοσοτροφία τεκτονικῇ μὲν καὶ ταῖς ἄλλαις τέχναις ἐμπόδιον τῇ προσέξει τοῦ νοῦ, τὸ δὲ Φωκυλίδου παρακέλευμα οὐδὲν ἐμποδίζει.","st":"407b"},{"sp":"N","t":"Ναὶ μὰ τὸν Δία, ἦ δ’ ὅς. σχεδόν γέ τι πάντων μάλιστα ἥ γε περαιτέρω γυμναστικῆς ἡ περιττὴ αὕτη ἐπιμέλεια τοῦ σώματος· καὶ γὰρ πρὸς οἰκονομίας καὶ πρὸς στρατείας καὶ πρὸς ἑδραίους ἐν πόλει ἀρχὰς δύσκολος.","st":"407b"},{"sp":"N","t":"Τὸ δὲ δὴ μέγιστον, ὅτι καὶ πρὸς μαθήσεις ἁστινασοῦν καὶ","st":"407b"},{"sp":"N","t":"ἐννοήσεις τε καὶ μελέτας πρὸς ἑαυτὸν χαλεπή, κεφαλῆς τινας ἀεὶ διατάσεις καὶ ἰλίγγους ὑποπτεύουσα καὶ αἰτιωμένη ἐκ φιλοσοφίας ἐγγίγνεσθαι, ὥστε, ὅπῃ ταύτῃ ἀρετὴ ἀσκεῖται καὶ δοκιμάζεται, πάντῃ ἐμπόδιος· κάμνειν γὰρ οἴεσθαι ποιεῖ ἀεὶ καὶ ὠδίνοντα μήποτε λήγειν περὶ τοῦ σώματος.","st":"407c"},{"sp":"N","t":"Εἰκός γε, ἔφη.","st":"407c"},{"sp":"N","t":"Οὐκοῦν ταῦτα γιγνώσκοντα φῶμεν καὶ Ἀσκληπιὸν τοὺς μὲν φύσει τε καὶ διαίτῃ ὑγιεινῶς ἔχοντας τὰ σώματα,","st":"407c"},{"sp":"N","t":"νόσημα δέ τι ἀποκεκριμένον ἴσχοντας ἐν αὑτοῖς, τούτοις μὲν καὶ ταύτῃ τῇ ἕξει καταδεῖξαι ἰατρικήν, φαρμάκοις τε καὶ τομαῖς τὰ νοσήματα ἐκβάλλοντα αὐτῶν τὴν εἰωθυῖαν προστάττειν δίαιταν, ἵνα μὴ τὰ πολιτικὰ βλάπτοι, τὰ δ’ εἴσω διὰ παντὸς νενοσηκότα σώματα οὐκ ἐπιχειρεῖν διαίταις κατὰ σμικρὸν ἀπαντλοῦντα καὶ ἐπιχέοντα μακρὸν καὶ κακὸν βίον ἀνθρώπῳ ποιεῖν, καὶ ἔκγονα αὐτῶν, ὡς τὸ εἰκός, ἕτερα τοιαῦτα φυτεύειν, ἀλλὰ τὸν μὴ δυνάμενον ἐν τῇ καθεστηκυίᾳ","st":"407d"},{"sp":"N","t":"περιόδῳ ζῆν μὴ οἴεσθαι δεῖν θεραπεύειν, ὡς οὔτε αὑτῷ οὔτε πόλει λυσιτελῆ;","st":"407e"},{"sp":"N","t":"Πολιτικόν, ἔφη, λέγεις Ἀσκληπιόν.","st":"407e"},{"sp":"N","t":"Δῆλον, ἦν δ’ ἐγώ· καὶ οἱ παῖδες αὐτοῦ, ὅτι τοιοῦτος ἦν,","st":"407e"},{"sp":"N","t":"οὐχ ὁρᾷς ὡς καὶ ἐν Τροίᾳ ἀγαθοὶ πρὸς τὸν πόλεμον ἐφάνησαν, καὶ τῇ ἰατρικῇ, ὡς ἐγὼ λέγω, ἐχρῶντο; ἢ οὐ μέμνησαι ὅτι καὶ τῷ Μενέλεῳ ἐκ τοῦ τραύματος οὗ ὁ Πάνδαρος ἔβαλεν —","st":"408a"},{"sp":"N","t":"αἷμ’ ἐκμυζήσαντες ἐπ’ ἤπια φάρμακ’ ἔπασσον,","st":"408a"},{"sp":"N","t":"ὅτι δ’ ἐχρῆν μετὰ τοῦτο ἢ πιεῖν ἢ φαγεῖν οὐδὲν μᾶλλον ἢ τῷ Εὐρυπύλῳ προσέταττον, ὡς ἱκανῶν ὄντων τῶν φαρμάκων ἰάσασθαι ἄνδρας πρὸ τῶν τραυμάτων ὑγιεινούς τε καὶ","st":"408a"},{"sp":"N","t":"κοσμίους ἐν διαίτῃ, κἂν εἰ τύχοιεν ἐν τῷ παραχρῆμα κυκεῶνα πιόντες, νοσώδη δὲ φύσει τε καὶ ἀκόλαστον οὔτε αὐτοῖς οὔτε τοῖς ἄλλοις ᾤοντο λυσιτελεῖν ζῆν, οὐδ’ ἐπὶ τούτοις τὴν τέχνην δεῖν εἶναι, οὐδὲ θεραπευτέον αὐτούς, οὐδ’ εἰ Μίδου πλουσιώτεροι εἶεν.","st":"408b"},{"sp":"N","t":"Πάνυ κομψούς, ἔφη, λέγεις Ἀσκληπιοῦ παῖδας.","st":"408b"},{"sp":"N","t":"Πρέπει, ἦν δ’ ἐγώ, καίτοι ἀπειθοῦντές γε ἡμῖν οἱ τραγῳδοποιοί τε καὶ Πίνδαρος Ἀπόλλωνος μέν φασιν Ἀσκληπιὸν εἶναι, ὑπὸ δὲ χρυσοῦ πεισθῆναι πλούσιον ἄνδρα θανάσιμον","st":"408b"},{"sp":"N","t":"ἤδη ὄντα ἰάσασθαι, ὅθεν δὴ καὶ κεραυνωθῆναι αὐτόν. ἡμεῖς δὲ κατὰ τὰ προειρημένα οὐ πεισόμεθα αὐτοῖς ἀμφότερα, ἀλλ’ εἰ μὲν θεοῦ ἦν, οὐκ ἦν, φήσομεν, αἰσχροκερδής· εἰ δ’ αἰσχροκερδής, οὐκ ἦν θεοῦ.","st":"408c"},{"sp":"N","t":"Ὀρθότατα, ἦ δ’ ὅς, ταῦτά γε. ἀλλὰ περὶ τοῦδε τί λέγεις, ὦ Σώκρατες; ἆρ’ οὐκ ἀγαθοὺς δεῖ ἐν τῇ πόλει κεκτῆσθαι ἰατρούς; εἶεν δ’ ἄν που μάλιστα τοιοῦτοι ὅσοι","st":"408c"},{"sp":"N","t":"πλείστους μὲν ὑγιεινούς, πλείστους δὲ νοσώδεις μετεχειρίσαντο, καὶ δικασταὶ αὖ ὡσαύτως οἱ παντοδαπαῖς φύσεσιν ὡμιληκότες.","st":"408d"},{"sp":"N","t":"Καὶ μάλα, εἶπον, ἀγαθοὺς λέγω. ἀλλ’ οἶσθα οὓς ἡγοῦμαι τοιούτους;","st":"408d"},{"sp":"N","t":"Ἂν εἴπῃς, ἔφη.","st":"408d"},{"sp":"N","t":"Ἀλλὰ πειράσομαι, ἦν δ’ ἐγώ· σὺ μέντοι οὐχ ὅμοιον πρᾶγμα τῷ αὐτῷ λόγῳ ἤρου.","st":"408d"},{"sp":"N","t":"Πῶς; ἔφη.","st":"408d"},{"sp":"N","t":"Ἰατροὶ μέν, εἶπον, δεινότατοι ἂν γένοιντο, εἰ ἐκ παίδων ἀρξάμενοι πρὸς τῷ μανθάνειν τὴν τέχνην ὡς πλείστοις τε καὶ πονηροτάτοις σώμασιν ὁμιλήσειαν καὶ αὐτοὶ πάσας","st":"408d"},{"sp":"N","t":"νόσους κάμοιεν καὶ εἶεν μὴ πάνυ ὑγιεινοὶ φύσει. οὐ γὰρ οἶμαι σώματι σῶμα θεραπεύουσιν — οὐ γὰρ ἂν αὐτὰ ἐνεχώρει κακὰ εἶναί ποτε καὶ γενέσθαι — ἀλλὰ ψυχῇ σῶμα, ᾗ οὐκ ἐγχωρεῖ κακὴν γενομένην τε καὶ οὖσαν εὖ τι θεραπεύειν.","st":"408e"},{"sp":"N","t":"Ὀρθῶς, ἔφη.","st":"408e"},{"sp":"N","t":"Δικαστὴς δέ γε, ὦ φίλε, ψυχῇ ψυχῆς ἄρχει, ᾗ οὐκ ἐγχωρεῖ ἐκ νέας ἐν πονηραῖς ψυχαῖς τεθράφθαι τε καὶ ὡμιληκέναι καὶ πάντα ἀδικήματα αὐτὴν ἠδικηκυῖαν διεξεληλυθέναι, ὥστε ὀξέως ἀφ’ αὑτῆς τεκμαίρεσθαι τὰ τῶν ἄλλων ἀδικήματα οἷον κατὰ σῶμα νόσους· ἀλλ’ ἄπειρον αὐτὴν καὶ ἀκέραιον δεῖ κακῶν ἠθῶν νέαν οὖσαν γεγονέναι, εἰ μέλλει καλὴ κἀγαθὴ οὖσα κρινεῖν ὑγιῶς τὰ δίκαια. διὸ δὴ καὶ εὐήθεις νέοι ὄντες οἱ ἐπιεικεῖς φαίνονται καὶ εὐεξαπάτητοι","st":"409a"},{"sp":"N","t":"ὑπὸ τῶν ἀδίκων, ἅτε οὐκ ἔχοντες ἐν ἑαυτοῖς παραδείγματα ὁμοιοπαθῆ τοῖς πονηροῖς.","st":"409b"},{"sp":"N","t":"Καὶ μὲν δή, ἔφη, σφόδρα γε αὐτὸ πάσχουσι.","st":"409b"},{"sp":"N","t":"Τῷ τοι, ἦν δ’ ἐγώ, οὐ νέον ἀλλὰ γέροντα δεῖ τὸν ἀγαθὸν δικαστὴν εἶναι, ὀψιμαθῆ γεγονότα τῆς ἀδικίας οἷόν ἐστιν, οὐκ οἰκείαν ἐν τῇ αὑτοῦ ψυχῇ ἐνοῦσαν ᾐσθημένον, ἀλλ’ ἀλλοτρίαν ἐν ἀλλοτρίαις μεμελετηκότα ἐν πολλῷ χρόνῳ διαισθάνεσθαι οἷον πέφυκε κακόν, ἐπιστήμῃ, οὐκ","st":"409b"},{"sp":"N","t":"ἐμπειρίᾳ οἰκείᾳ κεχρημένον.","st":"409c"},{"sp":"N","t":"Γενναιότατος γοῦν, ἔφη, ἔοικεν εἶναι ὁ τοιοῦτος δικαστής.","st":"409c"},{"sp":"N","t":"Καὶ ἀγαθός γε, ἦν δ’ ἐγώ, ὃ σὺ ἠρώτας· ὁ γὰρ ἔχων ψυχὴν ἀγαθὴν ἀγαθός. ὁ δὲ δεινὸς ἐκεῖνος καὶ καχύποπτος, ὁ πολλὰ αὐτὸς ἠδικηκὼς καὶ πανοῦργός τε καὶ σοφὸς οἰόμενος εἶναι, ὅταν μὲν ὁμοίοις ὁμιλῇ, δεινὸς φαίνεται ἐξευλαβούμενος, πρὸς τὰ ἐν αὑτῷ παραδείγματα ἀποσκοπῶν· ὅταν δὲ ἀγαθοῖς καὶ πρεσβυτέροις ἤδη πλησιάσῃ, ἀβέλτερος","st":"409c"},{"sp":"N","t":"αὖ φαίνεται, ἀπιστῶν παρὰ καιρὸν καὶ ἀγνοῶν ὑγιὲς ἦθος, ἅτε οὐκ ἔχων παράδειγμα τοῦ τοιούτου. πλεονάκις δὲ πονηροῖς ἢ χρηστοῖς ἐντυγχάνων σοφώτερος ἢ ἀμαθέστερος δοκεῖ εἶναι αὑτῷ τε καὶ ἄλλοις.","st":"409d"},{"sp":"N","t":"Παντάπασι μὲν οὖν, ἔφη, ἀληθῆ.","st":"409d"},{"sp":"N","t":"Οὐ τοίνυν, ἦν δ’ ἐγώ, τοιοῦτον χρὴ τὸν δικαστὴν ζητεῖν τὸν ἀγαθόν τε καὶ σοφόν, ἀλλὰ τὸν πρότερον· πονηρία μὲν γὰρ ἀρετήν τε καὶ αὑτὴν οὔποτ’ ἂν γνοίη, ἀρετὴ δὲ φύσεως παιδευομένης χρόνῳ ἅμα αὑτῆς τε καὶ πονηρίας ἐπιστήμην","st":"409d"},{"sp":"N","t":"λήψεται. σοφὸς οὖν οὗτος, ὥς μοι δοκεῖ, ἀλλ’ οὐχ ὁ κακὸς γίγνεται.","st":"409e"},{"sp":"N","t":"Καὶ ἐμοί, ἔφη, συνδοκεῖ.","st":"409e"},{"sp":"N","t":"Οὐκοῦν καὶ ἰατρικήν, οἵαν εἴπομεν, μετὰ τῆς τοιαύτης δικαστικῆς κατὰ πόλιν νομοθετήσεις, αἳ τῶν πολιτῶν σοι","st":"409e"},{"sp":"N","t":"τοὺς μὲν εὐφυεῖς τὰ σώματα καὶ τὰς ψυχὰς θεραπεύσουσι, τοὺς δὲ μή, ὅσοι μὲν κατὰ σῶμα τοιοῦτοι, ἀποθνῄσκειν ἐάσουσιν, τοὺς δὲ κατὰ τὴν ψυχὴν κακοφυεῖς καὶ ἀνιάτους αὐτοὶ ἀποκτενοῦσιν;","st":"410a"},{"sp":"N","t":"Τὸ γοῦν ἄριστον, ἔφη, αὐτοῖς τε τοῖς πάσχουσιν καὶ τῇ πόλει οὕτω πέφανται.","st":"410a"},{"sp":"N","t":"Οἱ δὲ δὴ νέοι, ἦν δ’ ἐγώ, δῆλον ὅτι εὐλαβήσονταί σοι δικαστικῆς εἰς χρείαν ἰέναι, τῇ ἁπλῇ ἐκείνῃ μουσικῇ χρώμενοι ἣν δὴ ἔφαμεν σωφροσύνην ἐντίκτειν.","st":"410a"},{"sp":"N","t":"Τί μήν; ἔφη.","st":"410a"},{"sp":"N","t":"Ἆρ’ οὖν οὐ κατὰ ταὐτὰ ἴχνη ταῦτα ὁ μουσικὸς γυμναστικὴν διώκων, ἐὰν ἐθέλῃ, αἱρήσει, ὥστε μηδὲν ἰατρικῆς δεῖσθαι ὅτι μὴ ἀνάγκη;","st":"410b"},{"sp":"N","t":"Ἔμοιγε δοκεῖ.","st":"410b"},{"sp":"N","t":"Αὐτά γε μὴν τὰ γυμνάσια καὶ τοὺς πόνους πρὸς τὸ θυμοειδὲς τῆς φύσεως βλέπων κἀκεῖνο ἐγείρων πονήσει μᾶλλον ἢ πρὸς ἰσχύν, οὐχ ὥσπερ οἱ ἄλλοι ἀθληταὶ ῥώμης ἕνεκα σιτία καὶ πόνους μεταχειριεῖται.","st":"410b"},{"sp":"N","t":"Ὀρθότατα, ἦ δ’ ὅς.","st":"410b"},{"sp":"N","t":"Ἆρ’ οὖν, ἦν δ’ ἐγώ, ὦ Γλαύκων, καὶ οἱ καθιστάντες","st":"410b"},{"sp":"N","t":"μουσικῇ καὶ γυμναστικῇ παιδεύειν οὐχ οὗ ἕνεκά τινες οἴονται καθιστᾶσιν, ἵνα τῇ μὲν τὸ σῶμα θεραπεύοιντο, τῇ δὲ τὴν ψυχήν;","st":"410c"},{"sp":"N","t":"Ἀλλὰ τί μήν; ἔφη.","st":"410c"},{"sp":"N","t":"Κινδυνεύουσιν, ἦν δ’ ἐγώ, ἀμφότερα τῆς ψυχῆς ἕνεκα τὸ μέγιστον καθιστάναι.","st":"410c"},{"sp":"N","t":"Πῶς δή;","st":"410c"},{"sp":"N","t":"Οὐκ ἐννοεῖς, εἶπον, ὡς διατίθενται αὐτὴν τὴν διάνοιαν οἳ ἂν γυμναστικῇ μὲν διὰ βίου ὁμιλήσωσιν, μουσικῆς δὲ μὴ ἅψωνται; ἢ αὖ ὅσοι ἂν τοὐναντίον διατεθῶσιν;","st":"410c"},{"sp":"N","t":"Τίνος δέ, ἦ δ’ ὅς, πέρι λέγεις;","st":"410c"},{"sp":"N","t":"Ἀγριότητός τε καὶ σκληρότητος, καὶ αὖ μαλακίας τε καὶ ἡμερότητος, ἦν δ’ ἐγώ —","st":"410d"},{"sp":"N","t":"Ἔγωγε, ἔφη· ὅτι οἱ μὲν γυμναστικῇ ἀκράτῳ χρησάμενοι ἀγριώτεροι τοῦ δέοντος ἀποβαίνουσιν, οἱ δὲ μουσικῇ μαλακώτεροι αὖ γίγνονται ἢ ὡς κάλλιον αὐτοῖς.","st":"410d"},{"sp":"N","t":"Καὶ μήν, ἦν δ’ ἐγώ, τό γε ἄγριον τὸ θυμοειδὲς ἂν τῆς φύσεως παρέχοιτο, καὶ ὀρθῶς μὲν τραφὲν ἀνδρεῖον ἂν εἴη, μᾶλλον δ’ ἐπιταθὲν τοῦ δέοντος σκληρόν τε καὶ χαλεπὸν γίγνοιτ’ ἄν, ὡς τὸ εἰκός.","st":"410d"},{"sp":"N","t":"Δοκεῖ μοι, ἔφη.","st":"410d"},{"sp":"N","t":"Τί δέ; τὸ ἥμερον οὐχ ἡ φιλόσοφος ἂν ἔχοι φύσις, καὶ μᾶλλον μὲν ἀνεθέντος αὐτοῦ μαλακώτερον εἴη τοῦ δέοντος, καλῶς δὲ τραφέντος ἥμερόν τε καὶ κόσμιον;","st":"410e"},{"sp":"N","t":"Ἔστι ταῦτα.","st":"410e"},{"sp":"N","t":"Δεῖν δέ γέ φαμεν τοὺς φύλακας ἀμφοτέρα ἔχειν τούτω τὼ φύσει.","st":"410e"},{"sp":"N","t":"Δεῖ γάρ.","st":"410e"},{"sp":"N","t":"Οὐκοῦν ἡρμόσθαι δεῖ αὐτὰς πρὸς ἀλλήλας;","st":"410e"},{"sp":"N","t":"Πῶς δ’ οὔ;","st":"410e"},{"sp":"N","t":"Καὶ τοῦ μὲν ἡρμοσμένου σώφρων τε καὶ ἀνδρεία ἡ","st":"410e"},{"sp":"N","t":"ψυχή;","st":"411a"},{"sp":"N","t":"Πάνυ γε.","st":"411a"},{"sp":"N","t":"Τοῦ δὲ ἀναρμόστου δειλὴ καὶ ἄγροικος;","st":"411a"},{"sp":"N","t":"Καὶ μάλα.","st":"411a"},{"sp":"N","t":"Οὐκοῦν ὅταν μέν τις μουσικῇ παρέχῃ καταυλεῖν καὶ καταχεῖν τῆς ψυχῆς διὰ τῶν ὤτων ὥσπερ διὰ χώνης ἃς νυνδὴ ἡμεῖς ἐλέγομεν τὰς γλυκείας τε καὶ μαλακὰς καὶ θρηνώδεις ἁρμονίας, καὶ μινυρίζων τε καὶ γεγανωμένος ὑπὸ τῆς ᾠδῆς διατελῇ τὸν βίον ὅλον, οὗτος τὸ μὲν πρῶτον, εἴ τι θυμοειδὲς εἶχεν, ὥσπερ σίδηρον ἐμάλαξεν καὶ χρήσιμον","st":"411a"},{"sp":"N","t":"ἐξ ἀχρήστου καὶ σκληροῦ ἐποίησεν· ὅταν δ’ ἐπέχων μὴ ἀνιῇ ἀλλὰ κηλῇ, τὸ δὴ μετὰ τοῦτο ἤδη τήκει καὶ λείβει, ἕως ἂν ἐκτήξῃ τὸν θυμὸν καὶ ἐκτέμῃ ὥσπερ νεῦρα ἐκ τῆς ψυχῆς καὶ ποιήσῃ “μαλθακὸν αἰχμητήν.”","st":"411b"},{"sp":"N","t":"Πάνυ μὲν οὖν, ἔφη.","st":"411b"},{"sp":"N","t":"Καὶ ἐὰν μέν γε, ἦν δ’ ἐγώ, ἐξ ἀρχῆς φύσει ἄθυμον λάβῃ, ταχὺ τοῦτο διεπράξατο· ἐὰν δὲ θυμοειδῆ, ἀσθενῆ ποιήσας τὸν θυμὸν ὀξύρροπον ἀπηργάσατο, ἀπὸ σμικρῶν ταχὺ ἐρεθιζόμενόν","st":"411b"},{"sp":"N","t":"τε καὶ κατασβεννύμενον. ἀκράχολοι οὖν καὶ ὀργίλοι ἀντὶ θυμοειδοῦς γεγένηνται, δυσκολίας ἔμπλεῳ.","st":"411c"},{"sp":"N","t":"Κομιδῇ μὲν οὖν.","st":"411c"},{"sp":"N","t":"Τί δὲ ἂν αὖ γυμναστικῇ πολλὰ πονῇ καὶ εὐωχῆται εὖ μάλα, μουσικῆς δὲ καὶ φιλοσοφίας μὴ ἅπτηται; οὐ πρῶτον μὲν εὖ ἴσχων τὸ σῶμα φρονήματός τε καὶ θυμοῦ ἐμπίμπλαται καὶ ἀνδρειότερος γίγνεται αὐτὸς αὑτοῦ;","st":"411c"},{"sp":"N","t":"Καὶ μάλα γε.","st":"411c"},{"sp":"N","t":"Τί δὲ ἐπειδὰν ἄλλο μηδὲν πράττῃ μηδὲ κοινωνῇ Μούσης","st":"411c"},{"sp":"N","t":"μηδαμῇ; οὐκ εἴ τι καὶ ἐνῆν αὐτοῦ φιλομαθὲς ἐν τῇ ψυχῇ, ἅτε οὔτε μαθήματος γευόμενον οὐδενὸς οὔτε ζητήματος, οὔτε λόγου μετίσχον οὔτε τῆς ἄλλης μουσικῆς, ἀσθενές τε καὶ κωφὸν καὶ τυφλὸν γίγνεται, ἅτε οὐκ ἐγειρόμενον οὐδὲ τρεφόμενον οὐδὲ διακαθαιρομένων τῶν αἰσθήσεων αὐτοῦ;","st":"411d"},{"sp":"N","t":"Οὕτως, ἔφη.","st":"411d"},{"sp":"N","t":"Μισόλογος δὴ οἶμαι ὁ τοιοῦτος γίγνεται καὶ ἄμουσος, καὶ πειθοῖ μὲν διὰ λόγων οὐδὲν ἔτι χρῆται, βίᾳ δὲ καὶ","st":"411d"},{"sp":"N","t":"ἀγριότητι ὥσπερ θηρίον πρὸς πάντα διαπράττεται, καὶ ἐν ἀμαθίᾳ καὶ σκαιότητι μετὰ ἀρρυθμίας τε καὶ ἀχαριστίας ζῇ.","st":"411e"},{"sp":"N","t":"Παντάπασιν, ἦ δ’ ὅς, οὕτως ἔχει.","st":"411e"},{"sp":"N","t":"Ἐπὶ δὴ δύ’ ὄντε τούτω, ὡς ἔοικε, δύο τέχνα θεὸν ἔγωγ’ ἄν τινα φαίην δεδωκέναι τοῖς ἀνθρώποις, μουσικήν τε καὶ γυμναστικὴν ἐπὶ τὸ θυμοειδὲς καὶ τὸ φιλόσοφον, οὐκ ἐπὶ ψυχὴν καὶ σῶμα, εἰ μὴ εἰ πάρεργον, ἀλλ’ ἐπ’ ἐκείνω, ὅπως","st":"411e"},{"sp":"N","t":"ἂν ἀλλήλοιν συναρμοσθῆτον ἐπιτεινομένω καὶ ἀνιεμένω μέχρι τοῦ προσήκοντος.","st":"412a"},{"sp":"N","t":"Καὶ γὰρ ἔοικεν, ἔφη.","st":"412a"},{"sp":"N","t":"Τὸν κάλλιστ’ ἄρα μουσικῇ γυμναστικὴν κεραννύντα καὶ μετριώτατα τῇ ψυχῇ προσφέροντα, τοῦτον ὀρθότατ’ ἂν φαῖμεν εἶναι τελέως μουσικώτατον καὶ εὐαρμοστότατον, πολὺ μᾶλλον ἢ τὸν τὰς χορδὰς ἀλλήλαις συνιστάντα.","st":"412a"},{"sp":"N","t":"Εἰκότως γ’, ἔφη, ὦ Σώκρατες.","st":"412a"},{"sp":"N","t":"Οὐκοῦν καὶ ἐν τῇ πόλει ἡμῖν, ὦ Γλαύκων, δεήσει τοῦ τοιούτου τινὸς ἀεὶ ἐπιστάτου, εἰ μέλλει ἡ πολιτεία σῴζεσθαι;","st":"412a"},{"sp":"N","t":"Δεήσει μέντοι ὡς οἷόν τέ γε μάλιστα.","st":"412b"},{"sp":"N","t":"Οἱ μὲν δὴ τύποι τῆς παιδείας τε καὶ τροφῆς οὗτοι ἂν εἶεν. χορείας γὰρ τί ἄν τις διεξίοι τῶν τοιούτων καὶ θήρας τε καὶ κυνηγέσια καὶ γυμνικοὺς ἀγῶνας καὶ ἱππικούς; σχεδὸν γάρ τι δῆλα δὴ ὅτι τούτοις ἑπόμενα δεῖ αὐτὰ εἶναι, καὶ οὐκέτι χαλεπὰ εὑρεῖν.","st":"412b"},{"sp":"N","t":"Ἴσως, ἦ δ’ ὅς, οὐ χαλεπά.","st":"412b"},{"sp":"N","t":"Εἶεν, ἦν δ’ ἐγώ· τὸ δὴ μετὰ τοῦτο τί ἂν ἡμῖν διαιρετέον εἴη; ἆρ’ οὐκ αὐτῶν τούτων οἵτινες ἄρξουσί τε καὶ ἄρξονται;","st":"412b"},{"sp":"N","t":"Τί μήν;","st":"412c"},{"sp":"N","t":"Οὐκοῦν ὅτι μὲν πρεσβυτέρους τοὺς ἄρχοντας δεῖ εἶναι, νεωτέρους δὲ τοὺς ἀρχομένους, δῆλον;","st":"412c"},{"sp":"N","t":"Δῆλον.","st":"412c"},{"sp":"N","t":"Καὶ ὅτι γε τοὺς ἀρίστους αὐτῶν;","st":"412c"},{"sp":"N","t":"Καὶ τοῦτο.","st":"412c"},{"sp":"N","t":"Οἱ δὲ γεωργῶν ἄριστοι ἆρ’ οὐ γεωργικώτατοι γίγνονται;","st":"412c"},{"sp":"N","t":"Ναί.","st":"412c"},{"sp":"N","t":"Νῦν δ’, ἐπειδὴ φυλάκων αὐτοὺς ἀρίστους δεῖ εἶναι, ἆρ’ οὐ φυλακικωτάτους πόλεως;","st":"412c"},{"sp":"N","t":"Ναί.","st":"412c"},{"sp":"N","t":"Οὐκοῦν φρονίμους τε εἰς τοῦτο δεῖ ὑπάρχειν καὶ δυνατοὺς καὶ ἔτι κηδεμόνας τῆς πόλεως;","st":"412c"},{"sp":"N","t":"Ἔστι ταῦτα.","st":"412d"},{"sp":"N","t":"Κήδοιτο δέ γ’ ἄν τις μάλιστα τούτου ὃ τυγχάνοι φιλῶν.","st":"412d"},{"sp":"N","t":"Ἀνάγκη.","st":"412d"},{"sp":"N","t":"Καὶ μὴν τοῦτό γ’ ἂν μάλιστα φιλοῖ, ᾧ συμφέρειν ἡγοῖτο τὰ αὐτὰ καὶ ἑαυτῷ καὶ [ὅταν μάλιστα] ἐκείνου μὲν εὖ πράττοντος οἴοιτο συμβαίνειν καὶ ἑαυτῷ εὖ πράττειν, μὴ δέ, τοὐναντίον.","st":"412d"},{"sp":"N","t":"Οὕτως, ἔφη.","st":"412d"},{"sp":"N","t":"Ἐκλεκτέον ἄρ’ ἐκ τῶν ἄλλων φυλάκων τοιούτους ἄνδρας, οἳ ἂν σκοποῦσιν ἡμῖν μάλιστα φαίνωνται παρὰ πάντα τὸν","st":"412d"},{"sp":"N","t":"βίον, ὃ μὲν ἂν τῇ πόλει ἡγήσωνται συμφέρειν, πάσῃ προθυμίᾳ ποιεῖν, ὃ δ’ ἂν μή, μηδενὶ τρόπῳ πρᾶξαι ἂν ἐθέλειν.","st":"412e"},{"sp":"N","t":"Ἐπιτήδειοι γάρ, ἔφη.","st":"412e"},{"sp":"N","t":"Δοκεῖ δή μοι τηρητέον αὐτοὺς εἶναι ἐν ἁπάσαις ταῖς ἡλικίαις, εἰ φυλακικοί εἰσι τούτου τοῦ δόγματος καὶ μήτε γοητευόμενοι μήτε βιαζόμενοι ἐκβάλλουσιν ἐπιλανθανόμενοι δόξαν τὴν τοῦ ποιεῖν δεῖν ἃ τῇ πόλει βέλτιστα.","st":"412e"},{"sp":"N","t":"Τίνα, ἔφη, λέγεις τὴν ἐκβολήν;","st":"412e"},{"sp":"N","t":"Ἐγώ σοι, ἔφην, ἐρῶ. φαίνεταί μοι δόξα ἐξιέναι ἐκ διανοίας ἢ ἑκουσίως ἢ ἀκουσίως, ἑκουσίως μὲν ἡ ψευδὴς","st":"412e"},{"sp":"N","t":"τοῦ μεταμανθάνοντος, ἀκουσίως δὲ πᾶσα ἡ ἀληθής.","st":"413a"},{"sp":"N","t":"Τὸ μὲν τῆς ἑκουσίου, ἔφη, μανθάνω, τὸ δὲ τῆς ἀκουσίου δέομαι μαθεῖν.","st":"413a"},{"sp":"N","t":"Τί δέ; οὐ καὶ σὺ ἡγῇ, ἔφην ἐγώ, τῶν μὲν ἀγαθῶν ἀκουσίως στέρεσθαι τοὺς ἀνθρώπους, τῶν δὲ κακῶν ἑκουσίως; ἢ οὐ τὸ μὲν ἐψεῦσθαι τῆς ἀληθείας κακόν, τὸ δὲ ἀληθεύειν ἀγαθόν; ἢ οὐ τὸ τὰ ὄντα δοξάζειν ἀληθεύειν δοκεῖ σοι εἶναι;","st":"413a"},{"sp":"N","t":"Ἀλλ’, ἦ δ’ ὅς, ὀρθῶς λέγεις, καί μοι δοκοῦσιν ἄκοντες ἀληθοῦς δόξης στερίσκεσθαι.","st":"413a"},{"sp":"N","t":"Οὐκοῦν κλαπέντες ἢ γοητευθέντες ἢ βιασθέντες τοῦτο πάσχουσιν;","st":"413b"},{"sp":"N","t":"Οὐδὲ νῦν, ἔφη, μανθάνω.","st":"413b"},{"sp":"N","t":"Τραγικῶς, ἦν δ’ ἐγώ, κινδυνεύω λέγειν. κλαπέντας μὲν γὰρ τοὺς μεταπεισθέντας λέγω καὶ τοὺς ἐπιλανθανομένους, ὅτι τῶν μὲν χρόνος, τῶν δὲ λόγος ἐξαιρούμενος λανθάνει· νῦν γάρ που μανθάνεις;","st":"413b"},{"sp":"N","t":"Ναί.","st":"413b"},{"sp":"N","t":"Τοὺς τοίνυν βιασθέντας λέγω οὓς ἂν ὀδύνη τις ἢ ἀλγηδὼν μεταδοξάσαι ποιήσῃ.","st":"413b"},{"sp":"N","t":"Καὶ τοῦτ’, ἔφη, ἔμαθον, καὶ ὀρθῶς λέγεις.","st":"413b"},{"sp":"N","t":"Τοὺς μὴν γοητευθέντας, ὡς ἐγᾦμαι, κἂν σὺ φαίης εἶναι οἳ ἂν μεταδοξάσωσιν ἢ ὑφ’ ἡδονῆς κηληθέντες ἢ ὑπὸ φόβου τι δείσαντες.","st":"413c"},{"sp":"N","t":"Ἔοικε γάρ, ἦ δ’ ὅς, γοητεύειν πάντα ὅσα ἀπατᾷ.","st":"413c"},{"sp":"N","t":"Ὃ τοίνυν ἄρτι ἔλεγον, ζητητέον τίνες ἄριστοι φύλακες τοῦ παρ’ αὑτοῖς δόγματος, τοῦτο ὡς ποιητέον ὃ ἂν τῇ πόλει ἀεὶ δοκῶσι βέλτιστον εἶναι [αὑτοῖς ποιεῖν]. τηρητέον δὴ εὐθὺς ἐκ παίδων προθεμένοις ἔργα ἐν οἷς ἄν τις τὸ τοιοῦτον μάλιστα ἐπιλανθάνοιτο καὶ ἐξαπατῷτο, καὶ τὸν μὲν μνήμονα","st":"413c"},{"sp":"N","t":"καὶ δυσεξαπάτητον ἐγκριτέον, τὸν δὲ μὴ ἀποκριτέον. ἦ γάρ;","st":"413d"},{"sp":"N","t":"Ναί.","st":"413d"},{"sp":"N","t":"Καὶ πόνους γε αὖ καὶ ἀλγηδόνας καὶ ἀγῶνας αὐτοῖς θετέον, ἐν οἷς ταὐτὰ ταῦτα τηρητέον.","st":"413d"},{"sp":"N","t":"Ὀρθῶς, ἔφη.","st":"413d"},{"sp":"N","t":"Οὐκοῦν, ἦν δ’ ἐγώ, καὶ τρίτου εἴδους τούτοις γοητείας ἅμιλλαν ποιητέον, καὶ θεατέον — ὥσπερ τοὺς πώλους ἐπὶ τοὺς ψόφους τε καὶ θορύβους ἄγοντες σκοποῦσιν εἰ φοβεροί, οὕτω νέους ὄντας εἰς δείματ’ ἄττα κομιστέον καὶ εἰς ἡδονὰς","st":"413d"},{"sp":"N","t":"αὖ μεταβλητέον, βασανίζοντας πολὺ μᾶλλον ἢ χρυσὸν ἐν πυρί — εἰ δυσγοήτευτος καὶ εὐσχήμων ἐν πᾶσι φαίνεται, φύλαξ αὑτοῦ ὢν ἀγαθὸς καὶ μουσικῆς ἧς ἐμάνθανεν, εὔρυθμόν τε καὶ εὐάρμοστον ἑαυτὸν ἐν πᾶσι τούτοις παρέχων, οἷος δὴ ἂν ὢν καὶ ἑαυτῷ καὶ πόλει χρησιμώτατος εἴη. καὶ τὸν ἀεὶ ἔν τε παισὶ καὶ νεανίσκοις καὶ ἐν ἀνδράσι βασανιζόμενον","st":"413e"},{"sp":"N","t":"καὶ ἀκήρατον ἐκβαίνοντα καταστατέον ἄρχοντα τῆς πόλεως καὶ φύλακα, καὶ τιμὰς δοτέον καὶ ζῶντι καὶ τελευτήσαντι, τάφων τε καὶ τῶν ἄλλων μνημείων μέγιστα γέρα λαγχάνοντα· τὸν δὲ μὴ τοιοῦτον ἀποκριτέον. τοιαύτη τις, ἦν δ’ ἐγώ, δοκεῖ μοι, ὦ Γλαύκων, ἡ ἐκλογὴ εἶναι καὶ κατάστασις τῶν ἀρχόντων τε καὶ φυλάκων, ὡς ἐν τύπῳ, μὴ δι’ ἀκριβείας, εἰρῆσθαι.","st":"414a"},{"sp":"N","t":"Καὶ ἐμοί, ἦ δ’ ὅς, οὕτως πῃ φαίνεται.","st":"414a"},{"sp":"N","t":"Ἆρ’ οὖν ὡς ἀληθῶς ὀρθότατον καλεῖν τούτους μὲν φύλακας παντελεῖς τῶν τε ἔξωθεν πολεμίων τῶν τε ἐντὸς φιλίων, ὅπως οἱ μὲν μὴ βουλήσονται, οἱ δὲ μὴ δυνήσονται κακουργεῖν, τοὺς δὲ νέους, οὓς δὴ νῦν φύλακας ἐκαλοῦμεν, ἐπικούρους τε καὶ βοηθοὺς τοῖς τῶν ἀρχόντων δόγμασιν;","st":"414b"},{"sp":"N","t":"Ἔμοιγε δοκεῖ, ἔφη.","st":"414b"},{"sp":"N","t":"Τίς ἂν οὖν ἡμῖν, ἦν δ’ ἐγώ, μηχανὴ γένοιτο τῶν ψευδῶν τῶν ἐν δέοντι γιγνομένων, ὧν δὴ νῦν ἐλέγομεν, γενναῖόν","st":"414b"},{"sp":"N","t":"τι ἓν ψευδομένους πεῖσαι μάλιστα μὲν καὶ αὐτοὺς τοὺς ἄρχοντας, εἰ δὲ μή, τὴν ἄλλην πόλιν;","st":"414c"},{"sp":"N","t":"Ποῖόν τι; ἔφη.","st":"414c"},{"sp":"N","t":"Μηδὲν καινόν, ἦν δ’ ἐγώ, ἀλλὰ Φοινικικόν τι, πρότερον μὲν ἤδη πολλαχοῦ γεγονός, ὥς φασιν οἱ ποιηταὶ καὶ πεπείκασιν, ἐφ’ ἡμῶν δὲ οὐ γεγονὸς οὐδ’ οἶδα εἰ γενόμενον ἄν, πεῖσαι δὲ συχνῆς πειθοῦς.","st":"414c"},{"sp":"N","t":"Ὡς ἔοικας, ἔφη, ὀκνοῦντι λέγειν.","st":"414c"},{"sp":"N","t":"Δόξω δέ σοι, ἦν δ’ ἐγώ, καὶ μάλ’ εἰκότως ὀκνεῖν, ἐπειδὰν εἴπω.","st":"414c"},{"sp":"N","t":"Λέγ’, ἔφη, καὶ μὴ φοβοῦ.","st":"414c"},{"sp":"N","t":"Λέγω δή — καίτοι οὐκ οἶδα ὁποίᾳ τόλμῃ ἢ ποίοις λόγοις χρώμενος ἐρῶ — καὶ ἐπιχειρήσω πρῶτον μὲν αὐτοὺς τοὺς ἄρχοντας πείθειν καὶ τοὺς στρατιώτας, ἔπειτα δὲ καὶ τὴν ἄλλην πόλιν, ὡς ἄρ’ ἃ ἡμεῖς αὐτοὺς ἐτρέφομέν τε καὶ ἐπαιδεύομεν, ὥσπερ ὀνείρατα ἐδόκουν ταῦτα πάντα πάσχειν τε καὶ γίγνεσθαι περὶ αὐτούς, ἦσαν δὲ τότε τῇ ἀληθείᾳ ὑπὸ γῆς ἐντὸς πλαττόμενοι καὶ τρεφόμενοι καὶ αὐτοὶ καὶ τὰ","st":"414d"},{"sp":"N","t":"ὅπλα αὐτῶν καὶ ἡ ἄλλη σκευὴ δημιουργουμένη, ἐπειδὴ δὲ παντελῶς ἐξειργασμένοι ἦσαν, καὶ ἡ γῆ αὐτοὺς μήτηρ οὖσα ἀνῆκεν, καὶ νῦν δεῖ ὡς περὶ μητρὸς καὶ τροφοῦ τῆς χώρας ἐν ᾗ εἰσι βουλεύεσθαί τε καὶ ἀμύνειν αὐτούς, ἐάν τις ἐπ’ αὐτὴν ἴῃ, καὶ ὑπὲρ τῶν ἄλλων πολιτῶν ὡς ἀδελφῶν ὄντων καὶ γηγενῶν διανοεῖσθαι.","st":"414e"},{"sp":"N","t":"Οὐκ ἐτός, ἔφη, πάλαι ᾐσχύνου τὸ ψεῦδος λέγειν.","st":"414e"},{"sp":"N","t":"Πάνυ, ἦν δ’ ἐγώ, εἰκότως· ἀλλ’ ὅμως ἄκουε καὶ τὸ λοιπὸν τοῦ μύθου. ἐστὲ μὲν γὰρ δὴ πάντες οἱ ἐν τῇ πόλει ἀδελφοί, ὡς φήσομεν πρὸς αὐτοὺς μυθολογοῦντες, ἀλλ’ ὁ θεὸς πλάττων, ὅσοι μὲν ὑμῶν ἱκανοὶ ἄρχειν, χρυσὸν ἐν τῇ γενέσει συνέμειξεν αὐτοῖς, διὸ τιμιώτατοί εἰσιν· ὅσοι δ’ ἐπίκουροι, ἄργυρον· σίδηρον δὲ καὶ χαλκὸν τοῖς τε γεωργοῖς καὶ τοῖς ἄλλοις δημιουργοῖς. ἅτε οὖν συγγενεῖς ὄντες πάντες τὸ μὲν πολὺ ὁμοίους ἂν ὑμῖν αὐτοῖς γεννῷτε,","st":"415a"},{"sp":"N","t":"ἔστι δ’ ὅτε ἐκ χρυσοῦ γεννηθείη ἂν ἀργυροῦν καὶ ἐξ ἀργύρου χρυσοῦν ἔκγονον καὶ τἆλλα πάντα οὕτως ἐξ ἀλλήλων. τοῖς οὖν ἄρχουσι καὶ πρῶτον καὶ μάλιστα παραγγέλλει ὁ θεός, ὅπως μηδενὸς οὕτω φύλακες ἀγαθοὶ ἔσονται μηδ’ οὕτω σφόδρα φυλάξουσι μηδὲν ὡς τοὺς ἐκγόνους, ὅτι αὐτοῖς τούτων ἐν ταῖς ψυχαῖς παραμέμεικται, καὶ ἐάν τε σφέτερος ἔκγονος ὑπόχαλκος ἢ ὑποσίδηρος γένηται, μηδενὶ","st":"415b"},{"sp":"N","t":"τρόπῳ κατελεήσουσιν, ἀλλὰ τὴν τῇ φύσει προσήκουσαν τιμὴν ἀποδόντες ὤσουσιν εἰς δημιουργοὺς ἢ εἰς γεωργούς, καὶ ἂν αὖ ἐκ τούτων τις ὑπόχρυσος ἢ ὑπάργυρος φυῇ, τιμήσαντες ἀνάξουσι τοὺς μὲν εἰς φυλακήν, τοὺς δὲ εἰς ἐπικουρίαν, ὡς χρησμοῦ ὄντος τότε τὴν πόλιν διαφθαρῆναι, ὅταν αὐτὴν ὁ σιδηροῦς φύλαξ ἢ ὁ χαλκοῦς φυλάξῃ. τοῦτον οὖν τὸν μῦθον ὅπως ἂν πεισθεῖεν, ἔχεις τινὰ μηχανήν;","st":"415c"},{"sp":"N","t":"Οὐδαμῶς, ἔφη, ὅπως γ’ ἂν αὐτοὶ οὗτοι· ὅπως μεντἂν οἱ τούτων ὑεῖς καὶ οἱ ἔπειτα οἵ τ’ ἄλλοι ἄνθρωποι οἱ ὕστερον.","st":"415d"},{"sp":"N","t":"Ἀλλὰ καὶ τοῦτο, ἦν δ’ ἐγώ, εὖ ἂν ἔχοι πρὸς τὸ μᾶλλον αὐτοὺς τῆς πόλεώς τε καὶ ἀλλήλων κήδεσθαι· σχεδὸν γάρ τι μανθάνω ὃ λέγεις.","st":"415d"},{"sp":"N","t":"Καὶ τοῦτο μὲν δὴ ἕξει ὅπῃ ἂν αὐτὸ ἡ φήμη ἀγάγῃ· ἡμεῖς δὲ τούτους τοὺς γηγενεῖς ὁπλίσαντες προάγωμεν ἡγουμένων τῶν ἀρχόντων. ἐλθόντες δὲ θεασάσθων τῆς πόλεως ὅπου κάλλιστον στρατοπεδεύσασθαι, ὅθεν τούς τε","st":"415d"},{"sp":"N","t":"ἔνδον μάλιστ’ ἂν κατέχοιεν, εἴ τις μὴ ἐθέλοι τοῖς νόμοις πείθεσθαι, τούς τε ἔξωθεν ἀπαμύνοιεν, εἰ πολέμιος ὥσπερ λύκος ἐπὶ ποίμνην τις ἴοι· στρατοπεδευσάμενοι δέ, θύσαντες οἷς χρή, εὐνὰς ποιησάσθων. ἢ πῶς;","st":"415e"},{"sp":"N","t":"Οὕτως, ἔφη.","st":"415e"},{"sp":"N","t":"Οὐκοῦν τοιαύτας, οἵας χειμῶνός τε στέγειν καὶ θέρους ἱκανὰς εἶναι;","st":"415e"},{"sp":"N","t":"Πῶς γὰρ οὐχί; οἰκήσεις γάρ, ἔφη, δοκεῖς μοι λέγειν.","st":"415e"},{"sp":"N","t":"Ναί, ἦν δ’ ἐγώ, στρατιωτικάς γε, ἀλλ’ οὐ χρηματιστικάς.","st":"415e"},{"sp":"N","t":"Πῶς, ἔφη, αὖ τοῦτο λέγεις διαφέρειν ἐκείνου;","st":"416a"},{"sp":"N","t":"Ἐγώ σοι, ἦν δ’ ἐγώ, πειράσομαι εἰπεῖν. δεινότατον γάρ που πάντων καὶ αἴσχιστον ποιμέσι τοιούτους γε καὶ οὕτω τρέφειν κύνας ἐπικούρους ποιμνίων, ὥστε ὑπὸ ἀκολασίας ἢ λιμοῦ ἤ τινος ἄλλου κακοῦ ἔθους αὐτοὺς τοὺς κύνας ἐπιχειρῆσαι τοῖς προβάτοις κακουργεῖν καὶ ἀντὶ κυνῶν λύκοις ὁμοιωθῆναι.","st":"416a"},{"sp":"N","t":"Δεινόν, ἦ δ’ ὅς· πῶς δ’ οὔ;","st":"416a"},{"sp":"N","t":"Οὐκοῦν φυλακτέον παντὶ τρόπῳ μὴ τοιοῦτον ἡμῖν οἱ ἐπίκουροι ποιήσωσι πρὸς τοὺς πολίτας, ἐπειδὴ αὐτῶν κρείττους εἰσίν, ἀντὶ συμμάχων εὐμενῶν δεσπόταις ἀγρίοις ἀφομοιωθῶσιν;","st":"416b"},{"sp":"N","t":"Φυλακτέον, ἔφη.","st":"416b"},{"sp":"N","t":"Οὐκοῦν τὴν μεγίστην τῆς εὐλαβείας παρεσκευασμένοι ἂν εἶεν, εἰ τῷ ὄντι καλῶς πεπαιδευμένοι εἰσίν;","st":"416b"},{"sp":"N","t":"Ἀλλὰ μὴν εἰσίν γ’, ἔφη.","st":"416b"},{"sp":"N","t":"Καὶ ἐγὼ εἶπον· Τοῦτο μὲν οὐκ ἄξιον διισχυρίζεσθαι, ὦ φίλε Γλαύκων· ὃ μέντοι ἄρτι ἐλέγομεν, ἄξιον, ὅτι δεῖ","st":"416b"},{"sp":"N","t":"αὐτοὺς τῆς ὀρθῆς τυχεῖν παιδείας, ἥτις ποτέ ἐστιν, εἰ μέλλουσι τὸ μέγιστον ἔχειν πρὸς τὸ ἥμεροι εἶναι αὑτοῖς τε καὶ τοῖς φυλαττομένοις ὑπ’ αὐτῶν.","st":"416c"},{"sp":"N","t":"Καὶ ὀρθῶς γε, ἦ δ’ ὅς.","st":"416c"},{"sp":"N","t":"Πρὸς τοίνυν τῇ παιδείᾳ ταύτῃ φαίη ἄν τις νοῦν ἔχων δεῖν καὶ τὰς οἰκήσεις καὶ τὴν ἄλλην οὐσίαν τοιαύτην αὐτοῖς παρεσκευάσθαι, ἥτις μήτε τοῦ φύλακας ὡς ἀρίστους εἶναι παύσει","st":"416c"},{"sp":"N","t":"αὐτούς, κακουργεῖν τε μὴ ἐπαρεῖ περὶ τοὺς ἄλλους πολίτας.","st":"416d"},{"sp":"N","t":"Καὶ ἀληθῶς γε φήσει.","st":"416d"},{"sp":"N","t":"Ὅρα δή, εἶπον ἐγώ, εἰ τοιόνδε τινὰ τρόπον δεῖ αὐτοὺς ζῆν τε καὶ οἰκεῖν, εἰ μέλλουσι τοιοῦτοι ἔσεσθαι· πρῶτον μὲν οὐσίαν κεκτημένον μηδεμίαν μηδένα ἰδίαν, ἂν μὴ πᾶσα ἀνάγκη· ἔπειτα οἴκησιν καὶ ταμιεῖον μηδενὶ εἶναι μηδὲν τοιοῦτον, εἰς ὃ οὐ πᾶς ὁ βουλόμενος εἴσεισι· τὰ δ’ ἐπιτήδεια, ὅσων δέονται ἄνδρες ἀθληταὶ πολέμου σώφρονές τε καὶ","st":"416d"},{"sp":"N","t":"ἀνδρεῖοι, ταξαμένους παρὰ τῶν ἄλλων πολιτῶν δέχεσθαι μισθὸν τῆς φυλακῆς τοσοῦτον ὅσον μήτε περιεῖναι αὐτοῖς εἰς τὸν ἐνιαυτὸν μήτε ἐνδεῖν· φοιτῶντας δὲ εἰς συσσίτια ὥσπερ ἐστρατοπεδευμένους κοινῇ ζῆν· χρυσίον δὲ καὶ ἀργύριον εἰπεῖν αὐτοῖς ὅτι θεῖον παρὰ θεῶν ἀεὶ ἐν τῇ ψυχῇ ἔχουσι καὶ οὐδὲν προσδέονται τοῦ ἀνθρωπείου, οὐδὲ ὅσια τὴν ἐκείνου κτῆσιν τῇ τοῦ θνητοῦ χρυσοῦ κτήσει συμμειγνύντας μιαίνειν, διότι πολλὰ καὶ ἀνόσια περὶ τὸ τῶν","st":"416e"},{"sp":"N","t":"πολλῶν νόμισμα γέγονεν, τὸ παρ’ ἐκείνοις δὲ ἀκήρατον· ἀλλὰ μόνοις αὐτοῖς τῶν ἐν τῇ πόλει μεταχειρίζεσθαι καὶ ἅπτεσθαι χρυσοῦ καὶ ἀργύρου οὐ θέμις, οὐδ’ ὑπὸ τὸν αὐτὸν ὄροφον ἰέναι οὐδὲ περιάψασθαι οὐδὲ πίνειν ἐξ ἀργύρου ἢ χρυσοῦ. καὶ οὕτω μὲν σῴζοιντό τ’ ἂν καὶ σῴζοιεν τὴν πόλιν· ὁπότε δ’ αὐτοὶ γῆν τε ἰδίαν καὶ οἰκίας καὶ νομίσματα κτήσονται, οἰκονόμοι μὲν καὶ γεωργοὶ ἀντὶ φυλάκων ἔσονται,","st":"417a"},{"sp":"N","t":"δεσπόται δ’ ἐχθροὶ ἀντὶ συμμάχων τῶν ἄλλων πολιτῶν γενήσονται, μισοῦντες δὲ δὴ καὶ μισούμενοι καὶ ἐπιβουλεύοντες καὶ ἐπιβουλευόμενοι διάξουσι πάντα τὸν βίον, πολὺ πλείω καὶ μᾶλλον δεδιότες τοὺς ἔνδον ἢ τοὺς ἔξωθεν πολεμίους, θέοντες ἤδη τότε ἐγγύτατα ὀλέθρου αὐτοί τε καὶ ἡ ἄλλη πόλις. τούτων οὖν πάντων ἕνεκα, ἦν δ’ ἐγώ, φῶμεν οὕτω δεῖν κατεσκευάσθαι τοὺς φύλακας οἰκήσεώς τε πέρι καὶ τῶν ἄλλων, καὶ ταῦτα νομοθετήσωμεν, ἢ μή;","st":"417b"},{"sp":"N","t":"Πάνυ γε, ἦ δ’ ὃς ὁ Γλαύκων.","st":"417b"},{"sp":"N","t":"ΣΩΚΡΆΤΗς, ΑΔΕΊΜΑΝΤΟς","st":"417b"},{"sp":"N","t":"Καὶ ὁ Ἀδείμαντος ὑπολαβών, τί οὖν, ἔφη, ὦ Σώκρατες, ἀπολογήσῃ, ἐάν τίς σε φῇ μὴ πάνυ τι εὐδαίμονας ποιεῖν τούτους τοὺς ἄνδρας, καὶ ταῦτα δι’ ἑαυτούς, ὧν ἔστι μὲν ἡ πόλις τῇ ἀληθείᾳ, οἱ δὲ μηδὲν ἀπολαύουσιν ἀγαθὸν τῆς πόλεως, οἷον ἄλλοι ἀγρούς τε κεκτημένοι καὶ οἰκίας οἰκοδομούμενοι καλὰς καὶ μεγάλας, καὶ ταύταις πρέπουσαν κατασκευὴν κτώμενοι, καὶ θυσίας θεοῖς ἰδίας θύοντες, καὶ ξενοδοκοῦντες, καὶ δὴ καὶ ἃ νυνδὴ σὺ ἔλεγες, χρυσόν τε καὶ ἄργυρον κεκτημένοι καὶ πάντα ὅσα νομίζεται τοῖς μέλλουσιν μακαρίοις εἶναι; ἀλλ’ ἀτεχνῶς, φαίη ἄν, ὥσπερ ἐπίκουροι μισθωτοὶ ἐν","st":"419a"},{"sp":"N","t":"τῇ πόλει φαίνονται καθῆσθαι οὐδὲν ἄλλο ἢ φρουροῦντες. Ναί, ἦν δ’ ἐγώ, καὶ ταῦτά γε ἐπισίτιοι καὶ οὐδὲ μισθὸν πρὸς τοῖς σιτίοις λαμβάνοντες ὥσπερ οἱ ἄλλοι, ὥστε οὐδ’ ἂν ἀποδημῆσαι βούλωνται ἰδίᾳ, ἐξέσται αὐτοῖς, οὐδ’ ἑταίραις διδόναι, οὐδ’ ἀναλίσκειν ἄν ποι βούλωνται ἄλλοσε, οἷα δὴ οἱ εὐδαίμονες δοκοῦντες εἶναι ἀναλίσκουσι. ταῦτα καὶ ἄλλα τοιαῦτα συχνὰ τῆς κατηγορίας ἀπολείπεις.","st":"420a"},{"sp":"N","t":"Ἀλλ’, ἦ δ’ ὅς, ἔστω καὶ ταῦτα κατηγορημένα.","st":"420a"},{"sp":"N","t":"Τί οὖν δὴ ἀπολογησόμεθα, φῄς;","st":"420b"},{"sp":"N","t":"Ναί.","st":"420b"},{"sp":"N","t":"Τὸν αὐτὸν οἶμον, ἦν δ’ ἐγώ, πορευόμενοι εὑρήσομεν, ὡς ἐγᾦμαι, ἃ λεκτέα. ἐροῦμεν γὰρ ὅτι θαυμαστὸν μὲν ἂν οὐδὲν εἴη εἰ καὶ οὗτοι οὕτως εὐδαιμονέστατοί εἰσιν, οὐ μὴν πρὸς τοῦτο βλέποντες τὴν πόλιν οἰκίζομεν, ὅπως ἕν τι ἡμῖν ἔθνος ἔσται διαφερόντως εὔδαιμον, ἀλλ’ ὅπως ὅτι μάλιστα ὅλη ἡ πόλις. ᾠήθημεν γὰρ ἐν τῇ τοιαύτῃ μάλιστα ἂν εὑρεῖν δικαιοσύνην καὶ αὖ ἐν τῇ κάκιστα οἰκουμένῃ","st":"420b"},{"sp":"N","t":"ἀδικίαν, κατιδόντες δὲ κρῖναι ἂν ὃ πάλαι ζητοῦμεν. νῦν μὲν οὖν, ὡς οἰόμεθα, τὴν εὐδαίμονα πλάττομεν οὐκ ἀπολαβόντες ὀλίγους ἐν αὐτῇ τοιούτους τινὰς τιθέντες, ἀλλ’ ὅλην· αὐτίκα δὲ τὴν ἐναντίαν σκεψόμεθα. ὥσπερ οὖν ἂν εἰ ἡμᾶς ἀνδριάντα γράφοντας προσελθών τις ἔψεγε λέγων ὅτι οὐ τοῖς καλλίστοις τοῦ ζῴου τὰ κάλλιστα φάρμακα προστίθεμεν — οἱ γὰρ ὀφθαλμοὶ κάλλιστον ὂν οὐκ ὀστρείῳ ἐναληλιμμένοι εἶεν ἀλλὰ μέλανι — μετρίως ἂν ἐδοκοῦμεν","st":"420c"},{"sp":"N","t":"πρὸς αὐτὸν ἀπολογεῖσθαι λέγοντες· “Ὦ θαυμάσιε, μὴ οἴου δεῖν ἡμᾶς οὕτω καλοὺς ὀφθαλμοὺς γράφειν, ὥστε μηδὲ ὀφθαλμοὺς φαίνεσθαι, μηδ’ αὖ τἆλλα μέρη, ἀλλ’ ἄθρει εἰ τὰ προσήκοντα ἑκάστοις ἀποδιδόντες τὸ ὅλον καλὸν ποιοῦμεν· καὶ δὴ καὶ νῦν μὴ ἀνάγκαζε ἡμᾶς τοιαύτην εὐδαιμονίαν τοῖς φύλαξι προσάπτειν, ἣ ἐκείνους πᾶν μᾶλλον","st":"420d"},{"sp":"N","t":"ἀπεργάσεται ἢ φύλακας. ἐπιστάμεθα γὰρ καὶ τοὺς γεωργοὺς ξυστίδας ἀμφιέσαντες καὶ χρυσὸν περιθέντες πρὸς ἡδονὴν ἐργάζεσθαι κελεύειν τὴν γῆν, καὶ τοὺς κεραμέας κατακλίναντες ἐπὶ δεξιὰ πρὸς τὸ πῦρ διαπίνοντάς τε καὶ εὐωχουμένους, τὸν τροχὸν παραθεμένους, ὅσον ἂν ἐπιθυμῶσι κεραμεύειν, καὶ τοὺς ἄλλους πάντας τοιούτῳ τρόπῳ μακαρίους ποιεῖν, ἵνα δὴ ὅλη ἡ πόλις εὐδαιμονῇ. ἀλλ’ ἡμᾶς μὴ οὕτω νουθέτει· ὡς, ἄν σοι πειθώμεθα, οὔτε ὁ γεωργὸς γεωργὸς","st":"420e"},{"sp":"N","t":"ἔσται οὔτε ὁ κεραμεὺς κεραμεὺς οὔτε ἄλλος οὐδεὶς οὐδὲν ἔχων σχῆμα ἐξ ὧν πόλις γίγνεται. ἀλλὰ τῶν μὲν ἄλλων ἐλάττων λόγος· νευρορράφοι γὰρ φαῦλοι γενόμενοι καὶ διαφθαρέντες καὶ προσποιησάμενοι εἶναι μὴ ὄντες πόλει οὐδὲν δεινόν, φύλακες δὲ νόμων τε καὶ πόλεως μὴ ὄντες ἀλλὰ δοκοῦντες ὁρᾷς δὴ ὅτι πᾶσαν ἄρδην πόλιν ἀπολλύασιν, καὶ αὖ τοῦ εὖ οἰκεῖν καὶ εὐδαιμονεῖν μόνοι τὸν καιρὸν ἔχουσιν.” εἰ μὲν οὖν ἡμεῖς μὲν φύλακας ὡς ἀληθῶς","st":"421a"},{"sp":"N","t":"ποιοῦμεν ἥκιστα κακούργους τῆς πόλεως, ὁ δ’ ἐκεῖνο λέγων γεωργούς τινας καὶ ὥσπερ ἐν πανηγύρει ἀλλ’ οὐκ ἐν πόλει ἑστιάτορας εὐδαίμονας, ἄλλο ἄν τι ἢ πόλιν λέγοι. σκεπτέον οὖν πότερον πρὸς τοῦτο βλέποντες τοὺς φύλακας καθιστῶμεν, ὅπως ὅτι πλείστη αὐτοῖς εὐδαιμονία ἐγγενήσεται, ἢ τοῦτο μὲν εἰς τὴν πόλιν ὅλην βλέποντας θεατέον εἰ ἐκείνῃ ἐγγίγνεται, τοὺς δ’ ἐπικούρους τούτους καὶ τοὺς","st":"421b"},{"sp":"N","t":"φύλακας ἐκεῖνο ἀναγκαστέον ποιεῖν καὶ πειστέον, ὅπως ὅτι ἄριστοι δημιουργοὶ τοῦ ἑαυτῶν ἔργου ἔσονται, καὶ τοὺς ἄλλους ἅπαντας ὡσαύτως, καὶ οὕτω συμπάσης τῆς πόλεως αὐξανομένης καὶ καλῶς οἰκιζομένης ἐατέον ὅπως ἑκάστοις τοῖς ἔθνεσιν ἡ φύσις ἀποδίδωσι τοῦ μεταλαμβάνειν εὐδαιμονίας.","st":"421c"},{"sp":"N","t":"Ἀλλ’, ἦ δ’ ὅς, καλῶς μοι δοκεῖς λέγειν.","st":"421c"},{"sp":"N","t":"Ἆρ’ οὖν, ἦν δ’ ἐγώ, καὶ τὸ τούτου ἀδελφὸν δόξω σοι μετρίως λέγειν;","st":"421c"},{"sp":"N","t":"Τί μάλιστα;","st":"421c"},{"sp":"N","t":"Τοὺς ἄλλους αὖ δημιουργοὺς σκόπει εἰ τάδε διαφθείρει, ὥστε καὶ κακοὺς γίγνεσθαι.","st":"421d"},{"sp":"N","t":"Τὰ ποῖα δὴ ταῦτα;","st":"421d"},{"sp":"N","t":"Πλοῦτος, ἦν δ’ ἐγώ, καὶ πενία.","st":"421d"},{"sp":"N","t":"Πῶς δή;","st":"421d"},{"sp":"N","t":"Ὧδε. πλουτήσας χυτρεὺς δοκεῖ σοι ἔτ’ ἐθελήσειν ἐπιμελεῖσθαι τῆς τέχνης;","st":"421d"},{"sp":"N","t":"Οὐδαμῶς, ἔφη.","st":"421d"},{"sp":"N","t":"Ἀργὸς δὲ καὶ ἀμελὴς γενήσεται μᾶλλον αὐτὸς αὑτοῦ;","st":"421d"},{"sp":"N","t":"Πολύ γε.","st":"421d"},{"sp":"N","t":"Οὐκοῦν κακίων χυτρεὺς γίγνεται;","st":"421d"},{"sp":"N","t":"Καὶ τοῦτο, ἔφη, πολύ.","st":"421d"},{"sp":"N","t":"Καὶ μὴν καὶ ὄργανά γε μὴ ἔχων παρέχεσθαι ὑπὸ πενίας ἤ τι ἄλλο τῶν εἰς τὴν τέχνην τά τε ἔργα πονηρότερα","st":"421d"},{"sp":"N","t":"ἐργάσεται καὶ τοὺς ὑεῖς ἢ ἄλλους οὓς ἂν διδάσκῃ χείρους δημιουργοὺς διδάξεται.","st":"421e"},{"sp":"N","t":"Πῶς δ’ οὔ;","st":"421e"},{"sp":"N","t":"Ὑπ’ ἀμφοτέρων δή, πενίας τε καὶ πλούτου, χείρω μὲν τὰ τῶν τεχνῶν ἔργα, χείρους δὲ αὐτοί.","st":"421e"},{"sp":"N","t":"Φαίνεται.","st":"421e"},{"sp":"N","t":"Ἕτερα δή, ὡς ἔοικε, τοῖς φύλαξιν ηὑρήκαμεν, ἃ παντὶ τρόπῳ φυλακτέον ὅπως μήποτε αὐτοὺς λήσει εἰς τὴν πόλιν παραδύντα.","st":"421e"},{"sp":"N","t":"Τὰ ποῖα ταῦτα;","st":"421e"},{"sp":"N","t":"Πλοῦτός τε, ἦν δ’ ἐγώ, καὶ πενία· ὡς τοῦ μὲν τρυφὴν καὶ ἀργίαν καὶ νεωτερισμὸν ἐμποιοῦντος, τῆς δὲ ἀνελευθερίαν καὶ κακοεργίαν πρὸς τῷ νεωτερισμῷ. Πάνυ μὲν οὖν, ἔφη. τόδε μέντοι, ὦ Σώκρατες, σκόπει, πῶς ἡμῖν ἡ πόλις οἵα τ’ ἔσται πολεμεῖν, ἐπειδὰν χρήματα μὴ κεκτημένη ᾖ, ἄλλως τε κἂν πρὸς μεγάλην τε καὶ πλουσίαν ἀναγκασθῇ πολεμεῖν.","st":"422a"},{"sp":"N","t":"Δῆλον, ἦν δ’ ἐγώ, ὅτι πρὸς μὲν μίαν χαλεπώτερον,","st":"422a"},{"sp":"N","t":"πρὸς δὲ δύο τοιαύτας ῥᾷον.","st":"422b"},{"sp":"N","t":"Πῶς εἶπες; ἦ δ’ ὅς.","st":"422b"},{"sp":"N","t":"Πρῶτον μέν που, εἶπον, ἐὰν δέῃ μάχεσθαι, ἆρα οὐ πλουσίοις ἀνδράσι μαχοῦνται αὐτοὶ ὄντες πολέμου ἀθληταί;","st":"422b"},{"sp":"N","t":"Ναὶ τοῦτό γε, ἔφη.","st":"422b"},{"sp":"N","t":"Τί οὖν, ἦν δ’ ἐγώ, ὦ Ἀδείμαντε; εἷς πύκτης ὡς οἷόν τε κάλλιστα ἐπὶ τοῦτο παρεσκευασμένος δυοῖν μὴ πύκταιν, πλουσίοιν δὲ καὶ πιόνοιν, οὐκ ἂν δοκεῖ σοι ῥᾳδίως μάχεσθαι;","st":"422b"},{"sp":"N","t":"Οὐκ ἂν ἴσως, ἔφη, ἅμα γε.","st":"422b"},{"sp":"N","t":"Οὐδ’ εἰ ἐξείη, ἦν δ’ ἐγώ, ὑποφεύγοντι τὸν πρότερον ἀεὶ","st":"422b"},{"sp":"N","t":"προσφερόμενον ἀναστρέφοντα κρούειν, καὶ τοῦτο ποιοῖ πολλάκις ἐν ἡλίῳ τε καὶ πνίγει; ἆρά γε οὐ καὶ πλείους χειρώσαιτ’ ἂν τοιούτους ὁ τοιοῦτος;","st":"422c"},{"sp":"N","t":"Ἀμέλει, ἔφη, οὐδὲν ἂν γένοιτο θαυμαστόν.","st":"422c"},{"sp":"N","t":"Ἀλλ’ οὐκ οἴει πυκτικῆς πλέον μετέχειν τοὺς πλουσίους ἐπιστήμῃ τε καὶ ἐμπειρίᾳ ἢ πολεμικῆς;","st":"422c"},{"sp":"N","t":"Ἔγωγ’, ἔφη.","st":"422c"},{"sp":"N","t":"Ῥᾳδίως ἄρα ἡμῖν οἱ ἀθληταὶ ἐκ τῶν εἰκότων διπλασίοις τε καὶ τριπλασίοις αὑτῶν μαχοῦνται.","st":"422c"},{"sp":"N","t":"Συγχωρήσομαί σοι, ἔφη· δοκεῖς γάρ μοι ὀρθῶς λέγειν.","st":"422c"},{"sp":"N","t":"Τί δ’ ἂν πρεσβείαν πέμψαντες εἰς τὴν ἑτέραν πόλιν τἀληθῆ εἴπωσιν, ὅτι “Ἡμεῖς μὲν οὐδὲν χρυσίῳ οὐδ’ ἀργυρίῳ χρώμεθα, οὐδ’ ἡμῖν θέμις, ὑμῖν δέ· συμπολεμήσαντες οὖν μεθ’ ἡμῶν ἔχετε τὰ τῶν ἑτέρων;” οἴει τινὰς ἀκούσαντας ταῦτα αἱρήσεσθαι κυσὶ πολεμεῖν στερεοῖς τε καὶ ἰσχνοῖς μᾶλλον ἢ μετὰ κυνῶν προβάτοις πίοσί τε καὶ ἁπαλοῖς;","st":"422d"},{"sp":"N","t":"Οὔ μοι δοκεῖ. ἀλλ’ ἐὰν εἰς μίαν, ἔφη, πόλιν συναθροισθῇ","st":"422d"},{"sp":"N","t":"τὰ τῶν ἄλλων χρήματα, ὅρα μὴ κίνδυνον φέρῃ τῇ μὴ πλουτούσῃ.","st":"422e"},{"sp":"N","t":"Εὐδαίμων εἶ, ἦν δ’ ἐγώ, ὅτι οἴει ἄξιον εἶναι ἄλλην τινὰ προσειπεῖν πόλιν ἢ τὴν τοιαύτην οἵαν ἡμεῖς κατεσκευάζομεν.","st":"422e"},{"sp":"N","t":"Ἀλλὰ τί μήν; ἔφη.","st":"422e"},{"sp":"N","t":"Μειζόνως, ἦν δ’ ἐγώ, χρὴ προσαγορεύειν τὰς ἄλλας· ἑκάστη γὰρ αὐτῶν πόλεις εἰσὶ πάμπολλαι ἀλλ’ οὐ πόλις, τὸ τῶν παιζόντων. δύο μέν, κἂν ὁτιοῦν ᾖ, πολεμία ἀλλήλαις,","st":"422e"},{"sp":"N","t":"ἡ μὲν πενήτων, ἡ δὲ πλουσίων· τούτων δ’ ἐν ἑκατέρᾳ πάνυ πολλαί, αἷς ἐὰν μὲν ὡς μιᾷ προσφέρῃ, παντὸς ἂν ἁμάρτοις, ἐὰν δὲ ὡς πολλαῖς, διδοὺς τὰ τῶν ἑτέρων τοῖς ἑτέροις χρήματά τε καὶ δυνάμεις ἢ καὶ αὐτούς, συμμάχοις μὲν ἀεὶ πολλοῖς χρήσῃ, πολεμίοις δ’ ὀλίγοις. καὶ ἕως ἂν ἡ πόλις σοι οἰκῇ σωφρόνως ὡς ἄρτι ἐτάχθη, μεγίστη ἔσται, οὐ τῷ εὐδοκιμεῖν λέγω, ἀλλ’ ὡς ἀληθῶς μεγίστη, καὶ ἐὰν μόνον ᾖ χιλίων τῶν προπολεμούντων· οὕτω γὰρ μεγάλην πόλιν μίαν οὐ ῥᾳδίως οὔτε ἐν Ἕλλησιν οὔτε ἐν βαρβάροις","st":"423a"},{"sp":"N","t":"εὑρήσεις, δοκούσας δὲ πολλὰς καὶ πολλαπλασίας τῆς τηλικαύτης. ἢ ἄλλως οἴει;","st":"423b"},{"sp":"N","t":"Οὐ μὰ τὸν Δί’, ἔφη.","st":"423b"},{"sp":"N","t":"Οὐκοῦν, ἦν δ’ ἐγώ, οὗτος ἂν εἴη καὶ κάλλιστος ὅρος τοῖς ἡμετέροις ἄρχουσιν, ὅσην δεῖ τὸ μέγεθος τὴν πόλιν ποιεῖσθαι καὶ ἡλίκῃ οὔσῃ ὅσην χώραν ἀφορισαμένους τὴν ἄλλην χαίρειν ἐᾶν.","st":"423b"},{"sp":"N","t":"Τίς, ἔφη, ὅρος;","st":"423b"},{"sp":"N","t":"Οἶμαι μέν, ἦν δ’ ἐγώ, τόνδε· μέχρι οὗ ἂν ἐθέλῃ αὐξομένη εἶναι μία, μέχρι τούτου αὔξειν, πέρα δὲ μή.","st":"423b"},{"sp":"N","t":"Καὶ καλῶς γ’, ἔφη.","st":"423c"},{"sp":"N","t":"Οὐκοῦν καὶ τοῦτο αὖ ἄλλο πρόσταγμα τοῖς φύλαξι προστάξομεν, φυλάττειν παντὶ τρόπῳ ὅπως μήτε σμικρὰ ἡ πόλις ἔσται μήτε μεγάλη δοκοῦσα, ἀλλά τις ἱκανὴ καὶ μία. Καὶ φαῦλόν γ’, ἔφη, ἴσως αὐτοῖς προστάξομεν.","st":"423c"},{"sp":"N","t":"Καὶ τούτου γε, ἦν δ’ ἐγώ, ἔτι φαυλότερον τόδε, οὗ καὶ ἐν τῷ πρόσθεν ἐπεμνήσθημεν λέγοντες ὡς δέοι, ἐάντε τῶν φυλάκων τις φαῦλος ἔκγονος γένηται, εἰς τοὺς ἄλλους","st":"423c"},{"sp":"N","t":"αὐτὸν ἀποπέμπεσθαι, ἐάντ’ ἐκ τῶν ἄλλων σπουδαῖος, εἰς τοὺς φύλακας. τοῦτο δ’ ἐβούλετο δηλοῦν ὅτι καὶ τοὺς ἄλλους πολίτας, πρὸς ὅ τις πέφυκεν, πρὸς τοῦτο ἕνα πρὸς ἓν ἕκαστον ἔργον δεῖ κομίζειν, ὅπως ἂν ἓν τὸ αὑτοῦ ἐπιτηδεύων ἕκαστος μὴ πολλοὶ ἀλλ’ εἷς γίγνηται, καὶ οὕτω δὴ σύμπασα ἡ πόλις μία φύηται ἀλλὰ μὴ πολλαί.","st":"423d"},{"sp":"N","t":"Ἔστι γάρ, ἔφη, τοῦτο ἐκείνου σμικρότερον.","st":"423d"},{"sp":"N","t":"Οὔτοι, ἦν δ’ ἐγώ, ὦ ἀγαθὲ Ἀδείμαντε, ὡς δόξειεν ἄν τις, ταῦτα πολλὰ καὶ μεγάλα αὐτοῖς προστάττομεν ἀλλὰ","st":"423d"},{"sp":"N","t":"πάντα φαῦλα, ἐὰν τὸ λεγόμενον ἓν μέγα φυλάττωσι, μᾶλλον δ’ ἀντὶ μεγάλου ἱκανόν.","st":"423e"},{"sp":"N","t":"Τί τοῦτο; ἔφη.","st":"423e"},{"sp":"N","t":"Τὴν παιδείαν, ἦν δ’ ἐγώ, καὶ τροφήν· ἐὰν γὰρ εὖ παιδευόμενοι μέτριοι ἄνδρες γίγνωνται, πάντα ταῦτα ῥᾳδίως διόψονται, καὶ ἄλλα γε ὅσα νῦν ἡμεῖς παραλείπομεν, τήν τε τῶν γυναικῶν κτῆσιν καὶ γάμων καὶ παιδοποιίας, ὅτι","st":"423e"},{"sp":"N","t":"δεῖ ταῦτα κατὰ τὴν παροιμίαν πάντα ὅτι μάλιστα κοινὰ τὰ φίλων ποιεῖσθαι.","st":"424a"},{"sp":"N","t":"Ὀρθότατα γάρ, ἔφη, γίγνοιτ’ ἄν.","st":"424a"},{"sp":"N","t":"Καὶ μήν, εἶπον, πολιτεία ἐάνπερ ἅπαξ ὁρμήσῃ εὖ, ἔρχεται ὥσπερ κύκλος αὐξανομένη· τροφὴ γὰρ καὶ παίδευσις χρηστὴ σῳζομένη φύσεις ἀγαθὰς ἐμποιεῖ, καὶ αὖ φύσεις χρησταὶ τοιαύτης παιδείας ἀντιλαμβανόμεναι ἔτι βελτίους τῶν προτέρων φύονται, εἴς τε τἆλλα καὶ εἰς τὸ","st":"424a"},{"sp":"N","t":"γεννᾶν, ὥσπερ καὶ ἐν τοῖς ἄλλοις ζῴοις.","st":"424b"},{"sp":"N","t":"Εἰκός γ’, ἔφη.","st":"424b"},{"sp":"N","t":"Ὡς τοίνυν διὰ βραχέων εἰπεῖν, τούτου ἀνθεκτέον τοῖς ἐπιμεληταῖς τῆς πόλεως, ὅπως ἂν αὐτοὺς μὴ λάθῃ διαφθαρὲν ἀλλὰ παρὰ πάντα αὐτὸ φυλάττωσι, τὸ μὴ νεωτερίζειν περὶ γυμναστικήν τε καὶ μουσικὴν παρὰ τὴν τάξιν, ἀλλ’ ὡς οἷόν τε μάλιστα φυλάττειν, φοβουμένους ὅταν τις λέγῃ ὡς τὴν","st":"424b"},{"sp":"N","t":"ἀοιδὴν μᾶλλον ἐπιφρονέουσ’ ἄνθρωποι,","st":"424b"},{"sp":"N","t":"ἥτις ἀειδόντεσσι νεωτάτη ἀμφιπέληται,","st":"424b"},{"sp":"N","t":"μὴ πολλάκις τὸν ποιητήν τις οἴηται λέγειν οὐκ ᾄσματα νέα ἀλλὰ τρόπον ᾠδῆς νέον, καὶ τοῦτο ἐπαινῇ. δεῖ δ’ οὔτ’ ἐπαινεῖν τὸ τοιοῦτον οὔτε ὑπολαμβάνειν. εἶδος γὰρ καινὸν μουσικῆς μεταβάλλειν εὐλαβητέον ὡς ἐν ὅλῳ κινδυνεύοντα· οὐδαμοῦ γὰρ κινοῦνται μουσικῆς τρόποι ἄνευ πολιτικῶν νόμων τῶν μεγίστων, ὥς φησί τε Δάμων καὶ ἐγὼ πείθομαι.","st":"424c"},{"sp":"N","t":"Καὶ ἐμὲ τοίνυν, ἔφη ὁ Ἀδείμαντος, θὲς τῶν πεπεισμένων.","st":"424c"},{"sp":"N","t":"Τὸ δὴ φυλακτήριον, ἦν δ’ ἐγώ, ὡς ἔοικεν, ἐνταῦθά που οἰκοδομητέον τοῖς φύλαξιν, ἐν μουσικῇ.","st":"424d"},{"sp":"N","t":"Ἡ γοῦν παρανομία, ἔφη, ῥᾳδίως αὕτη λανθάνει παραδυομένη.","st":"424d"},{"sp":"N","t":"Ναί, ἔφην, ὡς ἐν παιδιᾶς γε μέρει καὶ ὡς κακὸν οὐδὲν ἐργαζομένη.","st":"424d"},{"sp":"N","t":"Οὐδὲ γὰρ ἐργάζεται, ἔφη, ἄλλο γε ἢ κατὰ σμικρὸν εἰσοικισαμένη ἠρέμα ὑπορρεῖ πρὸς τὰ ἤθη τε καὶ τὰ ἐπιτηδεύματα· ἐκ δὲ τούτων εἰς τὰ πρὸς ἀλλήλους συμβόλαια μείζων ἐκβαίνει, ἐκ δὲ δὴ τῶν συμβολαίων ἔρχεται ἐπὶ","st":"424d"},{"sp":"N","t":"τοὺς νόμους καὶ πολιτείας σὺν πολλῇ, ὦ Σώκρατες, ἀσελγείᾳ, ἕως ἂν τελευτῶσα πάντα ἰδίᾳ καὶ δημοσίᾳ ἀνατρέψῃ.","st":"424e"},{"sp":"N","t":"Εἶεν, ἦν δ’ ἐγώ· οὕτω τοῦτ’ ἔχει;","st":"424e"},{"sp":"N","t":"Δοκεῖ μοι, ἔφη.","st":"424e"},{"sp":"N","t":"Οὐκοῦν, ὃ ἐξ ἀρχῆς ἐλέγομεν, τοῖς ἡμετέροις παισὶν ἐννομωτέρου εὐθὺς παιδιᾶς μεθεκτέον, ὡς παρανόμου γιγνομένης αὐτῆς καὶ παίδων τοιούτων ἐννόμους τε καὶ σπουδαίους","st":"424e"},{"sp":"N","t":"ἐξ αὐτῶν ἄνδρας αὐξάνεσθαι ἀδύνατον ὄν;","st":"425a"},{"sp":"N","t":"Πῶς δ’ οὐχί; ἔφη.","st":"425a"},{"sp":"N","t":"Ὅταν δὴ ἄρα καλῶς ἀρξάμενοι παῖδες παίζειν εὐνομίαν διὰ τῆς μουσικῆς εἰσδέξωνται, πάλιν τοὐναντίον ἢ ‘κείνοις εἰς πάντα συνέπεταί τε καὶ αὔξει, ἐπανορθοῦσα εἴ τι καὶ πρότερον τῆς πόλεως ἔκειτο.","st":"425a"},{"sp":"N","t":"Ἀληθῆ μέντοι, ἔφη.","st":"425a"},{"sp":"N","t":"Καὶ τὰ σμικρὰ ἄρα, εἶπον, δοκοῦντα εἶναι νόμιμα ἐξευρίσκουσιν οὗτοι, ἃ οἱ πρότερον ἀπώλλυσαν πάντα.","st":"425a"},{"sp":"N","t":"⟨Τὰ⟩ ποῖα;","st":"425a"},{"sp":"N","t":"Τὰ τοιάδε· σιγάς τε τῶν νεωτέρων παρὰ πρεσβυτέροις ἃς πρέπει, καὶ κατακλίσεις καὶ ὑπαναστάσεις καὶ γονέων θεραπείας, καὶ κουράς γε καὶ ἀμπεχόνας καὶ ὑποδέσεις καὶ ὅλον τὸν τοῦ σώματος σχηματισμὸν καὶ τἆλλα ὅσα τοιαῦτα. ἢ οὐκ οἴει;","st":"425b"},{"sp":"N","t":"Ἔγωγε.","st":"425b"},{"sp":"N","t":"Νομοθετεῖν δ’ αὐτὰ οἶμαι εὔηθες· οὔτε γάρ που γίγνεται οὔτ’ ἂν μείνειεν λόγῳ τε καὶ γράμμασιν νομοθετηθέντα.","st":"425b"},{"sp":"N","t":"Πῶς γάρ;","st":"425b"},{"sp":"N","t":"Κινδυνεύει γοῦν, ἦν δ’ ἐγώ, ὦ Ἀδείμαντε, ἐκ τῆς παιδείας","st":"425b"},{"sp":"N","t":"ὅποι ἄν τις ὁρμήσῃ, τοιαῦτα καὶ τὰ ἑπόμενα εἶναι. ἢ οὐκ ἀεὶ τὸ ὅμοιον ὂν ὅμοιον παρακαλεῖ;","st":"425c"},{"sp":"N","t":"Τί μήν;","st":"425c"},{"sp":"N","t":"Καὶ τελευτῶν δὴ οἶμαι φαῖμεν ἂν εἰς ἕν τι τέλεον καὶ νεανικὸν ἀποβαίνειν αὐτὸ ἢ ἀγαθὸν ἢ καὶ τοὐναντίον.","st":"425c"},{"sp":"N","t":"Τί γὰρ οὔκ; ἦ δ’ ὅς.","st":"425c"},{"sp":"N","t":"Ἐγὼ μὲν τοίνυν, εἶπον, διὰ ταῦτα οὐκ ἂν ἔτι τὰ τοιαῦτα ἐπιχειρήσαιμι νομοθετεῖν.","st":"425c"},{"sp":"N","t":"Εἰκότως γ’, ἔφη.","st":"425c"},{"sp":"N","t":"Τί δέ, ὦ πρὸς θεῶν, ἔφην, τάδε τὰ ἀγοραῖα, συμβολαίων τε πέρι κατ’ ἀγορὰν ἕκαστοι ἃ πρὸς ἀλλήλους συμβάλλουσιν,","st":"425c"},{"sp":"N","t":"εἰ δὲ βούλει, καὶ χειροτεχνικῶν περὶ συμβολαίων καὶ λοιδοριῶν καὶ αἰκίας καὶ δικῶν λήξεως καὶ δικαστῶν καταστάσεως, καὶ εἴ που τελῶν τινες ἢ πράξεις ἢ θέσεις ἀναγκαῖοί εἰσιν ἢ κατ’ ἀγορὰς ἢ λιμένας, ἢ καὶ τὸ παράπαν ἀγορανομικὰ ἄττα ἢ ἀστυνομικὰ ἢ ἐλλιμενικὰ ἢ ὅσα ἄλλα τοιαῦτα, τούτων τολμήσομέν τι νομοθετεῖν;","st":"425d"},{"sp":"N","t":"Ἀλλ’ οὐκ ἄξιον, ἔφη, ἀνδράσι καλοῖς κἀγαθοῖς ἐπιτάττειν","st":"425d"},{"sp":"N","t":"τὰ πολλὰ γὰρ αὐτῶν, ὅσα δεῖ νομοθετήσασθαι, ῥᾳδίως που εὑρήσουσιν.","st":"425e"},{"sp":"N","t":"Ναί, ὦ φίλε, εἶπον, ἐάν γε θεὸς αὐτοῖς διδῷ σωτηρίαν τῶν νόμων ὧν ἔμπροσθεν διήλθομεν.","st":"425e"},{"sp":"N","t":"Εἰ δὲ μή γε, ἦ δ’ ὅς, πολλὰ τοιαῦτα τιθέμενοι ἀεὶ καὶ ἐπανορθούμενοι τὸν βίον διατελοῦσιν, οἰόμενοι ἐπιλήψεσθαι τοῦ βελτίστου.","st":"425e"},{"sp":"N","t":"Λέγεις, ἔφην ἐγώ, βιώσεσθαι τοὺς τοιούτους ὥσπερ τοὺς κάμνοντάς τε καὶ οὐκ ἐθέλοντας ὑπὸ ἀκολασίας ἐκβῆναι πονηρᾶς διαίτης.","st":"425e"},{"sp":"N","t":"Πάνυ μὲν οὖν.","st":"425e"},{"sp":"N","t":"Καὶ μὴν οὗτοί γε χαριέντως διατελοῦσιν· ἰατρευόμενοι γὰρ οὐδὲν περαίνουσιν, πλήν γε ποικιλώτερα καὶ μείζω ποιοῦσι τὰ νοσήματα, καὶ ἀεὶ ἐλπίζοντες, ἐάν τις φάρμακον συμβουλεύσῃ, ὑπὸ τούτου ἔσεσθαι ὑγιεῖς.","st":"426a"},{"sp":"N","t":"Πάνυ γάρ, ἔφη, τῶν οὕτω καμνόντων τὰ τοιαῦτα πάθη.","st":"426a"},{"sp":"N","t":"Τί δέ; ἦν δ’ ἐγώ· τόδε αὐτῶν οὐ χαρίεν, τὸ πάντων ἔχθιστον ἡγεῖσθαι τὸν τἀληθῆ λέγοντα, ὅτι πρὶν ἂν μεθύων καὶ ἐμπιμπλάμενος καὶ ἀφροδισιάζων καὶ ἀργῶν παύσηται,","st":"426a"},{"sp":"N","t":"οὔτε φάρμακα οὔτε καύσεις οὔτε τομαὶ οὐδ’ αὖ ἐπῳδαὶ αὐτὸν οὐδὲ περίαπτα οὐδὲ ἄλλο τῶν τοιούτων οὐδὲν ὀνήσει;","st":"426b"},{"sp":"N","t":"Οὐ πάνυ χαρίεν, ἔφη· τὸ γὰρ τῷ εὖ λέγοντι χαλεπαίνειν οὐκ ἔχει χάριν.","st":"426b"},{"sp":"N","t":"Οὐκ ἐπαινέτης εἶ, ἔφην ἐγώ, ὡς ἔοικας, τῶν τοιούτων ἀνδρῶν.","st":"426b"},{"sp":"N","t":"Οὐ μέντοι μὰ Δία.","st":"426b"},{"sp":"N","t":"Οὐδ’ ἂν ἡ πόλις ἄρα, ὅπερ ἄρτι ἐλέγομεν, ὅλη τοιοῦτον ποιῇ, οὐκ ἐπαινέσῃ. ἢ οὐ φαίνονταί σοι ταὐτὸν ἐργάζεσθαι τούτοις τῶν πόλεων ὅσαι κακῶς πολιτευόμεναι προαγορεύουσι","st":"426b"},{"sp":"N","t":"τοῖς πολίταις τὴν μὲν κατάστασιν τῆς πόλεως ὅλην μὴ κινεῖν, ὡς ἀποθανουμένους, ὃς ἂν τοῦτο δρᾷ· ὃς δ’ ἂν σφᾶς οὕτω πολιτευομένους ἥδιστα θεραπεύῃ καὶ χαρίζηται ὑποτρέχων καὶ προγιγνώσκων τὰς σφετέρας βουλήσεις καὶ ταύτας δεινὸς ᾖ ἀποπληροῦν, οὗτος ἄρα ἀγαθός τε ἔσται ἀνὴρ καὶ σοφὸς τὰ μεγάλα καὶ τιμήσεται ὑπὸ σφῶν;","st":"426c"},{"sp":"N","t":"Ταὐτὸν μὲν οὖν, ἔφη, ἔμοιγε δοκοῦσι δρᾶν, καὶ οὐδ’ ὁπωστιοῦν ἐπαινῶ.","st":"426c"},{"sp":"N","t":"Τί δ’ αὖ τοὺς ἐθέλοντας θεραπεύειν τὰς τοιαύτας πόλεις καὶ προθυμουμένους; οὐκ ἄγασαι τῆς ἀνδρείας τε καὶ εὐχερείας;","st":"426d"},{"sp":"N","t":"Ἔγωγ’, ἔφη, πλήν γ’ ὅσοι ἐξηπάτηνται ὑπ’ αὐτῶν καὶ οἴονται τῇ ἀληθείᾳ πολιτικοὶ εἶναι, ὅτι ἐπαινοῦνται ὑπὸ τῶν πολλῶν.","st":"426d"},{"sp":"N","t":"Πῶς λέγεις; οὐ συγγιγνώσκεις, ἦν δ’ ἐγώ, τοῖς ἀνδράσιν; ἢ οἴει οἷόν τ’ εἶναι ἀνδρὶ μὴ ἐπισταμένῳ μετρεῖν, ἑτέρων","st":"426d"},{"sp":"N","t":"τοιούτων πολλῶν λεγόντων ὅτι τετράπηχύς ἐστιν, αὐτὸν ταῦτα μὴ ἡγεῖσθαι περὶ αὑτοῦ;","st":"426e"},{"sp":"N","t":"Οὐκ αὖ, ἔφη, τοῦτό γε.","st":"426e"},{"sp":"N","t":"Μὴ τοίνυν χαλέπαινε· καὶ γάρ πού εἰσι πάντων χαριέστατοι οἱ τοιοῦτοι, νομοθετοῦντές τε οἷα ἄρτι διήλθομεν καὶ ἐπανορθοῦντες, ἀεὶ οἰόμενοί τι πέρας εὑρήσειν περὶ τὰ ἐν τοῖς συμβολαίοις κακουργήματα καὶ περὶ ἃ νυνδὴ ἐγὼ ἔλεγον, ἀγνοοῦντες ὅτι τῷ ὄντι ὥσπερ Ὕδραν τέμνουσιν.","st":"426e"},{"sp":"N","t":"Καὶ μήν, ἔφη, οὐκ ἄλλο γέ τι ποιοῦσιν.","st":"427a"},{"sp":"N","t":"Ἐγὼ μὲν τοίνυν, ἦν δ’ ἐγώ, τὸ τοιοῦτον εἶδος νόμων πέρι καὶ πολιτείας οὔτ’ ἐν κακῶς οὔτ’ ἐν εὖ πολιτευομένῃ πόλει ᾤμην ἂν δεῖν τὸν ἀληθινὸν νομοθέτην πραγματεύεσθαι, ἐν τῇ μὲν ὅτι ἀνωφελῆ καὶ πλέον οὐδέν, ἐν δὲ τῇ ὅτι τὰ μὲν αὐτῶν κἂν ὁστισοῦν εὕροι, τὰ δὲ ὅτι αὐτόματα ἔπεισιν ἐκ τῶν ἔμπροσθεν ἐπιτηδευμάτων.","st":"427a"},{"sp":"N","t":"Τί οὖν, ἔφη, ἔτι ἂν ἡμῖν λοιπὸν τῆς νομοθεσίας εἴη;","st":"427b"},{"sp":"N","t":"Καὶ ἐγὼ εἶπον ὅτι Ἡμῖν μὲν οὐδέν, τῷ μέντοι Ἀπόλλωνι τῷ ἐν Δελφοῖς τά γε μέγιστα καὶ κάλλιστα καὶ πρῶτα τῶν νομοθετημάτων.","st":"427b"},{"sp":"N","t":"Τὰ ποῖα; ἦ δ’ ὅς.","st":"427b"},{"sp":"N","t":"Ἱερῶν τε ἱδρύσεις καὶ θυσίαι καὶ ἄλλαι θεῶν τε καὶ δαιμόνων καὶ ἡρώων θεραπεῖαι· τελευτησάντων ⟨τε⟩ αὖ θῆκαι καὶ ὅσα τοῖς ἐκεῖ δεῖ ὑπηρετοῦντας ἵλεως αὐτοὺς ἔχειν. τὰ γὰρ δὴ τοιαῦτα οὔτ’ ἐπιστάμεθα ἡμεῖς οἰκίζοντές τε πόλιν","st":"427b"},{"sp":"N","t":"οὐδενὶ ἄλλῳ πεισόμεθα, ἐὰν νοῦν ἔχωμεν, οὐδὲ χρησόμεθα ἐξηγητῇ ἀλλ’ ἢ τῷ πατρίῳ· οὗτος γὰρ δήπου ὁ θεὸς περὶ τὰ τοιαῦτα πᾶσιν ἀνθρώποις πάτριος ἐξηγητὴς [ἐν μέσῳ] τῆς γῆς ἐπὶ τοῦ ὀμφαλοῦ καθήμενος ἐξηγεῖται.","st":"427c"},{"sp":"N","t":"Καὶ καλῶς γ’, ἔφη, λέγεις· καὶ ποιητέον οὕτω.","st":"427c"},{"sp":"N","t":"Ὠικισμένη μὲν τοίνυν, ἦν δ’ ἐγώ, ἤδη ἄν σοι εἴη, ὦ παῖ","st":"427c"},{"sp":"N","t":"Ἀρίστωνος, ἡ πόλις· τὸ δὲ δὴ μετὰ τοῦτο σκόπει ἐν αὐτῇ, φῶς ποθὲν πορισάμενος ἱκανόν, αὐτός τε καὶ τὸν ἀδελφὸν παρακάλει καὶ Πολέμαρχον καὶ τοὺς ἄλλους, ἐάν πως ἴδωμεν ποῦ ποτ’ ἂν εἴη ἡ δικαιοσύνη καὶ ποῦ ἡ ἀδικία, καὶ τί ἀλλήλοιν διαφέρετον, καὶ πότερον δεῖ κεκτῆσθαι τὸν μέλλοντα εὐδαίμονα εἶναι, ἐάντε λανθάνῃ ἐάντε μὴ πάντας θεούς τε καὶ ἀνθρώπους.","st":"427d"},{"sp":"N","t":"Οὐδὲν λέγεις, ἔφη ὁ Γλαύκων· σὺ γὰρ ὑπέσχου ζητήσειν,","st":"427d"},{"sp":"N","t":"ὡς οὐχ ὅσιόν σοι ὂν μὴ οὐ βοηθεῖν δικαιοσύνῃ εἰς δύναμιν παντὶ τρόπῳ.","st":"427e"},{"sp":"N","t":"Ἀληθῆ, ἔφην ἐγώ, ὑπομιμνῄσκεις, καὶ ποιητέον μέν γε οὕτως, χρὴ δὲ καὶ ὑμᾶς συλλαμβάνειν.","st":"427e"},{"sp":"N","t":"Ἀλλ’, ἔφη, ποιήσομεν οὕτω.","st":"427e"},{"sp":"N","t":"Ἐλπίζω τοίνυν, ἦν δ’ ἐγώ, εὑρήσειν αὐτὸ ὧδε. οἶμαι ἡμῖν τὴν πόλιν, εἴπερ ὀρθῶς γε ᾤκισται, τελέως ἀγαθὴν εἶναι.","st":"427e"},{"sp":"N","t":"Ἀνάγκη γ’, ἔφη.","st":"427e"},{"sp":"N","t":"Δῆλον δὴ ὅτι σοφή τ’ ἐστὶ καὶ ἀνδρεία καὶ σώφρων καὶ δικαία.","st":"427e"},{"sp":"N","t":"Δῆλον.","st":"427e"},{"sp":"N","t":"Οὐκοῦν ὅτι ἂν αὐτῶν εὕρωμεν ἐν αὐτῇ, τὸ ὑπόλοιπον ἔσται τὸ οὐχ ηὑρημένον;","st":"427e"},{"sp":"N","t":"Τί μήν;","st":"428a"},{"sp":"N","t":"Ὥσπερ τοίνυν ἄλλων τινῶν τεττάρων, εἰ ἕν τι ἐζητοῦμεν αὐτῶν ἐν ὁτῳοῦν, ὁπότε πρῶτον ἐκεῖνο ἔγνωμεν, ἱκανῶς ἂν εἶχεν ἡμῖν, εἰ δὲ τὰ τρία πρότερον ἐγνωρίσαμεν, αὐτῷ ἂν τούτῳ ἐγνώριστο τὸ ζητούμενον· δῆλον γὰρ ὅτι οὐκ ἄλλο ἔτι ἦν ἢ τὸ ὑπολειφθέν.","st":"428a"},{"sp":"N","t":"Ὀρθῶς, ἔφη, λέγεις.","st":"428a"},{"sp":"N","t":"Οὐκοῦν καὶ περὶ τούτων, ἐπειδὴ τέτταρα ὄντα τυγχάνει, ὡσαύτως ζητητέον;","st":"428a"},{"sp":"N","t":"Δῆλα δή.","st":"428a"},{"sp":"N","t":"Καὶ μὲν δὴ πρῶτόν γέ μοι δοκεῖ ἐν αὐτῷ κατάδηλον εἶναι","st":"428a"},{"sp":"N","t":"ἡ σοφία· καί τι ἄτοπον περὶ αὐτὴν φαίνεται.","st":"428b"},{"sp":"N","t":"Τί; ἦ δ’ ὅς.","st":"428b"},{"sp":"N","t":"Σοφὴ μὲν τῷ ὄντι δοκεῖ μοι ἡ πόλις εἶναι ἣν διήλθομεν· εὔβουλος γάρ, οὐχί;","st":"428b"},{"sp":"N","t":"Ναί.","st":"428b"},{"sp":"N","t":"Καὶ μὴν τοῦτό γε αὐτό, ἡ εὐβουλία, δῆλον ὅτι ἐπιστήμη τίς ἐστιν· οὐ γάρ που ἀμαθίᾳ γε ἀλλ’ ἐπιστήμῃ εὖ βουλεύονται.","st":"428b"},{"sp":"N","t":"Δῆλον.","st":"428b"},{"sp":"N","t":"Πολλαὶ δέ γε καὶ παντοδαπαὶ ἐπιστῆμαι ἐν τῇ πόλει εἰσίν.","st":"428b"},{"sp":"N","t":"Πῶς γὰρ οὔ;","st":"428b"},{"sp":"N","t":"Ἆρ’ οὖν διὰ τὴν τῶν τεκτόνων ἐπιστήμην σοφὴ καὶ εὔβουλος ἡ πόλις προσρητέα;","st":"428b"},{"sp":"N","t":"Οὐδαμῶς, ἔφη, διά γε ταύτην, ἀλλὰ τεκτονική.","st":"428c"},{"sp":"N","t":"Οὐκ ἄρα διὰ τὴν ὑπὲρ τῶν ξυλίνων σκευῶν ἐπιστήμην, βουλευομένη ὡς ἂν ἔχοι βέλτιστα, σοφὴ κλητέα πόλις.","st":"428c"},{"sp":"N","t":"Οὐ μέντοι.","st":"428c"},{"sp":"N","t":"Τί δέ; τὴν ὑπὲρ τῶν ἐκ τοῦ χαλκοῦ ἤ τινα ἄλλην τῶν τοιούτων;","st":"428c"},{"sp":"N","t":"Οὐδ’ ἡντινοῦν, ἔφη.","st":"428c"},{"sp":"N","t":"Οὐδὲ τὴν ὑπὲρ τοῦ καρποῦ τῆς γενέσεως ἐκ τῆς γῆς, ἀλλὰ γεωργική.","st":"428c"},{"sp":"N","t":"Δοκεῖ μοι.","st":"428c"},{"sp":"N","t":"Τί δ’; ἦν δ’ ἐγώ· ἔστι τις ἐπιστήμη ἐν τῇ ἄρτι ὑφ’ ἡμῶν οἰκισθείσῃ παρά τισι τῶν πολιτῶν, ᾗ οὐχ ὑπὲρ τῶν","st":"428c"},{"sp":"N","t":"ἐν τῇ πόλει τινὸς βουλεύεται, ἀλλ’ ὑπὲρ αὑτῆς ὅλης, ὅντινα τρόπον αὐτή τε πρὸς αὑτὴν καὶ πρὸς τὰς ἄλλας πόλεις ἄριστα ὁμιλοῖ;","st":"428d"},{"sp":"N","t":"Ἔστι μέντοι.","st":"428d"},{"sp":"N","t":"Τίς, ἔφην ἐγώ, καὶ ἐν τίσιν;","st":"428d"},{"sp":"N","t":"Αὕτη, ἦ δ’ ὅς, ἡ φυλακική, καὶ ἐν τούτοις τοῖς ἄρχουσιν οὓς νυνδὴ τελέους φύλακας ὠνομάζομεν.","st":"428d"},{"sp":"N","t":"Διὰ ταύτην οὖν τὴν ἐπιστήμην τί τὴν πόλιν προσαγορεύεις;","st":"428d"},{"sp":"N","t":"Εὔβουλον, ἔφη, καὶ τῷ ὄντι σοφήν.","st":"428d"},{"sp":"N","t":"Πότερον οὖν, ἦν δ’ ἐγώ, ἐν τῇ πόλει οἴει ἡμῖν χαλκέας","st":"428d"},{"sp":"N","t":"πλείους ἐνέσεσθαι ἢ τοὺς ἀληθινοὺς φύλακας τούτους;","st":"428e"},{"sp":"N","t":"Πολύ, ἔφη, χαλκέας.","st":"428e"},{"sp":"N","t":"Οὐκοῦν, ἔφην, καὶ τῶν ἄλλων ὅσοι ἐπιστήμας ἔχοντες ὀνομάζονταί τινες εἶναι, πάντων τούτων οὗτοι ἂν εἶεν ὀλίγιστοι;","st":"428e"},{"sp":"N","t":"Πολύ γε.","st":"428e"},{"sp":"N","t":"Τῷ σμικροτάτῳ ἄρα ἔθνει καὶ μέρει ἑαυτῆς καὶ τῇ ἐν τούτῳ ἐπιστήμῃ, τῷ προεστῶτι καὶ ἄρχοντι, ὅλη σοφὴ ἂν εἴη κατὰ φύσιν οἰκισθεῖσα πόλις· καὶ τοῦτο, ὡς ἔοικε, φύσει","st":"428e"},{"sp":"N","t":"ὀλίγιστον γίγνεται γένος, ᾧ προσήκει ταύτης τῆς ἐπιστήμης μεταλαγχάνειν ἣν μόνην δεῖ τῶν ἄλλων ἐπιστημῶν σοφίαν καλεῖσθαι.","st":"429a"},{"sp":"N","t":"Ἀληθέστατα, ἔφη, λέγεις.","st":"429a"},{"sp":"N","t":"Τοῦτο μὲν δὴ ἓν τῶν τεττάρων οὐκ οἶδα ὅντινα τρόπον ηὑρήκαμεν, αὐτό τε καὶ ὅπου τῆς πόλεως ἵδρυται.","st":"429a"},{"sp":"N","t":"Ἐμοὶ γοῦν δοκεῖ, ἔφη, ἀποχρώντως ηὑρῆσθαι.","st":"429a"},{"sp":"N","t":"Ἀλλὰ μὴν ἀνδρεία γε αὐτή τε καὶ ἐν ᾧ κεῖται τῆς πόλεως, δι’ ὃ τοιαύτη κλητέα ἡ πόλις, οὐ πάνυ χαλεπὸν ἰδεῖν.","st":"429a"},{"sp":"N","t":"Πῶς δή;","st":"429a"},{"sp":"N","t":"Τίς ἄν, ἦν δ’ ἐγώ, εἰς ἄλλο τι ἀποβλέψας ἢ δειλὴν ἢ ἀνδρείαν πόλιν εἴποι ἀλλ’ ἢ εἰς τοῦτο τὸ μέρος ὃ προπολεμεῖ τε καὶ στρατεύεται ὑπὲρ αὐτῆς;","st":"429b"},{"sp":"N","t":"Οὐδ’ ἂν εἷς, ἔφη, εἰς ἄλλο τι.","st":"429b"},{"sp":"N","t":"Οὐ γὰρ οἶμαι, εἶπον, οἵ γε ἄλλοι ἐν αὐτῇ ἢ δειλοὶ ἢ ἀνδρεῖοι ὄντες κύριοι ἂν εἶεν ἢ τοίαν αὐτὴν εἶναι ἢ τοίαν.","st":"429b"},{"sp":"N","t":"Οὐ γάρ.","st":"429b"},{"sp":"N","t":"Καὶ ἀνδρεία ἄρα πόλις μέρει τινὶ ἑαυτῆς ἐστι, διὰ τὸ ἐν ἐκείνῳ ἔχειν δύναμιν τοιαύτην ἣ διὰ παντὸς σώσει τὴν περὶ","st":"429b"},{"sp":"N","t":"τῶν δεινῶν δόξαν, ταῦτά τε αὐτὰ εἶναι καὶ τοιαῦτα, ἅ τε καὶ οἷα ὁ νομοθέτης παρήγγελλεν ἐν τῇ παιδείᾳ. ἢ οὐ τοῦτο ἀνδρείαν καλεῖς;","st":"429c"},{"sp":"N","t":"Οὐ πάνυ, ἔφη, ἔμαθον ὃ εἶπες, ἀλλ’ αὖθις εἰπέ.","st":"429c"},{"sp":"N","t":"Σωτηρίαν ἔγωγ’, εἶπον, λέγω τινὰ εἶναι τὴν ἀνδρείαν.","st":"429c"},{"sp":"N","t":"Ποίαν δὴ σωτηρίαν;","st":"429c"},{"sp":"N","t":"Τὴν τῆς δόξης τῆς ὑπὸ νόμου διὰ τῆς παιδείας γεγονυίας περὶ τῶν δεινῶν ἅ τέ ἐστι καὶ οἷα· διὰ παντὸς δὲ ἔλεγον αὐτῆς σωτηρίαν τὸ ἔν τε λύπαις ὄντα διασῴζεσθαι αὐτὴν καὶ ἐν","st":"429c"},{"sp":"N","t":"ἡδοναῖς καὶ ἐν ἐπιθυμίαις καὶ ἐν φόβοις καὶ μὴ ἐκβάλλειν. ᾧ δέ μοι δοκεῖ ὅμοιον εἶναι ἐθέλω ἀπεικάσαι, εἰ βούλει.","st":"429d"},{"sp":"N","t":"Ἀλλὰ βούλομαι.","st":"429d"},{"sp":"N","t":"Οὐκοῦν οἶσθα, ἦν δ’ ἐγώ, ὅτι οἱ βαφῆς, ἐπειδὰν βουληθῶσι βάψαι ἔρια ὥστ’ εἶναι ἁλουργά, πρῶτον μὲν ἐκλέγονται ἐκ τοσούτων χρωμάτων μίαν φύσιν τὴν τῶν λευκῶν, ἔπειτα προπαρασκευάζουσιν, οὐκ ὀλίγῃ παρασκευῇ θεραπεύσαντες ὅπως δέξεται ὅτι μάλιστα τὸ ἄνθος, καὶ οὕτω δὴ βάπτουσι.","st":"429d"},{"sp":"N","t":"καὶ ὃ μὲν ἂν τούτῳ τῷ τρόπῳ βαφῇ, δευσοποιὸν γίγνεται τὸ βαφέν, καὶ ἡ πλύσις οὔτ’ ἄνευ ῥυμμάτων οὔτε μετὰ ῥυμμάτων δύναται αὐτῶν τὸ ἄνθος ἀφαιρεῖσθαι· ἃ δ’ ἂν μή, οἶσθα οἷα δὴ γίγνεται, ἐάντέ τις ἄλλα χρώματα βάπτῃ ἐάντε καὶ ταῦτα μὴ προθεραπεύσας.","st":"429e"},{"sp":"N","t":"Οἶδα, ἔφη, ὅτι καὶ ἔκπλυτα καὶ γελοῖα.","st":"429e"},{"sp":"N","t":"Τοιοῦτον τοίνυν, ἦν δ’ ἐγώ, ὑπόλαβε κατὰ δύναμιν ἐργάζεσθαι καὶ ἡμᾶς, ὅτε ἐξελεγόμεθα τοὺς στρατιώτας καὶ","st":"429e"},{"sp":"N","t":"ἐπαιδεύομεν μουσικῇ καὶ γυμναστικῇ· μηδὲν οἴου ἄλλο μηχανᾶσθαι ἢ ὅπως ἡμῖν ὅτι κάλλιστα τοὺς νόμους πεισθέντες δέξοιντο ὥσπερ βαφήν, ἵνα δευσοποιὸς αὐτῶν ἡ δόξα γίγνοιτο καὶ περὶ δεινῶν καὶ περὶ τῶν ἄλλων διὰ τὸ τήν τε φύσιν καὶ τὴν τροφὴν ἐπιτηδείαν ἐσχηκέναι, καὶ μὴ αὐτῶν ἐκπλύναι τὴν βαφὴν τὰ ῥύμματα ταῦτα, δεινὰ ὄντα ἐκκλύζειν, ἥ τε ἡδονή, παντὸς χαλεστραίου δεινοτέρα οὖσα τοῦτο δρᾶν","st":"430a"},{"sp":"N","t":"καὶ κονίας, λύπη τε καὶ φόβος καὶ ἐπιθυμία, παντὸς ἄλλου ῥύμματος. τὴν δὴ τοιαύτην δύναμιν καὶ σωτηρίαν διὰ παντὸς δόξης ὀρθῆς τε καὶ νομίμου δεινῶν τε πέρι καὶ μὴ ἀνδρείαν ἔγωγε καλῶ καὶ τίθεμαι, εἰ μή τι σὺ ἄλλο λέγεις.","st":"430b"},{"sp":"N","t":"Ἀλλ’ οὐδέν, ἦ δ’ ὅς, λέγω· δοκεῖς γάρ μοι τὴν ὀρθὴν δόξαν περὶ τῶν αὐτῶν τούτων ἄνευ παιδείας γεγονυῖαν, τήν τε θηριώδη καὶ ἀνδραποδώδη, οὔτε πάνυ νόμιμον ἡγεῖσθαι, ἄλλο τέ τι ἢ ἀνδρείαν καλεῖν.","st":"430b"},{"sp":"N","t":"Ἀληθέστατα, ἦν δ’ ἐγώ, λέγεις.","st":"430c"},{"sp":"N","t":"Ἀποδέχομαι τοίνυν τοῦτο ἀνδρείαν εἶναι.","st":"430c"},{"sp":"N","t":"Καὶ γὰρ ἀποδέχου, ἦν δ’ ἐγώ, πολιτικήν γε, καὶ ὀρθῶς ἀποδέξῃ· αὖθις δὲ περὶ αὐτοῦ, ἐὰν βούλῃ, ἔτι κάλλιον δίιμεν. νῦν γὰρ οὐ τοῦτο ἐζητοῦμεν, ἀλλὰ δικαιοσύνην· πρὸς οὖν τὴν ἐκείνου ζήτησιν, ὡς ἐγᾦμαι, ἱκανῶς ἔχει.","st":"430c"},{"sp":"N","t":"Ἀλλὰ καλῶς, ἔφη, λέγεις.","st":"430c"},{"sp":"N","t":"Δύο μήν, ἦν δ’ ἐγώ, ἔτι λοιπὰ ἃ δεῖ κατιδεῖν ἐν τῇ","st":"430c"},{"sp":"N","t":"πόλει, ἥ τε σωφροσύνη καὶ οὗ δὴ ἕνεκα πάντα ζητοῦμεν, δικαιοσύνη.","st":"430d"},{"sp":"N","t":"Πάνυ μὲν οὖν.","st":"430d"},{"sp":"N","t":"Πῶς οὖν ἂν τὴν δικαιοσύνην εὕροιμεν, ἵνα μηκέτι πραγματευώμεθα περὶ σωφροσύνης;","st":"430d"},{"sp":"N","t":"Ἐγὼ μὲν τοίνυν, ἔφη, οὔτε οἶδα οὔτ’ ἂν βουλοίμην αὐτὸ πρότερον φανῆναι, εἴπερ μηκέτι ἐπισκεψόμεθα σωφροσύνην· ἀλλ’ εἰ ἔμοιγε βούλει χαρίζεσθαι, σκόπει πρότερον τοῦτο ἐκείνου.","st":"430d"},{"sp":"N","t":"Ἀλλὰ μέντοι, ἦν δ’ ἐγώ, βούλομαί γε, εἰ μὴ ἀδικῶ.","st":"430e"},{"sp":"N","t":"Σκόπει δή, ἔφη.","st":"430e"},{"sp":"N","t":"Σκεπτέον, εἶπον· καὶ ὥς γε ἐντεῦθεν ἰδεῖν, συμφωνίᾳ τινὶ καὶ ἁρμονίᾳ προσέοικεν μᾶλλον ἢ τὰ πρότερον.","st":"430e"},{"sp":"N","t":"Πῶς;","st":"430e"},{"sp":"N","t":"Κόσμος πού τις, ἦν δ’ ἐγώ, ἡ σωφροσύνη ἐστὶν καὶ ἡδονῶν τινων καὶ ἐπιθυμιῶν ἐγκράτεια, ὥς φασι κρείττω δὴ αὑτοῦ ἀποφαίνοντες οὐκ οἶδ’ ὅντινα τρόπον, καὶ ἄλλα ἄττα τοιαῦτα ὥσπερ ἴχνη αὐτῆς λέγεται. ἦ γάρ;","st":"430e"},{"sp":"N","t":"Πάντων μάλιστα, ἔφη.","st":"430e"},{"sp":"N","t":"Οὐκοῦν τὸ μὲν κρείττω αὑτοῦ γελοῖον; ὁ γὰρ ἑαυτοῦ κρείττων καὶ ἥττων δήπου ἂν αὑτοῦ εἴη καὶ ὁ ἥττων κρείττων","st":"430e"},{"sp":"N","t":"ὁ αὐτὸς γὰρ ἐν ἅπασιν τούτοις προσαγορεύεται.","st":"431a"},{"sp":"N","t":"Τί δ’ οὔ;","st":"431a"},{"sp":"N","t":"Ἀλλ’, ἦν δ’ ἐγώ, φαίνεταί μοι βούλεσθαι λέγειν οὗτος ὁ λόγος ὥς τι ἐν αὐτῷ τῷ ἀνθρώπῳ περὶ τὴν ψυχὴν τὸ μὲν βέλτιον ἔνι, τὸ δὲ χεῖρον, καὶ ὅταν μὲν τὸ βέλτιον φύσει τοῦ χείρονος ἐγκρατὲς ᾖ, τοῦτο λέγειν τὸ κρείττω αὑτοῦ — ἐπαινεῖ γοῦν — ὅταν δὲ ὑπὸ τροφῆς κακῆς ἤ τινος ὁμιλίας κρατηθῇ ὑπὸ πλήθους τοῦ χείρονος σμικρότερον τὸ βέλτιον","st":"431a"},{"sp":"N","t":"ὄν, τοῦτο δὲ ὡς ἐν ὀνείδει ψέγειν τε καὶ καλεῖν ἥττω ἑαυτοῦ καὶ ἀκόλαστον τὸν οὕτω διακείμενον.","st":"431b"},{"sp":"N","t":"Καὶ γὰρ ἔοικεν, ἔφη.","st":"431b"},{"sp":"N","t":"Ἀπόβλεπε τοίνυν, ἦν δ’ ἐγώ, πρὸς τὴν νέαν ἡμῖν πόλιν, καὶ εὑρήσεις ἐν αὐτῇ τὸ ἕτερον τούτων ἐνόν· κρείττω γὰρ αὐτὴν αὑτῆς δικαίως φήσεις προσαγορεύεσθαι, εἴπερ οὗ τὸ ἄμεινον τοῦ χείρονος ἄρχει σῶφρον κλητέον καὶ κρεῖττον αὑτοῦ.","st":"431b"},{"sp":"N","t":"Ἀλλ’ ἀποβλέπω, ἔφη, καὶ ἀληθῆ λέγεις.","st":"431b"},{"sp":"N","t":"Καὶ μὴν καὶ τάς γε πολλὰς καὶ παντοδαπὰς ἐπιθυμίας καὶ","st":"431b"},{"sp":"N","t":"ἡδονάς τε καὶ λύπας ἐν παισὶ μάλιστα ἄν τις εὕροι καὶ γυναιξὶ καὶ οἰκέταις καὶ τῶν ἐλευθέρων λεγομένων ἐν τοῖς πολλοῖς τε καὶ φαύλοις.","st":"431c"},{"sp":"N","t":"Πάνυ μὲν οὖν.","st":"431c"},{"sp":"N","t":"Τὰς δέ γε ἁπλᾶς τε καὶ μετρίας, αἳ δὴ μετὰ νοῦ τε καὶ δόξης ὀρθῆς λογισμῷ ἄγονται, ἐν ὀλίγοις τε ἐπιτεύξῃ καὶ τοῖς βέλτιστα μὲν φῦσιν, βέλτιστα δὲ παιδευθεῖσιν.","st":"431c"},{"sp":"N","t":"Ἀληθῆ, ἔφη.","st":"431c"},{"sp":"N","t":"Οὐκοῦν καὶ ταῦτα ὁρᾷς ἐνόντα σοι ἐν τῇ πόλει καὶ κρατουμένας αὐτόθι τὰς ἐπιθυμίας τὰς ἐν τοῖς πολλοῖς τε","st":"431c"},{"sp":"N","t":"καὶ φαύλοις ὑπό τε τῶν ἐπιθυμιῶν καὶ τῆς φρονήσεως τῆς ἐν τοῖς ἐλάττοσί τε καὶ ἐπιεικεστέροις;","st":"431d"},{"sp":"N","t":"Ἔγωγ’, ἔφη.","st":"431d"},{"sp":"N","t":"Εἰ ἄρα δεῖ τινα πόλιν προσαγορεύειν κρείττω ἡδονῶν τε καὶ ἐπιθυμιῶν καὶ αὐτὴν αὑτῆς, καὶ ταύτην προσρητέον.","st":"431d"},{"sp":"N","t":"Παντάπασιν μὲν οὖν, ἔφη.","st":"431d"},{"sp":"N","t":"Ἆρ’ οὖν οὐ καὶ σώφρονα κατὰ πάντα ταῦτα;","st":"431d"},{"sp":"N","t":"Καὶ μάλα, ἔφη.","st":"431d"},{"sp":"N","t":"Καὶ μὴν εἴπερ αὖ ἐν ἄλλῃ πόλει ἡ αὐτὴ δόξα ἔνεστι τοῖς","st":"431d"},{"sp":"N","t":"τε ἄρχουσι καὶ ἀρχομένοις περὶ τοῦ οὕστινας δεῖ ἄρχειν, καὶ ἐν ταύτῃ ἂν εἴη τοῦτο ἐνόν. ἢ οὐ δοκεῖ;","st":"431e"},{"sp":"N","t":"Καὶ μάλα, ἔφη, σφόδρα.","st":"431e"},{"sp":"N","t":"Ἐν ποτέροις οὖν φήσεις τῶν πολιτῶν τὸ σωφρονεῖν ἐνεῖναι ὅταν οὕτως ἔχωσιν; ἐν τοῖς ἄρχουσιν ἢ ἐν τοῖς ἀρχομένοις;","st":"431e"},{"sp":"N","t":"Ἐν ἀμφοτέροις που, ἔφη.","st":"431e"},{"sp":"N","t":"Ὁρᾷς οὖν, ἦν δ’ ἐγώ, ὅτι ἐπιεικῶς ἐμαντευόμεθα ἄρτι ὡς ἁρμονίᾳ τινὶ ἡ σωφροσύνη ὡμοίωται;","st":"431e"},{"sp":"N","t":"Τί δή;","st":"431e"},{"sp":"N","t":"Ὅτι οὐχ ὥσπερ ἡ ἀνδρεία καὶ ἡ σοφία ἐν μέρει τινὶ","st":"431e"},{"sp":"N","t":"ἑκατέρα ἐνοῦσα ἡ μὲν σοφήν, ἡ δὲ ἀνδρείαν τὴν πόλιν παρείχετο, οὐχ οὕτω ποιεῖ αὕτη, ἀλλὰ δι’ ὅλης ἀτεχνῶς τέταται διὰ πασῶν παρεχομένη συνᾴδοντας τούς τε ἀσθενεστάτους ταὐτὸν καὶ τοὺς ἰσχυροτάτους καὶ τοὺς μέσους, εἰ μὲν βούλει, φρονήσει, εἰ δὲ βούλει, ἰσχύι, εἰ δέ, καὶ πλήθει ἢ χρήμασιν ἢ ἄλλῳ ὁτῳοῦν τῶν τοιούτων· ὥστε ὀρθότατ’ ἂν φαῖμεν ταύτην τὴν ὁμόνοιαν σωφροσύνην εἶναι, χείρονός τε καὶ ἀμείνονος κατὰ φύσιν συμφωνίαν ὁπότερον δεῖ ἄρχειν καὶ ἐν πόλει καὶ ἐν ἑνὶ ἑκάστῳ.","st":"432a"},{"sp":"N","t":"Πάνυ μοι, ἔφη, συνδοκεῖ.","st":"432b"},{"sp":"N","t":"Εἶεν, ἦν δ’ ἐγώ· τὰ μὲν τρία ἡμῖν ἐν τῇ πόλει κατῶπται, ὥς γε οὑτωσὶ δόξαι· τὸ δὲ δὴ λοιπὸν εἶδος, δι’ ὃ ἂν ἔτι ἀρετῆς μετέχοι πόλις, τί ποτ’ ἂν εἴη; δῆλον γὰρ ὅτι τοῦτ’ ἐστὶν ἡ δικαιοσύνη.","st":"432b"},{"sp":"N","t":"Δῆλον.","st":"432b"},{"sp":"N","t":"Οὐκοῦν, ὦ Γλαύκων, νῦν δὴ ἡμᾶς δεῖ ὥσπερ κυνηγέτας τινὰς θάμνον κύκλῳ περιίστασθαι προσέχοντας τὸν νοῦν, μή πῃ διαφύγῃ ἡ δικαιοσύνη καὶ ἀφανισθεῖσα ἄδηλος γένηται.","st":"432b"},{"sp":"N","t":"φανερὸν γὰρ δὴ ὅτι ταύτῃ πῃ ἔστιν· ὅρα οὖν καὶ προθυμοῦ κατιδεῖν, ἐάν πως πρότερος ἐμοῦ ἴδῃς καὶ ἐμοὶ φράσῃς.","st":"432c"},{"sp":"N","t":"Εἰ γὰρ ὤφελον, ἔφη. ἀλλὰ μᾶλλον, ἐάν μοι ἑπομένῳ χρῇ καὶ τὰ δεικνύμενα δυναμένῳ καθορᾶν, πάνυ μοι μετρίως χρήσῃ.","st":"432c"},{"sp":"N","t":"Ἕπου, ἦν δ’ ἐγώ, εὐξάμενος μετ’ ἐμοῦ.","st":"432c"},{"sp":"N","t":"Ποιήσω ταῦτα, ἀλλὰ μόνον, ἦ δ’ ὅς, ἡγοῦ.","st":"432c"},{"sp":"N","t":"Καὶ μήν, εἶπον ἐγώ, δύσβατός γέ τις ὁ τόπος φαίνεται καὶ ἐπίσκιος· ἔστι γοῦν σκοτεινὸς καὶ δυσδιερεύνητος. ἀλλὰ γὰρ ὅμως ἰτέον.","st":"432c"},{"sp":"N","t":"Ἰτέον γάρ, ἔφη.","st":"432d"},{"sp":"N","t":"Καὶ ἐγὼ κατιδών, Ἰοὺ ἰού, εἶπον, ὦ Γλαύκων· κινδυνεύομέν τι ἔχειν ἴχνος, καί μοι δοκεῖ οὐ πάνυ τι ἐκφευξεῖσθαι ἡμᾶς.","st":"432d"},{"sp":"N","t":"Εὖ ἀγγέλλεις, ἦ δ’ ὅς.","st":"432d"},{"sp":"N","t":"Ἦ μήν, ἦν δ’ ἐγώ, βλακικόν γε ἡμῶν τὸ πάθος.","st":"432d"},{"sp":"N","t":"Τὸ ποῖον;","st":"432d"},{"sp":"N","t":"Πάλαι, ὦ μακάριε, φαίνεται πρὸ ποδῶν ἡμῖν ἐξ ἀρχῆς κυλινδεῖσθαι, καὶ οὐχ ἑωρῶμεν ἄρ’ αὐτό, ἀλλ’ ἦμεν καταγελαστότατοι· ὥσπερ οἱ ἐν ταῖς χερσὶν ἔχοντες ζητοῦσιν","st":"432d"},{"sp":"N","t":"ἐνίοτε ὃ ἔχουσιν, καὶ ἡμεῖς εἰς αὐτὸ μὲν οὐκ ἀπεβλέπομεν, πόρρω δέ ποι ἀπεσκοποῦμεν, ᾗ δὴ καὶ ἐλάνθανεν ἴσως ἡμᾶς.","st":"432e"},{"sp":"N","t":"Πῶς, ἔφη, λέγεις;","st":"432e"},{"sp":"N","t":"Οὕτως, εἶπον, ὡς δοκοῦμέν μοι καὶ λέγοντες αὐτὸ καὶ ἀκούοντες πάλαι οὐ μανθάνειν ἡμῶν αὐτῶν, ὅτι ἐλέγομεν τρόπον τινὰ αὐτό.","st":"432e"},{"sp":"N","t":"Μακρόν, ἔφη, τὸ προοίμιον τῷ ἐπιθυμοῦντι ἀκοῦσαι.","st":"432e"},{"sp":"N","t":"Ἀλλ’, ἦν δ’ ἐγώ, ἄκουε εἴ τι ἄρα λέγω. ὃ γὰρ ἐξ ἀρχῆς ἐθέμεθα δεῖν ποιεῖν διὰ παντός, ὅτε τὴν πόλιν κατῳκίζομεν, τοῦτό ἐστιν, ὡς ἐμοὶ δοκεῖ, ἤτοι τούτου τι εἶδος ἡ δικαιοσύνη. ἐθέμεθα δὲ δήπου καὶ πολλάκις ἐλέγομεν, εἰ μέμνησαι, ὅτι ἕνα ἕκαστον ἓν δέοι ἐπιτηδεύειν τῶν περὶ τὴν πόλιν, εἰς ὃ αὐτοῦ ἡ φύσις ἐπιτηδειοτάτη πεφυκυῖα εἴη.","st":"433a"},{"sp":"N","t":"Ἐλέγομεν γάρ.","st":"433a"},{"sp":"N","t":"Καὶ μὴν ὅτι γε τὸ τὰ αὑτοῦ πράττειν καὶ μὴ πολυπραγμονεῖν δικαιοσύνη ἐστί, καὶ τοῦτο ἄλλων τε πολλῶν","st":"433a"},{"sp":"N","t":"ἀκηκόαμεν καὶ αὐτοὶ πολλάκις εἰρήκαμεν.","st":"433b"},{"sp":"N","t":"Εἰρήκαμεν γάρ.","st":"433b"},{"sp":"N","t":"Τοῦτο τοίνυν, ἦν δ’ ἐγώ, ὦ φίλε, κινδυνεύει τρόπον τινὰ γιγνόμενον ἡ δικαιοσύνη εἶναι, τὸ τὰ αὑτοῦ πράττειν. οἶσθα ὅθεν τεκμαίρομαι;","st":"433b"},{"sp":"N","t":"Οὐκ, ἀλλὰ λέγ’, ἔφη.","st":"433b"},{"sp":"N","t":"Δοκεῖ μοι, ἦν δ’ ἐγώ, τὸ ὑπόλοιπον ἐν τῇ πόλει ὧν ἐσκέμμεθα, σωφροσύνης καὶ ἀνδρείας καὶ φρονήσεως, τοῦτο εἶναι, ὃ πᾶσιν ἐκείνοις τὴν δύναμιν παρέσχεν ὥστε ἐγγενέσθαι, καὶ ἐγγενομένοις γε σωτηρίαν παρέχειν, ἕωσπερ ἂν","st":"433b"},{"sp":"N","t":"ἐνῇ. καίτοι ἔφαμεν δικαιοσύνην ἔσεσθαι τὸ ὑπολειφθὲν ἐκείνων, εἰ τὰ τρία εὕροιμεν.","st":"433c"},{"sp":"N","t":"Καὶ γὰρ ἀνάγκη, ἔφη.","st":"433c"},{"sp":"N","t":"Ἀλλὰ μέντοι, ἦν δ’ ἐγώ, εἰ δέοι γε κρῖναι τί τὴν πόλιν ἡμῖν τούτων μάλιστα ἀγαθὴν ἀπεργάσεται ἐγγενόμενον, δύσκριτον ἂν εἴη πότερον ἡ ὁμοδοξία τῶν ἀρχόντων τε καὶ ἀρχομένων, ἢ ἡ περὶ δεινῶν τε καὶ μή, ἅττα ἐστί, δόξης ἐννόμου σωτηρία ἐν τοῖς στρατιώταις ἐγγενομένη, ἢ ἡ ἐν","st":"433c"},{"sp":"N","t":"τοῖς ἄρχουσι φρόνησίς τε καὶ φυλακὴ ἐνοῦσα, ἢ τοῦτο μάλιστα ἀγαθὴν αὐτὴν ποιεῖ ἐνὸν καὶ ἐν παιδὶ καὶ ἐν γυναικὶ καὶ δούλῳ καὶ ἐλευθέρῳ καὶ δημιουργῷ καὶ ἄρχοντι καὶ ἀρχομένῳ, ὅτι τὸ αὑτοῦ ἕκαστος εἷς ὢν ἔπραττε καὶ οὐκ ἐπολυπραγμόνει.","st":"433d"},{"sp":"N","t":"Δύσκριτον, ἔφη· πῶς δ’ οὔ;","st":"433d"},{"sp":"N","t":"Ἐνάμιλλον ἄρα, ὡς ἔοικε, πρὸς ἀρετὴν πόλεως τῇ τε σοφίᾳ αὐτῆς καὶ τῇ σωφροσύνῃ καὶ τῇ ἀνδρείᾳ ἡ τοῦ ἕκαστον ἐν αὐτῇ τὰ αὑτοῦ πράττειν δύναμις.","st":"433d"},{"sp":"N","t":"Καὶ μάλα, ἔφη.","st":"433d"},{"sp":"N","t":"Οὐκοῦν δικαιοσύνην τό γε τούτοις ἐνάμιλλον ἂν εἰς ἀρετὴν","st":"433d"},{"sp":"N","t":"πόλεως θείης;","st":"433e"},{"sp":"N","t":"Παντάπασι μὲν οὖν.","st":"433e"},{"sp":"N","t":"Σκόπει δὴ καὶ τῇδε εἰ οὕτω δόξει· ἆρα τοῖς ἄρχουσιν ἐν τῇ πόλει τὰς δίκας προστάξεις δικάζειν;","st":"433e"},{"sp":"N","t":"Τί μήν;","st":"433e"},{"sp":"N","t":"Ἦ ἄλλου οὑτινοσοῦν μᾶλλον ἐφιέμενοι δικάσουσιν ἢ τούτου, ὅπως ἂν ἕκαστοι μήτ’ ἔχωσι τἀλλότρια μήτε τῶν αὑτῶν στέρωνται;","st":"433e"},{"sp":"N","t":"Οὔκ, ἀλλὰ τούτου.","st":"433e"},{"sp":"N","t":"Ὡς δικαίου ὄντος;","st":"433e"},{"sp":"N","t":"Ναί.","st":"433e"},{"sp":"N","t":"Καὶ ταύτῃ ἄρα πῃ ἡ τοῦ οἰκείου τε καὶ ἑαυτοῦ ἕξις τε καὶ","st":"433e"},{"sp":"N","t":"πρᾶξις δικαιοσύνη ἂν ὁμολογοῖτο.","st":"434a"},{"sp":"N","t":"Ἔστι ταῦτα.","st":"434a"},{"sp":"N","t":"Ἰδὲ δὴ ἐὰν σοὶ ὅπερ ἐμοὶ συνδοκῇ. τέκτων σκυτοτόμου ἐπιχειρῶν ἔργα ἐργάζεσθαι ἢ σκυτοτόμος τέκτονος, ἢ τὰ ὄργανα μεταλαμβάνοντες τἀλλήλων ἢ τιμάς, ἢ καὶ ὁ αὐτὸς ἐπιχειρῶν ἀμφότερα πράττειν, πάντα τἆλλα μεταλλαττόμενα, ἆρά σοι ἄν τι δοκεῖ μέγα βλάψαι πόλιν;","st":"434a"},{"sp":"N","t":"Οὐ πάνυ, ἔφη.","st":"434a"},{"sp":"N","t":"Ἀλλ’ ὅταν γε οἶμαι δημιουργὸς ὢν ἤ τις ἄλλος χρηματιστὴς","st":"434a"},{"sp":"N","t":"φύσει, ἔπειτα ἐπαιρόμενος ἢ πλούτῳ ἢ πλήθει ἢ ἰσχύι ἢ ἄλλῳ τῳ τοιούτῳ εἰς τὸ τοῦ πολεμικοῦ εἶδος ἐπιχειρῇ ἰέναι, ἢ τῶν πολεμικῶν τις εἰς τὸ τοῦ βουλευτικοῦ καὶ φύλακος ἀνάξιος ὤν, καὶ τὰ ἀλλήλων οὗτοι ὄργανα μεταλαμβάνωσι καὶ τὰς τιμάς, ἢ ὅταν ὁ αὐτὸς πάντα ταῦτα ἅμα ἐπιχειρῇ πράττειν, τότε οἶμαι καὶ σοὶ δοκεῖν ταύτην τὴν τούτων μεταβολὴν καὶ πολυπραγμοσύνην ὄλεθρον εἶναι τῇ πόλει.","st":"434b"},{"sp":"N","t":"Παντάπασι μὲν οὖν.","st":"434b"},{"sp":"N","t":"Ἡ τριῶν ἄρα ὄντων γενῶν πολυπραγμοσύνη καὶ μεταβολὴ","st":"434b"},{"sp":"N","t":"εἰς ἄλληλα μεγίστη τε βλάβη τῇ πόλει καὶ ὀρθότατ’ ἂν προσαγορεύοιτο μάλιστα κακουργία.","st":"434c"},{"sp":"N","t":"Κομιδῇ μὲν οὖν.","st":"434c"},{"sp":"N","t":"Κακουργίαν δὲ τὴν μεγίστην τῆς ἑαυτοῦ πόλεως οὐκ ἀδικίαν φήσεις εἶναι;","st":"434c"},{"sp":"N","t":"Πῶς δ’ οὔ;","st":"434c"},{"sp":"N","t":"Τοῦτο μὲν ἄρα ἀδικία. πάλιν δὲ ὧδε λέγωμεν· χρηματιστικοῦ, ἐπικουρικοῦ, φυλακικοῦ γένους οἰκειοπραγία, ἑκάστου τούτων τὸ αὑτοῦ πράττοντος ἐν πόλει, τοὐναντίον ἐκείνου δικαιοσύνη τ’ ἂν εἴη καὶ τὴν πόλιν δικαίαν παρέχοι;","st":"434c"},{"sp":"N","t":"Οὐκ ἄλλῃ ἔμοιγε δοκεῖ, ἦ δ’ ὅς, ἔχειν ἢ ταύτῃ.","st":"434d"},{"sp":"N","t":"Μηδέν, ἦν δ’ ἐγώ, πω πάνυ παγίως αὐτὸ λέγωμεν, ἀλλ’ ἐὰν μὲν ἡμῖν καὶ εἰς ἕνα ἕκαστον τῶν ἀνθρώπων ἰὸν τὸ εἶδος τοῦτο ὁμολογῆται καὶ ἐκεῖ δικαιοσύνη εἶναι, συγχωρησόμεθα ἤδη — τί γὰρ καὶ ἐροῦμεν; — εἰ δὲ μή, τότε ἄλλο τι σκεψόμεθα. νῦν δ’ ἐκτελέσωμεν τὴν σκέψιν ἣν ᾠήθημεν, εἰ ἐν μείζονί τινι τῶν ἐχόντων δικαιοσύνην πρότερον ⟨ἢ⟩ ἐκεῖ ἐπιχειρήσαιμεν θεάσασθαι, ῥᾷον ἂν ἐν ἑνὶ ἀνθρώπῳ κατιδεῖν οἷόν ἐστιν. καὶ","st":"434d"},{"sp":"N","t":"ἔδοξε δὴ ἡμῖν τοῦτο εἶναι πόλις, καὶ οὕτω ᾠκίζομεν ὡς ἐδυνάμεθα ἀρίστην, εὖ εἰδότες ὅτι ἔν γε τῇ ἀγαθῇ ἂν εἴη. ὃ οὖν ἡμῖν ἐκεῖ ἐφάνη, ἐπαναφέρωμεν εἰς τὸν ἕνα, κἂν μὲν ὁμολογῆται, καλῶς ἕξει· ἐὰν δέ τι ἄλλο ἐν τῷ ἑνὶ ἐμφαίνηται, πάλιν ἐπανιόντες ἐπὶ τὴν πόλιν βασανιοῦμεν, καὶ","st":"434e"},{"sp":"N","t":"τάχ’ ἂν παρ’ ἄλληλα σκοποῦντες καὶ τρίβοντες, ὥσπερ ἐκ πυρείων ἐκλάμψαι ποιήσαιμεν τὴν δικαιοσύνην· καὶ φανερὰν γενομένην βεβαιωσόμεθα αὐτὴν παρ’ ἡμῖν αὐτοῖς.","st":"435a"},{"sp":"N","t":"Ἀλλ’, ἔφη, καθ’ ὁδόν τε λέγεις καὶ ποιεῖν χρὴ οὕτως.","st":"435a"},{"sp":"N","t":"Ἆρ’ οὖν, ἦν δ’ ἐγώ, ὅ γε ταὐτὸν ἄν τις προσείποι μεῖζόν τε καὶ ἔλαττον, ἀνόμοιον τυγχάνει ὂν ταύτῃ ᾗ ταὐτὸν προσαγορεύεται, ἢ ὅμοιον;","st":"435a"},{"sp":"N","t":"Ὅμοιον, ἔφη.","st":"435a"},{"sp":"N","t":"Καὶ δίκαιος ἄρα ἀνὴρ δικαίας πόλεως κατ’ αὐτὸ τὸ τῆς δικαιοσύνης εἶδος οὐδὲν διοίσει, ἀλλ’ ὅμοιος ἔσται.","st":"435b"},{"sp":"N","t":"Ὅμοιος, ἔφη.","st":"435b"},{"sp":"N","t":"Ἀλλὰ μέντοι πόλις γε ἔδοξεν εἶναι δικαία ὅτε ἐν αὐτῇ τριττὰ γένη φύσεων ἐνόντα τὸ αὑτῶν ἕκαστον ἔπραττεν, σώφρων δὲ αὖ καὶ ἀνδρεία καὶ σοφὴ διὰ τῶν αὐτῶν τούτων γενῶν ἄλλ’ ἄττα πάθη τε καὶ ἕξεις.","st":"435b"},{"sp":"N","t":"Ἀληθῆ, ἔφη.","st":"435b"},{"sp":"N","t":"Καὶ τὸν ἕνα ἄρα, ὦ φίλε, οὕτως ἀξιώσομεν, τὰ αὐτὰ ταῦτα","st":"435b"},{"sp":"N","t":"εἴδη ἐν τῇ αὑτοῦ ψυχῇ ἔχοντα, διὰ τὰ αὐτὰ πάθη ἐκείνοις τῶν αὐτῶν ὀνομάτων ὀρθῶς ἀξιοῦσθαι τῇ πόλει.","st":"435c"},{"sp":"N","t":"Πᾶσα ἀνάγκη, ἔφη.","st":"435c"},{"sp":"N","t":"Εἰς φαῦλόν γε αὖ, ἦν δ’ ἐγώ, ὦ θαυμάσιε, σκέμμα ἐμπεπτώκαμεν περὶ ψυχῆς, εἴτε ἔχει τὰ τρία εἴδη ταῦτα ἐν αὑτῇ εἴτε μή.","st":"435c"},{"sp":"N","t":"Οὐ πάνυ μοι δοκοῦμεν, ἔφη, εἰς φαῦλον· ἴσως γάρ, ὦ Σώκρατες, τὸ λεγόμενον ἀληθές, ὅτι χαλεπὰ τὰ καλά.","st":"435c"},{"sp":"N","t":"Φαίνεται, ἦν δ’ ἐγώ. καὶ εὖ γ’ ἴσθι, ὦ Γλαύκων, ὡς ἡ","st":"435c"},{"sp":"N","t":"ἐμὴ δόξα, ἀκριβῶς μὲν τοῦτο ἐκ τοιούτων μεθόδων, οἵαις νῦν ἐν τοῖς λόγοις χρώμεθα, οὐ μή ποτε λάβωμεν — ἄλλη γὰρ μακροτέρα καὶ πλείων ὁδὸς ἡ ἐπὶ τοῦτο ἄγουσα — ἴσως μέντοι τῶν γε προειρημένων τε καὶ προεσκεμμένων ἀξίως.","st":"435d"},{"sp":"N","t":"Οὐκοῦν ἀγαπητόν; ἔφη· ἐμοὶ μὲν γὰρ ἔν γε τῷ παρόντι ἱκανῶς ἂν ἔχοι.","st":"435d"},{"sp":"N","t":"Ἀλλὰ μέντοι, εἶπον, ἔμοιγε καὶ πάνυ ἐξαρκέσει.","st":"435d"},{"sp":"N","t":"Μὴ τοίνυν ἀποκάμῃς, ἔφη, ἀλλὰ σκόπει.","st":"435d"},{"sp":"N","t":"Ἆρ’ οὖν ἡμῖν, ἦν δ’ ἐγώ, πολλὴ ἀνάγκη ὁμολογεῖν ὅτι γε τὰ αὐτὰ ἐν ἑκάστῳ ἔνεστιν ἡμῶν εἴδη τε καὶ ἤθη ἅπερ ἐν τῇ πόλει; οὐ γάρ που ἄλλοθεν ἐκεῖσε ἀφῖκται. γελοῖον γὰρ ἂν εἴη εἴ τις οἰηθείη τὸ θυμοειδὲς μὴ ἐκ τῶν ἰδιωτῶν ἐν ταῖς πόλεσιν ἐγγεγονέναι, οἳ δὴ καὶ ἔχουσι ταύτην τὴν αἰτίαν, οἷον οἱ κατὰ τὴν Θρᾴκην τε καὶ Σκυθικὴν καὶ σχεδόν τι κατὰ τὸν ἄνω τόπον, ἢ τὸ φιλομαθές, ὃ δὴ τὸν παρ’ ἡμῖν","st":"435e"},{"sp":"N","t":"μάλιστ’ ἄν τις αἰτιάσαιτο τόπον, ἢ τὸ φιλοχρήματον τὸ περὶ τούς τε Φοίνικας εἶναι καὶ τοὺς κατὰ Αἴγυπτον φαίη τις ἂν οὐχ ἥκιστα.","st":"436a"},{"sp":"N","t":"Καὶ μάλα, ἔφη.","st":"436a"},{"sp":"N","t":"Τοῦτο μὲν δὴ οὕτως ἔχει, ἦν δ’ ἐγώ, καὶ οὐδὲν χαλεπὸν γνῶναι.","st":"436a"},{"sp":"N","t":"Οὐ δῆτα.","st":"436a"},{"sp":"N","t":"Τόδε δὲ ἤδη χαλεπόν, εἰ τῷ αὐτῷ τούτῳ ἕκαστα πράττομεν ἢ τρισὶν οὖσιν ἄλλο ἄλλῳ· μανθάνομεν μὲν ἑτέρῳ, θυμούμεθα δὲ ἄλλῳ τῶν ἐν ἡμῖν, ἐπιθυμοῦμεν δ’ αὖ τρίτῳ τινὶ τῶν περὶ τὴν τροφήν τε καὶ γέννησιν ἡδονῶν καὶ ὅσα τούτων","st":"436a"},{"sp":"N","t":"ἀδελφά, ἢ ὅλῃ τῇ ψυχῇ καθ’ ἕκαστον αὐτῶν πράττομεν, ὅταν ὁρμήσωμεν. ταῦτ’ ἔσται τὰ χαλεπὰ διορίσασθαι ἀξίως λόγου.","st":"436b"},{"sp":"N","t":"Καὶ ἐμοὶ δοκεῖ, ἔφη.","st":"436b"},{"sp":"N","t":"Ὧδε τοίνυν ἐπιχειρῶμεν αὐτὰ ὁρίζεσθαι, εἴτε τὰ αὐτὰ ἀλλήλοις εἴτε ἕτερά ἐστι.","st":"436b"},{"sp":"N","t":"Πῶς;","st":"436b"},{"sp":"N","t":"Δῆλον ὅτι ταὐτὸν τἀναντία ποιεῖν ἢ πάσχειν κατὰ ταὐτόν γε καὶ πρὸς ταὐτὸν οὐκ ἐθελήσει ἅμα, ὥστε ἄν που εὑρίσκωμεν ἐν αὐτοῖς ταῦτα γιγνόμενα, εἰσόμεθα ὅτι οὐ ταὐτὸν","st":"436b"},{"sp":"N","t":"ἦν ἀλλὰ πλείω.","st":"436c"},{"sp":"N","t":"Εἶεν.","st":"436c"},{"sp":"N","t":"Σκόπει δὴ ὃ λέγω.","st":"436c"},{"sp":"N","t":"Λέγε, ἔφη.","st":"436c"},{"sp":"N","t":"Ἑστάναι, εἶπον, καὶ κινεῖσθαι τὸ αὐτὸ ἅμα κατὰ τὸ αὐτὸ ἆρα δυνατόν;","st":"436c"},{"sp":"N","t":"Οὐδαμῶς.","st":"436c"},{"sp":"N","t":"Ἔτι τοίνυν ἀκριβέστερον ὁμολογησώμεθα, μή πῃ προϊόντες ἀμφισβητήσωμεν. εἰ γάρ τις λέγοι ἄνθρωπον ἑστηκότα, κινοῦντα δὲ τὰς χεῖράς τε καὶ τὴν κεφαλήν, ὅτι ὁ αὐτὸς ἕστηκέ τε καὶ κινεῖται ἅμα, οὐκ ἂν οἶμαι ἀξιοῖμεν οὕτω","st":"436c"},{"sp":"N","t":"λέγειν δεῖν, ἀλλ’ ὅτι τὸ μέν τι αὐτοῦ ἕστηκε, τὸ δὲ κινεῖται. οὐχ οὕτω;","st":"436d"},{"sp":"N","t":"Οὕτω.","st":"436d"},{"sp":"N","t":"Οὐκοῦν καὶ εἰ ἔτι μᾶλλον χαριεντίζοιτο ὁ ταῦτα λέγων, κομψευόμενος ὡς οἵ γε στρόβιλοι ὅλοι ἑστᾶσί τε ἅμα καὶ κινοῦνται, ὅταν ἐν τῷ αὐτῷ πήξαντες τὸ κέντρον περιφέρωνται, ἢ καὶ ἄλλο τι κύκλῳ περιιὸν ἐν τῇ αὐτῇ ἕδρᾳ τοῦτο δρᾷ, οὐκ ἂν ἀποδεχοίμεθα, ὡς οὐ κατὰ ταὐτὰ ἑαυτῶν","st":"436d"},{"sp":"N","t":"τὰ τοιαῦτα τότε μενόντων τε καὶ φερομένων, ἀλλὰ φαῖμεν ἂν ἔχειν αὐτὰ εὐθύ τε καὶ περιφερὲς ἐν αὑτοῖς, καὶ κατὰ μὲν τὸ εὐθὺ ἑστάναι — οὐδαμῇ γὰρ ἀποκλίνειν — κατὰ δὲ τὸ περιφερὲς κύκλῳ κινεῖσθαι, καὶ ὅταν δὲ τὴν εὐθυωρίαν ἢ εἰς δεξιὰν ἢ εἰς ἀριστερὰν ἢ εἰς τὸ πρόσθεν ἢ εἰς τὸ ὄπισθεν ἐγκλίνῃ ἅμα περιφερόμενον, τότε οὐδαμῇ [ἔστιν] ἑστάναι.","st":"436e"},{"sp":"N","t":"Καὶ ὀρθῶς γε, ἔφη.","st":"436e"},{"sp":"N","t":"Οὐδὲν ἄρα ἡμᾶς τῶν τοιούτων λεγόμενον ἐκπλήξει, οὐδὲ μᾶλλόν τι πείσει ὥς ποτέ τι ἂν τὸ αὐτὸ ὂν ἅμα κατὰ","st":"436e"},{"sp":"N","t":"τὸ αὐτὸ πρὸς τὸ αὐτὸ τἀναντία πάθοι ἢ καὶ εἴη ἢ καὶ ποιήσειεν.","st":"437a"},{"sp":"N","t":"Οὔκουν ἐμέ γε, ἔφη.","st":"437a"},{"sp":"N","t":"Ἀλλ’ ὅμως, ἦν δ’ ἐγώ, ἵνα μὴ ἀναγκαζώμεθα πάσας τὰς τοιαύτας ἀμφισβητήσεις ἐπεξιόντες καὶ βεβαιούμενοι ὡς οὐκ ἀληθεῖς οὔσας μηκύνειν, ὑποθέμενοι ὡς τούτου οὕτως ἔχοντος εἰς τὸ πρόσθεν προΐωμεν, ὁμολογήσαντες, ἐάν ποτε ἄλλῃ φανῇ ταῦτα ἢ ταύτῃ, πάντα ἡμῖν τὰ ἀπὸ τούτου συμβαίνοντα λελυμένα ἔσεσθαι.","st":"437a"},{"sp":"N","t":"Ἀλλὰ χρή, ἔφη, ταῦτα ποιεῖν.","st":"437a"},{"sp":"N","t":"Ἆρ’ ⟨ἂν⟩ οὖν, ἦν δ’ ἐγώ, τὸ ἐπινεύειν τῷ ἀνανεύειν καὶ τὸ ἐφίεσθαί τινος λαβεῖν τῷ ἀπαρνεῖσθαι καὶ τὸ προσάγεσθαι τῷ ἀπωθεῖσθαι, πάντα τὰ τοιαῦτα τῶν ἐναντίων ἀλλήλοις θείης εἴτε ποιημάτων εἴτε παθημάτων; οὐδὲν γὰρ ταύτῃ διοίσει.","st":"437b"},{"sp":"N","t":"Ἀλλ’, ἦ δ’ ὅς, τῶν ἐναντίων.","st":"437b"},{"sp":"N","t":"Τί οὖν; ἦν δ’ ἐγώ· διψῆν καὶ πεινῆν καὶ ὅλως τὰς ἐπιθυμίας, καὶ αὖ τὸ ἐθέλειν καὶ τὸ βούλεσθαι, οὐ πάντα ταῦτα","st":"437b"},{"sp":"N","t":"εἰς ἐκεῖνά ποι ἂν θείης τὰ εἴδη τὰ νυνδὴ λεχθέντα; οἷον ἀεὶ τὴν τοῦ ἐπιθυμοῦντος ψυχὴν οὐχὶ ἤτοι ἐφίεσθαι φήσεις ἐκείνου οὗ ἂν ἐπιθυμῇ, ἢ προσάγεσθαι τοῦτο ὃ ἂν βούληταί οἱ γενέσθαι, ἢ αὖ, καθ’ ὅσον ἐθέλει τί οἱ πορισθῆναι, ἐπινεύειν τοῦτο πρὸς αὑτὴν ὥσπερ τινὸς ἐρωτῶντος, ἐπορεγομένην αὐτοῦ τῆς γενέσεως;","st":"437c"},{"sp":"N","t":"Ἔγωγε.","st":"437c"},{"sp":"N","t":"Τί δέ; τὸ ἀβουλεῖν καὶ μὴ ἐθέλειν μηδ’ ἐπιθυμεῖν οὐκ εἰς τὸ ἀπωθεῖν καὶ ἀπελαύνειν ἀπ’ αὐτῆς καὶ εἰς ἅπαντα τἀναντία ἐκείνοις θήσομεν;","st":"437c"},{"sp":"N","t":"Πῶς γὰρ οὔ;","st":"437d"},{"sp":"N","t":"Τούτων δὴ οὕτως ἐχόντων ἐπιθυμιῶν τι φήσομεν εἶναι εἶδος, καὶ ἐναργεστάτας αὐτῶν τούτων ἥν τε δίψαν καλοῦμεν καὶ ἣν πεῖναν;","st":"437d"},{"sp":"N","t":"Φήσομεν, ἦ δ’ ὅς.","st":"437d"},{"sp":"N","t":"Οὐκοῦν τὴν μὲν ποτοῦ, τὴν δ’ ἐδωδῆς;","st":"437d"},{"sp":"N","t":"Ναί.","st":"437d"},{"sp":"N","t":"Ἆρ’ οὖν, καθ’ ὅσον δίψα ἐστί, πλέονος ἄν τινος ἢ οὗ λέγομεν ἐπιθυμία ἐν τῇ ψυχῇ εἴη, οἷον δίψα ἐστὶ δίψα ἆρά γε θερμοῦ ποτοῦ ἢ ψυχροῦ, ἢ πολλοῦ ἢ ὀλίγου, ἢ καὶ ἑνὶ λόγῳ ποιοῦ τινος πώματος; ἢ ἐὰν μέν τις θερμότης τῷ","st":"437d"},{"sp":"N","t":"δίψει προσῇ, τὴν τοῦ ψυχροῦ ἐπιθυμίαν προσπαρέχοιτ’ ἄν, ἐὰν δὲ ψυχρότης, τὴν τοῦ θερμοῦ; ἐὰν δὲ διὰ πλήθους παρουσίαν πολλὴ ἡ δίψα ᾖ, τὴν τοῦ πολλοῦ παρέξεται, ἐὰν δὲ ὀλίγη, τὴν τοῦ ὀλίγου; αὐτὸ δὲ τὸ διψῆν οὐ μή ποτε ἄλλου γένηται ἐπιθυμία ἢ οὗπερ πέφυκεν, αὐτοῦ πώματος, καὶ αὖ τὸ πεινῆν βρώματος;","st":"437e"},{"sp":"N","t":"Οὕτως, ἔφη, αὐτή γε ἡ ἐπιθυμία ἑκάστη αὐτοῦ μόνον ἑκάστου οὗ πέφυκεν, τοῦ δὲ τοίου ἢ τοίου τὰ προσγιγνόμενα.","st":"437e"},{"sp":"N","t":"Μήτοι τις, ἦν δ’ ἐγώ, ἀσκέπτους ἡμᾶς ὄντας θορυβήσῃ, ὡς οὐδεὶς ποτοῦ ἐπιθυμεῖ ἀλλὰ χρηστοῦ ποτοῦ, καὶ οὐ σίτου ἀλλὰ χρηστοῦ σίτου. πάντες γὰρ ἄρα τῶν ἀγαθῶν ἐπιθυμοῦσιν· εἰ οὖν ἡ δίψα ἐπιθυμία ἐστί, χρηστοῦ ἂν εἴη εἴτε πώματος εἴτε ἄλλου ὅτου ἐστὶν ἐπιθυμία, καὶ αἱ ἄλλαι οὕτω.","st":"438a"},{"sp":"N","t":"Ἴσως γὰρ ἄν, ἔφη, δοκοῖ τι λέγειν ὁ ταῦτα λέγων.","st":"438a"},{"sp":"N","t":"Ἀλλὰ μέντοι, ἦν δ’ ἐγώ, ὅσα γ’ ἐστὶ τοιαῦτα οἷα εἶναί","st":"438a"},{"sp":"N","t":"του, τὰ μὲν ποιὰ ἄττα ποιοῦ τινός ἐστιν, ὡς ἐμοὶ δοκεῖ, τὰ δ’ αὐτὰ ἕκαστα αὐτοῦ ἑκάστου μόνον. Οὐκ ἔμαθον, ἔφη.","st":"438b"},{"sp":"N","t":"Οὐκ ἔμαθες, ἔφην, ὅτι τὸ μεῖζον τοιοῦτόν ἐστιν οἷον τινὸς εἶναι μεῖζον;","st":"438b"},{"sp":"N","t":"Πάνυ γε.","st":"438b"},{"sp":"N","t":"Οὐκοῦν τοῦ ἐλάττονος;","st":"438b"},{"sp":"N","t":"Ναί.","st":"438b"},{"sp":"N","t":"Τὸ δέ γε πολὺ μεῖζον πολὺ ἐλάττονος. ἦ γάρ;","st":"438b"},{"sp":"N","t":"Ναί.","st":"438b"},{"sp":"N","t":"Ἆρ’ οὖν καὶ τὸ ποτὲ μεῖζον ποτὲ ἐλάττονος, καὶ τὸ ἐσόμενον μεῖζον ἐσομένου ἐλάττονος;","st":"438b"},{"sp":"N","t":"Ἀλλὰ τί μήν; ἦ δ’ ὅς.","st":"438b"},{"sp":"N","t":"Καὶ τὰ πλείω δὴ πρὸς τὰ ἐλάττω καὶ τὰ διπλάσια πρὸς τὰ ἡμίσεα καὶ πάντα τὰ τοιαῦτα, καὶ αὖ βαρύτερα πρὸς κουφότερα καὶ θάττω πρὸς τὰ βραδύτερα, καὶ ἔτι γε τὰ θερμὰ πρὸς τὰ ψυχρὰ καὶ πάντα τὰ τούτοις ὅμοια ἆρ’ οὐχ οὕτως ἔχει;","st":"438c"},{"sp":"N","t":"Πάνυ μὲν οὖν.","st":"438c"},{"sp":"N","t":"Τί δὲ τὰ περὶ τὰς ἐπιστήμας; οὐχ ὁ αὐτὸς τρόπος; ἐπιστήμη μὲν αὐτὴ μαθήματος αὐτοῦ ἐπιστήμη ἐστὶν ἢ ὅτου δὴ δεῖ θεῖναι τὴν ἐπιστήμην, ἐπιστήμη δέ τις καὶ ποιά τις","st":"438c"},{"sp":"N","t":"ποιοῦ τινος καὶ τινός. λέγω δὲ τὸ τοιόνδε· οὐκ ἐπειδὴ οἰκίας ἐργασίας ἐπιστήμη ἐγένετο, διήνεγκε τῶν ἄλλων ἐπιστημῶν, ὥστε οἰκοδομικὴ κληθῆναι;","st":"438d"},{"sp":"N","t":"Τί μήν;","st":"438d"},{"sp":"N","t":"Ἆρ’ οὐ τῷ ποιά τις εἶναι, οἵα ἑτέρα οὐδεμία τῶν ἄλλων;","st":"438d"},{"sp":"N","t":"Ναί.","st":"438d"},{"sp":"N","t":"Οὐκοῦν ἐπειδὴ ποιοῦ τινος, καὶ αὐτὴ ποιά τις ἐγένετο; καὶ αἱ ἄλλαι οὕτω τέχναι τε καὶ ἐπιστῆμαι;","st":"438d"},{"sp":"N","t":"Ἔστιν οὕτω.","st":"438d"},{"sp":"N","t":"Τοῦτο τοίνυν, ἦν δ’ ἐγώ, φάθι με τότε βούλεσθαι λέγειν, εἰ ἄρα νῦν ἔμαθες, ὅτι ὅσα ἐστὶν οἷα εἶναί του, αὐτὰ μὲν μόνα αὐτῶν μόνων ἐστίν, τῶν δὲ ποιῶν τινων ποιὰ ἄττα.","st":"438d"},{"sp":"N","t":"καὶ οὔ τι λέγω, ὡς, οἵων ἂν ᾖ, τοιαῦτα καὶ ἔστιν, ὡς ἄρα καὶ τῶν ὑγιεινῶν καὶ νοσωδῶν ἡ ἐπιστήμη ὑγιεινὴ καὶ νοσώδης καὶ τῶν κακῶν καὶ τῶν ἀγαθῶν κακὴ καὶ ἀγαθή· ἀλλ’ ἐπειδὴ οὐκ αὐτοῦ οὗπερ ἐπιστήμη ἐστὶν ἐγένετο ἐπιστήμη, ἀλλὰ ποιοῦ τινος, τοῦτο δ’ ἦν ὑγιεινὸν καὶ νοσῶδες, ποιὰ δή τις συνέβη καὶ αὐτὴ γενέσθαι, καὶ τοῦτο αὐτὴν ἐποίησεν μηκέτι ἐπιστήμην ἁπλῶς καλεῖσθαι, ἀλλὰ τοῦ ποιοῦ τινος προσγενομένου ἰατρικήν.","st":"438e"},{"sp":"N","t":"Ἔμαθον, ἔφη, καί μοι δοκεῖ οὕτως ἔχειν.","st":"438e"},{"sp":"N","t":"Τὸ δὲ δὴ δίψος, ἦν δ’ ἐγώ, οὐ τούτων θήσεις τῶν τινὸς εἶναι τοῦτο ὅπερ ἐστίν; ἔστι δὲ δήπου δίψος —","st":"439a"},{"sp":"N","t":"Ἔγωγε, ἦ δ’ ὅς· πώματός γε.","st":"439a"},{"sp":"N","t":"Οὐκοῦν ποιοῦ μέν τινος πώματος ποιόν τι καὶ δίψος, δίψος δ’ οὖν αὐτὸ οὔτε πολλοῦ οὔτε ὀλίγου, οὔτε ἀγαθοῦ οὔτε κακοῦ, οὐδ’ ἑνὶ λόγῳ ποιοῦ τινος, ἀλλ’ αὐτοῦ πώματος μόνον αὐτὸ δίψος πέφυκεν;","st":"439a"},{"sp":"N","t":"Παντάπασι μὲν οὖν.","st":"439a"},{"sp":"N","t":"Τοῦ διψῶντος ἄρα ἡ ψυχή, καθ’ ὅσον διψῇ, οὐκ ἄλλο","st":"439a"},{"sp":"N","t":"τι βούλεται ἢ πιεῖν, καὶ τούτου ὀρέγεται καὶ ἐπὶ τοῦτο ὁρμᾷ.","st":"439b"},{"sp":"N","t":"Δῆλον δή.","st":"439b"},{"sp":"N","t":"Οὐκοῦν εἴ ποτέ τι αὐτὴν ἀνθέλκει διψῶσαν, ἕτερον ἄν τι ἐν αὐτῇ εἴη αὐτοῦ τοῦ διψῶντος καὶ ἄγοντος ὥσπερ θηρίον ἐπὶ τὸ πιεῖν; οὐ γὰρ δή, φαμέν, τό γε αὐτὸ τῷ αὐτῷ ἑαυτοῦ περὶ τὸ αὐτὸ ἅμ’ ἂ⟨ν⟩ τἀναντία πράττοι.","st":"439b"},{"sp":"N","t":"Οὐ γὰρ οὖν.","st":"439b"},{"sp":"N","t":"Ὥσπερ γε οἶμαι τοῦ τοξότου οὐ καλῶς ἔχει λέγειν ὅτι αὐτοῦ ἅμα αἱ χεῖρες τὸ τόξον ἀπωθοῦνταί τε καὶ προσέλκονται, ἀλλ’ ὅτι ἄλλη μὲν ἡ ἀπωθοῦσα χείρ, ἑτέρα δὲ ἡ προσαγομένη.","st":"439b"},{"sp":"N","t":"Παντάπασι μὲν οὖν, ἔφη.","st":"439c"},{"sp":"N","t":"Πότερον δὴ φῶμέν τινας ἔστιν ὅτε διψῶντας οὐκ ἐθέλειν πιεῖν;","st":"439c"},{"sp":"N","t":"Καὶ μάλα γ’, ἔφη, πολλοὺς καὶ πολλάκις.","st":"439c"},{"sp":"N","t":"Τί οὖν, ἔφην ἐγώ, φαίη τις ἂν τούτων πέρι; οὐκ ἐνεῖναι μὲν ἐν τῇ ψυχῇ αὐτῶν τὸ κελεῦον, ἐνεῖναι δὲ τὸ κωλῦον πιεῖν, ἄλλο ὂν καὶ κρατοῦν τοῦ κελεύοντος;","st":"439c"},{"sp":"N","t":"Ἔμοιγε, ἔφη, δοκεῖ.","st":"439c"},{"sp":"N","t":"Ἆρ’ οὖν οὐ τὸ μὲν κωλῦον τὰ τοιαῦτα ἐγγίγνεται, ὅταν","st":"439c"},{"sp":"N","t":"ἐγγένηται, ἐκ λογισμοῦ, τὰ δὲ ἄγοντα καὶ ἕλκοντα διὰ παθημάτων τε καὶ νοσημάτων παραγίγνεται;","st":"439d"},{"sp":"N","t":"Φαίνεται.","st":"439d"},{"sp":"N","t":"Οὐ δὴ ἀλόγως, ἦν δ’ ἐγώ, ἀξιώσομεν αὐτὰ διττά τε καὶ ἕτερα ἀλλήλων εἶναι, τὸ μὲν ᾧ λογίζεται λογιστικὸν προσαγορεύοντες τῆς ψυχῆς, τὸ δὲ ᾧ ἐρᾷ τε καὶ πεινῇ καὶ διψῇ καὶ περὶ τὰς ἄλλας ἐπιθυμίας ἐπτόηται ἀλόγιστόν τε καὶ ἐπιθυμητικόν, πληρώσεών τινων καὶ ἡδονῶν ἑταῖρον.","st":"439d"},{"sp":"N","t":"Οὔκ, ἀλλ’ εἰκότως, ἔφη, ἡγοίμεθ’ ἂν οὕτως.","st":"439e"},{"sp":"N","t":"Ταῦτα μὲν τοίνυν, ἦν δ’ ἐγώ, δύο ἡμῖν ὡρίσθω εἴδη ἐν ψυχῇ ἐνόντα· τὸ δὲ δὴ τοῦ θυμοῦ καὶ ᾧ θυμούμεθα πότερον τρίτον, ἢ τούτων ποτέρῳ ἂν εἴη ὁμοφυές;","st":"439e"},{"sp":"N","t":"Ἴσως, ἔφη, τῷ ἑτέρῳ, τῷ ἐπιθυμητικῷ.","st":"439e"},{"sp":"N","t":"Ἀλλ’, ἦν δ’ ἐγώ, ποτὲ ἀκούσας τι† πιστεύω τούτῳ· ὡς ἄρα Λεόντιος ὁ Ἀγλαΐωνος ἀνιὼν ἐκ Πειραιῶς ὑπὸ τὸ βόρειον τεῖχος ἐκτός, αἰσθόμενος νεκροὺς παρὰ τῷ δημίῳ κειμένους, ἅμα μὲν ἰδεῖν ἐπιθυμοῖ, ἅμα δὲ αὖ δυσχεραίνοι καὶ ἀποτρέποι ἑαυτόν, καὶ τέως μὲν μάχοιτό τε καὶ παρακαλύπτοιτο,","st":"439e"},{"sp":"N","t":"κρατούμενος δ’ οὖν ὑπὸ τῆς ἐπιθυμίας, διελκύσας τοὺς ὀφθαλμούς, προσδραμὼν πρὸς τοὺς νεκρούς, “Ἰδοὺ ὑμῖν,” ἔφη, “ὦ κακοδαίμονες, ἐμπλήσθητε τοῦ καλοῦ θεάματος.”","st":"440a"},{"sp":"N","t":"Ἤκουσα, ἔφη, καὶ αὐτός.","st":"440a"},{"sp":"N","t":"Οὗτος μέντοι, ἔφην, ὁ λόγος σημαίνει τὴν ὀργὴν πολεμεῖν ἐνίοτε ταῖς ἐπιθυμίαις ὡς ἄλλο ὂν ἄλλῳ.","st":"440a"},{"sp":"N","t":"Σημαίνει γάρ, ἔφη.","st":"440a"},{"sp":"N","t":"Οὐκοῦν καὶ ἄλλοθι, ἔφην, πολλαχοῦ αἰσθανόμεθα, ὅταν","st":"440a"},{"sp":"N","t":"βιάζωνταί τινα παρὰ τὸν λογισμὸν ἐπιθυμίαι, λοιδοροῦντά τε αὑτὸν καὶ θυμούμενον τῷ βιαζομένῳ ἐν αὑτῷ, καὶ ὥσπερ δυοῖν στασιαζόντοιν σύμμαχον τῷ λόγῳ γιγνόμενον τὸν θυμὸν τοῦ τοιούτου; ταῖς δ’ ἐπιθυμίαις αὐτὸν κοινωνήσαντα, αἱροῦντος λόγου μὴ δεῖν ἀντιπράττειν, οἶμαί σε οὐκ ἂν φάναι γενομένου ποτὲ ἐν σαυτῷ τοῦ τοιούτου αἰσθέσθαι, οἶμαι δ’ οὐδ’ ἐν ἄλλῳ.","st":"440b"},{"sp":"N","t":"Οὐ μὰ τὸν Δία, ἔφη.","st":"440b"},{"sp":"N","t":"Τί δέ, ἦν δ’ ἐγώ, ὅταν τις οἴηται ἀδικεῖν; οὐχ ὅσῳ ἂν γενναιότερος ᾖ, τοσούτῳ ἧττον δύναται ὀργίζεσθαι καὶ πεινῶν καὶ ῥιγῶν καὶ ἄλλο ὁτιοῦν τῶν τοιούτων πάσχων ὑπ’ ἐκείνου ὃν ἂν οἴηται δικαίως ταῦτα δρᾶν, καί, ὃ λέγω, οὐκ ἐθέλει πρὸς τοῦτον αὐτοῦ ἐγείρεσθαι ὁ θυμός;","st":"440c"},{"sp":"N","t":"Ἀληθῆ, ἔφη.","st":"440c"},{"sp":"N","t":"Τί δὲ ὅταν ἀδικεῖσθαί τις ἡγῆται; οὐκ ἐν τούτῳ ζεῖ τε καὶ χαλεπαίνει καὶ συμμαχεῖ τῷ δοκοῦντι δικαίῳ καί, διὰ τὸ πεινῆν καὶ διὰ τὸ ῥιγοῦν καὶ πάντα τὰ τοιαῦτα πάσχειν,","st":"440c"},{"sp":"N","t":"ὑπομένων καὶ νικᾷ καὶ οὐ λήγει τῶν γενναίων, πρὶν ἂν ἢ διαπράξηται ἢ τελευτήσῃ ἢ ὥσπερ κύων ὑπὸ νομέως ὑπὸ τοῦ λόγου τοῦ παρ’ αὑτῷ ἀνακληθεὶς πραϋνθῇ;","st":"440d"},{"sp":"N","t":"Πάνυ μὲν οὖν, ἔφη, ἔοικε τούτῳ ᾧ λέγεις· καίτοι γ’ ἐν τῇ ἡμετέρᾳ πόλει τοὺς ἐπικούρους ὥσπερ κύνας ἐθέμεθα ὑπηκόους τῶν ἀρχόντων ὥσπερ ποιμένων πόλεως.","st":"440d"},{"sp":"N","t":"Καλῶς γάρ, ἦν δ’ ἐγώ, νοεῖς ὃ βούλομαι λέγειν. ἀλλ’ ἦ πρὸς τούτῳ καὶ τόδε ἐνθυμῇ;","st":"440d"},{"sp":"N","t":"Τὸ ποῖον;","st":"440e"},{"sp":"N","t":"Ὅτι τοὐναντίον ἢ ἀρτίως ἡμῖν φαίνεται περὶ τοῦ θυμοειδοῦς. τότε μὲν γὰρ ἐπιθυμητικόν τι αὐτὸ ᾠόμεθα εἶναι, νῦν δὲ πολλοῦ δεῖν φαμεν, ἀλλὰ πολὺ μᾶλλον αὐτὸ ἐν τῇ τῆς ψυχῆς στάσει τίθεσθαι τὰ ὅπλα πρὸς τὸ λογιστικόν.","st":"440e"},{"sp":"N","t":"Παντάπασιν, ἔφη.","st":"440e"},{"sp":"N","t":"Ἆρ’ οὖν ἕτερον ὂν καὶ τούτου, ἢ λογιστικοῦ τι εἶδος, ὥστε μὴ τρία ἀλλὰ δύο εἴδη εἶναι ἐν ψυχῇ, λογιστικὸν καὶ ἐπιθυμητικόν; ἢ καθάπερ ἐν τῇ πόλει συνεῖχεν αὐτὴν τρία","st":"440e"},{"sp":"N","t":"ὄντα γένη, χρηματιστικόν, ἐπικουρητικόν, βουλευτικόν, οὕτως καὶ ἐν ψυχῇ τρίτον τοῦτό ἐστι τὸ θυμοειδές, ἐπίκουρον ὂν τῷ λογιστικῷ φύσει, ἐὰν μὴ ὑπὸ κακῆς τροφῆς διαφθαρῇ;","st":"441a"},{"sp":"N","t":"Ἀνάγκη, ἔφη, τρίτον.","st":"441a"},{"sp":"N","t":"Ναί, ἦν δ’ ἐγώ, ἄν γε τοῦ λογιστικοῦ ἄλλο τι φανῇ, ὥσπερ τοῦ ἐπιθυμητικοῦ ἐφάνη ἕτερον ὄν.","st":"441a"},{"sp":"N","t":"Ἀλλ’ οὐ χαλεπόν, ἔφη, φανῆναι· καὶ γὰρ ἐν τοῖς παιδίοις τοῦτό γ’ ἄν τις ἴδοι, ὅτι θυμοῦ μὲν εὐθὺς γενόμενα μεστά ἐστι, λογισμοῦ δ’ ἔνιοι μὲν ἔμοιγε δοκοῦσιν οὐδέποτε μεταλαμβάνειν,","st":"441a"},{"sp":"N","t":"οἱ δὲ πολλοὶ ὀψέ ποτε.","st":"441b"},{"sp":"N","t":"Ναὶ μὰ Δί’, ἦν δ’ ἐγώ, καλῶς γε εἶπες. ἔτι δὲ ἐν τοῖς θηρίοις ἄν τις ἴδοι ὃ λέγεις, ὅτι οὕτως ἔχει. πρὸς δὲ τούτοις καὶ ὃ ἄνω που [ἐκεῖ] εἴπομεν, τὸ τοῦ Ὁμήρου μαρτυρήσει, τὸ —","st":"441b"},{"sp":"N","t":"στῆθος δὲ πλήξας κραδίην ἠνίπαπε μύθῳ","st":"441b"},{"sp":"N","t":"ἐνταῦθα γὰρ δὴ σαφῶς ὡς ἕτερον ἑτέρῳ ἐπιπλῆττον πεποίηκεν","st":"441b"},{"sp":"N","t":"Ὅμηρος τὸ ἀναλογισάμενον περὶ τοῦ βελτίονός τε καὶ χείρονος τῷ ἀλογίστως θυμουμένῳ. Κομιδῇ, ἔφη, ὀρθῶς λέγεις.","st":"441c"},{"sp":"N","t":"Ταῦτα μὲν ἄρα, ἦν δ’ ἐγώ, μόγις διανενεύκαμεν, καὶ ἡμῖν ἐπιεικῶς ὡμολόγηται τὰ αὐτὰ μὲν ἐν πόλει, τὰ αὐτὰ δ’ ἐν ἑνὸς ἑκάστου τῇ ψυχῇ γένη ἐνεῖναι καὶ ἴσα τὸν ἀριθμόν.","st":"441c"},{"sp":"N","t":"Ἔστι ταῦτα.","st":"441c"},{"sp":"N","t":"Οὐκοῦν ἐκεῖνό γε ἤδη ἀναγκαῖον, ὡς πόλις ἦν σοφὴ καὶ ᾧ, οὕτω καὶ τὸν ἰδιώτην καὶ τούτῳ σοφὸν εἶναι;","st":"441c"},{"sp":"N","t":"Τί μήν;","st":"441c"},{"sp":"N","t":"Καὶ ᾧ δὴ ἀνδρεῖος ἰδιώτης καὶ ὥς, τούτῳ καὶ πόλιν ἀνδρείαν καὶ οὕτως, καὶ τἆλλα πάντα πρὸς ἀρετὴν ὡσαύτως ἀμφότερα ἔχειν;","st":"441d"},{"sp":"N","t":"Ἀνάγκη.","st":"441d"},{"sp":"N","t":"Καὶ δίκαιον δή, ὦ Γλαύκων, οἶμαι φήσομεν ἄνδρα εἶναι τῷ αὐτῷ τρόπῳ ᾧπερ καὶ πόλις ἦν δικαία.","st":"441d"},{"sp":"N","t":"Καὶ τοῦτο πᾶσα ἀνάγκη.","st":"441d"},{"sp":"N","t":"Ἀλλ’ οὔ πῃ μὴν τοῦτό γε ἐπιλελήσμεθα, ὅτι ἐκείνη γε τῷ τὸ ἑαυτοῦ ἕκαστον ἐν αὐτῇ πράττειν τριῶν ὄντων γενῶν δικαία ἦν.","st":"441d"},{"sp":"N","t":"Οὔ μοι δοκοῦμεν, ἔφη, ἐπιλελῆσθαι.","st":"441d"},{"sp":"N","t":"Μνημονευτέον ἄρα ἡμῖν ὅτι καὶ ἡμῶν ἕκαστος, ὅτου ἂν","st":"441d"},{"sp":"N","t":"τὰ αὑτοῦ ἕκαστον τῶν ἐν αὐτῷ πράττῃ, οὗτος δίκαιός τε ἔσται καὶ τὰ αὑτοῦ πράττων.","st":"441e"},{"sp":"N","t":"Καὶ μάλα, ἦ δ’ ὅς, μνημονευτέον.","st":"441e"},{"sp":"N","t":"Οὐκοῦν τῷ μὲν λογιστικῷ ἄρχειν προσήκει, σοφῷ ὄντι καὶ ἔχοντι τὴν ὑπὲρ ἁπάσης τῆς ψυχῆς προμήθειαν, τῷ δὲ θυμοειδεῖ ὑπηκόῳ εἶναι καὶ συμμάχῳ τούτου;","st":"441e"},{"sp":"N","t":"Πάνυ γε.","st":"441e"},{"sp":"N","t":"Ἆρ’ οὖν οὐχ, ὥσπερ ἐλέγομεν, μουσικῆς καὶ γυμναστικῆς κρᾶσις σύμφωνα αὐτὰ ποιήσει, τὸ μὲν ἐπιτείνουσα καὶ","st":"441e"},{"sp":"N","t":"τρέφουσα λόγοις τε καλοῖς καὶ μαθήμασιν, τὸ δὲ ἀνιεῖσα παραμυθουμένη, ἡμεροῦσα ἁρμονίᾳ τε καὶ ῥυθμῷ;","st":"442a"},{"sp":"N","t":"Κομιδῇ γε, ἦ δ’ ὅς.","st":"442a"},{"sp":"N","t":"Καὶ τούτω δὴ οὕτω τραφέντε καὶ ὡς ἀληθῶς τὰ αὑτῶν μαθόντε καὶ παιδευθέντε προστήσεσθον τοῦ ἐπιθυμητικοῦ — ὃ δὴ πλεῖστον τῆς ψυχῆς ἐν ἑκάστῳ ἐστὶ καὶ χρημάτων φύσει ἀπληστότατον — ὃ τηρήσετον μὴ τῷ πίμπλασθαι τῶν περὶ τὸ σῶμα καλουμένων ἡδονῶν πολὺ καὶ ἰσχυρὸν γενόμενον","st":"442a"},{"sp":"N","t":"οὐκ αὖ τὰ αὑτοῦ πράττῃ, ἀλλὰ καταδουλώσασθαι καὶ ἄρχειν ἐπιχειρήσῃ ὧν οὐ προσῆκον αὐτῷ γένει, καὶ σύμπαντα τὸν βίον πάντων ἀνατρέψῃ.","st":"442b"},{"sp":"N","t":"Πάνυ μὲν οὖν, ἔφη.","st":"442b"},{"sp":"N","t":"Ἆρ’ οὖν, ἦν δ’ ἐγώ, καὶ τοὺς ἔξωθεν πολεμίους τούτω ἂν κάλλιστα φυλαττοίτην ὑπὲρ ἁπάσης τῆς ψυχῆς τε καὶ τοῦ σώματος, τὸ μὲν βουλευόμενον, τὸ δὲ προπολεμοῦν, ἑπόμενον [δὲ] τῷ ἄρχοντι καὶ τῇ ἀνδρείᾳ ἐπιτελοῦν τὰ βουλευθέντα;","st":"442b"},{"sp":"N","t":"Ἔστι ταῦτα.","st":"442b"},{"sp":"N","t":"Καὶ ἀνδρεῖον δὴ οἶμαι τούτῳ τῷ μέρει καλοῦμεν ἕνα","st":"442b"},{"sp":"N","t":"ἕκαστον, ὅταν αὐτοῦ τὸ θυμοειδὲς διασῴζῃ διά τε λυπῶν καὶ ἡδονῶν τὸ ὑπὸ τῶν λόγων παραγγελθὲν δεινόν τε καὶ μή.","st":"442c"},{"sp":"N","t":"Ὀρθῶς γ’, ἔφη.","st":"442c"},{"sp":"N","t":"Σοφὸν δέ γε ἐκείνῳ τῷ σμικρῷ μέρει, τῷ ὃ ἦρχέν τ’ ἐν αὐτῷ καὶ ταῦτα παρήγγελλεν, ἔχον αὖ κἀκεῖνο ἐπιστήμην ἐν αὑτῷ τὴν τοῦ συμφέροντος ἑκάστῳ τε καὶ ὅλῳ τῷ κοινῷ σφῶν αὐτῶν τριῶν ὄντων.","st":"442c"},{"sp":"N","t":"Πάνυ μὲν οὖν.","st":"442c"},{"sp":"N","t":"Τί δέ; σώφρονα οὐ τῇ φιλίᾳ καὶ συμφωνίᾳ τῇ αὐτῶν τούτων, ὅταν τό τε ἄρχον καὶ τὼ ἀρχομένω τὸ λογιστικὸν","st":"442c"},{"sp":"N","t":"ὁμοδοξῶσι δεῖν ἄρχειν καὶ μὴ στασιάζωσιν αὐτῷ;","st":"442d"},{"sp":"N","t":"Σωφροσύνη γοῦν, ἦ δ’ ὅς, οὐκ ἄλλο τί ἐστιν ἢ τοῦτο, πόλεώς τε καὶ ἰδιώτου.","st":"442d"},{"sp":"N","t":"Ἀλλὰ μὲν δὴ δίκαιός γε, ᾧ πολλάκις λέγομεν, τούτῳ καὶ οὕτως ἔσται.","st":"442d"},{"sp":"N","t":"Πολλὴ ἀνάγκη.","st":"442d"},{"sp":"N","t":"Τί οὖν; εἶπον ἐγώ· μή πῃ ἡμῖν ἀπαμβλύνεται ἄλλο τι δικαιοσύνη δοκεῖν εἶναι ἢ ὅπερ ἐν τῇ πόλει ἐφάνη;","st":"442d"},{"sp":"N","t":"Οὐκ ἔμοιγε, ἔφη, δοκεῖ.","st":"442d"},{"sp":"N","t":"Ὧδε γάρ, ἦν δ’ ἐγώ, παντάπασιν ἂν βεβαιωσαίμεθα","st":"442d"},{"sp":"N","t":"εἴ τι ἡμῶν ἔτι ἐν τῇ ψυχῇ ἀμφισβητεῖ, τὰ φορτικὰ αὐτῷ προσφέροντες.","st":"442e"},{"sp":"N","t":"Ποῖα δή;","st":"442e"},{"sp":"N","t":"Οἷον εἰ δέοι ἡμᾶς ἀνομολογεῖσθαι περί τε ἐκείνης τῆς πόλεως καὶ τοῦ ἐκείνῃ ὁμοίως πεφυκότος τε καὶ τεθραμμένου ἀνδρός, εἰ δοκεῖ ἂν παρακαταθήκην χρυσίου ἢ ἀργυρίου δεξάμενος ὁ τοιοῦτος ἀποστερῆσαι, τίν’ ἂν οἴει οἰηθῆναι","st":"442e"},{"sp":"N","t":"τοῦτον αὐτὸ δρᾶσαι μᾶλλον ἢ ὅσοι μὴ τοιοῦτοι;","st":"443a"},{"sp":"N","t":"Οὐδέν’ ἄν, ἔφη.","st":"443a"},{"sp":"N","t":"Οὐκοῦν καὶ ἱεροσυλιῶν καὶ κλοπῶν καὶ προδοσιῶν, ἢ ἰδίᾳ ἑταίρων ἢ δημοσίᾳ πόλεων, ἐκτὸς ἂν οὗτος εἴη;","st":"443a"},{"sp":"N","t":"ἐκτός.","st":"443a"},{"sp":"N","t":"Καὶ μὴν οὐδ’ ὁπωστιοῦν γ’ ἂν ἄπιστος ἢ κατὰ ὅρκους ἢ κατὰ τὰς ἄλλας ὁμολογίας.","st":"443a"},{"sp":"N","t":"Πῶς γὰρ ἄν;","st":"443a"},{"sp":"N","t":"Μοιχεῖαί γε μὴν καὶ γονέων ἀμέλειαι καὶ θεῶν ἀθεραπευσίαι παντὶ ἄλλῳ μᾶλλον ἢ τῷ τοιούτῳ προσήκουσι.","st":"443a"},{"sp":"N","t":"Παντὶ μέντοι, ἔφη.","st":"443a"},{"sp":"N","t":"Οὐκοῦν τούτων πάντων αἴτιον ὅτι αὐτοῦ τῶν ἐν αὐτῷ ἕκαστον τὰ αὑτοῦ πράττει ἀρχῆς τε πέρι καὶ τοῦ ἄρχεσθαι;","st":"443b"},{"sp":"N","t":"Τοῦτο μὲν οὖν, καὶ οὐδὲν ἄλλο.","st":"443b"},{"sp":"N","t":"Ἔτι τι οὖν ἕτερον ζητεῖς δικαιοσύνην εἶναι ἢ ταύτην τὴν δύναμιν ἣ τοὺς τοιούτους ἄνδρας τε παρέχεται καὶ πόλεις;","st":"443b"},{"sp":"N","t":"Μὰ Δία, ἦ δ’ ὅς, οὐκ ἔγωγε.","st":"443b"},{"sp":"N","t":"Τέλεον ἄρα ἡμῖν τὸ ἐνύπνιον ἀποτετέλεσται, ὃ ἔφαμεν ὑποπτεῦσαι ὡς εὐθὺς ἀρχόμενοι τῆς πόλεως οἰκίζειν κατὰ","st":"443b"},{"sp":"N","t":"θεόν τινα εἰς ἀρχήν τε καὶ τύπον τινὰ τῆς δικαιοσύνης κινδυνεύομεν ἐμβεβηκέναι.","st":"443c"},{"sp":"N","t":"Παντάπασιν μὲν οὖν.","st":"443c"},{"sp":"N","t":"Τὸ δέ γε ἦν ἄρα, ὦ Γλαύκων — δι’ ὃ καὶ ὠφελεῖ — εἴδωλόν τι τῆς δικαιοσύνης, τὸ τὸν μὲν σκυτοτομικὸν φύσει ὀρθῶς ἔχειν σκυτοτομεῖν καὶ ἄλλο μηδὲν πράττειν, τὸν δὲ τεκτονικὸν τεκταίνεσθαι, καὶ τἆλλα δὴ οὕτως.","st":"443c"},{"sp":"N","t":"Φαίνεται.","st":"443c"},{"sp":"N","t":"Τὸ δέ γε ἀληθές, τοιοῦτόν τι ἦν, ὡς ἔοικεν, ἡ δικαιοσύνη ἀλλ’ οὐ περὶ τὴν ἔξω πρᾶξιν τῶν αὑτοῦ, ἀλλὰ περὶ τὴν","st":"443c"},{"sp":"N","t":"ἐντός, ὡς ἀληθῶς περὶ ἑαυτὸν καὶ τὰ ἑαυτοῦ, μὴ ἐάσαντα τἀλλότρια πράττειν ἕκαστον ἐν αὑτῷ μηδὲ πολυπραγμονεῖν πρὸς ἄλληλα τὰ ἐν τῇ ψυχῇ γένη, ἀλλὰ τῷ ὄντι τὰ οἰκεῖα εὖ θέμενον καὶ ἄρξαντα αὐτὸν αὑτοῦ καὶ κοσμήσαντα καὶ φίλον γενόμενον ἑαυτῷ καὶ συναρμόσαντα τρία ὄντα, ὥσπερ ὅρους τρεῖς ἁρμονίας ἀτεχνῶς, νεάτης τε καὶ ὑπάτης καὶ μέσης, καὶ εἰ ἄλλα ἄττα μεταξὺ τυγχάνει ὄντα, πάντα ταῦτα συνδήσαντα καὶ παντάπασιν ἕνα γενόμενον ἐκ πολλῶν, σώφρονα καὶ ἡρμοσμένον, οὕτω δὴ πράττειν ἤδη, ἐάν τι πράττῃ ἢ περὶ χρημάτων κτῆσιν ἢ περὶ σώματος θεραπείαν ἢ καὶ πολιτικόν τι ἢ περὶ τὰ ἴδια συμβόλαια, ἐν πᾶσι τούτοις ἡγούμενον καὶ ὀνομάζοντα δικαίαν μὲν καὶ καλὴν πρᾶξιν ἣ ἂν ταύτην τὴν ἕξιν σῴζῃ τε καὶ συναπεργάζηται, σοφίαν δὲ τὴν ἐπιστατοῦσαν ταύτῃ τῇ πράξει ἐπιστήμην, ἄδικον δὲ","st":"443d"},{"sp":"N","t":"πρᾶξιν ἣ ἂν ἀεὶ ταύτην λύῃ, ἀμαθίαν δὲ τὴν ταύτῃ αὖ ἐπιστατοῦσαν δόξαν.","st":"444a"},{"sp":"N","t":"Παντάπασιν, ἦ δ’ ὅς, ὦ Σώκρατες, ἀληθῆ λέγεις.","st":"444a"},{"sp":"N","t":"Εἶεν, ἦν δ’ ἐγώ· τὸν μὲν δίκαιον καὶ ἄνδρα καὶ πόλιν καὶ δικαιοσύνην, ὃ τυγχάνει ἐν αὐτοῖς ὄν, εἰ φαῖμεν ηὑρηκέναι, οὐκ ἂν πάνυ τι οἶμαι δόξαιμεν ψεύδεσθαι. Μὰ Δία οὐ μέντοι, ἔφη.","st":"444a"},{"sp":"N","t":"Φῶμεν ἄρα;","st":"444a"},{"sp":"N","t":"Φῶμεν.","st":"444a"},{"sp":"N","t":"Ἔστω δή, ἦν δ’ ἐγώ· μετὰ γὰρ τοῦτο σκεπτέον οἶμαι ἀδικίαν.","st":"444a"},{"sp":"N","t":"Δῆλον.","st":"444a"},{"sp":"N","t":"Οὐκοῦν στάσιν τινὰ αὖ τριῶν ὄντων τούτων δεῖ αὐτὴν εἶναι καὶ πολυπραγμοσύνην καὶ ἀλλοτριοπραγμοσύνην καὶ ἐπανάστασιν μέρους τινὸς τῷ ὅλῳ τῆς ψυχῆς, ἵν’ ἄρχῃ ἐν αὐτῇ οὐ προσῆκον, ἀλλὰ τοιούτου ὄντος φύσει οἵου πρέπειν αὐτῷ δουλεύειν, τῷ δ’ οὐ δουλεύειν ἀρχικοῦ γένους ὄντι; τοιαῦτ’ ἄττα οἶμαι φήσομεν καὶ τὴν τούτων ταραχὴν καὶ πλάνην εἶναι τήν τε ἀδικίαν καὶ ἀκολασίαν καὶ δειλίαν καὶ ἀμαθίαν καὶ συλλήβδην πᾶσαν κακίαν.","st":"444b"},{"sp":"N","t":"Αὐτὰ μὲν οὖν ταῦτα, ἔφη.","st":"444b"},{"sp":"N","t":"Οὐκοῦν, ἦν δ’ ἐγώ, καὶ τὸ ἄδικα πράττειν καὶ τὸ ἀδικεῖν καὶ αὖ τὸ δίκαια ποιεῖν, ταῦτα πάντα τυγχάνει ὄντα κατάδηλα ἤδη σαφῶς, εἴπερ καὶ ἡ ἀδικία τε καὶ δικαιοσύνη;","st":"444c"},{"sp":"N","t":"Πῶς δή;","st":"444c"},{"sp":"N","t":"Ὅτι, ἦν δ’ ἐγώ, τυγχάνει οὐδὲν διαφέροντα τῶν ὑγιεινῶν τε καὶ νοσωδῶν, ὡς ἐκεῖνα ἐν σώματι, ταῦτα ἐν ψυχῇ.","st":"444c"},{"sp":"N","t":"Πῇ; ἔφη.","st":"444c"},{"sp":"N","t":"Τὰ μέν που ὑγιεινὰ ὑγίειαν ἐμποιεῖ, τὰ δὲ νοσώδη νόσον.","st":"444c"},{"sp":"N","t":"Ναί.","st":"444c"},{"sp":"N","t":"Οὐκοῦν καὶ τὸ μὲν δίκαια πράττειν δικαιοσύνην ἐμποιεῖ,","st":"444c"},{"sp":"N","t":"τὸ δ’ ἄδικα ἀδικίαν;","st":"444d"},{"sp":"N","t":"Ἀνάγκη.","st":"444d"},{"sp":"N","t":"Ἔστι δὲ τὸ μὲν ὑγίειαν ποιεῖν τὰ ἐν τῷ σώματι κατὰ φύσιν καθιστάναι κρατεῖν τε καὶ κρατεῖσθαι ὑπ’ ἀλλήλων,","st":"444d"},{"sp":"N","t":"τὸ δὲ νόσον παρὰ φύσιν ἄρχειν τε καὶ ἄρχεσθαι ἄλλο ὑπ’ ἄλλου.","st":"444d"},{"sp":"N","t":"Ἔστι γάρ.","st":"444d"},{"sp":"N","t":"Οὐκοῦν αὖ, ἔφην, τὸ δικαιοσύνην ἐμποιεῖν τὰ ἐν τῇ ψυχῇ κατὰ φύσιν καθιστάναι κρατεῖν τε καὶ κρατεῖσθαι ὑπ’ ἀλλήλων, τὸ δὲ ἀδικίαν παρὰ φύσιν ἄρχειν τε καὶ ἄρχεσθαι ἄλλο ὑπ’ ἄλλου;","st":"444d"},{"sp":"N","t":"Κομιδῇ, ἔφη.","st":"444d"},{"sp":"N","t":"Ἀρετὴ μὲν ἄρα, ὡς ἔοικεν, ὑγίειά τέ τις ἂν εἴη καὶ","st":"444d"},{"sp":"N","t":"κάλλος καὶ εὐεξία ψυχῆς, κακία δὲ νόσος τε καὶ αἶσχος καὶ ἀσθένεια.","st":"444e"},{"sp":"N","t":"Ἔστιν οὕτω.","st":"444e"},{"sp":"N","t":"Ἆρ’ οὖν οὐ καὶ τὰ μὲν καλὰ ἐπιτηδεύματα εἰς ἀρετῆς κτῆσιν φέρει, τὰ δ’ αἰσχρὰ εἰς κακίας;","st":"444e"},{"sp":"N","t":"Ἀνάγκη.","st":"444e"},{"sp":"N","t":"Τὸ δὴ λοιπὸν ἤδη, ὡς ἔοικεν, ἡμῖν ἐστι σκέψασθαι","st":"444e"},{"sp":"N","t":"πότερον αὖ λυσιτελεῖ δίκαιά τε πράττειν καὶ καλὰ ἐπιτηδεύειν καὶ εἶναι δίκαιον, ἐάντε λανθάνῃ ἐάντε μὴ τοιοῦτος ὤν, ἢ ἀδικεῖν τε καὶ ἄδικον εἶναι, ἐάνπερ μὴ διδῷ δίκην μηδὲ βελτίων γίγνηται κολαζόμενος.","st":"445a"},{"sp":"N","t":"Ἀλλ’, ἔφη, ὦ Σώκρατες, γελοῖον ἔμοιγε φαίνεται τὸ σκέμμα γίγνεσθαι ἤδη, εἰ τοῦ μὲν σώματος τῆς φύσεως διαφθειρομένης δοκεῖ οὐ βιωτὸν εἶναι οὐδὲ μετὰ πάντων σιτίων τε καὶ ποτῶν καὶ παντὸς πλούτου καὶ πάσης ἀρχῆς, τῆς δὲ αὐτοῦ τούτου ᾧ ζῶμεν φύσεως ταραττομένης καὶ","st":"445a"},{"sp":"N","t":"διαφθειρομένης βιωτὸν ἄρα ἔσται, ἐάνπερ τις ποιῇ ὃ ἂν βουληθῇ ἄλλο πλὴν τοῦτο ὁπόθεν κακίας μὲν καὶ ἀδικίας ἀπαλλαγήσεται, δικαιοσύνην δὲ καὶ ἀρετὴν κτήσεται, ἐπειδήπερ ἐφάνη γε ὄντα ἑκάτερα οἷα ἡμεῖς διεληλύθαμεν.","st":"445b"},{"sp":"N","t":"Γελοῖον γάρ, ἦν δ’ ἐγώ· ἀλλ’ ὅμως ἐπείπερ ἐνταῦθα ἐληλύθαμεν, ὅσον οἷόν τε σαφέστατα κατιδεῖν ὅτι ταῦτα οὕτως ἔχει οὐ χρὴ ἀποκάμνειν.","st":"445b"},{"sp":"N","t":"Ἥκιστα, νὴ τὸν Δία, ἔφη, πάντων ἀποκμητέον.","st":"445b"},{"sp":"N","t":"Δεῦρό νυν, ἦν δ’ ἐγώ, ἵνα καὶ ἴδῃς ὅσα καὶ εἴδη ἔχει ἡ κακία, ὡς ἐμοὶ δοκεῖ, ἅ γε δὴ καὶ ἄξια θέας.","st":"445c"},{"sp":"N","t":"Ἕπομαι, ἔφη· μόνον λέγε.","st":"445c"},{"sp":"N","t":"Καὶ μήν, ἦν δ’ ἐγώ, ὥσπερ ἀπὸ σκοπιᾶς μοι φαίνεται, ἐπειδὴ ἐνταῦθα ἀναβεβήκαμεν τοῦ λόγου, ἓν μὲν εἶναι εἶδος τῆς ἀρετῆς, ἄπειρα δὲ τῆς κακίας, τέτταρα δ’ ἐν αὐτοῖς ἄττα ὧν καὶ ἄξιον ἐπιμνησθῆναι.","st":"445c"},{"sp":"N","t":"Πῶς λέγεις; ἔφη.","st":"445c"},{"sp":"N","t":"Ὅσοι, ἦν δ’ ἐγώ, πολιτειῶν τρόποι εἰσὶν εἴδη ἔχοντες, τοσοῦτοι κινδυνεύουσι καὶ ψυχῆς τρόποι εἶναι.","st":"445c"},{"sp":"N","t":"Πόσοι δή;","st":"445c"},{"sp":"N","t":"Πέντε μέν, ἦν δ’ ἐγώ, πολιτειῶν, πέντε δὲ ψυχῆς.","st":"445d"},{"sp":"N","t":"Λέγε, ἔφη, τίνες.","st":"445d"},{"sp":"N","t":"Λέγω, εἶπον, ὅτι εἷς μὲν οὗτος ὃν ἡμεῖς διεληλύθαμεν πολιτείας εἴη ἂν τρόπος, ἐπονομασθείη δ’ ἂν καὶ διχῇ· ἐγγενομένου μὲν γὰρ ἀνδρὸς ἑνὸς ἐν τοῖς ἄρχουσι διαφέροντος βασιλεία ἂν κληθείη, πλειόνων δὲ ἀριστοκρατία.","st":"445d"},{"sp":"N","t":"Ἀληθῆ, ἔφη.","st":"445d"},{"sp":"N","t":"Τοῦτο μὲν τοίνυν, ἦν δ’ ἐγώ, ἓν εἶδος λέγω· οὔτε γὰρ ἂν","st":"445d"},{"sp":"N","t":"πλείους οὔτε εἷς ἐγγενόμενοι κινήσειεν ἂν τῶν ἀξίων λόγου νόμων τῆς πόλεως, τροφῇ τε καὶ παιδείᾳ χρησάμενος ᾗ διήλθομεν.","st":"445e"},{"sp":"N","t":"οὐ γὰρ εἰκός, ἔφη.","st":"445e"},{"sp":"N","t":"ΣΩΚΡΆΤΗς, ΓΛΑΎΚΩΝ, ΑΔΕΊΜΑΝΤΟς","st":"445e"},{"sp":"N","t":"ἀγαθὴν μὲν τοίνυν τὴν τοιαύτην πόλιν τε καὶ πολιτείαν καὶ ὀρθὴν καλῶ, καὶ ἄνδρα τὸν τοιοῦτον: κακὰς δὲ τὰς ἄλλας καὶ ἡμαρτημένας, εἴπερ αὕτη ὀρθή, περί τε πόλεων διοικήσεις καὶ περὶ ἰδιωτῶν ψυχῆς τρόπου κατασκευήν, ἐν τέτταρσι πονηρίας εἴδεσιν οὔσας.","st":"449a"},{"sp":"N","t":"ποίας δὴ ταύτας; ἔφη.","st":"449a"},{"sp":"N","t":"καὶ ἐγὼ μὲν ᾖα τὰς ἐφεξῆς ἐρῶν, ὥς μοι ἐφαίνοντο","st":"449a"},{"sp":"N","t":"ἕκασται ἐξ ἀλλήλων μεταβαίνειν: ὁ δὲ Πολέμαρχος- σμικρὸν γὰρ ἀπωτέρω τοῦ Ἀδειμάντου καθῆστο — ἐκτείνας τὴν χεῖρα καὶ λαβόμενος τοῦ ἱματίου ἄνωθεν αὐτοῦ παρὰ τὸν ὦμον, ἐκεῖνόν τε προσηγάγετο καὶ προτείνας ἑαυτὸν ἔλεγεν ἄττα προσκεκυφώς, ὧν ἄλλο μὲν οὐδὲν κατηκούσαμεν, τόδε δέ: Ἀφήσομεν οὖν, ἔφη, ἢ τί δράσομεν;","st":"449b"},{"sp":"N","t":"ἥκιστά γε, ἔφη ὁ Ἀδείμαντος μέγα ἤδη λέγων.","st":"449b"},{"sp":"N","t":"καὶ ἐγώ, τί μάλιστα, ἔφην, ὑμεῖς οὐκ ἀφίετε;","st":"449b"},{"sp":"N","t":"σέ, ἦ δ᾽ ὅς.","st":"449b"},{"sp":"N","t":"ὅτι, ἐγὼ εἶπον, τί μάλιστα;","st":"449c"},{"sp":"N","t":"ἀπορρᾳθυμεῖν ἡμῖν δοκεῖς, ἔφη, καὶ εἶδος ὅλον οὐ τὸ ἐλάχιστον ἐκκλέπτειν τοῦ λόγου ἵνα μὴ διέλθῃς, καὶ λήσειν οἰηθῆναι εἰπὼν αὐτὸ φαύλως, ὡς ἄρα περὶ γυναικῶν τε καὶ παίδων παντὶ δῆλον ὅτι κοινὰ τὰ φίλων ἔσται.","st":"449c"},{"sp":"N","t":"οὐκοῦν ὀρθῶς, ἔφην, ὦ Ἀδείμαντε;","st":"449c"},{"sp":"N","t":"ναί, ἦ δ᾽ ὅς. ἀλλὰ τὸ ὀρθῶς τοῦτο, ὥσπερ τἆλλα, λόγου δεῖται τίς ὁ τρόπος τῆς κοινωνίας: πολλοὶ γὰρ ἂν γένοιντο.","st":"449c"},{"sp":"N","t":"μὴ οὖν παρῇς ὅντινα σὺ λέγεις: ὡς ἡμεῖς πάλαι περιμένομεν οἰόμενοί σέ που μνησθήσεσθαι παιδοποιίας τε πέρι, πῶς παιδοποιήσονται, καὶ γενομένους πῶς θρέψουσιν, καὶ ὅλην ταύτην ἣν λέγεις κοινωνίαν γυναικῶν τε καὶ παίδων: μέγα γάρ τι οἰόμεθα φέρειν καὶ ὅλον εἰς πολιτείαν ὀρθῶς ἢ μὴ ὀρθῶς γιγνόμενον. νῦν οὖν, ἐπειδὴ ἄλλης ἐπιλαμβάνῃ πολιτείας πρὶν ταῦτα ἱκανῶς διελέσθαι, δέδοκται ἡμῖν τοῦτο","st":"449d"},{"sp":"N","t":"ὃ σὺ ἤκουσας, τὸ σὲ μὴ μεθιέναι πρὶν ἂν ταῦτα πάντα ὥσπερ τἆλλα διέλθῃς.","st":"450a"},{"sp":"N","t":"καὶ ἐμὲ τοίνυν, ὁ Γλαύκων ἔφη, κοινωνὸν τῆς ψήφου ταύτης τίθετε.","st":"450a"},{"sp":"N","t":"Σωκράτης, Γλαύκων, Αδείμαντος, Θρασύμαχος","st":"450a"},{"sp":"N","t":"ἀμέλει, ἔφη ὁ Θρασύμαχος, πᾶσι ταῦτα δεδογμένα ἡμῖν νόμιζε, ὦ Σώκρατες.","st":"450a"},{"sp":"N","t":"οἷον, ἦν δ᾽ ἐγώ, εἰργάσασθε ἐπιλαβόμενοί μου. ὅσον λόγον πάλιν, ὥσπερ ἐξ ἀρχῆς, κινεῖτε περὶ τῆς πολιτείας: ἣν ὡς ἤδη διεληλυθὼς ἔγωγε ἔχαιρον, ἀγαπῶν εἴ τις ἐάσοι ταῦτα ἀποδεξάμενος ὡς τότε ἐρρήθη. ἃ νῦν ὑμεῖς παρακαλοῦντες","st":"450a"},{"sp":"N","t":"οὐκ ἴστε ὅσον ἑσμὸν λόγων ἐπεγείρετε: ὃν ὁρῶν ἐγὼ παρῆκα τότε, μὴ παράσχοι πολὺν ὄχλον.","st":"450b"},{"sp":"N","t":"τί δέ; ἦ δ᾽ ὃς ὁ Θρασύμαχος: χρυσοχοήσοντας οἴει τούσδε νῦν ἐνθάδε ἀφῖχθαι, ἀλλ᾽ οὐ λόγων ἀκουσομένους;","st":"450b"},{"sp":"N","t":"ναί, εἶπον, μετρίων γε.","st":"450b"},{"sp":"N","t":"μέτρον δέ γ᾽, ἔφη, ὦ Σώκρατες, ὁ Γλαύκων, τοιούτων λόγων ἀκούειν ὅλος ὁ βίος νοῦν ἔχουσιν. ἀλλὰ τὸ μὲν ἡμέτερον ἔα: σὺ δὲ περὶ ὧν ἐρωτῶμεν μηδαμῶς ἀποκάμῃς ᾗ","st":"450b"},{"sp":"N","t":"σοι δοκεῖ διεξιών, τίς ἡ κοινωνία τοῖς φύλαξιν ἡμῖν παίδων τε πέρι καὶ γυναικῶν ἔσται καὶ τροφῆς νέων ἔτι ὄντων, τῆς ἐν τῷ μεταξὺ χρόνῳ γιγνομένης γενέσεώς τε καὶ παιδείας, ἣ δὴ ἐπιπονωτάτη δοκεῖ εἶναι. πειρῶ οὖν εἰπεῖν τίνα τρόπον δεῖ γίγνεσθαι αὐτήν.","st":"450c"},{"sp":"N","t":"οὐ ῥᾴδιον, ὦ εὔδαιμον, ἦν δ᾽ ἐγώ, διελθεῖν: πολλὰς γὰρ ἀπιστίας ἔχει ἔτι μᾶλλον τῶν ἔμπροσθεν ὧν διήλθομεν. καὶ γὰρ ὡς δυνατὰ λέγεται, ἀπιστοῖτ᾽ ἄν, καὶ εἰ ὅτι μάλιστα γένοιτο, ὡς ἄριστ᾽ ἂν εἴη ταῦτα, καὶ ταύτῃ ἀπιστήσεται.","st":"450c"},{"sp":"N","t":"διὸ δὴ καὶ ὄκνος τις αὐτῶν ἅπτεσθαι, μὴ εὐχὴ δοκῇ εἶναι ὁ λόγος, ὦ φίλε ἑταῖρε. μηδέν, ἦ δ᾽ ὅς, ὄκνει: οὔτε γὰρ ἀγνώμονες οὔτε ἄπιστοι οὔτε δύσνοι οἱ ἀκουσόμενοι.","st":"450d"},{"sp":"N","t":"καὶ ἐγὼ εἶπον: ὦ ἄριστε, ἦ που βουλόμενός με παραθαρρύνειν λέγεις;","st":"450d"},{"sp":"N","t":"ἔγωγ᾽, ἔφη.","st":"450d"},{"sp":"N","t":"πᾶν τοίνυν, ἦν δ᾽ ἐγώ, τοὐναντίον ποιεῖς. πιστεύοντος μὲν γὰρ ἐμοῦ ἐμοὶ εἰδέναι ἃ λέγω, καλῶς εἶχεν ἡ παραμυθία: ἐν γὰρ φρονίμοις τε καὶ φίλοις περὶ τῶν μεγίστων τε καὶ","st":"450d"},{"sp":"N","t":"φίλων τἀληθῆ εἰδότα λέγειν ἀσφαλὲς καὶ θαρραλέον, ἀπιστοῦντα δὲ καὶ ζητοῦντα ἅμα τοὺς λόγους ποιεῖσθαι, ὃ δὴ","st":"450e"},{"sp":"N","t":"ἐγὼ δρῶ, φοβερόν τε καὶ σφαλερόν, οὔ τι γέλωτα ὀφλεῖν- παιδικὸν γὰρ τοῦτό γε — ἀλλὰ μὴ σφαλεὶς τῆς ἀληθείας οὐ μόνον αὐτὸς ἀλλὰ καὶ τοὺς φίλους συνεπισπασάμενος κείσομαι περὶ ἃ ἥκιστα δεῖ σφάλλεσθαι. προσκυνῶ δὲ Ἀδράστειαν, ὦ Γλαύκων, χάριν οὗ μέλλω λέγειν: ἐλπίζω γὰρ οὖν ἔλαττον ἁμάρτημα ἀκουσίως τινὸς φονέα γενέσθαι ἢ ἀπατεῶνα καλῶν τε καὶ ἀγαθῶν καὶ δικαίων νομίμων πέρι. τοῦτο οὖν τὸ κινδύνευμα κινδυνεύειν ἐν ἐχθροῖς κρεῖττον ἢ","st":"451a"},{"sp":"N","t":"φίλοις, ὥστε εὖ με παραμυθῇ.","st":"451b"},{"sp":"N","t":"καὶ ὁ Γλαύκων γελάσας, ἀλλ᾽, ὦ Σώκρατες, ἔφη, ἐάν τι πάθωμεν πλημμελὲς ὑπὸ τοῦ λόγου, ἀφίεμέν σε ὥσπερ φόνου καὶ καθαρὸν εἶναι καὶ μὴ ἀπατεῶνα ἡμῶν. ἀλλὰ θαρρήσας λέγε.","st":"451b"},{"sp":"N","t":"ἀλλὰ μέντοι, εἶπον, καθαρός γε καὶ ἐκεῖ ὁ ἀφεθείς, ὡς ὁ νόμος λέγει: εἰκὸς δέ γε, εἴπερ ἐκεῖ, κἀνθάδε.","st":"451b"},{"sp":"N","t":"λέγε τοίνυν, ἔφη, τούτου γ᾽ ἕνεκα.","st":"451b"},{"sp":"N","t":"λέγειν δή, ἔφην ἐγώ, χρὴ ἀνάπαλιν αὖ νῦν, ἃ τότε ἴσως","st":"451b"},{"sp":"N","t":"ἔδει ἐφεξῆς λέγειν: τάχα δὲ οὕτως ἂν ὀρθῶς ἔχοι, μετὰ ἀνδρεῖον δρᾶμα παντελῶς διαπερανθὲν τὸ γυναικεῖον αὖ περαίνειν, ἄλλως τε καὶ ἐπειδὴ σὺ οὕτω προκαλῇ.","st":"451c"},{"sp":"N","t":"ἀνθρώποις γὰρ φῦσι καὶ παιδευθεῖσιν ὡς ἡμεῖς διήλθομεν, κατ᾽ ἐμὴν δόξαν οὐκ ἔστ᾽ ἄλλη ὀρθὴ παίδων τε καὶ γυναικῶν κτῆσίς τε καὶ χρεία ἢ κατ᾽ ἐκείνην τὴν ὁρμὴν ἰοῦσιν, ἥνπερ τὸ πρῶτον ὡρμήσαμεν: ἐπεχειρήσαμεν δέ που ὡς ἀγέλης φύλακας τοὺς ἄνδρας καθιστάναι τῷ λόγῳ.","st":"451c"},{"sp":"N","t":"ναί.","st":"451c"},{"sp":"N","t":"ἀκολουθῶμεν τοίνυν καὶ τὴν γένεσιν καὶ τροφὴν παραπλησίαν ἀποδιδόντες, καὶ σκοπῶμεν εἰ ἡμῖν πρέπει ἢ οὔ.","st":"451d"},{"sp":"N","t":"πῶς; ἔφη.","st":"451d"},{"sp":"N","t":"ὧδε. τὰς θηλείας τῶν φυλάκων κυνῶν πότερα συμφυλάττειν οἰόμεθα δεῖν ἅπερ ἂν οἱ ἄρρενες φυλάττωσι καὶ συνθηρεύειν καὶ τἆλλα κοινῇ πράττειν, ἢ τὰς μὲν οἰκουρεῖν ἔνδον ὡς ἀδυνάτους διὰ τὸν τῶν σκυλάκων τόκον τε καὶ τροφήν, τοὺς δὲ πονεῖν τε καὶ πᾶσαν ἐπιμέλειαν ἔχειν περὶ τὰ ποίμνια;","st":"451d"},{"sp":"N","t":"κοινῇ, ἔφη, πάντα: πλὴν ὡς ἀσθενεστέραις χρώμεθα, τοῖς δὲ ὡς ἰσχυροτέροις.","st":"451e"},{"sp":"N","t":"οἷόν τ᾽ οὖν, ἔφην ἐγώ, ἐπὶ τὰ αὐτὰ χρῆσθαί τινι ζῴῳ, ἂν μὴ τὴν αὐτὴν τροφήν τε καὶ παιδείαν ἀποδιδῷς;","st":"451e"},{"sp":"N","t":"οὐχ οἷόν τε.","st":"451e"},{"sp":"N","t":"εἰ ἄρα ταῖς γυναιξὶν ἐπὶ ταὐτὰ χρησόμεθα καὶ τοῖς ἀνδράσι, ταὐτὰ καὶ διδακτέον αὐτάς.","st":"451e"},{"sp":"N","t":"ναί.","st":"452a"},{"sp":"N","t":"μουσικὴ μὴν ἐκείνοις γε καὶ γυμναστικὴ ἐδόθη.","st":"452a"},{"sp":"N","t":"ναί.","st":"452a"},{"sp":"N","t":"καὶ ταῖς γυναιξὶν ἄρα τούτω τὼ τέχνα καὶ τὰ περὶ τὸν πόλεμον ἀποδοτέον καὶ χρηστέον κατὰ ταὐτά.","st":"452a"},{"sp":"N","t":"εἰκὸς ἐξ ὧν λέγεις, ἔφη.","st":"452a"},{"sp":"N","t":"ἴσως δή, εἶπον, παρὰ τὸ ἔθος γελοῖα ἂν φαίνοιτο πολλὰ περὶ τὰ νῦν λεγόμενα, εἰ πράξεται ᾗ λέγεται.","st":"452a"},{"sp":"N","t":"καὶ μάλα, ἔφη.","st":"452a"},{"sp":"N","t":"τί, ἦν δ᾽ ἐγώ, γελοιότατον αὐτῶν ὁρᾷς; ἢ δῆλα δὴ ὅτι γυμνὰς τὰς γυναῖκας ἐν ταῖς παλαίστραις γυμναζομένας μετὰ","st":"452a"},{"sp":"N","t":"τῶν ἀνδρῶν, οὐ μόνον τὰς νέας, ἀλλὰ καὶ ἤδη τὰς πρεσβυτέρας, ὥσπερ τοὺς γέροντας ἐν τοῖς γυμνασίοις, ὅταν ῥυσοὶ καὶ μὴ ἡδεῖς τὴν ὄψιν ὅμως φιλογυμναστῶσιν;","st":"452b"},{"sp":"N","t":"νὴ τὸν Δία, ἔφη: γελοῖον γὰρ ἄν, ὥς γε ἐν τῷ παρεστῶτι, φανείη.","st":"452b"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, ἐπείπερ ὡρμήσαμεν λέγειν, οὐ φοβητέον τὰ τῶν χαριέντων σκώμματα, ὅσα καὶ οἷα ἂν εἴποιεν εἰς τὴν τοιαύτην μεταβολὴν γενομένην καὶ περὶ τὰ γυμνάσια","st":"452b"},{"sp":"N","t":"καὶ περὶ μουσικὴν καὶ οὐκ ἐλάχιστα περὶ τὴν τῶν ὅπλων σχέσιν καὶ ἵππων ὀχήσεις.","st":"452c"},{"sp":"N","t":"ὀρθῶς, ἔφη, λέγεις.","st":"452c"},{"sp":"N","t":"ἀλλ᾽ ἐπείπερ λέγειν ἠρξάμεθα, πορευτέον πρὸς τὸ τραχὺ τοῦ νόμου, δεηθεῖσίν τε τούτων μὴ τὰ αὑτῶν πράττειν ἀλλὰ σπουδάζειν, καὶ ὑπομνήσασιν ὅτι οὐ πολὺς χρόνος ἐξ οὗ τοῖς Ἕλλησιν ἐδόκει αἰσχρὰ εἶναι καὶ γελοῖα ἅπερ νῦν τοῖς πολλοῖς τῶν βαρβάρων, γυμνοὺς ἄνδρας ὁρᾶσθαι, καὶ ὅτε ἤρχοντο τῶν γυμνασίων πρῶτοι μὲν Κρῆτες, ἔπειτα Λακεδαιμόνιοι,","st":"452c"},{"sp":"N","t":"ἐξῆν τοῖς τότε ἀστείοις πάντα ταῦτα κωμῳδεῖν. ἢ οὐκ οἴει;","st":"452d"},{"sp":"N","t":"ἔγωγε.","st":"452d"},{"sp":"N","t":"ἀλλ᾽ ἐπειδὴ οἶμαι χρωμένοις ἄμεινον τὸ ἀποδύεσθαι τοῦ συγκαλύπτειν πάντα τὰ τοιαῦτα ἐφάνη, καὶ τὸ ἐν τοῖς ὀφθαλμοῖς δὴ γελοῖον ἐξερρύη ὑπὸ τοῦ ἐν τοῖς λόγοις μηνυθέντος ἀρίστου: καὶ τοῦτο ἐνεδείξατο, ὅτι μάταιος ὃς γελοῖον ἄλλο τι ἡγεῖται ἢ τὸ κακόν, καὶ ὁ γελωτοποιεῖν ἐπιχειρῶν πρὸς ἄλλην τινὰ ὄψιν ἀποβλέπων ὡς γελοίου ἢ τὴν τοῦ ἄφρονός","st":"452d"},{"sp":"N","t":"τε καὶ κακοῦ, καὶ καλοῦ αὖ σπουδάζει πρὸς ἄλλον τινὰ σκοπὸν στησάμενος ἢ τὸν τοῦ ἀγαθοῦ.","st":"452e"},{"sp":"N","t":"παντάπασι μὲν οὖν, ἔφη.","st":"452e"},{"sp":"N","t":"ἆρ᾽ οὖν οὐ πρῶτον μὲν τοῦτο περὶ αὐτῶν ἀνομολογητέον, εἰ δυνατὰ ἢ οὔ, καὶ δοτέον ἀμφισβήτησιν εἴτε τις φιλοπαίσμων εἴτε σπουδαστικὸς ἐθέλει ἀμφισβητῆσαι, πότερον","st":"452e"},{"sp":"N","t":"δυνατὴ φύσις ἡ ἀνθρωπίνη ἡ θήλεια τῇ τοῦ ἄρρενος γένους κοινωνῆσαι εἰς ἅπαντα τὰ ἔργα ἢ οὐδ᾽ εἰς ἕν, ἢ εἰς τὰ μὲν οἵα τε, εἰς δὲ τὰ οὔ, καὶ τοῦτο δὴ τὸ περὶ τὸν πόλεμον ποτέρων ἐστίν; ἆρ᾽ οὐχ οὕτως ἂν κάλλιστά τις ἀρχόμενος ὡς τὸ εἰκὸς καὶ κάλλιστα τελευτήσειεν;","st":"453a"},{"sp":"N","t":"πολύ γε, ἔφη.","st":"453a"},{"sp":"N","t":"βούλει οὖν, ἦν δ᾽ ἐγώ, ἡμεῖς πρὸς ἡμᾶς αὐτοὺς ὑπὲρ τῶν ἄλλων ἀμφισβητήσωμεν, ἵνα μὴ ἔρημα τὰ τοῦ ἑτέρου λόγου πολιορκῆται;","st":"453a"},{"sp":"N","t":"οὐδέν, ἔφη, κωλύει.","st":"453b"},{"sp":"N","t":"λέγωμεν δὴ ὑπὲρ αὐτῶν ὅτι “ὦ Σώκρατές τε καὶ Γλαύκων, οὐδὲν δεῖ ὑμῖν ἄλλους ἀμφισβητεῖν: αὐτοὶ γὰρ ἐν ἀρχῇ τῆς κατοικίσεως, ἣν ᾠκίζετε πόλιν, ὡμολογεῖτε δεῖν κατὰ φύσιν ἕκαστον ἕνα ἓν τὸ αὑτοῦ πράττειν.”","st":"453b"},{"sp":"N","t":"ὡμολογήσαμεν οἶμαι: πῶς γὰρ οὔ;","st":"453b"},{"sp":"N","t":"“ἔστιν οὖν ὅπως οὐ πάμπολυ διαφέρει γυνὴ ἀνδρὸς τὴν φύσιν;”","st":"453b"},{"sp":"N","t":"πῶς δ᾽ οὐ διαφέρει;","st":"453b"},{"sp":"N","t":"“οὐκοῦν ἄλλο καὶ ἔργον ἑκατέρῳ προσήκει προστάττειν","st":"453b"},{"sp":"N","t":"τὸ κατὰ τὴν αὑτοῦ φύσιν;”","st":"453c"},{"sp":"N","t":"τί μήν;","st":"453c"},{"sp":"N","t":"“πῶς οὖν οὐχ ἁμαρτάνετε νυνὶ καὶ τἀναντία ὑμῖν αὐτοῖς λέγετε φάσκοντες αὖ τοὺς ἄνδρας καὶ τὰς γυναῖκας δεῖν τὰ αὐτὰ πράττειν, πλεῖστον κεχωρισμένην φύσιν ἔχοντας;” ἕξεις τι, ὦ θαυμάσιε, πρὸς ταῦτ᾽ ἀπολογεῖσθαι;","st":"453c"},{"sp":"N","t":"ὡς μὲν ἐξαίφνης, ἔφη, οὐ πάνυ ῥᾴδιον: ἀλλὰ σοῦ δεήσομαί τε καὶ δέομαι καὶ τὸν ὑπὲρ ἡμῶν λόγον, ὅστις ποτ᾽ ἐστίν, ἑρμηνεῦσαι.","st":"453c"},{"sp":"N","t":"ταῦτ᾽ ἐστίν, ἦν δ᾽ ἐγώ, ὦ Γλαύκων, καὶ ἄλλα πολλὰ","st":"453c"},{"sp":"N","t":"τοιαῦτα, ἃ ἐγὼ πάλαι προορῶν ἐφοβούμην τε καὶ ὤκνουν ἅπτεσθαι τοῦ νόμου τοῦ περὶ τὴν τῶν γυναικῶν καὶ παίδων κτῆσιν καὶ τροφήν.","st":"453d"},{"sp":"N","t":"οὐ μὰ τὸν Δία, ἔφη: οὐ γὰρ εὐκόλῳ ἔοικεν.","st":"453d"},{"sp":"N","t":"οὐ γάρ, εἶπον. ἀλλὰ δὴ ὧδ᾽ ἔχει: ἄντε τις εἰς κολυμβήθραν μικρὰν ἐμπέσῃ ἄντε εἰς τὸ μέγιστον πέλαγος μέσον, ὅμως γε νεῖ οὐδὲν ἧττον.","st":"453d"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"453d"},{"sp":"N","t":"οὐκοῦν καὶ ἡμῖν νευστέον καὶ πειρατέον σῴζεσθαι ἐκ τοῦ λόγου, ἤτοι δελφῖνά τινα ἐλπίζοντας ἡμᾶς ὑπολαβεῖν ἂν ἤ τινα ἄλλην ἄπορον σωτηρίαν.","st":"453d"},{"sp":"N","t":"ἔοικεν, ἔφη.","st":"453e"},{"sp":"N","t":"φέρε δή, ἦν δ᾽ ἐγώ, ἐάν πῃ εὕρωμεν τὴν ἔξοδον. ὁμολογοῦμεν γὰρ δὴ ἄλλην φύσιν ἄλλο δεῖν ἐπιτηδεύειν, γυναικὸς δὲ καὶ ἀνδρὸς ἄλλην εἶναι: τὰς δὲ ἄλλας φύσεις τὰ αὐτά φαμεν νῦν δεῖν ἐπιτηδεῦσαι. ταῦτα ἡμῶν κατηγορεῖται;","st":"453e"},{"sp":"N","t":"κομιδῇ γε.","st":"453e"},{"sp":"N","t":"ἦ γενναία, ἦν δ᾽ ἐγώ, ὦ Γλαύκων, ἡ δύναμις τῆς ἀντιλογικῆς τέχνης.","st":"454a"},{"sp":"N","t":"τί δή;","st":"454a"},{"sp":"N","t":"ὅτι, εἶπον, δοκοῦσί μοι εἰς αὐτὴν καὶ ἄκοντες πολλοὶ ἐμπίπτειν καὶ οἴεσθαι οὐκ ἐρίζειν ἀλλὰ διαλέγεσθαι, διὰ τὸ μὴ δύνασθαι κατ᾽ εἴδη διαιρούμενοι τὸ λεγόμενον ἐπισκοπεῖν, ἀλλὰ κατ᾽ αὐτὸ τὸ ὄνομα διώκειν τοῦ λεχθέντος τὴν ἐναντίωσιν, ἔριδι, οὐ διαλέκτῳ πρὸς ἀλλήλους χρώμενοι.","st":"454a"},{"sp":"N","t":"ἔστι γὰρ δή, ἔφη, περὶ πολλοὺς τοῦτο τὸ πάθος: ἀλλὰ μῶν καὶ πρὸς ἡμᾶς τοῦτο τείνει ἐν τῷ παρόντι;","st":"454a"},{"sp":"N","t":"παντάπασι μὲν οὖν, ἦν δ᾽ ἐγώ: κινδυνεύομεν γοῦν ἄκοντες ἀντιλογίας ἅπτεσθαι.","st":"454b"},{"sp":"N","t":"πῶς;","st":"454b"},{"sp":"N","t":"τὸ ⟨μὴ⟩ τὴν αὐτὴν φύσιν ὅτι οὐ τῶν αὐτῶν δεῖ ἐπιτηδευμάτων τυγχάνειν πάνυ ἀνδρείως τε καὶ ἐριστικῶς κατὰ τὸ ὄνομα διώκομεν, ἐπεσκεψάμεθα δὲ οὐδ᾽ ὁπῃοῦν τί εἶδος τὸ τῆς ἑτέρας τε καὶ τῆς αὐτῆς φύσεως καὶ πρὸς τί τεῖνον ὡριζόμεθα τότε, ὅτε τὰ ἐπιτηδεύματα ἄλλῃ φύσει ἄλλα, τῇ δὲ αὐτῇ τὰ αὐτὰ ἀπεδίδομεν.","st":"454b"},{"sp":"N","t":"οὐ γὰρ οὖν, ἔφη, ἐπεσκεψάμεθα.","st":"454b"},{"sp":"N","t":"τοιγάρτοι, εἶπον, ἔξεστιν ἡμῖν, ὡς ἔοικεν, ἀνερωτᾶν ἡμᾶς αὐτοὺς εἰ ἡ αὐτὴ φύσις φαλακρῶν καὶ κομητῶν καὶ οὐχ ἡ ἐναντία, καὶ ἐπειδὰν ὁμολογῶμεν ἐναντίαν εἶναι, ἐὰν φαλακροὶ σκυτοτομῶσιν, μὴ ἐᾶν κομήτας, ἐὰν δ᾽ αὖ κομῆται, μὴ τοὺς ἑτέρους.","st":"454c"},{"sp":"N","t":"γελοῖον μεντἂν εἴη, ἔφη.","st":"454c"},{"sp":"N","t":"ἆρα κατ᾽ ἄλλο τι, εἶπον ἐγώ, γελοῖον, ἢ ὅτι τότε οὐ πάντως τὴν αὐτὴν καὶ τὴν ἑτέραν φύσιν ἐτιθέμεθα, ἀλλ᾽ ἐκεῖνο τὸ εἶδος τῆς ἀλλοιώσεώς τε καὶ ὁμοιώσεως μόνον","st":"454c"},{"sp":"N","t":"ἐφυλάττομεν τὸ πρὸς αὐτὰ τεῖνον τὰ ἐπιτηδεύματα; οἷον ἰατρικὸν μὲν καὶ ἰατρικὴν τὴν ψυχὴν [ὄντα] τὴν αὐτὴν φύσιν ἔχειν ἐλέγομεν: ἢ οὐκ οἴει;","st":"454d"},{"sp":"N","t":"ἔγωγε.","st":"454d"},{"sp":"N","t":"ἰατρικὸν δέ γε καὶ τεκτονικὸν ἄλλην;","st":"454d"},{"sp":"N","t":"πάντως που.","st":"454d"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, καὶ τὸ τῶν ἀνδρῶν καὶ τὸ τῶν γυναικῶν γένος, ἐὰν μὲν πρὸς τέχνην τινὰ ἢ ἄλλο ἐπιτήδευμα διαφέρον φαίνηται, τοῦτο δὴ φήσομεν ἑκατέρῳ δεῖν ἀποδιδόναι: ἐὰν δ᾽ αὐτῷ τούτῳ φαίνηται διαφέρειν, τῷ τὸ μὲν θῆλυ τίκτειν,","st":"454d"},{"sp":"N","t":"τὸ δὲ ἄρρεν ὀχεύειν, οὐδέν τί πω φήσομεν μᾶλλον ἀποδεδεῖχθαι ὡς πρὸς ὃ ἡμεῖς λέγομεν διαφέρει γυνὴ ἀνδρός, ἀλλ᾽ ἔτι οἰησόμεθα δεῖν τὰ αὐτὰ ἐπιτηδεύειν τούς τε φύλακας ἡμῖν καὶ τὰς γυναῖκας αὐτῶν.","st":"454e"},{"sp":"N","t":"καὶ ὀρθῶς γ᾽, ἔφη.","st":"454e"},{"sp":"N","t":"οὐκοῦν μετὰ τοῦτο κελεύομεν τὸν τὰ ἐναντία λέγοντα","st":"454e"},{"sp":"N","t":"τοῦτο αὐτὸ διδάσκειν ἡμᾶς, πρὸς τίνα τέχνην ἢ τί ἐπιτήδευμα τῶν περὶ πόλεως κατασκευὴν οὐχ ἡ αὐτὴ ἀλλὰ ἑτέρα φύσις γυναικός τε καὶ ἀνδρός;","st":"455a"},{"sp":"N","t":"δίκαιον γοῦν.","st":"455a"},{"sp":"N","t":"τάχα τοίνυν ἄν, ὅπερ σὺ ὀλίγον πρότερον ἔλεγες, εἴποι ἂν καὶ ἄλλος, ὅτι ἐν μὲν τῷ παραχρῆμα ἱκανῶς εἰπεῖν οὐ ῥᾴδιον, ἐπισκεψαμένῳ δὲ οὐδὲν χαλεπόν.","st":"455a"},{"sp":"N","t":"εἴποι γὰρ ἄν.","st":"455a"},{"sp":"N","t":"βούλει οὖν δεώμεθα τοῦ τὰ τοιαῦτα ἀντιλέγοντος ἀκολουθῆσαι","st":"455a"},{"sp":"N","t":"ἡμῖν, ἐάν πως ἡμεῖς ἐκείνῳ ἐνδειξώμεθα ὅτι οὐδέν ἐστιν ἐπιτήδευμα ἴδιον γυναικὶ πρὸς διοίκησιν πόλεως;","st":"455b"},{"sp":"N","t":"πάνυ γε.","st":"455b"},{"sp":"N","t":"ἴθι δή, φήσομεν πρὸς αὐτόν, ἀποκρίνου: ἆρα οὕτως ἔλεγες τὸν μὲν εὐφυῆ πρός τι εἶναι, τὸν δὲ ἀφυῆ, ἐν ᾧ ὁ μὲν ῥᾳδίως τι μανθάνοι, ὁ δὲ χαλεπῶς; καὶ ὁ μὲν ἀπὸ βραχείας μαθήσεως ἐπὶ πολὺ εὑρετικὸς εἴη οὗ ἔμαθεν, ὁ δὲ πολλῆς μαθήσεως τυχὼν καὶ μελέτης μηδ᾽ ἃ ἔμαθε σῴζοιτο; καὶ τῷ μὲν τὰ τοῦ σώματος ἱκανῶς ὑπηρετοῖ τῇ διανοίᾳ, τῷ","st":"455b"},{"sp":"N","t":"δὲ ἐναντιοῖτο; ἆρ᾽ ἄλλα ἄττα ἐστὶν ἢ ταῦτα, οἷς τὸν εὐφυῆ πρὸς ἕκαστα καὶ τὸν μὴ ὡρίζου;","st":"455c"},{"sp":"N","t":"οὐδείς, ἦ δ᾽ ὅς, ἄλλα φήσει.","st":"455c"},{"sp":"N","t":"οἶσθά τι οὖν ὑπὸ ἀνθρώπων μελετώμενον, ἐν ᾧ οὐ πάντα ταῦτα τὸ τῶν ἀνδρῶν γένος διαφερόντως ἔχει ἢ τὸ τῶν γυναικῶν; ἢ μακρολογῶμεν τήν τε ὑφαντικὴν λέγοντες καὶ τὴν τῶν ποπάνων τε καὶ ἑψημάτων θεραπείαν, ἐν οἷς δή τι δοκεῖ τὸ γυναικεῖον γένος εἶναι, οὗ καὶ καταγελαστότατόν","st":"455c"},{"sp":"N","t":"ἐστι πάντων ἡττώμενον;","st":"455d"},{"sp":"N","t":"ἀληθῆ, ἔφη, λέγεις, ὅτι πολὺ κρατεῖται ἐν ἅπασιν ὡς ἔπος εἰπεῖν τὸ γένος τοῦ γένους. γυναῖκες μέντοι πολλαὶ πολλῶν ἀνδρῶν βελτίους εἰς πολλά: τὸ δὲ ὅλον ἔχει ὡς σὺ λέγεις.","st":"455d"},{"sp":"N","t":"οὐδὲν ἄρα ἐστίν, ὦ φίλε, ἐπιτήδευμα τῶν πόλιν διοικούντων γυναικὸς διότι γυνή, οὐδ᾽ ἀνδρὸς διότι ἀνήρ, ἀλλ᾽ ὁμοίως διεσπαρμέναι αἱ φύσεις ἐν ἀμφοῖν τοῖν ζῴοιν, καὶ πάντων μὲν μετέχει γυνὴ ἐπιτηδευμάτων κατὰ","st":"455d"},{"sp":"N","t":"φύσιν, πάντων δὲ ἀνήρ, ἐπὶ πᾶσι δὲ ἀσθενέστερον γυνὴ ἀνδρός.","st":"455e"},{"sp":"N","t":"πάνυ γε.","st":"455e"},{"sp":"N","t":"ἦ οὖν ἀνδράσι πάντα προστάξομεν, γυναικὶ δ᾽ οὐδέν;","st":"455e"},{"sp":"N","t":"καὶ πῶς;","st":"455e"},{"sp":"N","t":"ἀλλ᾽ ἔστι γὰρ οἶμαι, ὡς φήσομεν, καὶ γυνὴ ἰατρική, ἡ δ᾽ οὔ, καὶ μουσική, ἡ δ᾽ ἄμουσος φύσει.","st":"455e"},{"sp":"N","t":"τί μήν;","st":"455e"},{"sp":"N","t":"[καὶ] γυμναστικὴ δ᾽ ἄρα οὔ, οὐδὲ πολεμική, ἡ δὲ ἀπόλεμος καὶ οὐ φιλογυμναστική;","st":"456a"},{"sp":"N","t":"οἶμαι ἔγωγε.","st":"456a"},{"sp":"N","t":"τί δέ; φιλόσοφός τε καὶ μισόσοφος; καὶ θυμοειδής, ἡ δ᾽ ἄθυμός ἐστι;","st":"456a"},{"sp":"N","t":"καὶ ταῦτα.","st":"456a"},{"sp":"N","t":"ἔστιν ἄρα καὶ φυλακικὴ γυνή, ἡ δ᾽ οὔ. ἢ οὐ τοιαύτην καὶ τῶν ἀνδρῶν τῶν φυλακικῶν φύσιν ἐξελεξάμεθα;","st":"456a"},{"sp":"N","t":"τοιαύτην μὲν οὖν.","st":"456a"},{"sp":"N","t":"καὶ γυναικὸς ἄρα καὶ ἀνδρὸς ἡ αὐτὴ φύσις εἰς φυλακὴν πόλεως, πλὴν ὅσα ἀσθενεστέρα, ἡ δὲ ἰσχυροτέρα ἐστίν.","st":"456a"},{"sp":"N","t":"φαίνεται.","st":"456a"},{"sp":"N","t":"καὶ γυναῖκες ἄρα αἱ τοιαῦται τοῖς τοιούτοις ἀνδράσιν ἐκλεκτέαι συνοικεῖν τε καὶ συμφυλάττειν, ἐπείπερ εἰσὶν ἱκαναὶ καὶ συγγενεῖς αὐτοῖς τὴν φύσιν.","st":"456b"},{"sp":"N","t":"πάνυ γε.","st":"456b"},{"sp":"N","t":"τὰ δ᾽ ἐπιτηδεύματα οὐ τὰ αὐτὰ ἀποδοτέα ταῖς αὐταῖς φύσεσιν;","st":"456b"},{"sp":"N","t":"τὰ αὐτά.","st":"456b"},{"sp":"N","t":"ἥκομεν ἄρα εἰς τὰ πρότερα περιφερόμενοι, καὶ ὁμολογοῦμεν μὴ παρὰ φύσιν εἶναι ταῖς τῶν φυλάκων γυναιξὶ μουσικήν τε καὶ γυμναστικὴν ἀποδιδόναι.","st":"456b"},{"sp":"N","t":"παντάπασιν μὲν οὖν.","st":"456b"},{"sp":"N","t":"οὐκ ἄρα ἀδύνατά γε οὐδὲ εὐχαῖς ὅμοια ἐνομοθετοῦμεν,","st":"456b"},{"sp":"N","t":"ἐπείπερ κατὰ φύσιν ἐτίθεμεν τὸν νόμον: ἀλλὰ τὰ νῦν παρὰ ταῦτα γιγνόμενα παρὰ φύσιν μᾶλλον, ὡς ἔοικε, γίγνεται.","st":"456c"},{"sp":"N","t":"ἔοικεν.","st":"456c"},{"sp":"N","t":"οὐκοῦν ἡ ἐπίσκεψις ἡμῖν ἦν εἰ δυνατά γε καὶ βέλτιστα λέγοιμεν;","st":"456c"},{"sp":"N","t":"ἦν γάρ.","st":"456c"},{"sp":"N","t":"καὶ ὅτι μὲν δὴ δυνατά, διωμολόγηται;","st":"456c"},{"sp":"N","t":"ναί.","st":"456c"},{"sp":"N","t":"ὅτι δὲ δὴ βέλτιστα, τὸ μετὰ τοῦτο δεῖ διομολογηθῆναι;","st":"456c"},{"sp":"N","t":"δῆλον.","st":"456c"},{"sp":"N","t":"οὐκοῦν πρός γε τὸ φυλακικὴν γυναῖκα γενέσθαι, οὐκ ἄλλη μὲν ἡμῖν ἄνδρας ποιήσει παιδεία, ἄλλη δὲ γυναῖκας, ἄλλως","st":"456c"},{"sp":"N","t":"τε καὶ τὴν αὐτὴν φύσιν παραλαβοῦσα;","st":"456d"},{"sp":"N","t":"οὐκ ἄλλη.","st":"456d"},{"sp":"N","t":"πῶς οὖν ἔχεις δόξης τοῦ τοιοῦδε πέρι;","st":"456d"},{"sp":"N","t":"τίνος δή;","st":"456d"},{"sp":"N","t":"τοῦ ὑπολαμβάνειν παρὰ σεαυτῷ τὸν μὲν ἀμείνω ἄνδρα, τὸν δὲ χείρω: ἢ πάντας ὁμοίους ἡγῇ;","st":"456d"},{"sp":"N","t":"οὐδαμῶς.","st":"456d"},{"sp":"N","t":"ἐν οὖν τῇ πόλει ἣν ᾠκίζομεν, πότερον οἴει ἡμῖν ἀμείνους ἄνδρας ἐξειργάσθαι τοὺς φύλακας, τυχόντας ἧς διήλθομεν παιδείας, ἢ τοὺς σκυτοτόμους, τῇ σκυτικῇ παιδευθέντας;","st":"456d"},{"sp":"N","t":"γελοῖον, ἔφη, ἐρωτᾷς.","st":"456d"},{"sp":"N","t":"μανθάνω, ἔφην. τί δέ; τῶν ἄλλων πολιτῶν οὐχ οὗτοι","st":"456d"},{"sp":"N","t":"ἄριστοι;","st":"456e"},{"sp":"N","t":"πολύ γε.","st":"456e"},{"sp":"N","t":"τί δέ; αἱ γυναῖκες τῶν γυναικῶν οὐχ αὗται ἔσονται βέλτισται;","st":"456e"},{"sp":"N","t":"καὶ τοῦτο, ἔφη, πολύ.","st":"456e"},{"sp":"N","t":"ἔστι δέ τι πόλει ἄμεινον ἢ γυναῖκάς τε καὶ ἄνδρας ὡς ἀρίστους ἐγγίγνεσθαι;","st":"456e"},{"sp":"N","t":"οὐκ ἔστιν.","st":"456e"},{"sp":"N","t":"τοῦτο δὲ μουσική τε καὶ γυμναστικὴ παραγιγνόμεναι, ὡς","st":"456e"},{"sp":"N","t":"ἡμεῖς διήλθομεν, ἀπεργάσονται;","st":"457a"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"457a"},{"sp":"N","t":"οὐ μόνον ἄρα δυνατὸν ἀλλὰ καὶ ἄριστον πόλει νόμιμον ἐτίθεμεν.","st":"457a"},{"sp":"N","t":"οὕτως.","st":"457a"},{"sp":"N","t":"ἀποδυτέον δὴ ταῖς τῶν φυλάκων γυναιξίν, ἐπείπερ ἀρετὴν ἀντὶ ἱματίων ἀμφιέσονται, καὶ κοινωνητέον πολέμου τε καὶ τῆς ἄλλης φυλακῆς τῆς περὶ τὴν πόλιν, καὶ οὐκ ἄλλα πρακτέον: τούτων δ᾽ αὐτῶν τὰ ἐλαφρότερα ταῖς γυναιξὶν ἢ τοῖς ἀνδράσι δοτέον διὰ τὴν τοῦ γένους ἀσθένειαν. ὁ","st":"457a"},{"sp":"N","t":"δὲ γελῶν ἀνὴρ ἐπὶ γυμναῖς γυναιξί, τοῦ βελτίστου ἕνεκα γυμναζομέναις, “ἀτελῆ” τοῦ γελοίου “σοφίας δρέπων καρπόν”, οὐδὲν οἶδεν, ὡς ἔοικεν, ἐφ᾽ ᾧ γελᾷ οὐδ᾽ ὅτι πράττει: κάλλιστα γὰρ δὴ τοῦτο καὶ λέγεται καὶ λελέξεται, ὅτι τὸ μὲν ὠφέλιμον καλόν, τὸ δὲ βλαβερὸν αἰσχρόν.","st":"457b"},{"sp":"N","t":"παντάπασι μὲν οὖν.","st":"457b"},{"sp":"N","t":"τοῦτο μὲν τοίνυν ἓν ὥσπερ κῦμα φῶμεν διαφεύγειν τοῦ γυναικείου πέρι νόμου λέγοντες, ὥστε μὴ παντάπασι κατακλυσθῆναι τιθέντας ὡς δεῖ κοινῇ πάντα ἐπιτηδεύειν τούς τε","st":"457b"},{"sp":"N","t":"φύλακας ἡμῖν καὶ τὰς φυλακίδας, ἀλλά πῃ τὸν λόγον αὐτὸν αὑτῷ ὁμολογεῖσθαι ὡς δυνατά τε καὶ ὠφέλιμα λέγει;","st":"457c"},{"sp":"N","t":"καὶ μάλα, ἔφη, οὐ σμικρὸν κῦμα διαφεύγεις.","st":"457c"},{"sp":"N","t":"φήσεις γε, ἦν δ᾽ ἐγώ, οὐ μέγα αὐτὸ εἶναι, ὅταν τὸ μετὰ τοῦτο ἴδῃς.","st":"457c"},{"sp":"N","t":"λέγε δή, ἴδω, ἔφη.","st":"457c"},{"sp":"N","t":"τούτῳ, ἦν δ᾽ ἐγώ, ἕπεται νόμος καὶ τοῖς ἔμπροσθεν τοῖς ἄλλοις, ὡς ἐγᾦμαι, ὅδε.","st":"457c"},{"sp":"N","t":"τίς;","st":"457c"},{"sp":"N","t":"τὰς γυναῖκας ταύτας τῶν ἀνδρῶν τούτων πάντων πάσας","st":"457c"},{"sp":"N","t":"εἶναι κοινάς, ἰδίᾳ δὲ μηδενὶ μηδεμίαν συνοικεῖν: καὶ τοὺς παῖδας αὖ κοινούς, καὶ μήτε γονέα ἔκγονον εἰδέναι τὸν αὑτοῦ μήτε παῖδα γονέα.","st":"457d"},{"sp":"N","t":"πολύ, ἔφη, τοῦτο ἐκείνου μεῖζον πρὸς ἀπιστίαν καὶ τοῦ δυνατοῦ πέρι καὶ τοῦ ὠφελίμου.","st":"457d"},{"sp":"N","t":"οὐκ οἶμαι, ἦν δ᾽ ἐγώ, περί γε τοῦ ὠφελίμου ἀμφισβητεῖσθαι ἄν, ὡς οὐ μέγιστον ἀγαθὸν κοινὰς μὲν τὰς γυναῖκας εἶναι, κοινοὺς δὲ τοὺς παῖδας, εἴπερ οἷόν τε: ἀλλ᾽ οἶμαι περὶ τοῦ εἰ δυνατὸν ἢ μὴ πλείστην ἂν ἀμφισβήτησιν γενέσθαι.","st":"457d"},{"sp":"N","t":"περὶ ἀμφοτέρων, ἦ δ᾽ ὅς, εὖ μάλ᾽ ἂν ἀμφισβητηθείη.","st":"457e"},{"sp":"N","t":"λέγεις, ἦν δ᾽ ἐγώ, λόγων σύστασιν: ἐγὼ δ᾽ ᾤμην ἔκ γε τοῦ ἑτέρου ἀποδράσεσθαι, εἴ σοι δόξειεν ὠφέλιμον εἶναι, λοιπὸν δὲ δή μοι ἔσεσθαι περὶ τοῦ δυνατοῦ καὶ μή. ἀλλ᾽ οὐκ ἔλαθες, ἦ δ᾽ ὅς, ἀποδιδράσκων, ἀλλ᾽ ἀμφοτέρων πέρι δίδου λόγον.","st":"457e"},{"sp":"N","t":"ὑφεκτέον, ἦν δ᾽ ἐγώ, δίκην. τοσόνδε μέντοι χάρισαί","st":"457e"},{"sp":"N","t":"μοι: ἔασόν με ἑορτάσαι, ὥσπερ οἱ ἀργοὶ τὴν διάνοιαν εἰώθασιν ἑστιᾶσθαι ὑφ᾽ ἑαυτῶν, ὅταν μόνοι πορεύωνται. καὶ γὰρ οἱ τοιοῦτοί που, πρὶν ἐξευρεῖν τίνα τρόπον ἔσται τι ὧν ἐπιθυμοῦσι, τοῦτο παρέντες, ἵνα μὴ κάμνωσι βουλευόμενοι περὶ τοῦ δυνατοῦ καὶ μή, θέντες ὡς ὑπάρχον εἶναι ὃ βούλονται, ἤδη τὰ λοιπὰ διατάττουσιν καὶ χαίρουσιν διεξιόντες οἷα δράσουσι γενομένου, ἀργὸν καὶ ἄλλως ψυχὴν ἔτι","st":"458a"},{"sp":"N","t":"ἀργοτέραν ποιοῦντες. ἤδη οὖν καὶ αὐτὸς μαλθακίζομαι, καὶ ἐκεῖνα μὲν ἐπιθυμῶ ἀναβαλέσθαι καὶ ὕστερον ἐπισκέψασθαι, ᾗ δυνατά, νῦν δὲ ὡς δυνατῶν ὄντων θεὶς σκέψομαι, ἄν μοι παριῇς, πῶς διατάξουσιν αὐτὰ οἱ ἄρχοντες γιγνόμενα, καὶ ὅτι πάντων συμφορώτατ᾽ ἂν εἴη πραχθέντα τῇ τε πόλει καὶ τοῖς φύλαξιν. ταῦτα πειράσομαί σοι πρότερα συνδιασκοπεῖσθαι, ὕστερα δ᾽ ἐκεῖνα, εἴπερ παριεῖς.","st":"458b"},{"sp":"N","t":"ἀλλὰ παρίημι, ἔφη, καὶ σκόπει.","st":"458b"},{"sp":"N","t":"οἶμαι τοίνυν, ἦν δ᾽ ἐγώ, εἴπερ ἔσονται οἱ ἄρχοντες ἄξιοι","st":"458b"},{"sp":"N","t":"τούτου τοῦ ὀνόματος, οἵ τε τούτοις ἐπίκουροι κατὰ ταὐτά, τοὺς μὲν ἐθελήσειν ποιεῖν τὰ ἐπιταττόμενα, τοὺς δὲ ἐπιτάξειν, τὰ μὲν αὐτοὺς πειθομένους τοῖς νόμοις, τὰ δὲ καὶ μιμουμένους, ὅσα ἂν ἐκείνοις ἐπιτρέψωμεν.","st":"458c"},{"sp":"N","t":"εἰκός, ἔφη.","st":"458c"},{"sp":"N","t":"σὺ μὲν τοίνυν, ἦν δ᾽ ἐγώ, ὁ νομοθέτης αὐτοῖς, ὥσπερ τοὺς ἄνδρας ἐξέλεξας, οὕτω καὶ τὰς γυναῖκας ἐκλέξας παραδώσεις καθ᾽ ὅσον οἷόν τε ὁμοφυεῖς: οἱ δέ, ἅτε οἰκίας τε καὶ συσσίτια κοινὰ ἔχοντες, ἰδίᾳ δὲ οὐδενὸς οὐδὲν τοιοῦτον κεκτημένου,","st":"458c"},{"sp":"N","t":"ὁμοῦ δὴ ἔσονται, ὁμοῦ δὲ ἀναμεμειγμένων καὶ ἐν γυμνασίοις καὶ ἐν τῇ ἄλλῃ τροφῇ ὑπ᾽ ἀνάγκης οἶμαι τῆς ἐμφύτου ἄξονται πρὸς τὴν ἀλλήλων μεῖξιν. ἢ οὐκ ἀναγκαῖά σοι δοκῶ λέγειν;","st":"458d"},{"sp":"N","t":"οὐ γεωμετρικαῖς γε, ἦ δ᾽ ὅς, ἀλλ᾽ ἐρωτικαῖς ἀνάγκαις, αἳ κινδυνεύουσιν ἐκείνων δριμύτεραι εἶναι πρὸς τὸ πείθειν τε καὶ ἕλκειν τὸν πολὺν λεών.","st":"458d"},{"sp":"N","t":"καὶ μάλα, εἶπον. ἀλλὰ μετὰ δὴ ταῦτα, ὦ Γλαύκων, ἀτάκτως μὲν μείγνυσθαι ἀλλήλοις ἢ ἄλλο ὁτιοῦν ποιεῖν οὔτε","st":"458d"},{"sp":"N","t":"ὅσιον ἐν εὐδαιμόνων πόλει οὔτ᾽ ἐάσουσιν οἱ ἄρχοντες.","st":"458e"},{"sp":"N","t":"οὐ γὰρ δίκαιον, ἔφη.","st":"458e"},{"sp":"N","t":"δῆλον δὴ ὅτι γάμους τὸ μετὰ τοῦτο ποιήσομεν ἱεροὺς εἰς δύναμιν ὅτι μάλιστα: εἶεν δ᾽ ἂν ἱεροὶ οἱ ὠφελιμώτατοι.","st":"458e"},{"sp":"N","t":"παντάπασι μὲν οὖν.","st":"458e"},{"sp":"N","t":"πῶς οὖν δὴ ὠφελιμώτατοι ἔσονται; τόδε μοι λέγε, ὦ Γλαύκων: ὁρῶ γάρ σου ἐν τῇ οἰκίᾳ καὶ κύνας θηρευτικοὺς καὶ τῶν γενναίων ὀρνίθων μάλα συχνούς: ἆρ᾽ οὖν, ὦ πρὸς Διός, προσέσχηκάς τι τοῖς τούτων γάμοις τε καὶ παιδοποιίᾳ;","st":"459a"},{"sp":"N","t":"τὸ ποῖον; ἔφη.","st":"459a"},{"sp":"N","t":"πρῶτον μὲν αὐτῶν τούτων, καίπερ ὄντων γενναίων, ἆρ᾽ οὐκ εἰσί τινες καὶ γίγνονται ἄριστοι;","st":"459a"},{"sp":"N","t":"εἰσίν.","st":"459a"},{"sp":"N","t":"πότερον οὖν ἐξ ἁπάντων ὁμοίως γεννᾷς, ἢ προθυμῇ ὅτι μάλιστα ἐκ τῶν ἀρίστων;","st":"459a"},{"sp":"N","t":"ἐκ τῶν ἀρίστων.","st":"459a"},{"sp":"N","t":"τί δ᾽; ἐκ τῶν νεωτάτων ἢ ἐκ τῶν γεραιτάτων ἢ ἐξ ἀκμαζόντων ὅτι μάλιστα;","st":"459b"},{"sp":"N","t":"ἐξ ἀκμαζόντων.","st":"459b"},{"sp":"N","t":"καὶ ἂν μὴ οὕτω γεννᾶται, πολύ σοι ἡγῇ χεῖρον ἔσεσθαι τό τε τῶν ὀρνίθων καὶ τὸ τῶν κυνῶν γένος;","st":"459b"},{"sp":"N","t":"ἔγωγ᾽, ἔφη.","st":"459b"},{"sp":"N","t":"τί δὲ ἵππων οἴει, ἦν δ᾽ ἐγώ, καὶ τῶν ἄλλων ζῴων; ἦ ἄλλῃ πῃ ἔχειν;","st":"459b"},{"sp":"N","t":"ἄτοπον μεντἄν, ἦ δ᾽ ὅς, εἴη.","st":"459b"},{"sp":"N","t":"βαβαῖ, ἦν δ᾽ ἐγώ, ὦ φίλε ἑταῖρε, ὡς ἄρα σφόδρα ἡμῖν δεῖ ἄκρων εἶναι τῶν ἀρχόντων, εἴπερ καὶ περὶ τὸ τῶν ἀνθρώπων γένος ὡσαύτως ἔχει.","st":"459b"},{"sp":"N","t":"ἀλλὰ μὲν δὴ ἔχει, ἔφη: ἀλλὰ τί δή;","st":"459c"},{"sp":"N","t":"ὅτι ἀνάγκη αὐτοῖς, ἦν δ᾽ ἐγώ, φαρμάκοις πολλοῖς χρῆσθαι. ἰατρὸν δέ που μὴ δεομένοις μὲν σώμασι φαρμάκων, ἀλλὰ διαίτῃ ἐθελόντων ὑπακούειν, καὶ φαυλότερον ἐξαρκεῖν ἡγούμεθα εἶναι: ὅταν δὲ δὴ καὶ φαρμακεύειν δέῃ, ἴσμεν ὅτι ἀνδρειοτέρου δεῖ τοῦ ἰατροῦ.","st":"459c"},{"sp":"N","t":"ἀληθῆ: ἀλλὰ πρὸς τί λέγεις;","st":"459c"},{"sp":"N","t":"πρὸς τόδε, ἦν δ᾽ ἐγώ: συχνῷ τῷ ψεύδει καὶ τῇ ἀπάτῃ κινδυνεύει ἡμῖν δεήσειν χρῆσθαι τοὺς ἄρχοντας ἐπ᾽ ὠφελίᾳ","st":"459c"},{"sp":"N","t":"τῶν ἀρχομένων. ἔφαμεν δέ που ἐν φαρμάκου εἴδει πάντα τὰ τοιαῦτα χρήσιμα εἶναι.","st":"459d"},{"sp":"N","t":"καὶ ὀρθῶς γε, ἔφη.","st":"459d"},{"sp":"N","t":"ἐν τοῖς γάμοις τοίνυν καὶ παιδοποιίαις ἔοικε τὸ ὀρθὸν τοῦτο γίγνεσθαι οὐκ ἐλάχιστον.","st":"459d"},{"sp":"N","t":"πῶς δή;","st":"459d"},{"sp":"N","t":"δεῖ μέν, εἶπον, ἐκ τῶν ὡμολογημένων τοὺς ἀρίστους ταῖς ἀρίσταις συγγίγνεσθαι ὡς πλειστάκις, τοὺς δὲ φαυλοτάτους ταῖς φαυλοτάταις τοὐναντίον, καὶ τῶν μὲν τὰ ἔκγονα τρέφειν,","st":"459d"},{"sp":"N","t":"τῶν δὲ μή, εἰ μέλλει τὸ ποίμνιον ὅτι ἀκρότατον εἶναι, καὶ ταῦτα πάντα γιγνόμενα λανθάνειν πλὴν αὐτοὺς τοὺς ἄρχοντας, εἰ αὖ ἡ ἀγέλη τῶν φυλάκων ὅτι μάλιστα ἀστασίαστος ἔσται.","st":"459e"},{"sp":"N","t":"ὀρθότατα, ἔφη.","st":"459e"},{"sp":"N","t":"οὐκοῦν δὴ ἑορταί τινες νομοθετητέαι ἐν αἷς συνάξομεν τάς τε νύμφας καὶ τοὺς νυμφίους καὶ θυσίαι, καὶ ὕμνοι","st":"459e"},{"sp":"N","t":"ποιητέοι τοῖς ἡμετέροις ποιηταῖς πρέποντες τοῖς γιγνομένοις γάμοις: τὸ δὲ πλῆθος τῶν γάμων ἐπὶ τοῖς ἄρχουσι ποιήσομεν, ἵν᾽ ὡς μάλιστα διασῴζωσι τὸν αὐτὸν ἀριθμὸν τῶν ἀνδρῶν, πρὸς πολέμους τε καὶ νόσους καὶ πάντα τὰ τοιαῦτα ἀποσκοποῦντες, καὶ μήτε μεγάλη ἡμῖν ἡ πόλις κατὰ τὸ δυνατὸν μήτε σμικρὰ γίγνηται.","st":"460a"},{"sp":"N","t":"ὀρθῶς, ἔφη.","st":"460a"},{"sp":"N","t":"κλῆροι δή τινες οἶμαι ποιητέοι κομψοί, ὥστε τὸν φαῦλον ἐκεῖνον αἰτιᾶσθαι ἐφ᾽ ἑκάστης συνέρξεως τύχην ἀλλὰ μὴ τοὺς ἄρχοντας.","st":"460a"},{"sp":"N","t":"καὶ μάλα, ἔφη.","st":"460a"},{"sp":"N","t":"καὶ τοῖς ἀγαθοῖς γέ που τῶν νέων ἐν πολέμῳ ἢ ἄλλοθί που γέρα δοτέον καὶ ἆθλα ἄλλα τε καὶ ἀφθονεστέρα ἡ ἐξουσία τῆς τῶν γυναικῶν συγκοιμήσεως, ἵνα καὶ ἅμα μετὰ προφάσεως ὡς πλεῖστοι τῶν παίδων ἐκ τῶν τοιούτων σπείρωνται.","st":"460b"},{"sp":"N","t":"ὀρθῶς.","st":"460b"},{"sp":"N","t":"οὐκοῦν καὶ τὰ ἀεὶ γιγνόμενα ἔκγονα παραλαμβάνουσαι αἱ ἐπὶ τούτων ἐφεστηκυῖαι ἀρχαὶ εἴτε ἀνδρῶν εἴτε γυναικῶν εἴτε ἀμφότερα — κοιναὶ μὲν γάρ που καὶ ἀρχαὶ γυναιξί τε καὶ ἀνδράσιν-","st":"460b"},{"sp":"N","t":"ναί.","st":"460b"},{"sp":"N","t":"τὰ μὲν δὴ τῶν ἀγαθῶν, δοκῶ, λαβοῦσαι εἰς τὸν σηκὸν οἴσουσιν παρά τινας τροφοὺς χωρὶς οἰκούσας ἔν τινι μέρει τῆς πόλεως: τὰ δὲ τῶν χειρόνων, καὶ ἐάν τι τῶν ἑτέρων ἀνάπηρον γίγνηται, ἐν ἀπορρήτῳ τε καὶ ἀδήλῳ κατακρύψουσιν ὡς πρέπει.","st":"460c"},{"sp":"N","t":"εἴπερ μέλλει, ἔφη, καθαρὸν τὸ γένος τῶν φυλάκων ἔσεσθαι.","st":"460c"},{"sp":"N","t":"οὐκοῦν καὶ τροφῆς οὗτοι ἐπιμελήσονται τάς τε μητέρας ἐπὶ τὸν σηκὸν ἄγοντες ὅταν σπαργῶσι, πᾶσαν μηχανὴν","st":"460c"},{"sp":"N","t":"μηχανώμενοι ὅπως μηδεμία τὸ αὑτῆς αἰσθήσεται, καὶ ἄλλας γάλα ἐχούσας ἐκπορίζοντες, ἐὰν μὴ αὐταὶ ἱκαναὶ ὦσι, καὶ αὐτῶν τούτων ἐπιμελήσονται ὅπως μέτριον χρόνον θηλάσονται, ἀγρυπνίας δὲ καὶ τὸν ἄλλον πόνον τίτθαις τε καὶ τροφοῖς παραδώσουσιν;","st":"460d"},{"sp":"N","t":"πολλὴν ῥᾳστώνην, ἔφη, λέγεις τῆς παιδοποιίας ταῖς τῶν φυλάκων γυναιξίν.","st":"460d"},{"sp":"N","t":"πρέπει γάρ, ἦν δ᾽ ἐγώ. τὸ δ᾽ ἐφεξῆς διέλθωμεν ὃ προυθέμεθα. ἔφαμεν γὰρ δὴ ἐξ ἀκμαζόντων δεῖν τὰ ἔκγονα γίγνεσθαι.","st":"460d"},{"sp":"N","t":"ἀληθῆ.","st":"460d"},{"sp":"N","t":"ἆρ᾽ οὖν σοι συνδοκεῖ μέτριος χρόνος ἀκμῆς τὰ εἴκοσι ἔτη γυναικί, ἀνδρὶ δὲ τὰ τριάκοντα;","st":"460e"},{"sp":"N","t":"τὰ ποῖα αὐτῶν; ἔφη.","st":"460e"},{"sp":"N","t":"γυναικὶ μέν, ἦν δ᾽ ἐγώ, ἀρξαμένῃ ἀπὸ εἰκοσιέτιδος μέχρι τετταρακονταέτιδος τίκτειν τῇ πόλει: ἀνδρὶ δέ, ἐπειδὰν τὴν ὀξυτάτην δρόμου ἀκμὴν παρῇ, τὸ ἀπὸ τούτου γεννᾶν τῇ πόλει μέχρι πεντεκαιπεντηκονταέτους.","st":"460e"},{"sp":"N","t":"ἀμφοτέρων γοῦν, ἔφη, αὕτη ἀκμὴ σώματός τε καὶ φρονήσεως.","st":"461a"},{"sp":"N","t":"οὐκοῦν ἐάντε πρεσβύτερος τούτων ἐάντε νεώτερος τῶν εἰς τὸ κοινὸν γεννήσεων ἅψηται, οὔτε ὅσιον οὔτε δίκαιον φήσομεν τὸ ἁμάρτημα, ὡς παῖδα φιτύοντος τῇ πόλει, ὅς, ἂν λάθῃ, γεννήσεται οὐχ ὑπὸ θυσιῶν οὐδ᾽ ὑπὸ εὐχῶν φύς, ἃς ἐφ᾽ ἑκάστοις τοῖς γάμοις εὔξονται καὶ ἱέρειαι καὶ ἱερεῖς καὶ σύμπασα ἡ πόλις ἐξ ἀγαθῶν ἀμείνους καὶ ἐξ ὠφελίμων","st":"461a"},{"sp":"N","t":"ὠφελιμωτέρους ἀεὶ τοὺς ἐκγόνους γίγνεσθαι, ἀλλ᾽ ὑπὸ σκότου μετὰ δεινῆς ἀκρατείας γεγονώς.","st":"461b"},{"sp":"N","t":"ὀρθῶς, ἔφη.","st":"461b"},{"sp":"N","t":"ὁ αὐτὸς δέ γ᾽, εἶπον, νόμος, ἐάν τις τῶν ἔτι γεννώντων μὴ συνέρξαντος ἄρχοντος ἅπτηται τῶν ἐν ἡλικίᾳ γυναικῶν: νόθον γὰρ καὶ ἀνέγγυον καὶ ἀνίερον φήσομεν αὐτὸν παῖδα τῇ πόλει καθιστάναι.","st":"461b"},{"sp":"N","t":"ὀρθότατα, ἔφη.","st":"461b"},{"sp":"N","t":"ὅταν δὲ δὴ οἶμαι αἵ τε γυναῖκες καὶ οἱ ἄνδρες τοῦ γεννᾶν ἐκβῶσι τὴν ἡλικίαν, ἀφήσομέν που ἐλευθέρους αὐτοὺς συγγίγνεσθαι","st":"461b"},{"sp":"N","t":"ᾧ ἂν ἐθέλωσι, πλὴν θυγατρὶ καὶ μητρὶ καὶ ταῖς τῶν θυγατέρων παισὶ καὶ ταῖς ἄνω μητρός, καὶ γυναῖκας αὖ πλὴν ὑεῖ καὶ πατρὶ καὶ τοῖς τούτων εἰς τὸ κάτω καὶ ἐπὶ τὸ ἄνω, καὶ ταῦτά γ᾽ ἤδη πάντα διακελευσάμενοι προθυμεῖσθαι μάλιστα μὲν μηδ᾽ εἰς φῶς ἐκφέρειν κύημα μηδέ γ᾽ ἕν, ἐὰν γένηται, ἐὰν δέ τι βιάσηται, οὕτω τιθέναι, ὡς οὐκ οὔσης τροφῆς τῷ τοιούτῳ. καὶ ταῦτα μέν γ᾽, ἔφη, μετρίως λέγεται: πατέρας δὲ καὶ","st":"461c"},{"sp":"N","t":"θυγατέρας καὶ ἃ νυνδὴ ἔλεγες πῶς διαγνώσονται ἀλλήλων;","st":"461d"},{"sp":"N","t":"οὐδαμῶς, ἦν δ᾽ ἐγώ: ἀλλ᾽ ἀφ᾽ ἧς ἂν ἡμέρας τις αὐτῶν νυμφίος γένηται, μετ᾽ ἐκείνην δεκάτῳ μηνὶ καὶ ἑβδόμῳ δὴ ἃ ἂν γένηται ἔκγονα, ταῦτα πάντα προσερεῖ τὰ μὲν ἄρρενα ὑεῖς, τὰ δὲ θήλεα θυγατέρας, καὶ ἐκεῖνα ἐκεῖνον πατέρα, καὶ οὕτω δὴ τὰ τούτων ἔκγονα παίδων παῖδας, καὶ ἐκεῖν᾽ αὖ ἐκείνους πάππους τε καὶ τηθάς, τὰ δ᾽ ἐν ἐκείνῳ τῷ χρόνῳ γεγονότα, ἐν ᾧ αἱ μητέρες καὶ οἱ πατέρες αὐτῶν ἐγέννων,","st":"461d"},{"sp":"N","t":"ἀδελφάς τε καὶ ἀδελφούς, ὥστε, ὃ νυνδὴ ἐλέγομεν, ἀλλήλων μὴ ἅπτεσθαι. ἀδελφοὺς δὲ καὶ ἀδελφὰς δώσει ὁ νόμος συνοικεῖν, ἐὰν ὁ κλῆρος ταύτῃ συμπίπτῃ καὶ ἡ Πυθία προσαναιρῇ.","st":"461e"},{"sp":"N","t":"ὀρθότατα, ἦ δ᾽ ὅς.","st":"461e"},{"sp":"N","t":"ἡ μὲν δὴ κοινωνία, ὦ Γλαύκων, αὕτη τε καὶ τοιαύτη γυναικῶν τε καὶ παίδων τοῖς φύλαξί σοι τῆς πόλεως: ὡς δὲ ἑπομένη τε τῇ ἄλλῃ πολιτείᾳ καὶ μακρῷ βελτίστη, δεῖ δὴ τὸ μετὰ τοῦτο βεβαιώσασθαι παρὰ τοῦ λόγου. ἢ πῶς ποιῶμεν;","st":"461e"},{"sp":"N","t":"οὕτω νὴ Δία, ἦ δ᾽ ὅς.","st":"462a"},{"sp":"N","t":"ἆρ᾽ οὖν οὐχ ἥδε ἀρχὴ τῆς ὁμολογίας, ἐρέσθαι ἡμᾶς αὐτοὺς τί ποτε τὸ μέγιστον ἀγαθὸν ἔχομεν εἰπεῖν εἰς πόλεως κατασκευήν, οὗ δεῖ στοχαζόμενον τὸν νομοθέτην τιθέναι τοὺς νόμους, καὶ τί μέγιστον κακόν, εἶτα ἐπισκέψασθαι ἆρα ἃ νυνδὴ διήλθομεν εἰς μὲν τὸ τοῦ ἀγαθοῦ ἴχνος ἡμῖν ἁρμόττει, τῷ δὲ τοῦ κακοῦ ἀναρμοστεῖ;","st":"462a"},{"sp":"N","t":"πάντων μάλιστα, ἔφη.","st":"462a"},{"sp":"N","t":"ἔχομεν οὖν τι μεῖζον κακὸν πόλει ἢ ἐκεῖνο ὃ ἂν αὐτὴν","st":"462a"},{"sp":"N","t":"διασπᾷ καὶ ποιῇ πολλὰς ἀντὶ μιᾶς; ἢ μεῖζον ἀγαθὸν τοῦ ὃ ἂν συνδῇ τε καὶ ποιῇ μίαν;","st":"462b"},{"sp":"N","t":"οὐκ ἔχομεν.","st":"462b"},{"sp":"N","t":"οὐκοῦν ἡ μὲν ἡδονῆς τε καὶ λύπης κοινωνία συνδεῖ, ὅταν ὅτι μάλιστα πάντες οἱ πολῖται τῶν αὐτῶν γιγνομένων τε καὶ ἀπολλυμένων παραπλησίως χαίρωσι καὶ λυπῶνται;","st":"462b"},{"sp":"N","t":"παντάπασι μὲν οὖν, ἔφη.","st":"462b"},{"sp":"N","t":"ἡ δέ γε τῶν τοιούτων ἰδίωσις διαλύει, ὅταν οἱ μὲν περιαλγεῖς, οἱ δὲ περιχαρεῖς γίγνωνται ἐπὶ τοῖς αὐτοῖς","st":"462b"},{"sp":"N","t":"παθήμασι τῆς πόλεώς τε καὶ τῶν ἐν τῇ πόλει;","st":"462c"},{"sp":"N","t":"τί δ᾽ οὔ;","st":"462c"},{"sp":"N","t":"ἆρ᾽ οὖν ἐκ τοῦδε τὸ τοιόνδε γίγνεται, ὅταν μὴ ἅμα φθέγγωνται ἐν τῇ πόλει τὰ τοιάδε ῥήματα, τό τε ἐμὸν καὶ τὸ οὐκ ἐμόν; καὶ περὶ τοῦ ἀλλοτρίου κατὰ ταὐτά;","st":"462c"},{"sp":"N","t":"κομιδῇ μὲν οὖν.","st":"462c"},{"sp":"N","t":"ἐν ᾗτινι δὴ πόλει πλεῖστοι ἐπὶ τὸ αὐτὸ κατὰ ταὐτὰ τοῦτο λέγουσι τὸ ἐμὸν καὶ τὸ οὐκ ἐμόν, αὕτη ἄριστα διοικεῖται;","st":"462c"},{"sp":"N","t":"πολύ γε.","st":"462c"},{"sp":"N","t":"καὶ ἥτις δὴ ἐγγύτατα ἑνὸς ἀνθρώπου ἔχει; οἷον ὅταν που ἡμῶν δάκτυλός του πληγῇ, πᾶσα ἡ κοινωνία ἡ κατὰ τὸ σῶμα πρὸς τὴν ψυχὴν τεταμένη εἰς μίαν σύνταξιν τὴν τοῦ ἄρχοντος","st":"462c"},{"sp":"N","t":"ἐν αὐτῇ ᾔσθετό τε καὶ πᾶσα ἅμα συνήλγησεν μέρους πονήσαντος ὅλη, καὶ οὕτω δὴ λέγομεν ὅτι ὁ ἄνθρωπος τὸν δάκτυλον ἀλγεῖ: καὶ περὶ ἄλλου ὁτουοῦν τῶν τοῦ ἀνθρώπου ὁ αὐτὸς λόγος, περί τε λύπης πονοῦντος μέρους καὶ περὶ ἡδονῆς ῥαΐζοντος;","st":"462d"},{"sp":"N","t":"ὁ αὐτὸς γάρ, ἔφη: καὶ τοῦτο ὃ ἐρωτᾷς, τοῦ τοιούτου ἐγγύτατα ἡ ἄριστα πολιτευομένη πόλις οἰκεῖ.","st":"462d"},{"sp":"N","t":"ἑνὸς δὴ οἶμαι πάσχοντος τῶν πολιτῶν ὁτιοῦν ἢ ἀγαθὸν","st":"462d"},{"sp":"N","t":"ἢ κακὸν ἡ τοιαύτη πόλις μάλιστά τε φήσει ἑαυτῆς εἶναι τὸ πάσχον, καὶ ἢ συνησθήσεται ἅπασα ἢ συλλυπήσεται.","st":"462e"},{"sp":"N","t":"ἀνάγκη, ἔφη, τήν γε εὔνομον.","st":"462e"},{"sp":"N","t":"ὥρα ἂν εἴη, ἦν δ᾽ ἐγώ, ἐπανιέναι ἡμῖν ἐπὶ τὴν ἡμετέραν πόλιν, καὶ τὰ τοῦ λόγου ὁμολογήματα σκοπεῖν ἐν αὐτῇ, εἰ αὐτὴ μάλιστ᾽ ἔχει εἴτε καὶ ἄλλη τις μᾶλλον.","st":"462e"},{"sp":"N","t":"οὐκοῦν χρή, ἔφη.","st":"462e"},{"sp":"N","t":"τί οὖν; ἔστι μέν που καὶ ἐν ταῖς ἄλλαις πόλεσιν ἄρχοντές τε καὶ δῆμος, ἔστι δὲ καὶ ἐν ταύτῃ;","st":"463a"},{"sp":"N","t":"ἔστι.","st":"463a"},{"sp":"N","t":"πολίτας μὲν δὴ πάντες οὗτοι ἀλλήλους προσεροῦσι;","st":"463a"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"463a"},{"sp":"N","t":"ἀλλὰ πρὸς τῷ πολίτας τί ὁ ἐν ταῖς ἄλλαις δῆμος τοὺς ἄρχοντας προσαγορεύει;","st":"463a"},{"sp":"N","t":"ἐν μὲν ταῖς πολλαῖς δεσπότας, ἐν δὲ ταῖς δημοκρατουμέναις αὐτὸ τοὔνομα τοῦτο, ἄρχοντας.","st":"463a"},{"sp":"N","t":"τί δ᾽ ὁ ἐν τῇ ἡμετέρᾳ δῆμος; πρὸς τῷ πολίτας τί τοὺς ἄρχοντάς φησιν εἶναι;","st":"463a"},{"sp":"N","t":"σωτῆράς τε καὶ ἐπικούρους, ἔφη.","st":"463b"},{"sp":"N","t":"τί δ᾽ οὗτοι τὸν δῆμον;","st":"463b"},{"sp":"N","t":"μισθοδότας τε καὶ τροφέας.","st":"463b"},{"sp":"N","t":"οἱ δ᾽ ἐν ταῖς ἄλλαις ἄρχοντες τοὺς δήμους;","st":"463b"},{"sp":"N","t":"δούλους, ἔφη.","st":"463b"},{"sp":"N","t":"τί δ᾽ οἱ ἄρχοντες ἀλλήλους;","st":"463b"},{"sp":"N","t":"συνάρχοντας, ἔφη.","st":"463b"},{"sp":"N","t":"τί δ᾽ οἱ ἡμέτεροι;","st":"463b"},{"sp":"N","t":"συμφύλακας.","st":"463b"},{"sp":"N","t":"ἔχεις οὖν εἰπεῖν τῶν ἀρχόντων τῶν ἐν ταῖς ἄλλαις πόλεσιν, εἴ τίς τινα ἔχει προσειπεῖν τῶν συναρχόντων τὸν μὲν ὡς οἰκεῖον, τὸν δ᾽ ὡς ἀλλότριον;","st":"463b"},{"sp":"N","t":"καὶ πολλούς γε.","st":"463b"},{"sp":"N","t":"οὐκοῦν τὸν μὲν οἰκεῖον ὡς ἑαυτοῦ νομίζει τε καὶ λέγει,","st":"463b"},{"sp":"N","t":"τὸν δ᾽ ἀλλότριον ὡς οὐχ ἑαυτοῦ;","st":"463c"},{"sp":"N","t":"οὕτω.","st":"463c"},{"sp":"N","t":"τί δὲ οἱ παρὰ σοὶ φύλακες; ἔσθ᾽ ὅστις αὐτῶν ἔχοι ἂν τῶν συμφυλάκων νομίσαι τινὰ ἢ προσειπεῖν ὡς ἀλλότριον;","st":"463c"},{"sp":"N","t":"οὐδαμῶς, ἔφη: παντὶ γὰρ ᾧ ἂν ἐντυγχάνῃ, ἢ ὡς ἀδελφῷ ἢ ὡς ἀδελφῇ ἢ ὡς πατρὶ ἢ ὡς μητρὶ ἢ ὑεῖ ἢ θυγατρὶ ἢ τούτων ἐκγόνοις ἢ προγόνοις νομιεῖ ἐντυγχάνειν.","st":"463c"},{"sp":"N","t":"κάλλιστα, ἦν δ᾽ ἐγώ, λέγεις, ἀλλ᾽ ἔτι καὶ τόδε εἰπέ: πότερον αὐτοῖς τὰ ὀνόματα μόνον οἰκεῖα νομοθετήσεις, ἢ","st":"463c"},{"sp":"N","t":"καὶ τὰς πράξεις πάσας κατὰ τὰ ὀνόματα πράττειν, περί τε τοὺς πατέρας, ὅσα νόμος περὶ πατέρας αἰδοῦς τε πέρι καὶ κηδεμονίας καὶ τοῦ ὑπήκοον δεῖν εἶναι τῶν γονέων, ἢ μήτε πρὸς θεῶν μήτε πρὸς ἀνθρώπων αὐτῷ ἄμεινον ἔσεσθαι, ὡς οὔτε ὅσια οὔτε δίκαια πράττοντος ἄν, εἰ ἄλλα πράττοι ἢ ταῦτα; αὗταί σοι ἢ ἄλλαι φῆμαι ἐξ ἁπάντων τῶν πολιτῶν ὑμνήσουσιν εὐθὺς περὶ τὰ τῶν παίδων ὦτα καὶ περὶ πατέρων, οὓς ἂν αὐτοῖς τις ἀποφήνῃ, καὶ περὶ τῶν ἄλλων συγγενῶν;","st":"463d"},{"sp":"N","t":"αὗται, ἔφη: γελοῖον γὰρ ἂν εἴη εἰ ἄνευ ἔργων οἰκεῖα ὀνόματα διὰ τῶν στομάτων μόνον φθέγγοιντο.","st":"463e"},{"sp":"N","t":"πασῶν ἄρα πόλεων μάλιστα ἐν αὐτῇ συμφωνήσουσιν ἑνός τινος ἢ εὖ ἢ κακῶς πράττοντος ὃ νυνδὴ ἐλέγομεν τὸ ῥῆμα, τὸ ὅτι τὸ ἐμὸν εὖ πράττει ἢ ὅτι τὸ ἐμὸν κακῶς.","st":"463e"},{"sp":"N","t":"ἀληθέστατα αὖ, ἦ δ᾽ ὅς.","st":"463e"},{"sp":"N","t":"οὐκοῦν μετὰ τούτου τοῦ δόγματός τε καὶ ῥήματος ἔφαμεν συνακολουθεῖν τάς τε ἡδονὰς καὶ τὰς λύπας κοινῇ;","st":"464a"},{"sp":"N","t":"καὶ ὀρθῶς γε ἔφαμεν.","st":"464a"},{"sp":"N","t":"οὐκοῦν μάλιστα τοῦ αὐτοῦ κοινωνήσουσιν ἡμῖν οἱ πολῖται, ὃ δὴ ἐμὸν ὀνομάσουσιν; τούτου δὲ κοινωνοῦντες οὕτω δὴ λύπης τε καὶ ἡδονῆς μάλιστα κοινωνίαν ἕξουσιν;","st":"464a"},{"sp":"N","t":"πολύ γε.","st":"464a"},{"sp":"N","t":"ἆρ᾽ οὖν τούτων αἰτία πρὸς τῇ ἄλλῃ καταστάσει ἡ τῶν γυναικῶν τε καὶ παίδων κοινωνία τοῖς φύλαξιν;","st":"464a"},{"sp":"N","t":"πολὺ μὲν οὖν μάλιστα, ἔφη.","st":"464a"},{"sp":"N","t":"ἀλλὰ μὴν μέγιστόν γε πόλει αὐτὸ ὡμολογήσαμεν ἀγαθόν, ἀπεικάζοντες εὖ οἰκουμένην πόλιν σώματι πρὸς μέρος αὑτοῦ λύπης τε πέρι καὶ ἡδονῆς ὡς ἔχει.","st":"464b"},{"sp":"N","t":"καὶ ὀρθῶς γ᾽, ἔφη, ὡμολογήσαμεν.","st":"464b"},{"sp":"N","t":"τοῦ μεγίστου ἄρα ἀγαθοῦ τῇ πόλει αἰτία ἡμῖν πέφανται ἡ κοινωνία τοῖς ἐπικούροις τῶν τε παίδων καὶ τῶν γυναικῶν.","st":"464b"},{"sp":"N","t":"καὶ μάλ᾽, ἔφη.","st":"464b"},{"sp":"N","t":"καὶ μὲν δὴ καὶ τοῖς πρόσθεν γε ὁμολογοῦμεν: ἔφαμεν γάρ που οὔτε οἰκίας τούτοις ἰδίας δεῖν εἶναι οὔτε γῆν οὔτε","st":"464b"},{"sp":"N","t":"τι κτῆμα, ἀλλὰ παρὰ τῶν ἄλλων τροφὴν λαμβάνοντας, μισθὸν τῆς φυλακῆς, κοινῇ πάντας ἀναλίσκειν, εἰ μέλλοιεν ὄντως φύλακες εἶναι.","st":"464c"},{"sp":"N","t":"ὀρθῶς, ἔφη.","st":"464c"},{"sp":"N","t":"ἆρ᾽ οὖν οὐχ, ὅπερ λέγω, τά τε πρόσθεν εἰρημένα καὶ τὰ νῦν λεγόμενα ἔτι μᾶλλον ἀπεργάζεται αὐτοὺς ἀληθινοὺς φύλακας, καὶ ποιεῖ μὴ διασπᾶν τὴν πόλιν τὸ ἐμὸν ὀνομάζοντας μὴ τὸ αὐτὸ ἀλλ᾽ ἄλλον ἄλλο, τὸν μὲν εἰς τὴν ἑαυτοῦ οἰκίαν ἕλκοντα ὅτι ἂν δύνηται χωρὶς τῶν ἄλλων κτήσασθαι,","st":"464c"},{"sp":"N","t":"τὸν δὲ εἰς τὴν ἑαυτοῦ ἑτέραν οὖσαν, καὶ γυναῖκά τε καὶ παῖδας ἑτέρους, ἡδονάς τε καὶ ἀλγηδόνας ἐμποιοῦντας ἰδίων ὄντων ἰδίας, ἀλλ᾽ ἑνὶ δόγματι τοῦ οἰκείου πέρι ἐπὶ τὸ αὐτὸ τείνοντας πάντας εἰς τὸ δυνατὸν ὁμοπαθεῖς λύπης τε καὶ ἡδονῆς εἶναι;","st":"464d"},{"sp":"N","t":"κομιδῇ μὲν οὖν, ἔφη.","st":"464d"},{"sp":"N","t":"τί δέ; δίκαι τε καὶ ἐγκλήματα πρὸς ἀλλήλους οὐκ οἰχήσεται ἐξ αὐτῶν ὡς ἔπος εἰπεῖν διὰ τὸ μηδὲν ἴδιον ἐκτῆσθαι πλὴν τὸ σῶμα, τὰ δ᾽ ἄλλα κοινά; ὅθεν δὴ ὑπάρχει","st":"464d"},{"sp":"N","t":"τούτοις ἀστασιάστοις εἶναι, ὅσα γε διὰ χρημάτων ἢ παίδων καὶ συγγενῶν κτῆσιν ἄνθρωποι στασιάζουσιν;","st":"464e"},{"sp":"N","t":"πολλὴ ἀνάγκη, ἔφη, ἀπηλλάχθαι.","st":"464e"},{"sp":"N","t":"καὶ μὴν οὐδὲ βιαίων γε οὐδ᾽ αἰκίας δίκαι δικαίως ἂν εἶεν ἐν αὐτοῖς: ἥλιξι μὲν γὰρ ἥλικας ἀμύνεσθαι καλὸν καὶ δίκαιόν που φήσομεν, ἀνάγκην σωμάτων ἐπιμελείᾳ τιθέντες.","st":"464e"},{"sp":"N","t":"ὀρθῶς, ἔφη.","st":"464e"},{"sp":"N","t":"καὶ γὰρ τόδε ὀρθὸν ἔχει, ἦν δ᾽ ἐγώ, οὗτος ὁ νόμος: εἴ πού τίς τῳ θυμοῖτο, ἐν τῷ τοιούτῳ πληρῶν τὸν θυμὸν ἧττον ἐπὶ μείζους ἂν ἴοι στάσεις.","st":"465a"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"465a"},{"sp":"N","t":"πρεσβυτέρῳ μὴν νεωτέρων πάντων ἄρχειν τε καὶ κολάζειν προστετάξεται.","st":"465a"},{"sp":"N","t":"δῆλον.","st":"465a"},{"sp":"N","t":"καὶ μὴν ὅτι γε νεώτερος πρεσβύτερον, ἂν μὴ ἄρχοντες προστάττωσιν, οὔτε ἄλλο βιάζεσθαι ἐπιχειρήσει ποτὲ οὔτε τύπτειν, ὡς τὸ εἰκός. οἶμαι δ᾽ οὐδὲ ἄλλως ἀτιμάσει: ἱκανὼ γὰρ τὼ φύλακε κωλύοντε, δέος τε καὶ αἰδώς, αἰδὼς μὲν ὡς","st":"465a"},{"sp":"N","t":"γονέων μὴ ἅπτεσθαι εἴργουσα, δέος δὲ τὸ τῷ πάσχοντι τοὺς ἄλλους βοηθεῖν, τοὺς μὲν ὡς ὑεῖς, τοὺς δὲ ὡς ἀδελφούς, τοὺς δὲ ὡς πατέρας.","st":"465b"},{"sp":"N","t":"συμβαίνει γὰρ οὕτως, ἔφη.","st":"465b"},{"sp":"N","t":"πανταχῇ δὴ ἐκ τῶν νόμων εἰρήνην πρὸς ἀλλήλους οἱ ἄνδρες ἄξουσι;","st":"465b"},{"sp":"N","t":"πολλήν γε.","st":"465b"},{"sp":"N","t":"τούτων μὴν ἐν ἑαυτοῖς μὴ στασιαζόντων οὐδὲν δεινὸν μή ποτε ἡ ἄλλη πόλις πρὸς τούτους ἢ πρὸς ἀλλήλους διχοστατήσῃ.","st":"465b"},{"sp":"N","t":"οὐ γὰρ οὖν.","st":"465b"},{"sp":"N","t":"τά γε μὴν σμικρότατα τῶν κακῶν δι᾽ ἀπρέπειαν ὀκνῶ","st":"465b"},{"sp":"N","t":"καὶ λέγειν, ὧν ἀπηλλαγμένοι ἂν εἶεν, κολακείας τε πλουσίων πένητες ἀπορίας τε καὶ ἀλγηδόνας ὅσας ἐν παιδοτροφίᾳ καὶ χρηματισμοῖς διὰ τροφὴν οἰκετῶν ἀναγκαίαν ἴσχουσι, τὰ μὲν δανειζόμενοι, τὰ δ᾽ ἐξαρνούμενοι, τὰ δὲ πάντως πορισάμενοι θέμενοι παρὰ γυναῖκάς τε καὶ οἰκέτας, ταμιεύειν παραδόντες, ὅσα τε, ὦ φίλε, περὶ αὐτὰ καὶ οἷα πάσχουσι, δῆλά τε δὴ καὶ ἀγεννῆ καὶ οὐκ ἄξια λέγειν.","st":"465c"},{"sp":"N","t":"δῆλα γάρ, ἔφη, καὶ τυφλῷ.","st":"465d"},{"sp":"N","t":"πάντων τε δὴ τούτων ἀπαλλάξονται, ζήσουσί τε τοῦ μακαριστοῦ βίου ὃν οἱ Ὀλυμπιονῖκαι ζῶσι μακαριώτερον.","st":"465d"},{"sp":"N","t":"πῇ;","st":"465d"},{"sp":"N","t":"διὰ σμικρόν που μέρος εὐδαιμονίζονται ἐκεῖνοι ὧν τούτοις ὑπάρχει. ἥ τε γὰρ τῶνδε νίκη καλλίων, ἥ τ᾽ ἐκ τοῦ δημοσίου τροφὴ τελεωτέρα. νίκην τε γὰρ νικῶσι συμπάσης τῆς πόλεως σωτηρίαν, τροφῇ τε καὶ τοῖς ἄλλοις πᾶσιν ὅσων βίος δεῖται αὐτοί τε καὶ παῖδες ἀναδοῦνται, καὶ γέρα δέχονται","st":"465d"},{"sp":"N","t":"παρὰ τῆς αὑτῶν πόλεως ζῶντές τε καὶ τελευτήσαντες ταφῆς ἀξίας μετέχουσιν.","st":"465e"},{"sp":"N","t":"καὶ μάλα, ἔφη, καλά.","st":"465e"},{"sp":"N","t":"μέμνησαι οὖν, ἦν δ᾽ ἐγώ, ὅτι ἐν τοῖς πρόσθεν οὐκ οἶδα ὅτου λόγος ἡμῖν ἐπέπληξεν ὅτι τοὺς φύλακας οὐκ εὐδαίμονας","st":"465e"},{"sp":"N","t":"ποιοῖμεν, οἷς ἐξὸν πάντα ἔχειν τὰ τῶν πολιτῶν οὐδὲν ἔχοιεν; ἡμεῖς δέ που εἴπομεν ὅτι τοῦτο μέν, εἴ που παραπίπτοι, εἰς αὖθις σκεψοίμεθα, νῦν δὲ τοὺς μὲν φύλακας φύλακας ποιοῖμεν, τὴν δὲ πόλιν ὡς οἷοί τ᾽ εἶμεν εὐδαιμονεστάτην, ἀλλ᾽ οὐκ εἰς ἓν ἔθνος ἀποβλέποντες ἐν αὐτῇ τοῦτο εὔδαιμον πλάττοιμεν;","st":"466a"},{"sp":"N","t":"μέμνημαι, ἔφη.","st":"466a"},{"sp":"N","t":"τί οὖν; νῦν ἡμῖν ὁ τῶν ἐπικούρων βίος, εἴπερ τοῦ γε τῶν Ὀλυμπιονικῶν πολύ τε καλλίων καὶ ἀμείνων φαίνεται,","st":"466a"},{"sp":"N","t":"μή πῃ κατὰ τὸν τῶν σκυτοτόμων φαίνεται βίον ἤ τινων ἄλλων δημιουργῶν ἢ τὸν τῶν γεωργῶν;","st":"466b"},{"sp":"N","t":"οὔ μοι δοκεῖ, ἔφη.","st":"466b"},{"sp":"N","t":"ἀλλὰ μέντοι, ὅ γε καὶ ἐκεῖ ἔλεγον, δίκαιον καὶ ἐνταῦθα εἰπεῖν, ὅτι εἰ οὕτως ὁ φύλαξ ἐπιχειρήσει εὐδαίμων γίγνεσθαι, ὥστε μηδὲ φύλαξ εἶναι, μηδ᾽ ἀρκέσει αὐτῷ βίος οὕτω μέτριος καὶ βέβαιος καὶ ὡς ἡμεῖς φαμεν ἄριστος, ἀλλ᾽ ἀνόητός τε καὶ μειρακιώδης δόξα ἐμπεσοῦσα εὐδαιμονίας πέρι ὁρμήσει","st":"466b"},{"sp":"N","t":"αὐτὸν διὰ δύναμιν ἐπὶ τὸ ἅπαντα τὰ ἐν τῇ πόλει οἰκειοῦσθαι, γνώσεται τὸν Ἡσίοδον ὅτι τῷ ὄντι ἦν σοφὸς λέγων “πλέον” εἶναί πως “ἥμισυ παντός.”","st":"466c"},{"sp":"N","t":"ἐμοὶ μέν, ἔφη, συμβούλῳ χρώμενος μενεῖ ἐπὶ τούτῳ τῷ βίῳ.","st":"466c"},{"sp":"N","t":"συγχωρεῖς ἄρα, ἦν δ᾽ ἐγώ, τὴν τῶν γυναικῶν κοινωνίαν τοῖς ἀνδράσιν, ἣν διεληλύθαμεν, παιδείας τε πέρι καὶ παίδων καὶ φυλακῆς τῶν ἄλλων πολιτῶν, κατά τε πόλιν μενούσας εἰς πόλεμόν τε ἰούσας καὶ συμφυλάττειν δεῖν καὶ","st":"466c"},{"sp":"N","t":"συνθηρεύειν ὥσπερ κύνας, καὶ πάντα πάντῃ κατὰ τὸ δυνατὸν κοινωνεῖν, καὶ ταῦτα πραττούσας τά τε βέλτιστα πράξειν καὶ οὐ παρὰ φύσιν τὴν τοῦ θήλεος πρὸς τὸ ἄρρεν, ᾗ πεφύκατον πρὸς ἀλλήλω κοινωνεῖν;","st":"466d"},{"sp":"N","t":"συγχωρῶ, ἔφη.","st":"466d"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, ἐκεῖνο λοιπὸν διελέσθαι, εἰ ἄρα καὶ ἐν ἀνθρώποις δυνατόν, ὥσπερ ἐν ἄλλοις ζῴοις, ταύτην τὴν κοινωνίαν ἐγγενέσθαι, καὶ ὅπῃ δυνατόν;","st":"466d"},{"sp":"N","t":"ἔφθης, ἔφη, εἰπὼν ᾗ ἔμελλον ὑπολήψεσθαι.","st":"466d"},{"sp":"N","t":"περὶ μὲν γὰρ τῶν ἐν τῷ πολέμῳ οἶμαι, ἔφην, δῆλον ὃν τρόπον πολεμήσουσιν.","st":"466e"},{"sp":"N","t":"πῶς; ἦ δ᾽ ὅς.","st":"466e"},{"sp":"N","t":"ὅτι κοινῇ στρατεύσονται, καὶ πρός γε ἄξουσι τῶν παίδων εἰς τὸν πόλεμον ὅσοι ἁδροί, ἵν᾽ ὥσπερ οἱ τῶν ἄλλων δημιουργῶν θεῶνται ταῦτα ἃ τελεωθέντας δεήσει δημιουργεῖν:","st":"466e"},{"sp":"N","t":"πρὸς δὲ τῇ θέᾳ διακονεῖν καὶ ὑπηρετεῖν πάντα τὰ περὶ τὸν πόλεμον, καὶ θεραπεύειν πατέρας τε καὶ μητέρας. ἢ οὐκ ᾔσθησαι τὰ περὶ τὰς τέχνας, οἷον τοὺς τῶν κεραμέων παῖδας, ὡς πολὺν χρόνον διακονοῦντες θεωροῦσι πρὶν ἅπτεσθαι τοῦ κεραμεύειν;","st":"467a"},{"sp":"N","t":"καὶ μάλα.","st":"467a"},{"sp":"N","t":"ἦ οὖν ἐκείνοις ἐπιμελέστερον παιδευτέον ἢ τοῖς φύλαξι τοὺς αὑτῶν ἐμπειρίᾳ τε καὶ θέᾳ τῶν προσηκόντων;","st":"467a"},{"sp":"N","t":"καταγέλαστον μεντἄν, ἔφη, εἴη.","st":"467a"},{"sp":"N","t":"ἀλλὰ μὴν καὶ μαχεῖταί γε πᾶν ζῷον διαφερόντως","st":"467a"},{"sp":"N","t":"παρόντων ὧν ἂν τέκῃ.","st":"467b"},{"sp":"N","t":"ἔστιν οὕτω. κίνδυνος δέ, ὦ Σώκρατες, οὐ σμικρὸς σφαλεῖσιν, οἷα δὴ ἐν πολέμῳ φιλεῖ, πρὸς ἑαυτοῖς παῖδας ἀπολέσαντας ποιῆσαι καὶ τὴν ἄλλην πόλιν ἀδύνατον ἀναλαβεῖν. ἀληθῆ, ἦν δ᾽ ἐγώ, λέγεις. ἀλλὰ σὺ πρῶτον μὲν ἡγῇ παρασκευαστέον τὸ μή ποτε κινδυνεῦσαι;","st":"467b"},{"sp":"N","t":"οὐδαμῶς.","st":"467b"},{"sp":"N","t":"τί δ᾽; εἴ που κινδυνευτέον, οὐκ ἐν ᾧ βελτίους ἔσονται κατορθοῦντες;","st":"467b"},{"sp":"N","t":"δῆλον δή.","st":"467b"},{"sp":"N","t":"ἀλλὰ σμικρὸν οἴει διαφέρειν καὶ οὐκ ἄξιον κινδύνου θεωρεῖν ἢ μὴ τὰ περὶ τὸν πόλεμον παῖδας τοὺς ἄνδρας πολεμικοὺς ἐσομένους;","st":"467c"},{"sp":"N","t":"οὔκ, ἀλλὰ διαφέρει πρὸς ὃ λέγεις.","st":"467c"},{"sp":"N","t":"τοῦτο μὲν ἄρα ὑπαρκτέον, θεωροὺς πολέμου τοὺς παῖδας ποιεῖν, προσμηχανᾶσθαι δ᾽ αὐτοῖς ἀσφάλειαν, καὶ καλῶς ἕξει: ἦ γάρ;","st":"467c"},{"sp":"N","t":"ναί.","st":"467c"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, πρῶτον μὲν αὐτῶν οἱ πατέρες, ὅσα ἄνθρωποι, οὐκ ἀμαθεῖς ἔσονται ἀλλὰ γνωμονικοὶ τῶν","st":"467c"},{"sp":"N","t":"στρατειῶν ὅσαι τε καὶ μὴ ἐπικίνδυνοι;","st":"467d"},{"sp":"N","t":"εἰκός, ἔφη.","st":"467d"},{"sp":"N","t":"εἰς μὲν ἄρα τὰς ἄξουσιν, εἰς δὲ τὰς εὐλαβήσονται.","st":"467d"},{"sp":"N","t":"ὀρθῶς.","st":"467d"},{"sp":"N","t":"καὶ ἄρχοντάς γέ που, ἦν δ᾽ ἐγώ, οὐ τοὺς φαυλοτάτους αὐτοῖς ἐπιστήσουσιν ἀλλὰ τοὺς ἐμπειρίᾳ τε καὶ ἡλικίᾳ ἱκανοὺς ἡγεμόνας τε καὶ παιδαγωγοὺς εἶναι.","st":"467d"},{"sp":"N","t":"πρέπει γάρ.","st":"467d"},{"sp":"N","t":"ἀλλὰ γάρ, φήσομεν, καὶ παρὰ δόξαν πολλὰ πολλοῖς δὴ ἐγένετο.","st":"467d"},{"sp":"N","t":"καὶ μάλα.","st":"467d"},{"sp":"N","t":"πρὸς τοίνυν τὰ τοιαῦτα, ὦ φίλε, πτεροῦν χρὴ παιδία ὄντα εὐθύς, ἵν᾽, ἄν τι δέῃ, πετόμενοι ἀποφεύγωσιν.","st":"467d"},{"sp":"N","t":"πῶς λέγεις; ἔφη.","st":"467e"},{"sp":"N","t":"ἐπὶ τοὺς ἵππους, ἦν δ᾽ ἐγώ, ἀναβιβαστέον ὡς νεωτάτους, καὶ διδαξαμένους ἱππεύειν ἐφ᾽ ἵππων ἀκτέον ἐπὶ τὴν θέαν, μὴ θυμοειδῶν μηδὲ μαχητικῶν, ἀλλ᾽ ὅτι ποδωκεστάτων καὶ εὐηνιωτάτων. οὕτω γὰρ κάλλιστά τε θεάσονται τὸ αὑτῶν ἔργον, καὶ ἀσφαλέστατα, ἄν τι δέῃ, σωθήσονται μετὰ πρεσβυτέρων ἡγεμόνων ἑπόμενοι.","st":"467e"},{"sp":"N","t":"ὀρθῶς, ἔφη, μοι δοκεῖς λέγειν.","st":"467e"},{"sp":"N","t":"τί δὲ δή, εἶπον, τὰ περὶ τὸν πόλεμον; πῶς ἑκτέον σοι τοὺς στρατιώτας πρὸς αὑτούς τε καὶ τοὺς πολεμίους; ἆρ᾽ ὀρθῶς μοι καταφαίνεται ἢ οὔ;","st":"468a"},{"sp":"N","t":"λέγ᾽, ἔφη, ποῖ᾽ αὖ.","st":"468a"},{"sp":"N","t":"αὐτῶν μέν, εἶπον, τὸν λιπόντα τάξιν ἢ ὅπλα ἀποβαλόντα ἤ τι τῶν τοιούτων ποιήσαντα διὰ κάκην ἆρα οὐ δημιουργόν τινα δεῖ καθιστάναι ἢ γεωργόν;","st":"468a"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"468a"},{"sp":"N","t":"τὸν δὲ ζῶντα εἰς τοὺς πολεμίους ἁλόντα ἆρ᾽ οὐ δωρεὰν διδόναι τοῖς ἑλοῦσι χρῆσθαι τῇ ἄγρᾳ ὅτι ἂν βούλωνται;","st":"468a"},{"sp":"N","t":"κομιδῇ γε.","st":"468b"},{"sp":"N","t":"τὸν δὲ ἀριστεύσαντά τε καὶ εὐδοκιμήσαντα οὐ πρῶτον μὲν ἐπὶ στρατιᾶς ὑπὸ τῶν συστρατευομένων μειρακίων τε καὶ παίδων ἐν μέρει ὑπὸ ἑκάστου δοκεῖ σοι χρῆναι στεφανωθῆναι; ἢ οὔ;","st":"468b"},{"sp":"N","t":"ἔμοιγε.","st":"468b"},{"sp":"N","t":"τί δέ; δεξιωθῆναι;","st":"468b"},{"sp":"N","t":"καὶ τοῦτο.","st":"468b"},{"sp":"N","t":"ἀλλὰ τόδ᾽ οἶμαι, ἦν δ᾽ ἐγώ, οὐκέτι σοι δοκεῖ.","st":"468b"},{"sp":"N","t":"τὸ ποῖον;","st":"468b"},{"sp":"N","t":"τὸ φιλῆσαί τε καὶ φιληθῆναι ὑπὸ ἑκάστου.","st":"468b"},{"sp":"N","t":"πάντων, ἔφη, μάλιστα: καὶ προστίθημί γε τῷ νόμῳ,","st":"468b"},{"sp":"N","t":"ἕως ἂν ἐπὶ ταύτης ὦσι τῆς στρατιᾶς, καὶ μηδενὶ ἐξεῖναι ἀπαρνηθῆναι ὃν ἂν βούληται φιλεῖν, ἵνα καί, ἐάν τίς του τύχῃ ἐρῶν ἢ ἄρρενος ἢ θηλείας, προθυμότερος ᾖ πρὸς τὸ τἀριστεῖα φέρειν.","st":"468c"},{"sp":"N","t":"καλῶς, ἦν δ᾽ ἐγώ. ὅτι μὲν γὰρ ἀγαθῷ ὄντι γάμοι τε ἕτοιμοι πλείους ἢ τοῖς ἄλλοις καὶ αἱρέσεις τῶν τοιούτων πολλάκις παρὰ τοὺς ἄλλους ἔσονται, ἵν᾽ ὅτι πλεῖστοι ἐκ τοῦ τοιούτου γίγνωνται, εἴρηται ἤδη.","st":"468c"},{"sp":"N","t":"εἴπομεν γάρ, ἔφη.","st":"468c"},{"sp":"N","t":"ἀλλὰ μὴν καὶ καθ᾽ Ὅμηρον τοῖς τοιοῖσδε δίκαιον τιμᾶν","st":"468c"},{"sp":"N","t":"τῶν νέων ὅσοι ἀγαθοί. καὶ γὰρ Ὅμηρος τὸν εὐδοκιμήσαντα ἐν τῷ πολέμῳ “νώτοισιν” Αἴαντα ἔφη “διηνεκέεσσι γεραίρεσθαι,” ὡς ταύτην οἰκείαν οὖσαν τιμὴν τῷ ἡβῶντί τε καὶ ἀνδρείῳ, ἐξ ἧς ἅμα τῷ τιμᾶσθαι καὶ τὴν ἰσχὺν αὐξήσει.","st":"468d"},{"sp":"N","t":"ὀρθότατα, ἔφη.","st":"468d"},{"sp":"N","t":"πεισόμεθα ἄρα, ἦν δ᾽ ἐγώ, ταῦτά γε Ὁμήρῳ. καὶ γὰρ ἡμεῖς ἔν τε θυσίαις καὶ τοῖς τοιούτοις πᾶσι τοὺς ἀγαθούς, καθ᾽ ὅσον ἂν ἀγαθοὶ φαίνωνται, καὶ ὕμνοις καὶ οἷς νυνδὴ ἐλέγομεν τιμήσομεν, πρὸς δὲ τούτοις “ἕδραις τε καὶ κρέασιν”","st":"468d"},{"sp":"N","t":"“ἰδὲ πλείοις δεπάεσσιν,” ἵνα ἅμα τῷ τιμᾶν ἀσκῶμεν τοὺς ἀγαθοὺς ἄνδρας τε καὶ γυναῖκας.","st":"468e"},{"sp":"N","t":"κάλλιστα, ἔφη, λέγεις.","st":"468e"},{"sp":"N","t":"εἶεν: τῶν δὲ δὴ ἀποθανόντων ἐπὶ στρατιᾶς ὃς ἂν εὐδοκιμήσας τελευτήσῃ ἆρ᾽ οὐ πρῶτον μὲν φήσομεν τοῦ χρυσοῦ γένους εἶναι;","st":"468e"},{"sp":"N","t":"πάντων γε μάλιστα.","st":"468e"},{"sp":"N","t":"ἀλλ᾽ οὐ πεισόμεθα Ἡσιόδῳ, ἐπειδάν τινες τοῦ τοιούτου γένους τελευτήσωσιν, ὡς ἄρα-","st":"468e"},{"sp":"N","t":"οἱ μὲν δαίμονες ἁγνοὶ ἐπιχθόνιοι τελέθουσιν,","st":"469a"},{"sp":"N","t":"ἐσθλοί, ἀλεξίκακοι, φύλακες μερόπων ἀνθρώπων;","st":"469a"},{"sp":"N","t":"πεισόμεθα μὲν οὖν.","st":"469a"},{"sp":"N","t":"διαπυθόμενοι ἄρα τοῦ θεοῦ πῶς χρὴ τοὺς δαιμονίους τε καὶ θείους τιθέναι καὶ τίνι διαφόρῳ, οὕτω καὶ ταύτῃ θήσομεν ᾗ ἂν ἐξηγῆται;","st":"469a"},{"sp":"N","t":"τί δ᾽ οὐ μέλλομεν;","st":"469a"},{"sp":"N","t":"καὶ τὸν λοιπὸν δὴ χρόνον ὡς δαιμόνων, οὕτω θεραπεύσομέν","st":"469a"},{"sp":"N","t":"τε καὶ προσκυνήσομεν αὐτῶν τὰς θήκας; ταὐτὰ δὲ ταῦτα νομιοῦμεν ὅταν τις γήρᾳ ἤ τινι ἄλλῳ τρόπῳ τελευτήσῃ τῶν ὅσοι ἂν διαφερόντως ἐν τῷ βίῳ ἀγαθοὶ κριθῶσιν;","st":"469b"},{"sp":"N","t":"δίκαιον γοῦν, ἔφη.","st":"469b"},{"sp":"N","t":"τί δέ; πρὸς τοὺς πολεμίους πῶς ποιήσουσιν ἡμῖν οἱ στρατιῶται;","st":"469b"},{"sp":"N","t":"τὸ ποῖον δή;","st":"469b"},{"sp":"N","t":"πρῶτον μὲν ἀνδραποδισμοῦ πέρι, δοκεῖ δίκαιον Ἕλληνας Ἑλληνίδας πόλεις ἀνδραποδίζεσθαι, ἢ μηδ᾽ ἄλλῃ ἐπιτρέπειν κατὰ τὸ δυνατὸν καὶ τοῦτο ἐθίζειν, τοῦ Ἑλληνικοῦ","st":"469b"},{"sp":"N","t":"γένους φείδεσθαι, εὐλαβουμένους τὴν ὑπὸ τῶν βαρβάρων δουλείαν;","st":"469c"},{"sp":"N","t":"ὅλῳ καὶ παντί, ἔφη, διαφέρει τὸ φείδεσθαι.","st":"469c"},{"sp":"N","t":"μηδὲ Ἕλληνα ἄρα δοῦλον ἐκτῆσθαι μήτε αὐτούς, τοῖς τε ἄλλοις Ἕλλησιν οὕτω συμβουλεύειν;","st":"469c"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη: μᾶλλόν γ᾽ ἂν οὖν οὕτω πρὸς τοὺς βαρβάρους τρέποιντο, ἑαυτῶν δ᾽ ἀπέχοιντο.","st":"469c"},{"sp":"N","t":"τί δέ; σκυλεύειν, ἦν δ᾽ ἐγώ, τοὺς τελευτήσαντας πλὴν ὅπλων, ἐπειδὰν νικήσωσιν, ἦ καλῶς ἔχει; ἢ οὐ πρόφασιν","st":"469c"},{"sp":"N","t":"μὲν τοῖς δειλοῖς ἔχει μὴ πρὸς τὸν μαχόμενον ἰέναι, ὥς τι τῶν δεόντων δρῶντας ὅταν περὶ τὸν τεθνεῶτα κυπτάζωσι, πολλὰ δὲ ἤδη στρατόπεδα διὰ τὴν τοιαύτην ἁρπαγὴν ἀπώλετο;","st":"469d"},{"sp":"N","t":"καὶ μάλα.","st":"469d"},{"sp":"N","t":"ἀνελεύθερον δὲ οὐ δοκεῖ καὶ φιλοχρήματον νεκρὸν συλᾶν, καὶ γυναικείας τε καὶ σμικρᾶς διανοίας τὸ πολέμιον νομίζειν τὸ σῶμα τοῦ τεθνεῶτος ἀποπταμένου τοῦ ἐχθροῦ, λελοιπότος δὲ ᾧ ἐπολέμει; ἢ οἴει τι διάφορον δρᾶν τοὺς τοῦτο","st":"469d"},{"sp":"N","t":"ποιοῦντας τῶν κυνῶν, αἳ τοῖς λίθοις οἷς ἂν βληθῶσι χαλεπαίνουσι, τοῦ βάλλοντος οὐχ ἁπτόμεναι;","st":"469e"},{"sp":"N","t":"οὐδὲ σμικρόν, ἔφη.","st":"469e"},{"sp":"N","t":"ἐατέον ἄρα τὰς νεκροσυλίας καὶ τὰς τῶν ἀναιρέσεων διακωλύσεις;","st":"469e"},{"sp":"N","t":"ἐατέον μέντοι, ἔφη, νὴ Δία.","st":"469e"},{"sp":"N","t":"οὐδὲ μήν που πρὸς τὰ ἱερὰ τὰ ὅπλα οἴσομεν ὡς ἀναθήσοντες, ἄλλως τε καὶ τὰ τῶν Ἑλλήνων, ἐάν τι ἡμῖν μέλῃ","st":"469e"},{"sp":"N","t":"τῆς πρὸς τοὺς ἄλλους Ἕλληνας εὐνοίας: μᾶλλον δὲ καὶ φοβησόμεθα μή τι μίασμα ᾖ πρὸς ἱερὸν τὰ τοιαῦτα ἀπὸ τῶν οἰκείων φέρειν, ἐὰν μή τι δὴ ὁ θεὸς ἄλλο λέγῃ.","st":"470a"},{"sp":"N","t":"ὀρθότατα, ἔφη.","st":"470a"},{"sp":"N","t":"τί δὲ γῆς τε τμήσεως τῆς Ἑλληνικῆς καὶ οἰκιῶν ἐμπρήσεως; ποῖόν τί σοι δράσουσιν οἱ στρατιῶται πρὸς τοὺς πολεμίους;","st":"470a"},{"sp":"N","t":"σοῦ, ἔφη, δόξαν ἀποφαινομένου ἡδέως ἂν ἀκούσαιμι.","st":"470a"},{"sp":"N","t":"ἐμοὶ μὲν τοίνυν, ἦν δ᾽ ἐγώ, δοκεῖ τούτων μηδέτερα ποιεῖν,","st":"470a"},{"sp":"N","t":"ἀλλὰ τὸν ἐπέτειον καρπὸν ἀφαιρεῖσθαι. καὶ ὧν ἕνεκα, βούλει σοι λέγω;","st":"470b"},{"sp":"N","t":"πάνυ γε.","st":"470b"},{"sp":"N","t":"φαίνεταί μοι, ὥσπερ καὶ ὀνομάζεται δύο ταῦτα ὀνόματα, πόλεμός τε καὶ στάσις, οὕτω καὶ εἶναι δύο, ὄντα ἐπὶ δυοῖν τινοιν διαφοραῖν. λέγω δὲ τὰ δύο τὸ μὲν οἰκεῖον καὶ συγγενές, τὸ δὲ ἀλλότριον καὶ ὀθνεῖον. ἐπὶ μὲν οὖν τῇ τοῦ οἰκείου ἔχθρᾳ στάσις κέκληται, ἐπὶ δὲ τῇ τοῦ ἀλλοτρίου πόλεμος.","st":"470b"},{"sp":"N","t":"καὶ οὐδέν γε, ἔφη, ἀπὸ τρόπου λέγεις.","st":"470b"},{"sp":"N","t":"ὅρα δὴ καὶ εἰ τόδε πρὸς τρόπου λέγω. φημὶ γὰρ τὸ μὲν Ἑλληνικὸν γένος αὐτὸ αὑτῷ οἰκεῖον εἶναι καὶ συγγενές, τῷ δὲ βαρβαρικῷ ὀθνεῖόν τε καὶ ἀλλότριον.","st":"470c"},{"sp":"N","t":"καλῶς γε, ἔφη.","st":"470c"},{"sp":"N","t":"Ἕλληνας μὲν ἄρα βαρβάροις καὶ βαρβάρους Ἕλλησι πολεμεῖν μαχομένους τε φήσομεν καὶ πολεμίους φύσει εἶναι, καὶ πόλεμον τὴν ἔχθραν ταύτην κλητέον: Ἕλληνας δὲ Ἕλλησιν, ὅταν τι τοιοῦτον δρῶσιν, φύσει μὲν φίλους εἶναι, νοσεῖν δ᾽ ἐν τῷ τοιούτῳ τὴν Ἑλλάδα καὶ στασιάζειν,","st":"470c"},{"sp":"N","t":"καὶ στάσιν τὴν τοιαύτην ἔχθραν κλητέον.","st":"470d"},{"sp":"N","t":"ἐγὼ μέν, ἔφη, συγχωρῶ οὕτω νομίζειν.","st":"470d"},{"sp":"N","t":"σκόπει δή, εἶπον, ὅτι ἐν τῇ νῦν ὁμολογουμένῃ στάσει, ὅπου ἄν τι τοιοῦτον γένηται καὶ διαστῇ πόλις, ἐὰν ἑκάτεροι ἑκατέρων τέμνωσιν ἀγροὺς καὶ οἰκίας ἐμπιμπρῶσιν, ὡς ἀλιτηριώδης τε δοκεῖ ἡ στάσις εἶναι καὶ οὐδέτεροι αὐτῶν φιλοπόλιδες — οὐ γὰρ ἄν ποτε ἐτόλμων τὴν τροφόν τε καὶ μητέρα κείρειν — ἀλλὰ μέτριον εἶναι τοὺς καρποὺς ἀφαιρεῖσθαι","st":"470d"},{"sp":"N","t":"τοῖς κρατοῦσι τῶν κρατουμένων, καὶ διανοεῖσθαι ὡς διαλλαγησομένων καὶ οὐκ ἀεὶ πολεμησόντων.","st":"470e"},{"sp":"N","t":"πολὺ γάρ, ἔφη, ἡμερωτέρων αὕτη ἡ διάνοια ἐκείνης.","st":"470e"},{"sp":"N","t":"τί δὲ δή; ἔφην: ἣν σὺ πόλιν οἰκίζεις, οὐχ Ἑλληνὶς ἔσται;","st":"470e"},{"sp":"N","t":"δεῖ γ᾽ αὐτήν, ἔφη.","st":"470e"},{"sp":"N","t":"οὐκοῦν καὶ ἀγαθοί τε καὶ ἥμεροι ἔσονται;","st":"470e"},{"sp":"N","t":"σφόδρα γε.","st":"470e"},{"sp":"N","t":"ἀλλ᾽ οὐ φιλέλληνες; οὐδὲ οἰκείαν τὴν Ἑλλάδα ἡγήσονται, οὐδὲ κοινωνήσουσιν ὧνπερ οἱ ἄλλοι ἱερῶν;","st":"470e"},{"sp":"N","t":"καὶ σφόδρα γε.","st":"470e"},{"sp":"N","t":"οὐκοῦν τὴν πρὸς τοὺς Ἕλληνας διαφοράν, ὡς οἰκείους, στάσιν ἡγήσονται καὶ οὐδὲ ὀνομάσουσιν πόλεμον;","st":"471a"},{"sp":"N","t":"οὐ γάρ.","st":"471a"},{"sp":"N","t":"καὶ ὡς διαλλαγησόμενοι ἄρα διοίσονται;","st":"471a"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"471a"},{"sp":"N","t":"εὐμενῶς δὴ σωφρονιοῦσιν, οὐκ ἐπὶ δουλείᾳ κολάζοντες οὐδ᾽ ἐπ᾽ ὀλέθρῳ, σωφρονισταὶ ὄντες, οὐ πολέμιοι.","st":"471a"},{"sp":"N","t":"οὕτως, ἔφη.","st":"471a"},{"sp":"N","t":"οὐδ᾽ ἄρα τὴν Ἑλλάδα Ἕλληνες ὄντες κεροῦσιν, οὐδὲ οἰκήσεις ἐμπρήσουσιν, οὐδὲ ὁμολογήσουσιν ἐν ἑκάστῃ πόλει πάντας ἐχθροὺς αὑτοῖς εἶναι, καὶ ἄνδρας καὶ γυναῖκας καὶ παῖδας, ἀλλ᾽ ὀλίγους ἀεὶ ἐχθροὺς τοὺς αἰτίους τῆς διαφορᾶς.","st":"471a"},{"sp":"N","t":"καὶ διὰ ταῦτα πάντα οὔτε τὴν γῆν ἐθελήσουσιν κείρειν αὐτῶν, ὡς φίλων τῶν πολλῶν, οὔτε οἰκίας ἀνατρέπειν, ἀλλὰ μέχρι τούτου ποιήσονται τὴν διαφοράν, μέχρι οὗ ἂν οἱ αἴτιοι ἀναγκασθῶσιν ὑπὸ τῶν ἀναιτίων ἀλγούντων δοῦναι δίκην.","st":"471b"},{"sp":"N","t":"ἐγὼ μέν, ἔφη, ὁμολογῶ οὕτω δεῖν πρὸς τοὺς ἐναντίους τοὺς ἡμετέρους πολίτας προσφέρεσθαι: πρὸς δὲ τοὺς βαρβάρους, ὡς νῦν οἱ Ἕλληνες πρὸς ἀλλήλους.","st":"471b"},{"sp":"N","t":"τιθῶμεν δὴ καὶ τοῦτον τὸν νόμον τοῖς φύλαξι, μήτε γῆν","st":"471b"},{"sp":"N","t":"τέμνειν μήτε οἰκίας ἐμπιμπράναι;","st":"471c"},{"sp":"N","t":"θῶμεν, ἔφη, καὶ ἔχειν γε καλῶς ταῦτά τε καὶ τὰ πρόσθεν.","st":"471c"},{"sp":"N","t":"ἀλλὰ γάρ μοι δοκεῖς, ὦ Σώκρατες, ἐάν τίς σοι τὰ τοιαῦτα ἐπιτρέπῃ λέγειν, οὐδέποτε μνησθήσεσθαι ὃ ἐν τῷ πρόσθεν παρωσάμενος πάντα ταῦτα εἴρηκας, τὸ ὡς δυνατὴ αὕτη ἡ πολιτεία γενέσθαι καὶ τίνα τρόπον ποτὲ δυνατή: ἐπεὶ ὅτι γε, εἰ γένοιτο, πάντ᾽ ἂν εἴη ἀγαθὰ πόλει ᾗ γένοιτο, καὶ ἃ σὺ παραλείπεις ἐγὼ λέγω, ὅτι καὶ τοῖς πολεμίοις","st":"471c"},{"sp":"N","t":"ἄριστ᾽ ἂν μάχοιντο τῷ ἥκιστα ἀπολείπειν ἀλλήλους, γιγνώσκοντές τε καὶ ἀνακαλοῦντες ταῦτα τὰ ὀνόματα ἑαυτούς, ἀδελφούς, πατέρας, ὑεῖς: εἰ δὲ καὶ τὸ θῆλυ συστρατεύοιτο, εἴτε καὶ ἐν τῇ αὐτῇ τάξει εἴτε καὶ ὄπισθεν ἐπιτεταγμένον, φόβων τε ἕνεκα τοῖς ἐχθροῖς καὶ εἴ ποτέ τις ἀνάγκη βοηθείας γένοιτο, οἶδ᾽ ὅτι ταύτῃ πάντῃ ἄμαχοι ἂν εἶεν: καὶ οἴκοι γε ἃ παραλείπεται ἀγαθά, ὅσα ἂν εἴη αὐτοῖς, ὁρῶ.","st":"471d"},{"sp":"N","t":"ἀλλ᾽ ὡς ἐμοῦ ὁμολογοῦντος πάντα ταῦτα ὅτι εἴη ἂν καὶ ἄλλα γε μυρία, εἰ γένοιτο ἡ πολιτεία αὕτη, μηκέτι πλείω περὶ αὐτῆς λέγε, ἀλλὰ τοῦτο αὐτὸ ἤδη πειρώμεθα ἡμᾶς αὐτοὺς πείθειν, ὡς δυνατὸν καὶ ᾗ δυνατόν, τὰ δ᾽ ἄλλα χαίρειν ἐῶμεν.","st":"471e"},{"sp":"N","t":"ἐξαίφνης γε σύ, ἦν δ᾽ ἐγώ, ὥσπερ καταδρομὴν ἐποιήσω ἐπὶ τὸν λόγον μου, καὶ οὐ συγγιγνώσκεις στραγγευομένῳ. ἴσως γὰρ οὐκ οἶσθα ὅτι μόγις μοι τὼ δύο κύματε ἐκφυγόντι νῦν τὸ μέγιστον καὶ χαλεπώτατον τῆς τρικυμίας ἐπάγεις, ὃ ἐπειδὰν ἴδῃς τε καὶ ἀκούσῃς, πάνυ συγγνώμην ἕξεις, ὅτι εἰκότως ἄρα ὤκνουν τε καὶ ἐδεδοίκη οὕτω παράδοξον λόγον λέγειν τε καὶ ἐπιχειρεῖν διασκοπεῖν.","st":"472a"},{"sp":"N","t":"ὅσῳ ἄν, ἔφη, τοιαῦτα πλείω λέγῃς, ἧττον ἀφεθήσῃ","st":"472a"},{"sp":"N","t":"ὑφ᾽ ἡμῶν πρὸς τὸ μὴ εἰπεῖν πῇ δυνατὴ γίγνεσθαι αὕτη ἡ πολιτεία. ἀλλὰ λέγε καὶ μὴ διάτριβε.","st":"472b"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, πρῶτον μὲν τόδε χρὴ ἀναμνησθῆναι, ὅτι ἡμεῖς ζητοῦντες δικαιοσύνην οἷόν ἐστι καὶ ἀδικίαν δεῦρο ἥκομεν.","st":"472b"},{"sp":"N","t":"χρή: ἀλλὰ τί τοῦτο; ἔφη.","st":"472b"},{"sp":"N","t":"οὐδέν: ἀλλ᾽ ἐὰν εὕρωμεν οἷόν ἐστι δικαιοσύνη, ἆρα καὶ ἄνδρα τὸν δίκαιον ἀξιώσομεν μηδὲν δεῖν αὐτῆς ἐκείνης διαφέρειν, ἀλλὰ πανταχῇ τοιοῦτον εἶναι οἷον δικαιοσύνη","st":"472b"},{"sp":"N","t":"ἐστίν; ἢ ἀγαπήσομεν ἐὰν ὅτι ἐγγύτατα αὐτῆς ᾖ καὶ πλεῖστα τῶν ἄλλων ἐκείνης μετέχῃ;","st":"472c"},{"sp":"N","t":"οὕτως, ἔφη: ἀγαπήσομεν.","st":"472c"},{"sp":"N","t":"παραδείγματος ἄρα ἕνεκα, ἦν δ᾽ ἐγώ, ἐζητοῦμεν αὐτό τε δικαιοσύνην οἷόν ἐστι, καὶ ἄνδρα τὸν τελέως δίκαιον εἰ γένοιτο, καὶ οἷος ἂν εἴη γενόμενος, καὶ ἀδικίαν αὖ καὶ τὸν ἀδικώτατον, ἵνα εἰς ἐκείνους ἀποβλέποντες, οἷοι ἂν ἡμῖν φαίνωνται εὐδαιμονίας τε πέρι καὶ τοῦ ἐναντίου, ἀναγκαζώμεθα καὶ περὶ ἡμῶν αὐτῶν ὁμολογεῖν, ὃς ἂν ἐκείνοις ὅτι","st":"472c"},{"sp":"N","t":"ὁμοιότατος ᾖ, τὴν ἐκείνης μοῖραν ὁμοιοτάτην ἕξειν, ἀλλ᾽ οὐ τούτου ἕνεκα, ἵν᾽ ἀποδείξωμεν ὡς δυνατὰ ταῦτα γίγνεσθαι.","st":"472d"},{"sp":"N","t":"τοῦτο μέν, ἔφη, ἀληθὲς λέγεις.","st":"472d"},{"sp":"N","t":"οἴει ἂν οὖν ἧττόν τι ἀγαθὸν ζωγράφον εἶναι ὃς ἂν γράψας παράδειγμα οἷον ἂν εἴη ὁ κάλλιστος ἄνθρωπος καὶ πάντα εἰς τὸ γράμμα ἱκανῶς ἀποδοὺς μὴ ἔχῃ ἀποδεῖξαι ὡς καὶ δυνατὸν γενέσθαι τοιοῦτον ἄνδρα;","st":"472d"},{"sp":"N","t":"μὰ Δί᾽ οὐκ ἔγωγ᾽, ἔφη.","st":"472d"},{"sp":"N","t":"τί οὖν; οὐ καὶ ἡμεῖς, φαμέν, παράδειγμα ἐποιοῦμεν","st":"472d"},{"sp":"N","t":"λόγῳ ἀγαθῆς πόλεως;","st":"472e"},{"sp":"N","t":"πάνυ γε.","st":"472e"},{"sp":"N","t":"ἧττόν τι οὖν οἴει ἡμᾶς εὖ λέγειν τούτου ἕνεκα, ἐὰν μὴ ἔχωμεν ἀποδεῖξαι ὡς δυνατὸν οὕτω πόλιν οἰκῆσαι ὡς ἐλέγετο;","st":"472e"},{"sp":"N","t":"οὐ δῆτα, ἔφη.","st":"472e"},{"sp":"N","t":"τὸ μὲν τοίνυν ἀληθές, ἦν δ᾽ ἐγώ, οὕτω: εἰ δὲ δὴ καὶ τοῦτο προθυμηθῆναι δεῖ σὴν χάριν, ἀποδεῖξαι πῇ μάλιστα καὶ κατὰ τί δυνατώτατ᾽ ἂν εἴη, πάλιν μοι πρὸς τὴν τοιαύτην ἀπόδειξιν τὰ αὐτὰ διομολόγησαι.","st":"472e"},{"sp":"N","t":"τὰ ποῖα;","st":"472e"},{"sp":"N","t":"ἆρ᾽ οἷόν τέ τι πραχθῆναι ὡς λέγεται, ἢ φύσιν ἔχει πρᾶξιν λέξεως ἧττον ἀληθείας ἐφάπτεσθαι, κἂν εἰ μή τῳ δοκεῖ; ἀλλὰ σὺ πότερον ὁμολογεῖς οὕτως ἢ οὔ;","st":"473a"},{"sp":"N","t":"ὁμολογῶ, ἔφη.","st":"473a"},{"sp":"N","t":"τοῦτο μὲν δὴ μὴ ἀνάγκαζέ με, οἷα τῷ λόγῳ διήλθομεν, τοιαῦτα παντάπασι καὶ τῷ ἔργῳ δεῖν γιγνόμενα ⟨ἂν⟩ ἀποφαίνειν: ἀλλ᾽, ἐὰν οἷοί τε γενώμεθα εὑρεῖν ὡς ἂν ἐγγύτατα τῶν εἰρημένων πόλις οἰκήσειεν, φάναι ἡμᾶς","st":"473a"},{"sp":"N","t":"ἐξηυρηκέναι ὡς δυνατὰ ταῦτα γίγνεσθαι ἃ σὺ ἐπιτάττεις. ἢ οὐκ ἀγαπήσεις τούτων τυγχάνων; ἐγὼ μὲν γὰρ ἂν ἀγαπῴην.","st":"473b"},{"sp":"N","t":"καὶ γὰρ ἐγώ, ἔφη.","st":"473b"},{"sp":"N","t":"τὸ δὲ δὴ μετὰ τοῦτο, ὡς ἔοικε, πειρώμεθα ζητεῖν τε καὶ ἀποδεικνύναι τί ποτε νῦν κακῶς ἐν ταῖς πόλεσι πράττεται δι᾽ ὃ οὐχ οὕτως οἰκοῦνται, καὶ τίνος ἂν σμικροτάτου μεταβαλόντος ἔλθοι εἰς τοῦτον τὸν τρόπον τῆς πολιτείας πόλις, μάλιστα μὲν ἑνός, εἰ δὲ μή, δυοῖν, εἰ δὲ μή, ὅτι ὀλιγίστων τὸν ἀριθμὸν καὶ σμικροτάτων τὴν δύναμιν.","st":"473b"},{"sp":"N","t":"παντάπασι μὲν οὖν, ἔφη.","st":"473c"},{"sp":"N","t":"ἑνὸς μὲν τοίνυν, ἦν δ᾽ ἐγώ, μεταβαλόντος δοκοῦμέν μοι ἔχειν δεῖξαι ὅτι μεταπέσοι ἄν, οὐ μέντοι σμικροῦ γε οὐδὲ ῥᾳδίου, δυνατοῦ δέ.","st":"473c"},{"sp":"N","t":"τίνος; ἔφη.","st":"473c"},{"sp":"N","t":"ἐπ᾽ αὐτῷ δή, ἦν δ᾽ ἐγώ, εἰμὶ ὃ τῷ μεγίστῳ προσῃκάζομεν κύματι. εἰρήσεται δ᾽ οὖν, εἰ καὶ μέλλει γέλωτί τε ἀτεχνῶς ὥσπερ κῦμα ἐκγελῶν καὶ ἀδοξίᾳ κατακλύσειν. σκόπει δὲ ὃ μέλλω λέγειν.","st":"473c"},{"sp":"N","t":"λέγε, ἔφη.","st":"473c"},{"sp":"N","t":"ἐὰν μή, ἦν δ᾽ ἐγώ, ἢ οἱ φιλόσοφοι βασιλεύσωσιν ἐν","st":"473c"},{"sp":"N","t":"ταῖς πόλεσιν ἢ οἱ βασιλῆς τε νῦν λεγόμενοι καὶ δυνάσται φιλοσοφήσωσι γνησίως τε καὶ ἱκανῶς, καὶ τοῦτο εἰς ταὐτὸν συμπέσῃ, δύναμίς τε πολιτικὴ καὶ φιλοσοφία, τῶν δὲ νῦν πορευομένων χωρὶς ἐφ᾽ ἑκάτερον αἱ πολλαὶ φύσεις ἐξ ἀνάγκης ἀποκλεισθῶσιν, οὐκ ἔστι κακῶν παῦλα, ὦ φίλε Γλαύκων, ταῖς πόλεσι, δοκῶ δ᾽ οὐδὲ τῷ ἀνθρωπίνῳ γένει,","st":"473d"},{"sp":"N","t":"οὐδὲ αὕτη ἡ πολιτεία μή ποτε πρότερον φυῇ τε εἰς τὸ δυνατὸν καὶ φῶς ἡλίου ἴδῃ, ἣν νῦν λόγῳ διεληλύθαμεν. ἀλλὰ τοῦτό ἐστιν ὃ ἐμοὶ πάλαι ὄκνον ἐντίθησι λέγειν, ὁρῶντι ὡς πολὺ παρὰ δόξαν ῥηθήσεται: χαλεπὸν γὰρ ἰδεῖν ὅτι οὐκ ἂν ἄλλη τις εὐδαιμονήσειεν οὔτε ἰδίᾳ οὔτε δημοσίᾳ.","st":"473e"},{"sp":"N","t":"καὶ ὅς, ὦ Σώκρατες, ἔφη, τοιοῦτον ἐκβέβληκας ῥῆμά τε καὶ λόγον, ὃν εἰπὼν ἡγοῦ ἐπὶ σὲ πάνυ πολλούς τε καὶ","st":"473e"},{"sp":"N","t":"οὐ φαύλους νῦν οὕτως, οἷον ῥίψαντας τὰ ἱμάτια, γυμνοὺς λαβόντας ὅτι ἑκάστῳ παρέτυχεν ὅπλον, θεῖν διατεταμένους ὡς θαυμάσια ἐργασομένους: οὓς εἰ μὴ ἀμυνῇ τῷ λόγῳ καὶ ἐκφεύξῃ, τῷ ὄντι τωθαζόμενος δώσεις δίκην.","st":"474a"},{"sp":"N","t":"οὐκοῦν σύ μοι, ἦν δ᾽ ἐγώ, τούτων αἴτιος;","st":"474a"},{"sp":"N","t":"καλῶς γ᾽, ἔφη, ἐγὼ ποιῶν. ἀλλά τοί σε οὐ προδώσω, ἀλλ᾽ ἀμυνῶ οἷς δύναμαι: δύναμαι δὲ εὐνοίᾳ τε καὶ τῷ παρακελεύεσθαι, καὶ ἴσως ἂν ἄλλου του ἐμμελέστερόν σοι","st":"474a"},{"sp":"N","t":"ἀποκρινοίμην. ἀλλ᾽ ὡς ἔχων τοιοῦτον βοηθὸν πειρῶ τοῖς ἀπιστοῦσιν ἐνδείξασθαι ὅτι ἔχει ᾗ σὺ λέγεις.","st":"474b"},{"sp":"N","t":"πειρατέον, ἦν δ᾽ ἐγώ, ἐπειδὴ καὶ σὺ οὕτω μεγάλην συμμαχίαν παρέχῃ. ἀναγκαῖον οὖν μοι δοκεῖ, εἰ μέλλομέν πῃ ἐκφεύξεσθαι οὓς λέγεις, διορίσασθαι πρὸς αὐτοὺς τοὺς φιλοσόφους τίνας λέγοντες τολμῶμεν φάναι δεῖν ἄρχειν, ἵνα διαδήλων γενομένων δύνηταί τις ἀμύνεσθαι, ἐνδεικνύμενος","st":"474b"},{"sp":"N","t":"ὅτι τοῖς μὲν προσήκει φύσει ἅπτεσθαί τε φιλοσοφίας ἡγεμονεύειν τ᾽ ἐν πόλει, τοῖς δ᾽ ἄλλοις μήτε ἅπτεσθαι ἀκολουθεῖν τε τῷ ἡγουμένῳ.","st":"474c"},{"sp":"N","t":"ὥρα ἂν εἴη, ἔφη, ὁρίζεσθαι.","st":"474c"},{"sp":"N","t":"ἴθι δή, ἀκολούθησόν μοι τῇδε, ἐὰν αὐτὸ ἁμῇ γέ πῃ ἱκανῶς ἐξηγησώμεθα.","st":"474c"},{"sp":"N","t":"ἄγε, ἔφη.","st":"474c"},{"sp":"N","t":"ἀναμιμνῄσκειν οὖν σε, ἦν δ᾽ ἐγώ, δεήσει, ἢ μέμνησαι ὅτι ὃν ἂν φῶμεν φιλεῖν τι, δεῖ φανῆναι αὐτόν, ἐὰν ὀρθῶς λέγηται, οὐ τὸ μὲν φιλοῦντα ἐκείνου, τὸ δὲ μή, ἀλλὰ πᾶν στέργοντα;","st":"474c"},{"sp":"N","t":"ἀναμιμνῄσκειν, ἔφη, ὡς ἔοικεν, δεῖ: οὐ γὰρ πάνυ γε ἐννοῶ.","st":"474d"},{"sp":"N","t":"ἄλλῳ, εἶπον, ἔπρεπεν, ὦ Γλαύκων, λέγειν ἃ λέγεις: ἀνδρὶ δ᾽ ἐρωτικῷ οὐ πρέπει ἀμνημονεῖν ὅτι πάντες οἱ ἐν ὥρᾳ τὸν φιλόπαιδα καὶ ἐρωτικὸν ἁμῇ γέ πῃ δάκνουσί τε καὶ κινοῦσι, δοκοῦντες ἄξιοι εἶναι ἐπιμελείας τε καὶ τοῦ ἀσπάζεσθαι. ἢ οὐχ οὕτω ποιεῖτε πρὸς τοὺς καλούς; ὁ μέν, ὅτι σιμός, ἐπίχαρις κληθεὶς ἐπαινεθήσεται ὑφ᾽ ὑμῶν, τοῦ δὲ τὸ γρυπὸν βασιλικόν φατε εἶναι, τὸν δὲ δὴ διὰ","st":"474d"},{"sp":"N","t":"μέσου τούτων ἐμμετρώτατα ἔχειν, μέλανας δὲ ἀνδρικοὺς ἰδεῖν, λευκοὺς δὲ θεῶν παῖδας εἶναι: μελιχλώρους δὲ καὶ τοὔνομα οἴει τινὸς ἄλλου ποίημα εἶναι ἢ ἐραστοῦ ὑποκοριζομένου τε καὶ εὐχερῶς φέροντος τὴν ὠχρότητα, ἐὰν ἐπὶ ὥρᾳ ᾖ; καὶ ἑνὶ λόγῳ πάσας προφάσεις προφασίζεσθέ τε","st":"474e"},{"sp":"N","t":"καὶ πάσας φωνὰς ἀφίετε, ὥστε μηδένα ἀποβάλλειν τῶν ἀνθούντων ἐν ὥρᾳ.","st":"475a"},{"sp":"N","t":"εἰ βούλει, ἔφη, ἐπ᾽ ἐμοῦ λέγειν περὶ τῶν ἐρωτικῶν ὅτι οὕτω ποιοῦσι, συγχωρῶ τοῦ λόγου χάριν.","st":"475a"},{"sp":"N","t":"τί δέ; ἦν δ᾽ ἐγώ: τοὺς φιλοίνους οὐ τὰ αὐτὰ ταῦτα ποιοῦντας ὁρᾷς; πάντα οἶνον ἐπὶ πάσης προφάσεως ἀσπαζομένους;","st":"475a"},{"sp":"N","t":"καὶ μάλα.","st":"475a"},{"sp":"N","t":"καὶ μὴν φιλοτίμους γε, ὡς ἐγᾦμαι, καθορᾷς ὅτι, ἂν μὴ στρατηγῆσαι δύνωνται, τριττυαρχοῦσιν, κἂν μὴ ὑπὸ μειζόνων","st":"475a"},{"sp":"N","t":"καὶ σεμνοτέρων τιμᾶσθαι, ὑπὸ σμικροτέρων καὶ φαυλοτέρων τιμώμενοι ἀγαπῶσιν, ὡς ὅλως τιμῆς ἐπιθυμηταὶ ὄντες.","st":"475b"},{"sp":"N","t":"κομιδῇ μὲν οὖν.","st":"475b"},{"sp":"N","t":"τοῦτο δὴ φάθι ἢ μή: ἆρα ὃν ἄν τινος ἐπιθυμητικὸν λέγωμεν, παντὸς τοῦ εἴδους τούτου φήσομεν ἐπιθυμεῖν, ἢ τοῦ μέν, τοῦ δὲ οὔ;","st":"475b"},{"sp":"N","t":"παντός, ἔφη.","st":"475b"},{"sp":"N","t":"οὐκοῦν καὶ τὸν φιλόσοφον σοφίας φήσομεν ἐπιθυμητὴν εἶναι, οὐ τῆς μέν, τῆς δ᾽ οὔ, ἀλλὰ πάσης;","st":"475b"},{"sp":"N","t":"ἀληθῆ.","st":"475b"},{"sp":"N","t":"τὸν ἄρα περὶ τὰ μαθήματα δυσχεραίνοντα, ἄλλως τε","st":"475b"},{"sp":"N","t":"καὶ νέον ὄντα καὶ μήπω λόγον ἔχοντα τί τε χρηστὸν καὶ μή, οὐ φήσομεν φιλομαθῆ οὐδὲ φιλόσοφον εἶναι, ὥσπερ τὸν περὶ τὰ σιτία δυσχερῆ οὔτε πεινῆν φαμεν οὔτ᾽ ἐπιθυμεῖν σιτίων, οὐδὲ φιλόσιτον ἀλλὰ κακόσιτον εἶναι.","st":"475c"},{"sp":"N","t":"καὶ ὀρθῶς γε φήσομεν.","st":"475c"},{"sp":"N","t":"τὸν δὲ δὴ εὐχερῶς ἐθέλοντα παντὸς μαθήματος γεύεσθαι καὶ ἁσμένως ἐπὶ τὸ μανθάνειν ἰόντα καὶ ἀπλήστως ἔχοντα, τοῦτον δ᾽ ἐν δίκῃ φήσομεν φιλόσοφον: ἦ γάρ;","st":"475c"},{"sp":"N","t":"καὶ ὁ Γλαύκων ἔφη: πολλοὶ ἄρα καὶ ἄτοποι ἔσονταί σοι τοιοῦτοι. οἵ τε γὰρ φιλοθεάμονες πάντες ἔμοιγε δοκοῦσι τῷ καταμανθάνειν χαίροντες τοιοῦτοι εἶναι, οἵ τε φιλήκοοι ἀτοπώτατοί τινές εἰσιν ὥς γ᾽ ἐν φιλοσόφοις τιθέναι, οἳ πρὸς μὲν λόγους καὶ τοιαύτην διατριβὴν ἑκόντες οὐκ ἂν ἐθέλοιεν ἐλθεῖν, ὥσπερ δὲ ἀπομεμισθωκότες τὰ ὦτα ἐπακοῦσαι πάντων χορῶν περιθέουσι τοῖς Διονυσίοις οὔτε τῶν κατὰ πόλεις οὔτε τῶν κατὰ κώμας ἀπολειπόμενοι. τούτους οὖν πάντας καὶ ἄλλους τοιούτων τινῶν","st":"475d"},{"sp":"N","t":"μαθητικοὺς καὶ τοὺς τῶν τεχνυδρίων φιλοσόφους φήσομεν;","st":"475e"},{"sp":"N","t":"οὐδαμῶς, εἶπον, ἀλλ᾽ ὁμοίους μὲν φιλοσόφοις.","st":"475e"},{"sp":"N","t":"τοὺς δὲ ἀληθινούς, ἔφη, τίνας λέγεις;","st":"475e"},{"sp":"N","t":"τοὺς τῆς ἀληθείας, ἦν δ᾽ ἐγώ, φιλοθεάμονας.","st":"475e"},{"sp":"N","t":"καὶ τοῦτο μέν γ᾽, ἔφη, ὀρθῶς: ἀλλὰ πῶς αὐτὸ λέγεις;","st":"475e"},{"sp":"N","t":"οὐδαμῶς, ἦν δ᾽ ἐγώ, ῥᾳδίως πρός γε ἄλλον: σὲ δὲ οἶμαι ὁμολογήσειν μοι τὸ τοιόνδε.","st":"475e"},{"sp":"N","t":"τὸ ποῖον;","st":"475e"},{"sp":"N","t":"ἐπειδή ἐστιν ἐναντίον καλὸν αἰσχρῷ, δύο αὐτὼ εἶναι.","st":"475e"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"476a"},{"sp":"N","t":"οὐκοῦν ἐπειδὴ δύο, καὶ ἓν ἑκάτερον;","st":"476a"},{"sp":"N","t":"καὶ τοῦτο.","st":"476a"},{"sp":"N","t":"καὶ περὶ δὴ δικαίου καὶ ἀδίκου καὶ ἀγαθοῦ καὶ κακοῦ καὶ πάντων τῶν εἰδῶν πέρι ὁ αὐτὸς λόγος, αὐτὸ μὲν ἓν ἕκαστον εἶναι, τῇ δὲ τῶν πράξεων καὶ σωμάτων καὶ ἀλλήλων κοινωνίᾳ πανταχοῦ φανταζόμενα πολλὰ φαίνεσθαι ἕκαστον.","st":"476a"},{"sp":"N","t":"ὀρθῶς, ἔφη, λέγεις.","st":"476a"},{"sp":"N","t":"ταύτῃ τοίνυν, ἦν δ᾽ ἐγώ, διαιρῶ, χωρὶς μὲν οὓς νυνδὴ ἔλεγες φιλοθεάμονάς τε καὶ φιλοτέχνους καὶ πρακτικούς,","st":"476a"},{"sp":"N","t":"καὶ χωρὶς αὖ περὶ ὧν ὁ λόγος, οὓς μόνους ἄν τις ὀρθῶς προσείποι φιλοσόφους.","st":"476b"},{"sp":"N","t":"πῶς, ἔφη, λέγεις;","st":"476b"},{"sp":"N","t":"οἱ μέν που, ἦν δ᾽ ἐγώ, φιλήκοοι καὶ φιλοθεάμονες τάς τε καλὰς φωνὰς ἀσπάζονται καὶ χρόας καὶ σχήματα καὶ πάντα τὰ ἐκ τῶν τοιούτων δημιουργούμενα, αὐτοῦ δὲ τοῦ καλοῦ ἀδύνατος αὐτῶν ἡ διάνοια τὴν φύσιν ἰδεῖν τε καὶ ἀσπάσασθαι.","st":"476b"},{"sp":"N","t":"ἔχει γὰρ οὖν δή, ἔφη, οὕτως.","st":"476b"},{"sp":"N","t":"οἱ δὲ δὴ ἐπ᾽ αὐτὸ τὸ καλὸν δυνατοὶ ἰέναι τε καὶ ὁρᾶν καθ᾽ αὑτὸ ἆρα οὐ σπάνιοι ἂν εἶεν;","st":"476b"},{"sp":"N","t":"καὶ μάλα.","st":"476c"},{"sp":"N","t":"ὁ οὖν καλὰ μὲν πράγματα νομίζων, αὐτὸ δὲ κάλλος μήτε νομίζων μήτε, ἄν τις ἡγῆται ἐπὶ τὴν γνῶσιν αὐτοῦ, δυνάμενος ἕπεσθαι, ὄναρ ἢ ὕπαρ δοκεῖ σοι ζῆν; σκόπει δέ. τὸ ὀνειρώττειν ἆρα οὐ τόδε ἐστίν, ἐάντε ἐν ὕπνῳ τις ἐάντ᾽ ἐγρηγορὼς τὸ ὅμοιόν τῳ μὴ ὅμοιον ἀλλ᾽ αὐτὸ ἡγῆται εἶναι ᾧ ἔοικεν;","st":"476c"},{"sp":"N","t":"ἐγὼ γοῦν ἄν, ἦ δ᾽ ὅς, φαίην ὀνειρώττειν τὸν τοιοῦτον.","st":"476c"},{"sp":"N","t":"τί δέ; ὁ τἀναντία τούτων ἡγούμενός τέ τι αὐτὸ καλὸν","st":"476c"},{"sp":"N","t":"καὶ δυνάμενος καθορᾶν καὶ αὐτὸ καὶ τὰ ἐκείνου μετέχοντα, καὶ οὔτε τὰ μετέχοντα αὐτὸ οὔτε αὐτὸ τὰ μετέχοντα ἡγούμενος, ὕπαρ ἢ ὄναρ αὖ καὶ οὗτος δοκεῖ σοι ζῆν;","st":"476d"},{"sp":"N","t":"καὶ μάλα, ἔφη, ὕπαρ.","st":"476d"},{"sp":"N","t":"οὐκοῦν τούτου μὲν τὴν διάνοιαν ὡς γιγνώσκοντος γνώμην ἂν ὀρθῶς φαῖμεν εἶναι, τοῦ δὲ δόξαν ὡς δοξάζοντος;","st":"476d"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"476d"},{"sp":"N","t":"τί οὖν ἐὰν ἡμῖν χαλεπαίνῃ οὗτος, ὅν φαμεν δοξάζειν ἀλλ᾽ οὐ γιγνώσκειν, καὶ ἀμφισβητῇ ὡς οὐκ ἀληθῆ λέγομεν;","st":"476d"},{"sp":"N","t":"ἕξομέν τι παραμυθεῖσθαι αὐτὸν καὶ πείθειν ἠρέμα, ἐπικρυπτόμενοι ὅτι οὐχ ὑγιαίνει;","st":"476e"},{"sp":"N","t":"δεῖ γέ τοι δή, ἔφη.","st":"476e"},{"sp":"N","t":"ἴθι δή, σκόπει τί ἐροῦμεν πρὸς αὐτόν. ἢ βούλει ὧδε πυνθανώμεθα παρ᾽ αὐτοῦ, λέγοντες ὡς εἴ τι οἶδεν οὐδεὶς αὐτῷ φθόνος, ἀλλ᾽ ἅσμενοι ἂν ἴδοιμεν εἰδότα τι. ἀλλ᾽ ἡμῖν εἰπὲ τόδε: ὁ γιγνώσκων γιγνώσκει τὶ ἢ οὐδέν; σὺ οὖν μοι ὑπὲρ ἐκείνου ἀποκρίνου.","st":"476e"},{"sp":"N","t":"ἀποκρινοῦμαι, ἔφη, ὅτι γιγνώσκει τί.","st":"476e"},{"sp":"N","t":"πότερον ὂν ἢ οὐκ ὄν;","st":"476e"},{"sp":"N","t":"ὄν: πῶς γὰρ ἂν μὴ ὄν γέ τι γνωσθείη;","st":"477a"},{"sp":"N","t":"ἱκανῶς οὖν τοῦτο ἔχομεν, κἂν εἰ πλεοναχῇ σκοποῖμεν, ὅτι τὸ μὲν παντελῶς ὂν παντελῶς γνωστόν, μὴ ὂν δὲ μηδαμῇ πάντῃ ἄγνωστον;","st":"477a"},{"sp":"N","t":"ἱκανώτατα.","st":"477a"},{"sp":"N","t":"εἶεν: εἰ δὲ δή τι οὕτως ἔχει ὡς εἶναί τε καὶ μὴ εἶναι, οὐ μεταξὺ ἂν κέοιτο τοῦ εἰλικρινῶς ὄντος καὶ τοῦ αὖ μηδαμῇ ὄντος;","st":"477a"},{"sp":"N","t":"μεταξύ.","st":"477a"},{"sp":"N","t":"οὐκοῦν ἐπὶ μὲν τῷ ὄντι γνῶσις ἦν, ἀγνωσία δ᾽ ἐξ ἀνάγκης ἐπὶ μὴ ὄντι, ἐπὶ δὲ τῷ μεταξὺ τούτῳ μεταξύ τι καὶ ζητητέον","st":"477a"},{"sp":"N","t":"ἀγνοίας τε καὶ ἐπιστήμης, εἴ τι τυγχάνει ὂν τοιοῦτον;","st":"477b"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"477b"},{"sp":"N","t":"ἆρ᾽ οὖν λέγομέν τι δόξαν εἶναι;","st":"477b"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"477b"},{"sp":"N","t":"πότερον ἄλλην δύναμιν ἐπιστήμης ἢ τὴν αὐτήν;","st":"477b"},{"sp":"N","t":"ἄλλην.","st":"477b"},{"sp":"N","t":"ἐπ᾽ ἄλλῳ ἄρα τέτακται δόξα καὶ ἐπ᾽ ἄλλῳ ἐπιστήμη, κατὰ τὴν δύναμιν ἑκατέρα τὴν αὑτῆς.","st":"477b"},{"sp":"N","t":"οὕτω.","st":"477b"},{"sp":"N","t":"οὐκοῦν ἐπιστήμη μὲν ἐπὶ τῷ ὄντι πέφυκε, γνῶναι ὡς ἔστι τὸ ὄν; -μᾶλλον δὲ ὧδέ μοι δοκεῖ πρότερον ἀναγκαῖον εἶναι διελέσθαι.","st":"477b"},{"sp":"N","t":"πῶς;","st":"477b"},{"sp":"N","t":"φήσομεν δυνάμεις εἶναι γένος τι τῶν ὄντων, αἷς δὴ καὶ ἡμεῖς δυνάμεθα ἃ δυνάμεθα καὶ ἄλλο πᾶν ὅτι περ ἂν δύνηται, οἷον λέγω ὄψιν καὶ ἀκοὴν τῶν δυνάμεων εἶναι, εἰ ἄρα μανθάνεις ὃ βούλομαι λέγειν τὸ εἶδος.","st":"477c"},{"sp":"N","t":"ἀλλὰ μανθάνω, ἔφη.","st":"477c"},{"sp":"N","t":"ἄκουσον δὴ ὅ μοι φαίνεται περὶ αὐτῶν. δυνάμεως γὰρ ἐγὼ οὔτε τινὰ χρόαν ὁρῶ οὔτε σχῆμα οὔτε τι τῶν τοιούτων οἷον καὶ ἄλλων πολλῶν, πρὸς ἃ ἀποβλέπων ἔνια διορίζομαι παρ᾽ ἐμαυτῷ τὰ μὲν ἄλλα εἶναι, τὰ δὲ ἄλλα: δυνάμεως","st":"477c"},{"sp":"N","t":"δ᾽ εἰς ἐκεῖνο μόνον βλέπω ἐφ᾽ ᾧ τε ἔστι καὶ ὃ ἀπεργάζεται, καὶ ταύτῃ ἑκάστην αὐτῶν δύναμιν ἐκάλεσα, καὶ τὴν μὲν ἐπὶ τῷ αὐτῷ τεταγμένην καὶ τὸ αὐτὸ ἀπεργαζομένην τὴν αὐτὴν καλῶ, τὴν δὲ ἐπὶ ἑτέρῳ καὶ ἕτερον ἀπεργαζομένην ἄλλην. τί δὲ σύ; πῶς ποιεῖς;","st":"477d"},{"sp":"N","t":"οὕτως, ἔφη.","st":"477d"},{"sp":"N","t":"δεῦρο δὴ πάλιν, ἦν δ᾽ ἐγώ, ὦ ἄριστε. ἐπιστήμην πότερον δύναμίν τινα φῂς εἶναι αὐτήν, ἢ εἰς τί γένος τιθεῖς;","st":"477d"},{"sp":"N","t":"εἰς τοῦτο, ἔφη, πασῶν γε δυνάμεων ἐρρωμενεστάτην.","st":"477d"},{"sp":"N","t":"τί δέ, δόξαν εἰς δύναμιν ἢ εἰς ἄλλο εἶδος οἴσομεν;","st":"477e"},{"sp":"N","t":"οὐδαμῶς, ἔφη: ᾧ γὰρ δοξάζειν δυνάμεθα, οὐκ ἄλλο τι ἢ δόξα ἐστίν.","st":"477e"},{"sp":"N","t":"ἀλλὰ μὲν δὴ ὀλίγον γε πρότερον ὡμολόγεις μὴ τὸ αὐτὸ εἶναι ἐπιστήμην τε καὶ δόξαν.","st":"477e"},{"sp":"N","t":"πῶς γὰρ ἄν, ἔφη, τό γε ἀναμάρτητον τῷ μὴ ἀναμαρτήτῳ ταὐτόν τις νοῦν ἔχων τιθείη;","st":"477e"},{"sp":"N","t":"καλῶς, ἦν δ᾽ ἐγώ, καὶ δῆλον ὅτι ἕτερον ἐπιστήμης δόξα","st":"477e"},{"sp":"N","t":"ὁμολογεῖται ἡμῖν.","st":"478a"},{"sp":"N","t":"ἕτερον.","st":"478a"},{"sp":"N","t":"ἐφ᾽ ἑτέρῳ ἄρα ἕτερόν τι δυναμένη ἑκατέρα αὐτῶν πέφυκεν;","st":"478a"},{"sp":"N","t":"ἀνάγκη.","st":"478a"},{"sp":"N","t":"ἐπιστήμη μέν γέ που ἐπὶ τῷ ὄντι, τὸ ὂν γνῶναι ὡς ἔχει;","st":"478a"},{"sp":"N","t":"ναί.","st":"478a"},{"sp":"N","t":"δόξα δέ, φαμέν, δοξάζειν;","st":"478a"},{"sp":"N","t":"ναί.","st":"478a"},{"sp":"N","t":"ἦ ταὐτὸν ὅπερ ἐπιστήμη γιγνώσκει; καὶ ἔσται γνωστόν τε καὶ δοξαστὸν τὸ αὐτό; ἢ ἀδύνατον;","st":"478a"},{"sp":"N","t":"ἀδύνατον, ἔφη, ἐκ τῶν ὡμολογημένων: εἴπερ ἐπ᾽ ἄλλῳ ἄλλη δύναμις πέφυκεν, δυνάμεις δὲ ἀμφότεραί ἐστον, δόξα τε","st":"478a"},{"sp":"N","t":"καὶ ἐπιστήμη, ἄλλη δὲ ἑκατέρα, ὥς φαμεν, ἐκ τούτων δὴ οὐκ ἐγχωρεῖ γνωστὸν καὶ δοξαστὸν ταὐτὸν εἶναι.","st":"478b"},{"sp":"N","t":"οὐκοῦν εἰ τὸ ὂν γνωστόν, ἄλλο τι ἂν δοξαστὸν ἢ τὸ ὂν εἴη;","st":"478b"},{"sp":"N","t":"ἄλλο.","st":"478b"},{"sp":"N","t":"ἆρ᾽ οὖν τὸ μὴ ὂν δοξάζει; ἢ ἀδύνατον καὶ δοξάσαι τό γε μὴ ὄν; ἐννόει δέ. οὐχ ὁ δοξάζων ἐπὶ τὶ φέρει τὴν δόξαν; ἢ οἷόν τε αὖ δοξάζειν μέν, δοξάζειν δὲ μηδέν;","st":"478b"},{"sp":"N","t":"ἀδύνατον.","st":"478b"},{"sp":"N","t":"ἀλλ᾽ ἕν γέ τι δοξάζει ὁ δοξάζων;","st":"478b"},{"sp":"N","t":"ναί.","st":"478b"},{"sp":"N","t":"ἀλλὰ μὴν μὴ ὄν γε οὐχ ἕν τι ἀλλὰ μηδὲν ὀρθότατ᾽ ἂν","st":"478b"},{"sp":"N","t":"προσαγορεύοιτο;","st":"478c"},{"sp":"N","t":"πάνυ γε.","st":"478c"},{"sp":"N","t":"μὴ ὄντι μὴν ἄγνοιαν ἐξ ἀνάγκης ἀπέδομεν, ὄντι δὲ γνῶσιν;","st":"478c"},{"sp":"N","t":"ὀρθῶς, ἔφη.","st":"478c"},{"sp":"N","t":"οὐκ ἄρα ὂν οὐδὲ μὴ ὂν δοξάζει;","st":"478c"},{"sp":"N","t":"οὐ γάρ.","st":"478c"},{"sp":"N","t":"οὔτε ἄρα ἄγνοια οὔτε γνῶσις δόξα ἂν εἴη;","st":"478c"},{"sp":"N","t":"οὐκ ἔοικεν.","st":"478c"},{"sp":"N","t":"ἄρ᾽ οὖν ἐκτὸς τούτων ἐστίν, ὑπερβαίνουσα ἢ γνῶσιν σαφηνείᾳ ἢ ἄγνοιαν ἀσαφείᾳ;","st":"478c"},{"sp":"N","t":"οὐδέτερα.","st":"478c"},{"sp":"N","t":"ἀλλ᾽ ἆρα, ἦν δ᾽ ἐγώ, γνώσεως μέν σοι φαίνεται δόξα σκοτωδέστερον, ἀγνοίας δὲ φανότερον;","st":"478c"},{"sp":"N","t":"καὶ πολύ γε, ἔφη.","st":"478c"},{"sp":"N","t":"ἐντὸς δ᾽ ἀμφοῖν κεῖται;","st":"478d"},{"sp":"N","t":"ναί.","st":"478d"},{"sp":"N","t":"μεταξὺ ἄρα ἂν εἴη τούτοιν δόξα.","st":"478d"},{"sp":"N","t":"κομιδῇ μὲν οὖν.","st":"478d"},{"sp":"N","t":"οὐκοῦν ἔφαμεν ἐν τοῖς πρόσθεν, εἴ τι φανείη οἷον ἅμα ὄν τε καὶ μὴ ὄν, τὸ τοιοῦτον μεταξὺ κεῖσθαι τοῦ εἰλικρινῶς ὄντος τε καὶ τοῦ πάντως μὴ ὄντος, καὶ οὔτε ἐπιστήμην οὔτε ἄγνοιαν ἐπ᾽ αὐτῷ ἔσεσθαι, ἀλλὰ τὸ μεταξὺ αὖ φανὲν ἀγνοίας καὶ ἐπιστήμης;","st":"478d"},{"sp":"N","t":"ὀρθῶς.","st":"478d"},{"sp":"N","t":"νῦν δέ γε πέφανται μεταξὺ τούτοιν ὃ δὴ καλοῦμεν δόξαν;","st":"478d"},{"sp":"N","t":"πέφανται.","st":"478d"},{"sp":"N","t":"ἐκεῖνο δὴ λείποιτ᾽ ἂν ἡμῖν εὑρεῖν, ὡς ἔοικε, τὸ ἀμφοτέρων μετέχον, τοῦ εἶναί τε καὶ μὴ εἶναι, καὶ οὐδέτερον εἰλικρινὲς ὀρθῶς ἂν προσαγορευόμενον, ἵνα, ἐὰν φανῇ, δοξαστὸν αὐτὸ εἶναι ἐν δίκῃ προσαγορεύωμεν, τοῖς μὲν ἄκροις τὰ ἄκρα, τοῖς δὲ μεταξὺ τὰ μεταξὺ ἀποδιδόντες. ἢ οὐχ οὕτως;","st":"478e"},{"sp":"N","t":"οὕτω.","st":"478e"},{"sp":"N","t":"τούτων δὴ ὑποκειμένων λεγέτω μοι, φήσω, καὶ ἀποκρινέσθω","st":"478e"},{"sp":"N","t":"ὁ χρηστὸς ὃς αὐτὸ μὲν καλὸν καὶ ἰδέαν τινὰ αὐτοῦ κάλλους μηδεμίαν ἡγεῖται ἀεὶ μὲν κατὰ ταὐτὰ ὡσαύτως ἔχουσαν, πολλὰ δὲ τὰ καλὰ νομίζει, ἐκεῖνος ὁ φιλοθεάμων καὶ οὐδαμῇ ἀνεχόμενος ἄν τις ἓν τὸ καλὸν φῇ εἶναι καὶ δίκαιον καὶ τἆλλα οὕτω. “τούτων γὰρ δή, ὦ ἄριστε, φήσομεν, τῶν πολλῶν καλῶν μῶν τι ἔστιν ὃ οὐκ αἰσχρὸν φανήσεται; καὶ τῶν δικαίων, ὃ οὐκ ἄδικον; καὶ τῶν ὁσίων, ὃ οὐκ ἀνόσιον;”","st":"479a"},{"sp":"N","t":"οὔκ, ἀλλ᾽ ἀνάγκη, ἔφη, καὶ καλά πως αὐτὰ καὶ αἰσχρὰ φανῆναι, καὶ ὅσα ἄλλα ἐρωτᾷς.","st":"479b"},{"sp":"N","t":"τί δὲ τὰ πολλὰ διπλάσια; ἧττόν τι ἡμίσεα ἢ διπλάσια φαίνεται;","st":"479b"},{"sp":"N","t":"οὐδέν.","st":"479b"},{"sp":"N","t":"καὶ μεγάλα δὴ καὶ σμικρὰ καὶ κοῦφα καὶ βαρέα μή τι μᾶλλον ἃ ἂν φήσωμεν, ταῦτα προσρηθήσεται ἢ τἀναντία;","st":"479b"},{"sp":"N","t":"οὔκ, ἀλλ᾽ ἀεί, ἔφη, ἕκαστον ἀμφοτέρων ἕξεται.","st":"479b"},{"sp":"N","t":"πότερον οὖν ἔστι μᾶλλον ἢ οὐκ ἔστιν ἕκαστον τῶν πολλῶν τοῦτο ὃ ἄν τις φῇ αὐτὸ εἶναι;","st":"479b"},{"sp":"N","t":"τοῖς ἐν ταῖς ἑστιάσεσιν, ἔφη, ἐπαμφοτερίζουσιν ἔοικεν,","st":"479b"},{"sp":"N","t":"καὶ τῷ τῶν παίδων αἰνίγματι τῷ περὶ τοῦ εὐνούχου, τῆς βολῆς πέρι τῆς νυκτερίδος, ᾧ καὶ ἐφ᾽ οὗ αὐτὸν αὐτὴν αἰνίττονται βαλεῖν: καὶ γὰρ ταῦτα ἐπαμφοτερίζειν, καὶ οὔτ᾽ εἶναι οὔτε μὴ εἶναι οὐδὲν αὐτῶν δυνατὸν παγίως νοῆσαι, οὔτε ἀμφότερα οὔτε οὐδέτερον.","st":"479c"},{"sp":"N","t":"ἔχεις οὖν αὐτοῖς, ἦν δ᾽ ἐγώ, ὅτι χρήσῃ, ἢ ὅποι θήσεις καλλίω θέσιν τῆς μεταξὺ οὐσίας τε καὶ τοῦ μὴ εἶναι; οὔτε γάρ που σκοτωδέστερα μὴ ὄντος πρὸς τὸ μᾶλλον μὴ εἶναι","st":"479c"},{"sp":"N","t":"φανήσεται, οὔτε φανότερα ὄντος πρὸς τὸ μᾶλλον εἶναι.","st":"479d"},{"sp":"N","t":"ἀληθέστατα, ἔφη.","st":"479d"},{"sp":"N","t":"ηὑρήκαμεν ἄρα, ὡς ἔοικεν, ὅτι τὰ τῶν πολλῶν πολλὰ νόμιμα καλοῦ τε πέρι καὶ τῶν ἄλλων μεταξύ που κυλινδεῖται τοῦ τε μὴ ὄντος καὶ τοῦ ὄντος εἰλικρινῶς.","st":"479d"},{"sp":"N","t":"ηὑρήκαμεν.","st":"479d"},{"sp":"N","t":"προωμολογήσαμεν δέ γε, εἴ τι τοιοῦτον φανείη, δοξαστὸν αὐτὸ ἀλλ᾽ οὐ γνωστὸν δεῖν λέγεσθαι, τῇ μεταξὺ δυνάμει τὸ μεταξὺ πλανητὸν ἁλισκόμενον.","st":"479d"},{"sp":"N","t":"ὡμολογήκαμεν.","st":"479d"},{"sp":"N","t":"τοὺς ἄρα πολλὰ καλὰ θεωμένους, αὐτὸ δὲ τὸ καλὸν μὴ ὁρῶντας μηδ᾽ ἄλλῳ ἐπ᾽ αὐτὸ ἄγοντι δυναμένους ἕπεσθαι, καὶ πολλὰ δίκαια, αὐτὸ δὲ τὸ δίκαιον μή, καὶ πάντα οὕτω, δοξάζειν φήσομεν ἅπαντα, γιγνώσκειν δὲ ὧν δοξάζουσιν οὐδέν.","st":"479e"},{"sp":"N","t":"ἀνάγκη, ἔφη.","st":"479e"},{"sp":"N","t":"τί δὲ αὖ τοὺς αὐτὰ ἕκαστα θεωμένους καὶ ἀεὶ κατὰ ταὐτὰ ὡσαύτως ὄντα; ἆρ᾽ οὐ γιγνώσκειν ἀλλ᾽ οὐ δοξάζειν;","st":"479e"},{"sp":"N","t":"ἀνάγκη καὶ ταῦτα.","st":"479e"},{"sp":"N","t":"οὐκοῦν καὶ ἀσπάζεσθαί τε καὶ φιλεῖν τούτους μὲν ταῦτα","st":"479e"},{"sp":"N","t":"φήσομεν ἐφ᾽ οἷς γνῶσίς ἐστιν, ἐκείνους δὲ ἐφ᾽ οἷς δόξα; ἢ οὐ μνημονεύομεν ὅτι φωνάς τε καὶ χρόας καλὰς καὶ τὰ τοιαῦτ᾽ ἔφαμεν τούτους φιλεῖν τε καὶ θεᾶσθαι, αὐτὸ δὲ τὸ καλὸν οὐδ᾽ ἀνέχεσθαι ὥς τι ὄν;","st":"480a"},{"sp":"N","t":"μεμνήμεθα.","st":"480a"},{"sp":"N","t":"μὴ οὖν τι πλημμελήσομεν φιλοδόξους καλοῦντες αὐτοὺς μᾶλλον ἢ φιλοσόφους; καὶ ἆρα ἡμῖν σφόδρα χαλεπανοῦσιν ἂν οὕτω λέγωμεν;","st":"480a"},{"sp":"N","t":"οὔκ, ἄν γέ μοι πείθωνται, ἔφη: τῷ γὰρ ἀληθεῖ χαλεπαίνειν οὐ θέμις.","st":"480a"},{"sp":"N","t":"τοὺς αὐτὸ ἄρα ἕκαστον τὸ ὂν ἀσπαζομένους φιλοσόφους ἀλλ᾽ οὐ φιλοδόξους κλητέον;","st":"480a"},{"sp":"N","t":"παντάπασι μὲν οὖν.","st":"480a"},{"sp":"N","t":"ΣΩΚΡΆΤΗς, ΓΛΑΎΚΩΝ","st":"480a"},{"sp":"N","t":"οἱ μὲν δὴ φιλόσοφοι, ἦν δ᾽ ἐγώ, ὦ Γλαύκων, καὶ οἱ μὴ διὰ μακροῦ τινος διεξελθόντες λόγου μόγις πως ἀνεφάνησαν οἵ εἰσιν ἑκάτεροι.","st":"484a"},{"sp":"N","t":"ἴσως γάρ, ἔφη, διὰ βραχέος οὐ ῥᾴδιον.","st":"484a"},{"sp":"N","t":"οὐ φαίνεται, εἶπον: ἐμοὶ γοῦν ἔτι δοκεῖ ἂν βελτιόνως φανῆναι εἰ περὶ τούτου μόνου ἔδει ῥηθῆναι, καὶ μὴ πολλὰ τὰ λοιπὰ διελθεῖν μέλλοντι κατόψεσθαι τί διαφέρει βίος","st":"484a"},{"sp":"N","t":"δίκαιος ἀδίκου.","st":"484b"},{"sp":"N","t":"τί οὖν, ἔφη, τὸ μετὰ τοῦτο ἡμῖν;","st":"484b"},{"sp":"N","t":"τί δ᾽ ἄλλο, ἦν δ᾽ ἐγώ, ἢ τὸ ἑξῆς; ἐπειδὴ φιλόσοφοι μὲν οἱ τοῦ ἀεὶ κατὰ ταὐτὰ ὡσαύτως ἔχοντος δυνάμενοι ἐφάπτεσθαι, οἱ δὲ μὴ ἀλλ᾽ ἐν πολλοῖς καὶ παντοίως ἴσχουσιν πλανώμενοι οὐ φιλόσοφοι, ποτέρους δὴ δεῖ πόλεως ἡγεμόνας εἶναι;","st":"484b"},{"sp":"N","t":"πῶς οὖν λέγοντες ἂν αὐτό, ἔφη, μετρίως λέγοιμεν;","st":"484b"},{"sp":"N","t":"ὁπότεροι ἄν, ἦν δ᾽ ἐγώ, δυνατοὶ φαίνωνται φυλάξαι νόμους τε καὶ ἐπιτηδεύματα πόλεων, τούτους καθιστάναι","st":"484b"},{"sp":"N","t":"φύλακας.","st":"484c"},{"sp":"N","t":"ὀρθῶς, ἔφη.","st":"484c"},{"sp":"N","t":"τόδε δέ, ἦν δ᾽ ἐγώ, ἆρα δῆλον, εἴτε τυφλὸν εἴτε ὀξὺ ὁρῶντα χρὴ φύλακα τηρεῖν ὁτιοῦν;","st":"484c"},{"sp":"N","t":"καὶ πῶς, ἔφη, οὐ δῆλον;","st":"484c"},{"sp":"N","t":"ἦ οὖν δοκοῦσί τι τυφλῶν διαφέρειν οἱ τῷ ὄντι τοῦ ὄντος ἑκάστου ἐστερημένοι τῆς γνώσεως, καὶ μηδὲν ἐναργὲς ἐν τῇ ψυχῇ ἔχοντες παράδειγμα, μηδὲ δυνάμενοι ὥσπερ γραφῆς εἰς τὸ ἀληθέστατον ἀποβλέποντες κἀκεῖσε ἀεὶ ἀναφέροντές τε","st":"484c"},{"sp":"N","t":"καὶ θεώμενοι ὡς οἷόν τε ἀκριβέστατα, οὕτω δὴ καὶ τὰ ἐνθάδε νόμιμα καλῶν τε πέρι καὶ δικαίων καὶ ἀγαθῶν τίθεσθαί τε, ἐὰν δέῃ τίθεσθαι, καὶ τὰ κείμενα φυλάττοντες σῴζειν;","st":"484d"},{"sp":"N","t":"οὐ μὰ τὸν Δία, ἦ δ᾽ ὅς, οὐ πολύ τι διαφέρει.","st":"484d"},{"sp":"N","t":"τούτους οὖν μᾶλλον φύλακας στησόμεθα ἢ τοὺς ἐγνωκότας μὲν ἕκαστον τὸ ὄν, ἐμπειρίᾳ δὲ μηδὲν ἐκείνων ἐλλείποντας μηδ᾽ ἐν ἄλλῳ μηδενὶ μέρει ἀρετῆς ὑστεροῦντας;","st":"484d"},{"sp":"N","t":"ἄτοπον μεντἄν, ἔφη, εἴη ἄλλους αἱρεῖσθαι, εἴ γε τἆλλα μὴ ἐλλείποιντο: τούτῳ γὰρ αὐτῷ σχεδόν τι τῷ μεγίστῳ ἂν προέχοιεν.","st":"484d"},{"sp":"N","t":"οὐκοῦν τοῦτο δὴ λέγωμεν, τίνα τρόπον οἷοί τ᾽ ἔσονται οἱ αὐτοὶ κἀκεῖνα καὶ ταῦτα ἔχειν;","st":"485a"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"485a"},{"sp":"N","t":"ὃ τοίνυν ἀρχόμενοι τούτου τοῦ λόγου ἐλέγομεν, τὴν φύσιν αὐτῶν πρῶτον δεῖ καταμαθεῖν: καὶ οἶμαι, ἐὰν ἐκείνην ἱκανῶς ὁμολογήσωμεν, ὁμολογήσειν καὶ ὅτι οἷοί τε ταῦτα ἔχειν οἱ αὐτοί, ὅτι τε οὐκ ἄλλους πόλεων ἡγεμόνας δεῖ εἶναι ἢ τούτους.","st":"485a"},{"sp":"N","t":"πῶς;","st":"485a"},{"sp":"N","t":"τοῦτο μὲν δὴ τῶν φιλοσόφων φύσεων πέρι ὡμολογήσθω","st":"485a"},{"sp":"N","t":"ἡμῖν ὅτι μαθήματός γε ἀεὶ ἐρῶσιν ὃ ἂν αὐτοῖς δηλοῖ ἐκείνης τῆς οὐσίας τῆς ἀεὶ οὔσης καὶ μὴ πλανωμένης ὑπὸ γενέσεως καὶ φθορᾶς.","st":"485b"},{"sp":"N","t":"ὡμολογήσθω.","st":"485b"},{"sp":"N","t":"καὶ μήν, ἦν δ᾽ ἐγώ, καὶ ὅτι πάσης αὐτῆς, καὶ οὔτε σμικροῦ οὔτε μείζονος οὔτε τιμιωτέρου οὔτε ἀτιμοτέρου μέρους ἑκόντες ἀφίενται, ὥσπερ ἐν τοῖς πρόσθεν περί τε τῶν φιλοτίμων καὶ ἐρωτικῶν διήλθομεν.","st":"485b"},{"sp":"N","t":"ὀρθῶς, ἔφη, λέγεις.","st":"485b"},{"sp":"N","t":"τόδε τοίνυν μετὰ τοῦτο σκόπει εἰ ἀνάγκη ἔχειν πρὸς","st":"485b"},{"sp":"N","t":"τούτῳ ἐν τῇ φύσει οἳ ἂν μέλλωσιν ἔσεσθαι οἵους ἐλέγομεν.","st":"485c"},{"sp":"N","t":"τὸ ποῖον;","st":"485c"},{"sp":"N","t":"τὴν ἀψεύδειαν καὶ τὸ ἑκόντας εἶναι μηδαμῇ προσδέχεσθαι τὸ ψεῦδος ἀλλὰ μισεῖν, τὴν δ᾽ ἀλήθειαν στέργειν.","st":"485c"},{"sp":"N","t":"εἰκός γ᾽, ἔφη.","st":"485c"},{"sp":"N","t":"οὐ μόνον γε, ὦ φίλε, εἰκός, ἀλλὰ καὶ πᾶσα ἀνάγκη τὸν ἐρωτικῶς του φύσει ἔχοντα πᾶν τὸ συγγενές τε καὶ οἰκεῖον τῶν παιδικῶν ἀγαπᾶν.","st":"485c"},{"sp":"N","t":"ὀρθῶς, ἔφη.","st":"485c"},{"sp":"N","t":"ἦ οὖν οἰκειότερον σοφίᾳ τι ἀληθείας ἂν εὕροις;","st":"485c"},{"sp":"N","t":"καὶ πῶς; ἦ δ᾽ ὅς.","st":"485c"},{"sp":"N","t":"ἦ οὖν δυνατὸν εἶναι τὴν αὐτὴν φύσιν φιλόσοφόν τε καὶ","st":"485c"},{"sp":"N","t":"φιλοψευδῆ;","st":"485d"},{"sp":"N","t":"οὐδαμῶς γε.","st":"485d"},{"sp":"N","t":"τὸν ἄρα τῷ ὄντι φιλομαθῆ πάσης ἀληθείας δεῖ εὐθὺς ἐκ νέου ὅτι μάλιστα ὀρέγεσθαι.","st":"485d"},{"sp":"N","t":"παντελῶς γε.","st":"485d"},{"sp":"N","t":"ἀλλὰ μὴν ὅτῳ γε εἰς ἕν τι αἱ ἐπιθυμίαι σφόδρα ῥέπουσιν, ἴσμεν που ὅτι εἰς τἆλλα τούτῳ ἀσθενέστεραι, ὥσπερ ῥεῦμα ἐκεῖσε ἀπωχετευμένον.","st":"485d"},{"sp":"N","t":"τί μήν;","st":"485d"},{"sp":"N","t":"ὧι δὴ πρὸς τὰ μαθήματα καὶ πᾶν τὸ τοιοῦτον ἐρρυήκασιν, περὶ τὴν τῆς ψυχῆς οἶμαι ἡδονὴν αὐτῆς καθ᾽ αὑτὴν εἶεν ἄν, τὰς δὲ διὰ τοῦ σώματος ἐκλείποιεν, εἰ μὴ πεπλασμένως ἀλλ᾽","st":"485d"},{"sp":"N","t":"ἀληθῶς φιλόσοφός τις εἴη.","st":"485e"},{"sp":"N","t":"μεγάλη ἀνάγκη.","st":"485e"},{"sp":"N","t":"σώφρων μὴν ὅ γε τοιοῦτος καὶ οὐδαμῇ φιλοχρήματος: ὧν γὰρ ἕνεκα χρήματα μετὰ πολλῆς δαπάνης σπουδάζεται, ἄλλῳ τινὶ μᾶλλον ἢ τούτῳ προσήκει σπουδάζειν.","st":"485e"},{"sp":"N","t":"οὕτω.","st":"485e"},{"sp":"N","t":"καὶ μήν που καὶ τόδε δεῖ σκοπεῖν, ὅταν κρίνειν μέλλῃς φύσιν φιλόσοφόν τε καὶ μή.","st":"486a"},{"sp":"N","t":"τὸ ποῖον;","st":"486a"},{"sp":"N","t":"μή σε λάθῃ μετέχουσα ἀνελευθερίας: ἐναντιώτατον γάρ που σμικρολογία ψυχῇ μελλούσῃ τοῦ ὅλου καὶ παντὸς ἀεὶ ἐπορέξεσθαι θείου τε καὶ ἀνθρωπίνου.","st":"486a"},{"sp":"N","t":"ἀληθέστατα, ἔφη.","st":"486a"},{"sp":"N","t":"ἧι οὖν ὑπάρχει διανοίᾳ μεγαλοπρέπεια καὶ θεωρία παντὸς μὲν χρόνου, πάσης δὲ οὐσίας, οἷόν τε οἴει τούτῳ μέγα τι δοκεῖν εἶναι τὸν ἀνθρώπινον βίον;","st":"486a"},{"sp":"N","t":"ἀδύνατον, ἦ δ᾽ ὅς.","st":"486a"},{"sp":"N","t":"οὐκοῦν καὶ θάνατον οὐ δεινόν τι ἡγήσεται ὁ τοιοῦτος;","st":"486b"},{"sp":"N","t":"ἥκιστά γε.","st":"486b"},{"sp":"N","t":"δειλῇ δὴ καὶ ἀνελευθέρῳ φύσει φιλοσοφίας ἀληθινῆς, ὡς ἔοικεν, οὐκ ἂν μετείη.","st":"486b"},{"sp":"N","t":"οὔ μοι δοκεῖ.","st":"486b"},{"sp":"N","t":"τί οὖν; ὁ κόσμιος καὶ μὴ φιλοχρήματος μηδ᾽ ἀνελεύθερος μηδ᾽ ἀλαζὼν μηδὲ δειλὸς ἔσθ᾽ ὅπῃ ἂν δυσσύμβολος ἢ ἄδικος γένοιτο;","st":"486b"},{"sp":"N","t":"οὐκ ἔστιν.","st":"486b"},{"sp":"N","t":"καὶ τοῦτο δὴ ψυχὴν σκοπῶν φιλόσοφον καὶ μὴ εὐθὺς νέου ὄντος ἐπισκέψῃ, εἰ ἄρα δικαία τε καὶ ἥμερος ἢ δυσκοινώνητος καὶ ἀγρία.","st":"486b"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"486b"},{"sp":"N","t":"οὐ μὴν οὐδὲ τόδε παραλείψεις, ὡς ἐγᾦμαι.","st":"486c"},{"sp":"N","t":"τὸ ποῖον;","st":"486c"},{"sp":"N","t":"εὐμαθὴς ἢ δυσμαθής. ἢ προσδοκᾷς ποτέ τινά τι ἱκανῶς ἂν στέρξαι, ὃ πράττων ἂν ἀλγῶν τε πράττοι καὶ μόγις σμικρὸν ἀνύτων;","st":"486c"},{"sp":"N","t":"οὐκ ἂν γένοιτο.","st":"486c"},{"sp":"N","t":"τί δ᾽ εἰ μηδὲν ὧν μάθοι σῴζειν δύναιτο, λήθης ὢν πλέως; ἆρ᾽ ἂν οἷός τ᾽ εἴη ἐπιστήμης μὴ κενὸς εἶναι;","st":"486c"},{"sp":"N","t":"καὶ πῶς;","st":"486c"},{"sp":"N","t":"ἀνόνητα δὴ πονῶν οὐκ οἴει ἀναγκασθήσεται τελευτῶν αὑτόν τε μισεῖν καὶ τὴν τοιαύτην πρᾶξιν;","st":"486c"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"486c"},{"sp":"N","t":"ἐπιλήσμονα ἄρα ψυχὴν ἐν ταῖς ἱκανῶς φιλοσόφοις μή ποτε ἐγκρίνωμεν, ἀλλὰ μνημονικὴν αὐτὴν ζητῶμεν δεῖν εἶναι.","st":"486d"},{"sp":"N","t":"παντάπασι μὲν οὖν.","st":"486d"},{"sp":"N","t":"ἀλλ᾽ οὐ μὴν τό γε τῆς ἀμούσου τε καὶ ἀσχήμονος φύσεως ἄλλοσέ ποι ἂν φαῖμεν ἕλκειν ἢ εἰς ἀμετρίαν.","st":"486d"},{"sp":"N","t":"τί μήν;","st":"486d"},{"sp":"N","t":"ἀλήθειαν δ᾽ ἀμετρίᾳ ἡγῇ συγγενῆ εἶναι ἢ ἐμμετρίᾳ;","st":"486d"},{"sp":"N","t":"ἐμμετρίᾳ.","st":"486d"},{"sp":"N","t":"ἔμμετρον ἄρα καὶ εὔχαριν ζητῶμεν πρὸς τοῖς ἄλλοις διάνοιαν φύσει, ἣν ἐπὶ τὴν τοῦ ὄντος ἰδέαν ἑκάστου τὸ αὐτοφυὲς εὐάγωγον παρέξει.","st":"486d"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"486d"},{"sp":"N","t":"τί οὖν; μή πῃ δοκοῦμέν σοι οὐκ ἀναγκαῖα ἕκαστα διεληλυθέναι καὶ ἑπόμενα ἀλλήλοις τῇ μελλούσῃ τοῦ ὄντος ἱκανῶς τε καὶ τελέως ψυχῇ μεταλήψεσθαι;","st":"486e"},{"sp":"N","t":"ἀναγκαιότατα μὲν οὖν, ἔφη.","st":"487a"},{"sp":"N","t":"ἔστιν οὖν ὅπῃ μέμψῃ τοιοῦτον ἐπιτήδευμα, ὃ μή ποτ᾽ ἄν τις οἷός τε γένοιτο ἱκανῶς ἐπιτηδεῦσαι, εἰ μὴ φύσει εἴη μνήμων, εὐμαθής, μεγαλοπρεπής, εὔχαρις, φίλος τε καὶ συγγενὴς ἀληθείας, δικαιοσύνης, ἀνδρείας, σωφροσύνης;","st":"487a"},{"sp":"N","t":"οὐδ᾽ ἂν ὁ Μῶμος, ἔφη, τό γε τοιοῦτον μέμψαιτο.","st":"487a"},{"sp":"N","t":"ἀλλ᾽, ἦν δ᾽ ἐγώ, τελειωθεῖσι τοῖς τοιούτοις παιδείᾳ τε καὶ ἡλικίᾳ ἆρα οὐ μόνοις ἂν τὴν πόλιν ἐπιτρέποις;","st":"487a"},{"sp":"N","t":"Σωκράτης, Αδείμαντος","st":"487b"},{"sp":"N","t":"καὶ ὁ Ἀδείμαντος, ὦ Σώκρατες, ἔφη, πρὸς μὲν ταῦτά σοι οὐδεὶς ἂν οἷός τ᾽ εἴη ἀντειπεῖν. ἀλλὰ γὰρ τοιόνδε τι πάσχουσιν οἱ ἀκούοντες ἑκάστοτε ἃ νῦν λέγεις: ἡγοῦνται δι᾽ ἀπειρίαν τοῦ ἐρωτᾶν καὶ ἀποκρίνεσθαι ὑπὸ τοῦ λόγου παρ᾽ ἕκαστον τὸ ἐρώτημα σμικρὸν παραγόμενοι, ἁθροισθέντων τῶν σμικρῶν ἐπὶ τελευτῆς τῶν λόγων μέγα τὸ σφάλμα καὶ ἐναντίον τοῖς πρώτοις ἀναφαίνεσθαι, καὶ ὥσπερ ὑπὸ τῶν πεττεύειν δεινῶν οἱ μὴ τελευτῶντες ἀποκλείονται καὶ οὐκ ἔχουσιν ὅτι","st":"487b"},{"sp":"N","t":"φέρωσιν, οὕτω καὶ σφεῖς τελευτῶντες ἀποκλείεσθαι καὶ οὐκ ἔχειν ὅτι λέγωσιν ὑπὸ πεττείας αὖ ταύτης τινὸς ἑτέρας, οὐκ ἐν ψήφοις ἀλλ᾽ ἐν λόγοις: ἐπεὶ τό γε ἀληθὲς οὐδέν τι μᾶλλον ταύτῃ ἔχειν. λέγω δ᾽ εἰς τὸ παρὸν ἀποβλέψας. νῦν γὰρ φαίη ἄν τίς σοι λόγῳ μὲν οὐκ ἔχειν καθ᾽ ἕκαστον τὸ ἐρωτώμενον ἐναντιοῦσθαι, ἔργῳ δὲ ὁρᾶν, ὅσοι ἂν ἐπὶ φιλοσοφίαν ὁρμήσαντες μὴ τοῦ πεπαιδεῦσθαι ἕνεκα ἁψάμενοι νέοι ὄντες","st":"487c"},{"sp":"N","t":"ἀπαλλάττωνται, ἀλλὰ μακρότερον ἐνδιατρίψωσιν, τοὺς μὲν πλείστους καὶ πάνυ ἀλλοκότους γιγνομένους, ἵνα μὴ παμπονήρους εἴπωμεν, τοὺς δ᾽ ἐπιεικεστάτους δοκοῦντας ὅμως τοῦτό γε ὑπὸ τοῦ ἐπιτηδεύματος οὗ σὺ ἐπαινεῖς πάσχοντας, ἀχρήστους ταῖς πόλεσι γιγνομένους.","st":"487d"},{"sp":"N","t":"καὶ ἐγὼ ἀκούσας, οἴει οὖν, εἶπον, τοὺς ταῦτα λέγοντας ψεύδεσθαι;","st":"487d"},{"sp":"N","t":"οὐκ οἶδα, ἦ δ᾽ ὅς, ἀλλὰ τὸ σοὶ δοκοῦν ἡδέως ἂν ἀκούοιμι.","st":"487d"},{"sp":"N","t":"ἀκούοις ἂν ὅτι ἔμοιγε φαίνονται τἀληθῆ λέγειν.","st":"487d"},{"sp":"N","t":"πῶς οὖν, ἔφη, εὖ ἔχει λέγειν ὅτι οὐ πρότερον κακῶν παύσονται αἱ πόλεις, πρὶν ἂν ἐν αὐταῖς οἱ φιλόσοφοι ἄρξωσιν, οὓς ἀχρήστους ὁμολογοῦμεν αὐταῖς εἶναι;","st":"487e"},{"sp":"N","t":"ἐρωτᾷς, ἦν δ᾽ ἐγώ, ἐρώτημα δεόμενον ἀποκρίσεως δι᾽ εἰκόνος λεγομένης.","st":"487e"},{"sp":"N","t":"σὺ δέ γε, ἔφη, οἶμαι οὐκ εἴωθας δι᾽ εἰκόνων λέγειν.","st":"487e"},{"sp":"N","t":"εἶεν, εἶπον: σκώπτεις ἐμβεβληκώς με εἰς λόγον οὕτω","st":"487e"},{"sp":"N","t":"δυσαπόδεικτον; ἄκουε δ᾽ οὖν τῆς εἰκόνος, ἵν᾽ ἔτι μᾶλλον ἴδῃς ὡς γλίσχρως εἰκάζω. οὕτω γὰρ χαλεπὸν τὸ πάθος τῶν ἐπιεικεστάτων, ὃ πρὸς τὰς πόλεις πεπόνθασιν, ὥστε οὐδ᾽ ἔστιν ἓν οὐδὲν ἄλλο τοιοῦτον πεπονθός, ἀλλὰ δεῖ ἐκ πολλῶν αὐτὸ συναγαγεῖν εἰκάζοντα καὶ ἀπολογούμενον ὑπὲρ αὐτῶν, οἷον οἱ γραφῆς τραγελάφους καὶ τὰ τοιαῦτα μειγνύντες γράφουσιν. νόησον γὰρ τοιουτονὶ γενόμενον εἴτε πολλῶν νεῶν πέρι εἴτε μιᾶς: ναύκληρον μεγέθει μὲν καὶ","st":"488a"},{"sp":"N","t":"ῥώμῃ ὑπὲρ τοὺς ἐν τῇ νηὶ πάντας, ὑπόκωφον δὲ καὶ ὁρῶντα ὡσαύτως βραχύ τι καὶ γιγνώσκοντα περὶ ναυτικῶν ἕτερα τοιαῦτα, τοὺς δὲ ναύτας στασιάζοντας πρὸς ἀλλήλους περὶ τῆς κυβερνήσεως, ἕκαστον οἰόμενον δεῖν κυβερνᾶν, μήτε μαθόντα πώποτε τὴν τέχνην μέτε ἔχοντα ἀποδεῖξαι διδάσκαλον ἑαυτοῦ μηδὲ χρόνον ἐν ᾧ ἐμάνθανεν, πρὸς δὲ τούτοις φάσκοντας μηδὲ διδακτὸν εἶναι, ἀλλὰ καὶ τὸν λέγοντα ὡς διδακτὸν ἑτοίμους κατατέμνειν, αὐτοὺς δὲ αὐτῷ ἀεὶ τῷ","st":"488b"},{"sp":"N","t":"ναυκλήρῳ περικεχύσθαι δεομένους καὶ πάντα ποιοῦντας ὅπως ἂν σφίσι τὸ πηδάλιον ἐπιτρέψῃ, ἐνίοτε δ᾽ ἂν μὴ πείθωσιν ἀλλὰ ἄλλοι μᾶλλον, τοὺς μὲν ἄλλους ἢ ἀποκτεινύντας ἢ ἐκβάλλοντας ἐκ τῆς νεώς, τὸν δὲ γενναῖον ναύκληρον μανδραγόρᾳ ἢ μέθῃ ἤ τινι ἄλλῳ συμποδίσαντας τῆς νεὼς ἄρχειν χρωμένους τοῖς ἐνοῦσι, καὶ πίνοντάς τε καὶ εὐωχουμένους πλεῖν ὡς τὸ εἰκὸς τοὺς τοιούτους, πρὸς δὲ τούτοις ἐπαινοῦντας","st":"488c"},{"sp":"N","t":"ναυτικὸν μὲν καλοῦντας καὶ κυβερνητικὸν καὶ ἐπιστάμενον τὰ κατὰ ναῦν, ὃς ἂν συλλαμβάνειν δεινὸς ᾖ ὅπως ἄρξουσιν ἢ πείθοντες ἢ βιαζόμενοι τὸν ναύκληρον, τὸν δὲ μὴ τοιοῦτον ψέγοντας ὡς ἄχρηστον, τοῦ δὲ ἀληθινοῦ κυβερνήτου πέρι μηδ᾽ ἐπαΐοντες, ὅτι ἀνάγκη αὐτῷ τὴν ἐπιμέλειαν ποιεῖσθαι ἐνιαυτοῦ καὶ ὡρῶν καὶ οὐρανοῦ καὶ ἄστρων καὶ πνευμάτων καὶ πάντων τῶν τῇ τέχνῃ προσηκόντων, εἰ μέλλει τῷ ὄντι νεὼς ἀρχικὸς ἔσεσθαι, ὅπως δὲ κυβερνήσει","st":"488d"},{"sp":"N","t":"ἐάντε τινες βούλωνται ἐάντε μή, μήτε τέχνην τούτου μήτε μελέτην οἰόμενοι δυνατὸν εἶναι λαβεῖν ἅμα καὶ τὴν κυβερνητικήν. τοιούτων δὴ περὶ τὰς ναῦς γιγνομένων τὸν ὡς ἀληθῶς κυβερνητικὸν οὐχ ἡγῇ ἂν τῷ ὄντι μετεωροσκόπον","st":"488e"},{"sp":"N","t":"τε καὶ ἀδολέσχην καὶ ἄχρηστόν σφισι καλεῖσθαι ὑπὸ τῶν ἐν ταῖς οὕτω κατεσκευασμέναις ναυσὶ πλωτήρων;","st":"489a"},{"sp":"N","t":"καὶ μάλα, ἔφη ὁ Ἀδείμαντος.","st":"489a"},{"sp":"N","t":"οὐ δή, ἦν δ᾽ ἐγώ, οἶμαι δεῖσθαί σε ἐξεταζομένην τὴν εἰκόνα ἰδεῖν, ὅτι ταῖς πόλεσι πρὸς τοὺς ἀληθινοὺς φιλοσόφους τὴν διάθεσιν ἔοικεν, ἀλλὰ μανθάνειν ὃ λέγω.","st":"489a"},{"sp":"N","t":"καὶ μάλ᾽, ἔφη.","st":"489a"},{"sp":"N","t":"πρῶτον μὲν τοίνυν ἐκεῖνον τὸν θαυμάζοντα ὅτι οἱ φιλόσοφοι οὐ τιμῶνται ἐν ταῖς πόλεσι δίδασκέ τε τὴν εἰκόνα καὶ πειρῶ πείθειν ὅτι πολὺ ἂν θαυμαστότερον ἦν","st":"489a"},{"sp":"N","t":"εἰ ἐτιμῶντο.","st":"489b"},{"sp":"N","t":"ἀλλὰ διδάξω, ἔφη.","st":"489b"},{"sp":"N","t":"καὶ ὅτι τοίνυν τἀληθῆ λέγεις, ὡς ἄχρηστοι τοῖς πολλοῖς οἱ ἐπιεικέστατοι τῶν ἐν φιλοσοφίᾳ: τῆς μέντοι ἀχρηστίας τοὺς μὴ χρωμένους κέλευε αἰτιᾶσθαι, ἀλλὰ μὴ τοὺς ἐπιεικεῖς. οὐ γὰρ ἔχει φύσιν κυβερνήτην ναυτῶν δεῖσθαι ἄρχεσθαι ὑφ᾽ αὑτοῦ οὐδὲ τοὺς σοφοὺς ἐπὶ τὰς τῶν πλουσίων θύρας ἰέναι, ἀλλ᾽ ὁ τοῦτο κομψευσάμενος ἐψεύσατο, τὸ δὲ ἀληθὲς πέφυκεν, ἐάντε πλούσιος ἐάντε πένης κάμνῃ, ἀναγκαῖον","st":"489b"},{"sp":"N","t":"εἶναι ἐπὶ ἰατρῶν θύρας ἰέναι καὶ πάντα τὸν ἄρχεσθαι δεόμενον ἐπὶ τὰς τοῦ ἄρχειν δυναμένου, οὐ τὸν ἄρχοντα δεῖσθαι τῶν ἀρχομένων ἄρχεσθαι, οὗ ἂν τῇ ἀληθείᾳ τι ὄφελος ᾖ. ἀλλὰ τοὺς νῦν πολιτικοὺς ἄρχοντας ἀπεικάζων οἷς ἄρτι ἐλέγομεν ναύταις οὐχ ἁμαρτήσῃ, καὶ τοὺς ὑπὸ τούτων ἀχρήστους λεγομένους καὶ μετεωρολέσχας τοῖς ὡς ἀληθῶς κυβερνήταις.","st":"489c"},{"sp":"N","t":"ὀρθότατα, ἔφη.","st":"489c"},{"sp":"N","t":"ἔκ τε τοίνυν τούτων καὶ ἐν τούτοις οὐ ῥᾴδιον εὐδοκιμεῖν τὸ βέλτιστον ἐπιτήδευμα ὑπὸ τῶν τἀναντία ἐπιτηδευόντων:","st":"489c"},{"sp":"N","t":"πολὺ δὲ μεγίστη καὶ ἰσχυροτάτη διαβολὴ γίγνεται φιλοσοφίᾳ διὰ τοὺς τὰ τοιαῦτα φάσκοντας ἐπιτηδεύειν, οὓς δὴ σὺ φῂς τὸν ἐγκαλοῦντα τῇ φιλοσοφίᾳ λέγειν ὡς παμπόνηροι οἱ πλεῖστοι τῶν ἰόντων ἐπ᾽ αὐτήν, οἱ δὲ ἐπιεικέστατοι ἄχρηστοι, καὶ ἐγὼ συνεχώρησα ἀληθῆ σε λέγειν. ἦ γάρ;","st":"489d"},{"sp":"N","t":"ναί.","st":"489d"},{"sp":"N","t":"οὐκοῦν τῆς μὲν τῶν ἐπιεικῶν ἀχρηστίας τὴν αἰτίαν διεληλύθαμεν;","st":"489d"},{"sp":"N","t":"καὶ μάλα.","st":"489d"},{"sp":"N","t":"τῆς δὲ τῶν πολλῶν πονηρίας τὴν ἀνάγκην βούλει τὸ μετὰ τοῦτο διέλθωμεν, καὶ ὅτι οὐδὲ τούτου φιλοσοφία αἰτία,","st":"489d"},{"sp":"N","t":"ἂν δυνώμεθα, πειραθῶμεν δεῖξαι;","st":"489e"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"489e"},{"sp":"N","t":"ἀκούωμεν δὴ καὶ λέγωμεν ἐκεῖθεν ἀναμνησθέντες, ὅθεν διῇμεν τὴν φύσιν οἷον ἀνάγκη φῦναι τὸν καλόν τε κἀγαθὸν","st":"489e"},{"sp":"N","t":"ἐσόμενον. ἡγεῖτο δ᾽ αὐτῷ, εἰ νῷ ἔχεις, πρῶτον μὲν ἀλήθεια, ἣν διώκειν αὐτὸν πάντως καὶ πάντῃ ἔδει ἢ ἀλαζόνι ὄντι μηδαμῇ μετεῖναι φιλοσοφίας ἀληθινῆς.","st":"490a"},{"sp":"N","t":"ἦν γὰρ οὕτω λεγόμενον.","st":"490a"},{"sp":"N","t":"οὐκοῦν ἓν μὲν τοῦτο σφόδρα οὕτω παρὰ δόξαν τοῖς νῦν δοκουμένοις περὶ αὐτοῦ;","st":"490a"},{"sp":"N","t":"καὶ μάλα, ἔφη.","st":"490a"},{"sp":"N","t":"ἆρ᾽ οὖν δὴ οὐ μετρίως ἀπολογησόμεθα ὅτι πρὸς τὸ ὂν πεφυκὼς εἴη ἁμιλλᾶσθαι ὅ γε ὄντως φιλομαθής, καὶ οὐκ","st":"490a"},{"sp":"N","t":"ἐπιμένοι ἐπὶ τοῖς δοξαζομένοις εἶναι πολλοῖς ἑκάστοις, ἀλλ᾽ ἴοι καὶ οὐκ ἀμβλύνοιτο οὐδ᾽ ἀπολήγοι τοῦ ἔρωτος, πρὶν αὐτοῦ ὃ ἔστιν ἑκάστου τῆς φύσεως ἅψασθαι ᾧ προσήκει ψυχῆς ἐφάπτεσθαι τοῦ τοιούτου — προσήκει δὲ συγγενεῖ- ᾧ πλησιάσας καὶ μιγεὶς τῷ ὄντι ὄντως, γεννήσας νοῦν καὶ ἀλήθειαν, γνοίη τε καὶ ἀληθῶς ζῴη καὶ τρέφοιτο καὶ οὕτω λήγοι ὠδῖνος, πρὶν δ᾽ οὔ;","st":"490b"},{"sp":"N","t":"ὡς οἷόν τ᾽, ἔφη, μετριώτατα.","st":"490b"},{"sp":"N","t":"τί οὖν; τούτῳ τι μετέσται ψεῦδος ἀγαπᾶν ἢ πᾶν τοὐναντίον μισεῖν;","st":"490b"},{"sp":"N","t":"μισεῖν, ἔφη.","st":"490c"},{"sp":"N","t":"ἡγουμένης δὴ ἀληθείας οὐκ ἄν ποτε οἶμαι φαμὲν αὐτῇ χορὸν κακῶν ἀκολουθῆσαι.","st":"490c"},{"sp":"N","t":"πῶς γάρ;","st":"490c"},{"sp":"N","t":"ἀλλ᾽ ὑγιές τε καὶ δίκαιον ἦθος, ᾧ καὶ σωφροσύνην ἕπεσθαι.","st":"490c"},{"sp":"N","t":"ὀρθῶς, ἔφη.","st":"490c"},{"sp":"N","t":"καὶ δὴ τὸν ἄλλον τῆς φιλοσόφου φύσεως χορὸν τί δεῖ πάλιν ἐξ ἀρχῆς ἀναγκάζοντα τάττειν; μέμνησαι γάρ που ὅτι συνέβη προσῆκον τούτοις ἀνδρεία, μεγαλοπρέπεια, εὐμάθεια, μνήμη: καὶ σοῦ ἐπιλαβομένου ὅτι πᾶς μὲν ἀναγκασθήσεται","st":"490c"},{"sp":"N","t":"ὁμολογεῖν οἷς λέγομεν, ἐάσας δὲ τοὺς λόγους, εἰς αὐτοὺς ἀποβλέψας περὶ ὧν ὁ λόγος, φαίη ὁρᾶν αὐτῶν τοὺς μὲν ἀχρήστους, τοὺς δὲ πολλοὺς κακοὺς πᾶσαν κακίαν, τῆς διαβολῆς τὴν αἰτίαν ἐπισκοποῦντες ἐπὶ τούτῳ νῦν γεγόναμεν, τί ποθ᾽ οἱ πολλοὶ κακοί, καὶ τούτου δὴ ἕνεκα πάλιν ἀνειλήφαμεν τὴν τῶν ἀληθῶς φιλοσόφων φύσιν καὶ ἐξ ἀνάγκης ὡρισάμεθα.","st":"490d"},{"sp":"N","t":"ἔστιν, ἔφη, ταῦτα.","st":"490e"},{"sp":"N","t":"ταύτης δή, ἦν δ᾽ ἐγώ, τῆς φύσεως δεῖ θεάσασθαι τὰς φθοράς, ὡς διόλλυται ἐν πολλοῖς, σμικρὸν δέ τι ἐκφεύγει, οὓς δὴ καὶ οὐ πονηρούς, ἀχρήστους δὲ καλοῦσι: καὶ μετὰ","st":"490e"},{"sp":"N","t":"τοῦτο αὖ τὰς μιμουμένας ταύτην καὶ εἰς τὸ ἐπιτήδευμα καθισταμένας αὐτῆς, οἷαι οὖσαι φύσεις ψυχῶν εἰς ἀνάξιον καὶ μεῖζον ἑαυτῶν ἀφικνούμεναι ἐπιτήδευμα, πολλαχῇ πλημμελοῦσαι, πανταχῇ καὶ ἐπὶ πάντας δόξαν οἵαν λέγεις φιλοσοφίᾳ προσῆψαν.","st":"491a"},{"sp":"N","t":"τίνας δέ, ἔφη, τὰς διαφθορὰς λέγεις;","st":"491a"},{"sp":"N","t":"ἐγώ σοι, εἶπον, ἂν οἷός τε γένωμαι, πειράσομαι διελθεῖν. τόδε μὲν οὖν οἶμαι πᾶς ἡμῖν ὁμολογήσει, τοιαύτην φύσιν καὶ πάντα ἔχουσαν ὅσα προσετάξαμεν νυνδή, εἰ τελέως","st":"491a"},{"sp":"N","t":"μέλλοι φιλόσοφος γενέσθαι, ὀλιγάκις ἐν ἀνθρώποις φύεσθαι καὶ ὀλίγας. ἢ οὐκ οἴει;","st":"491b"},{"sp":"N","t":"σφόδρα γε.","st":"491b"},{"sp":"N","t":"τούτων δὴ τῶν ὀλίγων σκόπει ὡς πολλοὶ ὄλεθροι καὶ μεγάλοι.","st":"491b"},{"sp":"N","t":"τίνες δή;","st":"491b"},{"sp":"N","t":"ὃ μὲν πάντων θαυμαστότατον ἀκοῦσαι, ὅτι ἓν ἕκαστον ὧν ἐπῃνέσαμεν τῆς φύσεως ἀπόλλυσι τὴν ἔχουσαν ψυχὴν καὶ ἀποσπᾷ φιλοσοφίας. λέγω δὲ ἀνδρείαν, σωφροσύνην καὶ πάντα ἃ διήλθομεν.","st":"491b"},{"sp":"N","t":"ἄτοπον, ἔφη, ἀκοῦσαι.","st":"491b"},{"sp":"N","t":"ἔτι τοίνυν, ἦν δ᾽ ἐγώ, πρὸς τούτοις τὰ λεγόμενα ἀγαθὰ πάντα φθείρει καὶ ἀποσπᾷ, κάλλος καὶ πλοῦτος καὶ ἰσχὺς σώματος καὶ συγγένεια ἐρρωμένη ἐν πόλει καὶ πάντα τὰ τούτων οἰκεῖα: ἔχεις γὰρ τὸν τύπον ὧν λέγω.","st":"491c"},{"sp":"N","t":"ἔχω, ἔφη: καὶ ἡδέως γ᾽ ἂν ἀκριβέστερον ἃ λέγεις πυθοίμην.","st":"491c"},{"sp":"N","t":"λαβοῦ τοίνυν, ἦν δ᾽ ἐγώ, ὅλου αὐτοῦ ὀρθῶς, καί σοι εὔδηλόν τε φανεῖται καὶ οὐκ ἄτοπα δόξει τὰ προειρημένα περὶ αὐτῶν.","st":"491c"},{"sp":"N","t":"πῶς οὖν, ἔφη, κελεύεις;","st":"491c"},{"sp":"N","t":"παντός, ἦν δ᾽ ἐγώ, σπέρματος πέρι ἢ φυτοῦ, εἴτε ἐγγείων εἴτε τῶν ζῴων, ἴσμεν ὅτι τὸ μὴ τυχὸν τροφῆς ἧς προσήκει ἑκάστῳ μηδ᾽ ὥρας μηδὲ τόπου, ὅσῳ ἂν ἐρρωμενέστερον ᾖ, τοσούτῳ πλειόνων ἐνδεῖ τῶν πρεπόντων: ἀγαθῷ γάρ που κακὸν ἐναντιώτερον ἢ τῷ μὴ ἀγαθῷ.","st":"491d"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"491d"},{"sp":"N","t":"ἔχει δὴ οἶμαι λόγον τὴν ἀρίστην φύσιν ἐν ἀλλοτριωτέρᾳ οὖσαν τροφῇ κάκιον ἀπαλλάττειν τῆς φαύλης.","st":"491d"},{"sp":"N","t":"ἔχει.","st":"491d"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, ὦ Ἀδείμαντε, καὶ τὰς ψυχὰς οὕτω φῶμεν τὰς εὐφυεστάτας κακῆς παιδαγωγίας τυχούσας διαφερόντως κακὰς γίγνεσθαι; ἢ οἴει τὰ μεγάλα ἀδικήματα καὶ τὴν ἄκρατον πονηρίαν ἐκ φαύλης ἀλλ᾽ οὐκ ἐκ νεανικῆς φύσεως τροφῇ διολομένης γίγνεσθαι, ἀσθενῆ δὲ φύσιν μεγάλων οὔτε ἀγαθῶν οὔτε κακῶν αἰτίαν ποτὲ ἔσεσθαι;","st":"491e"},{"sp":"N","t":"οὔκ, ἀλλά, ἦ δ᾽ ὅς, οὕτως.","st":"491e"},{"sp":"N","t":"ἣν τοίνυν ἔθεμεν τοῦ φιλοσόφου φύσιν, ἂν μὲν οἶμαι μαθήσεως προσηκούσης τύχῃ, εἰς πᾶσαν ἀρετὴν ἀνάγκη αὐξανομένην ἀφικνεῖσθαι, ἐὰν δὲ μὴ ἐν προσηκούσῃ σπαρεῖσά τε καὶ φυτευθεῖσα τρέφηται, εἰς πάντα τἀναντία αὖ, ἐὰν μή τις αὐτῇ βοηθήσας θεῶν τύχῃ. ἢ καὶ σὺ ἡγῇ, ὥσπερ οἱ πολλοί, διαφθειρομένους τινὰς εἶναι ὑπὸ σοφιστῶν νέους, διαφθείροντας δέ τινας σοφιστὰς ἰδιωτικούς, ὅτι καὶ ἄξιον λόγου, ἀλλ᾽ οὐκ αὐτοὺς τοὺς ταῦτα λέγοντας μεγίστους","st":"492a"},{"sp":"N","t":"μὲν εἶναι σοφιστάς, παιδεύειν δὲ τελεώτατα καὶ ἀπεργάζεσθαι οἵους βούλονται εἶναι καὶ νέους καὶ πρεσβυτέρους καὶ ἄνδρας καὶ γυναῖκας;","st":"492b"},{"sp":"N","t":"πότε δή; ἦ δ᾽ ὅς.","st":"492b"},{"sp":"N","t":"ὅταν, εἶπον, συγκαθεζόμενοι ἁθρόοι πολλοὶ εἰς ἐκκλησίας ἢ εἰς δικαστήρια ἢ θέατρα ἢ στρατόπεδα ἤ τινα ἄλλον κοινὸν πλήθους σύλλογον σὺν πολλῷ θορύβῳ τὰ μὲν ψέγωσι τῶν λεγομένων ἢ πραττομένων, τὰ δὲ ἐπαινῶσιν, ὑπερβαλλόντως ἑκάτερα, καὶ ἐκβοῶντες καὶ κροτοῦντες, πρὸς δ᾽","st":"492b"},{"sp":"N","t":"αὐτοῖς αἵ τε πέτραι καὶ ὁ τόπος ἐν ᾧ ἂν ὦσιν ἐπηχοῦντες διπλάσιον θόρυβον παρέχωσι τοῦ ψόγου καὶ ἐπαίνου. ἐν δὴ τῷ τοιούτῳ τὸν νέον, τὸ λεγόμενον, τίνα οἴει καρδίαν ἴσχειν; ἢ ποίαν [ἂν] αὐτῷ παιδείαν ἰδιωτικὴν ἀνθέξειν, ἣν οὐ κατακλυσθεῖσαν ὑπὸ τοῦ τοιούτου ψόγου ἢ ἐπαίνου οἰχήσεσθαι φερομένην κατὰ ῥοῦν ᾗ ἂν οὗτος φέρῃ, καὶ φήσειν τε τὰ αὐτὰ τούτοις καλὰ καὶ αἰσχρὰ εἶναι, καὶ ἐπιτηδεύσειν ἅπερ ἂν οὗτοι, καὶ ἔσεσθαι τοιοῦτον;","st":"492c"},{"sp":"N","t":"πολλή, ἦ δ᾽ ὅς, ὦ Σώκρατες, ἀνάγκη.","st":"492d"},{"sp":"N","t":"καὶ μήν, ἦν δ᾽ ἐγώ, οὔπω τὴν μεγίστην ἀνάγκην εἰρήκαμεν.","st":"492d"},{"sp":"N","t":"ποίαν; ἔφη.","st":"492d"},{"sp":"N","t":"ἣν ἔργῳ προστιθέασι λόγῳ μὴ πείθοντες οὗτοι οἱ παιδευταί τε καὶ σοφισταί. ἢ οὐκ οἶσθα ὅτι τὸν μὴ πειθόμενον ἀτιμίαις τε καὶ χρήμασι καὶ θανάτοις κολάζουσι;","st":"492d"},{"sp":"N","t":"καὶ μάλα, ἔφη, σφόδρα.","st":"492d"},{"sp":"N","t":"τίνα οὖν ἄλλον σοφιστὴν οἴει ἢ ποίους ἰδιωτικοὺς λόγους ἐναντία τούτοις τείνοντας κρατήσειν;","st":"492d"},{"sp":"N","t":"οἶμαι μὲν οὐδένα, ἦ δ᾽ ὅς.","st":"492e"},{"sp":"N","t":"οὐ γάρ, ἦν δ᾽ ἐγώ, ἀλλὰ καὶ τὸ ἐπιχειρεῖν πολλὴ ἄνοια. οὔτε γὰρ γίγνεται οὔτε γέγονεν οὐδὲ οὖν μὴ γένηται ἀλλοῖον ἦθος πρὸς ἀρετὴν παρὰ τὴν τούτων παιδείαν πεπαιδευμένον, ἀνθρώπειον, ὦ ἑταῖρε — θεῖον μέντοι κατὰ τὴν παροιμίαν ἐξαιρῶμεν λόγου: εὖ γὰρ χρὴ εἰδέναι, ὅτιπερ ἂν σωθῇ τε","st":"492e"},{"sp":"N","t":"καὶ γένηται οἷον δεῖ ἐν τοιαύτῃ καταστάσει πολιτειῶν, θεοῦ μοῖραν αὐτὸ σῶσαι λέγων οὐ κακῶς ἐρεῖς.","st":"493a"},{"sp":"N","t":"οὐδ᾽ ἐμοὶ ἄλλως, ἔφη, δοκεῖ.","st":"493a"},{"sp":"N","t":"ἔτι τοίνυν σοι, ἦν δ᾽ ἐγώ, πρὸς τούτοις καὶ τόδε δοξάτω.","st":"493a"},{"sp":"N","t":"τὸ ποῖον;","st":"493a"},{"sp":"N","t":"ἕκαστος τῶν μισθαρνούντων ἰδιωτῶν, οὓς δὴ οὗτοι σοφιστὰς καλοῦσι καὶ ἀντιτέχνους ἡγοῦνται, μὴ ἄλλα παιδεύειν ἢ ταῦτα τὰ τῶν πολλῶν δόγματα, ἃ δοξάζουσιν ὅταν ἁθροισθῶσιν, καὶ σοφίαν ταύτην καλεῖν: οἷόνπερ ἂν εἰ θρέμματος μεγάλου καὶ ἰσχυροῦ τρεφομένου τὰς ὀργάς τις καὶ","st":"493a"},{"sp":"N","t":"ἐπιθυμίας κατεμάνθανεν, ὅπῃ τε προσελθεῖν χρὴ καὶ ὅπῃ ἅψασθαι αὐτοῦ, καὶ ὁπότε χαλεπώτατον ἢ πρᾳότατον καὶ ἐκ τίνων γίγνεται, καὶ φωνὰς δὴ ἐφ᾽ οἷς ἑκάστας εἴωθεν φθέγγεσθαι, καὶ οἵας αὖ ἄλλου φθεγγομένου ἡμεροῦταί τε καὶ ἀγριαίνει, καταμαθὼν δὲ ταῦτα πάντα συνουσίᾳ τε καὶ χρόνου τριβῇ σοφίαν τε καλέσειεν καὶ ὡς τέχνην συστησάμενος ἐπὶ διδασκαλίαν τρέποιτο, μηδὲν εἰδὼς τῇ ἀληθείᾳ τούτων τῶν δογμάτων τε καὶ ἐπιθυμιῶν ὅτι καλὸν ἢ αἰσχρὸν","st":"493b"},{"sp":"N","t":"ἢ ἀγαθὸν ἢ κακὸν ἢ δίκαιον ἢ ἄδικον, ὀνομάζοι δὲ πάντα ταῦτα ἐπὶ ταῖς τοῦ μεγάλου ζῴου δόξαις, οἷς μὲν χαίροι ἐκεῖνο ἀγαθὰ καλῶν, οἷς δὲ ἄχθοιτο κακά, ἄλλον δὲ μηδένα ἔχοι λόγον περὶ αὐτῶν, ἀλλὰ τἀναγκαῖα δίκαια καλοῖ καὶ καλά, τὴν δὲ τοῦ ἀναγκαίου καὶ ἀγαθοῦ φύσιν, ὅσον διαφέρει τῷ ὄντι, μήτε ἑωρακὼς εἴη μήτε ἄλλῳ δυνατὸς δεῖξαι. τοιοῦτος δὴ ὢν πρὸς Διὸς οὐκ ἄτοπος ἄν σοι δοκεῖ εἶναι παιδευτής;","st":"493c"},{"sp":"N","t":"ἔμοιγ᾽, ἔφη.","st":"493c"},{"sp":"N","t":"ἦ οὖν τι τούτου δοκεῖ διαφέρειν ὁ τὴν τῶν πολλῶν καὶ","st":"493c"},{"sp":"N","t":"παντοδαπῶν συνιόντων ὀργὴν καὶ ἡδονὰς κατανενοηκέναι σοφίαν ἡγούμενος, εἴτ᾽ ἐν γραφικῇ εἴτ᾽ ἐν μουσικῇ εἴτε δὴ ἐν πολιτικῇ; ὅτι μὲν γὰρ ἄν τις τούτοις ὁμιλῇ ἐπιδεικνύμενος, ἢ ποίησιν ἤ τινα ἄλλην δημιουργίαν ἢ πόλει διακονίαν, κυρίους αὑτοῦ ποιῶν τοὺς πολλούς, πέρα τῶν ἀναγκαίων, ἡ Διομηδεία λεγομένη ἀνάγκη ποιεῖν αὐτῷ ταῦτα ἃ ἂν οὗτοι ἐπαινῶσιν: ὡς δὲ καὶ ἀγαθὰ καὶ καλὰ ταῦτα τῇ ἀληθείᾳ, ἤδη πώποτέ του ἤκουσας αὐτῶν λόγον διδόντος οὐ καταγέλαστον;","st":"493d"},{"sp":"N","t":"οἶμαι δέ γε, ἦ δ᾽ ὅς, οὐδ᾽ ἀκούσομαι.","st":"493e"},{"sp":"N","t":"ταῦτα τοίνυν πάντα ἐννοήσας ἐκεῖνο ἀναμνήσθητι: αὐτὸ τὸ καλὸν ἀλλὰ μὴ τὰ πολλὰ καλά, ἢ αὐτό τι ἕκαστον καὶ","st":"493e"},{"sp":"N","t":"μὴ τὰ πολλὰ ἕκαστα, ἔσθ᾽ ὅπως πλῆθος ἀνέξεται ἢ ἡγήσεαι εἶναι;","st":"494a"},{"sp":"N","t":"ἥκιστά γ᾽, ἔφη.","st":"494a"},{"sp":"N","t":"φιλόσοφον μὲν ἄρα, ἦν δ᾽ ἐγώ, πλῆθος ἀδύνατον εἶναι.","st":"494a"},{"sp":"N","t":"ἀδύνατον.","st":"494a"},{"sp":"N","t":"καὶ τοὺς φιλοσοφοῦντας ἄρα ἀνάγκη ψέγεσθαι ὑπ᾽ αὐτῶν.","st":"494a"},{"sp":"N","t":"ἀνάγκη.","st":"494a"},{"sp":"N","t":"καὶ ὑπὸ τούτων δὴ τῶν ἰδιωτῶν, ὅσοι προσομιλοῦντες ὄχλῳ ἀρέσκειν αὐτῷ ἐπιθυμοῦσι.","st":"494a"},{"sp":"N","t":"δῆλον.","st":"494a"},{"sp":"N","t":"ἐκ δὴ τούτων τίνα ὁρᾷς σωτηρίαν φιλοσόφῳ φύσει, ὥστ᾽ ἐν τῷ ἐπιτηδεύματι μείνασαν πρὸς τέλος ἐλθεῖν; ἐννόει δ᾽","st":"494a"},{"sp":"N","t":"ἐκ τῶν ἔμπροσθεν. ὡμολόγηται γὰρ δὴ ἡμῖν εὐμάθεια καὶ μνήμη καὶ ἀνδρεία καὶ μεγαλοπρέπεια ταύτης εἶναι τῆς φύσεως.","st":"494b"},{"sp":"N","t":"ναί.","st":"494b"},{"sp":"N","t":"οὐκοῦν εὐθὺς ἐν παισὶν ὁ τοιοῦτος πρῶτος ἔσται ἐν ἅπασιν, ἄλλως τε καὶ ἐὰν τὸ σῶμα φυῇ προσφερὴς τῇ ψυχῇ;","st":"494b"},{"sp":"N","t":"τί δ᾽ οὐ μέλλει; ἔφη.","st":"494b"},{"sp":"N","t":"βουλήσονται δὴ οἶμαι αὐτῷ χρῆσθαι, ἐπειδὰν πρεσβύτερος γίγνηται, ἐπὶ τὰ αὑτῶν πράγματα οἵ τε οἰκεῖοι καὶ οἱ πολῖται.","st":"494b"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"494b"},{"sp":"N","t":"ὑποκείσονται ἄρα δεόμενοι καὶ τιμῶντες, προκαταλαμβάνοντες καὶ προκολακεύοντες τὴν μέλλουσαν αὐτοῦ δύναμιν.","st":"494c"},{"sp":"N","t":"φιλεῖ γοῦν, ἔφη, οὕτω γίγνεσθαι.","st":"494c"},{"sp":"N","t":"τί οὖν οἴει, ἦν δ᾽ ἐγώ, τὸν τοιοῦτον ἐν τοῖς τοιούτοις ποιήσειν, ἄλλως τε καὶ ἐὰν τύχῃ μεγάλης πόλεως ὢν καὶ ἐν ταύτῃ πλούσιός τε καὶ γενναῖος, καὶ ἔτι εὐειδὴς καὶ μέγας; ἆρ᾽ οὐ πληρωθήσεσθαι ἀμηχάνου ἐλπίδος, ἡγούμενον καὶ τὰ τῶν Ἑλλήνων καὶ τὰ τῶν βαρβάρων ἱκανὸν ἔσεσθαι","st":"494c"},{"sp":"N","t":"πράττειν, καὶ ἐπὶ τούτοις ὑψηλὸν ἐξαρεῖν αὑτόν, σχηματισμοῦ καὶ φρονήματος κενοῦ ἄνευ νοῦ ἐμπιμπλάμενον;","st":"494d"},{"sp":"N","t":"καὶ μάλ᾽, ἔφη.","st":"494d"},{"sp":"N","t":"τῷ δὴ οὕτω διατιθεμένῳ ἐάν τις ἠρέμα προσελθὼν τἀληθῆ λέγῃ, ὅτι νοῦς οὐκ ἔνεστιν αὐτῷ, δεῖται δέ, τὸ δὲ οὐ κτητὸν μὴ δουλεύσαντι τῇ κτήσει αὐτοῦ, ἆρ᾽ εὐπετὲς οἴει εἶναι εἰσακοῦσαι διὰ τοσούτων κακῶν;","st":"494d"},{"sp":"N","t":"πολλοῦ γε δεῖ, ἦ δ᾽ ὅς.","st":"494d"},{"sp":"N","t":"ἐὰν δ᾽ οὖν, ἦν δ᾽ ἐγώ, διὰ τὸ εὖ πεφυκέναι καὶ τὸ συγγενὲς","st":"494d"},{"sp":"N","t":"τῶν λόγων εἰσαισθάνηταί τέ πῃ καὶ κάμπτηται καὶ ἕλκηται πρὸς φιλοσοφίαν, τί οἰόμεθα δράσειν ἐκείνους τοὺς ἡγουμένους ἀπολλύναι αὐτοῦ τὴν χρείαν τε καὶ ἑταιρίαν; οὐ πᾶν μὲν ἔργον, πᾶν δ᾽ ἔπος λέγοντάς τε καὶ πράττοντας καὶ περὶ αὐτόν, ὅπως ἂν μὴ πεισθῇ, καὶ περὶ τὸν πείθοντα, ὅπως ἂν μὴ οἷός τ᾽ ᾖ, καὶ ἰδίᾳ ἐπιβουλεύοντας καὶ δημοσίᾳ εἰς ἀγῶνας καθιστάντας;","st":"494e"},{"sp":"N","t":"πολλή, ἦ δ᾽ ὅς, ἀνάγκη.","st":"495a"},{"sp":"N","t":"ἔστιν οὖν ὅπως ὁ τοιοῦτος φιλοσοφήσει;","st":"495a"},{"sp":"N","t":"οὐ πάνυ.","st":"495a"},{"sp":"N","t":"ὁρᾷς οὖν, ἦν δ᾽ ἐγώ, ὅτι οὐ κακῶς ἐλέγομεν ὡς ἄρα καὶ αὐτὰ τὰ τῆς φιλοσόφου φύσεως μέρη, ὅταν ἐν κακῇ τροφῇ γένηται, αἴτια τρόπον τινὰ τοῦ ἐκπεσεῖν ἐκ τοῦ ἐπιτηδεύματος, καὶ τὰ λεγόμενα ἀγαθά, πλοῦτοί τε καὶ πᾶσα ἡ τοιαύτη παρασκευή;","st":"495a"},{"sp":"N","t":"οὐ γάρ, ἀλλ᾽ ὀρθῶς, ἔφη, ἐλέχθη.","st":"495a"},{"sp":"N","t":"οὗτος δή, εἶπον, ὦ θαυμάσιε, ὄλεθρός τε καὶ διαφθορὰ","st":"495a"},{"sp":"N","t":"τοσαύτη τε καὶ τοιαύτη τῆς βελτίστης φύσεως εἰς τὸ ἄριστον ἐπιτήδευμα, ὀλίγης καὶ ἄλλως γιγνομένης, ὡς ἡμεῖς φαμεν. καὶ ἐκ τούτων δὴ τῶν ἀνδρῶν καὶ οἱ τὰ μέγιστα κακὰ ἐργαζόμενοι τὰς πόλεις γίγνονται καὶ τοὺς ἰδιώτας, καὶ οἱ τἀγαθά, οἳ ἂν ταύτῃ τύχωσι ῥυέντες: σμικρὰ δὲ φύσις οὐδὲν μέγα οὐδέποτε οὐδένα οὔτε ἰδιώτην οὔτε πόλιν δρᾷ.","st":"495b"},{"sp":"N","t":"ἀληθέστατα, ἦ δ᾽ ὅς.","st":"495b"},{"sp":"N","t":"οὗτοι μὲν δὴ οὕτως ἐκπίπτοντες, οἷς μάλιστα προσήκει,","st":"495b"},{"sp":"N","t":"ἔρημον καὶ ἀτελῆ φιλοσοφίαν λείποντες αὐτοί τε βίον οὐ προσήκοντα οὐδ᾽ ἀληθῆ ζῶσιν, τὴν δέ, ὥσπερ ὀρφανὴν συγγενῶν, ἄλλοι ἐπεισελθόντες ἀνάξιοι ᾔσχυνάν τε καὶ ὀνείδη περιῆψαν, οἷα καὶ σὺ φῂς ὀνειδίζειν τοὺς ὀνειδίζοντας, ὡς οἱ συνόντες αὐτῇ οἱ μὲν οὐδενός, οἱ δὲ πολλοὶ πολλῶν κακῶν ἄξιοί εἰσιν.","st":"495c"},{"sp":"N","t":"καὶ γὰρ οὖν, ἔφη, τά γε λεγόμενα ταῦτα.","st":"495c"},{"sp":"N","t":"εἰκότως γε, ἦν δ᾽ ἐγώ, λεγόμενα. καθορῶντες γὰρ ἄλλοι ἀνθρωπίσκοι κενὴν τὴν χώραν ταύτην γιγνομένην, καλῶν","st":"495c"},{"sp":"N","t":"δὲ ὀνομάτων καὶ προσχημάτων μεστήν, ὥσπερ οἱ ἐκ τῶν εἱργμῶν εἰς τὰ ἱερὰ ἀποδιδράσκοντες, ἅσμενοι καὶ οὗτοι ἐκ τῶν τεχνῶν ἐκπηδῶσιν εἰς τὴν φιλοσοφίαν, οἳ ἂν κομψότατοι ὄντες τυγχάνωσι περὶ τὸ αὑτῶν τεχνίον. ὅμως γὰρ δὴ πρός γε τὰς ἄλλας τέχνας καίπερ οὕτω πραττούσης φιλοσοφίας τὸ ἀξίωμα μεγαλοπρεπέστερον λείπεται, οὗ δὴ ἐφιέμενοι πολλοὶ ἀτελεῖς μὲν τὰς φύσεις, ὑπὸ δὲ τῶν τεχνῶν τε καὶ δημιουργιῶν ὥσπερ τὰ σώματα λελώβηνται, οὕτω","st":"495d"},{"sp":"N","t":"καὶ τὰς ψυχὰς συγκεκλασμένοι τε καὶ ἀποτεθρυμμένοι διὰ τὰς βαναυσίας τυγχάνουσιν — ἢ οὐκ ἀνάγκη;","st":"495e"},{"sp":"N","t":"καὶ μάλα, ἔφη.","st":"495e"},{"sp":"N","t":"δοκεῖς οὖν τι, ἦν δ᾽ ἐγώ, διαφέρειν αὐτοὺς ἰδεῖν ἀργύριον κτησαμένου χαλκέως φαλακροῦ καὶ σμικροῦ, νεωστὶ μὲν ἐκ δεσμῶν λελυμένου, ἐν βαλανείῳ δὲ λελουμένου, νεουογὸν ἱμάτιον ἔχοντος, ὡς νυμφίου παρεσκευασμένου, διὰ πενίαν καὶ ἐρημίαν τοῦ δεσπότου τὴν θυγατέρα μέλλοντος γαμεῖν;","st":"495e"},{"sp":"N","t":"οὐ πάνυ, ἔφη, διαφέρει.","st":"496a"},{"sp":"N","t":"ποῖ᾽ ἄττα οὖν εἰκὸς γεννᾶν τοὺς τοιούτους; οὐ νόθα καὶ φαῦλα;","st":"496a"},{"sp":"N","t":"πολλὴ ἀνάγκη.","st":"496a"},{"sp":"N","t":"τί δέ; τοὺς ἀναξίους παιδεύσεως, ὅταν αὐτῇ πλησιάζοντες ὁμιλῶσι μὴ κατ᾽ ἀξίαν, ποῖ᾽ ἄττα φῶμεν γεννᾶν διανοήματά τε καὶ δόξας; ἆρ᾽ οὐχ ὡς ἀληθῶς προσήκοντα ἀκοῦσαι σοφίσματα, καὶ οὐδὲν γνήσιον οὐδὲ φρονήσεως [ἄξιον] ἀληθινῆς ἐχόμενον;","st":"496a"},{"sp":"N","t":"παντελῶς μὲν οὖν, ἔφη.","st":"496a"},{"sp":"N","t":"πάνσμικρον δή τι, ἔφην ἐγώ, ὦ Ἀδείμαντε, λείπεται τῶν","st":"496a"},{"sp":"N","t":"κατ᾽ ἀξίαν ὁμιλούντων φιλοσοφίᾳ, ἤ που ὑπὸ φυγῆς καταληφθὲν γενναῖον καὶ εὖ τεθραμμένον ἦθος, ἀπορίᾳ τῶν διαφθερούντων κατὰ φύσιν μεῖναν ἐπ᾽ αὐτῇ, ἢ ἐν σμικρᾷ πόλει ὅταν μεγάλη ψυχὴ φυῇ καὶ ἀτιμάσασα τὰ τῆς πόλεως ὑπερίδῃ: βραχὺ δέ πού τι καὶ ἀπ᾽ ἄλλης τέχνης δικαίως ἀτιμάσαν εὐφυὲς ἐπ᾽ αὐτὴν ἂν ἔλθοι. εἴη δ᾽ ἂν καὶ ὁ τοῦ ἡμετέρου ἑταίρου Θεάγους χαλινὸς οἷος κατασχεῖν: καὶ γὰρ","st":"496b"},{"sp":"N","t":"Θεάγει τὰ μὲν ἄλλα πάντα παρεσκεύασται πρὸς τὸ ἐκπεσεῖν φιλοσοφίας, ἡ δὲ τοῦ σώματος νοσοτροφία ἀπείργουσα αὐτὸν τῶν πολιτικῶν κατέχει. τὸ δ᾽ ἡμέτερον οὐκ ἄξιον λέγειν, τὸ δαιμόνιον σημεῖον: ἢ γάρ πού τινι ἄλλῳ ἢ οὐδενὶ τῶν ἔμπροσθεν γέγονεν. καὶ τούτων δὴ τῶν ὀλίγων οἱ γενόμενοι καὶ γευσάμενοι ὡς ἡδὺ καὶ μακάριον τὸ κτῆμα, καὶ τῶν πολλῶν αὖ ἱκανῶς ἰδόντες τὴν μανίαν, καὶ ὅτι οὐδεὶς οὐδὲν ὑγιὲς ὡς ἔπος εἰπεῖν περὶ τὰ τῶν πόλεων πράττει οὐδ᾽ ἔστι","st":"496c"},{"sp":"N","t":"σύμμαχος μεθ᾽ ὅτου τις ἰὼν ἐπὶ τὴν τῷ δικαίῳ βοήθειαν σῴζοιτ᾽ ἄν, ἀλλ᾽ ὥσπερ εἰς θηρία ἄνθρωπος ἐμπεσών, οὔτε συναδικεῖν ἐθέλων οὔτε ἱκανὸς ὢν εἷς πᾶσιν ἀγρίοις ἀντέχειν, πρίν τι τὴν πόλιν ἢ φίλους ὀνῆσαι προαπολόμενος ἀνωφελὴς αὑτῷ τε καὶ τοῖς ἄλλοις ἂν γένοιτο — ταῦτα πάντα λογισμῷ λαβών, ἡσυχίαν ἔχων καὶ τὰ αὑτοῦ πράττων, οἷον ἐν χειμῶνι κονιορτοῦ καὶ ζάλης ὑπὸ πνεύματος φερομένου ὑπὸ τειχίον ἀποστάς, ὁρῶν τοὺς ἄλλους καταπιμπλαμένους ἀνομίας, ἀγαπᾷ εἴ πῃ αὐτὸς καθαρὸς ἀδικίας τε καὶ ἀνοσίων","st":"496d"},{"sp":"N","t":"ἔργων τόν τε ἐνθάδε βίον βιώσεται καὶ τὴν ἀπαλλαγὴν αὐτοῦ μετὰ καλῆς ἐλπίδος ἵλεώς τε καὶ εὐμενὴς ἀπαλλάξεται.","st":"496e"},{"sp":"N","t":"ἀλλά τοι, ἦ δ᾽ ὅς, οὐ τὰ ἐλάχιστα ἂν διαπραξάμενος ἀπαλλάττοιτο.","st":"497a"},{"sp":"N","t":"οὐδέ γε, εἶπον, τὰ μέγιστα, μὴ τυχὼν πολιτείας προσηκούσης: ἐν γὰρ προσηκούσῃ αὐτός τε μᾶλλον αὐξήσεται καὶ μετὰ τῶν ἰδίων τὰ κοινὰ σώσει.","st":"497a"},{"sp":"N","t":"τὸ μὲν οὖν τῆς φιλοσοφίας ὧν ἕνεκα διαβολὴν εἴληφεν καὶ ὅτι οὐ δικαίως, ἐμοὶ μὲν δοκεῖ μετρίως εἰρῆσθαι, εἰ μὴ ἔτ᾽ ἄλλο λέγεις τι σύ.","st":"497a"},{"sp":"N","t":"ἀλλ᾽ οὐδέν, ἦ δ᾽ ὅς, ἔτι λέγω περὶ τούτου: ἀλλὰ τὴν προσήκουσαν αὐτῇ τίνα τῶν νῦν λέγεις πολιτειῶν;","st":"497a"},{"sp":"N","t":"οὐδ᾽ ἡντινοῦν, εἶπον, ἀλλὰ τοῦτο καὶ ἐπαιτιῶμαι, μηδεμίαν ἀξίαν εἶναι τῶν νῦν κατάστασιν πόλεως φιλοσόφου φύσεως: διὸ καὶ στρέφεσθαί τε καὶ ἀλλοιοῦσθαι αὐτήν, ὥσπερ ξενικὸν σπέρμα ἐν γῇ ἄλλῃ σπειρόμενον ἐξίτηλον εἰς τὸ ἐπιχώριον φιλεῖ κρατούμενον ἰέναι, οὕτω καὶ τοῦτο τὸ γένος νῦν μὲν οὐκ ἴσχειν τὴν αὑτοῦ δύναμιν, ἀλλ᾽ εἰς ἀλλότριον ἦθος ἐκπίπτειν: εἰ δὲ λήψεται τὴν ἀρίστην πολιτείαν, ὥσπερ","st":"497b"},{"sp":"N","t":"καὶ αὐτὸ ἄριστόν ἐστιν, τότε δηλώσει ὅτι τοῦτο μὲν τῷ ὄντι θεῖον ἦν, τὰ δὲ ἄλλα ἀνθρώπινα, τά τε τῶν φύσεων καὶ τῶν ἐπιτηδευμάτων. δῆλος δὴ οὖν εἶ ὅτι μετὰ τοῦτο ἐρήσῃ τίς αὕτη ἡ πολιτεία.","st":"497c"},{"sp":"N","t":"οὐκ ἔγνως, ἔφη: οὐ γὰρ τοῦτο ἔμελλον, ἀλλ᾽ εἰ αὑτὴ ἣν ἡμεῖς διεληλύθαμεν οἰκίζοντες τὴν πόλιν ἢ ἄλλη.","st":"497c"},{"sp":"N","t":"τὰ μὲν ἄλλα, ἦν δ᾽ ἐγώ, αὕτη: τοῦτο δὲ αὐτὸ ἐρρήθη μὲν καὶ τότε, ὅτι δεήσοι τι ἀεὶ ἐνεῖναι ἐν τῇ πόλει λόγον","st":"497c"},{"sp":"N","t":"ἔχον τῆς πολιτείας τὸν αὐτὸν ὅνπερ καὶ σὺ ὁ νομοθέτης ἔχων τοὺς νόμους ἐτίθεις.","st":"497d"},{"sp":"N","t":"ἐρρήθη γάρ, ἔφη.","st":"497d"},{"sp":"N","t":"ἀλλ᾽ οὐχ ἱκανῶς, εἶπον, ἐδηλώθη, φόβῳ ὧν ὑμεῖς ἀντιλαμβανόμενοι δεδηλώκατε μακρὰν καὶ χαλεπὴν αὐτοῦ τὴν ἀπόδειξιν: ἐπεὶ καὶ τὸ λοιπὸν οὐ πάντων ῥᾷστον διελθεῖν.","st":"497d"},{"sp":"N","t":"τὸ ποῖον;","st":"497d"},{"sp":"N","t":"τίνα τρόπον μεταχειριζομένη πόλις φιλοσοφίαν οὐ διολεῖται. τὰ γὰρ δὴ μεγάλα πάντα ἐπισφαλῆ, καὶ τὸ λεγόμενον τὰ καλὰ τῷ ὄντι χαλεπά.","st":"497d"},{"sp":"N","t":"ἀλλ᾽ ὅμως, ἔφη, λαβέτω τέλος ἡ ἀπόδειξις τούτου φανεροῦ γενομένου.","st":"497e"},{"sp":"N","t":"οὐ τὸ μὴ βούλεσθαι, ἦν δ᾽ ἐγώ, ἀλλ᾽ εἴπερ, τὸ μὴ δύνασθαι διακωλύσει: παρὼν δὲ τήν γ᾽ ἐμὴν προθυμίαν εἴσῃ. σκόπει δὲ καὶ νῦν ὡς προθύμως καὶ παρακινδυνευτικῶς μέλλω λέγειν, ὅτι τοὐναντίον ἢ νῦν δεῖ τοῦ ἐπιτηδεύματος τούτου πόλιν ἅπτεσθαι.","st":"497e"},{"sp":"N","t":"πῶς;","st":"497e"},{"sp":"N","t":"νῦν μέν, ἦν δ᾽ ἐγώ, οἱ καὶ ἁπτόμενοι μειράκια ὄντα ἄρτι","st":"497e"},{"sp":"N","t":"ἐκ παίδων τὸ μεταξὺ οἰκονομίας καὶ χρηματισμοῦ πλησιάσαντες αὐτοῦ τῷ χαλεπωτάτῳ ἀπαλλάττονται, οἱ φιλοσοφώτατοι ποιούμενοι — λέγω δὲ χαλεπώτατον τὸ περὶ τοὺς λόγους -ἐν δὲ τῷ ἔπειτα, ἐὰν καὶ ἄλλων τοῦτο πραττόντων παρακαλούμενοι ἐθέλωσιν ἀκροαταὶ γίγνεσθαι, μεγάλα ἡγοῦνται, πάρεργον οἰόμενοι αὐτὸ δεῖν πράττειν: πρὸς δὲ τὸ γῆρας ἐκτὸς δή τινων ὀλίγων ἀποσβέννυνται πολὺ μᾶλλον τοῦ","st":"498a"},{"sp":"N","t":"Ἡρακλειτείου ἡλίου, ὅσον αὖθις οὐκ ἐξάπτονται.","st":"498b"},{"sp":"N","t":"δεῖ δὲ πῶς; ἔφη.","st":"498b"},{"sp":"N","t":"πᾶν τοὐναντίον: μειράκια μὲν ὄντα καὶ παῖδας μειρακιώδη παιδείαν καὶ φιλοσοφίαν μεταχειρίζεσθαι, τῶν τε σωμάτων, ἐν ᾧ βλαστάνει τε καὶ ἀνδροῦται, εὖ μάλα ἐπιμελεῖσθαι, ὑπηρεσίαν φιλοσοφίᾳ κτωμένους: προϊούσης δὲ τῆς ἡλικίας, ἐν ᾗ ἡ ψυχὴ τελεοῦσθαι ἄρχεται, ἐπιτείνειν τὰ ἐκείνης γυμνάσια: ὅταν δὲ λήγῃ μὲν ἡ ῥώμη, πολιτικῶν δὲ καὶ","st":"498b"},{"sp":"N","t":"στρατειῶν ἐκτὸς γίγνηται, τότε ἤδη ἀφέτους νέμεσθαι καὶ μηδὲν ἄλλο πράττειν, ὅτι μὴ πάρεργον, τοὺς μέλλοντας εὐδαιμόνως βιώσεσθαι καὶ τελευτήσαντας τῷ βίῳ τῷ βεβιωμένῳ τὴν ἐκεῖ μοῖραν ἐπιστήσειν πρέπουσαν.","st":"498c"},{"sp":"N","t":"ὡς ἀληθῶς μοι δοκεῖς, ἔφη, λέγειν γε προθύμως, ὦ Σώκρατες: οἶμαι μέντοι τοὺς πολλοὺς τῶν ἀκουόντων προθυμότερον ἔτι ἀντιτείνειν οὐδ᾽ ὁπωστιοῦν πεισομένους, ἀπὸ Θρασυμάχου ἀρξαμένους.","st":"498c"},{"sp":"N","t":"μὴ διάβαλλε, ἦν δ᾽ ἐγώ, ἐμὲ καὶ Θρασύμαχον ἄρτι","st":"498c"},{"sp":"N","t":"φίλους γεγονότας, οὐδὲ πρὸ τοῦ ἐχθροὺς ὄντας. πείρας γὰρ οὐδὲν ἀνήσομεν, ἕως ἂν ἢ πείσωμεν καὶ τοῦτον καὶ τοὺς ἄλλους, ἢ προὔργου τι ποιήσωμεν εἰς ἐκεῖνον τὸν βίον, ὅταν αὖθις γενόμενοι τοῖς τοιούτοις ἐντύχωσι λόγοις.","st":"498d"},{"sp":"N","t":"εἰς μικρόν γ᾽, ἔφη, χρόνον εἴρηκας.","st":"498d"},{"sp":"N","t":"εἰς οὐδὲν μὲν οὖν, ἔφην, ὥς γε πρὸς τὸν ἅπαντα. τὸ μέντοι μὴ πείθεσθαι τοῖς λεγομένοις τοὺς πολλοὺς θαῦμα οὐδέν: οὐ γὰρ πώποτε εἶδον γενόμενον τὸ νῦν λεγόμενον,","st":"498d"},{"sp":"N","t":"ἀλλὰ πολὺ μᾶλλον τοιαῦτ᾽ ἄττα ῥήματα ἐξεπίτηδες ἀλλήλοις ὡμοιωμένα, ἀλλ᾽ οὐκ ἀπὸ τοῦ αὐτομάτου ὥσπερ νῦν συμπεσόντα. ἄνδρα δὲ ἀρετῇ παρισωμένον καὶ ὡμοιωμένον μέχρι τοῦ δυνατοῦ τελέως ἔργῳ τε καὶ λόγῳ, δυναστεύοντα","st":"498e"},{"sp":"N","t":"ἐν πόλει ἑτέρᾳ τοιαύτῃ, οὐ πώποτε ἑωράκασιν, οὔτε ἕνα οὔτε πλείους. ἢ οἴει;","st":"499a"},{"sp":"N","t":"οὐδαμῶς γε.","st":"499a"},{"sp":"N","t":"οὐδέ γε αὖ λόγων, ὦ μακάριε, καλῶν τε καὶ ἐλευθέρων ἱκανῶς ἐπήκοοι γεγόνασιν, οἵων ζητεῖν μὲν τὸ ἀληθὲς συντεταμένως ἐκ παντὸς τρόπου τοῦ γνῶναι χάριν, τὰ δὲ κομψά τε καὶ ἐριστικὰ καὶ μηδαμόσε ἄλλοσε τείνοντα ἢ πρὸς δόξαν καὶ ἔριν καὶ ἐν δίκαις καὶ ἐν ἰδίαις συνουσίαις πόρρωθεν ἀσπαζομένων.","st":"499a"},{"sp":"N","t":"οὐδὲ τούτων, ἔφη.","st":"499a"},{"sp":"N","t":"τούτων τοι χάριν, ἦν δ᾽ ἐγώ, καὶ ταῦτα προορώμενοι","st":"499a"},{"sp":"N","t":"ἡμεῖς τότε καὶ δεδιότες ὅμως ἐλέγομεν, ὑπὸ τἀληθοῦς ἠναγκασμένοι, ὅτι οὔτε πόλις οὔτε πολιτεία οὐδέ γ᾽ ἀνὴρ ὁμοίως μή ποτε γένηται τέλεος, πρὶν ἂν τοῖς φιλοσόφοις τούτοις τοῖς ὀλίγοις καὶ οὐ πονηροῖς, ἀχρήστοις δὲ νῦν κεκλημένοις, ἀνάγκη τις ἐκ τύχης περιβάλῃ, εἴτε βούλονται εἴτε μή, πόλεως ἐπιμεληθῆναι, καὶ τῇ πόλει κατηκόῳ γενέσθαι, ἢ τῶν νῦν ἐν δυναστείαις ἢ βασιλείαις ὄντων ὑέσιν ἢ αὐτοῖς","st":"499b"},{"sp":"N","t":"ἔκ τινος θείας ἐπιπνοίας ἀληθινῆς φιλοσοφίας ἀληθινὸς ἔρως ἐμπέσῃ. τούτων δὲ πότερα γενέσθαι ἢ ἀμφότερα ὡς ἄρα ἐστὶν ἀδύνατον, ἐγὼ μὲν οὐδένα φημὶ ἔχειν λόγον. οὕτω γὰρ ἂν ἡμεῖς δικαίως καταγελῴμεθα, ὡς ἄλλως εὐχαῖς ὅμοια λέγοντες. ἢ οὐχ οὕτως;","st":"499c"},{"sp":"N","t":"οὕτως.","st":"499c"},{"sp":"N","t":"εἰ τοίνυν ἄκροις εἰς φιλοσοφίαν πόλεώς τις ἀνάγκη ἐπιμεληθῆναι ἢ γέγονεν ἐν τῷ ἀπείρῳ τῷ παρεληλυθότι χρόνῳ ἢ καὶ νῦν ἔστιν ἔν τινι βαρβαρικῷ τόπῳ, πόρρω που","st":"499c"},{"sp":"N","t":"ἐκτὸς ὄντι τῆς ἡμετέρας ἐπόψεως, ἢ καὶ ἔπειτα γενήσεται, περὶ τούτου ἕτοιμοι τῷ λόγῳ διαμάχεσθαι, ὡς γέγονεν ἡ εἰρημένη πολιτεία καὶ ἔστιν καὶ γενήσεταί γε, ὅταν αὕτη ἡ Μοῦσα πόλεως ἐγκρατὴς γένηται. οὐ γὰρ ἀδύνατος γενέσθαι, οὐδ᾽ ἡμεῖς ἀδύνατα λέγομεν: χαλεπὰ δὲ καὶ παρ᾽ ἡμῶν ὁμολογεῖται.","st":"499d"},{"sp":"N","t":"καὶ ἐμοί, ἔφη, οὕτω δοκεῖ.","st":"499d"},{"sp":"N","t":"τοῖς δὲ πολλοῖς, ἦν δ᾽ ἐγώ, ὅτι οὐκ αὖ δοκεῖ, ἐρεῖς;","st":"499d"},{"sp":"N","t":"ἴσως, ἔφη.","st":"499d"},{"sp":"N","t":"ὦ μακάριε, ἦν δ᾽ ἐγώ, μὴ πάνυ οὕτω τῶν πολλῶν κατηγόρει.","st":"499d"},{"sp":"N","t":"ἀλλοίαν τοι δόξαν ἕξουσιν, ἐὰν αὐτοῖς μὴ φιλονικῶν ἀλλὰ παραμυθούμενος καὶ ἀπολυόμενος τὴν τῆς φιλομαθείας διαβολὴν ἐνδεικνύῃ οὓς λέγεις τοὺς φιλοσόφους, καὶ διορίζῃ","st":"499e"},{"sp":"N","t":"ὥσπερ ἄρτι τήν τε φύσιν αὐτῶν καὶ τὴν ἐπιτήδευσιν, ἵνα μὴ ἡγῶνταί σε λέγειν οὓς αὐτοὶ οἴονται. [ἢ καὶ ἐὰν οὕτω θεῶνται, ἀλλοίαν τοι φήσεις αὐτοὺς δόξαν λήψεσθαι καὶ ἄλλα ἀποκρινεῖσθαι.] ἢ οἴει τινὰ χαλεπαίνειν τῷ μὴ χαλεπῷ ἢ φθονεῖν τῷ μὴ φθονερῷ ἄφθονόν τε καὶ πρᾷον ὄντα; ἐγὼ μὲν γάρ σε προφθάσας λέγω ὅτι ἐν ὀλίγοις τισὶν ἡγοῦμαι, ἀλλ᾽ οὐκ ἐν τῷ πλήθει, χαλεπὴν οὕτω φύσιν γίγνεσθαι.","st":"500a"},{"sp":"N","t":"καὶ ἐγὼ ἀμέλει, ἔφη, συνοίομαι.","st":"500a"},{"sp":"N","t":"οὐκοῦν καὶ αὐτὸ τοῦτο συνοίει, τοῦ χαλεπῶς πρὸς φιλοσοφίαν τοὺς πολλοὺς διακεῖσθαι ἐκείνους αἰτίους εἶναι τοὺς ἔξωθεν οὐ προσῆκον ἐπεισκεκωμακότας, λοιδορουμένους τε αὑτοῖς καὶ φιλαπεχθημόνως ἔχοντας καὶ ἀεὶ περὶ ἀνθρώπων τοὺς λόγους ποιουμένους, ἥκιστα φιλοσοφίᾳ πρέπον ποιοῦντας;","st":"500b"},{"sp":"N","t":"πολύ γ᾽, ἔφη.","st":"500b"},{"sp":"N","t":"οὐδὲ γάρ που, ὦ Ἀδείμαντε, σχολὴ τῷ γε ὡς ἀληθῶς πρὸς τοῖς οὖσι τὴν διάνοιαν ἔχοντι κάτω βλέπειν εἰς ἀνθρώπων","st":"500b"},{"sp":"N","t":"πραγματείας, καὶ μαχόμενον αὐτοῖς φθόνου τε καὶ δυσμενείας ἐμπίμπλασθαι, ἀλλ᾽ εἰς τεταγμένα ἄττα καὶ κατὰ ταὐτὰ ἀεὶ ἔχοντα ὁρῶντας καὶ θεωμένους οὔτ᾽ ἀδικοῦντα οὔτ᾽ ἀδικούμενα ὑπ᾽ ἀλλήλων, κόσμῳ δὲ πάντα καὶ κατὰ λόγον ἔχοντα, ταῦτα μιμεῖσθαί τε καὶ ὅτι μάλιστα ἀφομοιοῦσθαι. ἢ οἴει τινὰ μηχανὴν εἶναι, ὅτῳ τις ὁμιλεῖ ἀγάμενος, μὴ μιμεῖσθαι ἐκεῖνο;","st":"500c"},{"sp":"N","t":"ἀδύνατον, ἔφη.","st":"500c"},{"sp":"N","t":"θείῳ δὴ καὶ κοσμίῳ ὅ γε φιλόσοφος ὁμιλῶν κόσμιός τε","st":"500c"},{"sp":"N","t":"καὶ θεῖος εἰς τὸ δυνατὸν ἀνθρώπῳ γίγνεται: διαβολὴ δ᾽ ἐν πᾶσι πολλή.","st":"500d"},{"sp":"N","t":"παντάπασι μὲν οὖν.","st":"500d"},{"sp":"N","t":"ἂν οὖν τις, εἶπον, αὐτῷ ἀνάγκη γένηται ἃ ἐκεῖ ὁρᾷ μελετῆσαι εἰς ἀνθρώπων ἤθη καὶ ἰδίᾳ καὶ δημοσίᾳ τιθέναι καὶ μὴ μόνον ἑαυτὸν πλάττειν, ἆρα κακὸν δημιουργὸν αὐτὸν οἴει γενήσεσθαι σωφροσύνης τε καὶ δικαιοσύνης καὶ συμπάσης τῆς δημοτικῆς ἀρετῆς;","st":"500d"},{"sp":"N","t":"ἥκιστά γε, ἦ δ᾽ ὅς.","st":"500d"},{"sp":"N","t":"ἀλλ᾽ ἐὰν δὴ αἴσθωνται οἱ πολλοὶ ὅτι ἀληθῆ περὶ αὐτοῦ","st":"500d"},{"sp":"N","t":"λέγομεν, χαλεπανοῦσι δὴ τοῖς φιλοσόφοις καὶ ἀπιστήσουσιν ἡμῖν λέγουσιν ὡς οὐκ ἄν ποτε ἄλλως εὐδαιμονήσειε πόλις, εἰ μὴ αὐτὴν διαγράψειαν οἱ τῷ θείῳ παραδείγματι χρώμενοι ζωγράφοι;","st":"500e"},{"sp":"N","t":"οὐ χαλεπανοῦσιν, ἦ δ᾽ ὅς, ἐάνπερ αἴσθωνται. ἀλλὰ δὴ","st":"500e"},{"sp":"N","t":"τίνα λέγεις τρόπον τῆς διαγραφῆς;","st":"501a"},{"sp":"N","t":"λαβόντες, ἦν δ᾽ ἐγώ, ὥσπερ πίνακα πόλιν τε καὶ ἤθη ἀνθρώπων, πρῶτον μὲν καθαρὰν ποιήσειαν ἄν, ὃ οὐ πάνυ ῥᾴδιον: ἀλλ᾽ οὖν οἶσθ᾽ ὅτι τούτῳ ἂν εὐθὺς τῶν ἄλλων διενέγκοιεν, τῷ μήτε ἰδιώτου μήτε πόλεως ἐθελῆσαι ἂν ἅψασθαι μηδὲ γράφειν νόμους, πρὶν ἢ παραλαβεῖν καθαρὰν ἢ αὐτοὶ ποιῆσαι.","st":"501a"},{"sp":"N","t":"καὶ ὀρθῶς γ᾽, ἔφη.","st":"501a"},{"sp":"N","t":"οὐκοῦν μετὰ ταῦτα οἴει ὑπογράψασθαι ἂν τὸ σχῆμα τῆς πολιτείας;","st":"501a"},{"sp":"N","t":"τί μήν;","st":"501a"},{"sp":"N","t":"ἔπειτα οἶμαι ἀπεργαζόμενοι πυκνὰ ἂν ἑκατέρωσ᾽ ἀποβλέποιεν, πρός τε τὸ φύσει δίκαιον καὶ καλὸν καὶ σῶφρον καὶ πάντα τὰ τοιαῦτα, καὶ πρὸς ἐκεῖν᾽ αὖ τὸ ἐν τοῖς ἀνθρώποις ἐμποιοῖεν, συμμειγνύντες τε καὶ κεραννύντες ἐκ τῶν ἐπιτηδευμάτων τὸ ἀνδρείκελον, ἀπ᾽ ἐκείνου τεκμαιρόμενοι, ὃ δὴ καὶ Ὅμηρος ἐκάλεσεν ἐν τοῖς ἀνθρώποις ἐγγιγνόμενον θεοειδές τε καὶ θεοείκελον.","st":"501b"},{"sp":"N","t":"ὀρθῶς, ἔφη.","st":"501b"},{"sp":"N","t":"καὶ τὸ μὲν ἂν οἶμαι ἐξαλείφοιεν, τὸ δὲ πάλιν ἐγγράφοιεν,","st":"501b"},{"sp":"N","t":"ἕως ὅτι μάλιστα ἀνθρώπεια ἤθη εἰς ὅσον ἐνδέχεται θεοφιλῆ ποιήσειαν.","st":"501c"},{"sp":"N","t":"καλλίστη γοῦν ἄν, ἔφη, ἡ γραφὴ γένοιτο.","st":"501c"},{"sp":"N","t":"ἆρ᾽ οὖν, ἦν δ᾽ ἐγώ, πείθομέν πῃ ἐκείνους, οὓς διατεταμένους ἐφ᾽ ἡμᾶς ἔφησθα ἰέναι, ὡς τοιοῦτός ἐστι πολιτειῶν ζωγράφος ὃν τότ᾽ ἐπῃνοῦμεν πρὸς αὐτούς, δι᾽ ὃν ἐκεῖνοι ἐχαλέπαινον ὅτι τὰς πόλεις αὐτῷ παρεδίδομεν, καί τι μᾶλλον αὐτὸ νῦν ἀκούοντες πραΰνονται;","st":"501c"},{"sp":"N","t":"καὶ πολύ γε, ἦ δ᾽ ὅς, εἰ σωφρονοῦσιν.","st":"501c"},{"sp":"N","t":"πῇ γὰρ δὴ ἕξουσιν ἀμφισβητῆσαι; πότερον μὴ τοῦ ὄντος τε καὶ ἀληθείας ἐραστὰς εἶναι τοὺς φιλοσόφους;","st":"501d"},{"sp":"N","t":"ἄτοπον μεντἄν, ἔφη, εἴη.","st":"501d"},{"sp":"N","t":"ἀλλὰ μὴ τὴν φύσιν αὐτῶν οἰκείαν εἶναι τοῦ ἀρίστου, ἣν ἡμεῖς διήλθομεν;","st":"501d"},{"sp":"N","t":"οὐδὲ τοῦτο.","st":"501d"},{"sp":"N","t":"τί δέ; τὴν τοιαύτην τυχοῦσαν τῶν προσηκόντων ἐπιτηδευμάτων οὐκ ἀγαθὴν τελέως ἔσεσθαι καὶ φιλόσοφον, εἴπερ τινὰ ἄλλην; ἢ ἐκείνους φήσει μᾶλλον, οὓς ἡμεῖς ἀφωρίσαμεν;","st":"501d"},{"sp":"N","t":"οὐ δήπου.","st":"501e"},{"sp":"N","t":"ἔτι οὖν ἀγριανοῦσι λεγόντων ἡμῶν ὅτι πρὶν ἂν πόλεως τὸ φιλόσοφον γένος ἐγκρατὲς γένηται, οὔτε πόλει οὔτε πολίταις κακῶν παῦλα ἔσται, οὐδὲ ἡ πολιτεία ἣν μυθολογοῦμεν λόγῳ ἔργῳ τέλος λήψεται;","st":"501e"},{"sp":"N","t":"ἴσως, ἔφη, ἧττον.","st":"501e"},{"sp":"N","t":"βούλει οὖν, ἦν δ᾽ ἐγώ, μὴ ἧττον φῶμεν αὐτοὺς ἀλλὰ","st":"501e"},{"sp":"N","t":"παντάπασι πρᾴους γεγονέναι καὶ πεπεῖσθαι, ἵνα, εἰ μή τι, ἀλλὰ αἰσχυνθέντες ὁμολογήσωσιν;","st":"502a"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη.","st":"502a"},{"sp":"N","t":"οὗτοι μὲν τοίνυν, ἦν δ᾽ ἐγώ, τοῦτο πεπεισμένοι ἔστων: τοῦδε δὲ πέρι τις ἀμφισβητήσει, ὡς οὐκ ἂν τύχοιεν γενόμενοι βασιλέων ἔκγονοι ἢ δυναστῶν τὰς φύσεις φιλόσοφοι;","st":"502a"},{"sp":"N","t":"οὐδ᾽ ἂν εἷς, ἔφη.","st":"502a"},{"sp":"N","t":"τοιούτους δὲ γενομένους ὡς πολλὴ ἀνάγκη διαφθαρῆναι, ἔχει τις λέγειν; ὡς μὲν γὰρ χαλεπὸν σωθῆναι, καὶ ἡμεῖς","st":"502a"},{"sp":"N","t":"συγχωροῦμεν: ὡς δὲ ἐν παντὶ τῷ χρόνῳ τῶν πάντων οὐδέποτε οὐδ᾽ ἂν εἷς σωθείη, ἔσθ᾽ ὅστις ἀμφισβητήσειε;","st":"502b"},{"sp":"N","t":"καὶ πῶς;","st":"502b"},{"sp":"N","t":"ἀλλὰ μήν, ἦν δ᾽ ἐγώ, εἷς ἱκανὸς γενόμενος, πόλιν ἔχων πειθομένην, πάντ᾽ ἐπιτελέσαι τὰ νῦν ἀπιστούμενα.","st":"502b"},{"sp":"N","t":"ἱκανὸς γάρ, ἔφη.","st":"502b"},{"sp":"N","t":"ἄρχοντος γάρ που, ἦν δ᾽ ἐγώ, τιθέντος τοὺς νόμους καὶ τὰ ἐπιτηδεύματα ἃ διεληλύθαμεν, οὐ δήπου ἀδύνατον ἐθέλειν ποιεῖν τοὺς πολίτας.","st":"502b"},{"sp":"N","t":"οὐδ᾽ ὁπωστιοῦν.","st":"502b"},{"sp":"N","t":"ἀλλὰ δή, ἅπερ ἡμῖν δοκεῖ, δόξαι καὶ ἄλλοις θαυμαστόν τι καὶ ἀδύνατον;","st":"502b"},{"sp":"N","t":"οὐκ οἶμαι ἔγωγε, ἦ δ᾽ ὅς.","st":"502c"},{"sp":"N","t":"καὶ μὴν ὅτι γε βέλτιστα, εἴπερ δυνατά, ἱκανῶς ἐν τοῖς ἔμπροσθεν, ὡς ἐγᾦμαι, διήλθομεν.","st":"502c"},{"sp":"N","t":"ἱκανῶς γάρ.","st":"502c"},{"sp":"N","t":"νῦν δή, ὡς ἔοικεν, συμβαίνει ἡμῖν περὶ τῆς νομοθεσίας ἄριστα μὲν εἶναι ἃ λέγομεν, εἰ γένοιτο, χαλεπὰ δὲ γενέσθαι, οὐ μέντοι ἀδύνατά γε.","st":"502c"},{"sp":"N","t":"συμβαίνει γάρ, ἔφη.","st":"502c"},{"sp":"N","t":"οὐκοῦν ἐπειδὴ τοῦτο μόγις τέλος ἔσχεν, τὰ ἐπίλοιπα δὴ μετὰ τοῦτο λεκτέον, τίνα τρόπον ἡμῖν καὶ ἐκ τίνων μαθημάτων","st":"502c"},{"sp":"N","t":"τε καὶ ἐπιτηδευμάτων οἱ σωτῆρες ἐνέσονται τῆς πολιτείας, καὶ κατὰ ποίας ἡλικίας ἕκαστοι ἑκάστων ἁπτόμενοι;","st":"502d"},{"sp":"N","t":"λεκτέον μέντοι, ἔφη.","st":"502d"},{"sp":"N","t":"οὐδέν, ἦν δ᾽ ἐγώ, τὸ σοφόν μοι ἐγένετο τήν τε τῶν γυναικῶν τῆς κτήσεως δυσχέρειαν ἐν τῷ πρόσθεν παραλιπόντι καὶ παιδογονίαν καὶ τὴν τῶν ἀρχόντων κατάστασιν, εἰδότι ὡς ἐπίφθονός τε καὶ χαλεπὴ γίγνεσθαι ἡ παντελῶς ἀληθής: νῦν γὰρ οὐδὲν ἧττον ἦλθεν τὸ δεῖν αὐτὰ διελθεῖν.","st":"502d"},{"sp":"N","t":"καὶ τὰ μὲν δὴ τῶν γυναικῶν τε καὶ παίδων πεπέρανται, τὸ δὲ τῶν ἀρχόντων ὥσπερ ἐξ ἀρχῆς μετελθεῖν δεῖ. ἐλέγομεν","st":"502e"},{"sp":"N","t":"δ᾽, εἰ μνημονεύεις, δεῖν αὐτοὺς φιλοπόλιδάς τε φαίνεσθαι, βασανιζομένους ἐν ἡδοναῖς τε καὶ λύπαις, καὶ τὸ δόγμα τοῦτο μήτ᾽ ἐν πόνοις μήτ᾽ ἐν φόβοις μήτ᾽ ἐν ἄλλῃ μηδεμιᾷ μεταβολῇ φαίνεσθαι ἐκβάλλοντας, ἢ τὸν ἀδυνατοῦντα ἀποκριτέον, τὸν δὲ πανταχοῦ ἀκήρατον ἐκβαίνοντα ὥσπερ χρυσὸν ἐν πυρὶ βασανιζόμενον, στατέον ἄρχοντα καὶ γέρα δοτέον καὶ ζῶντι καὶ τελευτήσαντι καὶ ἆθλα. τοιαῦτ᾽ ἄττα ἦν τὰ λεγόμενα παρεξιόντος καὶ παρακαλυπτομένου τοῦ","st":"503a"},{"sp":"N","t":"λόγου, πεφοβημένου κινεῖν τὸ νῦν παρόν.","st":"503b"},{"sp":"N","t":"ἀληθέστατα, ἔφη, λέγεις: μέμνημαι γάρ.","st":"503b"},{"sp":"N","t":"ὄκνος γάρ, ἔφην, ὦ φίλε, ἐγώ, εἰπεῖν τὰ νῦν ἀποτετολμημένα: νῦν δὲ τοῦτο μὲν τετολμήσθω εἰπεῖν, ὅτι τοὺς ἀκριβεστάτους φύλακας φιλοσόφους δεῖ καθιστάναι.","st":"503b"},{"sp":"N","t":"εἰρήσθω γάρ, ἔφη.","st":"503b"},{"sp":"N","t":"νόησον δὴ ὡς εἰκότως ὀλίγοι ἔσονταί σοι: ἣν γὰρ διήλθομεν φύσιν δεῖν ὑπάρχειν αὐτοῖς, εἰς ταὐτὸν συμφύεσθαι αὐτῆς τὰ μέρη ὀλιγάκις ἐθέλει, τὰ πολλὰ δὲ διεσπασμένη φύεται.","st":"503b"},{"sp":"N","t":"πῶς, ἔφη, λέγεις;","st":"503c"},{"sp":"N","t":"εὐμαθεῖς καὶ μνήμονες καὶ ἀγχίνοι καὶ ὀξεῖς καὶ ὅσα ἄλλα τούτοις ἕπεται οἶσθ᾽ ὅτι οὐκ ἐθέλουσιν ἅμα φύεσθαι καὶ νεανικοί τε καὶ μεγαλοπρεπεῖς τὰς διανοίας οἷοι κοσμίως μετὰ ἡσυχίας καὶ βεβαιότητος ἐθέλειν ζῆν, ἀλλ᾽ οἱ τοιοῦτοι ὑπὸ ὀξύτητος φέρονται ὅπῃ ἂν τύχωσιν, καὶ τὸ βέβαιον ἅπαν αὐτῶν ἐξοίχεται.","st":"503c"},{"sp":"N","t":"ἀληθῆ, ἔφη, λέγεις.","st":"503c"},{"sp":"N","t":"οὐκοῦν τὰ βέβαια αὖ ταῦτα ἤθη καὶ οὐκ εὐμετάβολα, οἷς","st":"503c"},{"sp":"N","t":"ἄν τις μᾶλλον ὡς πιστοῖς χρήσαιτο, καὶ ἐν τῷ πολέμῳ πρὸς τοὺς φόβους δυσκίνητα ὄντα, πρὸς τὰς μαθήσεις αὖ ποιεῖ ταὐτόν: δυσκινήτως ἔχει καὶ δυσμαθῶς ὥσπερ ἀπονεναρκωμένα, καὶ ὕπνου τε καὶ χάσμης ἐμπίμπλανται, ὅταν τι δέῃ τοιοῦτον διαπονεῖν.","st":"503d"},{"sp":"N","t":"ἔστι ταῦτα, ἔφη.","st":"503d"},{"sp":"N","t":"ἡμεῖς δέ γέ φαμεν ἀμφοτέρων δεῖν εὖ τε καὶ καλῶς μετέχειν, ἢ μήτε παιδείας τῆς ἀκριβεστάτης δεῖν αὐτῷ μεταδιδόναι μήτε τιμῆς μήτε ἀρχῆς.","st":"503d"},{"sp":"N","t":"ὀρθῶς, ἦ δ᾽ ὅς.","st":"503d"},{"sp":"N","t":"οὐκοῦν σπάνιον αὐτὸ οἴει ἔσεσθαι;","st":"503d"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"503d"},{"sp":"N","t":"βασανιστέον δὴ ἔν τε οἷς τότε ἐλέγομεν πόνοις τε καὶ φόβοις καὶ ἡδοναῖς, καὶ ἔτι δὴ ὃ τότε παρεῖμεν νῦν λέγομεν, ὅτι καὶ ἐν μαθήμασι πολλοῖς γυμνάζειν δεῖ, σκοποῦντας εἰ καὶ τὰ μέγιστα μαθήματα δυνατὴ ἔσται ἐνεγκεῖν εἴτε καὶ","st":"503e"},{"sp":"N","t":"ἀποδειλιάσει, ὥσπερ οἱ ἐν τοῖς ἄλλοις ἀποδειλιῶντες.","st":"504a"},{"sp":"N","t":"πρέπει γέ τοι δή, ἔφη, οὕτω σκοπεῖν. ἀλλὰ ποῖα δὴ λέγεις μαθήματα μέγιστα;","st":"504a"},{"sp":"N","t":"μνημονεύεις μέν που, ἦν δ᾽ ἐγώ, ὅτι τριττὰ εἴδη ψυχῆς διαστησάμενοι συνεβιβάζομεν δικαιοσύνης τε πέρι καὶ σωφροσύνης καὶ ἀνδρείας καὶ σοφίας ὃ ἕκαστον εἴη.","st":"504a"},{"sp":"N","t":"μὴ γὰρ μνημονεύων, ἔφη, τὰ λοιπὰ ἂν εἴην δίκαιος μὴ ἀκούειν.","st":"504a"},{"sp":"N","t":"ἦ καὶ τὸ προρρηθὲν αὐτῶν;","st":"504a"},{"sp":"N","t":"τὸ ποῖον δή;","st":"504a"},{"sp":"N","t":"ἐλέγομέν που ὅτι ὡς μὲν δυνατὸν ἦν κάλλιστα αὐτὰ κατιδεῖν ἄλλη μακροτέρα εἴη περίοδος, ἣν περιελθόντι καταφανῆ γίγνοιτο, τῶν μέντοι ἔμπροσθεν προειρημένων ἑπομένας ἀποδείξεις οἷόν τ᾽ εἴη προσάψαι. καὶ ὑμεῖς ἐξαρκεῖν ἔφατε, καὶ οὕτω δὴ ἐρρήθη τὰ τότε τῆς μὲν ἀκριβείας, ὡς ἐμοὶ ἐφαίνετο, ἐλλιπῆ, εἰ δὲ ὑμῖν ἀρεσκόντως, ὑμεῖς ἂν τοῦτο εἴποιτε.","st":"504b"},{"sp":"N","t":"ἀλλ᾽ ἔμοιγε, ἔφη, μετρίως: ἐφαίνετο μὴν καὶ τοῖς ἄλλοις.","st":"504b"},{"sp":"N","t":"ἀλλ᾽, ὦ φίλε, ἦν δ᾽ ἐγώ, μέτρον τῶν τοιούτων ἀπολεῖπον καὶ ὁτιοῦν τοῦ ὄντος οὐ πάνυ μετρίως γίγνεται: ἀτελὲς γὰρ οὐδὲν οὐδενὸς μέτρον. δοκεῖ δ᾽ ἐνίοτέ τισιν ἱκανῶς ἤδη ἔχειν καὶ οὐδὲν δεῖν περαιτέρω ζητεῖν.","st":"504c"},{"sp":"N","t":"καὶ μάλ᾽, ἔφη, συχνοὶ πάσχουσιν αὐτὸ διὰ ῥᾳθυμίαν.","st":"504c"},{"sp":"N","t":"τούτου δέ γε, ἦν δ᾽ ἐγώ, τοῦ παθήματος ἥκιστα προσδεῖ φύλακι πόλεώς τε καὶ νόμων.","st":"504c"},{"sp":"N","t":"εἰκός, ἦ δ᾽ ὅς.","st":"504c"},{"sp":"N","t":"τὴν μακροτέραν τοίνυν, ὦ ἑταῖρε, ἔφην, περιιτέον τῷ","st":"504c"},{"sp":"N","t":"τοιούτῳ, καὶ οὐχ ἧττον μανθάνοντι πονητέον ἢ γυμναζομένῳ: ἤ, ὃ νυνδὴ ἐλέγομεν, τοῦ μεγίστου τε καὶ μάλιστα προσήκοντος μαθήματος ἐπὶ τέλος οὔποτε ἥξει.","st":"504d"},{"sp":"N","t":"οὐ γὰρ ταῦτα, ἔφη, μέγιστα, ἀλλ᾽ ἔτι τι μεῖζον δικαιοσύνης τε καὶ ὧν διήλθομεν;","st":"504d"},{"sp":"N","t":"καὶ μεῖζον, ἦν δ᾽ ἐγώ, καὶ αὐτῶν τούτων οὐχ ὑπογραφὴν δεῖ ὥσπερ νῦν θεάσασθαι, ἀλλὰ τὴν τελεωτάτην ἀπεργασίαν μὴ παριέναι. ἢ οὐ γελοῖον ἐπὶ μὲν ἄλλοις σμικροῦ ἀξίοις","st":"504d"},{"sp":"N","t":"πᾶν ποιεῖν συντεινομένους ὅπως ὅτι ἀκριβέστατα καὶ καθαρώτατα ἕξει, τῶν δὲ μεγίστων μὴ μεγίστας ἀξιοῦν εἶναι καὶ τὰς ἀκριβείας;","st":"504e"},{"sp":"N","t":"καὶ μάλα, ἔφη, [ἄξιον τὸ διανόημα]: ὃ μέντοι μέγιστον μάθημα καὶ περὶ ὅτι αὐτὸ λέγεις, οἴει τιν᾽ ἄν σε, ἔφη, ἀφεῖναι μὴ ἐρωτήσαντα τί ἐστιν;","st":"504e"},{"sp":"N","t":"οὐ πάνυ, ἦν δ᾽ ἐγώ, ἀλλὰ καὶ σὺ ἐρώτα. πάντως αὐτὸ οὐκ ὀλιγάκις ἀκήκοας, νῦν δὲ ἢ οὐκ ἐννοεῖς ἢ αὖ διανοῇ","st":"504e"},{"sp":"N","t":"ἐμοὶ πράγματα παρέχειν ἀντιλαμβανόμενος. οἶμαι δὲ τοῦτο μᾶλλον: ἐπεὶ ὅτι γε ἡ τοῦ ἀγαθοῦ ἰδέα μέγιστον μάθημα, πολλάκις ἀκήκοας, ᾗ δὴ καὶ δίκαια καὶ τἆλλα προσχρησάμενα χρήσιμα καὶ ὠφέλιμα γίγνεται. καὶ νῦν σχεδὸν οἶσθ᾽ ὅτι μέλλω τοῦτο λέγειν, καὶ πρὸς τούτῳ ὅτι αὐτὴν οὐχ ἱκανῶς ἴσμεν: εἰ δὲ μὴ ἴσμεν, ἄνευ δὲ ταύτης εἰ ὅτι μάλιστα τἆλλα ἐπισταίμεθα, οἶσθ᾽ ὅτι οὐδὲν ἡμῖν ὄφελος, ὥσπερ οὐδ᾽ εἰ","st":"505a"},{"sp":"N","t":"κεκτῄμεθά τι ἄνευ τοῦ ἀγαθοῦ. ἢ οἴει τι πλέον εἶναι πᾶσαν κτῆσιν ἐκτῆσθαι, μὴ μέντοι ἀγαθήν; ἢ πάντα τἆλλα φρονεῖν ἄνευ τοῦ ἀγαθοῦ, καλὸν δὲ καὶ ἀγαθὸν μηδὲν φρονεῖν;","st":"505b"},{"sp":"N","t":"μὰ Δί᾽ οὐκ ἔγωγ᾽, ἔφη.","st":"505b"},{"sp":"N","t":"ἀλλὰ μὴν καὶ τόδε γε οἶσθα, ὅτι τοῖς μὲν πολλοῖς ἡδονὴ δοκεῖ εἶναι τὸ ἀγαθόν, τοῖς δὲ κομψοτέροις φρόνησις.","st":"505b"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"505b"},{"sp":"N","t":"καὶ ὅτι γε, ὦ φίλε, οἱ τοῦτο ἡγούμενοι οὐκ ἔχουσι δεῖξαι ἥτις φρόνησις, ἀλλ᾽ ἀναγκάζονται τελευτῶντες τὴν τοῦ ἀγαθοῦ φάναι.","st":"505b"},{"sp":"N","t":"καὶ μάλα, ἔφη, γελοίως.","st":"505b"},{"sp":"N","t":"πῶς γὰρ οὐχί, ἦν δ᾽ ἐγώ, εἰ ὀνειδίζοντές γε ὅτι οὐκ ἴσμεν τὸ ἀγαθὸν λέγουσι πάλιν ὡς εἰδόσιν; φρόνησιν γὰρ αὐτό φασιν εἶναι ἀγαθοῦ, ὡς αὖ συνιέντων ἡμῶν ὅτι λέγουσιν, ἐπειδὰν τὸ τοῦ ἀγαθοῦ φθέγξωνται ὄνομα.","st":"505c"},{"sp":"N","t":"ἀληθέστατα, ἔφη.","st":"505c"},{"sp":"N","t":"τί δὲ οἱ τὴν ἡδονὴν ἀγαθὸν ὁριζόμενοι; μῶν μή τι ἐλάττονος πλάνης ἔμπλεῳ τῶν ἑτέρων; ἢ οὐ καὶ οὗτοι ἀναγκάζονται ὁμολογεῖν ἡδονὰς εἶναι κακάς;","st":"505c"},{"sp":"N","t":"σφόδρα γε.","st":"505c"},{"sp":"N","t":"συμβαίνει δὴ αὐτοῖς οἶμαι ὁμολογεῖν ἀγαθὰ εἶναι καὶ κακὰ ταὐτά. ἦ γάρ;","st":"505c"},{"sp":"N","t":"τί μήν;","st":"505d"},{"sp":"N","t":"οὐκοῦν ὅτι μὲν μεγάλαι καὶ πολλαὶ ἀμφισβητήσεις περὶ αὐτοῦ, φανερόν;","st":"505d"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"505d"},{"sp":"N","t":"τί δέ; τόδε οὐ φανερόν, ὡς δίκαια μὲν καὶ καλὰ πολλοὶ ἂν ἕλοιντο τὰ δοκοῦντα, κἂν ⟨εἰ⟩ μὴ εἴη, ὅμως ταῦτα πράττειν καὶ κεκτῆσθαι καὶ δοκεῖν, ἀγαθὰ δὲ οὐδενὶ ἔτι ἀρκεῖ τὰ δοκοῦντα κτᾶσθαι, ἀλλὰ τὰ ὄντα ζητοῦσιν, τὴν δὲ δόξαν ἐνταῦθα ἤδη πᾶς ἀτιμάζει;","st":"505d"},{"sp":"N","t":"καὶ μάλα, ἔφη.","st":"505d"},{"sp":"N","t":"ὃ δὴ διώκει μὲν ἅπασα ψυχὴ καὶ τούτου ἕνεκα πάντα","st":"505d"},{"sp":"N","t":"πράττει, ἀπομαντευομένη τι εἶναι, ἀποροῦσα δὲ καὶ οὐκ ἔχουσα λαβεῖν ἱκανῶς τί ποτ᾽ ἐστὶν οὐδὲ πίστει χρήσασθαι μονίμῳ οἵᾳ καὶ περὶ τἆλλα, διὰ τοῦτο δὲ ἀποτυγχάνει καὶ τῶν ἄλλων εἴ τι ὄφελος ἦν, περὶ δὴ τὸ τοιοῦτον καὶ τοσοῦτον","st":"505e"},{"sp":"N","t":"οὕτω φῶμεν δεῖν ἐσκοτῶσθαι καὶ ἐκείνους τοὺς βελτίστους ἐν τῇ πόλει, οἷς πάντα ἐγχειριοῦμεν;","st":"506a"},{"sp":"N","t":"ἥκιστά γ᾽, ἔφη.","st":"506a"},{"sp":"N","t":"οἶμαι γοῦν, εἶπον, δίκαιά τε καὶ καλὰ ἀγνοούμενα ὅπῃ ποτὲ ἀγαθά ἐστιν, οὐ πολλοῦ τινος ἄξιον φύλακα κεκτῆσθαι ἂν ἑαυτῶν τὸν τοῦτο ἀγνοοῦντα: μαντεύομαι δὲ μηδένα αὐτὰ πρότερον γνώσεσθαι ἱκανῶς.","st":"506a"},{"sp":"N","t":"καλῶς γάρ, ἔφη, μαντεύῃ.","st":"506a"},{"sp":"N","t":"οὐκοῦν ἡμῖν ἡ πολιτεία τελέως κεκοσμήσεται, ἐὰν ὁ","st":"506a"},{"sp":"N","t":"τοιοῦτος αὐτὴν ἐπισκοπῇ φύλαξ, ὁ τούτων ἐπιστήμων;","st":"506b"},{"sp":"N","t":"ἀνάγκη, ἔφη. ἀλλὰ σὺ δή, ὦ Σώκρατες, πότερον ἐπιστήμην τὸ ἀγαθὸν φῂς εἶναι ἢ ἡδονήν, ἢ ἄλλο τι παρὰ ταῦτα;","st":"506b"},{"sp":"N","t":"οὗτος, ἦν δ᾽ ἐγώ, ἀνήρ, καλῶς ἦσθα καὶ πάλαι καταφανὴς ὅτι σοι οὐκ ἀποχρήσοι τὸ τοῖς ἄλλοις δοκοῦν περὶ αὐτῶν.","st":"506b"},{"sp":"N","t":"οὐδὲ γὰρ δίκαιόν μοι, ἔφη, ὦ Σώκρατες, φαίνεται τὰ τῶν ἄλλων μὲν ἔχειν εἰπεῖν δόγματα, τὸ δ᾽ αὑτοῦ μή, τοσοῦτον","st":"506b"},{"sp":"N","t":"χρόνον περὶ ταῦτα πραγματευόμενον.","st":"506c"},{"sp":"N","t":"τί δέ; ἦν δ᾽ ἐγώ: δοκεῖ σοι δίκαιον εἶναι περὶ ὧν τις μὴ οἶδεν λέγειν ὡς εἰδότα;","st":"506c"},{"sp":"N","t":"οὐδαμῶς γ᾽, ἔφη, ὡς εἰδότα, ὡς μέντοι οἰόμενον ταῦθ᾽ ἃ οἴεται ἐθέλειν λέγειν.","st":"506c"},{"sp":"N","t":"τί δέ; εἶπον: οὐκ ᾔσθησαι τὰς ἄνευ ἐπιστήμης δόξας, ὡς πᾶσαι αἰσχραί; ὧν αἱ βέλτισται τυφλαί — ἢ δοκοῦσί τί σοι τυφλῶν διαφέρειν ὁδὸν ὀρθῶς πορευομένων οἱ ἄνευ νοῦ ἀληθές τι δοξάζοντες;","st":"506c"},{"sp":"N","t":"οὐδέν, ἔφη.","st":"506c"},{"sp":"N","t":"βούλει οὖν αἰσχρὰ θεάσασθαι, τυφλά τε καὶ σκολιά, ἐξὸν","st":"506c"},{"sp":"N","t":"παρ᾽ ἄλλων ἀκούειν φανά τε καὶ καλά;","st":"506d"},{"sp":"N","t":"μὴ πρὸς Διός, ἦ δ᾽ ὅς, ὦ Σώκρατες, ὁ Γλαύκων, ὥσπερ ἐπὶ τέλει ὢν ἀποστῇς. ἀρκέσει γὰρ ἡμῖν, κἂν ὥσπερ δικαιοσύνης πέρι καὶ σωφροσύνης καὶ τῶν ἄλλων διῆλθες, οὕτω καὶ περὶ τοῦ ἀγαθοῦ διέλθῃς.","st":"506d"},{"sp":"N","t":"καὶ γὰρ ἐμοί, ἦν δ᾽ ἐγώ, ὦ ἑταῖρε, καὶ μάλα ἀρκέσει: ἀλλ᾽ ὅπως μὴ οὐχ οἷός τ᾽ ἔσομαι, προθυμούμενος δὲ ἀσχημονῶν γέλωτα ὀφλήσω. ἀλλ᾽, ὦ μακάριοι, αὐτὸ μὲν τί ποτ᾽","st":"506d"},{"sp":"N","t":"ἐστὶ τἀγαθὸν ἐάσωμεν τὸ νῦν εἶναι — πλέον γάρ μοι φαίνεται ἢ κατὰ τὴν παροῦσαν ὁρμὴν ἐφικέσθαι τοῦ γε δοκοῦντος ἐμοὶ τὰ νῦν — ὃς δὲ ἔκγονός τε τοῦ ἀγαθοῦ φαίνεται καὶ ὁμοιότατος ἐκείνῳ, λέγειν ἐθέλω, εἰ καὶ ὑμῖν φίλον, εἰ δὲ μή, ἐᾶν.","st":"506e"},{"sp":"N","t":"ἀλλ᾽, ἔφη, λέγε: εἰς αὖθις γὰρ τοῦ πατρὸς ἀποτείσεις τὴν διήγησιν.","st":"506e"},{"sp":"N","t":"βουλοίμην ἄν, εἶπον, ἐμέ τε δύνασθαι αὐτὴν ἀποδοῦναι καὶ ὑμᾶς κομίσασθαι, ἀλλὰ μὴ ὥσπερ νῦν τοὺς τόκους μόνον. τοῦτον δὲ δὴ οὖν τὸν τόκον τε καὶ ἔκγονον αὐτοῦ τοῦ ἀγαθοῦ κομίσασθε. εὐλαβεῖσθε μέντοι μή πῃ ἐξαπατήσω ὑμᾶς ἄκων, κίβδηλον ἀποδιδοὺς τὸν λόγον τοῦ τόκου.","st":"507a"},{"sp":"N","t":"εὐλαβησόμεθα, ἔφη, κατὰ δύναμιν: ἀλλὰ μόνον λέγε.","st":"507a"},{"sp":"N","t":"διομολογησάμενός γ᾽ ἔφην ἐγώ, καὶ ἀναμνήσας ὑμᾶς τά τ᾽ ἐν τοῖς ἔμπροσθεν ῥηθέντα καὶ ἄλλοτε ἤδη πολλάκις εἰρημένα.","st":"507a"},{"sp":"N","t":"τὰ ποῖα; ἦ δ᾽ ὅς.","st":"507b"},{"sp":"N","t":"πολλὰ καλά, ἦν δ᾽ ἐγώ, καὶ πολλὰ ἀγαθὰ καὶ ἕκαστα οὕτως εἶναί φαμέν τε καὶ διορίζομεν τῷ λόγῳ.","st":"507b"},{"sp":"N","t":"φαμὲν γάρ.","st":"507b"},{"sp":"N","t":"καὶ αὐτὸ δὴ καλὸν καὶ αὐτὸ ἀγαθόν, καὶ οὕτω περὶ πάντων ἃ τότε ὡς πολλὰ ἐτίθεμεν, πάλιν αὖ κατ᾽ ἰδέαν μίαν ἑκάστου ὡς μιᾶς οὔσης τιθέντες, “ὃ ἔστιν” ἕκαστον προσαγορεύομεν.","st":"507b"},{"sp":"N","t":"ἔστι ταῦτα.","st":"507b"},{"sp":"N","t":"καὶ τὰ μὲν δὴ ὁρᾶσθαί φαμεν, νοεῖσθαι δ᾽ οὔ, τὰς δ᾽ αὖ ἰδέας νοεῖσθαι μέν, ὁρᾶσθαι δ᾽ οὔ.","st":"507b"},{"sp":"N","t":"παντάπασι μὲν οὖν.","st":"507b"},{"sp":"N","t":"τῷ οὖν ὁρῶμεν ἡμῶν αὐτῶν τὰ ὁρώμενα;","st":"507c"},{"sp":"N","t":"τῇ ὄψει, ἔφη.","st":"507c"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, καὶ ἀκοῇ τὰ ἀκουόμενα, καὶ ταῖς ἄλλαις αἰσθήσεσι πάντα τὰ αἰσθητά;","st":"507c"},{"sp":"N","t":"τί μήν;","st":"507c"},{"sp":"N","t":"ἆρ᾽ οὖν, ἦν δ᾽ ἐγώ, ἐννενόηκας τὸν τῶν αἰσθήσεων δημιουργὸν ὅσῳ πολυτελεστάτην τὴν τοῦ ὁρᾶν τε καὶ ὁρᾶσθαι δύναμιν ἐδημιούργησεν;","st":"507c"},{"sp":"N","t":"οὐ πάνυ, ἔφη.","st":"507c"},{"sp":"N","t":"ἀλλ᾽ ὧδε σκόπει. ἔστιν ὅτι προσδεῖ ἀκοῇ καὶ φωνῇ γένους ἄλλου εἰς τὸ τὴν μὲν ἀκούειν, τὴν δὲ ἀκούεσθαι, ὃ","st":"507c"},{"sp":"N","t":"ἐὰν μὴ παραγένηται τρίτον, ἡ μὲν οὐκ ἀκούσεται, ἡ δὲ οὐκ ἀκουσθήσεται;","st":"507d"},{"sp":"N","t":"οὐδενός, ἔφη.","st":"507d"},{"sp":"N","t":"οἶμαι δέ γε, ἦν δ᾽ ἐγώ, οὐδ᾽ ἄλλαις πολλαῖς, ἵνα μὴ εἴπω ὅτι οὐδεμιᾷ, τοιούτου προσδεῖ οὐδενός. ἢ σύ τινα ἔχεις εἰπεῖν;","st":"507d"},{"sp":"N","t":"οὐκ ἔγωγε, ἦ δ᾽ ὅς.","st":"507d"},{"sp":"N","t":"τὴν δὲ τῆς ὄψεως καὶ τοῦ ὁρατοῦ οὐκ ἐννοεῖς ὅτι προσδεῖται;","st":"507d"},{"sp":"N","t":"πῶς;","st":"507d"},{"sp":"N","t":"ἐνούσης που ἐν ὄμμασιν ὄψεως καὶ ἐπιχειροῦντος τοῦ ἔχοντος χρῆσθαι αὐτῇ, παρούσης δὲ χρόας ἐν αὐτοῖς, ἐὰν μὴ","st":"507d"},{"sp":"N","t":"παραγένηται γένος τρίτον ἰδίᾳ ἐπ᾽ αὐτὸ τοῦτο πεφυκός, οἶσθα ὅτι ἥ τε ὄψις οὐδὲν ὄψεται, τά τε χρώματα ἔσται ἀόρατα.","st":"507e"},{"sp":"N","t":"τίνος δὴ λέγεις, ἔφη, τούτου;","st":"507e"},{"sp":"N","t":"ὃ δὴ σὺ καλεῖς, ἦν δ᾽ ἐγώ, φῶς.","st":"507e"},{"sp":"N","t":"ἀληθῆ, ἔφη, λέγεις.","st":"507e"},{"sp":"N","t":"οὐ σμικρᾷ ἄρα ἰδέᾳ ἡ τοῦ ὁρᾶν αἴσθησις καὶ ἡ τοῦ ὁρᾶσθαι","st":"507e"},{"sp":"N","t":"δύναμις τῶν ἄλλων συζεύξεων τιμιωτέρῳ ζυγῷ ἐζύγησαν, εἴπερ μὴ ἄτιμον τὸ φῶς.","st":"508a"},{"sp":"N","t":"ἀλλὰ μήν, ἔφη, πολλοῦ γε δεῖ ἄτιμον εἶναι.","st":"508a"},{"sp":"N","t":"τίνα οὖν ἔχεις αἰτιάσασθαι τῶν ἐν οὐρανῷ θεῶν τούτου κύριον, οὗ ἡμῖν τὸ φῶς ὄψιν τε ποιεῖ ὁρᾶν ὅτι κάλλιστα καὶ τὰ ὁρώμενα ὁρᾶσθαι;","st":"508a"},{"sp":"N","t":"ὅνπερ καὶ σύ, ἔφη, καὶ οἱ ἄλλοι: τὸν ἥλιον γὰρ δῆλον ὅτι ἐρωτᾷς.","st":"508a"},{"sp":"N","t":"ἆρ᾽ οὖν ὧδε πέφυκεν ὄψις πρὸς τοῦτον τὸν θεόν;","st":"508a"},{"sp":"N","t":"πῶς;","st":"508a"},{"sp":"N","t":"οὐκ ἔστιν ἥλιος ἡ ὄψις οὔτε αὐτὴ οὔτ᾽ ἐν ᾧ ἐγγίγνεται, ὃ","st":"508a"},{"sp":"N","t":"δὴ καλοῦμεν ὄμμα.","st":"508b"},{"sp":"N","t":"οὐ γὰρ οὖν.","st":"508b"},{"sp":"N","t":"ἀλλ᾽ ἡλιοειδέστατόν γε οἶμαι τῶν περὶ τὰς αἰσθήσεις ὀργάνων.","st":"508b"},{"sp":"N","t":"πολύ γε.","st":"508b"},{"sp":"N","t":"οὐκοῦν καὶ τὴν δύναμιν ἣν ἔχει ἐκ τούτου ταμιευομένην ὥσπερ ἐπίρρυτον κέκτηται;","st":"508b"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"508b"},{"sp":"N","t":"ἆρ᾽ οὖν οὐ καὶ ὁ ἥλιος ὄψις μὲν οὐκ ἔστιν, αἴτιος δ᾽ ὢν αὐτῆς ὁρᾶται ὑπ᾽ αὐτῆς ταύτης;","st":"508b"},{"sp":"N","t":"οὕτως, ἦ δ᾽ ὅς.","st":"508b"},{"sp":"N","t":"τοῦτον τοίνυν, ἦν δ᾽ ἐγώ, φάναι με λέγειν τὸν τοῦ ἀγαθοῦ ἔκγονον, ὃν τἀγαθὸν ἐγέννησεν ἀνάλογον ἑαυτῷ, ὅτιπερ αὐτὸ","st":"508b"},{"sp":"N","t":"ἐν τῷ νοητῷ τόπῳ πρός τε νοῦν καὶ τὰ νοούμενα, τοῦτο τοῦτον ἐν τῷ ὁρατῷ πρός τε ὄψιν καὶ τὰ ὁρώμενα.","st":"508c"},{"sp":"N","t":"πῶς; ἔφη: ἔτι δίελθέ μοι.","st":"508c"},{"sp":"N","t":"ὀφθαλμοί, ἦν δ᾽ ἐγώ, οἶσθ᾽ ὅτι, ὅταν μηκέτι ἐπ᾽ ἐκεῖνά τις αὐτοὺς τρέπῃ ὧν ἂν τὰς χρόας τὸ ἡμερινὸν φῶς ἐπέχῃ, ἀλλὰ ὧν νυκτερινὰ φέγγη, ἀμβλυώττουσί τε καὶ ἐγγὺς φαίνονται τυφλῶν, ὥσπερ οὐκ ἐνούσης καθαρᾶς ὄψεως;","st":"508c"},{"sp":"N","t":"καὶ μάλα, ἔφη.","st":"508c"},{"sp":"N","t":"ὅταν δέ γ᾽ οἶμαι ὧν ὁ ἥλιος καταλάμπει, σαφῶς ὁρῶσι, καὶ τοῖς αὐτοῖς τούτοις ὄμμασιν ἐνοῦσα φαίνεται.","st":"508d"},{"sp":"N","t":"τί μήν;","st":"508d"},{"sp":"N","t":"οὕτω τοίνυν καὶ τὸ τῆς ψυχῆς ὧδε νόει: ὅταν μὲν οὗ καταλάμπει ἀλήθειά τε καὶ τὸ ὄν, εἰς τοῦτο ἀπερείσηται, ἐνόησέν τε καὶ ἔγνω αὐτὸ καὶ νοῦν ἔχειν φαίνεται: ὅταν δὲ εἰς τὸ τῷ σκότῳ κεκραμένον, τὸ γιγνόμενόν τε καὶ ἀπολλύμενον, δοξάζει τε καὶ ἀμβλυώττει ἄνω καὶ κάτω τὰς δόξας μεταβάλλον, καὶ ἔοικεν αὖ νοῦν οὐκ ἔχοντι.","st":"508d"},{"sp":"N","t":"ἔοικε γάρ.","st":"508d"},{"sp":"N","t":"τοῦτο τοίνυν τὸ τὴν ἀλήθειαν παρέχον τοῖς γιγνωσκομένοις καὶ τῷ γιγνώσκοντι τὴν δύναμιν ἀποδιδὸν τὴν τοῦ ἀγαθοῦ ἰδέαν φάθι εἶναι: αἰτίαν δ᾽ ἐπιστήμης οὖσαν καὶ ἀληθείας, ὡς γιγνωσκομένης μὲν διανοοῦ, οὕτω δὲ καλῶν ἀμφοτέρων ὄντων, γνώσεώς τε καὶ ἀληθείας, ἄλλο καὶ κάλλιον ἔτι τούτων ἡγούμενος αὐτὸ ὀρθῶς ἡγήσῃ: ἐπιστήμην","st":"508e"},{"sp":"N","t":"δὲ καὶ ἀλήθειαν, ὥσπερ ἐκεῖ φῶς τε καὶ ὄψιν ἡλιοειδῆ μὲν νομίζειν ὀρθόν, ἥλιον δ᾽ ἡγεῖσθαι οὐκ ὀρθῶς ἔχει, οὕτω καὶ ἐνταῦθα ἀγαθοειδῆ μὲν νομίζειν ταῦτ᾽ ἀμφότερα ὀρθόν, ἀγαθὸν δὲ ἡγεῖσθαι ὁπότερον αὐτῶν οὐκ ὀρθόν, ἀλλ᾽ ἔτι μειζόνως τιμητέον τὴν τοῦ ἀγαθοῦ ἕξιν.","st":"509a"},{"sp":"N","t":"ἀμήχανον κάλλος, ἔφη, λέγεις, εἰ ἐπιστήμην μὲν καὶ ἀλήθειαν παρέχει, αὐτὸ δ᾽ ὑπὲρ ταῦτα κάλλει ἐστίν: οὐ γὰρ δήπου σύ γε ἡδονὴν αὐτὸ λέγεις.","st":"509a"},{"sp":"N","t":"εὐφήμει, ἦν δ᾽ ἐγώ: ἀλλ᾽ ὧδε μᾶλλον τὴν εἰκόνα αὐτοῦ ἔτι ἐπισκόπει.","st":"509a"},{"sp":"N","t":"πῶς;","st":"509b"},{"sp":"N","t":"τὸν ἥλιον τοῖς ὁρωμένοις οὐ μόνον οἶμαι τὴν τοῦ ὁρᾶσθαι δύναμιν παρέχειν φήσεις, ἀλλὰ καὶ τὴν γένεσιν καὶ αὔξην καὶ τροφήν, οὐ γένεσιν αὐτὸν ὄντα.","st":"509b"},{"sp":"N","t":"πῶς γάρ;","st":"509b"},{"sp":"N","t":"καὶ τοῖς γιγνωσκομένοις τοίνυν μὴ μόνον τὸ γιγνώσκεσθαι φάναι ὑπὸ τοῦ ἀγαθοῦ παρεῖναι, ἀλλὰ καὶ τὸ εἶναί τε καὶ τὴν οὐσίαν ὑπ᾽ ἐκείνου αὐτοῖς προσεῖναι, οὐκ οὐσίας ὄντος τοῦ ἀγαθοῦ, ἀλλ᾽ ἔτι ἐπέκεινα τῆς οὐσίας πρεσβείᾳ καὶ δυνάμει ὑπερέχοντος.","st":"509b"},{"sp":"N","t":"καὶ ὁ Γλαύκων μάλα γελοίως, Ἄπολλον, ἔφη, δαιμονίας ὑπερβολῆς.","st":"509c"},{"sp":"N","t":"σὺ γάρ, ἦν δ᾽ ἐγώ, αἴτιος, ἀναγκάζων τὰ ἐμοὶ δοκοῦντα περὶ αὐτοῦ λέγειν.","st":"509c"},{"sp":"N","t":"καὶ μηδαμῶς γ᾽, ἔφη, παύσῃ, εἰ μή τι, ἀλλὰ τὴν περὶ τὸν ἥλιον ὁμοιότητα αὖ διεξιών, εἴ πῃ ἀπολείπεις.","st":"509c"},{"sp":"N","t":"ἀλλὰ μήν, εἶπον, συχνά γε ἀπολείπω.","st":"509c"},{"sp":"N","t":"μηδὲ σμικρὸν τοίνυν, ἔφη, παραλίπῃς.","st":"509c"},{"sp":"N","t":"οἶμαι μέν, ἦν δ᾽ ἐγώ, καὶ πολύ: ὅμως δέ, ὅσα γ᾽ ἐν τῷ παρόντι δυνατόν, ἑκὼν οὐκ ἀπολείψω.","st":"509c"},{"sp":"N","t":"μὴ γάρ, ἔφη.","st":"509c"},{"sp":"N","t":"νόησον τοίνυν, ἦν δ᾽ ἐγώ, ὥσπερ λέγομεν, δύο αὐτὼ εἶναι, καὶ βασιλεύειν τὸ μὲν νοητοῦ γένους τε καὶ τόπου, τὸ δ᾽ αὖ ὁρατοῦ, ἵνα μὴ οὐρανοῦ εἰπὼν δόξω σοι σοφίζεσθαι περὶ τὸ ὄνομα. ἀλλ᾽ οὖν ἔχεις ταῦτα διττὰ εἴδη, ὁρατόν, νοητόν;","st":"509d"},{"sp":"N","t":"ἔχω.","st":"509d"},{"sp":"N","t":"ὥσπερ τοίνυν γραμμὴν δίχα τετμημένην λαβὼν ἄνισα τμήματα, πάλιν τέμνε ἑκάτερον τὸ τμῆμα ἀνὰ τὸν αὐτὸν λόγον, τό τε τοῦ ὁρωμένου γένους καὶ τὸ τοῦ νοουμένου, καί σοι ἔσται σαφηνείᾳ καὶ ἀσαφείᾳ πρὸς ἄλληλα ἐν μὲν τῷ ὁρωμένῳ","st":"509d"},{"sp":"N","t":"τὸ μὲν ἕτερον τμῆμα εἰκόνες — λέγω δὲ τὰς εἰκόνας πρῶτον","st":"509e"},{"sp":"N","t":"μὲν τὰς σκιάς, ἔπειτα τὰ ἐν τοῖς ὕδασι φαντάσματα καὶ ἐν τοῖς ὅσα πυκνά τε καὶ λεῖα καὶ φανὰ συνέστηκεν, καὶ πᾶν τὸ τοιοῦτον, εἰ κατανοεῖς.","st":"510a"},{"sp":"N","t":"ἀλλὰ κατανοῶ.","st":"510a"},{"sp":"N","t":"τὸ τοίνυν ἕτερον τίθει ᾧ τοῦτο ἔοικεν, τά τε περὶ ἡμᾶς ζῷα καὶ πᾶν τὸ φυτευτὸν καὶ τὸ σκευαστὸν ὅλον γένος.","st":"510a"},{"sp":"N","t":"τίθημι, ἔφη.","st":"510a"},{"sp":"N","t":"ἦ καὶ ἐθέλοις ἂν αὐτὸ φάναι, ἦν δ᾽ ἐγώ, διῃρῆσθαι ἀληθείᾳ τε καὶ μή, ὡς τὸ δοξαστὸν πρὸς τὸ γνωστόν, οὕτω τὸ ὁμοιωθὲν πρὸς τὸ ᾧ ὡμοιώθη;","st":"510a"},{"sp":"N","t":"ἔγωγ᾽, ἔφη, καὶ μάλα.","st":"510b"},{"sp":"N","t":"σκόπει δὴ αὖ καὶ τὴν τοῦ νοητοῦ τομὴν ᾗ τμητέον.","st":"510b"},{"sp":"N","t":"πῇ;","st":"510b"},{"sp":"N","t":"ἧι τὸ μὲν αὐτοῦ τοῖς τότε μιμηθεῖσιν ὡς εἰκόσιν χρωμένη ψυχὴ ζητεῖν ἀναγκάζεται ἐξ ὑποθέσεων, οὐκ ἐπ᾽ ἀρχὴν πορευομένη ἀλλ᾽ ἐπὶ τελευτήν, τὸ δ᾽ αὖ ἕτερον — τὸ ἐπ᾽ ἀρχὴν ἀνυπόθετον — ἐξ ὑποθέσεως ἰοῦσα καὶ ἄνευ τῶν περὶ ἐκεῖνο εἰκόνων, αὐτοῖς εἴδεσι δι᾽ αὐτῶν τὴν μέθοδον ποιουμένη.","st":"510b"},{"sp":"N","t":"ταῦτ᾽, ἔφη, ἃ λέγεις, οὐχ ἱκανῶς ἔμαθον.","st":"510b"},{"sp":"N","t":"ἀλλ᾽ αὖθις, ἦν δ᾽ ἐγώ: ῥᾷον γὰρ τούτων προειρημένων μαθήσῃ. οἶμαι γάρ σε εἰδέναι ὅτι οἱ περὶ τὰς γεωμετρίας τε καὶ λογισμοὺς καὶ τὰ τοιαῦτα πραγματευόμενοι, ὑποθέμενοι τό τε περιττὸν καὶ τὸ ἄρτιον καὶ τὰ σχήματα καὶ γωνιῶν τριττὰ εἴδη καὶ ἄλλα τούτων ἀδελφὰ καθ᾽ ἑκάστην μέθοδον, ταῦτα μὲν ὡς εἰδότες, ποιησάμενοι ὑποθέσεις αὐτά, οὐδένα λόγον οὔτε αὑτοῖς οὔτε ἄλλοις ἔτι ἀξιοῦσι περὶ αὐτῶν διδόναι","st":"510c"},{"sp":"N","t":"ὡς παντὶ φανερῶν, ἐκ τούτων δ᾽ ἀρχόμενοι τὰ λοιπὰ ἤδη διεξιόντες τελευτῶσιν ὁμολογουμένως ἐπὶ τοῦτο οὗ ἂν ἐπὶ σκέψιν ὁρμήσωσι.","st":"510d"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη, τοῦτό γε οἶδα.","st":"510d"},{"sp":"N","t":"οὐκοῦν καὶ ὅτι τοῖς ὁρωμένοις εἴδεσι προσχρῶνται καὶ τοὺς λόγους περὶ αὐτῶν ποιοῦνται, οὐ περὶ τούτων διανοούμενοι, ἀλλ᾽ ἐκείνων πέρι οἷς ταῦτα ἔοικε, τοῦ τετραγώνου αὐτοῦ ἕνεκα τοὺς λόγους ποιούμενοι καὶ διαμέτρου αὐτῆς, ἀλλ᾽ οὐ","st":"510d"},{"sp":"N","t":"ταύτης ἣν γράφουσιν, καὶ τἆλλα οὕτως, αὐτὰ μὲν ταῦτα ἃ πλάττουσίν τε καὶ γράφουσιν, ὧν καὶ σκιαὶ καὶ ἐν ὕδασιν εἰκόνες εἰσίν, τούτοις μὲν ὡς εἰκόσιν αὖ χρώμενοι, ζητοῦντες","st":"510e"},{"sp":"N","t":"δὲ αὐτὰ ἐκεῖνα ἰδεῖν ἃ οὐκ ἂν ἄλλως ἴδοι τις ἢ τῇ διανοίᾳ.","st":"511a"},{"sp":"N","t":"ἀληθῆ, ἔφη, λέγεις.","st":"511a"},{"sp":"N","t":"τοῦτο τοίνυν νοητὸν μὲν τὸ εἶδος ἔλεγον, ὑποθέσεσι δ᾽ ἀναγκαζομένην ψυχὴν χρῆσθαι περὶ τὴν ζήτησιν αὐτοῦ, οὐκ ἐπ᾽ ἀρχὴν ἰοῦσαν, ὡς οὐ δυναμένην τῶν ὑποθέσεων ἀνωτέρω ἐκβαίνειν, εἰκόσι δὲ χρωμένην αὐτοῖς τοῖς ὑπὸ τῶν κάτω ἀπεικασθεῖσιν καὶ ἐκείνοις πρὸς ἐκεῖνα ὡς ἐναργέσι δεδοξασμένοις τε καὶ τετιμημένοις.","st":"511a"},{"sp":"N","t":"μανθάνω, ἔφη, ὅτι τὸ ὑπὸ ταῖς γεωμετρίαις τε καὶ ταῖς ταύτης ἀδελφαῖς τέχναις λέγεις.","st":"511b"},{"sp":"N","t":"τὸ τοίνυν ἕτερον μάνθανε τμῆμα τοῦ νοητοῦ λέγοντά με τοῦτο οὗ αὐτὸς ὁ λόγος ἅπτεται τῇ τοῦ διαλέγεσθαι δυνάμει, τὰς ὑποθέσεις ποιούμενος οὐκ ἀρχὰς ἀλλὰ τῷ ὄντι ὑποθέσεις, οἷον ἐπιβάσεις τε καὶ ὁρμάς, ἵνα μέχρι τοῦ ἀνυποθέτου ἐπὶ τὴν τοῦ παντὸς ἀρχὴν ἰών, ἁψάμενος αὐτῆς, πάλιν αὖ ἐχόμενος τῶν ἐκείνης ἐχομένων, οὕτως ἐπὶ τελευτὴν καταβαίνῃ,","st":"511b"},{"sp":"N","t":"αἰσθητῷ παντάπασιν οὐδενὶ προσχρώμενος, ἀλλ᾽ εἴδεσιν αὐτοῖς δι᾽ αὐτῶν εἰς αὐτά, καὶ τελευτᾷ εἰς εἴδη.","st":"511c"},{"sp":"N","t":"μανθάνω, ἔφη, ἱκανῶς μὲν οὔ — δοκεῖς γάρ μοι συχνὸν ἔργον λέγειν — ὅτι μέντοι βούλει διορίζειν σαφέστερον εἶναι τὸ ὑπὸ τῆς τοῦ διαλέγεσθαι ἐπιστήμης τοῦ ὄντος τε καὶ νοητοῦ θεωρούμενον ἢ τὸ ὑπὸ τῶν τεχνῶν καλουμένων, αἷς αἱ ὑποθέσεις ἀρχαὶ καὶ διανοίᾳ μὲν ἀναγκάζονται ἀλλὰ μὴ αἰσθήσεσιν αὐτὰ θεᾶσθαι οἱ θεώμενοι, διὰ δὲ τὸ μὴ ἐπ᾽ ἀρχὴν","st":"511c"},{"sp":"N","t":"ἀνελθόντες σκοπεῖν ἀλλ᾽ ἐξ ὑποθέσεων, νοῦν οὐκ ἴσχειν περὶ αὐτὰ δοκοῦσί σοι, καίτοι νοητῶν ὄντων μετὰ ἀρχῆς. διάνοιαν δὲ καλεῖν μοι δοκεῖς τὴν τῶν γεωμετρικῶν τε καὶ τὴν τῶν τοιούτων ἕξιν ἀλλ᾽ οὐ νοῦν, ὡς μεταξύ τι δόξης τε καὶ νοῦ τὴν διάνοιαν οὖσαν.","st":"511d"},{"sp":"N","t":"ἱκανώτατα, ἦν δ᾽ ἐγώ, ἀπεδέξω. καί μοι ἐπὶ τοῖς τέτταρσι τμήμασι τέτταρα ταῦτα παθήματα ἐν τῇ ψυχῇ γιγνόμενα λαβέ, νόησιν μὲν ἐπὶ τῷ ἀνωτάτω, διάνοιαν","st":"511d"},{"sp":"N","t":"δὲ ἐπὶ τῷ δευτέρῳ, τῷ τρίτῳ δὲ πίστιν ἀπόδος καὶ τῷ τελευταίῳ εἰκασίαν, καὶ τάξον αὐτὰ ἀνὰ λόγον, ὥσπερ ἐφ᾽ οἷς ἐστιν ἀληθείας μετέχει, οὕτω ταῦτα σαφηνείας ἡγησάμενος μετέχειν.","st":"511e"},{"sp":"N","t":"μανθάνω, ἔφη, καὶ συγχωρῶ καὶ τάττω ὡς λέγεις.","st":"511e"},{"sp":"N","t":"ΣΩΚΡΆΤΗς, ΓΛΑΎΚΩΝ","st":"511e"},{"sp":"N","t":"μετὰ ταῦτα δή, εἶπον, ἀπείκασον τοιούτῳ πάθει τὴν ἡμετέραν φύσιν παιδείας τε πέρι καὶ ἀπαιδευσίας. ἰδὲ γὰρ ἀνθρώπους οἷον ἐν καταγείῳ οἰκήσει σπηλαιώδει, ἀναπεπταμένην πρὸς τὸ φῶς τὴν εἴσοδον ἐχούσῃ μακρὰν παρὰ πᾶν τὸ σπήλαιον, ἐν ταύτῃ ἐκ παίδων ὄντας ἐν δεσμοῖς καὶ τὰ σκέλη καὶ τοὺς αὐχένας, ὥστε μένειν τε αὐτοὺς εἴς τε τὸ","st":"514a"},{"sp":"N","t":"πρόσθεν μόνον ὁρᾶν, κύκλῳ δὲ τὰς κεφαλὰς ὑπὸ τοῦ δεσμοῦ ἀδυνάτους περιάγειν, φῶς δὲ αὐτοῖς πυρὸς ἄνωθεν καὶ πόρρωθεν καόμενον ὄπισθεν αὐτῶν, μεταξὺ δὲ τοῦ πυρὸς καὶ τῶν δεσμωτῶν ἐπάνω ὁδόν, παρ᾽ ἣν ἰδὲ τειχίον παρῳκοδομημένον, ὥσπερ τοῖς θαυματοποιοῖς πρὸ τῶν ἀνθρώπων πρόκειται τὰ παραφράγματα, ὑπὲρ ὧν τὰ θαύματα δεικνύασιν.","st":"514b"},{"sp":"N","t":"ὁρῶ, ἔφη.","st":"514b"},{"sp":"N","t":"ὅρα τοίνυν παρὰ τοῦτο τὸ τειχίον φέροντας ἀνθρώπους","st":"514b"},{"sp":"N","t":"σκεύη τε παντοδαπὰ ὑπερέχοντα τοῦ τειχίου καὶ ἀνδριάντας","st":"514c"},{"sp":"N","t":"καὶ ἄλλα ζῷα λίθινά τε καὶ ξύλινα καὶ παντοῖα εἰργασμένα, οἷον εἰκὸς τοὺς μὲν φθεγγομένους, τοὺς δὲ σιγῶντας τῶν παραφερόντων.","st":"515a"},{"sp":"N","t":"ἄτοπον, ἔφη, λέγεις εἰκόνα καὶ δεσμώτας ἀτόπους.","st":"515a"},{"sp":"N","t":"ὁμοίους ἡμῖν, ἦν δ᾽ ἐγώ: τοὺς γὰρ τοιούτους πρῶτον μὲν ἑαυτῶν τε καὶ ἀλλήλων οἴει ἄν τι ἑωρακέναι ἄλλο πλὴν τὰς σκιὰς τὰς ὑπὸ τοῦ πυρὸς εἰς τὸ καταντικρὺ αὐτῶν τοῦ σπηλαίου προσπιπτούσας;","st":"515a"},{"sp":"N","t":"πῶς γάρ, ἔφη, εἰ ἀκινήτους γε τὰς κεφαλὰς ἔχειν ἠναγκασμένοι","st":"515a"},{"sp":"N","t":"εἶεν διὰ βίου;","st":"515b"},{"sp":"N","t":"τί δὲ τῶν παραφερομένων; οὐ ταὐτὸν τοῦτο;","st":"515b"},{"sp":"N","t":"τί μήν;","st":"515b"},{"sp":"N","t":"εἰ οὖν διαλέγεσθαι οἷοί τ᾽ εἶεν πρὸς ἀλλήλους, οὐ ταῦτα ἡγῇ ἂν τὰ ὄντα αὐτοὺς νομίζειν ἅπερ ὁρῷεν;","st":"515b"},{"sp":"N","t":"ἀνάγκη.","st":"515b"},{"sp":"N","t":"τί δ᾽ εἰ καὶ ἠχὼ τὸ δεσμωτήριον ἐκ τοῦ καταντικρὺ ἔχοι; ὁπότε τις τῶν παριόντων φθέγξαιτο, οἴει ἂν ἄλλο τι αὐτοὺς ἡγεῖσθαι τὸ φθεγγόμενον ἢ τὴν παριοῦσαν σκιάν;","st":"515b"},{"sp":"N","t":"μὰ Δί᾽ οὐκ ἔγωγ᾽, ἔφη.","st":"515b"},{"sp":"N","t":"παντάπασι δή, ἦν δ᾽ ἐγώ, οἱ τοιοῦτοι οὐκ ἂν ἄλλο τι νομίζοιεν τὸ ἀληθὲς ἢ τὰς τῶν σκευαστῶν σκιάς.","st":"515c"},{"sp":"N","t":"πολλὴ ἀνάγκη, ἔφη.","st":"515c"},{"sp":"N","t":"σκόπει δή, ἦν δ᾽ ἐγώ, αὐτῶν λύσιν τε καὶ ἴασιν τῶν τε δεσμῶν καὶ τῆς ἀφροσύνης, οἵα τις ἂν εἴη, εἰ φύσει τοιάδε συμβαίνοι αὐτοῖς: ὁπότε τις λυθείη καὶ ἀναγκάζοιτο ἐξαίφνης ἀνίστασθαί τε καὶ περιάγειν τὸν αὐχένα καὶ βαδίζειν καὶ πρὸς τὸ φῶς ἀναβλέπειν, πάντα δὲ ταῦτα ποιῶν ἀλγοῖ τε καὶ διὰ τὰς μαρμαρυγὰς ἀδυνατοῖ καθορᾶν ἐκεῖνα ὧν","st":"515c"},{"sp":"N","t":"τότε τὰς σκιὰς ἑώρα, τί ἂν οἴει αὐτὸν εἰπεῖν, εἴ τις αὐτῷ λέγοι ὅτι τότε μὲν ἑώρα φλυαρίας, νῦν δὲ μᾶλλόν τι ἐγγυτέρω τοῦ ὄντος καὶ πρὸς μᾶλλον ὄντα τετραμμένος ὀρθότερον βλέποι, καὶ δὴ καὶ ἕκαστον τῶν παριόντων δεικνὺς αὐτῷ ἀναγκάζοι ἐρωτῶν ἀποκρίνεσθαι ὅτι ἔστιν; οὐκ οἴει αὐτὸν ἀπορεῖν τε ἂν καὶ ἡγεῖσθαι τὰ τότε ὁρώμενα ἀληθέστερα ἢ τὰ νῦν δεικνύμενα;","st":"515d"},{"sp":"N","t":"πολύ γ᾽, ἔφη.","st":"515d"},{"sp":"N","t":"οὐκοῦν κἂν εἰ πρὸς αὐτὸ τὸ φῶς ἀναγκάζοι αὐτὸν βλέπειν, ἀλγεῖν τε ἂν τὰ ὄμματα καὶ φεύγειν ἀποστρεφόμενον πρὸς ἐκεῖνα ἃ δύναται καθορᾶν, καὶ νομίζειν ταῦτα τῷ ὄντι σαφέστερα τῶν δεικνυμένων;","st":"515e"},{"sp":"N","t":"οὕτως, ἔφη.","st":"515e"},{"sp":"N","t":"εἰ δέ, ἦν δ᾽ ἐγώ, ἐντεῦθεν ἕλκοι τις αὐτὸν βίᾳ διὰ τραχείας τῆς ἀναβάσεως καὶ ἀνάντους, καὶ μὴ ἀνείη πρὶν ἐξελκύσειεν εἰς τὸ τοῦ ἡλίου φῶς, ἆρα οὐχὶ ὀδυνᾶσθαί τε","st":"515e"},{"sp":"N","t":"ἂν καὶ ἀγανακτεῖν ἑλκόμενον, καὶ ἐπειδὴ πρὸς τὸ φῶς ἔλθοι, αὐγῆς ἂν ἔχοντα τὰ ὄμματα μεστὰ ὁρᾶν οὐδ᾽ ἂν ἓν δύνασθαι τῶν νῦν λεγομένων ἀληθῶν;","st":"516a"},{"sp":"N","t":"οὐ γὰρ ἄν, ἔφη, ἐξαίφνης γε.","st":"516a"},{"sp":"N","t":"συνηθείας δὴ οἶμαι δέοιτ᾽ ἄν, εἰ μέλλοι τὰ ἄνω ὄψεσθαι. καὶ πρῶτον μὲν τὰς σκιὰς ἂν ῥᾷστα καθορῷ, καὶ μετὰ τοῦτο ἐν τοῖς ὕδασι τά τε τῶν ἀνθρώπων καὶ τὰ τῶν ἄλλων εἴδωλα, ὕστερον δὲ αὐτά: ἐκ δὲ τούτων τὰ ἐν τῷ οὐρανῷ καὶ αὐτὸν τὸν οὐρανὸν νύκτωρ ἂν ῥᾷον θεάσαιτο, προσβλέπων τὸ τῶν","st":"516a"},{"sp":"N","t":"ἄστρων τε καὶ σελήνης φῶς, ἢ μεθ᾽ ἡμέραν τὸν ἥλιόν τε καὶ τὸ τοῦ ἡλίου.","st":"516b"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"516b"},{"sp":"N","t":"τελευταῖον δὴ οἶμαι τὸν ἥλιον, οὐκ ἐν ὕδασιν οὐδ᾽ ἐν ἀλλοτρίᾳ ἕδρᾳ φαντάσματα αὐτοῦ, ἀλλ᾽ αὐτὸν καθ᾽ αὑτὸν ἐν τῇ αὑτοῦ χώρᾳ δύναιτ᾽ ἂν κατιδεῖν καὶ θεάσασθαι οἷός ἐστιν.","st":"516b"},{"sp":"N","t":"ἀναγκαῖον, ἔφη.","st":"516b"},{"sp":"N","t":"καὶ μετὰ ταῦτ᾽ ἂν ἤδη συλλογίζοιτο περὶ αὐτοῦ ὅτι οὗτος ὁ τάς τε ὥρας παρέχων καὶ ἐνιαυτοὺς καὶ πάντα ἐπιτροπεύων","st":"516b"},{"sp":"N","t":"τὰ ἐν τῷ ὁρωμένῳ τόπῳ, καὶ ἐκείνων ὧν σφεῖς ἑώρων τρόπον τινὰ πάντων αἴτιος.","st":"516c"},{"sp":"N","t":"δῆλον, ἔφη, ὅτι ἐπὶ ταῦτα ἂν μετ᾽ ἐκεῖνα ἔλθοι.","st":"516c"},{"sp":"N","t":"τί οὖν; ἀναμιμνῃσκόμενον αὐτὸν τῆς πρώτης οἰκήσεως καὶ τῆς ἐκεῖ σοφίας καὶ τῶν τότε συνδεσμωτῶν οὐκ ἂν οἴει αὑτὸν μὲν εὐδαιμονίζειν τῆς μεταβολῆς, τοὺς δὲ ἐλεεῖν;","st":"516c"},{"sp":"N","t":"καὶ μάλα.","st":"516c"},{"sp":"N","t":"τιμαὶ δὲ καὶ ἔπαινοι εἴ τινες αὐτοῖς ἦσαν τότε παρ᾽ ἀλλήλων καὶ γέρα τῷ ὀξύτατα καθορῶντι τὰ παριόντα, καὶ μνημονεύοντι μάλιστα ὅσα τε πρότερα αὐτῶν καὶ ὕστερα","st":"516c"},{"sp":"N","t":"εἰώθει καὶ ἅμα πορεύεσθαι, καὶ ἐκ τούτων δὴ δυνατώτατα ἀπομαντευομένῳ τὸ μέλλον ἥξειν, δοκεῖς ἂν αὐτὸν ἐπιθυμητικῶς αὐτῶν ἔχειν καὶ ζηλοῦν τοὺς παρ᾽ ἐκείνοις τιμωμένους τε καὶ ἐνδυναστεύοντας, ἢ τὸ τοῦ Ὁμήρου ἂν πεπονθέναι καὶ σφόδρα βούλεσθαι ““ἐπάρουρον ἐόντα θητευέμεν ἄλλῳ ἀνδρὶ παρ᾽ ἀκλήρῳ” “ καὶ ὁτιοῦν ἂν πεπονθέναι μᾶλλον ἢ ‘κεῖνά τε δοξάζειν καὶ ἐκείνως ζῆν;","st":"516d"},{"sp":"N","t":"οὕτως, ἔφη, ἔγωγε οἶμαι, πᾶν μᾶλλον πεπονθέναι ἂν δέξασθαι ἢ ζῆν ἐκείνως.","st":"516e"},{"sp":"N","t":"καὶ τόδε δὴ ἐννόησον, ἦν δ᾽ ἐγώ. εἰ πάλιν ὁ τοιοῦτος καταβὰς εἰς τὸν αὐτὸν θᾶκον καθίζοιτο, ἆρ᾽ οὐ σκότους ⟨ἂν⟩ ἀνάπλεως σχοίη τοὺς ὀφθαλμούς, ἐξαίφνης ἥκων ἐκ τοῦ ἡλίου;","st":"516e"},{"sp":"N","t":"καὶ μάλα γ᾽, ἔφη.","st":"516e"},{"sp":"N","t":"τὰς δὲ δὴ σκιὰς ἐκείνας πάλιν εἰ δέοι αὐτὸν γνωματεύοντα διαμιλλᾶσθαι τοῖς ἀεὶ δεσμώταις ἐκείνοις, ἐν ᾧ ἀμβλυώττει,","st":"516e"},{"sp":"N","t":"πρὶν καταστῆναι τὰ ὄμματα, οὗτος δ᾽ ὁ χρόνος μὴ πάνυ ὀλίγος εἴη τῆς συνηθείας, ἆρ᾽ οὐ γέλωτ᾽ ἂν παράσχοι, καὶ λέγοιτο ἂν περὶ αὐτοῦ ὡς ἀναβὰς ἄνω διεφθαρμένος ἥκει τὰ ὄμματα, καὶ ὅτι οὐκ ἄξιον οὐδὲ πειρᾶσθαι ἄνω ἰέναι; καὶ τὸν ἐπιχειροῦντα λύειν τε καὶ ἀνάγειν, εἴ πως ἐν ταῖς χερσὶ δύναιντο λαβεῖν καὶ ἀποκτείνειν, ἀποκτεινύναι ἄν;","st":"517a"},{"sp":"N","t":"σφόδρα γ᾽, ἔφη.","st":"517a"},{"sp":"N","t":"ταύτην τοίνυν, ἦν δ᾽ ἐγώ, τὴν εἰκόνα, ὦ φίλε Γλαύκων,","st":"517a"},{"sp":"N","t":"προσαπτέον ἅπασαν τοῖς ἔμπροσθεν λεγομένοις, τὴν μὲν δι᾽ ὄψεως φαινομένην ἕδραν τῇ τοῦ δεσμωτηρίου οἰκήσει ἀφομοιοῦντα, τὸ δὲ τοῦ πυρὸς ἐν αὐτῇ φῶς τῇ τοῦ ἡλίου δυνάμει: τὴν δὲ ἄνω ἀνάβασιν καὶ θέαν τῶν ἄνω τὴν εἰς τὸν νοητὸν τόπον τῆς ψυχῆς ἄνοδον τιθεὶς οὐχ ἁμαρτήσῃ τῆς γ᾽ ἐμῆς ἐλπίδος, ἐπειδὴ ταύτης ἐπιθυμεῖς ἀκούειν. θεὸς δέ που οἶδεν εἰ ἀληθὴς οὖσα τυγχάνει. τὰ δ᾽ οὖν ἐμοὶ φαινόμενα οὕτω φαίνεται, ἐν τῷ γνωστῷ τελευταία ἡ τοῦ","st":"517b"},{"sp":"N","t":"ἀγαθοῦ ἰδέα καὶ μόγις ὁρᾶσθαι, ὀφθεῖσα δὲ συλλογιστέα εἶναι ὡς ἄρα πᾶσι πάντων αὕτη ὀρθῶν τε καὶ καλῶν αἰτία, ἔν τε ὁρατῷ φῶς καὶ τὸν τούτου κύριον τεκοῦσα, ἔν τε νοητῷ αὐτὴ κυρία ἀλήθειαν καὶ νοῦν παρασχομένη, καὶ ὅτι δεῖ ταύτην ἰδεῖν τὸν μέλλοντα ἐμφρόνως πράξειν ἢ ἰδίᾳ ἢ δημοσίᾳ.","st":"517c"},{"sp":"N","t":"συνοίομαι, ἔφη, καὶ ἐγώ, ὅν γε δὴ τρόπον δύναμαι.","st":"517c"},{"sp":"N","t":"ἴθι τοίνυν, ἦν δ᾽ ἐγώ, καὶ τόδε συνοιήθητι καὶ μὴ θαυμάσῃς ὅτι οἱ ἐνταῦθα ἐλθόντες οὐκ ἐθέλουσιν τὰ τῶν ἀνθρώπων πράττειν, ἀλλ᾽ ἄνω ἀεὶ ἐπείγονται αὐτῶν αἱ ψυχαὶ διατρίβειν:","st":"517c"},{"sp":"N","t":"εἰκὸς γάρ που οὕτως, εἴπερ αὖ κατὰ τὴν προειρημένην εἰκόνα τοῦτ᾽ ἔχει.","st":"517d"},{"sp":"N","t":"εἰκὸς μέντοι, ἔφη.","st":"517d"},{"sp":"N","t":"τί δέ; τόδε οἴει τι θαυμαστόν, εἰ ἀπὸ θείων, ἦν δ᾽ ἐγώ, θεωριῶν ἐπὶ τὰ ἀνθρώπειά τις ἐλθὼν κακὰ ἀσχημονεῖ τε καὶ φαίνεται σφόδρα γελοῖος ἔτι ἀμβλυώττων καὶ πρὶν ἱκανῶς συνήθης γενέσθαι τῷ παρόντι σκότῳ ἀναγκαζόμενος ἐν δικαστηρίοις ἢ ἄλλοθί που ἀγωνίζεσθαι περὶ τῶν τοῦ δικαίου σκιῶν ἢ ἀγαλμάτων ὧν αἱ σκιαί, καὶ διαμιλλᾶσθαι","st":"517d"},{"sp":"N","t":"περὶ τούτου, ὅπῃ ποτὲ ὑπολαμβάνεται ταῦτα ὑπὸ τῶν αὐτὴν δικαιοσύνην μὴ πώποτε ἰδόντων;","st":"517e"},{"sp":"N","t":"οὐδ᾽ ὁπωστιοῦν θαυμαστόν, ἔφη.","st":"517e"},{"sp":"N","t":"ἀλλ᾽ εἰ νοῦν γε ἔχοι τις, ἦν δ᾽ ἐγώ, μεμνῇτ᾽ ἂν ὅτι διτταὶ καὶ ἀπὸ διττῶν γίγνονται ἐπιταράξεις ὄμμασιν, ἔκ τε φωτὸς εἰς σκότος μεθισταμένων καὶ ἐκ σκότους εἰς φῶς. ταὐτὰ δὲ ταῦτα νομίσας γίγνεσθαι καὶ περὶ ψυχήν, ὁπότε ἴδοι θορυβουμένην τινὰ καὶ ἀδυνατοῦσάν τι καθορᾶν, οὐκ ἂν ἀλογίστως γελῷ, ἀλλ᾽ ἐπισκοποῖ ἂν πότερον ἐκ φανοτέρου βίου ἥκουσα ὑπὸ ἀηθείας ἐσκότωται, ἢ ἐξ ἀμαθίας πλείονος εἰς φανότερον ἰοῦσα ὑπὸ λαμπροτέρου μαρμαρυγῆς","st":"518a"},{"sp":"N","t":"ἐμπέπλησται, καὶ οὕτω δὴ τὴν μὲν εὐδαιμονίσειεν ἂν τοῦ πάθους τε καὶ βίου, τὴν δὲ ἐλεήσειεν, καὶ εἰ γελᾶν ἐπ᾽ αὐτῇ βούλοιτο, ἧττον ἂν καταγέλαστος ὁ γέλως αὐτῷ εἴη ἢ ὁ ἐπὶ τῇ ἄνωθεν ἐκ φωτὸς ἡκούσῃ.","st":"518b"},{"sp":"N","t":"καὶ μάλα, ἔφη, μετρίως λέγεις.","st":"518b"},{"sp":"N","t":"δεῖ δή, εἶπον, ἡμᾶς τοιόνδε νομίσαι περὶ αὐτῶν, εἰ ταῦτ᾽ ἀληθῆ: τὴν παιδείαν οὐχ οἵαν τινὲς ἐπαγγελλόμενοί φασιν εἶναι τοιαύτην καὶ εἶναι. φασὶ δέ που οὐκ ἐνούσης ἐν τῇ","st":"518b"},{"sp":"N","t":"ψυχῇ ἐπιστήμης σφεῖς ἐντιθέναι, οἷον τυφλοῖς ὀφθαλμοῖς ὄψιν ἐντιθέντες.","st":"518c"},{"sp":"N","t":"φασὶ γὰρ οὖν, ἔφη.","st":"518c"},{"sp":"N","t":"ὁ δέ γε νῦν λόγος, ἦν δ᾽ ἐγώ, σημαίνει ταύτην τὴν ἐνοῦσαν ἑκάστου δύναμιν ἐν τῇ ψυχῇ καὶ τὸ ὄργανον ᾧ καταμανθάνει ἕκαστος, οἷον εἰ ὄμμα μὴ δυνατὸν ἦν ἄλλως ἢ σὺν ὅλῳ τῷ σώματι στρέφειν πρὸς τὸ φανὸν ἐκ τοῦ σκοτώδους, οὕτω σὺν ὅλῃ τῇ ψυχῇ ἐκ τοῦ γιγνομένου περιακτέον εἶναι, ἕως ἂν εἰς τὸ ὂν καὶ τοῦ ὄντος τὸ φανότατον δυνατὴ γένηται ἀνασχέσθαι θεωμένη: τοῦτο δ᾽ εἶναί φαμεν","st":"518c"},{"sp":"N","t":"τἀγαθόν. ἦ γάρ;","st":"518d"},{"sp":"N","t":"ναί.","st":"518d"},{"sp":"N","t":"τούτου τοίνυν, ἦν δ᾽ ἐγώ, αὐτοῦ τέχνη ἂν εἴη, τῆς περιαγωγῆς, τίνα τρόπον ὡς ῥᾷστά τε καὶ ἀνυσιμώτατα μεταστραφήσεται, οὐ τοῦ ἐμποιῆσαι αὐτῷ τὸ ὁρᾶν, ἀλλ᾽ ὡς ἔχοντι μὲν αὐτό, οὐκ ὀρθῶς δὲ τετραμμένῳ οὐδὲ βλέποντι οἷ ἔδει, τοῦτο διαμηχανήσασθαι.","st":"518d"},{"sp":"N","t":"ἔοικεν γάρ, ἔφη.","st":"518d"},{"sp":"N","t":"αἱ μὲν τοίνυν ἄλλαι ἀρεταὶ καλούμεναι ψυχῆς κινδυνεύουσιν ἐγγύς τι εἶναι τῶν τοῦ σώματος — τῷ ὄντι γὰρ","st":"518d"},{"sp":"N","t":"οὐκ ἐνοῦσαι πρότερον ὕστερον ἐμποιεῖσθαι ἔθεσι καὶ ἀσκήσεσιν — ἡ δὲ τοῦ φρονῆσαι παντὸς μᾶλλον θειοτέρου τινὸς τυγχάνει, ὡς ἔοικεν, οὖσα, ὃ τὴν μὲν δύναμιν οὐδέποτε ἀπόλλυσιν, ὑπὸ δὲ τῆς περιαγωγῆς χρήσιμόν τε καὶ ὠφέλιμον","st":"518e"},{"sp":"N","t":"καὶ ἄχρηστον αὖ καὶ βλαβερὸν γίγνεται. ἢ οὔπω ἐννενόηκας, τῶν λεγομένων πονηρῶν μέν, σοφῶν δέ, ὡς δριμὺ μὲν βλέπει τὸ ψυχάριον καὶ ὀξέως διορᾷ ταῦτα ἐφ᾽ ἃ τέτραπται, ὡς οὐ φαύλην ἔχον τὴν ὄψιν, κακίᾳ δ᾽ ἠναγκασμένον ὑπηρετεῖν, ὥστε ὅσῳ ἂν ὀξύτερον βλέπῃ, τοσούτῳ πλείω κακὰ ἐργαζόμενον;","st":"519a"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη.","st":"519a"},{"sp":"N","t":"τοῦτο μέντοι, ἦν δ᾽ ἐγώ, τὸ τῆς τοιαύτης φύσεως εἰ ἐκ παιδὸς εὐθὺς κοπτόμενον περιεκόπη τὰς τῆς γενέσεως","st":"519a"},{"sp":"N","t":"συγγενεῖς ὥσπερ μολυβδίδας, αἳ δὴ ἐδωδαῖς τε καὶ τοιούτων ἡδοναῖς τε καὶ λιχνείαις προσφυεῖς γιγνόμεναι [περὶ] κάτω στρέφουσι τὴν τῆς ψυχῆς ὄψιν: ὧν εἰ ἀπαλλαγὲν περιεστρέφετο εἰς τὰ ἀληθῆ, καὶ ἐκεῖνα ἂν τὸ αὐτὸ τοῦτο τῶν αὐτῶν ἀνθρώπων ὀξύτατα ἑώρα, ὥσπερ καὶ ἐφ᾽ ἃ νῦν τέτραπται.","st":"519b"},{"sp":"N","t":"εἰκός γε, ἔφη.","st":"519b"},{"sp":"N","t":"τί δέ; τόδε οὐκ εἰκός, ἦν δ᾽ ἐγώ, καὶ ἀνάγκη ἐκ τῶν προειρημένων, μήτε τοὺς ἀπαιδεύτους καὶ ἀληθείας ἀπείρους","st":"519b"},{"sp":"N","t":"ἱκανῶς ἄν ποτε πόλιν ἐπιτροπεῦσαι, μήτε τοὺς ἐν παιδείᾳ ἐωμένους διατρίβειν διὰ τέλους, τοὺς μὲν ὅτι σκοπὸν ἐν τῷ βίῳ οὐκ ἔχουσιν ἕνα, οὗ στοχαζομένους δεῖ ἅπαντα πράττειν ἃ ἂν πράττωσιν ἰδίᾳ τε καὶ δημοσίᾳ, τοὺς δὲ ὅτι ἑκόντες εἶναι οὐ πράξουσιν, ἡγούμενοι ἐν μακάρων νήσοις ζῶντες ἔτι ἀπῳκίσθαι;","st":"519c"},{"sp":"N","t":"ἀληθῆ, ἔφη.","st":"519c"},{"sp":"N","t":"ἡμέτερον δὴ ἔργον, ἦν δ᾽ ἐγώ, τῶν οἰκιστῶν τάς τε βελτίστας φύσεις ἀναγκάσαι ἀφικέσθαι πρὸς τὸ μάθημα ὃ ἐν τῷ πρόσθεν ἔφαμεν εἶναι μέγιστον, ἰδεῖν τε τὸ ἀγαθὸν","st":"519c"},{"sp":"N","t":"καὶ ἀναβῆναι ἐκείνην τὴν ἀνάβασιν, καὶ ἐπειδὰν ἀναβάντες ἱκανῶς ἴδωσι, μὴ ἐπιτρέπειν αὐτοῖς ὃ νῦν ἐπιτρέπεται.","st":"519d"},{"sp":"N","t":"τὸ ποῖον δή;","st":"519d"},{"sp":"N","t":"τὸ αὐτοῦ, ἦν δ᾽ ἐγώ, καταμένειν καὶ μὴ ἐθέλειν πάλιν καταβαίνειν παρ᾽ ἐκείνους τοὺς δεσμώτας μηδὲ μετέχειν τῶν παρ᾽ ἐκείνοις πόνων τε καὶ τιμῶν, εἴτε φαυλότεραι εἴτε σπουδαιότεραι.","st":"519d"},{"sp":"N","t":"ἔπειτ᾽, ἔφη, ἀδικήσομεν αὐτούς, καὶ ποιήσομεν χεῖρον ζῆν, δυνατὸν αὐτοῖς ὂν ἄμεινον;","st":"519d"},{"sp":"N","t":"ἐπελάθου, ἦν δ᾽ ἐγώ, πάλιν, ὦ φίλε, ὅτι νόμῳ οὐ τοῦτο μέλει, ὅπως ἕν τι γένος ἐν πόλει διαφερόντως εὖ πράξει, ἀλλ᾽ ἐν ὅλῃ τῇ πόλει τοῦτο μηχανᾶται ἐγγενέσθαι, συναρμόττων τοὺς πολίτας πειθοῖ τε καὶ ἀνάγκῃ, ποιῶν μεταδιδόναι","st":"519e"},{"sp":"N","t":"ἀλλήλοις τῆς ὠφελίας ἣν ἂν ἕκαστοι τὸ κοινὸν δυνατοὶ ὦσιν ὠφελεῖν καὶ αὐτὸς ἐμποιῶν τοιούτους ἄνδρας ἐν τῇ πόλει, οὐχ ἵνα ἀφιῇ τρέπεσθαι ὅπῃ ἕκαστος βούλεται, ἀλλ᾽ ἵνα καταχρῆται αὐτὸς αὐτοῖς ἐπὶ τὸν σύνδεσμον τῆς πόλεως.","st":"520a"},{"sp":"N","t":"ἀληθῆ, ἔφη: ἐπελαθόμην γάρ.","st":"520a"},{"sp":"N","t":"σκέψαι τοίνυν, εἶπον, ὦ Γλαύκων, ὅτι οὐδ᾽ ἀδικήσομεν τοὺς παρ᾽ ἡμῖν φιλοσόφους γιγνομένους, ἀλλὰ δίκαια πρὸς αὐτοὺς ἐροῦμεν, προσαναγκάζοντες τῶν ἄλλων ἐπιμελεῖσθαί τε καὶ φυλάττειν. ἐροῦμεν γὰρ ὅτι οἱ μὲν ἐν ταῖς ἄλλαις","st":"520a"},{"sp":"N","t":"πόλεσι τοιοῦτοι γιγνόμενοι εἰκότως οὐ μετέχουσι τῶν ἐν αὐταῖς πόνων: αὐτόματοι γὰρ ἐμφύονται ἀκούσης τῆς ἐν ἑκάστῃ πολιτείας, δίκην δ᾽ ἔχει τό γε αὐτοφυὲς μηδενὶ τροφὴν ὀφεῖλον μηδ᾽ ἐκτίνειν τῳ προθυμεῖσθαι τὰ τροφεῖα: ὑμᾶς δ᾽ ἡμεῖς ὑμῖν τε αὐτοῖς τῇ τε ἄλλῃ πόλει ὥσπερ ἐν σμήνεσιν ἡγεμόνας τε καὶ βασιλέας ἐγεννήσαμεν, ἄμεινόν τε καὶ τελεώτερον ἐκείνων πεπαιδευμένους καὶ μᾶλλον δυνατοὺς","st":"520b"},{"sp":"N","t":"ἀμφοτέρων μετέχειν. καταβατέον οὖν ἐν μέρει ἑκάστῳ εἰς τὴν τῶν ἄλλων συνοίκησιν καὶ συνεθιστέον τὰ σκοτεινὰ θεάσασθαι: συνεθιζόμενοι γὰρ μυρίῳ βέλτιον ὄψεσθε τῶν ἐκεῖ καὶ γνώσεσθε ἕκαστα τὰ εἴδωλα ἅττα ἐστὶ καὶ ὧν, διὰ τὸ τἀληθῆ ἑωρακέναι καλῶν τε καὶ δικαίων καὶ ἀγαθῶν πέρι. καὶ οὕτω ὕπαρ ἡμῖν καὶ ὑμῖν ἡ πόλις οἰκήσεται ἀλλ᾽ οὐκ ὄναρ, ὡς νῦν αἱ πολλαὶ ὑπὸ σκιαμαχούντων τε πρὸς ἀλλήλους καὶ στασιαζόντων περὶ τοῦ ἄρχειν","st":"520c"},{"sp":"N","t":"οἰκοῦνται, ὡς μεγάλου τινὸς ἀγαθοῦ ὄντος. τὸ δέ που ἀληθὲς ὧδ᾽ ἔχει: ἐν πόλει ᾗ ἥκιστα πρόθυμοι ἄρχειν οἱ μέλλοντες ἄρξειν, ταύτην ἄριστα καὶ ἀστασιαστότατα ἀνάγκη οἰκεῖσθαι, τὴν δ᾽ ἐναντίους ἄρχοντας σχοῦσαν ἐναντίως.","st":"520d"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη.","st":"520d"},{"sp":"N","t":"ἀπειθήσουσιν οὖν ἡμῖν οἴει οἱ τρόφιμοι ταῦτ᾽ ἀκούοντες, καὶ οὐκ ἐθελήσουσιν συμπονεῖν ἐν τῇ πόλει ἕκαστοι ἐν μέρει, τὸν δὲ πολὺν χρόνον μετ᾽ ἀλλήλων οἰκεῖν ἐν τῷ καθαρῷ;","st":"520d"},{"sp":"N","t":"ἀδύνατον, ἔφη: δίκαια γὰρ δὴ δικαίοις ἐπιτάξομεν. παντὸς μὴν μᾶλλον ὡς ἐπ᾽ ἀναγκαῖον αὐτῶν ἕκαστος εἶσι τὸ ἄρχειν, τοὐναντίον τῶν νῦν ἐν ἑκάστῃ πόλει ἀρχόντων.","st":"520e"},{"sp":"N","t":"οὕτω γὰρ ἔχει, ἦν δ᾽ ἐγώ, ὦ ἑταῖρε: εἰ μὲν βίον ἐξευρήσεις","st":"520e"},{"sp":"N","t":"ἀμείνω τοῦ ἄρχειν τοῖς μέλλουσιν ἄρξειν, ἔστι σοι δυνατὴ γενέσθαι πόλις εὖ οἰκουμένη: ἐν μόνῃ γὰρ αὐτῇ ἄρξουσιν οἱ τῷ ὄντι πλούσιοι, οὐ χρυσίου ἀλλ᾽ οὗ δεῖ τὸν εὐδαίμονα πλουτεῖν, ζωῆς ἀγαθῆς τε καὶ ἔμφρονος. εἰ δὲ πτωχοὶ καὶ πεινῶντες ἀγαθῶν ἰδίων ἐπὶ τὰ δημόσια ἴασιν, ἐντεῦθεν οἰόμενοι τἀγαθὸν δεῖν ἁρπάζειν, οὐκ ἔστι: περιμάχητον γὰρ τὸ ἄρχειν γιγνόμενον, οἰκεῖος ὢν καὶ ἔνδον ὁ τοιοῦτος πόλεμος αὐτούς τε ἀπόλλυσι καὶ τὴν ἄλλην πόλιν.","st":"521a"},{"sp":"N","t":"ἀληθέστατα, ἔφη.","st":"521a"},{"sp":"N","t":"ἔχεις οὖν, ἦν δ᾽ ἐγώ, βίον ἄλλον τινὰ πολιτικῶν ἀρχῶν καταφρονοῦντα ἢ τὸν τῆς ἀληθινῆς φιλοσοφίας;","st":"521b"},{"sp":"N","t":"οὐ μὰ τὸν Δία, ἦ δ᾽ ὅς.","st":"521b"},{"sp":"N","t":"ἀλλὰ μέντοι δεῖ γε μὴ ἐραστὰς τοῦ ἄρχειν ἰέναι ἐπ᾽ αὐτό: εἰ δὲ μή, οἵ γε ἀντερασταὶ μαχοῦνται.","st":"521b"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"521b"},{"sp":"N","t":"τίνας οὖν ἄλλους ἀναγκάσεις ἰέναι ἐπὶ φυλακὴν τῆς πόλεως ἢ οἳ περὶ τούτων τε φρονιμώτατοι δι᾽ ὧν ἄριστα πόλις οἰκεῖται, ἔχουσί τε τιμὰς ἄλλας καὶ βίον ἀμείνω τοῦ πολιτικοῦ;","st":"521b"},{"sp":"N","t":"οὐδένας ἄλλους, ἔφη.","st":"521b"},{"sp":"N","t":"βούλει οὖν τοῦτ᾽ ἤδη σκοπῶμεν, τίνα τρόπον οἱ τοιοῦτοι ἐγγενήσονται, καὶ πῶς τις ἀνάξει αὐτοὺς εἰς φῶς, ὥσπερ ἐξ Ἅιδου λέγονται δή τινες εἰς θεοὺς ἀνελθεῖν;","st":"521c"},{"sp":"N","t":"πῶς γὰρ οὐ βούλομαι; ἔφη.","st":"521c"},{"sp":"N","t":"τοῦτο δή, ὡς ἔοικεν, οὐκ ὀστράκου ἂν εἴη περιστροφή, ἀλλὰ ψυχῆς περιαγωγὴ ἐκ νυκτερινῆς τινος ἡμέρας εἰς ἀληθινήν, τοῦ ὄντος οὖσαν ἐπάνοδον, ἣν δὴ φιλοσοφίαν ἀληθῆ φήσομεν εἶναι.","st":"521c"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"521c"},{"sp":"N","t":"οὐκοῦν δεῖ σκοπεῖσθαι τί τῶν μαθημάτων ἔχει τοιαύτην","st":"521c"},{"sp":"N","t":"δύναμιν;","st":"521d"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"521d"},{"sp":"N","t":"τί ἂν οὖν εἴη, ὦ Γλαύκων, μάθημα ψυχῆς ὁλκὸν ἀπὸ τοῦ γιγνομένου ἐπὶ τὸ ὄν; τόδε δ᾽ ἐννοῶ λέγων ἅμα: οὐκ ἀθλητὰς μέντοι πολέμου ἔφαμεν τούτους ἀναγκαῖον εἶναι νέους ὄντας;","st":"521d"},{"sp":"N","t":"ἔφαμεν γάρ.","st":"521d"},{"sp":"N","t":"δεῖ ἄρα καὶ τοῦτο προσέχειν τὸ μάθημα ὃ ζητοῦμεν πρὸς ἐκείνῳ.","st":"521d"},{"sp":"N","t":"τὸ ποῖον;","st":"521d"},{"sp":"N","t":"μὴ ἄχρηστον πολεμικοῖς ἀνδράσιν εἶναι.","st":"521d"},{"sp":"N","t":"δεῖ μέντοι, ἔφη, εἴπερ οἷόν τε.","st":"521d"},{"sp":"N","t":"γυμναστικῇ μὴν καὶ μουσικῇ ἔν γε τῷ πρόσθεν ἐπαιδεύοντο","st":"521d"},{"sp":"N","t":"ἡμῖν.","st":"521e"},{"sp":"N","t":"ἦν ταῦτα, ἔφη.","st":"521e"},{"sp":"N","t":"καὶ γυμναστικὴ μέν που περὶ γιγνόμενον καὶ ἀπολλύμενον τετεύτακεν: σώματος γὰρ αὔξης καὶ φθίσεως. ἐπιστατεῖ.","st":"521e"},{"sp":"N","t":"φαίνεται.","st":"521e"},{"sp":"N","t":"τοῦτο μὲν δὴ οὐκ ἂν εἴη ὃ ζητοῦμεν μάθημα.","st":"521e"},{"sp":"N","t":"οὐ γάρ.","st":"522a"},{"sp":"N","t":"ἀλλ᾽ ἆρα μουσικὴ ὅσην τὸ πρότερον διήλθομεν;","st":"522a"},{"sp":"N","t":"ἀλλ᾽ ἦν ἐκείνη γ᾽, ἔφη, ἀντίστροφος τῆς γυμναστικῆς, εἰ μέμνησαι, ἔθεσι παιδεύουσα τοὺς φύλακας, κατά τε ἁρμονίαν εὐαρμοστίαν τινά, οὐκ ἐπιστήμην, παραδιδοῦσα, καὶ κατὰ ῥυθμὸν εὐρυθμίαν, ἔν τε τοῖς λόγοις ἕτερα τούτων ἀδελφὰ ἔθη ἄττα ἔχουσα, καὶ ὅσοι μυθώδεις τῶν λόγων καὶ ὅσοι ἀληθινώτεροι ἦσαν: μάθημα δὲ πρὸς τοιοῦτόν τι","st":"522a"},{"sp":"N","t":"ἄγον, οἷον σὺ νῦν ζητεῖς, οὐδὲν ἦν ἐν αὐτῇ.","st":"522b"},{"sp":"N","t":"ἀκριβέστατα, ἦν δ᾽ ἐγώ, ἀναμιμνῄσκεις με: τῷ γὰρ ὄντι τοιοῦτον οὐδὲν εἶχεν. ἀλλ᾽, ὦ δαιμόνιε Γλαύκων, τί ἂν εἴη τοιοῦτον; αἵ τε γὰρ τέχναι βάναυσοί που ἅπασαι ἔδοξαν εἶναι-","st":"522b"},{"sp":"N","t":"πῶς δ᾽ οὔ; καὶ μὴν τί ἔτ᾽ ἄλλο λείπεται μάθημα, μουσικῆς καὶ γυμναστικῆς καὶ τῶν τεχνῶν κεχωρισμένον;","st":"522b"},{"sp":"N","t":"φέρε, ἦν δ᾽ ἐγώ, εἰ μηδὲν ἔτι ἐκτὸς τούτων ἔχομεν λαβεῖν, τῶν ἐπὶ πάντα τεινόντων τι λάβωμεν.","st":"522b"},{"sp":"N","t":"τὸ ποῖον;","st":"522b"},{"sp":"N","t":"οἷον τοῦτο τὸ κοινόν, ᾧ πᾶσαι προσχρῶνται τέχναι τε καὶ διάνοιαι καὶ ἐπιστῆμαι — ὃ καὶ παντὶ ἐν πρώτοις ἀνάγκη μανθάνειν.","st":"522c"},{"sp":"N","t":"τὸ ποῖον; ἔφη.","st":"522c"},{"sp":"N","t":"τὸ φαῦλον τοῦτο, ἦν δ᾽ ἐγώ, τὸ ἕν τε καὶ τὰ δύο καὶ τὰ τρία διαγιγνώσκειν: λέγω δὲ αὐτὸ ἐν κεφαλαίῳ ἀριθμόν τε καὶ λογισμόν. ἢ οὐχ οὕτω περὶ τούτων ἔχει, ὡς πᾶσα τέχνη τε καὶ ἐπιστήμη ἀναγκάζεται αὐτῶν μέτοχος γίγνεσθαι;","st":"522c"},{"sp":"N","t":"καὶ μάλα, ἔφη.","st":"522c"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, καὶ ἡ πολεμική;","st":"522c"},{"sp":"N","t":"πολλή, ἔφη, ἀνάγκη.","st":"522c"},{"sp":"N","t":"παγγέλοιον γοῦν, ἔφην, στρατηγὸν Ἀγαμέμνονα ἐν ταῖς τραγῳδίαις Παλαμήδης ἑκάστοτε ἀποφαίνει. ἢ οὐκ ἐννενόηκας ὅτι φησὶν ἀριθμὸν εὑρὼν τάς τε τάξεις τῷ στρατοπέδῳ καταστῆσαι ἐν Ἰλίῳ καὶ ἐξαριθμῆσαι ναῦς τε καὶ τἆλλα πάντα, ὡς πρὸ τοῦ ἀναριθμήτων ὄντων καὶ τοῦ Ἀγαμέμνονος, ὡς ἔοικεν, οὐδ᾽ ὅσους πόδας εἶχεν εἰδότος, εἴπερ ἀριθμεῖν μὴ ἠπίστατο; καίτοι ποῖόν τιν᾽ αὐτὸν οἴει στρατηγὸν εἶναι;","st":"522d"},{"sp":"N","t":"ἄτοπόν τιν᾽, ἔφη, ἔγωγε, εἰ ἦν τοῦτ᾽ ἀληθές.","st":"522d"},{"sp":"N","t":"ἄλλο τι οὖν, ἦν δ᾽ ἐγώ, μάθημα ἀναγκαῖον πολεμικῷ ἀνδρὶ θήσομεν λογίζεσθαί τε καὶ ἀριθμεῖν δύνασθαι;","st":"522e"},{"sp":"N","t":"πάντων γ᾽, ἔφη, μάλιστα, εἰ καὶ ὁτιοῦν μέλλει τάξεων ἐπαΐειν, μᾶλλον δ᾽ εἰ καὶ ἄνθρωπος ἔσεσθαι.","st":"522e"},{"sp":"N","t":"ἐννοεῖς οὖν, εἶπον, περὶ τοῦτο τὸ μάθημα ὅπερ ἐγώ;","st":"522e"},{"sp":"N","t":"τὸ ποῖον;","st":"522e"},{"sp":"N","t":"κινδυνεύει τῶν πρὸς τὴν νόησιν ἀγόντων φύσει εἶναι ὧν ζητοῦμεν, χρῆσθαι δ᾽ οὐδεὶς αὐτῷ ὀρθῶς, ἑλκτικῷ ὄντι παντάπασι πρὸς οὐσίαν.","st":"523a"},{"sp":"N","t":"πῶς, ἔφη, λέγεις;","st":"523a"},{"sp":"N","t":"ἐγὼ πειράσομαι, ἦν δ᾽ ἐγώ, τό γ᾽ ἐμοὶ δοκοῦν δηλῶσαι. ἃ γὰρ διαιροῦμαι παρ᾽ ἐμαυτῷ ἀγωγά τε εἶναι οἷ λέγομεν καὶ μή, συνθεατὴς γενόμενος σύμφαθι ἢ ἄπειπε, ἵνα καὶ τοῦτο σαφέστερον ἴδωμεν εἰ ἔστιν οἷον μαντεύομαι.","st":"523a"},{"sp":"N","t":"δείκνυ᾽, ἔφη.","st":"523a"},{"sp":"N","t":"δείκνυμι δή, εἶπον, εἰ καθορᾷς, τὰ μὲν ἐν ταῖς αἰσθήσεσιν","st":"523a"},{"sp":"N","t":"οὐ παρακαλοῦντα τὴν νόησιν εἰς ἐπίσκεψιν, ὡς ἱκανῶς ὑπὸ τῆς αἰσθήσεως κρινόμενα, τὰ δὲ παντάπασι διακελευόμενα ἐκείνην ἐπισκέψασθαι, ὡς τῆς αἰσθήσεως οὐδὲν ὑγιὲς ποιούσης.","st":"523b"},{"sp":"N","t":"τὰ πόρρωθεν, ἔφη, φαινόμενα δῆλον ὅτι λέγεις καὶ τὰ ἐσκιαγραφημένα.","st":"523b"},{"sp":"N","t":"οὐ πάνυ, ἦν δ᾽ ἐγώ, ἔτυχες οὗ λέγω.","st":"523b"},{"sp":"N","t":"ποῖα μήν, ἔφη, λέγεις;","st":"523b"},{"sp":"N","t":"τὰ μὲν οὐ παρακαλοῦντα, ἦν δ᾽ ἐγώ, ὅσα μὴ ἐκβαίνει","st":"523b"},{"sp":"N","t":"εἰς ἐναντίαν αἴσθησιν ἅμα: τὰ δ᾽ ἐκβαίνοντα ὡς παρακαλοῦντα τίθημι, ἐπειδὰν ἡ αἴσθησις μηδὲν μᾶλλον τοῦτο ἢ τὸ ἐναντίον δηλοῖ, εἴτ᾽ ἐγγύθεν προσπίπτουσα εἴτε πόρρωθεν. ὧδε δὲ ἃ λέγω σαφέστερον εἴσῃ. οὗτοί φαμεν τρεῖς ἂν εἶεν δάκτυλοι, ὅ τε σμικρότατος καὶ ὁ δεύτερος καὶ ὁ μέσος.","st":"523c"},{"sp":"N","t":"πάνυ γ᾽, ἔφη.","st":"523c"},{"sp":"N","t":"ὡς ἐγγύθεν τοίνυν ὁρωμένους λέγοντός μου διανοοῦ. ἀλλά μοι περὶ αὐτῶν τόδε σκόπει.","st":"523c"},{"sp":"N","t":"τὸ ποῖον;","st":"523c"},{"sp":"N","t":"δάκτυλος μέν που αὐτῶν φαίνεται ὁμοίως ἕκαστος, καὶ","st":"523c"},{"sp":"N","t":"ταύτῃ γε οὐδὲν διαφέρει, ἐάντε ἐν μέσῳ ὁρᾶται ἐάντ᾽ ἐπ᾽ ἐσχάτῳ, ἐάντε λευκὸς ἐάντε μέλας, ἐάντε παχὺς ἐάντε λεπτός, καὶ πᾶν ὅτι τοιοῦτον. ἐν πᾶσι γὰρ τούτοις οὐκ ἀναγκάζεται τῶν πολλῶν ἡ ψυχὴ τὴν νόησιν ἐπερέσθαι τί ποτ᾽ ἐστὶ δάκτυλος: οὐδαμοῦ γὰρ ἡ ὄψις αὐτῇ ἅμα ἐσήμηνεν τὸ δάκτυλον τοὐναντίον ἢ δάκτυλον εἶναι.","st":"523d"},{"sp":"N","t":"οὐ γὰρ οὖν, ἔφη.","st":"523d"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, εἰκότως τό γε τοιοῦτον νοήσεως οὐκ","st":"523d"},{"sp":"N","t":"ἂν παρακλητικὸν οὐδ᾽ ἐγερτικὸν εἴη.","st":"523e"},{"sp":"N","t":"εἰκότως.","st":"523e"},{"sp":"N","t":"τί δὲ δή; τὸ μέγεθος αὐτῶν καὶ τὴν σμικρότητα ἡ ὄψις ἆρα ἱκανῶς ὁρᾷ, καὶ οὐδὲν αὐτῇ διαφέρει ἐν μέσῳ τινὰ αὐτῶν κεῖσθαι ἢ ἐπ᾽ ἐσχάτῳ; καὶ ὡσαύτως πάχος καὶ λεπτότητα ἢ μαλακότητα καὶ σκληρότητα ἡ ἁφή; καὶ αἱ ἄλλαι αἰσθήσεις ἆρ᾽ οὐκ ἐνδεῶς τὰ τοιαῦτα δηλοῦσιν; ἢ","st":"523e"},{"sp":"N","t":"ὧδε ποιεῖ ἑκάστη αὐτῶν: πρῶτον μὲν ἡ ἐπὶ τῷ σκληρῷ τεταγμένη αἴσθησις ἠνάγκασται καὶ ἐπὶ τῷ μαλακῷ τετάχθαι, καὶ παραγγέλλει τῇ ψυχῇ ὡς ταὐτὸν σκληρόν τε καὶ μαλακὸν αἰσθανομένη;","st":"524a"},{"sp":"N","t":"οὕτως, ἔφη.","st":"524a"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, ἀναγκαῖον ἔν γε τοῖς τοιούτοις αὖ τὴν ψυχὴν ἀπορεῖν τί ποτε σημαίνει αὕτη ἡ αἴσθησις τὸ σκληρόν, εἴπερ τὸ αὐτὸ καὶ μαλακὸν λέγει, καὶ ἡ τοῦ κούφου καὶ ἡ τοῦ βαρέος, τί τὸ κοῦφον καὶ βαρύ, εἰ τό τε βαρὺ κοῦφον καὶ τὸ κοῦφον βαρὺ σημαίνει;","st":"524a"},{"sp":"N","t":"καὶ γάρ, ἔφη, αὗταί γε ἄτοποι τῇ ψυχῇ αἱ ἑρμηνεῖαι καὶ ἐπισκέψεως δεόμεναι.","st":"524b"},{"sp":"N","t":"εἰκότως ἄρα, ἦν δ᾽ ἐγώ, ἐν τοῖς τοιούτοις πρῶτον μὲν πειρᾶται λογισμόν τε καὶ νόησιν ψυχὴ παρακαλοῦσα ἐπισκοπεῖν εἴτε ἓν εἴτε δύο ἐστὶν ἕκαστα τῶν εἰσαγγελλομένων.","st":"524b"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"524b"},{"sp":"N","t":"οὐκοῦν ἐὰν δύο φαίνηται, ἕτερόν τε καὶ ἓν ἑκάτερον φαίνεται;","st":"524b"},{"sp":"N","t":"ναί.","st":"524b"},{"sp":"N","t":"εἰ ἄρα ἓν ἑκάτερον, ἀμφότερα δὲ δύο, τά γε δύο κεχωρισμένα","st":"524b"},{"sp":"N","t":"νοήσει: οὐ γὰρ ἂν ἀχώριστά γε δύο ἐνόει, ἀλλ᾽ ἕν.","st":"524c"},{"sp":"N","t":"ὀρθῶς.","st":"524c"},{"sp":"N","t":"μέγα μὴν καὶ ὄψις καὶ σμικρὸν ἑώρα, φαμέν, ἀλλ᾽ οὐ κεχωρισμένον ἀλλὰ συγκεχυμένον τι. ἦ γάρ;","st":"524c"},{"sp":"N","t":"ναί.","st":"524c"},{"sp":"N","t":"διὰ δὲ τὴν τούτου σαφήνειαν μέγα αὖ καὶ σμικρὸν ἡ νόησις ἠναγκάσθη ἰδεῖν, οὐ συγκεχυμένα ἀλλὰ διωρισμένα, τοὐναντίον ἢ ‘κείνη.","st":"524c"},{"sp":"N","t":"ἀληθῆ.","st":"524c"},{"sp":"N","t":"οὐκοῦν ἐντεῦθέν ποθεν πρῶτον ἐπέρχεται ἐρέσθαι ἡμῖν τί οὖν ποτ᾽ ἐστὶ τὸ μέγα αὖ καὶ τὸ σμικρόν;","st":"524c"},{"sp":"N","t":"παντάπασι μὲν οὖν.","st":"524c"},{"sp":"N","t":"καὶ οὕτω δὴ τὸ μὲν νοητόν, τὸ δ᾽ ὁρατὸν ἐκαλέσαμεν.","st":"524c"},{"sp":"N","t":"ὀρθότατ᾽, ἔφη.","st":"524d"},{"sp":"N","t":"ταῦτα τοίνυν καὶ ἄρτι ἐπεχείρουν λέγειν, ὡς τὰ μὲν παρακλητικὰ τῆς διανοίας ἐστί, τὰ δ᾽ οὔ, ἃ μὲν εἰς τὴν αἴσθησιν ἅμα τοῖς ἐναντίοις ἑαυτοῖς ἐμπίπτει, παρακλητικὰ ὁριζόμενος, ὅσα δὲ μή, οὐκ ἐγερτικὰ τῆς νοήσεως.","st":"524d"},{"sp":"N","t":"μανθάνω τοίνυν ἤδη, ἔφη, καὶ δοκεῖ μοι οὕτω.","st":"524d"},{"sp":"N","t":"τί οὖν; ἀριθμός τε καὶ τὸ ἓν ποτέρων δοκεῖ εἶναι;","st":"524d"},{"sp":"N","t":"οὐ συννοῶ, ἔφη.","st":"524d"},{"sp":"N","t":"ἀλλ᾽ ἐκ τῶν προειρημένων, ἔφην, ἀναλογίζου. εἰ μὲν γὰρ ἱκανῶς αὐτὸ καθ᾽ αὑτὸ ὁρᾶται ἢ ἄλλῃ τινὶ αἰσθήσει","st":"524d"},{"sp":"N","t":"λαμβάνεται τὸ ἕν, οὐκ ἂν ὁλκὸν εἴη ἐπὶ τὴν οὐσίαν, ὥσπερ ἐπὶ τοῦ δακτύλου ἐλέγομεν: εἰ δ᾽ ἀεί τι αὐτῷ ἅμα ὁρᾶται ἐναντίωμα, ὥστε μηδὲν μᾶλλον ἓν ἢ καὶ τοὐναντίον φαίνεσθαι, τοῦ ἐπικρινοῦντος δὴ δέοι ἂν ἤδη καὶ ἀναγκάζοιτ᾽ ἂν ἐν αὐτῷ ψυχὴ ἀπορεῖν καὶ ζητεῖν, κινοῦσα ἐν ἑαυτῇ τὴν ἔννοιαν, καὶ ἀνερωτᾶν τί ποτέ ἐστιν αὐτὸ τὸ ἕν, καὶ οὕτω τῶν","st":"524e"},{"sp":"N","t":"ἀγωγῶν ἂν εἴη καὶ μεταστρεπτικῶν ἐπὶ τὴν τοῦ ὄντος θέαν ἡ περὶ τὸ ἓν μάθησις.","st":"525a"},{"sp":"N","t":"ἀλλὰ μέντοι, ἔφη, τοῦτό γ᾽ ἔχει οὐχ ἥκιστα ἡ περὶ αὐτὸ ὄψις: ἅμα γὰρ ταὐτὸν ὡς ἕν τε ὁρῶμεν καὶ ὡς ἄπειρα τὸ πλῆθος.","st":"525a"},{"sp":"N","t":"οὐκοῦν εἴπερ τὸ ἕν, ἦν δ᾽ ἐγώ, καὶ σύμπας ἀριθμὸς ταὐτὸν πέπονθε τοῦτο;","st":"525a"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"525a"},{"sp":"N","t":"ἀλλὰ μὴν λογιστική τε καὶ ἀριθμητικὴ περὶ ἀριθμὸν πᾶσα.","st":"525a"},{"sp":"N","t":"καὶ μάλα.","st":"525a"},{"sp":"N","t":"ταῦτα δέ γε φαίνεται ἀγωγὰ πρὸς ἀλήθειαν.","st":"525b"},{"sp":"N","t":"ὑπερφυῶς μὲν οὖν.","st":"525b"},{"sp":"N","t":"ὧν ζητοῦμεν ἄρα, ὡς ἔοικε, μαθημάτων ἂν εἴη: πολεμικῷ μὲν γὰρ διὰ τὰς τάξεις ἀναγκαῖον μαθεῖν ταῦτα, φιλοσόφῳ δὲ διὰ τὸ τῆς οὐσίας ἁπτέον εἶναι γενέσεως ἐξαναδύντι, ἢ μηδέποτε λογιστικῷ γενέσθαι.","st":"525b"},{"sp":"N","t":"ἔστι ταῦτ᾽, ἔφη.","st":"525b"},{"sp":"N","t":"ὁ δέ γε ἡμέτερος φύλαξ πολεμικός τε καὶ φιλόσοφος τυγχάνει ὤν.","st":"525b"},{"sp":"N","t":"τί μήν;","st":"525b"},{"sp":"N","t":"προσῆκον δὴ τὸ μάθημα ἂν εἴη, ὦ Γλαύκων, νομοθετῆσαι καὶ πείθειν τοὺς μέλλοντας ἐν τῇ πόλει τῶν μεγίστων","st":"525b"},{"sp":"N","t":"μεθέξειν ἐπὶ λογιστικὴν ἰέναι καὶ ἀνθάπτεσθαι αὐτῆς μὴ ἰδιωτικῶς, ἀλλ᾽ ἕως ἂν ἐπὶ θέαν τῆς τῶν ἀριθμῶν φύσεως ἀφίκωνται τῇ νοήσει αὐτῇ, οὐκ ὠνῆς οὐδὲ πράσεως χάριν ὡς ἐμπόρους ἢ καπήλους μελετῶντας, ἀλλ᾽ ἕνεκα πολέμου τε καὶ αὐτῆς τῆς ψυχῆς ῥᾳστώνης μεταστροφῆς ἀπὸ γενέσεως ἐπ᾽ ἀλήθειάν τε καὶ οὐσίαν.","st":"525c"},{"sp":"N","t":"κάλλιστ᾽, ἔφη, λέγεις.","st":"525c"},{"sp":"N","t":"καὶ μήν, ἦν δ᾽ ἐγώ, νῦν καὶ ἐννοῶ, ῥηθέντος τοῦ περὶ","st":"525c"},{"sp":"N","t":"τοὺς λογισμοὺς μαθήματος, ὡς κομψόν ἐστι καὶ πολλαχῇ χρήσιμον ἡμῖν πρὸς ὃ βουλόμεθα, ἐὰν τοῦ γνωρίζειν ἕνεκά τις αὐτὸ ἐπιτηδεύῃ ἀλλὰ μὴ τοῦ καπηλεύειν.","st":"525d"},{"sp":"N","t":"πῇ δή; ἔφη.","st":"525d"},{"sp":"N","t":"τοῦτό γε, ὃ νυνδὴ ἐλέγομεν, ὡς σφόδρα ἄνω ποι ἄγει τὴν ψυχὴν καὶ περὶ αὐτῶν τῶν ἀριθμῶν ἀναγκάζει διαλέγεσθαι, οὐδαμῇ ἀποδεχόμενον ἐάν τις αὐτῇ ὁρατὰ ἢ ἁπτὰ σώματα ἔχοντας ἀριθμοὺς προτεινόμενος διαλέγηται. οἶσθα γάρ που τοὺς περὶ ταῦτα δεινοὺς αὖ ὡς, ἐάν τις αὐτὸ τὸ","st":"525d"},{"sp":"N","t":"ἓν ἐπιχειρῇ τῷ λόγῳ τέμνειν, καταγελῶσί τε καὶ οὐκ ἀποδέχονται, ἀλλ᾽ ἐὰν σὺ κερματίζῃς αὐτό, ἐκεῖνοι πολλαπλασιοῦσιν, εὐλαβούμενοι μή ποτε φανῇ τὸ ἓν μὴ ἓν ἀλλὰ πολλὰ μόρια.","st":"525e"},{"sp":"N","t":"ἀληθέστατα, ἔφη, λέγεις.","st":"525e"},{"sp":"N","t":"τί οὖν οἴει, ὦ Γλαύκων, εἴ τις ἔροιτο αὐτούς: “ὦ θαυμάσιοι, περὶ ποίων ἀριθμῶν διαλέγεσθε, ἐν οἷς τὸ ἓν οἷον ὑμεῖς ἀξιοῦτέ ἐστιν, ἴσον τε ἕκαστον πᾶν παντὶ καὶ οὐδὲ σμικρὸν διαφέρον, μόριόν τε ἔχον ἐν ἑαυτῷ οὐδέν;” τί ἂν οἴει αὐτοὺς ἀποκρίνασθαι;","st":"526a"},{"sp":"N","t":"τοῦτο ἔγωγε, ὅτι περὶ τούτων λέγουσιν ὧν διανοηθῆναι μόνον ἐγχωρεῖ, ἄλλως δ᾽ οὐδαμῶς μεταχειρίζεσθαι δυνατόν.","st":"526a"},{"sp":"N","t":"ὁρᾷς οὖν, ἦν δ᾽ ἐγώ, ὦ φίλε, ὅτι τῷ ὄντι ἀναγκαῖον","st":"526a"},{"sp":"N","t":"ἡμῖν κινδυνεύει εἶναι τὸ μάθημα, ἐπειδὴ φαίνεταί γε προσαναγκάζον αὐτῇ τῇ νοήσει χρῆσθαι τὴν ψυχὴν ἐπ᾽ αὐτὴν τὴν ἀλήθειαν;","st":"526b"},{"sp":"N","t":"καὶ μὲν δή, ἔφη, σφόδρα γε ποιεῖ αὐτό.","st":"526b"},{"sp":"N","t":"τί δέ; τόδε ἤδη ἐπεσκέψω, ὡς οἵ τε φύσει λογιστικοὶ εἰς πάντα τὰ μαθήματα ὡς ἔπος εἰπεῖν ὀξεῖς φύονται, οἵ τε βραδεῖς, ἂν ἐν τούτῳ παιδευθῶσιν καὶ γυμνάσωνται, κἂν μηδὲν ἄλλο ὠφεληθῶσιν, ὅμως εἴς γε τὸ ὀξύτεροι αὐτοὶ αὑτῶν γίγνεσθαι πάντες ἐπιδιδόασιν;","st":"526b"},{"sp":"N","t":"ἔστιν, ἔφη, οὕτω.","st":"526b"},{"sp":"N","t":"καὶ μήν, ὡς ἐγᾦμαι, ἅ γε μείζω πόνον παρέχει μανθάνοντι καὶ μελετῶντι, οὐκ ἂν ῥᾳδίως οὐδὲ πολλὰ ἂν εὕροις ὡς τοῦτο.","st":"526c"},{"sp":"N","t":"οὐ γὰρ οὖν.","st":"526c"},{"sp":"N","t":"πάντων δὴ ἕνεκα τούτων οὐκ ἀφετέον τὸ μάθημα, ἀλλ᾽ οἱ ἄριστοι τὰς φύσεις παιδευτέοι ἐν αὐτῷ.","st":"526c"},{"sp":"N","t":"σύμφημι, ἦ δ᾽ ὅς.","st":"526c"},{"sp":"N","t":"τοῦτο μὲν τοίνυν, εἶπον, ἓν ἡμῖν κείσθω: δεύτερον δὲ τὸ ἐχόμενον τούτου σκεψώμεθα ἆρά τι προσήκει ἡμῖν.","st":"526c"},{"sp":"N","t":"τὸ ποῖον; ἢ γεωμετρίαν, ἔφη, λέγεις;","st":"526c"},{"sp":"N","t":"αὐτὸ τοῦτο, ἦν δ᾽ ἐγώ.","st":"526c"},{"sp":"N","t":"ὅσον μέν, ἔφη, πρὸς τὰ πολεμικὰ αὐτοῦ τείνει, δῆλον ὅτι προσήκει: πρὸς γὰρ τὰς στρατοπεδεύσεις καὶ καταλήψεις χωρίων καὶ συναγωγὰς καὶ ἐκτάσεις στρατιᾶς καὶ ὅσα δὴ ἄλλα σχηματίζουσι τὰ στρατόπεδα ἐν αὐταῖς τε ταῖς μάχαις καὶ πορείαις διαφέροι ἂν αὐτὸς αὑτοῦ γεωμετρικός τε καὶ μὴ ὤν.","st":"526d"},{"sp":"N","t":"ἀλλ᾽ οὖν δή, εἶπον, πρὸς μὲν τὰ τοιαῦτα καὶ βραχύ τι ἂν ἐξαρκοῖ γεωμετρίας τε καὶ λογισμῶν μόριον: τὸ δὲ πολὺ αὐτῆς καὶ πορρωτέρω προϊὸν σκοπεῖσθαι δεῖ εἴ τι πρὸς ἐκεῖνο","st":"526d"},{"sp":"N","t":"τείνει, πρὸς τὸ ποιεῖν κατιδεῖν ῥᾷον τὴν τοῦ ἀγαθοῦ ἰδέαν. τείνει δέ, φαμέν, πάντα αὐτόσε, ὅσα ἀναγκάζει ψυχὴν εἰς ἐκεῖνον τὸν τόπον μεταστρέφεσθαι ἐν ᾧ ἐστι τὸ εὐδαιμονέστατον τοῦ ὄντος, ὃ δεῖ αὐτὴν παντὶ τρόπῳ ἰδεῖν.","st":"526e"},{"sp":"N","t":"ὀρθῶς, ἔφη, λέγεις.","st":"526e"},{"sp":"N","t":"οὐκοῦν εἰ μὲν οὐσίαν ἀναγκάζει θεάσασθαι, προσήκει, εἰ δὲ γένεσιν, οὐ προσήκει.","st":"526e"},{"sp":"N","t":"φαμέν γε δή.","st":"526e"},{"sp":"N","t":"οὐ τοίνυν τοῦτό γε, ἦν δ᾽ ἐγώ, ἀμφισβητήσουσιν ἡμῖν ὅσοι καὶ σμικρὰ γεωμετρίας ἔμπειροι, ὅτι αὕτη ἡ ἐπιστήμη πᾶν τοὐναντίον ἔχει τοῖς ἐν αὐτῇ λόγοις λεγομένοις ὑπὸ τῶν μεταχειριζομένων.","st":"527a"},{"sp":"N","t":"πῶς; ἔφη.","st":"527a"},{"sp":"N","t":"λέγουσι μέν που μάλα γελοίως τε καὶ ἀναγκαίως: ὡς γὰρ πράττοντές τε καὶ πράξεως ἕνεκα πάντας τοὺς λόγους ποιούμενοι λέγουσιν τετραγωνίζειν τε καὶ παρατείνειν καὶ προστιθέναι καὶ πάντα οὕτω φθεγγόμενοι, τὸ δ᾽ ἔστι που","st":"527a"},{"sp":"N","t":"πᾶν τὸ μάθημα γνώσεως ἕνεκα ἐπιτηδευόμενον.","st":"527b"},{"sp":"N","t":"παντάπασι μὲν οὖν, ἔφη.","st":"527b"},{"sp":"N","t":"οὐκοῦν τοῦτο ἔτι διομολογητέον;","st":"527b"},{"sp":"N","t":"τὸ ποῖον;","st":"527b"},{"sp":"N","t":"ὡς τοῦ ἀεὶ ὄντος γνώσεως, ἀλλὰ οὐ τοῦ ποτέ τι γιγνομένου καὶ ἀπολλυμένου.","st":"527b"},{"sp":"N","t":"εὐομολόγητον, ἔφη: τοῦ γὰρ ἀεὶ ὄντος ἡ γεωμετρικὴ γνῶσίς ἐστιν.","st":"527b"},{"sp":"N","t":"ὁλκὸν ἄρα, ὦ γενναῖε, ψυχῆς πρὸς ἀλήθειαν εἴη ἂν καὶ ἀπεργαστικὸν φιλοσόφου διανοίας πρὸς τὸ ἄνω σχεῖν ἃ νῦν κάτω οὐ δέον ἔχομεν.","st":"527b"},{"sp":"N","t":"ὡς οἷόν τε μάλιστα, ἔφη.","st":"527b"},{"sp":"N","t":"ὡς οἷόν τ᾽ ἄρα, ἦν δ᾽ ἐγώ, μάλιστα προστακτέον ὅπως οἱ ἐν τῇ καλλιπόλει σοι μηδενὶ τρόπῳ γεωμετρίας ἀφέξονται. καὶ γὰρ τὰ πάρεργα αὐτοῦ οὐ σμικρά.","st":"527c"},{"sp":"N","t":"ποῖα; ἦ δ᾽ ὅς.","st":"527c"},{"sp":"N","t":"ἅ τε δὴ σὺ εἶπες, ἦν δ᾽ ἐγώ, τὰ περὶ τὸν πόλεμον, καὶ δὴ καὶ πρὸς πάσας μαθήσεις, ὥστε κάλλιον ἀποδέχεσθαι, ἴσμεν που ὅτι τῷ ὅλῳ καὶ παντὶ διοίσει ἡμμένος τε γεωμετρίας καὶ μή.","st":"527c"},{"sp":"N","t":"τῷ παντὶ μέντοι νὴ Δί᾽, ἔφη.","st":"527c"},{"sp":"N","t":"δεύτερον δὴ τοῦτο τιθῶμεν μάθημα τοῖς νέοις;","st":"527c"},{"sp":"N","t":"τιθῶμεν, ἔφη.","st":"527c"},{"sp":"N","t":"τί δέ; τρίτον θῶμεν ἀστρονομίαν; ἢ οὐ δοκεῖ;","st":"527d"},{"sp":"N","t":"ἐμοὶ γοῦν, ἔφη: τὸ γὰρ περὶ ὥρας εὐαισθητοτέρως ἔχειν καὶ μηνῶν καὶ ἐνιαυτῶν οὐ μόνον γεωργίᾳ οὐδὲ ναυτιλίᾳ προσήκει, ἀλλὰ καὶ στρατηγίᾳ οὐχ ἧττον.","st":"527d"},{"sp":"N","t":"ἡδὺς εἶ, ἦν δ᾽ ἐγώ, ὅτι ἔοικας δεδιότι τοὺς πολλούς, μὴ δοκῇς ἄχρηστα μαθήματα προστάττειν. τὸ δ᾽ ἔστιν οὐ πάνυ φαῦλον ἀλλὰ χαλεπὸν πιστεῦσαι ὅτι ἐν τούτοις τοῖς μαθήμασιν ἑκάστου ὄργανόν τι ψυχῆς ἐκκαθαίρεταί τε καὶ","st":"527d"},{"sp":"N","t":"ἀναζωπυρεῖται ἀπολλύμενον καὶ τυφλούμενον ὑπὸ τῶν ἄλλων ἐπιτηδευμάτων, κρεῖττον ὂν σωθῆναι μυρίων ὀμμάτων: μόνῳ γὰρ αὐτῷ ἀλήθεια ὁρᾶται. οἷς μὲν οὖν ταῦτα συνδοκεῖ ἀμηχάνως ὡς εὖ δόξεις λέγειν, ὅσοι δὲ τούτου μηδαμῇ ᾐσθημένοι εἰσὶν εἰκότως ἡγήσονταί σε λέγειν οὐδέν: ἄλλην γὰρ ἀπ᾽ αὐτῶν οὐχ ὁρῶσιν ἀξίαν λόγου ὠφελίαν. σκόπει","st":"527e"},{"sp":"N","t":"οὖν αὐτόθεν πρὸς ποτέρους διαλέγῃ: ἢ οὐδὲ πρὸς ἑτέρους, ἀλλὰ σαυτοῦ ἕνεκα τὸ μέγιστον ποιῇ τοὺς λόγους, φθονοῖς μὴν οὐδ᾽ ἂν ἄλλῳ, εἴ τίς τι δύναιτο ἀπ᾽ αὐτῶν ὄνασθαι.","st":"528a"},{"sp":"N","t":"οὕτως, ἔφη, αἱροῦμαι, ἐμαυτοῦ ἕνεκα τὸ πλεῖστον λέγειν τε καὶ ἐρωτᾶν καὶ ἀποκρίνεσθαι.","st":"528a"},{"sp":"N","t":"ἄναγε τοίνυν, ἦν δ᾽ ἐγώ, εἰς τοὐπίσω: νυνδὴ γὰρ οὐκ ὀρθῶς τὸ ἑξῆς ἐλάβομεν τῇ γεωμετρίᾳ.","st":"528a"},{"sp":"N","t":"πῶς λαβόντες; ἔφη.","st":"528a"},{"sp":"N","t":"μετὰ ἐπίπεδον, ἦν δ᾽ ἐγώ, ἐν περιφορᾷ ὂν ἤδη στερεὸν","st":"528a"},{"sp":"N","t":"λαβόντες, πρὶν αὐτὸ καθ᾽ αὑτὸ λαβεῖν: ὀρθῶς δὲ ἔχει ἑξῆς μετὰ δευτέραν αὔξην τρίτην λαμβάνειν. ἔστι δέ που τοῦτο περὶ τὴν τῶν κύβων αὔξην καὶ τὸ βάθους μετέχον.","st":"528b"},{"sp":"N","t":"ἔστι γάρ, ἔφη: ἀλλὰ ταῦτά γε, ὦ Σώκρατες, δοκεῖ οὔπω ηὑρῆσθαι.","st":"528b"},{"sp":"N","t":"διττὰ γάρ, ἦν δ᾽ ἐγώ, τὰ αἴτια: ὅτι τε οὐδεμία πόλις ἐντίμως αὐτὰ ἔχει, ἀσθενῶς ζητεῖται χαλεπὰ ὄντα, ἐπιστάτου τε δέονται οἱ ζητοῦντες, ἄνευ οὗ οὐκ ἂν εὕροιεν, ὃν πρῶτον μὲν γενέσθαι χαλεπόν, ἔπειτα καὶ γενομένου, ὡς νῦν ἔχει,","st":"528b"},{"sp":"N","t":"οὐκ ἂν πείθοιντο οἱ περὶ ταῦτα ζητητικοὶ μεγαλοφρονούμενοι. εἰ δὲ πόλις ὅλη συνεπιστατοῖ ἐντίμως ἄγουσα αὐτά, οὗτοί τε ἂν πείθοιντο καὶ συνεχῶς τε ἂν καὶ ἐντόνως ζητούμενα ἐκφανῆ γένοιτο ὅπῃ ἔχει: ἐπεὶ καὶ νῦν ὑπὸ τῶν πολλῶν ἀτιμαζόμενα καὶ κολουόμενα, ὑπὸ δὲ τῶν ζητούντων λόγον οὐκ ἐχόντων καθ᾽ ὅτι χρήσιμα, ὅμως πρὸς ἅπαντα ταῦτα βίᾳ ὑπὸ χάριτος αὐξάνεται, καὶ οὐδὲν θαυμαστὸν αὐτὰ φανῆναι.","st":"528c"},{"sp":"N","t":"καὶ μὲν δή, ἔφη, τό γε ἐπίχαρι καὶ διαφερόντως ἔχει. ἀλλά μοι σαφέστερον εἰπὲ ἃ νυνδὴ ἔλεγες. τὴν μὲν γάρ που τοῦ ἐπιπέδου πραγματείαν γεωμετρίαν ἐτίθεις.","st":"528d"},{"sp":"N","t":"ναί, ἦν δ᾽ ἐγώ.","st":"528d"},{"sp":"N","t":"εἶτά γ᾽, ἔφη, τὸ μὲν πρῶτον ἀστρονομίαν μετὰ ταύτην, ὕστερον δ᾽ ἀνεχώρησας.","st":"528d"},{"sp":"N","t":"σπεύδων γάρ, ἔφην, ταχὺ πάντα διεξελθεῖν μᾶλλον βραδύνω: ἑξῆς γὰρ οὖσαν τὴν βάθους αὔξης μέθοδον, ὅτι τῇ ζητήσει γελοίως ἔχει, ὑπερβὰς αὐτὴν μετὰ γεωμετρίαν","st":"528d"},{"sp":"N","t":"ἀστρονομίαν ἔλεγον, φορὰν οὖσαν βάθους.","st":"528e"},{"sp":"N","t":"ὀρθῶς, ἔφη, λέγεις.","st":"528e"},{"sp":"N","t":"τέταρτον τοίνυν, ἦν δ᾽ ἐγώ, τιθῶμεν μάθημα ἀστρονομίαν, ὡς ὑπαρχούσης τῆς νῦν παραλειπομένης, ἐὰν αὐτὴν πόλις μετίῃ.","st":"528e"},{"sp":"N","t":"εἰκός, ἦ δ᾽ ὅς. καὶ ὅ γε νυνδή μοι, ὦ Σώκρατες, ἐπέπληξας περὶ ἀστρονομίας ὡς φορτικῶς ἐπαινοῦντι, νῦν ᾗ σὺ μετέρχῃ","st":"528e"},{"sp":"N","t":"ἐπαινῶ: παντὶ γάρ μοι δοκεῖ δῆλον ὅτι αὕτη γε ἀναγκάζει ψυχὴν εἰς τὸ ἄνω ὁρᾶν καὶ ἀπὸ τῶν ἐνθένδε ἐκεῖσε ἄγει.","st":"529a"},{"sp":"N","t":"ἴσως, ἦν δ᾽ ἐγώ, παντὶ δῆλον πλὴν ἐμοί: ἐμοὶ γὰρ οὐ δοκεῖ οὕτως.","st":"529a"},{"sp":"N","t":"ἀλλὰ πῶς; ἔφη.","st":"529a"},{"sp":"N","t":"ὡς μὲν νῦν αὐτὴν μεταχειρίζονται οἱ εἰς φιλοσοφίαν ἀνάγοντες, πάνυ ποιεῖν κάτω βλέπειν.","st":"529a"},{"sp":"N","t":"πῶς, ἔφη, λέγεις;","st":"529a"},{"sp":"N","t":"οὐκ ἀγεννῶς μοι δοκεῖς, ἦν δ᾽ ἐγώ, τὴν περὶ τὰ ἄνω μάθησιν λαμβάνειν παρὰ σαυτῷ ἥ ἐστι: κινδυνεύεις γὰρ","st":"529a"},{"sp":"N","t":"καὶ εἴ τις ἐν ὀροφῇ ποικίλματα θεώμενος ἀνακύπτων καταμανθάνοι τι, ἡγεῖσθαι ἂν αὐτὸν νοήσει ἀλλ᾽ οὐκ ὄμμασι θεωρεῖν. ἴσως οὖν καλῶς ἡγῇ, ἐγὼ δ᾽ εὐηθικῶς. ἐγὼ γὰρ αὖ οὐ δύναμαι ἄλλο τι νομίσαι ἄνω ποιοῦν ψυχὴν βλέπειν μάθημα ἢ ἐκεῖνο ὃ ἂν περὶ τὸ ὄν τε ᾖ καὶ τὸ ἀόρατον, ἐάν τέ τις ἄνω κεχηνὼς ἢ κάτω συμμεμυκὼς τῶν αἰσθητῶν τι ἐπιχειρῇ μανθάνειν, οὔτε μαθεῖν ἄν ποτέ φημι αὐτόν — ἐπιστήμην","st":"529b"},{"sp":"N","t":"γὰρ οὐδὲν ἔχειν τῶν τοιούτων — οὔτε ἄνω ἀλλὰ κάτω αὐτοῦ βλέπειν τὴν ψυχήν, κἂν ἐξ ὑπτίας νέων ἐν γῇ ἢ ἐν θαλάττῃ μανθάνῃ.","st":"529c"},{"sp":"N","t":"δίκην, ἔφη, ἔχω: ὀρθῶς γάρ μοι ἐπέπληξας. ἀλλὰ πῶς δὴ ἔλεγες δεῖν ἀστρονομίαν μανθάνειν παρὰ ἃ νῦν μανθάνουσιν, εἰ μέλλοιεν ὠφελίμως πρὸς ἃ λέγομεν μαθήσεσθαι;","st":"529c"},{"sp":"N","t":"ὧδε, ἦν δ᾽ ἐγώ. ταῦτα μὲν τὰ ἐν τῷ οὐρανῷ ποικίλματα, ἐπείπερ ἐν ὁρατῷ πεποίκιλται, κάλλιστα μὲν ἡγεῖσθαι καὶ","st":"529c"},{"sp":"N","t":"ἀκριβέστατα τῶν τοιούτων ἔχειν, τῶν δὲ ἀληθινῶν πολὺ ἐνδεῖν, ἃς τὸ ὂν τάχος καὶ ἡ οὖσα βραδυτὴς ἐν τῷ ἀληθινῷ ἀριθμῷ καὶ πᾶσι τοῖς ἀληθέσι σχήμασι φοράς τε πρὸς ἄλληλα φέρεται καὶ τὰ ἐνόντα φέρει, ἃ δὴ λόγῳ μὲν καὶ διανοίᾳ ληπτά, ὄψει δ᾽ οὔ: ἢ σὺ οἴει;","st":"529d"},{"sp":"N","t":"οὐδαμῶς γε, ἔφη.","st":"529d"},{"sp":"N","t":"οὐκοῦν, εἶπον, τῇ περὶ τὸν οὐρανὸν ποικιλίᾳ παραδείγμασι χρηστέον τῆς πρὸς ἐκεῖνα μαθήσεως ἕνεκα, ὁμοίως ὥσπερ ἂν","st":"529d"},{"sp":"N","t":"εἴ τις ἐντύχοι ὑπὸ Δαιδάλου ἤ τινος ἄλλου δημιουργοῦ ἢ γραφέως διαφερόντως γεγραμμένοις καὶ ἐκπεπονημένοις διαγράμμασιν. ἡγήσαιτο γὰρ ἄν πού τις ἔμπειρος γεωμετρίας, ἰδὼν τὰ τοιαῦτα, κάλλιστα μὲν ἔχειν ἀπεργασίᾳ, γελοῖον μὴν ἐπισκοπεῖν αὐτὰ σπουδῇ ὡς τὴν ἀλήθειαν ἐν αὐτοῖς ληψόμενον","st":"529e"},{"sp":"N","t":"ἴσων ἢ διπλασίων ἢ ἄλλης τινὸς συμμετρίας.","st":"530a"},{"sp":"N","t":"τί δ᾽ οὐ μέλλει γελοῖον εἶναι; ἔφη.","st":"530a"},{"sp":"N","t":"τῷ ὄντι δὴ ἀστρονομικόν, ἦν δ᾽ ἐγώ, ὄντα οὐκ οἴει ταὐτὸν πείσεσθαι εἰς τὰς τῶν ἄστρων φορὰς ἀποβλέποντα; νομιεῖν μὲν ὡς οἷόν τε κάλλιστα τὰ τοιαῦτα ἔργα συστήσασθαι, οὕτω συνεστάναι τῷ τοῦ οὐρανοῦ δημιουργῷ αὐτόν τε καὶ τὰ ἐν αὐτῷ: τὴν δὲ νυκτὸς πρὸς ἡμέραν συμμετρίαν καὶ τούτων πρὸς μῆνα καὶ μηνὸς πρὸς ἐνιαυτὸν καὶ τῶν ἄλλων ἄστρων","st":"530a"},{"sp":"N","t":"πρός τε ταῦτα καὶ πρὸς ἄλληλα, οὐκ ἄτοπον, οἴει, ἡγήσεται τὸν νομίζοντα γίγνεσθαί τε ταῦτα ἀεὶ ὡσαύτως καὶ οὐδαμῇ οὐδὲν παραλλάττειν, σῶμά τε ἔχοντα καὶ ὁρώμενα, καὶ ζητεῖν παντὶ τρόπῳ τὴν ἀλήθειαν αὐτῶν λαβεῖν;","st":"530b"},{"sp":"N","t":"ἐμοὶ γοῦν δοκεῖ, ἔφη, σοῦ νῦν ἀκούοντι.","st":"530b"},{"sp":"N","t":"προβλήμασιν ἄρα, ἦν δ᾽ ἐγώ, χρώμενοι ὥσπερ γεωμετρίαν οὕτω καὶ ἀστρονομίαν μέτιμεν, τὰ δ᾽ ἐν τῷ οὐρανῷ ἐάσομεν, εἰ μέλλομεν ὄντως ἀστρονομίας μεταλαμβάνοντες χρήσιμον","st":"530b"},{"sp":"N","t":"τὸ φύσει φρόνιμον ἐν τῇ ψυχῇ ἐξ ἀχρήστου ποιήσειν.","st":"530c"},{"sp":"N","t":"ἦ πολλαπλάσιον, ἔφη, τὸ ἔργον ἢ ὡς νῦν ἀστρονομεῖται προστάττεις.","st":"530c"},{"sp":"N","t":"οἶμαι δέ γε, εἶπον, καὶ τἆλλα κατὰ τὸν αὐτὸν τρόπον προστάξειν ἡμᾶς, ἐάν τι ἡμῶν ὡς νομοθετῶν ὄφελος ᾖ. ἀλλὰ γάρ τι ἔχεις ὑπομνῆσαι τῶν προσηκόντων μαθημάτων;","st":"530c"},{"sp":"N","t":"οὐκ ἔχω, ἔφη, νῦν γ᾽ οὑτωσί.","st":"530c"},{"sp":"N","t":"οὐ μὴν ἕν, ἀλλὰ πλείω, ἦν δ᾽ ἐγώ, εἴδη παρέχεται ἡ φορά,","st":"530c"},{"sp":"N","t":"ὡς ἐγᾦμαι. τὰ μὲν οὖν πάντα ἴσως ὅστις σοφὸς ἕξει εἰπεῖν: ἃ δὲ καὶ ἡμῖν προφανῆ, δύο.","st":"530d"},{"sp":"N","t":"ποῖα δή;","st":"530d"},{"sp":"N","t":"πρὸς τούτῳ, ἦν δ᾽ ἐγώ, ἀντίστροφον αὐτοῦ.","st":"530d"},{"sp":"N","t":"τὸ ποῖον;","st":"530d"},{"sp":"N","t":"κινδυνεύει, ἔφην, ὡς πρὸς ἀστρονομίαν ὄμματα πέπηγεν, ὣς πρὸς ἐναρμόνιον φορὰν ὦτα παγῆναι, καὶ αὗται ἀλλήλων ἀδελφαί τινες αἱ ἐπιστῆμαι εἶναι, ὡς οἵ τε Πυθαγόρειοί φασι καὶ ἡμεῖς, ὦ Γλαύκων, συγχωροῦμεν. ἢ πῶς ποιοῦμεν;","st":"530d"},{"sp":"N","t":"οὕτως, ἔφη.","st":"530d"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, ἐπειδὴ πολὺ τὸ ἔργον, ἐκείνων πευσόμεθα πῶς λέγουσι περὶ αὐτῶν καὶ εἴ τι ἄλλο πρὸς τούτοις: ἡμεῖς δὲ παρὰ πάντα ταῦτα φυλάξομεν τὸ ἡμέτερον.","st":"530e"},{"sp":"N","t":"ποῖον;","st":"530e"},{"sp":"N","t":"μή ποτ᾽ αὐτῶν τι ἀτελὲς ἐπιχειρῶσιν ἡμῖν μανθάνειν οὓς θρέψομεν, καὶ οὐκ ἐξῆκον ἐκεῖσε ἀεί, οἷ πάντα δεῖ ἀφήκειν, οἷον ἄρτι περὶ τῆς ἀστρονομίας ἐλέγομεν. ἢ οὐκ οἶσθ᾽ ὅτι","st":"530e"},{"sp":"N","t":"καὶ περὶ ἁρμονίας ἕτερον τοιοῦτον ποιοῦσι; τὰς γὰρ ἀκουομένας αὖ συμφωνίας καὶ φθόγγους ἀλλήλοις ἀναμετροῦντες ἀνήνυτα, ὥσπερ οἱ ἀστρονόμοι, πονοῦσιν.","st":"531a"},{"sp":"N","t":"νὴ τοὺς θεούς, ἔφη, καὶ γελοίως γε, πυκνώματ᾽ ἄττα ὀνομάζοντες καὶ παραβάλλοντες τὰ ὦτα, οἷον ἐκ γειτόνων φωνὴν θηρευόμενοι, οἱ μέν φασιν ἔτι κατακούειν ἐν μέσῳ τινὰ ἠχὴν καὶ σμικρότατον εἶναι τοῦτο διάστημα, ᾧ μετρητέον, οἱ δὲ ἀμφισβητοῦντες ὡς ὅμοιον ἤδη φθεγγομένων, ἀμφότεροι","st":"531a"},{"sp":"N","t":"ὦτα τοῦ νοῦ προστησάμενοι.","st":"531b"},{"sp":"N","t":"σὺ μέν, ἦν δ᾽ ἐγώ, τοὺς χρηστοὺς λέγεις τοὺς ταῖς χορδαῖς πράγματα παρέχοντας καὶ βασανίζοντας, ἐπὶ τῶν κολλόπων στρεβλοῦντας: ἵνα δὲ μὴ μακροτέρα ἡ εἰκὼν γίγνηται πλήκτρῳ τε πληγῶν γιγνομένων καὶ κατηγορίας πέρι καὶ ἐξαρνήσεως καὶ ἀλαζονείας χορδῶν, παύομαι τῆς εἰκόνος καὶ οὔ φημι τούτους λέγειν, ἀλλ᾽ ἐκείνους οὓς ἔφαμεν νυνδὴ περὶ ἁρμονίας ἐρήσεσθαι. ταὐτὸν γὰρ ποιοῦσι τοῖς ἐν τῇ","st":"531b"},{"sp":"N","t":"ἀστρονομίᾳ: τοὺς γὰρ ἐν ταύταις ταῖς συμφωνίαις ταῖς ἀκουομέναις ἀριθμοὺς ζητοῦσιν, ἀλλ᾽ οὐκ εἰς προβλήματα ἀνίασιν, ἐπισκοπεῖν τίνες σύμφωνοι ἀριθμοὶ καὶ τίνες οὔ, καὶ διὰ τί ἑκάτεροι.","st":"531c"},{"sp":"N","t":"δαιμόνιον γάρ, ἔφη, πρᾶγμα λέγεις.","st":"531c"},{"sp":"N","t":"χρήσιμον μὲν οὖν, ἦν δ᾽ ἐγώ, πρὸς τὴν τοῦ καλοῦ τε καὶ ἀγαθοῦ ζήτησιν, ἄλλως δὲ μεταδιωκόμενον ἄχρηστον.","st":"531c"},{"sp":"N","t":"εἰκός γ᾽, ἔφη.","st":"531c"},{"sp":"N","t":"οἶμαι δέ γε, ἦν δ᾽ ἐγώ, καὶ ἡ τούτων πάντων ὧν διεληλύθαμεν","st":"531c"},{"sp":"N","t":"μέθοδος ἐὰν μὲν ἐπὶ τὴν ἀλλήλων κοινωνίαν ἀφίκηται καὶ συγγένειαν, καὶ συλλογισθῇ ταῦτα ᾗ ἐστὶν ἀλλήλοις οἰκεῖα, φέρειν τι αὐτῶν εἰς ἃ βουλόμεθα τὴν πραγματείαν καὶ οὐκ ἀνόνητα πονεῖσθαι, εἰ δὲ μή, ἀνόνητα.","st":"531d"},{"sp":"N","t":"καὶ ἐγώ, ἔφη, οὕτω μαντεύομαι. ἀλλὰ πάμπολυ ἔργον λέγεις, ὦ Σώκρατες.","st":"531d"},{"sp":"N","t":"τοῦ προοιμίου, ἦν δ᾽ ἐγώ, ἢ τίνος λέγεις; ἢ οὐκ ἴσμεν ὅτι πάντα ταῦτα προοίμιά ἐστιν αὐτοῦ τοῦ νόμου ὃν δεῖ μαθεῖν; οὐ γάρ που δοκοῦσί γέ σοι οἱ ταῦτα δεινοὶ διαλεκτικοὶ","st":"531d"},{"sp":"N","t":"εἶναι.","st":"531e"},{"sp":"N","t":"οὐ μὰ τὸν Δί᾽, ἔφη, εἰ μὴ μάλα γέ τινες ὀλίγοι ὧν ἐγὼ ἐντετύχηκα.","st":"531e"},{"sp":"N","t":"ἀλλὰ δή, εἶπον, μὴ δυνατοὶ οἵτινες δοῦναί τε καὶ ἀποδέξασθαι λόγον εἴσεσθαί ποτέ τι ὧν φαμεν δεῖν εἰδέναι;","st":"531e"},{"sp":"N","t":"οὐδ᾽ αὖ, ἔφη, τοῦτό γε.","st":"531e"},{"sp":"N","t":"οὐκοῦν, εἶπον, ὦ Γλαύκων, οὗτος ἤδη αὐτός ἐστιν ὁ νόμος ὃν τὸ διαλέγεσθαι περαίνει; ὃν καὶ ὄντα νοητὸν μιμοῖτ᾽ ἂν ἡ τῆς ὄψεως δύναμις, ἣν ἐλέγομεν πρὸς αὐτὰ ἤδη τὰ ζῷα ἐπιχειρεῖν ἀποβλέπειν καὶ πρὸς αὐτὰ ⟨τὰ⟩ ἄστρα τε καὶ τελευταῖον δὴ πρὸς αὐτὸν τὸν ἥλιον. οὕτω καὶ ὅταν τις τῷ διαλέγεσθαι ἐπιχειρῇ ἄνευ πασῶν τῶν αἰσθήσεων διὰ τοῦ λόγου ἐπ᾽ αὐτὸ ὃ ἔστιν ἕκαστον ὁρμᾶν, καὶ μὴ ἀποστῇ πρὶν","st":"532a"},{"sp":"N","t":"ἂν αὐτὸ ὃ ἔστιν ἀγαθὸν αὐτῇ νοήσει λάβῃ, ἐπ᾽ αὐτῷ γίγνεται τῷ τοῦ νοητοῦ τέλει, ὥσπερ ἐκεῖνος τότε ἐπὶ τῷ τοῦ ὁρατοῦ.","st":"532b"},{"sp":"N","t":"παντάπασι μὲν οὖν, ἔφη.","st":"532b"},{"sp":"N","t":"τί οὖν; οὐ διαλεκτικὴν ταύτην τὴν πορείαν καλεῖς;","st":"532b"},{"sp":"N","t":"τί μήν;","st":"532b"},{"sp":"N","t":"ἡ δέ γε, ἦν δ᾽ ἐγώ, λύσις τε ἀπὸ τῶν δεσμῶν καὶ μεταστροφὴ ἀπὸ τῶν σκιῶν ἐπὶ τὰ εἴδωλα καὶ τὸ φῶς καὶ ἐκ τοῦ καταγείου εἰς τὸν ἥλιον ἐπάνοδος, καὶ ἐκεῖ πρὸς μὲν τὰ ζῷά τε καὶ φυτὰ καὶ τὸ τοῦ ἡλίου φῶς ἔτι ἀδυναμία","st":"532b"},{"sp":"N","t":"βλέπειν, πρὸς δὲ τὰ ἐν ὕδασι φαντάσματα θεῖα καὶ σκιὰς τῶν ὄντων, ἀλλ᾽ οὐκ εἰδώλων σκιὰς δι᾽ ἑτέρου τοιούτου φωτὸς ὡς πρὸς ἥλιον κρίνειν ἀποσκιαζομένας — πᾶσα αὕτη ἡ πραγματεία τῶν τεχνῶν ἃς διήλθομεν ταύτην ἔχει τὴν δύναμιν καὶ ἐπαναγωγὴν τοῦ βελτίστου ἐν ψυχῇ πρὸς τὴν τοῦ ἀρίστου ἐν τοῖς οὖσι θέαν, ὥσπερ τότε τοῦ σαφεστάτου ἐν σώματι πρὸς τὴν τοῦ φανοτάτου ἐν τῷ σωματοειδεῖ τε καὶ","st":"532c"},{"sp":"N","t":"ὁρατῷ τόπῳ.","st":"532d"},{"sp":"N","t":"ἐγὼ μέν, ἔφη, ἀποδέχομαι οὕτω. καίτοι παντάπασί γέ μοι δοκεῖ χαλεπὰ μὲν ἀποδέχεσθαι εἶναι, ἄλλον δ᾽ αὖ τρόπον χαλεπὰ μὴ ἀποδέχεσθαι. ὅμως δέ — οὐ γὰρ ἐν τῷ νῦν παρόντι μόνον ἀκουστέα, ἀλλὰ καὶ αὖθις πολλάκις ἐπανιτέον -ταῦτα θέντες ἔχειν ὡς νῦν λέγεται, ἐπ᾽ αὐτὸν δὴ τὸν νόμον ἴωμεν, καὶ διέλθωμεν οὕτως ὥσπερ τὸ προοίμιον διήλθομεν. λέγε οὖν τίς ὁ τρόπος τῆς τοῦ διαλέγεσθαι δυνάμεως, καὶ","st":"532d"},{"sp":"N","t":"κατὰ ποῖα δὴ εἴδη διέστηκεν, καὶ τίνες αὖ ὁδοί: αὗται γὰρ ἂν ἤδη, ὡς ἔοικεν, αἱ πρὸς αὐτὸ ἄγουσαι εἶεν, οἷ ἀφικομένῳ ὥσπερ ὁδοῦ ἀνάπαυλα ἂν εἴη καὶ τέλος τῆς πορείας.","st":"532e"},{"sp":"N","t":"οὐκέτ᾽, ἦν δ᾽ ἐγώ, ὦ φίλε Γλαύκων, οἷός τ᾽ ἔσῃ ἀκολουθεῖν — ἐπεὶ τό γ᾽ ἐμὸν οὐδὲν ἂν προθυμίας ἀπολίποι — οὐδ᾽ εἰκόνα ἂν ἔτι οὗ λέγομεν ἴδοις, ἀλλ᾽ αὐτὸ τὸ ἀληθές, ὅ γε δή μοι φαίνεται — εἰ δ᾽ ὄντως ἢ μή, οὐκέτ᾽ ἄξιον τοῦτο διισχυρίζεσθαι: ἀλλ᾽ ὅτι μὲν δὴ τοιοῦτόν τι ἰδεῖν, ἰσχυριστέον. ἦ γάρ;","st":"533a"},{"sp":"N","t":"τί μήν;","st":"533a"},{"sp":"N","t":"οὐκοῦν καὶ ὅτι ἡ τοῦ διαλέγεσθαι δύναμις μόνη ἂν φήνειεν ἐμπείρῳ ὄντι ὧν νυνδὴ διήλθομεν, ἄλλῃ δὲ οὐδαμῇ δυνατόν;","st":"533a"},{"sp":"N","t":"καὶ τοῦτ᾽, ἔφη, ἄξιον διισχυρίζεσθαι.","st":"533a"},{"sp":"N","t":"τόδε γοῦν, ἦν δ᾽ ἐγώ, οὐδεὶς ἡμῖν ἀμφισβητήσει λέγουσιν, ὡς αὐτοῦ γε ἑκάστου πέρι ὃ ἔστιν ἕκαστον ἄλλη τις ἐπιχειρεῖ μέθοδος ὁδῷ περὶ παντὸς λαμβάνειν. ἀλλ᾽ αἱ μὲν ἄλλαι πᾶσαι τέχναι ἢ πρὸς δόξας ἀνθρώπων καὶ ἐπιθυμίας εἰσὶν ἢ πρὸς γενέσεις τε καὶ συνθέσεις, ἢ πρὸς θεραπείαν τῶν φυομένων τε καὶ συντιθεμένων ἅπασαι τετράφαται: αἱ δὲ λοιπαί, ἃς τοῦ ὄντος τι ἔφαμεν ἐπιλαμβάνεσθαι, γεωμετρίας τε καὶ τὰς ταύτῃ ἑπομένας, ὁρῶμεν ὡς ὀνειρώττουσι μὲν","st":"533b"},{"sp":"N","t":"περὶ τὸ ὄν, ὕπαρ δὲ ἀδύνατον αὐταῖς ἰδεῖν, ἕως ἂν ὑποθέσεσι χρώμεναι ταύτας ἀκινήτους ἐῶσι, μὴ δυνάμεναι λόγον διδόναι αὐτῶν. ᾧ γὰρ ἀρχὴ μὲν ὃ μὴ οἶδε, τελευτὴ δὲ καὶ τὰ μεταξὺ ἐξ οὗ μὴ οἶδεν συμπέπλεκται, τίς μηχανὴ τὴν τοιαύτην ὁμολογίαν ποτὲ ἐπιστήμην γενέσθαι;","st":"533c"},{"sp":"N","t":"οὐδεμία, ἦ δ᾽ ὅς.","st":"533c"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, ἡ διαλεκτικὴ μέθοδος μόνη ταύτῃ πορεύεται, τὰς ὑποθέσεις ἀναιροῦσα, ἐπ᾽ αὐτὴν τὴν ἀρχὴν","st":"533c"},{"sp":"N","t":"ἵνα βεβαιώσηται, καὶ τῷ ὄντι ἐν βορβόρῳ βαρβαρικῷ τινι τὸ τῆς ψυχῆς ὄμμα κατορωρυγμένον ἠρέμα ἕλκει καὶ ἀνάγει ἄνω, συνερίθοις καὶ συμπεριαγωγοῖς χρωμένη αἷς διήλθομεν τέχναις: ἃς ἐπιστήμας μὲν πολλάκις προσείπομεν διὰ τὸ ἔθος, δέονται δὲ ὀνόματος ἄλλου, ἐναργεστέρου μὲν ἢ δόξης, ἀμυδροτέρου δὲ ἢ ἐπιστήμης — διάνοιαν δὲ αὐτὴν ἔν γε τῷ πρόσθεν που ὡρισάμεθα — ἔστι δ᾽, ὡς ἐμοὶ δοκεῖ, οὐ περὶ","st":"533d"},{"sp":"N","t":"ὀνόματος ἀμφισβήτησις, οἷς τοσούτων πέρι σκέψις ὅσων ἡμῖν πρόκειται.","st":"533e"},{"sp":"N","t":"οὐ γὰρ οὖν, ἔφη.","st":"533e"},{"sp":"N","t":"ἀλλ᾽ ὃ ἂν μόνον δηλοῖ πως τὴν ἕξιν σαφηνείᾳ λέγειν ἐν ψυχῇ ⟨ἀρκέσει;","st":"533e"},{"sp":"N","t":"ναί.⟩","st":"533e"},{"sp":"N","t":"ἀρκέσει οὖν, ἦν δ᾽ ἐγώ, ὥσπερ τὸ πρότερον, τὴν μὲν πρώτην μοῖραν ἐπιστήμην καλεῖν, δευτέραν δὲ διάνοιαν, τρίτην","st":"533e"},{"sp":"N","t":"δὲ πίστιν καὶ εἰκασίαν τετάρτην: καὶ συναμφότερα μὲν ταῦτα δόξαν, συναμφότερα δ᾽ ἐκεῖνα νόησιν: καὶ δόξαν μὲν περὶ γένεσιν, νόησιν δὲ περὶ οὐσίαν: καὶ ὅτι οὐσία πρὸς γένεσιν, νόησιν πρὸς δόξαν, καὶ ὅτι νόησις πρὸς δόξαν, ἐπιστήμην πρὸς πίστιν καὶ διάνοιαν πρὸς εἰκασίαν: τὴν δ᾽ ἐφ᾽ οἷς ταῦτα ἀναλογίαν καὶ διαίρεσιν διχῇ ἑκατέρου, δοξαστοῦ τε καὶ νοητοῦ, ἐῶμεν, ὦ Γλαύκων, ἵνα μὴ ἡμᾶς πολλαπλασίων λόγων ἐμπλήσῃ ἢ ὅσων οἱ παρεληλυθότες.","st":"534a"},{"sp":"N","t":"ἀλλὰ μὴν ἔμοιγ᾽, ἔφη, τά γε ἄλλα, καθ᾽ ὅσον δύναμαι ἕπεσθαι, συνδοκεῖ.","st":"534b"},{"sp":"N","t":"ἦ καὶ διαλεκτικὸν καλεῖς τὸν λόγον ἑκάστου λαμβάνοντα τῆς οὐσίας; καὶ τὸν μὴ ἔχοντα, καθ᾽ ὅσον ἂν μὴ ἔχῃ λόγον αὑτῷ τε καὶ ἄλλῳ διδόναι, κατὰ τοσοῦτον νοῦν περὶ τούτου οὐ φήσεις ἔχειν;","st":"534b"},{"sp":"N","t":"πῶς γὰρ ἄν, ἦ δ᾽ ὅς, φαίην;","st":"534b"},{"sp":"N","t":"οὐκοῦν καὶ περὶ τοῦ ἀγαθοῦ ὡσαύτως: ὃς ἂν μὴ ἔχῃ διορίσασθαι τῷ λόγῳ ἀπὸ τῶν ἄλλων πάντων ἀφελὼν τὴν","st":"534b"},{"sp":"N","t":"τοῦ ἀγαθοῦ ἰδέαν, καὶ ὥσπερ ἐν μάχῃ διὰ πάντων ἐλέγχων διεξιών, μὴ κατὰ δόξαν ἀλλὰ κατ᾽ οὐσίαν προθυμούμενος ἐλέγχειν, ἐν πᾶσι τούτοις ἀπτῶτι τῷ λόγῳ διαπορεύηται, οὔτε αὐτὸ τὸ ἀγαθὸν φήσεις εἰδέναι τὸν οὕτως ἔχοντα οὔτε ἄλλο ἀγαθὸν οὐδέν, ἀλλ᾽ εἴ πῃ εἰδώλου τινὸς ἐφάπτεται, δόξῃ, οὐκ ἐπιστήμῃ ἐφάπτεσθαι, καὶ τὸν νῦν βίον ὀνειροπολοῦντα καὶ ὑπνώττοντα, πρὶν ἐνθάδ᾽ ἐξεγρέσθαι, εἰς Ἅιδου","st":"534c"},{"sp":"N","t":"πρότερον ἀφικόμενον τελέως ἐπικαταδαρθεῖν;","st":"534d"},{"sp":"N","t":"νὴ τὸν Δία, ἦ δ᾽ ὅς, σφόδρα γε πάντα ταῦτα φήσω.","st":"534d"},{"sp":"N","t":"ἀλλὰ μὴν τούς γε σαυτοῦ παῖδας, οὓς τῷ λόγῳ τρέφεις τε καὶ παιδεύεις, εἴ ποτε ἔργῳ τρέφοις, οὐκ ἂν ἐάσαις, ὡς ἐγᾦμαι, ἀλόγους ὄντας ὥσπερ γραμμάς, ἄρχοντας ἐν τῇ πόλει κυρίους τῶν μεγίστων εἶναι.","st":"534d"},{"sp":"N","t":"οὐ γὰρ οὖν, ἔφη.","st":"534d"},{"sp":"N","t":"νομοθετήσεις δὴ αὐτοῖς ταύτης μάλιστα τῆς παιδείας ἀντιλαμβάνεσθαι, ἐξ ἧς ἐρωτᾶν τε καὶ ἀποκρίνεσθαι ἐπιστημονέστατα οἷοί τ᾽ ἔσονται;","st":"534d"},{"sp":"N","t":"νομοθετήσω, ἔφη, μετά γε σοῦ.","st":"534e"},{"sp":"N","t":"ἆρ᾽ οὖν δοκεῖ σοι, ἔφην ἐγώ, ὥσπερ θριγκὸς τοῖς μαθήμασιν ἡ διαλεκτικὴ ἡμῖν ἐπάνω κεῖσθαι, καὶ οὐκέτ᾽ ἄλλο τούτου μάθημα ἀνωτέρω ὀρθῶς ἂν ἐπιτίθεσθαι, ἀλλ᾽ ἔχειν","st":"534e"},{"sp":"N","t":"ἤδη τέλος τὰ τῶν μαθημάτων;","st":"535a"},{"sp":"N","t":"ἔμοιγ᾽, ἔφη.","st":"535a"},{"sp":"N","t":"διανομὴ τοίνυν, ἦν δ᾽ ἐγώ, τὸ λοιπόν σοι, τίσιν ταῦτα τὰ μαθήματα δώσομεν καὶ τίνα τρόπον.","st":"535a"},{"sp":"N","t":"δῆλον, ἔφη.","st":"535a"},{"sp":"N","t":"μέμνησαι οὖν τὴν προτέραν ἐκλογὴν τῶν ἀρχόντων, οἵους ἐξελέξαμεν;","st":"535a"},{"sp":"N","t":"πῶς γάρ, ἦ δ᾽ ὅς, οὔ;","st":"535a"},{"sp":"N","t":"τὰ μὲν ἄλλα τοίνυν, ἦν δ᾽ ἐγώ, ἐκείνας τὰς φύσεις οἴου δεῖν ἐκλεκτέας εἶναι: τούς τε γὰρ βεβαιοτάτους καὶ τοὺς ἀνδρειοτάτους προαιρετέον, καὶ κατὰ δύναμιν τοὺς εὐειδεστάτους:","st":"535a"},{"sp":"N","t":"πρὸς δὲ τούτοις ζητητέον μὴ μόνον γενναίους τε καὶ βλοσυροὺς τὰ ἤθη, ἀλλὰ καὶ ἃ τῇδε τῇ παιδείᾳ τῆς φύσεως πρόσφορα ἑκτέον αὐτοῖς.","st":"535b"},{"sp":"N","t":"ποῖα δὴ διαστέλλῃ;","st":"535b"},{"sp":"N","t":"δριμύτητα, ὦ μακάριε, ἔφην, δεῖ αὐτοῖς πρὸς τὰ μαθήματα ὑπάρχειν, καὶ μὴ χαλεπῶς μανθάνειν. πολὺ γάρ τοι μᾶλλον ἀποδειλιῶσι ψυχαὶ ἐν ἰσχυροῖς μαθήμασιν ἢ ἐν γυμνασίοις: οἰκειότερος γὰρ αὐταῖς ὁ πόνος, ἴδιος ἀλλ᾽ οὐ κοινὸς ὢν μετὰ τοῦ σώματος.","st":"535b"},{"sp":"N","t":"ἀληθῆ, ἔφη.","st":"535b"},{"sp":"N","t":"καὶ μνήμονα δὴ καὶ ἄρρατον καὶ πάντῃ φιλόπονον ζητητέον. ἢ τίνι τρόπῳ οἴει τά τε τοῦ σώματος ἐθελήσειν τινὰ διαπονεῖν καὶ τοσαύτην μάθησίν τε καὶ μελέτην ἐπιτελεῖν;","st":"535c"},{"sp":"N","t":"οὐδένα, ἦ δ᾽ ὅς, ἐὰν μὴ παντάπασί γ᾽ ᾖ εὐφυής.","st":"535c"},{"sp":"N","t":"τὸ γοῦν νῦν ἁμάρτημα, ἦν δ᾽ ἐγώ, καὶ ἡ ἀτιμία φιλοσοφίᾳ διὰ ταῦτα προσπέπτωκεν, ὃ καὶ πρότερον εἴπομεν, ὅτι οὐ κατ᾽ ἀξίαν αὐτῆς ἅπτονται: οὐ γὰρ νόθους ἔδει ἅπτεσθαι, ἀλλὰ γνησίους.","st":"535c"},{"sp":"N","t":"πῶς; ἔφη.","st":"535c"},{"sp":"N","t":"πρῶτον μέν, εἶπον, φιλοπονίᾳ οὐ χωλὸν δεῖ εἶναι τὸν ἁψόμενον, τὰ μὲν ἡμίσεα φιλόπονον ὄντα, τὰ δ᾽ ἡμίσεα ἄπονον. ἔστι δὲ τοῦτο, ὅταν τις φιλογυμναστὴς μὲν καὶ φιλόθηρος ᾖ καὶ πάντα τὰ διὰ τοῦ σώματος φιλοπονῇ, φιλομαθὴς δὲ μή, μηδὲ φιλήκοος μηδὲ ζητητικός, ἀλλ᾽ ἐν πᾶσι τούτοις μισοπονῇ: χωλὸς δὲ καὶ ὁ τἀναντία τούτου μεταβεβληκὼς τὴν φιλοπονίαν.","st":"535d"},{"sp":"N","t":"ἀληθέστατα, ἔφη, λέγεις.","st":"535d"},{"sp":"N","t":"οὐκοῦν καὶ πρὸς ἀλήθειαν, ἦν δ᾽ ἐγώ, ταὐτὸν τοῦτο ἀνάπηρον","st":"535d"},{"sp":"N","t":"ψυχὴν θήσομεν, ἣ ἂν τὸ μὲν ἑκούσιον ψεῦδος μισῇ καὶ χαλεπῶς φέρῃ αὐτή τε καὶ ἑτέρων ψευδομένων ὑπεραγανακτῇ, τὸ δ᾽ ἀκούσιον εὐκόλως προσδέχηται καὶ ἀμαθαίνουσά που ἁλισκομένη μὴ ἀγανακτῇ, ἀλλ᾽ εὐχερῶς ὥσπερ θηρίον ὕειον ἐν ἀμαθίᾳ μολύνηται;","st":"535e"},{"sp":"N","t":"παντάπασι μὲν οὖν, ἔφη.","st":"536a"},{"sp":"N","t":"καὶ πρὸς σωφροσύνην, ἦν δ᾽ ἐγώ, καὶ ἀνδρείαν καὶ μεγαλοπρέπειαν καὶ πάντα τὰ τῆς ἀρετῆς μέρη οὐχ ἥκιστα δεῖ φυλάττειν τὸν νόθον τε καὶ τὸν γνήσιον. ὅταν γάρ τις μὴ ἐπίστηται πάντῃ τὰ τοιαῦτα σκοπεῖν καὶ ἰδιώτης καὶ πόλις, λανθάνουσι χωλοῖς τε καὶ νόθοις χρώμενοι πρὸς ὅτι ἂν τύχωσι τούτων, οἱ μὲν φίλοις, οἱ δὲ ἄρχουσι.","st":"536a"},{"sp":"N","t":"καὶ μάλα, ἔφη, οὕτως ἔχει.","st":"536a"},{"sp":"N","t":"ἡμῖν δή, ἦν δ᾽ ἐγώ, πάντα τὰ τοιαῦτα διευλαβητέον:","st":"536a"},{"sp":"N","t":"ὡς ἐὰν μὲν ἀρτιμελεῖς τε καὶ ἀρτίφρονας ἐπὶ τοσαύτην μάθησιν καὶ τοσαύτην ἄσκησιν κομίσαντες παιδεύωμεν, ἥ τε δίκη ἡμῖν οὐ μέμψεται αὐτή, τήν τε πόλιν καὶ πολιτείαν σώσομεν, ἀλλοίους δὲ ἄγοντες ἐπὶ ταῦτα τἀναντία πάντα καὶ πράξομεν καὶ φιλοσοφίας ἔτι πλείω γέλωτα καταντλήσομεν.","st":"536b"},{"sp":"N","t":"αἰσχρὸν μεντἂν εἴη, ἦ δ᾽ ὅς.","st":"536b"},{"sp":"N","t":"πάνυ μὲν οὖν, εἶπον: γελοῖον δ᾽ ἔγωγε καὶ ἐν τῷ παρόντι ⟨τι⟩ ἔοικα παθεῖν.","st":"536b"},{"sp":"N","t":"τὸ ποῖον; ἔφη.","st":"536b"},{"sp":"N","t":"ἐπελαθόμην, ἦν δ᾽ ἐγώ, ὅτι ἐπαίζομεν, καὶ μᾶλλον ἐντεινάμενος εἶπον. λέγων γὰρ ἅμα ἔβλεψα πρὸς φιλοσοφίαν, καὶ ἰδὼν προπεπηλακισμένην ἀναξίως ἀγανακτήσας μοι δοκῶ καὶ ὥσπερ θυμωθεὶς τοῖς αἰτίοις σπουδαιότερον εἰπεῖν ἃ εἶπον.","st":"536c"},{"sp":"N","t":"οὐ μὰ τὸν Δί᾽, ἔφη, οὔκουν ὥς γ᾽ ἐμοὶ ἀκροατῇ.","st":"536c"},{"sp":"N","t":"ἀλλ᾽ ὡς ἐμοί, ἦν δ᾽ ἐγώ, ῥήτορι. τόδε δὲ μὴ ἐπιλανθανώμεθα, ὅτι ἐν μὲν τῇ προτέρᾳ ἐκλογῇ πρεσβύτας ἐξελέγομεν,","st":"536c"},{"sp":"N","t":"ἐν δὲ ταύτῃ οὐκ ἐγχωρήσει: Σόλωνι γὰρ οὐ πειστέον ὡς γηράσκων τις πολλὰ δυνατὸς μανθάνειν, ἀλλ᾽ ἧττον ἢ τρέχειν, νέων δὲ πάντες οἱ μεγάλοι καὶ οἱ πολλοὶ πόνοι.","st":"536d"},{"sp":"N","t":"ἀνάγκη, ἔφη.","st":"536d"},{"sp":"N","t":"τὰ μὲν τοίνυν λογισμῶν τε καὶ γεωμετριῶν καὶ πάσης τῆς προπαιδείας, ἣν τῆς διαλεκτικῆς δεῖ προπαιδευθῆναι, παισὶν οὖσι χρὴ προβάλλειν, οὐχ ὡς ἐπάναγκες μαθεῖν τὸ σχῆμα τῆς διδαχῆς ποιουμένους.","st":"536d"},{"sp":"N","t":"τί δή;","st":"536d"},{"sp":"N","t":"ὅτι, ἦν δ᾽ ἐγώ, οὐδὲν μάθημα μετὰ δουλείας τὸν ἐλεύθερον χρὴ μανθάνειν. οἱ μὲν γὰρ τοῦ σώματος πόνοι βίᾳ πονούμενοι χεῖρον οὐδὲν τὸ σῶμα ἀπεργάζονται, ψυχῇ δὲ βίαιον οὐδὲν ἔμμονον μάθημα.","st":"536e"},{"sp":"N","t":"ἀληθῆ, ἔφη.","st":"536e"},{"sp":"N","t":"μὴ τοίνυν βίᾳ, εἶπον, ὦ ἄριστε, τοὺς παῖδας ἐν τοῖς","st":"536e"},{"sp":"N","t":"μαθήμασιν ἀλλὰ παίζοντας τρέφε, ἵνα καὶ μᾶλλον οἷός τ᾽ ᾖς καθορᾶν ἐφ᾽ ὃ ἕκαστος πέφυκεν.","st":"537a"},{"sp":"N","t":"ἔχει ὃ λέγεις, ἔφη, λόγον.","st":"537a"},{"sp":"N","t":"οὐκοῦν μνημονεύεις, ἦν δ᾽ ἐγώ, ὅτι καὶ εἰς τὸν πόλεμον ἔφαμεν τοὺς παῖδας εἶναι ἀκτέον ἐπὶ τῶν ἵππων θεωρούς, καὶ ἐάν που ἀσφαλὲς ᾖ, προσακτέον ἐγγὺς καὶ γευστέον αἵματος, ὥσπερ τοὺς σκύλακας;","st":"537a"},{"sp":"N","t":"μέμνημαι, ἔφη.","st":"537a"},{"sp":"N","t":"ἐν πᾶσι δὴ τούτοις, ἦν δ᾽ ἐγώ, τοῖς τε πόνοις καὶ μαθήμασι καὶ φόβοις ὃς ἂν ἐντρεχέστατος ἀεὶ φαίνηται, εἰς ἀριθμόν τινα ἐγκριτέον.","st":"537a"},{"sp":"N","t":"ἐν τίνι, ἔφη, ἡλικίᾳ;","st":"537b"},{"sp":"N","t":"ἡνίκα, ἦν δ᾽ ἐγώ, τῶν ἀναγκαίων γυμνασίων μεθίενται: οὗτος γὰρ ὁ χρόνος, ἐάντε δύο ἐάντε τρία ἔτη γίγνηται, ἀδύνατός τι ἄλλο πρᾶξαι: κόποι γὰρ καὶ ὕπνοι μαθήμασι πολέμιοι. καὶ ἅμα μία καὶ αὕτη τῶν βασάνων οὐκ ἐλαχίστη, τίς ἕκαστος ἐν τοῖς γυμνασίοις φανεῖται.","st":"537b"},{"sp":"N","t":"πῶς γὰρ οὔκ; ἔφη.","st":"537b"},{"sp":"N","t":"μετὰ δὴ τοῦτον τὸν χρόνον, ἦν δ᾽ ἐγώ, ἐκ τῶν εἰκοσιετῶν οἱ προκριθέντες τιμάς τε μείζους τῶν ἄλλων οἴσονται,","st":"537b"},{"sp":"N","t":"τά τε χύδην μαθήματα παισὶν ἐν τῇ παιδείᾳ γενόμενα τούτοις συνακτέον εἰς σύνοψιν οἰκειότητός τε ἀλλήλων τῶν μαθημάτων καὶ τῆς τοῦ ὄντος φύσεως.","st":"537c"},{"sp":"N","t":"μόνη γοῦν, εἶπεν, ἡ τοιαύτη μάθησις βέβαιος, ἐν οἷς ἂν ἐγγένηται.","st":"537c"},{"sp":"N","t":"καὶ μεγίστη γε, ἦν δ᾽ ἐγώ, πεῖρα διαλεκτικῆς φύσεως καὶ μή: ὁ μὲν γὰρ συνοπτικὸς διαλεκτικός, ὁ δὲ μὴ οὔ.","st":"537c"},{"sp":"N","t":"συνοίομαι, ἦ δ᾽ ὅς.","st":"537c"},{"sp":"N","t":"ταῦτα τοίνυν, ἦν δ᾽ ἐγώ, δεήσει σε ἐπισκοποῦντα οἳ ἂν","st":"537c"},{"sp":"N","t":"μάλιστα τοιοῦτοι ἐν αὐτοῖς ὦσι καὶ μόνιμοι μὲν ἐν μαθήμασι, μόνιμοι δ᾽ ἐν πολέμῳ καὶ τοῖς ἄλλοις νομίμοις, τούτους αὖ, ἐπειδὰν τὰ τριάκοντα ἔτη ἐκβαίνωσιν, ἐκ τῶν προκρίτων προκρινάμενον εἰς μείζους τε τιμὰς καθιστάναι καὶ σκοπεῖν, τῇ τοῦ διαλέγεσθαι δυνάμει βασανίζοντα τίς ὀμμάτων καὶ τῆς ἄλλης αἰσθήσεως δυνατὸς μεθιέμενος ἐπ᾽ αὐτὸ τὸ ὂν μετ᾽ ἀληθείας ἰέναι. καὶ ἐνταῦθα δὴ πολλῆς φυλακῆς ἔργον, ὦ ἑταῖρε.","st":"537d"},{"sp":"N","t":"τί μάλιστα; ἦ δ᾽ ὅς.","st":"537d"},{"sp":"N","t":"οὐκ ἐννοεῖς, ἦν δ᾽ ἐγώ, τὸ νῦν περὶ τὸ διαλέγεσθαι κακὸν γιγνόμενον ὅσον γίγνεται;","st":"537e"},{"sp":"N","t":"τὸ ποῖον; ἔφη.","st":"537e"},{"sp":"N","t":"παρανομίας που, ἔφην ἐγώ, ἐμπίμπλανται.","st":"537e"},{"sp":"N","t":"καὶ μάλα, ἔφη.","st":"537e"},{"sp":"N","t":"θαυμαστὸν οὖν τι οἴει, εἶπον, πάσχειν αὐτούς, καὶ οὐ συγγιγνώσκεις;","st":"537e"},{"sp":"N","t":"πῇ μάλιστα; ἔφη.","st":"537e"},{"sp":"N","t":"οἷον, ἦν δ᾽ ἐγώ, εἴ τις ὑποβολιμαῖος τραφείη ἐν πολλοῖς","st":"537e"},{"sp":"N","t":"μὲν χρήμασι, πολλῷ δὲ καὶ μεγάλῳ γένει καὶ κόλαξι πολλοῖς, ἀνὴρ δὲ γενόμενος αἴσθοιτο ὅτι οὐ τούτων ἐστὶ τῶν φασκόντων γονέων, τοὺς δὲ τῷ ὄντι γεννήσαντας μὴ εὕροι, τοῦτον ἔχεις μαντεύσασθαι πῶς ἂν διατεθείη πρός τε τοὺς κόλακας καὶ πρὸς τοὺς ὑποβαλομένους ἐν ἐκείνῳ τε τῷ χρόνῳ ᾧ οὐκ ᾔδει τὰ περὶ τῆς ὑποβολῆς, καὶ ἐν ᾧ αὖ ᾔδει; ἢ βούλει ἐμοῦ μαντευομένου ἀκοῦσαι;","st":"538a"},{"sp":"N","t":"βούλομαι, ἔφη.","st":"538a"},{"sp":"N","t":"μαντεύομαι τοίνυν, εἶπον, μᾶλλον αὐτὸν τιμᾶν ἂν τὸν","st":"538a"},{"sp":"N","t":"πατέρα καὶ τὴν μητέρα καὶ τοὺς ἄλλους οἰκείους δοκοῦντας ἢ τοὺς κολακεύοντας, καὶ ἧττον μὲν ἂν περιιδεῖν ἐνδεεῖς τινος, ἧττον δὲ παράνομόν τι δρᾶσαι ἢ εἰπεῖν εἰς αὐτούς, ἧττον δὲ ἀπειθεῖν τὰ μεγάλα ἐκείνοις ἢ τοῖς κόλαξιν, ἐν ᾧ χρόνῳ τὸ ἀληθὲς μὴ εἰδείη.","st":"538b"},{"sp":"N","t":"εἰκός, ἔφη.","st":"538b"},{"sp":"N","t":"αἰσθόμενον τοίνυν τὸ ὂν μαντεύομαι αὖ περὶ μὲν τούτους ἀνεῖναι ἂν τὸ τιμᾶν τε καὶ σπουδάζειν, περὶ δὲ τοὺς κόλακας ἐπιτεῖναι, καὶ πείθεσθαί τε αὐτοῖς διαφερόντως ἢ πρότερον","st":"538b"},{"sp":"N","t":"καὶ ζῆν ἂν ἤδη κατ᾽ ἐκείνους, συνόντα αὐτοῖς ἀπαρακαλύπτως, πατρὸς δὲ ἐκείνου καὶ τῶν ἄλλων ποιουμένων οἰκείων, εἰ μὴ πάνυ εἴη φύσει ἐπιεικής, μέλειν τὸ μηδέν.","st":"538c"},{"sp":"N","t":"πάντ᾽, ἔφη, λέγεις οἷά περ ἂν γένοιτο. ἀλλὰ πῇ πρὸς τοὺς ἁπτομένους τῶν λόγων αὕτη φέρει ἡ εἰκών;","st":"538c"},{"sp":"N","t":"τῇδε. ἔστι που ἡμῖν δόγματα ἐκ παίδων περὶ δικαίων καὶ καλῶν, ἐν οἷς ἐκτεθράμμεθα ὥσπερ ὑπὸ γονεῦσι, πειθαρχοῦντές τε καὶ τιμῶντες αὐτά.","st":"538c"},{"sp":"N","t":"ἔστι γάρ.","st":"538c"},{"sp":"N","t":"οὐκοῦν καὶ ἄλλα ἐναντία τούτων ἐπιτηδεύματα ἡδονὰς ἔχοντα, ἃ κολακεύει μὲν ἡμῶν τὴν ψυχὴν καὶ ἕλκει ἐφ᾽ αὑτά, πείθει δ᾽ οὒ τοὺς καὶ ὁπῃοῦν μετρίους: ἀλλ᾽ ἐκεῖνα τιμῶσι τὰ πάτρια καὶ ἐκείνοις πειθαρχοῦσιν.","st":"538d"},{"sp":"N","t":"ἔστι ταῦτα.","st":"538d"},{"sp":"N","t":"τί οὖν; ἦν δ᾽ ἐγώ: ὅταν τὸν οὕτως ἔχοντα ἐλθὸν ἐρώτημα ἔρηται: τί ἐστι τὸ καλόν, καὶ ἀποκριναμένου ὃ τοῦ νομοθέτου ἤκουεν ἐξελέγχῃ ὁ λόγος, καὶ πολλάκις καὶ πολλαχῇ ἐλέγχων εἰς δόξαν καταβάλῃ ὡς τοῦτο οὐδὲν μᾶλλον","st":"538d"},{"sp":"N","t":"καλὸν ἢ αἰσχρόν, καὶ περὶ δικαίου ὡσαύτως καὶ ἀγαθοῦ καὶ ἃ μάλιστα ἦγεν ἐν τιμῇ, μετὰ τοῦτο τί οἴει ποιήσειν αὐτὸν πρὸς αὐτὰ τιμῆς τε πέρι καὶ πειθαρχίας;","st":"538e"},{"sp":"N","t":"ἀνάγκη, ἔφη, μήτε τιμᾶν ἔτι ὁμοίως μήτε πείθεσθαι.","st":"538e"},{"sp":"N","t":"ὅταν οὖν, ἦν δ᾽ ἐγώ, μήτε ταῦτα ἡγῆται τίμια καὶ οἰκεῖα ὥσπερ πρὸ τοῦ, τά τε ἀληθῆ μὴ εὑρίσκῃ, ἔστι πρὸς ὁποῖον","st":"538e"},{"sp":"N","t":"βίον ἄλλον ἢ τὸν κολακεύοντα εἰκότως προσχωρήσεται;","st":"539a"},{"sp":"N","t":"οὐκ ἔστιν, ἔφη.","st":"539a"},{"sp":"N","t":"παράνομος δὴ οἶμαι δόξει γεγονέναι ἐκ νομίμου.","st":"539a"},{"sp":"N","t":"ἀνάγκη.","st":"539a"},{"sp":"N","t":"οὐκοῦν, ἔφην, εἰκὸς τὸ πάθος τῶν οὕτω λόγων ἁπτομένων καί, ὃ ἄρτι ἔλεγον, πολλῆς συγγνώμης ἄξιον;","st":"539a"},{"sp":"N","t":"καὶ ἐλέου γ᾽, ἔφη.","st":"539a"},{"sp":"N","t":"οὐκοῦν ἵνα μὴ γίγνηται ὁ ἔλεος οὗτος περὶ τοὺς τριακοντούτας σοι, εὐλαβουμένῳ παντὶ τρόπῳ τῶν λόγων ἁπτέον;","st":"539a"},{"sp":"N","t":"καὶ μάλ᾽, ἦ δ᾽ ὅς.","st":"539a"},{"sp":"N","t":"ἆρ᾽ οὖν οὐ μία μὲν εὐλάβεια αὕτη συχνή, τὸ μὴ νέους ὄντας αὐτῶν γεύεσθαι; οἶμαι γάρ σε οὐ λεληθέναι ὅτι οἱ μειρακίσκοι, ὅταν τὸ πρῶτον λόγων γεύωνται, ὡς παιδιᾷ αὐτοῖς καταχρῶνται, ἀεὶ εἰς ἀντιλογίαν χρώμενοι, καὶ μιμούμενοι τοὺς ἐξελέγχοντας αὐτοὶ ἄλλους ἐλέγχουσι, χαίροντες ὥσπερ σκυλάκια τῷ ἕλκειν τε καὶ σπαράττειν τῷ λόγῳ τοὺς πλησίον ἀεί.","st":"539b"},{"sp":"N","t":"ὑπερφυῶς μὲν οὖν, ἔφη.","st":"539b"},{"sp":"N","t":"οὐκοῦν ὅταν δὴ πολλοὺς μὲν αὐτοὶ ἐλέγξωσιν, ὑπὸ πολλῶν","st":"539b"},{"sp":"N","t":"δὲ ἐλεγχθῶσι, σφόδρα καὶ ταχὺ ἐμπίπτουσιν εἰς τὸ μηδὲν ἡγεῖσθαι ὧνπερ πρότερον: καὶ ἐκ τούτων δὴ αὐτοί τε καὶ τὸ ὅλον φιλοσοφίας πέρι εἰς τοὺς ἄλλους διαβέβληνται.","st":"539c"},{"sp":"N","t":"ἀληθέστατα, ἔφη.","st":"539c"},{"sp":"N","t":"ὁ δὲ δὴ πρεσβύτερος, ἦν δ᾽ ἐγώ, τῆς μὲν τοιαύτης μανίας οὐκ ἂν ἐθέλοι μετέχειν, τὸν δὲ διαλέγεσθαι ἐθέλοντα καὶ σκοπεῖν τἀληθὲς μᾶλλον μιμήσεται ἢ τὸν παιδιᾶς χάριν παίζοντα καὶ ἀντιλέγοντα, καὶ αὐτός τε μετριώτερος ἔσται","st":"539c"},{"sp":"N","t":"καὶ τὸ ἐπιτήδευμα τιμιώτερον ἀντὶ ἀτιμοτέρου ποιήσει.","st":"539d"},{"sp":"N","t":"ὀρθῶς, ἔφη.","st":"539d"},{"sp":"N","t":"οὐκοῦν καὶ τὰ προειρημένα τούτου ἐπ᾽ εὐλαβείᾳ πάντα προείρηται, τὸ τὰς φύσεις κοσμίους εἶναι καὶ στασίμους οἷς τις μεταδώσει τῶν λόγων, καὶ μὴ ὡς νῦν ὁ τυχὼν καὶ οὐδὲν προσήκων ἔρχεται ἐπ᾽ αὐτό;","st":"539d"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη.","st":"539d"},{"sp":"N","t":"ἀρκεῖ δὴ ἐπὶ λόγων μεταλήψει μεῖναι ἐνδελεχῶς καὶ συντόνως μηδὲν ἄλλο πράττοντι, ἀλλ᾽ ἀντιστρόφως γυμναζομένῳ τοῖς περὶ τὸ σῶμα γυμνασίοις, ἔτη διπλάσια ἢ τότε;","st":"539d"},{"sp":"N","t":"ἕξ, ἔφη, ἢ τέτταρα λέγεις;","st":"539e"},{"sp":"N","t":"ἀμέλει, εἶπον, πέντε θές. μετὰ γὰρ τοῦτο καταβιβαστέοι ἔσονταί σοι εἰς τὸ σπήλαιον πάλιν ἐκεῖνο, καὶ ἀναγκαστέοι ἄρχειν τά τε περὶ τὸν πόλεμον καὶ ὅσαι νέων ἀρχαί, ἵνα μηδ᾽ ἐμπειρίᾳ ὑστερῶσι τῶν ἄλλων: καὶ ἔτι καὶ ἐν τούτοις","st":"539e"},{"sp":"N","t":"βασανιστέοι εἰ ἐμμενοῦσιν ἑλκόμενοι πανταχόσε ἤ τι καὶ παρακινήσουσι.","st":"540a"},{"sp":"N","t":"χρόνον δέ, ἦ δ᾽ ὅς, πόσον τοῦτον τιθεῖς;","st":"540a"},{"sp":"N","t":"πεντεκαίδεκα ἔτη, ἦν δ᾽ ἐγώ. γενομένων δὲ πεντηκοντουτῶν τοὺς διασωθέντας καὶ ἀριστεύσαντας πάντα πάντῃ ἐν ἔργοις τε καὶ ἐπιστήμαις πρὸς τέλος ἤδη ἀκτέον, καὶ ἀναγκαστέον ἀνακλίναντας τὴν τῆς ψυχῆς αὐγὴν εἰς αὐτὸ ἀποβλέψαι τὸ πᾶσι φῶς παρέχον, καὶ ἰδόντας τὸ ἀγαθὸν αὐτό, παραδείγματι χρωμένους ἐκείνῳ, καὶ πόλιν καὶ ἰδιώτας","st":"540a"},{"sp":"N","t":"καὶ ἑαυτοὺς κοσμεῖν τὸν ἐπίλοιπον βίον ἐν μέρει ἑκάστους, τὸ μὲν πολὺ πρὸς φιλοσοφίᾳ διατρίβοντας, ὅταν δὲ τὸ μέρος ἥκῃ, πρὸς πολιτικοῖς ἐπιταλαιπωροῦντας καὶ ἄρχοντας ἑκάστους τῆς πόλεως ἕνεκα, οὐχ ὡς καλόν τι ἀλλ᾽ ὡς ἀναγκαῖον πράττοντας, καὶ οὕτως ἄλλους ἀεὶ παιδεύσαντας τοιούτους, ἀντικαταλιπόντας τῆς πόλεως φύλακας, εἰς μακάρων νήσους ἀπιόντας οἰκεῖν: μνημεῖα δ᾽ αὐτοῖς καὶ θυσίας","st":"540b"},{"sp":"N","t":"τὴν πόλιν δημοσίᾳ ποιεῖν, ἐὰν καὶ ἡ Πυθία συναναιρῇ, ὡς δαίμοσιν, εἰ δὲ μή, ὡς εὐδαίμοσί τε καὶ θείοις.","st":"540c"},{"sp":"N","t":"παγκάλους, ἔφη, τοὺς ἄρχοντας, ὦ Σώκρατες, ὥσπερ ἀνδριαντοποιὸς ἀπείργασαι.","st":"540c"},{"sp":"N","t":"καὶ τὰς ἀρχούσας γε, ἦν δ᾽ ἐγώ, ὦ Γλαύκων: μηδὲν γάρ τι οἴου με περὶ ἀνδρῶν εἰρηκέναι μᾶλλον ἃ εἴρηκα ἢ περὶ γυναικῶν, ὅσαι ἂν αὐτῶν ἱκαναὶ τὰς φύσεις ἐγγίγνωνται.","st":"540c"},{"sp":"N","t":"ὀρθῶς, ἔφη, εἴπερ ἴσα γε πάντα τοῖς ἀνδράσι κοινωνήσουσιν, ὡς διήλθομεν.","st":"540c"},{"sp":"N","t":"τί οὖν; ἔφην: συγχωρεῖτε περὶ τῆς πόλεώς τε καὶ πολιτείας μὴ παντάπασιν ἡμᾶς εὐχὰς εἰρηκέναι, ἀλλὰ χαλεπὰ μέν, δυνατὰ δέ πῃ, καὶ οὐκ ἄλλῃ ἢ εἴρηται, ὅταν οἱ ὡς ἀληθῶς φιλόσοφοι δυνάσται, ἢ πλείους ἢ εἷς, ἐν πόλει γενόμενοι τῶν μὲν νῦν τιμῶν καταφρονήσωσιν, ἡγησάμενοι ἀνελευθέρους εἶναι καὶ οὐδενὸς ἀξίας, τὸ δὲ ὀρθὸν περὶ","st":"540d"},{"sp":"N","t":"πλείστου ποιησάμενοι καὶ τὰς ἀπὸ τούτου τιμάς, μέγιστον δὲ καὶ ἀναγκαιότατον τὸ δίκαιον, καὶ τούτῳ δὴ ὑπηρετοῦντές τε καὶ αὔξοντες αὐτὸ διασκευωρήσωνται τὴν ἑαυτῶν πόλιν;","st":"540e"},{"sp":"N","t":"πῶς; ἔφη.","st":"540e"},{"sp":"N","t":"ὅσοι μὲν ἄν, ἦν δ᾽ ἐγώ, πρεσβύτεροι τυγχάνωσι δεκετῶν","st":"540e"},{"sp":"N","t":"ἐν τῇ πόλει, πάντας ἐκπέμψωσιν εἰς τοὺς ἀγρούς, τοὺς δὲ παῖδας αὐτῶν παραλαβόντες ἐκτὸς τῶν νῦν ἠθῶν, ἃ καὶ οἱ γονῆς ἔχουσι, θρέψωνται ἐν τοῖς σφετέροις τρόποισι καὶ νόμοις, οὖσιν οἵοις διεληλύθαμεν τότε: καὶ οὕτω τάχιστά τε καὶ ῥᾷστα πόλιν τε καὶ πολιτείαν, ἣν ἐλέγομεν, καταστᾶσαν αὐτήν τε εὐδαιμονήσειν καὶ τὸ ἔθνος ἐν ᾧ ἂν ἐγγένηται πλεῖστα ὀνήσειν;","st":"541a"},{"sp":"N","t":"πολύ γ᾽, ἔφη: καὶ ὡς ἂν γένοιτο, εἴπερ ποτὲ γίγνοιτο,","st":"541a"},{"sp":"N","t":"δοκεῖς μοι, ὦ Σώκρατες, εὖ εἰρηκέναι.","st":"541b"},{"sp":"N","t":"οὐκοῦν ἅδην ἤδη, εἶπον ἐγώ, ἔχουσιν ἡμῖν οἱ λόγοι περί τε τῆς πόλεως ταύτης καὶ τοῦ ὁμοίου ταύτῃ ἀνδρός; δῆλος γάρ που καὶ οὗτος οἷον φήσομεν δεῖν αὐτὸν εἶναι.","st":"541b"},{"sp":"N","t":"δῆλος, ἔφη: καὶ ὅπερ ἐρωτᾷς, δοκεῖ μοι τέλος ἔχειν.","st":"541b"},{"sp":"N","t":"ΣΩΚΡΆΤΗς, ΓΛΑΎΚΩΝ","st":"541b"},{"sp":"N","t":"εἶεν: ταῦτα μὲν δὴ ὡμολόγηται, ὦ Γλαύκων, τῇ μελλούσῃ ἄκρως οἰκεῖν πόλει κοινὰς μὲν γυναῖκας, κοινοὺς δὲ παῖδας εἶναι καὶ πᾶσαν παιδείαν, ὡσαύτως δὲ τὰ ἐπιτηδεύματα κοινὰ ἐν πολέμῳ τε καὶ εἰρήνῃ, βασιλέας δὲ αὐτῶν εἶναι τοὺς ἐν φιλοσοφίᾳ τε καὶ πρὸς τὸν πόλεμον γεγονότας ἀρίστους.","st":"543a"},{"sp":"N","t":"ὡμολόγηται, ἔφη.","st":"543a"},{"sp":"N","t":"καὶ μὴν καὶ τάδε συνεχωρήσαμεν, ὡς, ὅταν δὴ καταστῶσιν οἱ ἄρχοντες, ἄγοντες τοὺς στρατιώτας κατοικιοῦσιν εἰς οἰκήσεις οἵας προείπομεν, ἴδιον μὲν οὐδὲν οὐδενὶ ἐχούσας, κοινὰς δὲ πᾶσι: πρὸς δὲ ταῖς τοιαύταις οἰκήσεσι, καὶ τὰς κτήσεις, εἰ μνημονεύεις, διωμολογησάμεθά που οἷαι ἔσονται αὐτοῖς.","st":"543b"},{"sp":"N","t":"ἀλλὰ μνημονεύω, ἔφη, ὅτι γε οὐδὲν οὐδένα ᾠόμεθα δεῖν κεκτῆσθαι ὧν νῦν οἱ ἄλλοι, ὥσπερ δὲ ἀθλητάς τε πολέμου","st":"543b"},{"sp":"N","t":"καὶ φύλακας, μισθὸν τῆς φυλακῆς δεχομένους εἰς ἐνιαυτὸν τὴν εἰς ταῦτα τροφὴν παρὰ τῶν ἄλλων, αὑτῶν τε δεῖν καὶ τῆς ἄλλης πόλεως ἐπιμελεῖσθαι. ὀρθῶς, ἔφην, λέγεις. ἀλλ᾽ ἄγ᾽, ἐπειδὴ τοῦτ᾽ ἀπετελέσαμεν, ἀναμνησθῶμεν πόθεν δεῦρο ἐξετραπόμεθα, ἵνα πάλιν τὴν αὐτὴν ἴωμεν. οὐ χαλεπόν, ἔφη. σχεδὸν γάρ, καθάπερ νῦν, ὡς διεληλυθὼς περὶ τῆς πόλεως τοὺς λόγους ἐποιοῦ, λέγων ὡς ἀγαθὴν μὲν τὴν τοιαύτην, οἵαν τότε διῆλθες, τιθείης πόλιν,","st":"543c"},{"sp":"N","t":"καὶ ἄνδρα τὸν ἐκείνῃ ὅμοιον, καὶ ταῦτα, ὡς ἔοικας, καλλίω","st":"543d"},{"sp":"N","t":"ἔτι ἔχων εἰπεῖν πόλιν τε καὶ ἄνδρα. ἀλλ᾽ οὖν δὴ τὰς ἄλλας ἡμαρτημένας ἔλεγες, εἰ αὕτη ὀρθή. τῶν δὲ λοιπῶν πολιτειῶν ἔφησθα, ὡς μνημονεύω, τέτταρα εἴδη εἶναι, ὧν καὶ πέρι λόγον ἄξιον εἴη ἔχειν καὶ ἰδεῖν αὐτῶν τὰ ἁμαρτήματα καὶ τοὺς ἐκείναις αὖ ὁμοίους, ἵνα πάντας αὐτοὺς ἰδόντες, καὶ ὁμολογησάμενοι τὸν ἄριστον καὶ τὸν κάκιστον ἄνδρα, ἐπισκεψαίμεθα εἰ ὁ ἄριστος εὐδαιμονέστατος καὶ ὁ κάκιστος ἀθλιώτατος, ἢ ἄλλως ἔχοι: καὶ ἐμοῦ ἐρομένου τίνας λέγοις","st":"544a"},{"sp":"N","t":"τὰς τέτταρας πολιτείας, ἐν τούτῳ ὑπέλαβε Πολέμαρχός τε καὶ Ἀδείμαντος, καὶ οὕτω δὴ σὺ ἀναλαβὼν τὸν λόγον δεῦρ᾽ ἀφῖξαι.","st":"544b"},{"sp":"N","t":"ὀρθότατα, εἶπον, ἐμνημόνευσας.","st":"544b"},{"sp":"N","t":"πάλιν τοίνυν, ὥσπερ παλαιστής, τὴν αὐτὴν λαβὴν πάρεχε, καὶ τὸ αὐτὸ ἐμοῦ ἐρομένου πειρῶ εἰπεῖν ἅπερ τότε ἔμελλες λέγειν.","st":"544b"},{"sp":"N","t":"ἐάνπερ, ἦν δ᾽ ἐγώ, δύνωμαι.","st":"544b"},{"sp":"N","t":"καὶ μήν, ἦ δ᾽ ὅς, ἐπιθυμῶ γε καὶ αὐτὸς ἀκοῦσαι τίνας ἔλεγες τὰς τέτταρας πολιτείας.","st":"544b"},{"sp":"N","t":"οὐ χαλεπῶς, ἦν δ᾽ ἐγώ, ἀκούσῃ. εἰσὶ γὰρ ἃς λέγω, αἵπερ καὶ ὀνόματα ἔχουσιν, ἥ τε ὑπὸ τῶν πολλῶν ἐπαινουμένη, ἡ Κρητική τε καὶ Λακωνικὴ αὕτη: καὶ δευτέρα καὶ δευτέρως ἐπαινουμένη, καλουμένη δ᾽ ὀλιγαρχία, συχνῶν γέμουσα κακῶν πολιτεία: ἥ τε ταύτῃ διάφορος καὶ ἐφεξῆς γιγνομένη δημοκρατία, καὶ ἡ γενναία δὴ τυραννὶς καὶ πασῶν τούτων διαφέρουσα, τέταρτόν τε καὶ ἔσχατον πόλεως νόσημα. ἤ τινα ἄλλην ἔχεις ἰδέαν πολιτείας, ἥτις καὶ ἐν εἴδει διαφανεῖ","st":"544c"},{"sp":"N","t":"τινι κεῖται; δυναστεῖαι γὰρ καὶ ὠνηταὶ βασιλεῖαι καὶ τοιαῦταί τινες πολιτεῖαι μεταξύ τι τούτων πού εἰσιν, εὕροι δ᾽ ἄν τις αὐτὰς οὐκ ἐλάττους περὶ τοὺς βαρβάρους ἢ τοὺς Ἕλληνας.","st":"544d"},{"sp":"N","t":"πολλαὶ γοῦν καὶ ἄτοποι, ἔφη, λέγονται.","st":"544d"},{"sp":"N","t":"οἶσθ᾽ οὖν, ἦν δ᾽ ἐγώ, ὅτι καὶ ἀνθρώπων εἴδη τοσαῦτα ἀνάγκη τρόπων εἶναι, ὅσαπερ καὶ πολιτειῶν; ἢ οἴει ἐκ δρυός ποθεν ἢ ἐκ πέτρας τὰς πολιτείας γίγνεσθαι, ἀλλ᾽","st":"544d"},{"sp":"N","t":"οὐχὶ ἐκ τῶν ἠθῶν τῶν ἐν ταῖς πόλεσιν, ἃ ἂν ὥσπερ ῥέψαντα τἆλλα ἐφελκύσηται;","st":"544e"},{"sp":"N","t":"οὐδαμῶς ἔγωγ᾽, ἔφη, ἄλλοθεν ἢ ἐντεῦθεν.","st":"544e"},{"sp":"N","t":"οὐκοῦν εἰ τὰ τῶν πόλεων πέντε, καὶ αἱ τῶν ἰδιωτῶν κατασκευαὶ τῆς ψυχῆς πέντε ἂν εἶεν.","st":"544e"},{"sp":"N","t":"τί μήν;","st":"544e"},{"sp":"N","t":"τὸν μὲν δὴ τῇ ἀριστοκρατίᾳ ὅμοιον διεληλύθαμεν ἤδη, ὃν ἀγαθόν τε καὶ δίκαιον ὀρθῶς φαμεν εἶναι.","st":"544e"},{"sp":"N","t":"διεληλύθαμεν.","st":"545a"},{"sp":"N","t":"ἆρ᾽ οὖν τὸ μετὰ τοῦτο διιτέον τοὺς χείρους, τὸν φιλόνικόν τε καὶ φιλότιμον, κατὰ τὴν Λακωνικὴν ἑστῶτα πολιτείαν, καὶ ὀλιγαρχικὸν αὖ καὶ δημοκρατικὸν καὶ τὸν τυραννικόν, ἵνα τὸν ἀδικώτατον ἰδόντες ἀντιθῶμεν τῷ δικαιοτάτῳ καὶ ἡμῖν τελέα ἡ σκέψις ᾖ, πῶς ποτε ἡ ἄκρατος δικαιοσύνη πρὸς ἀδικίαν τὴν ἄκρατον ἔχει εὐδαιμονίας τε πέρι τοῦ ἔχοντος καὶ ἀθλιότητος, ἵνα ἢ Θρασυμάχῳ πειθόμενοι","st":"545a"},{"sp":"N","t":"διώκωμεν ἀδικίαν ἢ τῷ νῦν προφαινομένῳ λόγῳ δικαιοσύνην;","st":"545b"},{"sp":"N","t":"παντάπασι μὲν οὖν, ἔφη, οὕτω ποιητέον.","st":"545b"},{"sp":"N","t":"ἆρ᾽ οὖν, ὥσπερ ἠρξάμεθα ἐν ταῖς πολιτείαις πρότερον σκοπεῖν τὰ ἤθη ἢ ἐν τοῖς ἰδιώταις, ὡς ἐναργέστερον ὄν, καὶ νῦν οὕτω πρῶτον μὲν τὴν φιλότιμον σκεπτέον πολιτείαν -ὄνομα γὰρ οὐκ ἔχω λεγόμενον ἄλλο: ἢ τιμοκρατίαν ἢ τιμαρχίαν αὐτὴν κλητέον — πρὸς δὲ ταύτην τὸν τοιοῦτον","st":"545b"},{"sp":"N","t":"ἄνδρα σκεψόμεθα, ἔπειτα ὀλιγαρχίαν καὶ ἄνδρα ὀλιγαρχικόν, αὖθις δὲ εἰς δημοκρατίαν ἀποβλέψαντες θεασόμεθα ἄνδρα δημοκρατικόν, τὸ δὲ τέταρτον εἰς τυραννουμένην πόλιν ἐλθόντες καὶ ἰδόντες, πάλιν εἰς τυραννικὴν ψυχὴν βλέποντες, πειρασόμεθα περὶ ὧν προυθέμεθα ἱκανοὶ κριταὶ γενέσθαι;","st":"545c"},{"sp":"N","t":"κατὰ λόγον γέ τοι ἄν, ἔφη, οὕτω γίγνοιτο ἥ τε θέα καὶ ἡ κρίσις.","st":"545c"},{"sp":"N","t":"φέρε τοίνυν, ἦν δ᾽ ἐγώ, πειρώμεθα λέγειν τίνα τρόπον τιμοκρατία γένοιτ᾽ ἂν ἐξ ἀριστοκρατίας. ἢ τόδε μὲν ἁπλοῦν,","st":"545c"},{"sp":"N","t":"ὅτι πᾶσα πολιτεία μεταβάλλει ἐξ αὐτοῦ τοῦ ἔχοντος τὰς ἀρχάς, ὅταν ἐν αὐτῷ τούτῳ στάσις ἐγγένηται: ὁμονοοῦντος δέ, κἂν πάνυ ὀλίγον ᾖ, ἀδύνατον κινηθῆναι;","st":"545d"},{"sp":"N","t":"ἔστι γὰρ οὕτω.","st":"545d"},{"sp":"N","t":"πῶς οὖν δή, εἶπον, ὦ Γλαύκων, ἡ πόλις ἡμῖν κινηθήσεται, καὶ πῇ στασιάσουσιν οἱ ἐπίκουροι καὶ οἱ ἄρχοντες πρὸς ἀλλήλους τε καὶ πρὸς ἑαυτούς; ἢ βούλει, ὥσπερ Ὅμηρος, εὐχώμεθα ταῖς Μούσαις εἰπεῖν ἡμῖν “ὅπως δὴ”","st":"545d"},{"sp":"N","t":"“πρῶτον” στάσις “ἔμπεσε” καὶ φῶμεν αὐτὰς τραγικῶς ὡς πρὸς παῖδας ἡμᾶς παιζούσας καὶ ἐρεσχηλούσας, ὡς δὴ σπουδῇ λεγούσας, ὑψηλολογουμένας λέγειν;","st":"545e"},{"sp":"N","t":"πῶς;","st":"545e"},{"sp":"N","t":"ὧδέ πως. χαλεπὸν μὲν κινηθῆναι πόλιν οὕτω συστᾶσαν: ἀλλ᾽ ἐπεὶ γενομένῳ παντὶ φθορά ἐστιν, οὐδ᾽ ἡ τοιαύτη σύστασις τὸν ἅπαντα μενεῖ χρόνον, ἀλλὰ λυθήσεται. λύσις δὲ ἥδε: οὐ μόνον φυτοῖς ἐγγείοις, ἀλλὰ καὶ ἐν ἐπιγείοις ζῴοις φορὰ καὶ ἀφορία ψυχῆς τε καὶ σωμάτων γίγνονται, ὅταν περιτροπαὶ ἑκάστοις κύκλων περιφορὰς συνάπτωσι, βραχυβίοις μὲν βραχυπόρους, ἐναντίοις δὲ ἐναντίας. γένους δὲ ὑμετέρου εὐγονίας τε καὶ ἀφορίας, καίπερ ὄντες σοφοί,","st":"546a"},{"sp":"N","t":"οὓς ἡγεμόνας πόλεως ἐπαιδεύσασθε, οὐδὲν μᾶλλον λογισμῷ μετ᾽ αἰσθήσεως τεύξονται, ἀλλὰ πάρεισιν αὐτοὺς καὶ γεννήσουσι παῖδάς ποτε οὐ δέον. ἔστι δὲ θείῳ μὲν γεννητῷ περίοδος ἣν ἀριθμὸς περιλαμβάνει τέλειος, ἀνθρωπείῳ δὲ ἐν ᾧ πρώτῳ αὐξήσεις δυνάμεναί τε καὶ δυναστευόμεναι, τρεῖς ἀποστάσεις, τέτταρας δὲ ὅρους λαβοῦσαι ὁμοιούντων τε καὶ ἀνομοιούντων καὶ αὐξόντων καὶ φθινόντων, πάντα προσήγορα","st":"546b"},{"sp":"N","t":"καὶ ῥητὰ πρὸς ἄλληλα ἀπέφηναν: ὧν ἐπίτριτος πυθμὴν πεμπάδι συζυγεὶς δύο ἁρμονίας παρέχεται τρὶς αὐξηθείς, τὴν μὲν ἴσην ἰσάκις, ἑκατὸν τοσαυτάκις, τὴν δὲ ἰσομήκη μὲν τῇ, προμήκη δέ, ἑκατὸν μὲν ἀριθμῶν ἀπὸ διαμέτρων ῥητῶν πεμπάδος, δεομένων ἑνὸς ἑκάστων, ἀρρήτων δὲ δυοῖν, ἑκατὸν δὲ κύβων τριάδος. σύμπας δὲ οὗτος ἀριθμὸς γεωμετρικός, τοιούτου κύριος, ἀμεινόνων τε καὶ χειρόνων γενέσεων,","st":"546c"},{"sp":"N","t":"ἃς ὅταν ἀγνοήσαντες ὑμῖν οἱ φύλακες συνοικίζωσιν νύμφας νυμφίοις παρὰ καιρόν, οὐκ εὐφυεῖς οὐδ᾽ εὐτυχεῖς παῖδες ἔσονται: ὧν καταστήσουσι μὲν τοὺς ἀρίστους οἱ πρότεροι, ὅμως δὲ ὄντες ἀνάξιοι, εἰς τὰς τῶν πατέρων αὖ δυνάμεις ἐλθόντες, ἡμῶν πρῶτον ἄρξονται ἀμελεῖν φύλακες ὄντες, παρ᾽ ἔλαττον τοῦ δέοντος ἡγησάμενοι τὰ μουσικῆς, δεύτερον δὲ τὰ γυμναστικῆς, ὅθεν ἀμουσότεροι γενήσονται ὑμῖν οἱ νέοι. ἐκ δὲ τούτων ἄρχοντες οὐ πάνυ φυλακικοὶ","st":"546d"},{"sp":"N","t":"καταστήσονται πρὸς τὸ δοκιμάζειν τὰ Ἡσιόδου τε καὶ τὰ παρ᾽","st":"546e"},{"sp":"N","t":"ὑμῖν γένη, χρυσοῦν τε καὶ ἀργυροῦν καὶ χαλκοῦν καὶ σιδηροῦν: ὁμοῦ δὲ μιγέντος σιδηροῦ ἀργυρῷ καὶ χαλκοῦ χρυσῷ ἀνομοιότης ἐγγενήσεται καὶ ἀνωμαλία ἀνάρμοστος, ἃ γενόμενα, οὗ ἂν ἐγγένηται, ἀεὶ τίκτει πόλεμον καὶ ἔχθραν.","st":"547a"},{"sp":"N","t":"ταύτης τοι γενεῆς","st":"547a"},{"sp":"N","t":"χρὴ φάναι εἶναι στάσιν, ὅπου ἂν γίγνηται ἀεί.","st":"547a"},{"sp":"N","t":"καὶ ὀρθῶς γ᾽, ἔφη, αὐτὰς ἀποκρίνεσθαι φήσομεν.","st":"547a"},{"sp":"N","t":"καὶ γάρ, ἦν δ᾽ ἐγώ, ἀνάγκη μούσας γε οὔσας.","st":"547a"},{"sp":"N","t":"τί οὖν, ἦ δ᾽ ὅς, τὸ μετὰ τοῦτο λέγουσιν αἱ Μοῦσαι;","st":"547b"},{"sp":"N","t":"στάσεως, ἦν δ᾽ ἐγώ, γενομένης εἱλκέτην ἄρα ἑκατέρω τὼ γένει, τὸ μὲν σιδηροῦν καὶ χαλκοῦν ἐπὶ χρηματισμὸν καὶ γῆς κτῆσιν καὶ οἰκίας χρυσίου τε καὶ ἀργύρου, τὼ δ᾽ αὖ, τὸ χρυσοῦν τε καὶ ἀργυροῦν, ἅτε οὐ πενομένω ἀλλὰ φύσει ὄντε πλουσίω, τὰς ψυχὰς ἐπὶ τὴν ἀρετὴν καὶ τὴν ἀρχαίαν κατάστασιν ἠγέτην: βιαζομένων δὲ καὶ ἀντιτεινόντων ἀλλήλοις, εἰς μέσον ὡμολόγησαν γῆν μὲν καὶ οἰκίας κατανειμαμένους","st":"547b"},{"sp":"N","t":"ἰδιώσασθαι, τοὺς δὲ πρὶν φυλαττομένους ὑπ᾽ αὐτῶν ὡς ἐλευθέρους φίλους τε καὶ τροφέας, δουλωσάμενοι τότε περιοίκους τε καὶ οἰκέτας ἔχοντες, αὐτοὶ πολέμου τε καὶ φυλακῆς αὐτῶν ἐπιμελεῖσθαι.","st":"547c"},{"sp":"N","t":"δοκεῖ μοι, ἔφη, αὕτη ἡ μετάβασις ἐντεῦθεν γίγνεσθαι.","st":"547c"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, ἐν μέσῳ τις ἂν εἴη ἀριστοκρατίας τε καὶ ὀλιγαρχίας αὕτη ἡ πολιτεία;","st":"547c"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"547c"},{"sp":"N","t":"μεταβήσεται μὲν δὴ οὕτω: μεταβᾶσα δὲ πῶς οἰκήσει; ἢ","st":"547c"},{"sp":"N","t":"φανερὸν ὅτι τὰ μὲν μιμήσεται τὴν προτέραν πολιτείαν, τὰ δὲ τὴν ὀλιγαρχίαν, ἅτ᾽ ἐν μέσῳ οὖσα, τὸ δέ τι καὶ αὑτῆς ἕξει ἴδιον;","st":"547d"},{"sp":"N","t":"οὕτως, ἔφη.","st":"547d"},{"sp":"N","t":"οὐκοῦν τῷ μὲν τιμᾶν τοὺς ἄρχοντας καὶ γεωργιῶν ἀπέχεσθαι τὸ προπολεμοῦν αὐτῆς καὶ χειροτεχνιῶν καὶ τοῦ ἄλλου χρηματισμοῦ, συσσίτια δὲ κατεσκευάσθαι καὶ γυμναστικῆς τε καὶ τῆς τοῦ πολέμου ἀγωνίας ἐπιμελεῖσθαι, πᾶσι τοῖς τοιούτοις τὴν προτέραν μιμήσεται;","st":"547d"},{"sp":"N","t":"ναί.","st":"547d"},{"sp":"N","t":"τῷ δέ γε φοβεῖσθαι τοὺς σοφοὺς ἐπὶ τὰς ἀρχὰς ἄγειν, ἅτε οὐκέτι κεκτημένην ἁπλοῦς τε καὶ ἀτενεῖς τοὺς τοιούτους ἄνδρας ἀλλὰ μεικτούς, ἐπὶ δὲ θυμοειδεῖς τε καὶ ἁπλουστέρους ἀποκλίνειν, τοὺς πρὸς πόλεμον μᾶλλον πεφυκότας ἢ πρὸς","st":"547e"},{"sp":"N","t":"εἰρήνην, καὶ τοὺς περὶ ταῦτα δόλους τε καὶ μηχανὰς ἐντίμως ἔχειν, καὶ πολεμοῦσα τὸν ἀεὶ χρόνον διάγειν, αὐτὴ ἑαυτῆς αὖ τὰ πολλὰ τῶν τοιούτων ἴδια ἕξει;","st":"548a"},{"sp":"N","t":"ναί.","st":"548a"},{"sp":"N","t":"ἐπιθυμηταὶ δέ γε, ἦν δ᾽ ἐγώ, χρημάτων οἱ τοιοῦτοι ἔσονται, ὥσπερ οἱ ἐν ταῖς ὀλιγαρχίαις, καὶ τιμῶντες ἀγρίως ὑπὸ σκότου χρυσόν τε καὶ ἄργυρον, ἅτε κεκτημένοι ταμιεῖα καὶ οἰκείους θησαυρούς, οἷ θέμενοι ἂν αὐτὰ κρύψειαν, καὶ αὖ περιβόλους οἰκήσεων, ἀτεχνῶς νεοττιὰς ἰδίας, ἐν αἷς","st":"548a"},{"sp":"N","t":"ἀναλίσκοντες γυναιξί τε καὶ οἷς ἐθέλοιεν ἄλλοις πολλὰ ἂν δαπανῷντο.","st":"548b"},{"sp":"N","t":"ἀληθέστατα, ἔφη.","st":"548b"},{"sp":"N","t":"οὐκοῦν καὶ φειδωλοὶ χρημάτων, ἅτε τιμῶντες καὶ οὐ φανερῶς κτώμενοι, φιλαναλωταὶ δὲ ἀλλοτρίων δι᾽ ἐπιθυμίαν, καὶ λάθρᾳ τὰς ἡδονὰς καρπούμενοι, ὥσπερ παῖδες πατέρα τὸν νόμον ἀποδιδράσκοντες, οὐχ ὑπὸ πειθοῦς ἀλλ᾽ ὑπὸ βίας πεπαιδευμένοι διὰ τὸ τῆς ἀληθινῆς Μούσης τῆς μετὰ λόγων","st":"548b"},{"sp":"N","t":"τε καὶ φιλοσοφίας ἠμεληκέναι καὶ πρεσβυτέρως γυμναστικὴν μουσικῆς τετιμηκέναι.","st":"548c"},{"sp":"N","t":"παντάπασιν, ἔφη, λέγεις μεμειγμένην πολιτείαν ἐκ κακοῦ τε καὶ ἀγαθοῦ.","st":"548c"},{"sp":"N","t":"μέμεικται γάρ, ἦν δ᾽ ἐγώ: διαφανέστατον δ᾽ ἐν αὐτῇ ἐστὶν ἕν τι μόνον ὑπὸ τοῦ θυμοειδοῦς κρατοῦντος, φιλονικίαι καὶ φιλοτιμίαι.","st":"548c"},{"sp":"N","t":"σφόδρα γε, ἦ δ᾽ ὅς.","st":"548c"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, αὕτη μὲν ἡ πολιτεία οὕτω γεγονυῖα καὶ τοιαύτη ἄν τις εἴη, ὡς λόγῳ σχῆμα πολιτείας ὑπογράψαντα","st":"548c"},{"sp":"N","t":"μὴ ἀκριβῶς ἀπεργάσασθαι διὰ τὸ ἐξαρκεῖν μὲν ἰδεῖν καὶ ἐκ τῆς ὑπογραφῆς τόν τε δικαιότατον καὶ τὸν ἀδικώτατον, ἀμήχανον δὲ μήκει ἔργον εἶναι πάσας μὲν πολιτείας, πάντα δὲ ἤθη μηδὲν παραλιπόντα διελθεῖν.","st":"548d"},{"sp":"N","t":"καὶ ὀρθῶς, ἔφη.","st":"548d"},{"sp":"N","t":"τίς οὖν ὁ κατὰ ταύτην τὴν πολιτείαν ἀνήρ; πῶς τε γενόμενος ποῖός τέ τις ὤν;","st":"548d"},{"sp":"N","t":"οἶμαι μέν, ἔφη ὁ Ἀδείμαντος, ἐγγύς τι αὐτὸν Γλαύκωνος τουτουὶ τείνειν ἕνεκά γε φιλονικίας.","st":"548d"},{"sp":"N","t":"ἴσως, ἦν δ᾽ ἐγώ, τοῦτό γε: ἀλλά μοι δοκεῖ τάδε οὐ κατὰ τοῦτον πεφυκέναι.","st":"548e"},{"sp":"N","t":"τὰ ποῖα;","st":"548e"},{"sp":"N","t":"αὐθαδέστερόν τε δεῖ αὐτόν, ἦν δ᾽ ἐγώ, εἶναι καὶ ὑποαμουσότερον, φιλόμουσον δέ, καὶ φιλήκοον μέν, ῥητορικὸν δ᾽","st":"548e"},{"sp":"N","t":"οὐδαμῶς. καὶ δούλοις μέν τις ἂν ἄγριος εἴη ὁ τοιοῦτος, οὐ καταφρονῶν δούλων, ὥσπερ ὁ ἱκανῶς πεπαιδευμένος, ἐλευθέροις δὲ ἥμερος, ἀρχόντων δὲ σφόδρα ὑπήκοος, φίλαρχος δὲ καὶ φιλότιμος, οὐκ ἀπὸ τοῦ λέγειν ἀξιῶν ἄρχειν οὐδ᾽ ἀπὸ τοιούτου οὐδενός, ἀλλ᾽ ἀπὸ ἔργων τῶν τε πολεμικῶν καὶ τῶν περὶ τὰ πολεμικά, φιλογυμναστής τέ τις ὢν καὶ φιλόθηρος.","st":"549a"},{"sp":"N","t":"ἔστι γάρ, ἔφη, τοῦτο τὸ ἦθος ἐκείνης τῆς πολιτείας.","st":"549a"},{"sp":"N","t":"οὐκοῦν καὶ χρημάτων, ἦν δ᾽ ἐγώ, ὁ τοιοῦτος νέος μὲν ὢν","st":"549a"},{"sp":"N","t":"καταφρονοῖ ἄν, ὅσῳ δὲ πρεσβύτερος γίγνοιτο, μᾶλλον ἀεὶ ἀσπάζοιτο ἂν τῷ τε μετέχειν τῆς τοῦ φιλοχρημάτου φύσεως καὶ μὴ εἶναι εἰλικρινὴς πρὸς ἀρετὴν διὰ τὸ ἀπολειφθῆναι τοῦ ἀρίστου φύλακος;","st":"549b"},{"sp":"N","t":"τίνος; ἦ δ᾽ ὃς ὁ Ἀδείμαντος.","st":"549b"},{"sp":"N","t":"λόγου, ἦν δ᾽ ἐγώ, μουσικῇ κεκραμένου: ὃς μόνος ἐγγενόμενος σωτὴρ ἀρετῆς διὰ βίου ἐνοικεῖ τῷ ἔχοντι.","st":"549b"},{"sp":"N","t":"καλῶς, ἔφη, λέγεις.","st":"549b"},{"sp":"N","t":"καὶ ἔστι μέν γ᾽, ἦν δ᾽ ἐγώ, τοιοῦτος ὁ τιμοκρατικὸς νεανίας, τῇ τοιαύτῃ πόλει ἐοικώς.","st":"549b"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"549c"},{"sp":"N","t":"γίγνεται δέ γ᾽, εἶπον, οὗτος ὧδέ πως: ἐνίοτε πατρὸς ἀγαθοῦ ὢν νέος ὑὸς ἐν πόλει οἰκοῦντος οὐκ εὖ πολιτευομένῃ, φεύγοντος τάς τε τιμὰς καὶ ἀρχὰς καὶ δίκας καὶ τὴν τοιαύτην πᾶσαν φιλοπραγμοσύνην καὶ ἐθέλοντος ἐλαττοῦσθαι ὥστε πράγματα μὴ ἔχειν- πῇ δή, ἔφη, γίγνεται;","st":"549c"},{"sp":"N","t":"ὅταν, ἦν δ᾽ ἐγώ, πρῶτον μὲν τῆς μητρὸς ἀκούῃ ἀχθομένης ὅτι οὐ τῶν ἀρχόντων αὐτῇ ὁ ἀνήρ ἐστιν, καὶ ἐλαττουμένης διὰ","st":"549c"},{"sp":"N","t":"ταῦτα ἐν ταῖς ἄλλαις γυναιξίν, ἔπειτα ὁρώσης μὴ σφόδρα περὶ χρήματα σπουδάζοντα μηδὲ μαχόμενον καὶ λοιδορούμενον ἰδίᾳ τε ἐν δικαστηρίοις καὶ δημοσίᾳ, ἀλλὰ ῥᾳθύμως πάντα τὰ τοιαῦτα φέροντα, καὶ ἑαυτῷ μὲν τὸν νοῦν προσέχοντα ἀεὶ αἰσθάνηται, ἑαυτὴν δὲ μήτε πάνυ τιμῶντα μήτε ἀτιμάζοντα, ἐξ ἁπάντων τούτων ἀχθομένης τε καὶ λεγούσης ὡς ἄνανδρός τε αὐτῷ ὁ πατὴρ καὶ λίαν ἀνειμένος, καὶ ἄλλα δὴ ὅσα καὶ","st":"549d"},{"sp":"N","t":"οἷα φιλοῦσιν αἱ γυναῖκες περὶ τῶν τοιούτων ὑμνεῖν.","st":"549e"},{"sp":"N","t":"καὶ μάλ᾽, ἔφη ὁ Ἀδείμαντος, πολλά τε καὶ ὅμοια ἑαυταῖς.","st":"549e"},{"sp":"N","t":"οἶσθα οὖν, ἦν δ᾽ ἐγώ, ὅτι καὶ οἱ οἰκέται τῶν τοιούτων ἐνίοτε λάθρᾳ πρὸς τοὺς ὑεῖς τοιαῦτα λέγουσιν, οἱ δοκοῦντες εὖνοι εἶναι, καὶ ἐάν τινα ἴδωσιν ἢ ὀφείλοντα χρήματα, ᾧ μὴ ἐπεξέρχεται ὁ πατήρ, ἤ τι ἄλλο ἀδικοῦντα, διακελεύονται ὅπως, ἐπειδὰν ἀνὴρ γένηται, τιμωρήσεται πάντας τοὺς τοιούτους","st":"549e"},{"sp":"N","t":"καὶ ἀνὴρ μᾶλλον ἔσται τοῦ πατρός. καὶ ἐξιὼν ἕτερα τοιαῦτα ἀκούει καὶ ὁρᾷ, τοὺς μὲν τὰ αὑτῶν πράττοντας ἐν τῇ πόλει ἠλιθίους τε καλουμένους καὶ ἐν σμικρῷ λόγῳ ὄντας, τοὺς δὲ μὴ τὰ αὑτῶν τιμωμένους τε καὶ ἐπαινουμένους. τότε δὴ ὁ νέος πάντα τὰ τοιαῦτα ἀκούων τε καὶ ὁρῶν, καὶ αὖ τοὺς τοῦ πατρὸς λόγους ἀκούων τε καὶ ὁρῶν τὰ ἐπιτηδεύματα αὐτοῦ ἐγγύθεν παρὰ τὰ τῶν ἄλλων, ἑλκόμενος ὑπ᾽ ἀμφοτέρων","st":"550a"},{"sp":"N","t":"τούτων, τοῦ μὲν πατρὸς αὐτοῦ τὸ λογιστικὸν ἐν τῇ ψυχῇ ἄρδοντός τε καὶ αὔξοντος, τῶν δὲ ἄλλων τό τε ἐπιθυμητικὸν καὶ τὸ θυμοειδές, διὰ τὸ μὴ κακοῦ ἀνδρὸς εἶναι τὴν φύσιν, ὁμιλίαις δὲ ταῖς τῶν ἄλλων κακαῖς κεχρῆσθαι, εἰς τὸ μέσον ἑλκόμενος ὑπ᾽ ἀμφοτέρων τούτων ἦλθε, καὶ τὴν ἐν ἑαυτῷ ἀρχὴν παρέδωκε τῷ μέσῳ τε καὶ φιλονίκῳ καὶ θυμοειδεῖ, καὶ ἐγένετο ὑψηλόφρων τε καὶ φιλότιμος ἀνήρ.","st":"550b"},{"sp":"N","t":"κομιδῇ μοι, ἔφη, δοκεῖς τὴν τούτου γένεσιν διεληλυθέναι.","st":"550b"},{"sp":"N","t":"ἔχομεν ἄρα, ἦν δ᾽ ἐγώ, τήν τε δευτέραν πολιτείαν καὶ τὸν δεύτερον ἄνδρα.","st":"550c"},{"sp":"N","t":"ἔχομεν, ἔφη.","st":"550c"},{"sp":"N","t":"οὐκοῦν μετὰ τοῦτο, τὸ τοῦ Αἰσχύλου, λέγωμεν, ““ἄλλον ἄλλῃ πρὸς πόλει τεταγμένον” “ μᾶλλον δὲ κατὰ τὴν ὑπόθεσιν προτέραν τὴν πόλιν;","st":"550c"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη.","st":"550c"},{"sp":"N","t":"εἴη δέ γ᾽ ἄν, ὡς ἐγᾦμαι, ὀλιγαρχία ἡ μετὰ τὴν τοιαύτην πολιτείαν.","st":"550c"},{"sp":"N","t":"λέγεις δέ, ἦ δ᾽ ὅς, τὴν ποίαν κατάστασιν ὀλιγαρχίαν;","st":"550c"},{"sp":"N","t":"τὴν ἀπὸ τιμημάτων, ἦν δ᾽ ἐγώ, πολιτείαν, ἐν ᾗ οἱ μὲν","st":"550c"},{"sp":"N","t":"πλούσιοι ἄρχουσιν, πένητι δὲ οὐ μέτεστιν ἀρχῆς.","st":"550d"},{"sp":"N","t":"μανθάνω, ἦ δ᾽ ὅς.","st":"550d"},{"sp":"N","t":"οὐκοῦν ὡς μεταβαίνει πρῶτον ἐκ τῆς τιμαρχίας εἰς τὴν ὀλιγαρχίαν, ῥητέον;","st":"550d"},{"sp":"N","t":"ναί.","st":"550d"},{"sp":"N","t":"καὶ μήν, ἦν δ᾽ ἐγώ, καὶ τυφλῷ γε δῆλον ὡς μεταβαίνει.","st":"550d"},{"sp":"N","t":"πῶς;","st":"550d"},{"sp":"N","t":"τὸ ταμιεῖον, ἦν δ᾽ ἐγώ, ἐκεῖνο ἑκάστῳ χρυσίου πληρούμενον ἀπόλλυσι τὴν τοιαύτην πολιτείαν. πρῶτον μὲν γὰρ δαπάνας αὑτοῖς ἐξευρίσκουσιν, καὶ τοὺς νόμους ἐπὶ τοῦτο παράγουσιν, ἀπειθοῦντες αὐτοί τε καὶ γυναῖκες αὐτῶν.","st":"550d"},{"sp":"N","t":"εἰκός, ἔφη.","st":"550d"},{"sp":"N","t":"ἔπειτά γε οἶμαι ἄλλος ἄλλον ὁρῶν καὶ εἰς ζῆλον ἰὼν τὸ πλῆθος τοιοῦτον αὑτῶν ἀπηργάσαντο.","st":"550e"},{"sp":"N","t":"εἰκός.","st":"550e"},{"sp":"N","t":"τοὐντεῦθεν τοίνυν, εἶπον, προϊόντες εἰς τὸ πρόσθεν τοῦ χρηματίζεσθαι, ὅσῳ ἂν τοῦτο τιμιώτερον ἡγῶνται, τοσούτῳ ἀρετὴν ἀτιμοτέραν. ἢ οὐχ οὕτω πλούτου ἀρετὴ διέστηκεν, ὥσπερ ἐν πλάστιγγι ζυγοῦ κειμένου ἑκατέρου, ἀεὶ τοὐναντίον ῥέποντε;","st":"550e"},{"sp":"N","t":"καὶ μάλ᾽, ἔφη.","st":"550e"},{"sp":"N","t":"τιμωμένου δὴ πλούτου ἐν πόλει καὶ τῶν πλουσίων ἀτιμοτέρα ἀρετή τε καὶ οἱ ἀγαθοί.","st":"551a"},{"sp":"N","t":"δῆλον.","st":"551a"},{"sp":"N","t":"ἀσκεῖται δὴ τὸ ἀεὶ τιμώμενον, ἀμελεῖται δὲ τὸ ἀτιμαζόμενον.","st":"551a"},{"sp":"N","t":"οὕτω.","st":"551a"},{"sp":"N","t":"ἀντὶ δὴ φιλονίκων καὶ φιλοτίμων ἀνδρῶν φιλοχρηματισταὶ καὶ φιλοχρήματοι τελευτῶντες ἐγένοντο, καὶ τὸν μὲν πλούσιον ἐπαινοῦσίν τε καὶ θαυμάζουσι καὶ εἰς τὰς ἀρχὰς ἄγουσι, τὸν δὲ πένητα ἀτιμάζουσι.","st":"551a"},{"sp":"N","t":"πάνυ γε.","st":"551a"},{"sp":"N","t":"οὐκοῦν τότε δὴ νόμον τίθενται ὅρον πολιτείας ὀλιγαρχικῆς","st":"551a"},{"sp":"N","t":"ταξάμενοι πλῆθος χρημάτων, οὗ μὲν μᾶλλον ὀλιγαρχία, πλέον, οὗ δ᾽ ἧττον, ἔλαττον, προειπόντες ἀρχῶν μὴ μετέχειν ᾧ ἂν μὴ ᾖ οὐσία εἰς τὸ ταχθὲν τίμημα, ταῦτα δὲ ἢ βίᾳ μεθ᾽ ὅπλων διαπράττονται, ἢ καὶ πρὸ τούτου φοβήσαντες κατεστήσαντο τὴν τοιαύτην πολιτείαν. ἢ οὐχ οὕτως;","st":"551b"},{"sp":"N","t":"οὕτω μὲν οὖν.","st":"551b"},{"sp":"N","t":"ἡ μὲν δὴ κατάστασις ὡς ἔπος εἰπεῖν αὕτη.","st":"551b"},{"sp":"N","t":"ναί, ἔφη: ἀλλὰ τίς δὴ ὁ τρόπος τῆς πολιτείας; καὶ ποῖά","st":"551b"},{"sp":"N","t":"ἐστιν ἃ ἔφαμεν αὐτὴν ἁμαρτήματα ἔχειν;","st":"551c"},{"sp":"N","t":"πρῶτον μέν, ἔφην, τοῦτο αὐτό, ὅρος αὐτῆς οἷός ἐστιν. ἄθρει γάρ, εἰ νεῶν οὕτω τις ποιοῖτο κυβερνήτας, ἀπὸ τιμημάτων, τῷ δὲ πένητι, εἰ καὶ κυβερνητικώτερος εἴη, μὴ ἐπιτρέποι-","st":"551c"},{"sp":"N","t":"πονηράν, ἦ δ᾽ ὅς, τὴν ναυτιλίαν αὐτοὺς ναυτίλλεσθαι.","st":"551c"},{"sp":"N","t":"οὐκοῦν καὶ περὶ ἄλλου οὕτως ὁτουοῦν [ἤ τινος] ἀρχῆς;","st":"551c"},{"sp":"N","t":"οἶμαι ἔγωγε.","st":"551c"},{"sp":"N","t":"πλὴν πόλεως; ἦν δ᾽ ἐγώ: ἢ καὶ πόλεως πέρι;","st":"551c"},{"sp":"N","t":"πολύ γ᾽, ἔφη, μάλιστα, ὅσῳ χαλεπωτάτη καὶ μεγίστη ἡ ἀρχή.","st":"551c"},{"sp":"N","t":"ἓν μὲν δὴ τοῦτο τοσοῦτον ὀλιγαρχία ἂν ἔχοι ἁμάρτημα.","st":"551d"},{"sp":"N","t":"φαίνεται.","st":"551d"},{"sp":"N","t":"τί δέ; τόδε ἆρά τι τούτου ἔλαττον;","st":"551d"},{"sp":"N","t":"τὸ ποῖον;","st":"551d"},{"sp":"N","t":"τὸ μὴ μίαν ἀλλὰ δύο ἀνάγκῃ εἶναι τὴν τοιαύτην πόλιν, τὴν μὲν πενήτων, τὴν δὲ πλουσίων, οἰκοῦντας ἐν τῷ αὐτῷ, ἀεὶ ἐπιβουλεύοντας ἀλλήλοις.","st":"551d"},{"sp":"N","t":"οὐδὲν μὰ Δί᾽, ἔφη, ἔλαττον.","st":"551d"},{"sp":"N","t":"ἀλλὰ μὴν οὐδὲ τόδε καλόν, τὸ ἀδυνάτους εἶναι ἴσως πόλεμόν τινα πολεμεῖν διὰ τὸ ἀναγκάζεσθαι ἢ χρωμένους","st":"551d"},{"sp":"N","t":"τῷ πλήθει ὡπλισμένῳ δεδιέναι μᾶλλον ἢ τοὺς πολεμίους, ἢ μὴ χρωμένους ὡς ἀληθῶς ὀλιγαρχικοὺς φανῆναι ἐν αὐτῷ τῷ μάχεσθαι, καὶ ἅμα χρήματα μὴ ἐθέλειν εἰσφέρειν, ἅτε φιλοχρημάτους.","st":"551e"},{"sp":"N","t":"οὐ καλόν.","st":"551e"},{"sp":"N","t":"τί δέ; ὃ πάλαι ἐλοιδοροῦμεν, τὸ πολυπραγμονεῖν γεωργοῦντας","st":"551e"},{"sp":"N","t":"καὶ χρηματιζομένους καὶ πολεμοῦντας ἅμα τοὺς αὐτοὺς ἐν τῇ τοιαύτῃ πολιτείᾳ, ἦ δοκεῖ ὀρθῶς ἔχειν;","st":"552a"},{"sp":"N","t":"οὐδ᾽ ὁπωστιοῦν.","st":"552a"},{"sp":"N","t":"ὅρα δή, τούτων πάντων τῶν κακῶν εἰ τόδε μέγιστον αὕτη πρώτη παραδέχεται.","st":"552a"},{"sp":"N","t":"τὸ ποῖον;","st":"552a"},{"sp":"N","t":"τὸ ἐξεῖναι πάντα τὰ αὑτοῦ ἀποδόσθαι, καὶ ἄλλῳ κτήσασθαι τὰ τούτου, καὶ ἀποδόμενον οἰκεῖν ἐν τῇ πόλει μηδὲν ὄντα τῶν τῆς πόλεως μερῶν, μήτε χρηματιστὴν μήτε δημιουργὸν μήτε ἱππέα μήτε ὁπλίτην, ἀλλὰ πένητα καὶ ἄπορον κεκλημένον.","st":"552a"},{"sp":"N","t":"πρώτη, ἔφη.","st":"552b"},{"sp":"N","t":"οὔκουν διακωλύεταί γε ἐν ταῖς ὀλιγαρχουμέναις τὸ τοιοῦτον: οὐ γὰρ ἂν οἱ μὲν ὑπέρπλουτοι ἦσαν, οἱ δὲ παντάπασι πένητες.","st":"552b"},{"sp":"N","t":"ὀρθῶς.","st":"552b"},{"sp":"N","t":"τόδε δὲ ἄθρει: ἆρα ὅτε πλούσιος ὢν ἀνήλισκεν ὁ τοιοῦτος, μᾶλλόν τι τότ᾽ ἦν ὄφελος τῇ πόλει εἰς ἃ νυνδὴ ἐλέγομεν; ἢ ἐδόκει μὲν τῶν ἀρχόντων εἶναι, τῇ δὲ ἀληθείᾳ οὔτε ἄρχων οὔτε ὑπηρέτης ἦν αὐτῆς, ἀλλὰ τῶν ἑτοίμων ἀναλωτής;","st":"552b"},{"sp":"N","t":"οὕτως, ἔφη: ἐδόκει, ἦν δὲ οὐδὲν ἄλλο ἢ ἀναλωτής.","st":"552c"},{"sp":"N","t":"βούλει οὖν, ἦν δ᾽ ἐγώ, φῶμεν αὐτόν, ὡς ἐν κηρίῳ κηφὴν ἐγγίγνεται, σμήνους νόσημα, οὕτω καὶ τὸν τοιοῦτον ἐν οἰκίᾳ κηφῆνα ἐγγίγνεσθαι, νόσημα πόλεως;","st":"552c"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη, ὦ Σώκρατες.","st":"552c"},{"sp":"N","t":"οὐκοῦν, ὦ Ἀδείμαντε, τοὺς μὲν πτηνοὺς κηφῆνας πάντας ἀκέντρους ὁ θεὸς πεποίηκεν, τοὺς δὲ πεζοὺς τούτους ἐνίους μὲν αὐτῶν ἀκέντρους, ἐνίους δὲ δεινὰ κέντρα ἔχοντας; καὶ ἐκ μὲν τῶν ἀκέντρων πτωχοὶ πρὸς τὸ γῆρας τελευτῶσιν, ἐκ δὲ","st":"552c"},{"sp":"N","t":"τῶν κεκεντρωμένων πάντες ὅσοι κέκληνται κακοῦργοι;","st":"552d"},{"sp":"N","t":"ἀληθέστατα, ἔφη.","st":"552d"},{"sp":"N","t":"δῆλον ἄρα, ἦν δ᾽ ἐγώ, ἐν πόλει οὗ ἂν ἴδῃς πτωχούς, ὅτι εἰσί που ἐν τούτῳ τῷ τόπῳ ἀποκεκρυμμένοι κλέπται τε καὶ βαλλαντιατόμοι καὶ ἱερόσυλοι καὶ πάντων τῶν τοιούτων κακῶν δημιουργοί.","st":"552d"},{"sp":"N","t":"δῆλον, ἔφη.","st":"552d"},{"sp":"N","t":"τί οὖν; ἐν ταῖς ὀλιγαρχουμέναις πόλεσι πτωχοὺς οὐχ ὁρᾷς ἐνόντας;","st":"552d"},{"sp":"N","t":"ὀλίγου γ᾽, ἔφη, πάντας τοὺς ἐκτὸς τῶν ἀρχόντων.","st":"552d"},{"sp":"N","t":"μὴ οὖν οἰόμεθα, ἔφην ἐγώ, καὶ κακούργους πολλοὺς ἐν αὐταῖς εἶναι κέντρα ἔχοντας, οὓς ἐπιμελείᾳ βίᾳ κατέχουσιν αἱ ἀρχαί;","st":"552e"},{"sp":"N","t":"οἰόμεθα μὲν οὖν, ἔφη.","st":"552e"},{"sp":"N","t":"ἆρ᾽ οὖν οὐ δι᾽ ἀπαιδευσίαν καὶ κακὴν τροφὴν καὶ κατάστασιν τῆς πολιτείας φήσομεν τοὺς τοιούτους αὐτόθι ἐγγίγνεσθαι;","st":"552e"},{"sp":"N","t":"φήσομεν.","st":"552e"},{"sp":"N","t":"ἀλλ᾽ οὖν δὴ τοιαύτη γέ τις ἂν εἴη ἡ ὀλιγαρχουμένη πόλις καὶ τοσαῦτα κακὰ ἔχουσα, ἴσως δὲ καὶ πλείω.","st":"552e"},{"sp":"N","t":"σχεδόν τι, ἔφη.","st":"552e"},{"sp":"N","t":"ἀπειργάσθω δὴ ἡμῖν καὶ αὕτη, ἦν δ᾽ ἐγώ, ἡ πολιτεία, ἣν ὀλιγαρχίαν καλοῦσιν, ἐκ τιμημάτων ἔχουσα τοὺς ἄρχοντας: τὸν δὲ ταύτῃ ὅμοιον μετὰ ταῦτα σκοπῶμεν, ὥς τε γίγνεται οἷός τε γενόμενός ἐστιν.","st":"553a"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη.","st":"553a"},{"sp":"N","t":"ἆρ᾽ οὖν ὧδε μάλιστα εἰς ὀλιγαρχικὸν ἐκ τοῦ τιμοκρατικοῦ ἐκείνου μεταβάλλει;","st":"553a"},{"sp":"N","t":"πῶς;","st":"553a"},{"sp":"N","t":"ὅταν αὐτοῦ παῖς γενόμενος τὸ μὲν πρῶτον ζηλοῖ τε τὸν πατέρα καὶ τὰ ἐκείνου ἴχνη διώκῃ, ἔπειτα αὐτὸν ἴδῃ ἐξαίφνης","st":"553a"},{"sp":"N","t":"πταίσαντα ὥσπερ πρὸς ἕρματι πρὸς τῇ πόλει, καὶ ἐκχέαντα τά τε αὑτοῦ καὶ ἑαυτόν, ἢ στρατηγήσαντα ἤ τιν᾽ ἄλλην μεγάλην ἀρχὴν ἄρξαντα, εἶτα εἰς δικαστήριον ἐμπεσόντα [βλαπτόμενον] ὑπὸ συκοφαντῶν ἢ ἀποθανόντα ἢ ἐκπεσόντα ἢ ἀτιμωθέντα καὶ τὴν οὐσίαν ἅπασαν ἀποβαλόντα.","st":"553b"},{"sp":"N","t":"εἰκός γ᾽, ἔφη.","st":"553b"},{"sp":"N","t":"ἰδὼν δέ γε, ὦ φίλε, ταῦτα καὶ παθὼν καὶ ἀπολέσας τὰ ὄντα, δείσας οἶμαι εὐθὺς ἐπὶ κεφαλὴν ὠθεῖ ἐκ τοῦ θρόνου","st":"553b"},{"sp":"N","t":"τοῦ ἐν τῇ ἑαυτοῦ ψυχῇ φιλοτιμίαν τε καὶ τὸ θυμοειδὲς ἐκεῖνο, καὶ ταπεινωθεὶς ὑπὸ πενίας πρὸς χρηματισμὸν τραπόμενος γλίσχρως καὶ κατὰ σμικρὸν φειδόμενος καὶ ἐργαζόμενος χρήματα συλλέγεται. ἆρ᾽ οὐκ οἴει τὸν τοιοῦτον τότε εἰς μὲν τὸν θρόνον ἐκεῖνον τὸ ἐπιθυμητικόν τε καὶ φιλοχρήματον ἐγκαθίζειν καὶ μέγαν βασιλέα ποιεῖν ἐν ἑαυτῷ, τιάρας τε καὶ στρεπτοὺς καὶ ἀκινάκας παραζωννύντα;","st":"553c"},{"sp":"N","t":"ἔγωγ᾽, ἔφη.","st":"553c"},{"sp":"N","t":"τὸ δέ γε οἶμαι λογιστικόν τε καὶ θυμοειδὲς χαμαὶ ἔνθεν καὶ ἔνθεν παρακαθίσας ὑπ᾽ ἐκείνῳ καὶ καταδουλωσάμενος, τὸ μὲν οὐδὲν ἄλλο ἐᾷ λογίζεσθαι οὐδὲ σκοπεῖν ἀλλ᾽ ἢ ὁπόθεν ἐξ ἐλαττόνων χρημάτων πλείω ἔσται, τὸ δὲ αὖ θαυμάζειν καὶ τιμᾶν μηδὲν ἄλλο ἢ πλοῦτόν τε καὶ πλουσίους, καὶ φιλοτιμεῖσθαι μηδ᾽ ἐφ᾽ ἑνὶ ἄλλῳ ἢ ἐπὶ χρημάτων κτήσει καὶ ἐάν τι ἄλλο εἰς τοῦτο φέρῃ.","st":"553d"},{"sp":"N","t":"οὐκ ἔστ᾽ ἄλλη, ἔφη, μεταβολὴ οὕτω ταχεῖά τε καὶ ἰσχυρὰ ἐκ φιλοτίμου νέου εἰς φιλοχρήματον.","st":"553d"},{"sp":"N","t":"ἆρ᾽ οὖν οὗτος, ἦν δ᾽ ἐγώ, ὀλιγαρχικός ἐστιν;","st":"553e"},{"sp":"N","t":"ἡ γοῦν μεταβολὴ αὐτοῦ ἐξ ὁμοίου ἀνδρός ἐστι τῇ πολιτείᾳ, ἐξ ἧς ἡ ὀλιγαρχία μετέστη.","st":"553e"},{"sp":"N","t":"σκοπῶμεν δὴ εἰ ὅμοιος ἂν εἴη.","st":"553e"},{"sp":"N","t":"σκοπῶμεν.","st":"554a"},{"sp":"N","t":"οὐκοῦν πρῶτον μὲν τῷ χρήματα περὶ πλείστου ποιεῖσθαι ὅμοιος ἂν εἴη;","st":"554a"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"554a"},{"sp":"N","t":"καὶ μὴν τῷ γε φειδωλὸς εἶναι καὶ ἐργάτης, τὰς ἀναγκαίους ἐπιθυμίας μόνον τῶν παρ᾽ αὑτῷ ἀποπιμπλάς, τὰ δὲ ἄλλα ἀναλώματα μὴ παρεχόμενος, ἀλλὰ δουλούμενος τὰς ἄλλας ἐπιθυμίας ὡς ματαίους.","st":"554a"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"554a"},{"sp":"N","t":"αὐχμηρός γέ τις, ἦν δ᾽ ἐγώ, ὢν καὶ ἀπὸ παντὸς περιουσίαν ποιούμενος, θησαυροποιὸς ἀνήρ — οὓς δὴ καὶ ἐπαινεῖ τὸ πλῆθος","st":"554a"},{"sp":"N","t":"-ἢ οὐχ οὗτος ἂν εἴη ὁ τῇ τοιαύτῃ πολιτείᾳ ὅμοιος;","st":"554b"},{"sp":"N","t":"ἐμοὶ γοῦν, ἔφη, δοκεῖ: χρήματα γοῦν μάλιστα ἔντιμα τῇ τε πόλει καὶ παρὰ τῷ τοιούτῳ.","st":"554b"},{"sp":"N","t":"οὐ γὰρ οἶμαι, ἦν δ᾽ ἐγώ, παιδείᾳ ὁ τοιοῦτος προσέσχηκεν.","st":"554b"},{"sp":"N","t":"οὐ δοκῶ, ἔφη: οὐ γὰρ ἂν τυφλὸν ἡγεμόνα τοῦ χοροῦ ἐστήσατο καὶ ἐτί⟨μα⟩ μάλιστα.","st":"554b"},{"sp":"N","t":"εὖ, ἦν δ᾽ ἐγώ. τόδε δὲ σκόπει: κηφηνώδεις ἐπιθυμίας ἐν αὐτῷ διὰ τὴν ἀπαιδευσίαν μὴ φῶμεν ἐγγίγνεσθαι, τὰς μὲν","st":"554b"},{"sp":"N","t":"πτωχικάς, τὰς δὲ κακούργους, κατεχομένας βίᾳ ὑπὸ τῆς ἄλλης ἐπιμελείας;","st":"554c"},{"sp":"N","t":"καὶ μάλ᾽, ἔφη.","st":"554c"},{"sp":"N","t":"οἶσθ᾽ οὖν, εἶπον, οἷ ἀποβλέψας κατόψει αὐτῶν τὰς κακουργίας;","st":"554c"},{"sp":"N","t":"ποῖ; ἔφη.","st":"554c"},{"sp":"N","t":"εἰς τὰς τῶν ὀρφανῶν ἐπιτροπεύσεις, καὶ εἴ πού τι αὐτοῖς τοιοῦτον συμβαίνει, ὥστε πολλῆς ἐξουσίας λαβέσθαι τοῦ ἀδικεῖν.","st":"554c"},{"sp":"N","t":"ἀληθῆ.","st":"554c"},{"sp":"N","t":"ἆρ᾽ οὖν οὐ τούτῳ δῆλον ὅτι ἐν τοῖς ἄλλοις συμβολαίοις ὁ τοιοῦτος, ἐν οἷς εὐδοκιμεῖ δοκῶν δίκαιος εἶναι, ἐπιεικεῖ","st":"554c"},{"sp":"N","t":"τινὶ ἑαυτοῦ βίᾳ κατέχει ἄλλας κακὰς ἐπιθυμίας ἐνούσας, οὐ πείθων ὅτι οὐκ ἄμεινον, οὐδ᾽ ἡμερῶν λόγῳ, ἀλλ᾽ ἀνάγκῃ καὶ φόβῳ, περὶ τῆς ἄλλης οὐσίας τρέμων;","st":"554d"},{"sp":"N","t":"καὶ πάνυ γ᾽, ἔφη.","st":"554d"},{"sp":"N","t":"καὶ νὴ Δία, ἦν δ᾽ ἐγώ, ὦ φίλε, τοῖς πολλοῖς γε αὐτῶν ἐνευρήσεις, ὅταν δέῃ τἀλλότρια ἀναλίσκειν, τὰς τοῦ κηφῆνος συγγενεῖς ἐνούσας ἐπιθυμίας.","st":"554d"},{"sp":"N","t":"καὶ μάλα, ἦ δ᾽ ὅς, σφόδρα.","st":"554d"},{"sp":"N","t":"οὐκ ἄρ᾽ ἂν εἴη ἀστασίαστος ὁ τοιοῦτος ἐν ἑαυτῷ, οὐδὲ εἷς ἀλλὰ διπλοῦς τις, ἐπιθυμίας δὲ ἐπιθυμιῶν ὡς τὸ πολὺ","st":"554d"},{"sp":"N","t":"κρατούσας ἂν ἔχοι βελτίους χειρόνων.","st":"554e"},{"sp":"N","t":"ἔστιν οὕτω.","st":"554e"},{"sp":"N","t":"διὰ ταῦτα δὴ οἶμαι εὐσχημονέστερος ἂν πολλῶν ὁ τοιοῦτος εἴη: ὁμονοητικῆς δὲ καὶ ἡρμοσμένης τῆς ψυχῆς ἀληθὴς ἀρετὴ πόρρω ποι ἐκφεύγοι ἂν αὐτόν.","st":"554e"},{"sp":"N","t":"δοκεῖ μοι.","st":"554e"},{"sp":"N","t":"καὶ μὴν ἀνταγωνιστής γε ἰδίᾳ ἐν πόλει ὁ φειδωλὸς","st":"554e"},{"sp":"N","t":"φαῦλος ἤ τινος νίκης ἢ ἄλλης φιλοτιμίας τῶν καλῶν, χρήματά τε οὐκ ἐθέλων εὐδοξίας ἕνεκα καὶ τῶν τοιούτων ἀγώνων ἀναλίσκειν, δεδιὼς τὰς ἐπιθυμίας τὰς ἀναλωτικὰς ἐγείρειν καὶ συμπαρακαλεῖν ἐπὶ συμμαχίαν τε καὶ φιλονικίαν, ὀλίγοις τισὶν ἑαυτοῦ πολεμῶν ὀλιγαρχικῶς τὰ πολλὰ ἡττᾶται καὶ πλουτεῖ.","st":"555a"},{"sp":"N","t":"καὶ μάλα, ἔφη.","st":"555a"},{"sp":"N","t":"ἔτι οὖν, ἦν δ᾽ ἐγώ, ἀπιστοῦμεν μὴ κατὰ τὴν ὀλιγαρχουμένην πόλιν ὁμοιότητι τὸν φειδωλόν τε καὶ χρηματιστὴν","st":"555a"},{"sp":"N","t":"τετάχθαι;","st":"555b"},{"sp":"N","t":"οὐδαμῶς, ἔφη.","st":"555b"},{"sp":"N","t":"δημοκρατίαν δή, ὡς ἔοικε, μετὰ τοῦτο σκεπτέον, τίνα τε γίγνεται τρόπον, γενομένη τε ποῖόν τινα ἔχει, ἵν᾽ αὖ τὸν τοῦ τοιούτου ἀνδρὸς τρόπον γνόντες παραστησώμεθ᾽ αὐτὸν εἰς κρίσιν.","st":"555b"},{"sp":"N","t":"ὁμοίως γοῦν ἄν, ἔφη, ἡμῖν αὐτοῖς πορευοίμεθα.","st":"555b"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, μεταβάλλει μὲν τρόπον τινὰ τοιόνδε ἐξ ὀλιγαρχίας εἰς δημοκρατίαν, δι᾽ ἀπληστίαν τοῦ προκειμένου ἀγαθοῦ, τοῦ ὡς πλουσιώτατον δεῖν γίγνεσθαι;","st":"555b"},{"sp":"N","t":"πῶς δή;","st":"555b"},{"sp":"N","t":"ἅτε οἶμαι ἄρχοντες ἐν αὐτῇ οἱ ἄρχοντες διὰ τὸ πολλὰ κεκτῆσθαι, οὐκ ἐθέλουσιν εἴργειν νόμῳ τῶν νέων ὅσοι ἂν ἀκόλαστοι γίγνωνται, μὴ ἐξεῖναι αὐτοῖς ἀναλίσκειν τε καὶ ἀπολλύναι τὰ αὑτῶν, ἵνα ὠνούμενοι τὰ τῶν τοιούτων καὶ εἰσδανείζοντες ἔτι πλουσιώτεροι καὶ ἐντιμότεροι γίγνωνται.","st":"555c"},{"sp":"N","t":"παντός γε μᾶλλον.","st":"555c"},{"sp":"N","t":"οὐκοῦν δῆλον ἤδη τοῦτο ἐν πόλει, ὅτι πλοῦτον τιμᾶν καὶ σωφροσύνην ἅμα ἱκανῶς κτᾶσθαι ἐν τοῖς πολίταις","st":"555c"},{"sp":"N","t":"ἀδύνατον, ἀλλ᾽ ἀνάγκη ἢ τοῦ ἑτέρου ἀμελεῖν ἢ τοῦ ἑτέρου;","st":"555d"},{"sp":"N","t":"ἐπιεικῶς, ἔφη, δῆλον.","st":"555d"},{"sp":"N","t":"παραμελοῦντες δὴ ἐν ταῖς ὀλιγαρχίαις καὶ ἐφιέντες ἀκολασταίνειν οὐκ ἀγεννεῖς ἐνίοτε ἀνθρώπους πένητας ἠνάγκασαν γενέσθαι.","st":"555d"},{"sp":"N","t":"μάλα γε.","st":"555d"},{"sp":"N","t":"κάθηνται δὴ οἶμαι οὗτοι ἐν τῇ πόλει κεκεντρωμένοι τε καὶ ἐξωπλισμένοι, οἱ μὲν ὀφείλοντες χρέα, οἱ δὲ ἄτιμοι γεγονότες, οἱ δὲ ἀμφότερα, μισοῦντές τε καὶ ἐπιβουλεύοντες τοῖς κτησαμένοις τὰ αὑτῶν καὶ τοῖς ἄλλοις, νεωτερισμοῦ","st":"555d"},{"sp":"N","t":"ἐρῶντες.","st":"555e"},{"sp":"N","t":"ἔστι ταῦτα.","st":"555e"},{"sp":"N","t":"οἱ δὲ δὴ χρηματισταὶ ἐγκύψαντες, οὐδὲ δοκοῦντες τούτους ὁρᾶν, τῶν λοιπῶν τὸν ἀεὶ ὑπείκοντα ἐνιέντες ἀργύριον τιτρώσκοντες, καὶ τοῦ πατρὸς ἐκγόνους τόκους πολλαπλασίους","st":"555e"},{"sp":"N","t":"κομιζόμενοι, πολὺν τὸν κηφῆνα καὶ πτωχὸν ἐμποιοῦσι τῇ πόλει.","st":"556a"},{"sp":"N","t":"πῶς γάρ, ἔφη, οὐ πολύν; καὶ οὔτε γ᾽ ἐκείνῃ, ἦν δ᾽ ἐγώ, τὸ τοιοῦτον κακὸν ἐκκαόμενον ἐθέλουσιν ἀποσβεννύναι, εἴργοντες τὰ αὑτοῦ ὅπῃ τις βούλεται τρέπειν, οὔτε τῇδε, ᾗ αὖ κατὰ ἕτερον νόμον τὰ τοιαῦτα λύεται.","st":"556a"},{"sp":"N","t":"κατὰ δὴ τίνα;","st":"556a"},{"sp":"N","t":"ὃς μετ᾽ ἐκεῖνόν ἐστι δεύτερος καὶ ἀναγκάζων ἀρετῆς ἐπιμελεῖσθαι τοὺς πολίτας. ἐὰν γὰρ ἐπὶ τῷ αὑτοῦ κινδύνῳ","st":"556a"},{"sp":"N","t":"τὰ πολλά τις τῶν ἑκουσίων συμβολαίων προστάττῃ συμβάλλειν, χρηματίζοιντο μὲν ἂν ἧττον ἀναιδῶς ἐν τῇ πόλει, ἐλάττω δ᾽ ἐν αὐτῇ φύοιτο τῶν τοιούτων κακῶν οἵων νυνδὴ εἴπομεν.","st":"556b"},{"sp":"N","t":"καὶ πολύ γε, ἦ δ᾽ ὅς.","st":"556b"},{"sp":"N","t":"νῦν δέ γ᾽, ἔφην ἐγώ, διὰ πάντα τὰ τοιαῦτα τοὺς μὲν δὴ ἀρχομένους οὕτω διατιθέασιν ἐν τῇ πόλει οἱ ἄρχοντες: σφᾶς δὲ αὐτοὺς καὶ τοὺς αὑτῶν — ἆρ᾽ οὐ τρυφῶντας μὲν τοὺς νέους καὶ ἀπόνους καὶ πρὸς τὰ τοῦ σώματος καὶ πρὸς","st":"556b"},{"sp":"N","t":"τὰ τῆς ψυχῆς, μαλακοὺς δὲ καρτερεῖν πρὸς ἡδονάς τε καὶ λύπας καὶ ἀργούς;","st":"556c"},{"sp":"N","t":"τί μήν;","st":"556c"},{"sp":"N","t":"αὑτοὺς δὲ πλὴν χρηματισμοῦ τῶν ἄλλων ἠμεληκότας, καὶ οὐδὲν πλείω ἐπιμέλειαν πεποιημένους ἀρετῆς ἢ τοὺς πένητας;","st":"556c"},{"sp":"N","t":"οὐ γὰρ οὖν.","st":"556c"},{"sp":"N","t":"οὕτω δὴ παρεσκευασμένοι ὅταν παραβάλλωσιν ἀλλήλοις οἵ τε ἄρχοντες καὶ οἱ ἀρχόμενοι ἢ ἐν ὁδῶν πορείαις ἢ ἐν ἄλλαις τισὶ κοινωνίαις, ἢ κατὰ θεωρίας ἢ κατὰ στρατείας, ἢ σύμπλοι γιγνόμενοι ἢ συστρατιῶται, ἢ καὶ ἐν αὐτοῖς τοῖς","st":"556c"},{"sp":"N","t":"κινδύνοις ἀλλήλους θεώμενοι μηδαμῇ ταύτῃ καταφρονῶνται οἱ πένητες ὑπὸ τῶν πλουσίων, ἀλλὰ πολλάκις ἰσχνὸς ἀνὴρ πένης, ἡλιωμένος, παραταχθεὶς ἐν μάχῃ πλουσίῳ ἐσκιατροφηκότι, πολλὰς ἔχοντι σάρκας ἀλλοτρίας, ἴδῃ ἄσθματός τε καὶ ἀπορίας μεστόν, ἆρ᾽ οἴει αὐτὸν οὐχ ἡγεῖσθαι κακίᾳ τῇ σφετέρᾳ πλουτεῖν τοὺς τοιούτους, καὶ ἄλλον ἄλλῳ παραγγέλλειν, ὅταν ἰδίᾳ συγγίγνωνται, ὅτι “ἇνδρες ἡμέτεροι:","st":"556d"},{"sp":"N","t":"εἰσὶ γὰρ οὐδέν;”","st":"556e"},{"sp":"N","t":"εὖ οἶδα μὲν οὖν, ἔφη, ἔγωγε, ὅτι οὕτω ποιοῦσιν.","st":"556e"},{"sp":"N","t":"οὐκοῦν ὥσπερ σῶμα νοσῶδες μικρᾶς ῥοπῆς ἔξωθεν δεῖται προσλαβέσθαι πρὸς τὸ κάμνειν, ἐνίοτε δὲ καὶ ἄνευ τῶν ἔξω στασιάζει αὐτὸ αὑτῷ, οὕτω δὴ καὶ ἡ κατὰ ταὐτὰ ἐκείνῳ διακειμένη πόλις ἀπὸ σμικρᾶς προφάσεως, ἔξωθεν ἐπαγομένων ἢ τῶν ἑτέρων ἐξ ὀλιγαρχουμένης πόλεως συμμαχίαν ἢ τῶν ἑτέρων ἐκ δημοκρατουμένης, νοσεῖ τε καὶ αὐτὴ αὑτῇ μάχεται, ἐνίοτε δὲ καὶ ἄνευ τῶν ἔξω στασιάζει;","st":"556e"},{"sp":"N","t":"καὶ σφόδρα γε.","st":"557a"},{"sp":"N","t":"δημοκρατία δὴ οἶμαι γίγνεται ὅταν οἱ πένητες νικήσαντες τοὺς μὲν ἀποκτείνωσι τῶν ἑτέρων, τοὺς δὲ ἐκβάλωσι, τοῖς δὲ λοιποῖς ἐξ ἴσου μεταδῶσι πολιτείας τε καὶ ἀρχῶν, καὶ ὡς τὸ πολὺ ἀπὸ κλήρων αἱ ἀρχαὶ ἐν αὐτῇ γίγνονται.","st":"557a"},{"sp":"N","t":"ἔστι γάρ, ἔφη, αὕτη ἡ κατάστασις δημοκρατίας, ἐάντε καὶ δι᾽ ὅπλων γένηται ἐάντε καὶ διὰ φόβον ὑπεξελθόντων τῶν ἑτέρων. τίνα δὴ οὖν, ἦν δ᾽ ἐγώ, οὗτοι τρόπον οἰκοῦσι; καὶ ποία","st":"557a"},{"sp":"N","t":"τις ἡ τοιαύτη αὖ πολιτεία; δῆλον γὰρ ὅτι ὁ τοιοῦτος ἀνὴρ δημοκρατικός τις ἀναφανήσεται.","st":"557b"},{"sp":"N","t":"δῆλον, ἔφη.","st":"557b"},{"sp":"N","t":"οὐκοῦν πρῶτον μὲν δὴ ἐλεύθεροι, καὶ ἐλευθερίας ἡ πόλις μεστὴ καὶ παρρησίας γίγνεται, καὶ ἐξουσία ἐν αὐτῇ ποιεῖν ὅτι τις βούλεται;","st":"557b"},{"sp":"N","t":"λέγεταί γε δή, ἔφη.","st":"557b"},{"sp":"N","t":"ὅπου δέ γε ἐξουσία, δῆλον ὅτι ἰδίαν ἕκαστος ἂν κατασκευὴν τοῦ αὑτοῦ βίου κατασκευάζοιτο ἐν αὐτῇ, ἥτις ἕκαστον ἀρέσκοι.","st":"557b"},{"sp":"N","t":"δῆλον.","st":"557b"},{"sp":"N","t":"παντοδαποὶ δὴ ἂν οἶμαι ἐν ταύτῃ τῇ πολιτείᾳ μάλιστ᾽ ἐγγίγνοιντο ἄνθρωποι.","st":"557c"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"557c"},{"sp":"N","t":"κινδυνεύει, ἦν δ᾽ ἐγώ, καλλίστη αὕτη τῶν πολιτειῶν εἶναι: ὥσπερ ἱμάτιον ποικίλον πᾶσιν ἄνθεσι πεποικιλμένον, οὕτω καὶ αὕτη πᾶσιν ἤθεσιν πεποικιλμένη καλλίστη ἂν φαίνοιτο. καὶ ἴσως μέν, ἦν δ᾽ ἐγώ, καὶ ταύτην, ὥσπερ οἱ παῖδές τε καὶ αἱ γυναῖκες τὰ ποικίλα θεώμενοι, καλλίστην ἂν πολλοὶ κρίνειαν. καὶ μάλ᾽, ἔφη.","st":"557c"},{"sp":"N","t":"καὶ ἔστιν γε, ὦ μακάριε, ἦν δ᾽ ἐγώ, ἐπιτήδειον ζητεῖν ἐν αὐτῇ πολιτείαν.","st":"557d"},{"sp":"N","t":"τί δή;","st":"557d"},{"sp":"N","t":"ὅτι πάντα γένη πολιτειῶν ἔχει διὰ τὴν ἐξουσίαν, καὶ κινδυνεύει τῷ βουλομένῳ πόλιν κατασκευάζειν, ὃ νυνδὴ ἡμεῖς ἐποιοῦμεν, ἀναγκαῖον εἶναι εἰς δημοκρατουμένην ἐλθόντι πόλιν, ὃς ἂν αὐτὸν ἀρέσκῃ τρόπος, τοῦτον ἐκλέξασθαι, ὥσπερ εἰς παντοπώλιον ἀφικομένῳ πολιτειῶν, καὶ ἐκλεξαμένῳ οὕτω κατοικίζειν.","st":"557d"},{"sp":"N","t":"ἴσως γοῦν, ἔφη, οὐκ ἂν ἀποροῖ παραδειγμάτων.","st":"557e"},{"sp":"N","t":"τὸ δὲ μηδεμίαν ἀνάγκην, εἶπον, εἶναι ἄρχειν ἐν ταύτῃ τῇ πόλει, μηδ᾽ ἂν ᾖς ἱκανὸς ἄρχειν, μηδὲ αὖ ἄρχεσθαι, ἐὰν μὴ βούλῃ, μηδὲ πολεμεῖν πολεμούντων, μηδὲ εἰρήνην ἄγειν τῶν ἄλλων ἀγόντων, ἐὰν μὴ ἐπιθυμῇς εἰρήνης, μηδὲ αὖ, ἐάν τις ἄρχειν νόμος σε διακωλύῃ ἢ δικάζειν, μηδὲν ἧττον καὶ","st":"557e"},{"sp":"N","t":"ἄρχειν καὶ δικάζειν, ἐὰν αὐτῷ σοι ἐπίῃ, ἆρ᾽ οὐ θεσπεσία καὶ ἡδεῖα ἡ τοιαύτη διαγωγὴ ἐν τῷ παραυτίκα;","st":"558a"},{"sp":"N","t":"ἴσως, ἔφη, ἔν γε τούτῳ.","st":"558a"},{"sp":"N","t":"τί δέ; ἡ πρᾳότης ἐνίων τῶν δικασθέντων οὐ κομψή; ἢ οὔπω εἶδες, ἐν τοιαύτῃ πολιτείᾳ [ἀνθρώπων] καταψηφισθέντων θανάτου ἢ φυγῆς, οὐδὲν ἧττον αὐτῶν μενόντων τε καὶ ἀναστρεφομένων ἐν μέσῳ, [καὶ] ὡς οὔτε φροντίζοντος οὔτε ὁρῶντος οὐδενὸς περινοστεῖ ὥσπερ ἥρως;","st":"558a"},{"sp":"N","t":"καὶ πολλούς γ᾽, ἔφη.","st":"558a"},{"sp":"N","t":"ἡ δὲ συγγνώμη καὶ οὐδ᾽ ὁπωστιοῦν σμικρολογία αὐτῆς, ἀλλὰ καταφρόνησις ὧν ἡμεῖς ἐλέγομεν σεμνύνοντες, ὅτε τὴν πόλιν ᾠκίζομεν, ὡς εἰ μή τις ὑπερβεβλημένην φύσιν ἔχοι, οὔποτ᾽ ἂν γένοιτο ἀνὴρ ἀγαθός, εἰ μὴ παῖς ὢν εὐθὺς παίζοι ἐν καλοῖς καὶ ἐπιτηδεύοι τὰ τοιαῦτα πάντα, ὡς μεγαλοπρεπῶς καταπατήσασ᾽ ἅπαντ᾽ αὐτὰ οὐδὲν φροντίζει ἐξ ὁποίων ἄν τις ἐπιτηδευμάτων ἐπὶ τὰ πολιτικὰ ἰὼν πράττῃ, ἀλλὰ τιμᾷ,","st":"558b"},{"sp":"N","t":"ἐὰν φῇ μόνον εὔνους εἶναι τῷ πλήθει;","st":"558c"},{"sp":"N","t":"πάνυ γ᾽, ἔφη, γενναία.","st":"558c"},{"sp":"N","t":"ταῦτά τε δή, ἔφην, ἔχοι ἂν καὶ τούτων ἄλλα ἀδελφὰ δημοκρατία, καὶ εἴη, ὡς ἔοικεν, ἡδεῖα πολιτεία καὶ ἄναρχος καὶ ποικίλη, ἰσότητά τινα ὁμοίως ἴσοις τε καὶ ἀνίσοις διανέμουσα.","st":"558c"},{"sp":"N","t":"καὶ μάλ᾽, ἔφη, γνώριμα λέγεις.","st":"558c"},{"sp":"N","t":"ἄθρει δή, ἦν δ᾽ ἐγώ, τίς ὁ τοιοῦτος ἰδίᾳ. ἢ πρῶτον σκεπτέον, ὥσπερ τὴν πολιτείαν ἐσκεψάμεθα, τίνα τρόπον γίγνεται;","st":"558c"},{"sp":"N","t":"ναί, ἔφη.","st":"558c"},{"sp":"N","t":"ἆρ᾽ οὖν οὐχ ὧδε; τοῦ φειδωλοῦ ἐκείνου καὶ ὀλιγαρχικοῦ","st":"558c"},{"sp":"N","t":"γένοιτ᾽ ἂν οἶμαι ὑὸς ὑπὸ τῷ πατρὶ τεθραμμένος ἐν τοῖς ἐκείνου ἤθεσι;","st":"558d"},{"sp":"N","t":"τί γὰρ οὔ;","st":"558d"},{"sp":"N","t":"βίᾳ δὴ καὶ οὗτος ἄρχων τῶν ἐν αὑτῷ ἡδονῶν, ὅσαι ἀναλωτικαὶ μέν, χρηματιστικαὶ δὲ μή: αἳ δὴ οὐκ ἀναγκαῖαι κέκληνται-","st":"558d"},{"sp":"N","t":"δῆλον, ἔφη.","st":"558d"},{"sp":"N","t":"βούλει οὖν, ἦν δ᾽ ἐγώ, ἵνα μὴ σκοτεινῶς διαλεγώμεθα, πρῶτον ὁρισώμεθα τάς τε ἀναγκαίους ἐπιθυμίας καὶ τὰς μή;","st":"558d"},{"sp":"N","t":"βούλομαι, ἦ δ᾽ ὅς.","st":"558d"},{"sp":"N","t":"οὐκοῦν ἅς τε οὐκ ἂν οἷοί τ᾽ εἶμεν ἀποτρέψαι, δικαίως","st":"558d"},{"sp":"N","t":"ἂν ἀναγκαῖαι καλοῖντο, καὶ ὅσαι ἀποτελούμεναι ὠφελοῦσιν ἡμᾶς; τούτων γὰρ ἀμφοτέρων ἐφίεσθαι ἡμῶν τῇ φύσει ἀνάγκη. ἢ οὔ;","st":"558e"},{"sp":"N","t":"καὶ μάλα.","st":"558e"},{"sp":"N","t":"δικαίως δὴ τοῦτο ἐπ᾽ αὐταῖς ἐροῦμεν, τὸ ἀναγκαῖον.","st":"559a"},{"sp":"N","t":"δικαίως.","st":"559a"},{"sp":"N","t":"τί δέ; ἅς γέ τις ἀπαλλάξειεν ἄν, εἰ μελετῷ ἐκ νέου, καὶ πρὸς οὐδὲν ἀγαθὸν ἐνοῦσαι δρῶσιν, αἱ δὲ καὶ τοὐναντίον, πάσας ταύτας εἰ μὴ ἀναγκαίους φαῖμεν εἶναι, ἆρ᾽ οὐ","st":"559a"},{"sp":"N","t":"καλῶς ἂν λέγοιμεν;","st":"559a"},{"sp":"N","t":"καλῶς μὲν οὖν.","st":"559a"},{"sp":"N","t":"προελώμεθα δή τι παράδειγμα ἑκατέρων αἵ εἰσιν, ἵνα τύπῳ λάβωμεν αὐτάς;","st":"559a"},{"sp":"N","t":"οὐκοῦν χρή.","st":"559a"},{"sp":"N","t":"ἆρ᾽ οὖν οὐχ ἡ τοῦ φαγεῖν μέχρι ὑγιείας τε καὶ εὐεξίας","st":"559a"},{"sp":"N","t":"καὶ αὐτοῦ σίτου τε καὶ ὄψου ἀναγκαῖος ἂν εἴη;","st":"559b"},{"sp":"N","t":"οἶμαι.","st":"559b"},{"sp":"N","t":"ἡ μέν γέ που τοῦ σίτου κατ᾽ ἀμφότερα ἀναγκαία, ᾗ τε ὠφέλιμος ᾗ τε ⟨μὴ⟩ παῦσαι ζῶντα δυνατή.","st":"559b"},{"sp":"N","t":"ναί.","st":"559b"},{"sp":"N","t":"ἡ δὲ ὄψου, εἴ πῄ τινα ὠφελίαν πρὸς εὐεξίαν παρέχεται,","st":"559b"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"559b"},{"sp":"N","t":"τί δὲ ἡ πέρα τούτων καὶ ἀλλοίων ἐδεσμάτων ἢ τοιούτων ἐπιθυμία, δυνατὴ δὲ κολαζομένη ἐκ νέων καὶ παιδευομένη ἐκ τῶν πολλῶν ἀπαλλάττεσθαι, καὶ βλαβερὰ μὲν σώματι, βλαβερὰ δὲ ψυχῇ πρός τε φρόνησιν καὶ τὸ σωφρονεῖν; ἆρά","st":"559b"},{"sp":"N","t":"γε ὀρθῶς οὐκ ἀναγκαία ἂν καλοῖτο;","st":"559c"},{"sp":"N","t":"ὀρθότατα μὲν οὖν.","st":"559c"},{"sp":"N","t":"οὐκοῦν καὶ ἀναλωτικὰς φῶμεν εἶναι ταύτας, ἐκείνας δὲ χρηματιστικὰς διὰ τὸ χρησίμους πρὸς τὰ ἔργα εἶναι;","st":"559c"},{"sp":"N","t":"τί μήν;","st":"559c"},{"sp":"N","t":"οὕτω δὴ καὶ περὶ ἀφροδισίων καὶ τῶν ἄλλων φήσομεν;","st":"559c"},{"sp":"N","t":"οὕτω.","st":"559c"},{"sp":"N","t":"ἆρ᾽ οὖν καὶ ὃν νυνδὴ κηφῆνα ὠνομάζομεν, τοῦτον ἐλέγομεν τὸν τῶν τοιούτων ἡδονῶν καὶ ἐπιθυμιῶν γέμοντα καὶ","st":"559c"},{"sp":"N","t":"ἀρχόμενον ὑπὸ τῶν μὴ ἀναγκαίων, τὸν δὲ ὑπὸ τῶν ἀναγκαίων φειδωλόν τε καὶ ὀλιγαρχικόν;","st":"559d"},{"sp":"N","t":"ἀλλὰ τί μήν;","st":"559d"},{"sp":"N","t":"πάλιν τοίνυν, ἦν δ᾽ ἐγώ, λέγωμεν ὡς ἐξ ὀλιγαρχικοῦ δημοκρατικὸς γίγνεται. φαίνεται δέ μοι τά γε πολλὰ ὧδε γίγνεσθαι.","st":"559d"},{"sp":"N","t":"πῶς;","st":"559d"},{"sp":"N","t":"ὅταν νέος, τεθραμμένος ὡς νυνδὴ ἐλέγομεν, ἀπαιδεύτως τε καὶ φειδωλῶς, γεύσηται κηφήνων μέλιτος, καὶ συγγένηται αἴθωσι θηρσὶ καὶ δεινοῖς, παντοδαπὰς ἡδονὰς καὶ ποικίλας καὶ παντοίως ἐχούσας δυναμένοις σκευάζειν, ἐνταῦθά που","st":"559d"},{"sp":"N","t":"οἴου εἶναι ἀρχὴν αὐτῷ μεταβολῆς ... ὀλιγαρχικῆς τῆς ἑαυτῷ εἰς δημοκρατικήν. πολλὴ ἀνάγκη, ἔφη.","st":"559e"},{"sp":"N","t":"ἆρ᾽ οὖν, ὥσπερ ἡ πόλις μετέβαλλε βοηθησάσης τῷ ἑτέρῳ μέρει συμμαχίας ἔξωθεν, ὁμοίας ὁμοίῳ, οὕτω καὶ ὁ νεανίας μεταβάλλει βοηθοῦντος αὖ εἴδους ἐπιθυμιῶν ἔξωθεν τῷ ἑτέρῳ τῶν παρ᾽ ἐκείνῳ, συγγενοῦς τε καὶ ὁμοίου;","st":"559e"},{"sp":"N","t":"παντάπασιν μὲν οὖν.","st":"559e"},{"sp":"N","t":"καὶ ἐὰν μέν γε οἶμαι ἀντιβοηθήσῃ τις τῷ ἐν ἑαυτῷ ὀλιγαρχικῷ συμμαχία, ἤ ποθεν παρὰ τοῦ πατρὸς ἢ καὶ τῶν","st":"559e"},{"sp":"N","t":"ἄλλων οἰκείων νουθετούντων τε καὶ κακιζόντων, στάσις δὴ καὶ ἀντίστασις καὶ μάχη ἐν αὐτῷ πρὸς αὑτὸν τότε γίγνεται.","st":"560a"},{"sp":"N","t":"τί μήν;","st":"560a"},{"sp":"N","t":"καὶ ποτὲ μὲν οἶμαι τὸ δημοκρατικὸν ὑπεχώρησε τῷ ὀλιγαρχικῷ, καί τινες τῶν ἐπιθυμιῶν αἱ μὲν διεφθάρησαν, αἱ δὲ καὶ ἐξέπεσον, αἰδοῦς τινος ἐγγενομένης ἐν τῇ τοῦ νέου ψυχῇ, καὶ κατεκοσμήθη πάλιν.","st":"560a"},{"sp":"N","t":"γίγνεται γὰρ ἐνίοτε, ἔφη.","st":"560a"},{"sp":"N","t":"αὖθις δὲ οἶμαι τῶν ἐκπεσουσῶν ἐπιθυμιῶν ἄλλαι ὑποτρεφόμεναι","st":"560a"},{"sp":"N","t":"συγγενεῖς δι᾽ ἀνεπιστημοσύνην τροφῆς πατρὸς πολλαί τε καὶ ἰσχυραὶ ἐγένοντο.","st":"560b"},{"sp":"N","t":"φιλεῖ γοῦν, ἔφη, οὕτω γίγνεσθαι.","st":"560b"},{"sp":"N","t":"οὐκοῦν εἵλκυσάν τε πρὸς τὰς αὐτὰς ὁμιλίας, καὶ λάθρᾳ συγγιγνόμεναι πλῆθος ἐνέτεκον.","st":"560b"},{"sp":"N","t":"τί μήν;","st":"560b"},{"sp":"N","t":"τελευτῶσαι δὴ οἶμαι κατέλαβον τὴν τοῦ νέου τῆς ψυχῆς ἀκρόπολιν, αἰσθόμεναι κενὴν μαθημάτων τε καὶ ἐπιτηδευμάτων καλῶν καὶ λόγων ἀληθῶν, οἳ δὴ ἄριστοι φρουροί τε καὶ φύλακες ἐν ἀνδρῶν θεοφιλῶν εἰσι διανοίαις.","st":"560b"},{"sp":"N","t":"καὶ πολύ γ᾽, ἔφη.","st":"560c"},{"sp":"N","t":"ψευδεῖς δὴ καὶ ἀλαζόνες οἶμαι λόγοι τε καὶ δόξαι ἀντ᾽ ἐκείνων ἀναδραμόντες κατέσχον τὸν αὐτὸν τόπον τοῦ τοιούτου.","st":"560c"},{"sp":"N","t":"σφόδρα γ᾽, ἔφη.","st":"560c"},{"sp":"N","t":"ἆρ᾽ οὖν οὐ πάλιν τε εἰς ἐκείνους τοὺς Λωτοφάγους ἐλθὼν φανερῶς κατοικεῖ, καὶ ἐὰν παρ᾽ οἰκείων τις βοήθεια τῷ φειδωλῷ αὐτοῦ τῆς ψυχῆς ἀφικνῆται, κλῄσαντες οἱ ἀλαζόνες λόγοι ἐκεῖνοι τὰς τοῦ βασιλικοῦ τείχους ἐν αὐτῷ πύλας οὔτε αὐτὴν τὴν συμμαχίαν παριᾶσιν, οὔτε πρέσβεις πρεσβυτέρων","st":"560c"},{"sp":"N","t":"λόγους ἰδιωτῶν εἰσδέχονται, αὐτοί τε κρατοῦσι μαχόμενοι, καὶ τὴν μὲν αἰδῶ ἠλιθιότητα ὀνομάζοντες ὠθοῦσιν ἔξω ἀτίμως φυγάδα, σωφροσύνην δὲ ἀνανδρίαν καλοῦντές τε καὶ προπηλακίζοντες ἐκβάλλουσι, μετριότητα δὲ καὶ κοσμίαν δαπάνην ὡς ἀγροικίαν καὶ ἀνελευθερίαν οὖσαν πείθοντες ὑπερορίζουσι μετὰ πολλῶν καὶ ἀνωφελῶν ἐπιθυμιῶν;","st":"560d"},{"sp":"N","t":"σφόδρα γε.","st":"560d"},{"sp":"N","t":"τούτων δέ γέ που κενώσαντες καὶ καθήραντες τὴν τοῦ","st":"560d"},{"sp":"N","t":"κατεχομένου τε ὑπ᾽ αὐτῶν καὶ τελουμένου ψυχὴν μεγάλοισι τέλεσι, τὸ μετὰ τοῦτο ἤδη ὕβριν καὶ ἀναρχίαν καὶ ἀσωτίαν καὶ ἀναίδειαν λαμπρὰς μετὰ πολλοῦ χοροῦ κατάγουσιν ἐστεφανωμένας, ἐγκωμιάζοντες καὶ ὑποκοριζόμενοι, ὕβριν μὲν εὐπαιδευσίαν καλοῦντες, ἀναρχίαν δὲ ἐλευθερίαν, ἀσωτίαν","st":"560e"},{"sp":"N","t":"δὲ μεγαλοπρέπειαν, ἀναίδειαν δὲ ἀνδρείαν. ἆρ᾽ οὐχ οὕτω πως, ἦν δ᾽ ἐγώ, νέος ὢν μεταβάλλει ἐκ τοῦ ἐν ἀναγκαίοις ἐπιθυμίαις τρεφομένου τὴν τῶν μὴ ἀναγκαίων καὶ ἀνωφελῶν ἡδονῶν ἐλευθέρωσίν τε καὶ ἄνεσιν;","st":"561a"},{"sp":"N","t":"καὶ μάλα γ᾽, ἦ δ᾽ ὅς, ἐναργῶς.","st":"561a"},{"sp":"N","t":"Ζῇ δὴ οἶμαι μετὰ ταῦτα ὁ τοιοῦτος οὐδὲν μᾶλλον εἰς ἀναγκαίους ἢ μὴ ἀναγκαίους ἡδονὰς ἀναλίσκων καὶ χρήματα καὶ πόνους καὶ διατριβάς: ἀλλ᾽ ἐὰν εὐτυχὴς ᾖ καὶ μὴ πέρα ἐκβακχευθῇ, ἀλλά τι καὶ πρεσβύτερος γενόμενος τοῦ πολλοῦ","st":"561a"},{"sp":"N","t":"θορύβου παρελθόντος μέρη τε καταδέξηται τῶν ἐκπεσόντων καὶ τοῖς ἐπεισελθοῦσι μὴ ὅλον ἑαυτὸν ἐνδῷ, εἰς ἴσον δή τι καταστήσας τὰς ἡδονὰς διάγει, τῇ παραπιπτούσῃ ἀεὶ ὥσπερ λαχούσῃ τὴν ἑαυτοῦ ἀρχὴν παραδιδοὺς ἕως ἂν πληρωθῇ, καὶ αὖθις ἄλλῃ, οὐδεμίαν ἀτιμάζων ἀλλ᾽ ἐξ ἴσου τρέφων.","st":"561b"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"561b"},{"sp":"N","t":"καὶ λόγον γε, ἦν δ᾽ ἐγώ, ἀληθῆ οὐ προσδεχόμενος οὐδὲ παριεὶς εἰς τὸ φρούριον, ἐάν τις λέγῃ ὡς αἱ μέν εἰσι τῶν","st":"561b"},{"sp":"N","t":"καλῶν τε καὶ ἀγαθῶν ἐπιθυμιῶν ἡδοναί, αἱ δὲ τῶν πονηρῶν, καὶ τὰς μὲν χρὴ ἐπιτηδεύειν καὶ τιμᾶν, τὰς δὲ κολάζειν τε καὶ δουλοῦσθαι: ἀλλ᾽ ἐν πᾶσι τούτοις ἀνανεύει τε καὶ ὁμοίας φησὶν ἁπάσας εἶναι καὶ τιμητέας ἐξ ἴσου.","st":"561c"},{"sp":"N","t":"σφόδρα γάρ, ἔφη, οὕτω διακείμενος τοῦτο δρᾷ.","st":"561c"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, καὶ διαζῇ τὸ καθ᾽ ἡμέραν οὕτω χαριζόμενος τῇ προσπιπτούσῃ ἐπιθυμίᾳ, τοτὲ μὲν μεθύων καὶ καταυλούμενος, αὖθις δὲ ὑδροποτῶν καὶ κατισχναινόμενος,","st":"561c"},{"sp":"N","t":"τοτὲ δ᾽ αὖ γυμναζόμενος, ἔστιν δ᾽ ὅτε ἀργῶν καὶ πάντων ἀμελῶν, τοτὲ δ᾽ ὡς ἐν φιλοσοφίᾳ διατρίβων. πολλάκις δὲ πολιτεύεται, καὶ ἀναπηδῶν ὅτι ἂν τύχῃ λέγει τε καὶ πράττει: κἄν ποτέ τινας πολεμικοὺς ζηλώσῃ, ταύτῃ φέρεται, ἢ χρηματιστικούς, ἐπὶ τοῦτ᾽ αὖ. καὶ οὔτε τις τάξις οὔτε ἀνάγκη ἔπεστιν αὐτοῦ τῷ βίῳ, ἀλλ᾽ ἡδύν τε δὴ καὶ ἐλευθέριον καὶ μακάριον καλῶν τὸν βίον τοῦτον χρῆται αὐτῷ διὰ παντός.","st":"561d"},{"sp":"N","t":"παντάπασιν, ἦ δ᾽ ὅς, διελήλυθας βίον ἰσονομικοῦ τινος ἀνδρός.","st":"561e"},{"sp":"N","t":"οἶμαι δέ γε, ἦν δ᾽ ἐγώ, καὶ παντοδαπόν τε καὶ πλείστων ἠθῶν μεστόν, καὶ τὸν καλόν τε καὶ ποικίλον, ὥσπερ ἐκείνην τὴν πόλιν, τοῦτον τὸν ἄνδρα εἶναι: ὃν πολλοὶ ἂν καὶ πολλαὶ ζηλώσειαν τοῦ βίου, παραδείγματα πολιτειῶν τε καὶ τρόπων πλεῖστα ἐν αὐτῷ ἔχοντα.","st":"561e"},{"sp":"N","t":"οὗτος γάρ, ἔφη, ἔστιν.","st":"561e"},{"sp":"N","t":"τί οὖν; τετάχθω ἡμῖν κατὰ δημοκρατίαν ὁ τοιοῦτος ἀνήρ, ὡς δημοκρατικὸς ὀρθῶς ἂν προσαγορευόμενος;","st":"562a"},{"sp":"N","t":"τετάχθω, ἔφη.","st":"562a"},{"sp":"N","t":"ἡ καλλίστη δή, ἦν δ᾽ ἐγώ, πολιτεία τε καὶ ὁ κάλλιστος ἀνὴρ λοιπὰ ἂν ἡμῖν εἴη διελθεῖν, τυραννίς τε καὶ τύραννος.","st":"562a"},{"sp":"N","t":"κομιδῇ γ᾽, ἔφη.","st":"562a"},{"sp":"N","t":"φέρε δή, τίς τρόπος τυραννίδος, ὦ φίλε ἑταῖρε, γίγνεται; ὅτι μὲν γὰρ ἐκ δημοκρατίας μεταβάλλει σχεδὸν δῆλον.","st":"562a"},{"sp":"N","t":"δῆλον.","st":"562a"},{"sp":"N","t":"ἆρ᾽ οὖν τρόπον τινὰ τὸν αὐτὸν ἔκ τε ὀλιγαρχίας δημοκρατία","st":"562a"},{"sp":"N","t":"γίγνεται καὶ ἐκ δημοκρατίας τυραννίς;","st":"562b"},{"sp":"N","t":"πῶς;","st":"562b"},{"sp":"N","t":"ὃ προύθεντο, ἦν δ᾽ ἐγώ, ἀγαθόν, καὶ δι᾽ ὃ ἡ ὀλιγαρχία καθίστατο — τοῦτο δ᾽ ἦν [ὑπερ]πλοῦτος: ἦ γάρ; -","st":"562b"},{"sp":"N","t":"ναί.","st":"562b"},{"sp":"N","t":"ἡ πλούτου τοίνυν ἀπληστία καὶ ἡ τῶν ἄλλων ἀμέλεια διὰ χρηματισμὸν αὐτὴν ἀπώλλυ.","st":"562b"},{"sp":"N","t":"ἀληθῆ, ἔφη.","st":"562b"},{"sp":"N","t":"ἆρ᾽ οὖν καὶ ὃ δημοκρατία ὁρίζεται ἀγαθόν, ἡ τούτου ἀπληστία καὶ ταύτην καταλύει;","st":"562b"},{"sp":"N","t":"λέγεις δ᾽ αὐτὴν τί ὁρίζεσθαι;","st":"562b"},{"sp":"N","t":"τὴν ἐλευθερίαν, εἶπον. τοῦτο γάρ που ἐν δημοκρατουμένῃ","st":"562b"},{"sp":"N","t":"πόλει ἀκούσαις ἂν ὡς ἔχει τε κάλλιστον καὶ διὰ ταῦτα ἐν μόνῃ ταύτῃ ἄξιον οἰκεῖν ὅστις φύσει ἐλεύθερος.","st":"562c"},{"sp":"N","t":"λέγεται γὰρ δή, ἔφη, καὶ πολὺ τοῦτο τὸ ῥῆμα.","st":"562c"},{"sp":"N","t":"ἆρ᾽ οὖν, ἦν δ᾽ ἐγώ, ὅπερ ᾖα νυνδὴ ἐρῶν, ἡ τοῦ τοιούτου ἀπληστία καὶ ἡ τῶν ἄλλων ἀμέλεια καὶ ταύτην τὴν πολιτείαν μεθίστησίν τε καὶ παρασκευάζει τυραννίδος δεηθῆναι;","st":"562c"},{"sp":"N","t":"πῶς; ἔφη.","st":"562c"},{"sp":"N","t":"ὅταν οἶμαι δημοκρατουμένη πόλις ἐλευθερίας διψήσασα","st":"562c"},{"sp":"N","t":"κακῶν οἰνοχόων προστατούντων τύχῃ, καὶ πορρωτέρω τοῦ δέοντος ἀκράτου αὐτῆς μεθυσθῇ, τοὺς ἄρχοντας δή, ἂν μὴ πάνυ πρᾷοι ὦσι καὶ πολλὴν παρέχωσι τὴν ἐλευθερίαν, κολάζει αἰτιωμένη ὡς μιαρούς τε καὶ ὀλιγαρχικούς.","st":"562d"},{"sp":"N","t":"δρῶσιν γάρ, ἔφη, τοῦτο.","st":"562d"},{"sp":"N","t":"τοὺς δέ γε, εἶπον, τῶν ἀρχόντων κατηκόους προπηλακίζει ὡς ἐθελοδούλους τε καὶ οὐδὲν ὄντας, τοὺς δὲ ἄρχοντας μὲν ἀρχομένοις, ἀρχομένους δὲ ἄρχουσιν ὁμοίους ἰδίᾳ τε καὶ δημοσίᾳ ἐπαινεῖ τε καὶ τιμᾷ. ἆρ᾽ οὐκ ἀνάγκη ἐν τοιαύτῃ","st":"562d"},{"sp":"N","t":"πόλει ἐπὶ πᾶν τὸ τῆς ἐλευθερίας ἰέναι;","st":"562e"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"562e"},{"sp":"N","t":"καὶ καταδύεσθαί γε, ἦν δ᾽ ἐγώ, ὦ φίλε, εἴς τε τὰς ἰδίας οἰκίας καὶ τελευτᾶν μέχρι τῶν θηρίων τὴν ἀναρχίαν ἐμφυομένην.","st":"562e"},{"sp":"N","t":"πῶς, ἦ δ᾽ ὅς, τὸ τοιοῦτον λέγομεν;","st":"562e"},{"sp":"N","t":"οἷον, ἔφην, πατέρα μὲν ἐθίζεσθαι παιδὶ ὅμοιον γίγνεσθαι καὶ φοβεῖσθαι τοὺς ὑεῖς, ὑὸν δὲ πατρί, καὶ μήτε αἰσχύνεσθαι μήτε δεδιέναι τοὺς γονέας, ἵνα δὴ ἐλεύθερος ᾖ: μέτοικον δὲ","st":"562e"},{"sp":"N","t":"ἀστῷ καὶ ἀστὸν μετοίκῳ ἐξισοῦσθαι, καὶ ξένον ὡσαύτως.","st":"563a"},{"sp":"N","t":"γίγνεται γὰρ οὕτως, ἔφη.","st":"563a"},{"sp":"N","t":"ταῦτά τε, ἦν δ᾽ ἐγώ, καὶ σμικρὰ τοιάδε ἄλλα γίγνεται: διδάσκαλός τε ἐν τῷ τοιούτῳ φοιτητὰς φοβεῖται καὶ θωπεύει, φοιτηταί τε διδασκάλων ὀλιγωροῦσιν, οὕτω δὲ καὶ παιδαγωγῶν: καὶ ὅλως οἱ μὲν νέοι πρεσβυτέροις ἀπεικάζονται καὶ διαμιλλῶνται καὶ ἐν λόγοις καὶ ἐν ἔργοις, οἱ δὲ γέροντες συγκαθιέντες τοῖς νέοις εὐτραπελίας τε καὶ χαριεντισμοῦ","st":"563a"},{"sp":"N","t":"ἐμπίμπλανται, μιμούμενοι τοὺς νέους, ἵνα δὴ μὴ δοκῶσιν ἀηδεῖς εἶναι μηδὲ δεσποτικοί.","st":"563b"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη.","st":"563b"},{"sp":"N","t":"τὸ δέ γε, ἦν δ᾽ ἐγώ, ἔσχατον, ὦ φίλε, τῆς ἐλευθερίας τοῦ πλήθους, ὅσον γίγνεται ἐν τῇ τοιαύτῃ πόλει, ὅταν δὴ οἱ ἐωνημένοι καὶ αἱ ἐωνημέναι μηδὲν ἧττον ἐλεύθεροι ὦσι τῶν πριαμένων. ἐν γυναιξὶ δὲ πρὸς ἄνδρας καὶ ἀνδράσι πρὸς γυναῖκας ὅση ἡ ἰσονομία καὶ ἐλευθερία γίγνεται, ὀλίγου ἐπελαθόμεθ᾽ εἰπεῖν.","st":"563b"},{"sp":"N","t":"οὐκοῦν κατ᾽ Αἰσχύλον, ἔφη, “ἐροῦμεν ὅτι νῦν ἦλθ᾽ ἐπὶ στόμα;”","st":"563c"},{"sp":"N","t":"πάνυ γε, εἶπον: καὶ ἔγωγε οὕτω λέγω: τὸ μὲν γὰρ τῶν θηρίων τῶν ὑπὸ τοῖς ἀνθρώποις ὅσῳ ἐλευθερώτερά ἐστιν ἐνταῦθα ἢ ἐν ἄλλῃ, οὐκ ἄν τις πείθοιτο ἄπειρος. ἀτεχνῶς γὰρ αἵ τε κύνες κατὰ τὴν παροιμίαν οἷαίπερ αἱ δέσποιναι γίγνονταί τε δὴ καὶ ἵπποι καὶ ὄνοι, πάνυ ἐλευθέρως καὶ σεμνῶς εἰθισμένοι πορεύεσθαι, κατὰ τὰς ὁδοὺς ἐμβάλλοντες τῷ ἀεὶ ἀπαντῶντι, ἐὰν μὴ ἐξίστηται, καὶ τἆλλα πάντα οὕτω","st":"563c"},{"sp":"N","t":"μεστὰ ἐλευθερίας γίγνεται.","st":"563d"},{"sp":"N","t":"τὸ ἐμόν γ᾽, ἔφη, ἐμοὶ λέγεις ὄναρ: αὐτὸς γὰρ εἰς ἀγρὸν πορευόμενος θαμὰ αὐτὸ πάσχω.","st":"563d"},{"sp":"N","t":"τὸ δὲ δὴ κεφάλαιον, ἦν δ᾽ ἐγώ, πάντων τούτων συνηθροισμένων, ἐννοεῖς ὡς ἁπαλὴν τὴν ψυχὴν τῶν πολιτῶν ποιεῖ, ὥστε κἂν ὁτιοῦν δουλείας τις προσφέρηται, ἀγανακτεῖν καὶ μὴ ἀνέχεσθαι; τελευτῶντες γάρ που οἶσθ᾽ ὅτι οὐδὲ τῶν νόμων φροντίζουσιν γεγραμμένων ἢ ἀγράφων, ἵνα δὴ μηδαμῇ","st":"563d"},{"sp":"N","t":"μηδεὶς αὐτοῖς ᾖ δεσπότης.","st":"563e"},{"sp":"N","t":"καὶ μάλ᾽, ἔφη, οἶδα.","st":"563e"},{"sp":"N","t":"αὕτη μὲν τοίνυν, ἦν δ᾽ ἐγώ, ὦ φίλε, ἡ ἀρχὴ οὑτωσὶ καλὴ καὶ νεανική, ὅθεν τυραννὶς φύεται, ὡς ἐμοὶ δοκεῖ.","st":"563e"},{"sp":"N","t":"νεανικὴ δῆτα, ἔφη: ἀλλὰ τί τὸ μετὰ τοῦτο;","st":"563e"},{"sp":"N","t":"ταὐτόν, ἦν δ᾽ ἐγώ, ὅπερ ἐν τῇ ὀλιγαρχίᾳ νόσημα ἐγγενόμενον ἀπώλεσεν αὐτήν, τοῦτο καὶ ἐν ταύτῃ πλέον τε καὶ ἰσχυρότερον ἐκ τῆς ἐξουσίας ἐγγενόμενον καταδουλοῦται δημοκρατίαν. καὶ τῷ ὄντι τὸ ἄγαν τι ποιεῖν μεγάλην φιλεῖ εἰς τοὐναντίον μεταβολὴν ἀνταποδιδόναι, ἐν ὥραις τε καὶ ἐν","st":"563e"},{"sp":"N","t":"φυτοῖς καὶ ἐν σώμασιν, καὶ δὴ καὶ ἐν πολιτείαις οὐχ ἥκιστα.","st":"564a"},{"sp":"N","t":"εἰκός, ἔφη.","st":"564a"},{"sp":"N","t":"ἡ γὰρ ἄγαν ἐλευθερία ἔοικεν οὐκ εἰς ἄλλο τι ἢ εἰς ἄγαν δουλείαν μεταβάλλειν καὶ ἰδιώτῃ καὶ πόλει.","st":"564a"},{"sp":"N","t":"εἰκὸς γάρ.","st":"564a"},{"sp":"N","t":"εἰκότως τοίνυν, εἶπον, οὐκ ἐξ ἄλλης πολιτείας τυραννὶς καθίσταται ἢ ἐκ δημοκρατίας, ἐξ οἶμαι τῆς ἀκροτάτης ἐλευθερίας δουλεία πλείστη τε καὶ ἀγριωτάτη.","st":"564a"},{"sp":"N","t":"ἔχει γάρ, ἔφη, λόγον.","st":"564a"},{"sp":"N","t":"ἀλλ᾽ οὐ τοῦτ᾽ οἶμαι, ἦν δ᾽ ἐγώ, ἠρώτας, ἀλλὰ ποῖον","st":"564a"},{"sp":"N","t":"νόσημα ἐν ὀλιγαρχίᾳ τε φυόμενον ταὐτὸν καὶ ἐν δημοκρατίᾳ δουλοῦται αὐτήν.","st":"564b"},{"sp":"N","t":"ἀληθῆ, ἔφη, λέγεις.","st":"564b"},{"sp":"N","t":"ἐκεῖνο τοίνυν, ἔφην, ἔλεγον τὸ τῶν ἀργῶν τε καὶ δαπανηρῶν ἀνδρῶν γένος, τὸ μὲν ἀνδρειότατον ἡγούμενον αὐτῶν, τὸ δ᾽ ἀνανδρότερον ἑπόμενον: οὓς δὴ ἀφομοιοῦμεν κηφῆσι, τοὺς μὲν κέντρα ἔχουσι, τοὺς δὲ ἀκέντροις.","st":"564b"},{"sp":"N","t":"καὶ ὀρθῶς γ᾽, ἔφη.","st":"564b"},{"sp":"N","t":"τούτω τοίνυν, ἦν δ᾽ ἐγώ, ταράττετον ἐν πάσῃ πολιτείᾳ ἐγγιγνομένω, οἷον περὶ σῶμα φλέγμα τε καὶ χολή: ὣ δὴ καὶ","st":"564b"},{"sp":"N","t":"δεῖ τὸν ἀγαθὸν ἰατρόν τε καὶ νομοθέτην πόλεως μὴ ἧττον ἢ σοφὸν μελιττουργὸν πόρρωθεν εὐλαβεῖσθαι, μάλιστα μὲν ὅπως μὴ ἐγγενήσεσθον, ἂν δὲ ἐγγένησθον, ὅπως ὅτι τάχιστα σὺν αὐτοῖσι τοῖς κηρίοις ἐκτετμήσεσθον.","st":"564c"},{"sp":"N","t":"ναὶ μὰ Δία, ἦ δ᾽ ὅς, παντάπασί γε.","st":"564c"},{"sp":"N","t":"ὧδε τοίνυν, ἦν δ᾽ ἐγώ, λάβωμεν, ἵν᾽ εὐκρινέστερον ἴδωμεν ὃ βουλόμεθα.","st":"564c"},{"sp":"N","t":"πῶς;","st":"564c"},{"sp":"N","t":"τριχῇ διαστησώμεθα τῷ λόγῳ δημοκρατουμένην πόλιν,","st":"564c"},{"sp":"N","t":"ὥσπερ οὖν καὶ ἔχει. ἓν μὲν γάρ που τὸ τοιοῦτον γένος ἐν αὐτῇ ἐμφύεται δι᾽ ἐξουσίαν οὐκ ἔλαττον ἢ ἐν τῇ ὀλιγαρχουμένῃ.","st":"564d"},{"sp":"N","t":"ἔστιν οὕτω.","st":"564d"},{"sp":"N","t":"πολὺ δέ γε δριμύτερον ἐν ταύτῃ ἢ ἐν ἐκείνῃ.","st":"564d"},{"sp":"N","t":"πῶς;","st":"564d"},{"sp":"N","t":"ἐκεῖ μὲν διὰ τὸ μὴ ἔντιμον εἶναι, ἀλλ᾽ ἀπελαύνεσθαι τῶν ἀρχῶν, ἀγύμναστον καὶ οὐκ ἐρρωμένον γίγνεται: ἐν δημοκρατίᾳ δὲ τοῦτό που τὸ προεστὸς αὐτῆς, ἐκτὸς ὀλίγων, καὶ τὸ μὲν δριμύτατον αὐτοῦ λέγει τε καὶ πράττει, τὸ δ᾽ ἄλλο περὶ τὰ βήματα προσίζον βομβεῖ τε καὶ οὐκ ἀνέχεται τοῦ","st":"564d"},{"sp":"N","t":"ἄλλα λέγοντος, ὥστε πάντα ὑπὸ τοῦ τοιούτου διοικεῖται ἐν τῇ τοιαύτῃ πολιτείᾳ χωρίς τινων ὀλίγων.","st":"564e"},{"sp":"N","t":"μάλα γε, ἦ δ᾽ ὅς.","st":"564e"},{"sp":"N","t":"ἄλλο τοίνυν τοιόνδε ἀεὶ ἀποκρίνεται ἐκ τοῦ πλήθους.","st":"564e"},{"sp":"N","t":"τὸ ποῖον;","st":"564e"},{"sp":"N","t":"χρηματιζομένων που πάντων, οἱ κοσμιώτατοι φύσει ὡς τὸ πολὺ πλουσιώτατοι γίγνονται.","st":"564e"},{"sp":"N","t":"εἰκός.","st":"564e"},{"sp":"N","t":"πλεῖστον δὴ οἶμαι τοῖς κηφῆσι μέλι καὶ εὐπορώτατον ἐντεῦθεν βλίττει.","st":"564e"},{"sp":"N","t":"πῶς γὰρ ἄν, ἔφη, παρά γε τῶν σμικρὰ ἐχόντων τις βλίσειεν;","st":"564e"},{"sp":"N","t":"πλούσιοι δὴ οἶμαι οἱ τοιοῦτοι καλοῦνται κηφήνων βοτάνη.","st":"564e"},{"sp":"N","t":"σχεδόν τι, ἔφη.","st":"564e"},{"sp":"N","t":"δῆμος δ᾽ ἂν εἴη τρίτον γένος, ὅσοι αὐτουργοί τε καὶ ἀπράγμονες, οὐ πάνυ πολλὰ κεκτημένοι: ὃ δὴ πλεῖστόν τε καὶ κυριώτατον ἐν δημοκρατίᾳ ὅτανπερ ἁθροισθῇ.","st":"565a"},{"sp":"N","t":"ἔστιν γάρ, ἔφη: ἀλλ᾽ οὐ θαμὰ ἐθέλει ποιεῖν τοῦτο, ἐὰν μὴ μέλιτός τι μεταλαμβάνῃ.","st":"565a"},{"sp":"N","t":"οὐκοῦν μεταλαμβάνει, ἦν δ᾽ ἐγώ, ἀεί, καθ᾽ ὅσον δύνανται οἱ προεστῶτες, τοὺς ἔχοντας τὴν οὐσίαν ἀφαιρούμενοι, διανέμοντες τῷ δήμῳ, τὸ πλεῖστον αὐτοὶ ἔχειν.","st":"565a"},{"sp":"N","t":"μεταλαμβάνει γὰρ οὖν, ἦ δ᾽ ὅς, οὕτως.","st":"565b"},{"sp":"N","t":"ἀναγκάζονται δὴ οἶμαι ἀμύνεσθαι, λέγοντές τε ἐν τῷ δήμῳ καὶ πράττοντες ὅπῃ δύνανται, οὗτοι ὧν ἀφαιροῦνται.","st":"565b"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"565b"},{"sp":"N","t":"αἰτίαν δὴ ἔσχον ὑπὸ τῶν ἑτέρων, κἂν μὴ ἐπιθυμῶσι νεωτερίζειν, ὡς ἐπιβουλεύουσι τῷ δήμῳ καί εἰσιν ὀλιγαρχικοί.","st":"565b"},{"sp":"N","t":"τί μήν;","st":"565b"},{"sp":"N","t":"οὐκοῦν καὶ τελευτῶντες, ἐπειδὰν ὁρῶσι τὸν δῆμον, οὐχ ἑκόντα ἀλλ᾽ ἀγνοήσαντά τε καὶ ἐξαπατηθέντα ὑπὸ τῶν","st":"565b"},{"sp":"N","t":"διαβαλλόντων, ἐπιχειροῦντα σφᾶς ἀδικεῖν, τότ᾽ ἤδη, εἴτε βούλονται εἴτε μή, ὡς ἀληθῶς ὀλιγαρχικοὶ γίγνονται, οὐχ ἑκόντες, ἀλλὰ καὶ τοῦτο τὸ κακὸν ἐκεῖνος ὁ κηφὴν ἐντίκτει κεντῶν αὐτούς.","st":"565c"},{"sp":"N","t":"κομιδῇ μὲν οὖν.","st":"565c"},{"sp":"N","t":"εἰσαγγελίαι δὴ καὶ κρίσεις καὶ ἀγῶνες περὶ ἀλλήλων γίγνονται.","st":"565c"},{"sp":"N","t":"καὶ μάλα.","st":"565c"},{"sp":"N","t":"οὐκοῦν ἕνα τινὰ ἀεὶ δῆμος εἴωθεν διαφερόντως προΐστασθαι ἑαυτοῦ, καὶ τοῦτον τρέφειν τε καὶ αὔξειν μέγαν;","st":"565c"},{"sp":"N","t":"εἴωθε γάρ.","st":"565c"},{"sp":"N","t":"τοῦτο μὲν ἄρα, ἦν δ᾽ ἐγώ, δῆλον, ὅτι, ὅτανπερ φύηται τύραννος, ἐκ προστατικῆς ῥίζης καὶ οὐκ ἄλλοθεν ἐκβλαστάνει.","st":"565d"},{"sp":"N","t":"καὶ μάλα δῆλον.","st":"565d"},{"sp":"N","t":"τίς ἀρχὴ οὖν μεταβολῆς ἐκ προστάτου ἐπὶ τύραννον; ἢ δῆλον ὅτι ἐπειδὰν ταὐτὸν ἄρξηται δρᾶν ὁ προστάτης τῷ ἐν τῷ μύθῳ ὃς περὶ τὸ ἐν Ἀρκαδίᾳ τὸ τοῦ Διὸς τοῦ Λυκαίου","st":"565d"},{"sp":"N","t":"ἱερὸν λέγεται;","st":"565d"},{"sp":"N","t":"τίς; ἔφη.","st":"565d"},{"sp":"N","t":"ὡς ἄρα ὁ γευσάμενος τοῦ ἀνθρωπίνου σπλάγχνου, ἐν ἄλλοις ἄλλων ἱερείων ἑνὸς ἐγκατατετμημένου, ἀνάγκη δὴ","st":"565d"},{"sp":"N","t":"τούτῳ λύκῳ γενέσθαι. ἢ οὐκ ἀκήκοας τὸν λόγον;","st":"565e"},{"sp":"N","t":"ἔγωγε.","st":"565e"},{"sp":"N","t":"ἆρ᾽ οὖν οὕτω καὶ ὃς ἂν δήμου προεστώς, λαβὼν σφόδρα πειθόμενον ὄχλον, μὴ ἀπόσχηται ἐμφυλίου αἵματος, ἀλλ᾽ ἀδίκως ἐπαιτιώμενος, οἷα δὴ φιλοῦσιν, εἰς δικαστήρια ἄγων μιαιφονῇ, βίον ἀνδρὸς ἀφανίζων, γλώττῃ τε καὶ στόματι ἀνοσίῳ γευόμενος φόνου συγγενοῦς, καὶ ἀνδρηλατῇ καὶ","st":"565e"},{"sp":"N","t":"ἀποκτεινύῃ καὶ ὑποσημαίνῃ χρεῶν τε ἀποκοπὰς καὶ γῆς ἀναδασμόν, ἆρα τῷ τοιούτῳ ἀνάγκη δὴ τὸ μετὰ τοῦτο καὶ εἵμαρται ἢ ἀπολωλέναι ὑπὸ τῶν ἐχθρῶν ἢ τυραννεῖν καὶ λύκῳ ἐξ ἀνθρώπου γενέσθαι;","st":"566a"},{"sp":"N","t":"πολλὴ ἀνάγκη, ἔφη.","st":"566a"},{"sp":"N","t":"οὗτος δή, ἔφην, ὁ στασιάζων γίγνεται πρὸς τοὺς ἔχοντας τὰς οὐσίας.","st":"566a"},{"sp":"N","t":"οὗτος.","st":"566a"},{"sp":"N","t":"ἆρ᾽ οὖν ἐκπεσὼν μὲν καὶ κατελθὼν βίᾳ τῶν ἐχθρῶν τύραννος ἀπειργασμένος κατέρχεται;","st":"566a"},{"sp":"N","t":"δῆλον.","st":"566a"},{"sp":"N","t":"ἐὰν δὲ ἀδύνατοι ἐκβάλλειν αὐτὸν ὦσιν ἢ ἀποκτεῖναι διαβάλλοντες τῇ πόλει, βιαίῳ δὴ θανάτῳ ἐπιβουλεύουσιν ἀποκτεινύναι λάθρᾳ.","st":"566b"},{"sp":"N","t":"φιλεῖ γοῦν, ἦ δ᾽ ὅς, οὕτω γίγνεσθαι.","st":"566b"},{"sp":"N","t":"τὸ δὴ τυραννικὸν αἴτημα τὸ πολυθρύλητον ἐπὶ τούτῳ πάντες οἱ εἰς τοῦτο προβεβηκότες ἐξευρίσκουσιν, αἰτεῖν τὸν δῆμον φύλακάς τινας τοῦ σώματος, ἵνα σῶς αὐτοῖς ᾖ ὁ τοῦ δήμου βοηθός.","st":"566b"},{"sp":"N","t":"καὶ μάλ᾽, ἔφη.","st":"566b"},{"sp":"N","t":"διδόασι δὴ οἶμαι δείσαντες μὲν ὑπὲρ ἐκείνου, θαρρήσαντες δὲ ὑπὲρ ἑαυτῶν.","st":"566b"},{"sp":"N","t":"καὶ μάλα.","st":"566c"},{"sp":"N","t":"οὐκοῦν τοῦτο ὅταν ἴδῃ ἀνὴρ χρήματα ἔχων καὶ μετὰ τῶν χρημάτων αἰτίαν μισόδημος εἶναι, τότε δὴ οὗτος, ὦ ἑταῖρε, κατὰ τὸν Κροίσῳ γενόμενον χρησμὸν- . . . πολυψήφιδα παρ᾽ Ἕρμον","st":"566c"},{"sp":"N","t":"φεύγει, οὐδὲ μένει, οὐδ᾽ αἰδεῖται κακὸς εἶναι.","st":"566c"},{"sp":"N","t":"οὐ γὰρ ἄν, ἔφη, δεύτερον αὖθις αἰδεσθείη.","st":"566c"},{"sp":"N","t":"ὁ δέ γε οἶμαι, ἦν δ᾽ ἐγώ, καταληφθεὶς θανάτῳ δίδοται.","st":"566c"},{"sp":"N","t":"ἀνάγκη.","st":"566c"},{"sp":"N","t":"ὁ δὲ δὴ προστάτης ἐκεῖνος αὐτὸς δῆλον δὴ ὅτι","st":"566c"},{"sp":"N","t":"μέγας","st":"566c"},{"sp":"N","t":"μεγαλωστὶ","st":"566d"},{"sp":"N","t":"οὐ κεῖται, ἀλλὰ καταβαλὼν ἄλλους πολλοὺς ἕστηκεν ἐν τῷ δίφρῳ τῆς πόλεως, τύραννος ἀντὶ προστάτου ἀποτετελεσμένος.","st":"566d"},{"sp":"N","t":"τί δ᾽ οὐ μέλλει; ἔφη.","st":"566d"},{"sp":"N","t":"διέλθωμεν δὴ τὴν εὐδαιμονίαν, ἦν δ᾽ ἐγώ, τοῦ τε ἀνδρὸς καὶ τῆς πόλεως, ἐν ᾗ ἂν ὁ τοιοῦτος βροτὸς ἐγγένηται;","st":"566d"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη, διέλθωμεν.","st":"566d"},{"sp":"N","t":"ἆρ᾽ οὖν, εἶπον, οὐ ταῖς μὲν πρώταις ἡμέραις τε καὶ χρόνῳ προσγελᾷ τε καὶ ἀσπάζεται πάντας, ᾧ ἂν περιτυγχάνῃ, καὶ","st":"566d"},{"sp":"N","t":"οὔτε τύραννός φησιν εἶναι ὑπισχνεῖταί τε πολλὰ καὶ ἰδίᾳ καὶ δημοσίᾳ, χρεῶν τε ἠλευθέρωσε καὶ γῆν διένειμε δήμῳ τε καὶ τοῖς περὶ ἑαυτὸν καὶ πᾶσιν ἵλεώς τε καὶ πρᾷος εἶναι προσποιεῖται;","st":"566e"},{"sp":"N","t":"ἀνάγκη, ἔφη.","st":"566e"},{"sp":"N","t":"ὅταν δέ γε οἶμαι πρὸς τοὺς ἔξω ἐχθροὺς τοῖς μὲν καταλλαγῇ, τοὺς δὲ καὶ διαφθείρῃ, καὶ ἡσυχία ἐκείνων γένηται, πρῶτον μὲν πολέμους τινὰς ἀεὶ κινεῖ, ἵν᾽ ἐν χρείᾳ ἡγεμόνος ὁ δῆμος ᾖ.","st":"566e"},{"sp":"N","t":"εἰκός γε.","st":"566e"},{"sp":"N","t":"οὐκοῦν καὶ ἵνα χρήματα εἰσφέροντες πένητες γιγνόμενοι πρὸς τῷ καθ᾽ ἡμέραν ἀναγκάζωνται εἶναι καὶ ἧττον αὐτῷ ἐπιβουλεύωσι;","st":"567a"},{"sp":"N","t":"δῆλον.","st":"567a"},{"sp":"N","t":"καὶ ἄν γέ τινας οἶμαι ὑποπτεύῃ ἐλεύθερα φρονήματα ἔχοντας μὴ ἐπιτρέψειν αὐτῷ ἄρχειν, ὅπως ἂν τούτους μετὰ προφάσεως ἀπολλύῃ ἐνδοὺς τοῖς πολεμίοις; τούτων πάντων","st":"567a"},{"sp":"N","t":"ἕνεκα τυράννῳ ἀεὶ ἀνάγκη πόλεμον ταράττειν;","st":"567a"},{"sp":"N","t":"ἀνάγκη.","st":"567a"},{"sp":"N","t":"ταῦτα δὴ ποιοῦντα ἕτοιμον μᾶλλον ἀπεχθάνεσθαι τοῖς","st":"567a"},{"sp":"N","t":"πολίταις;","st":"567b"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"567b"},{"sp":"N","t":"οὐκοῦν καί τινας τῶν συγκαταστησάντων καὶ ἐν δυνάμει ὄντων παρρησιάζεσθαι καὶ πρὸς αὐτὸν καὶ πρὸς ἀλλήλους, ἐπιπλήττοντας τοῖς γιγνομένοις, οἳ ἂν τυγχάνωσιν ἀνδρικώτατοι ὄντες;","st":"567b"},{"sp":"N","t":"εἰκός γε.","st":"567b"},{"sp":"N","t":"ὑπεξαιρεῖν δὴ τούτους πάντας δεῖ τὸν τύραννον, εἰ μέλλει ἄρξειν, ἕως ἂν μήτε φίλων μήτ᾽ ἐχθρῶν λίπῃ μηδένα ὅτου τι ὄφελος.","st":"567b"},{"sp":"N","t":"δῆλον.","st":"567b"},{"sp":"N","t":"ὀξέως ἄρα δεῖ ὁρᾶν αὐτὸν τίς ἀνδρεῖος, τίς μεγαλόφρων,","st":"567b"},{"sp":"N","t":"τίς φρόνιμος, τίς πλούσιος: καὶ οὕτως εὐδαίμων ἐστίν, ὥστε τούτοις ἅπασιν ἀνάγκη αὐτῷ, εἴτε βούλεται εἴτε μή, πολεμίῳ εἶναι καὶ ἐπιβουλεύειν, ἕως ἂν καθήρῃ τὴν πόλιν.","st":"567c"},{"sp":"N","t":"καλόν γε, ἔφη, καθαρμόν.","st":"567c"},{"sp":"N","t":"ναί, ἦν δ᾽ ἐγώ, τὸν ἐναντίον ἢ οἱ ἰατροὶ τὰ σώματα: οἱ μὲν γὰρ τὸ χείριστον ἀφαιροῦντες λείπουσι τὸ βέλτιστον, ὁ δὲ τοὐναντίον.","st":"567c"},{"sp":"N","t":"ὡς ἔοικε γάρ, αὐτῷ, ἔφη, ἀνάγκη, εἴπερ ἄρξει.","st":"567c"},{"sp":"N","t":"ἐν μακαρίᾳ ἄρα, εἶπον ἐγώ, ἀνάγκῃ δέδεται, ἣ προστάττει αὐτῷ ἢ μετὰ φαύλων τῶν πολλῶν οἰκεῖν, καὶ ὑπὸ τούτων μισούμενον, ἢ μὴ ζῆν.","st":"567d"},{"sp":"N","t":"ἐν τοιαύτῃ, ἦ δ᾽ ὅς.","st":"567d"},{"sp":"N","t":"ἆρ᾽ οὖν οὐχὶ ὅσῳ ἂν μᾶλλον τοῖς πολίταις ἀπεχθάνηται ταῦτα δρῶν, τοσούτῳ πλειόνων καὶ πιστοτέρων δορυφόρων δεήσεται;","st":"567d"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"567d"},{"sp":"N","t":"τίνες οὖν οἱ πιστοί; καὶ πόθεν αὐτοὺς μεταπέμψεται;","st":"567d"},{"sp":"N","t":"αὐτόματοι, ἔφη, πολλοὶ ἥξουσι πετόμενοι, ἐὰν τὸν μισθὸν διδῷ.","st":"567d"},{"sp":"N","t":"κηφῆνας, ἦν δ᾽ ἐγώ, νὴ τὸν κύνα, δοκεῖς αὖ τινάς μοι","st":"567d"},{"sp":"N","t":"λέγειν ξενικούς τε καὶ παντοδαπούς.","st":"567e"},{"sp":"N","t":"ἀληθῆ γάρ, ἔφη, δοκῶ σοι.","st":"567e"},{"sp":"N","t":"τίς δὲ αὐτόθεν; ἆρ᾽ οὐκ ἂν ἐθελήσειεν-","st":"567e"},{"sp":"N","t":"πῶς;","st":"567e"},{"sp":"N","t":"τοὺς δούλους ἀφελόμενος τοὺς πολίτας, ἐλευθερώσας, τῶν περὶ ἑαυτὸν δορυφόρων ποιήσασθαι.","st":"567e"},{"sp":"N","t":"σφόδρα γ᾽, ἔφη: ἐπεί τοι καὶ πιστότατοι αὐτῷ οὗτοί εἰσιν.","st":"567e"},{"sp":"N","t":"ἦ μακάριον, ἦν δ᾽ ἐγώ, λέγεις τυράννου χρῆμα, εἰ τοιούτοις","st":"567e"},{"sp":"N","t":"φίλοις τε καὶ πιστοῖς ἀνδράσι χρῆται, τοὺς προτέρους ἐκείνους ἀπολέσας.","st":"568a"},{"sp":"N","t":"ἀλλὰ μήν, ἔφη, τοιούτοις γε χρῆται.","st":"568a"},{"sp":"N","t":"καὶ θαυμάζουσι δή, εἶπον, οὗτοι οἱ ἑταῖροι αὐτὸν καὶ σύνεισιν οἱ νέοι πολῖται, οἱ δ᾽ ἐπιεικεῖς μισοῦσί τε καὶ φεύγουσι;","st":"568a"},{"sp":"N","t":"τί δ᾽ οὐ μέλλουσιν;","st":"568a"},{"sp":"N","t":"οὐκ ἐτός, ἦν δ᾽ ἐγώ, ἥ τε τραγῳδία ὅλως σοφὸν δοκεῖ εἶναι καὶ ὁ Εὐριπίδης διαφέρων ἐν αὐτῇ.","st":"568a"},{"sp":"N","t":"τί δή;","st":"568a"},{"sp":"N","t":"ὅτι καὶ τοῦτο πυκνῆς διανοίας ἐχόμενον ἐφθέγξατο, ὡς","st":"568a"},{"sp":"N","t":"ἄρα “σοφοὶ τύραννοί” εἰσι “τῶν σοφῶν συνουσίᾳ.” καὶ ἔλεγε δῆλον ὅτι τούτους εἶναι τοὺς σοφοὺς οἷς σύνεστιν.","st":"568b"},{"sp":"N","t":"καὶ ὡς ἰσόθεόν γ᾽, ἔφη, τὴν τυραννίδα ἐγκωμιάζει, καὶ ἕτερα πολλά, καὶ οὗτος καὶ οἱ ἄλλοι ποιηταί.","st":"568b"},{"sp":"N","t":"τοιγάρτοι, ἔφην, ἅτε σοφοὶ ὄντες οἱ τῆς τραγῳδίας ποιηταὶ συγγιγνώσκουσιν ἡμῖν τε καὶ ἐκείνοις ὅσοι ἡμῶν ἐγγὺς πολιτεύονται, ὅτι αὐτοὺς εἰς τὴν πολιτείαν οὐ παραδεξόμεθα ἅτε τυραννίδος ὑμνητάς.","st":"568b"},{"sp":"N","t":"οἶμαι ἔγωγ᾽, ἔφη, συγγιγνώσκουσιν ὅσοιπέρ γε αὐτῶν","st":"568b"},{"sp":"N","t":"κομψοί.","st":"568c"},{"sp":"N","t":"εἰς δέ γε οἶμαι τὰς ἄλλας περιιόντες πόλεις, συλλέγοντες τοὺς ὄχλους, καλὰς φωνὰς καὶ μεγάλας καὶ πιθανὰς μισθωσάμενοι, εἰς τυραννίδας τε καὶ δημοκρατίας ἕλκουσι τὰς πολιτείας.","st":"568c"},{"sp":"N","t":"μάλα γε.","st":"568c"},{"sp":"N","t":"οὐκοῦν καὶ προσέτι τούτων μισθοὺς λαμβάνουσι καὶ τιμῶνται, μάλιστα μέν, ὥσπερ τὸ εἰκός, ὑπὸ τυράννων, δεύτερον δὲ ὑπὸ δημοκρατίας: ὅσῳ δ᾽ ἂν ἀνωτέρω ἴωσιν πρὸς","st":"568c"},{"sp":"N","t":"τὸ ἄναντες τῶν πολιτειῶν, μᾶλλον ἀπαγορεύει αὐτῶν ἡ τιμή, ὥσπερ ὑπὸ ἄσθματος ἀδυνατοῦσα πορεύεσθαι.","st":"568d"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"568d"},{"sp":"N","t":"ἀλλὰ δή, εἶπον, ἐνταῦθα μὲν ἐξέβημεν: λέγωμεν δὲ πάλιν ἐκεῖνο τὸ τοῦ τυράννου στρατόπεδον, τὸ καλόν τε καὶ πολὺ καὶ ποικίλον καὶ οὐδέποτε ταὐτόν, πόθεν θρέψεται. δῆλον, ἔφη, ὅτι, ἐάν τε ἱερὰ χρήματα ᾖ ἐν τῇ πόλει, ταῦτα ἀναλώσει, ὅποι ποτὲ ἂν ἀεὶ ἐξαρκῇ τὰ τῶν ἀποδομένων, ἐλάττους εἰσφορὰς ἀναγκάζων τὸν δῆμον εἰσφέρειν.","st":"568d"},{"sp":"N","t":"τί δ᾽ ὅταν δὴ ταῦτα ἐπιλίπῃ;","st":"568e"},{"sp":"N","t":"δῆλον, ἔφη, ὅτι ἐκ τῶν πατρῴων θρέψεται αὐτός τε καὶ οἱ συμπόται τε καὶ ἑταῖροι καὶ ἑταῖραι.","st":"568e"},{"sp":"N","t":"μανθάνω, ἦν δ᾽ ἐγώ: ὅτι ὁ δῆμος ὁ γεννήσας τὸν τύραννον θρέψει αὐτόν τε καὶ ἑταίρους.","st":"568e"},{"sp":"N","t":"πολλὴ αὐτῷ, ἔφη, ἀνάγκη.","st":"568e"},{"sp":"N","t":"πῶς [δὲ] λέγεις; εἶπον: ἐὰν δὲ ἀγανακτῇ τε καὶ λέγῃ ὁ δῆμος ὅτι οὔτε δίκαιον τρέφεσθαι ὑπὸ πατρὸς ὑὸν ἡβῶντα, ἀλλὰ τοὐναντίον ὑπὸ ὑέος πατέρα, οὔτε τούτου αὐτὸν ἕνεκα","st":"568e"},{"sp":"N","t":"ἐγέννησέν τε καὶ κατέστησεν, ἵνα, ἐπειδὴ μέγας γένοιτο, τότε αὐτὸς δουλεύων τοῖς αὑτοῦ δούλοις τρέφοι ἐκεῖνόν τε καὶ τοὺς δούλους μετὰ συγκλύδων ἄλλων, ἀλλ᾽ ἵνα ἀπὸ τῶν πλουσίων τε καὶ καλῶν κἀγαθῶν λεγομένων ἐν τῇ πόλει ἐλευθερωθείη ἐκείνου προστάντος, καὶ νῦν κελεύει ἀπιέναι ἐκ τῆς πόλεως αὐτόν τε καὶ τοὺς ἑταίρους, ὥσπερ πατὴρ ὑὸν ἐξ οἰκίας μετὰ ὀχληρῶν συμποτῶν ἐξελαύνων;","st":"569a"},{"sp":"N","t":"γνώσεταί γε, νὴ Δία, ἦ δ᾽ ὅς, τότ᾽ ἤδη ὁ δῆμος οἷος οἷον","st":"569a"},{"sp":"N","t":"θρέμμα γεννῶν ἠσπάζετό τε καὶ ηὖξεν, καὶ ὅτι ἀσθενέστερος ὢν ἰσχυροτέρους ἐξελαύνει.","st":"569b"},{"sp":"N","t":"πῶς, ἦν δ᾽ ἐγώ, λέγεις; τολμήσει τὸν πατέρα βιάζεσθαι, κἂν μὴ πείθηται, τύπτειν ὁ τύραννος;","st":"569b"},{"sp":"N","t":"ναί, ἔφη, ἀφελόμενός γε τὰ ὅπλα.","st":"569b"},{"sp":"N","t":"πατραλοίαν, ἦν δ᾽ ἐγώ, λέγεις τύραννον καὶ χαλεπὸν γηροτρόφον, καὶ ὡς ἔοικε τοῦτο δὴ ὁμολογουμένη ἂν ἤδη τυραννὶς εἴη, καί, τὸ λεγόμενον, ὁ δῆμος φεύγων ἂν καπνὸν","st":"569b"},{"sp":"N","t":"δουλείας ἐλευθέρων εἰς πῦρ δούλων δεσποτείας ἂν ἐμπεπτωκὼς εἴη, ἀντὶ τῆς πολλῆς ἐκείνης καὶ ἀκαίρου ἐλευθερίας τὴν χαλεπωτάτην τε καὶ πικροτάτην δούλων δουλείαν μεταμπισχόμενος.","st":"569c"},{"sp":"N","t":"καὶ μάλα, ἔφη, ταῦτα οὕτω γίγνεται.","st":"569c"},{"sp":"N","t":"τί οὖν; εἶπον: οὐκ ἐμμελῶς ἡμῖν εἰρήσεται, ἐὰν φῶμεν ἱκανῶς διεληλυθέναι ὡς μεταβαίνει τυραννὶς ἐκ δημοκρατίας, γενομένη τε οἵα ἐστίν;","st":"569c"},{"sp":"N","t":"πάνυ μὲν οὖν ἱκανῶς, ἔφη.","st":"569c"},{"sp":"N","t":"ΣΩΚΡΆΤΗς, ΑΔΕΊΜΑΝΤΟς","st":"569c"},{"sp":"N","t":"αὐτὸς δὴ λοιπός, ἦν δ᾽ ἐγώ, ὁ τυραννικὸς ἀνὴρ σκέψασθαι, πῶς τε μεθίσταται ἐκ δημοκρατικοῦ, γενόμενός τε ποῖός τίς ἐστιν καὶ τίνα τρόπον ζῇ, ἄθλιον ἢ μακάριον.","st":"571a"},{"sp":"N","t":"λοιπὸς γὰρ οὖν ἔτι οὗτος, ἔφη.","st":"571a"},{"sp":"N","t":"οἶσθ᾽ οὖν, ἦν δ᾽ ἐγώ, ὃ ποθῶ ἔτι;","st":"571a"},{"sp":"N","t":"τὸ ποῖον;","st":"571a"},{"sp":"N","t":"τὸ τῶν ἐπιθυμιῶν, οἷαί τε καὶ ὅσαι εἰσίν, οὔ μοι δοκοῦμεν ἱκανῶς διῃρῆσθαι. τούτου δὴ ἐνδεῶς ἔχοντος, ἀσαφεστέρα","st":"571a"},{"sp":"N","t":"ἔσται ἡ ζήτησις οὗ ζητοῦμεν. οὐκοῦν, ἦ δ᾽ ὅς, ἔτ᾽ ἐν καλῷ;","st":"571b"},{"sp":"N","t":"πάνυ μὲν οὖν: καὶ σκόπει γε ὃ ἐν αὐταῖς βούλομαι ἰδεῖν. ἔστιν δὲ τόδε. τῶν μὴ ἀναγκαίων ἡδονῶν τε καὶ ἐπιθυμιῶν δοκοῦσί τινές μοι εἶναι παράνομοι, αἳ κινδυνεύουσι μὲν ἐγγίγνεσθαι παντί, κολαζόμεναι δὲ ὑπό τε τῶν νόμων καὶ τῶν βελτιόνων ἐπιθυμιῶν μετὰ λόγου ἐνίων μὲν ἀνθρώπων ἢ παντάπασιν ἀπαλλάττεσθαι ἢ ὀλίγαι λείπεσθαι καὶ ἀσθενεῖς,","st":"571b"},{"sp":"N","t":"τῶν δὲ ἰσχυρότεραι καὶ πλείους.","st":"571c"},{"sp":"N","t":"λέγεις δὲ καὶ τίνας, ἔφη, ταύτας;","st":"571c"},{"sp":"N","t":"τὰς περὶ τὸν ὕπνον, ἦν δ᾽ ἐγώ, ἐγειρομένας, ὅταν τὸ μὲν ἄλλο τῆς ψυχῆς εὕδῃ, ὅσον λογιστικὸν καὶ ἥμερον καὶ ἄρχον ἐκείνου, τὸ δὲ θηριῶδές τε καὶ ἄγριον, ἢ σίτων ἢ μέθης πλησθέν, σκιρτᾷ τε καὶ ἀπωσάμενον τὸν ὕπνον ζητῇ ἰέναι καὶ ἀποπιμπλάναι τὰ αὑτοῦ ἤθη: οἶσθ᾽ ὅτι πάντα ἐν τῷ τοιούτῳ τολμᾷ ποιεῖν, ὡς ἀπὸ πάσης λελυμένον τε καὶ ἀπηλλαγμένον αἰσχύνης καὶ φρονήσεως. μητρί τε γὰρ ἐπιχειρεῖν","st":"571c"},{"sp":"N","t":"μείγνυσθαι, ὡς οἴεται, οὐδὲν ὀκνεῖ, ἄλλῳ τε ὁτῳοῦν ἀνθρώπων καὶ θεῶν καὶ θηρίων, μιαιφονεῖν τε ὁτιοῦν, βρώματός τε ἀπέχεσθαι μηδενός: καὶ ἑνὶ λόγῳ οὔτε ἀνοίας οὐδὲν ἐλλείπει οὔτ᾽ ἀναισχυντίας.","st":"571d"},{"sp":"N","t":"ἀληθέστατα, ἔφη, λέγεις.","st":"571d"},{"sp":"N","t":"ὅταν δέ γε οἶμαι ὑγιεινῶς τις ἔχῃ αὐτὸς αὑτοῦ καὶ σωφρόνως, καὶ εἰς τὸν ὕπνον ἴῃ τὸ λογιστικὸν μὲν ἐγείρας ἑαυτοῦ καὶ ἑστιάσας λόγων καλῶν καὶ σκέψεων, εἰς σύννοιαν","st":"571d"},{"sp":"N","t":"αὐτὸς αὑτῷ ἀφικόμενος, τὸ ἐπιθυμητικὸν δὲ μήτε ἐνδείᾳ δοὺς μήτε πλησμονῇ, ὅπως ἂν κοιμηθῇ καὶ μὴ παρέχῃ θόρυβον","st":"571e"},{"sp":"N","t":"τῷ βελτίστῳ χαῖρον ἢ λυπούμενον, ἀλλ᾽ ἐᾷ αὐτὸ καθ᾽ αὑτὸ μόνον καθαρὸν σκοπεῖν καὶ ὀρέγεσθαί του αἰσθάνεσθαι ὃ μὴ οἶδεν, ἤ τι τῶν γεγονότων ἢ ὄντων ἢ καὶ μελλόντων, ὡσαύτως δὲ καὶ τὸ θυμοειδὲς πραΰνας καὶ μή τισιν εἰς ὀργὰς ἐλθὼν κεκινημένῳ τῷ θυμῷ καθεύδῃ, ἀλλ᾽ ἡσυχάσας μὲν τὼ δύο εἴδη, τὸ τρίτον δὲ κινήσας ἐν ᾧ τὸ φρονεῖν ἐγγίγνεται, οὕτως ἀναπαύηται, οἶσθ᾽ ὅτι τῆς τ᾽ ἀληθείας ἐν τῷ τοιούτῳ μάλιστα ἅπτεται καὶ ἥκιστα παράνομοι τότε αἱ ὄψεις","st":"572a"},{"sp":"N","t":"φαντάζονται τῶν ἐνυπνίων.","st":"572b"},{"sp":"N","t":"παντελῶς μὲν οὖν, ἔφη, οἶμαι οὕτως.","st":"572b"},{"sp":"N","t":"ταῦτα μὲν τοίνυν ἐπὶ πλέον ἐξήχθημεν εἰπεῖν: ὃ δὲ βουλόμεθα γνῶναι τόδ᾽ ἐστίν, ὡς ἄρα δεινόν τι καὶ ἄγριον καὶ ἄνομον ἐπιθυμιῶν εἶδος ἑκάστῳ ἔνεστι, καὶ πάνυ δοκοῦσιν ἡμῶν ἐνίοις μετρίοις εἶναι: τοῦτο δὲ ἄρα ἐν τοῖς ὕπνοις γίγνεται ἔνδηλον. εἰ οὖν τι δοκῶ λέγειν καὶ συγχωρεῖς, ἄθρει.","st":"572b"},{"sp":"N","t":"ἀλλὰ συγχωρῶ.","st":"572b"},{"sp":"N","t":"τὸν τοίνυν δημοτικὸν ἀναμνήσθητι οἷον ἔφαμεν εἶναι.","st":"572b"},{"sp":"N","t":"ἦν δέ που γεγονὼς ἐκ νέου ὑπὸ φειδωλῷ πατρὶ τεθραμμένος, τὰς χρηματιστικὰς ἐπιθυμίας τιμῶντι μόνας, τὰς δὲ μὴ ἀναγκαίους ἀλλὰ παιδιᾶς τε καὶ καλλωπισμοῦ ἕνεκα γιγνομένας ἀτιμάζοντι. ἦ γάρ;","st":"572c"},{"sp":"N","t":"ναί.","st":"572c"},{"sp":"N","t":"συγγενόμενος δὲ κομψοτέροις ἀνδράσι καὶ μεστοῖς ὧν ἄρτι διήλθομεν ἐπιθυμιῶν, ὁρμήσας εἰς ὕβριν τε πᾶσαν καὶ τὸ ἐκείνων εἶδος μίσει τῆς τοῦ πατρὸς φειδωλίας, φύσιν δὲ τῶν διαφθειρόντων βελτίω ἔχων, ἀγόμενος ἀμφοτέρωσε","st":"572c"},{"sp":"N","t":"κατέστη εἰς μέσον ἀμφοῖν τοῖν τρόποιν, καὶ μετρίως δή, ὡς ᾤετο, ἑκάστων ἀπολαύων οὔτε ἀνελεύθερον οὔτε παράνομον βίον ζῇ, δημοτικὸς ἐξ ὀλιγαρχικοῦ γεγονώς.","st":"572d"},{"sp":"N","t":"ἦν γάρ, ἔφη, καὶ ἔστιν αὕτη ἡ δόξα περὶ τὸν τοιοῦτον.","st":"572d"},{"sp":"N","t":"θὲς τοίνυν, ἦν δ᾽ ἐγώ, πάλιν τοῦ τοιούτου ἤδη πρεσβυτέρου γεγονότος νέον ὑὸν ἐν τοῖς τούτου αὖ ἤθεσιν τεθραμμένον.","st":"572d"},{"sp":"N","t":"τίθημι.","st":"572d"},{"sp":"N","t":"τίθει τοίνυν καὶ τὰ αὐτὰ ἐκεῖνα περὶ αὐτὸν γιγνόμενα ἅπερ καὶ περὶ τὸν πατέρα αὐτοῦ, ἀγόμενόν τε εἰς πᾶσαν","st":"572d"},{"sp":"N","t":"παρανομίαν, ὀνομαζομένην δ᾽ ὑπὸ τῶν ἀγόντων ἐλευθερίαν ἅπασαν, βοηθοῦντά τε ταῖς ἐν μέσῳ ταύταις ἐπιθυμίαις πατέρα τε καὶ τοὺς ἄλλους οἰκείους, τοὺς δ᾽ αὖ παραβοηθοῦντας: ὅταν δ᾽ ἐλπίσωσιν οἱ δεινοὶ μάγοι τε καὶ τυραννοποιοὶ οὗτοι μὴ ἄλλως τὸν νέον καθέξειν, ἔρωτά τινα αὐτῷ μηχανωμένους ἐμποιῆσαι προστάτην τῶν ἀργῶν καὶ τὰ","st":"572e"},{"sp":"N","t":"ἕτοιμα διανεμομένων ἐπιθυμιῶν, ὑπόπτερον καὶ μέγαν κηφῆνά τινα — ἢ τί ἄλλο οἴει εἶναι τὸν τῶν τοιούτων ἔρωτα; -","st":"573a"},{"sp":"N","t":"οὐδὲν ἔγωγε, ἦ δ᾽ ὅς, ἄλλ᾽ ἢ τοῦτο.","st":"573a"},{"sp":"N","t":"οὐκοῦν ὅταν δὴ περὶ αὐτὸν βομβοῦσαι αἱ ἄλλαι ἐπιθυμίαι, θυμιαμάτων τε γέμουσαι καὶ μύρων καὶ στεφάνων καὶ οἴνων καὶ τῶν ἐν ταῖς τοιαύταις συνουσίαις ἡδονῶν ἀνειμένων, ἐπὶ τὸ ἔσχατον αὔξουσαί τε καὶ τρέφουσαι πόθου κέντρον ἐμποιήσωσι τῷ κηφῆνι, τότε δὴ δορυφορεῖταί τε ὑπὸ μανίας καὶ","st":"573a"},{"sp":"N","t":"οἰστρᾷ οὗτος ὁ προστάτης τῆς ψυχῆς, καὶ ἐάν τινας ἐν αὐτῷ δόξας ἢ ἐπιθυμίας λάβῃ ποιουμένας χρηστὰς καὶ ἔτι ἐπαισχυνομένας, ἀποκτείνει τε καὶ ἔξω ὠθεῖ παρ᾽ αὑτοῦ, ἕως ἂν καθήρῃ σωφροσύνης, μανίας δὲ πληρώσῃ ἐπακτοῦ.","st":"573b"},{"sp":"N","t":"παντελῶς, ἔφη, τυραννικοῦ ἀνδρὸς λέγεις γένεσιν.","st":"573b"},{"sp":"N","t":"ἆρ᾽ οὖν, ἦν δ᾽ ἐγώ, καὶ τὸ πάλαι διὰ τὸ τοιοῦτον τύραννος ὁ Ἔρως λέγεται;","st":"573b"},{"sp":"N","t":"κινδυνεύει, ἔφη.","st":"573b"},{"sp":"N","t":"οὐκοῦν, ὦ φίλε, εἶπον, καὶ μεθυσθεὶς ἀνὴρ τυραννικόν τι","st":"573b"},{"sp":"N","t":"φρόνημα ἴσχει;","st":"573c"},{"sp":"N","t":"ἴσχει γάρ.","st":"573c"},{"sp":"N","t":"καὶ μὴν ὅ γε μαινόμενος καὶ ὑποκεκινηκὼς οὐ μόνον ἀνθρώπων ἀλλὰ καὶ θεῶν ἐπιχειρεῖ τε καὶ ἐλπίζει δυνατὸς εἶναι ἄρχειν.","st":"573c"},{"sp":"N","t":"καὶ μάλ᾽, ἔφη.","st":"573c"},{"sp":"N","t":"τυραννικὸς δέ, ἦν δ᾽ ἐγώ, ὦ δαιμόνιε, ἀνὴρ ἀκριβῶς γίγνεται, ὅταν ἢ φύσει ἢ ἐπιτηδεύμασιν ἢ ἀμφοτέροις μεθυστικός τε καὶ ἐρωτικὸς καὶ μελαγχολικὸς γένηται.","st":"573c"},{"sp":"N","t":"παντελῶς μὲν οὖν.","st":"573c"},{"sp":"N","t":"γίγνεται μέν, ὡς ἔοικεν, οὕτω καὶ τοιοῦτος ἁνήρ: ζῇ δὲ δὴ πῶς;","st":"573c"},{"sp":"N","t":"τὸ τῶν παιζόντων, ἔφη, τοῦτο σὺ καὶ ἐμοὶ ἐρεῖς.","st":"573d"},{"sp":"N","t":"λέγω δή, ἔφην. οἶμαι γὰρ τὸ μετὰ τοῦτο ἑορταὶ γίγνονται παρ᾽ αὐτοῖς καὶ κῶμοι καὶ θάλειαι καὶ ἑταῖραι καὶ τὰ τοιαῦτα πάντα, ὧν ἂν Ἔρως τύραννος ἔνδον οἰκῶν διακυβερνᾷ τὰ τῆς ψυχῆς ἅπαντα.","st":"573d"},{"sp":"N","t":"ἀνάγκη, ἔφη.","st":"573d"},{"sp":"N","t":"ἆρ᾽ οὖν οὐ πολλαὶ καὶ δειναὶ παραβλαστάνουσιν ἐπιθυμίαι ἡμέρας τε καὶ νυκτὸς ἑκάστης, πολλῶν δεόμεναι;","st":"573d"},{"sp":"N","t":"πολλαὶ μέντοι.","st":"573d"},{"sp":"N","t":"ταχὺ ἄρα ἀναλίσκονται ἐάν τινες ὦσι πρόσοδοι.","st":"573d"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"573d"},{"sp":"N","t":"καὶ μετὰ τοῦτο δὴ δανεισμοὶ καὶ τῆς οὐσίας παραιρέσεις.","st":"573e"},{"sp":"N","t":"τί μήν;","st":"573e"},{"sp":"N","t":"ὅταν δὲ δὴ πάντ᾽ ἐπιλείπῃ, ἆρα οὐκ ἀνάγκη μὲν τὰς ἐπιθυμίας βοᾶν πυκνάς τε καὶ σφοδρὰς ἐννενεοττευμένας, τοὺς δ᾽ ὥσπερ ὑπὸ κέντρων ἐλαυνομένους τῶν τε ἄλλων ἐπιθυμιῶν καὶ διαφερόντως ὑπ᾽ αὐτοῦ τοῦ Ἔρωτος, πάσαις ταῖς ἄλλαις ὥσπερ δορυφόροις ἡγουμένου, οἰστρᾶν καὶ σκοπεῖν τίς τι ἔχει, ὃν δυνατὸν ἀφελέσθαι ἀπατήσαντα ἢ","st":"573e"},{"sp":"N","t":"βιασάμενον;","st":"574a"},{"sp":"N","t":"σφόδρα γ᾽, ἔφη.","st":"574a"},{"sp":"N","t":"ἀναγκαῖον δὴ πανταχόθεν φέρειν, ἢ μεγάλαις ὠδῖσί τε καὶ ὀδύναις συνέχεσθαι.","st":"574a"},{"sp":"N","t":"ἀναγκαῖον.","st":"574a"},{"sp":"N","t":"ἆρ᾽ οὖν, ὥσπερ αἱ ἐν αὐτῷ ἡδοναὶ ἐπιγιγνόμεναι τῶν ἀρχαίων πλέον εἶχον καὶ τὰ ἐκείνων ἀφῃροῦντο, οὕτω καὶ αὐτὸς ἀξιώσει νεώτερος ὢν πατρός τε καὶ μητρὸς πλέον ἔχειν, καὶ ἀφαιρεῖσθαι, ἐὰν τὸ αὑτοῦ μέρος ἀναλώσῃ, ἀπονειμάμενος τῶν πατρῴων;","st":"574a"},{"sp":"N","t":"ἀλλὰ τί μήν; ἔφη.","st":"574a"},{"sp":"N","t":"ἂν δὲ δὴ αὐτῷ μὴ ἐπιτρέπωσιν, ἆρ᾽ οὐ τὸ μὲν πρῶτον ἐπιχειροῖ ἂν κλέπτειν καὶ ἀπατᾶν τοὺς γονέας;","st":"574b"},{"sp":"N","t":"πάντως.","st":"574b"},{"sp":"N","t":"ὁπότε δὲ μὴ δύναιτο, ἁρπάζοι ἂν καὶ βιάζοιτο μετὰ τοῦτο;","st":"574b"},{"sp":"N","t":"οἶμαι, ἔφη.","st":"574b"},{"sp":"N","t":"ἀντεχομένων δὴ καὶ μαχομένων, ὦ θαυμάσιε, γέροντός τε καὶ γραός, ἆρ᾽ εὐλαβηθείη ἂν καὶ φείσαιτο μή τι δρᾶσαι τῶν τυραννικῶν;","st":"574b"},{"sp":"N","t":"οὐ πάνυ, ἦ δ᾽ ὅς, ἔγωγε θαρρῶ περὶ τῶν γονέων τοῦ τοιούτου.","st":"574b"},{"sp":"N","t":"ἀλλ᾽, ὦ Ἀδείμαντε, πρὸς Διός, ἕνεκα νεωστὶ φίλης καὶ οὐκ ἀναγκαίας ἑταίρας γεγονυίας τὴν πάλαι φίλην καὶ ἀναγκαίαν","st":"574b"},{"sp":"N","t":"μητέρα, ἢ ἕνεκα ὡραίου νεωστὶ φίλου γεγονότος οὐκ ἀναγκαίου τὸν ἄωρόν τε καὶ ἀναγκαῖον πρεσβύτην πατέρα καὶ τῶν φίλων ἀρχαιότατον δοκεῖ ἄν σοι ὁ τοιοῦτος πληγαῖς τε δοῦναι καὶ καταδουλώσασθαι ἂν αὐτοὺς ὑπ᾽ ἐκείνοις, εἰ εἰς τὴν αὐτὴν οἰκίαν ἀγάγοιτο;","st":"574c"},{"sp":"N","t":"ναὶ μὰ Δία, ἦ δ᾽ ὅς.","st":"574c"},{"sp":"N","t":"σφόδρα γε μακάριον, ἦν δ᾽ ἐγώ, ἔοικεν εἶναι τὸ τυραννικὸν ὑὸν τεκεῖν.","st":"574c"},{"sp":"N","t":"πάνυ γ᾽, ἔφη.","st":"574c"},{"sp":"N","t":"τί δ᾽, ὅταν δὴ τὰ πατρὸς καὶ μητρὸς ἐπιλείπῃ τὸν τοιοῦτον, πολὺ δὲ ἤδη συνειλεγμένον ἐν αὐτῷ ᾖ τὸ τῶν ἡδονῶν σμῆνος, οὐ πρῶτον μὲν οἰκίας τινὸς ἐφάψεται τοίχου ἤ τινος ὀψὲ νύκτωρ ἰόντος τοῦ ἱματίου, μετὰ δὲ ταῦτα ἱερόν τι νεωκορήσει; καὶ ἐν τούτοις δὴ πᾶσιν, ἃς πάλαι εἶχεν δόξας ἐκ παιδὸς περὶ καλῶν τε καὶ αἰσχρῶν, τὰς δικαίας ποιουμένας, αἱ νεωστὶ ἐκ δουλείας λελυμέναι, δορυφοροῦσαι τὸν ἔρωτα, κρατήσουσι μετ᾽ ἐκείνου, αἳ πρότερον μὲν ὄναρ","st":"574d"},{"sp":"N","t":"ἐλύοντο ἐν ὕπνῳ, ὅτε ἦν αὐτὸς ἔτι ὑπὸ νόμοις τε καὶ πατρὶ δημοκρατούμενος ἐν ἑαυτῷ: τυραννευθεὶς δὲ ὑπὸ Ἔρωτος, οἷος ὀλιγάκις ἐγίγνετο ὄναρ, ὕπαρ τοιοῦτος ἀεὶ γενόμενος, οὔτε τινὸς φόνου δεινοῦ ἀφέξεται οὔτε βρώματος οὔτ᾽ ἔργου,","st":"574e"},{"sp":"N","t":"ἀλλὰ τυραννικῶς ἐν αὐτῷ ὁ Ἔρως ἐν πάσῃ ἀναρχίᾳ καὶ ἀνομίᾳ ζῶν, ἅτε αὐτὸς ὢν μόναρχος, τὸν ἔχοντά τε αὐτὸν ὥσπερ πόλιν ἄξει ἐπὶ πᾶσαν τόλμαν, ὅθεν αὑτόν τε καὶ τὸν περὶ αὑτὸν θόρυβον θρέψει, τὸν μὲν ἔξωθεν εἰσεληλυθότα ἀπὸ κακῆς ὁμιλίας, τὸν δ᾽ ἔνδοθεν ὑπὸ τῶν αὐτῶν τρόπων καὶ ἑαυτοῦ ἀνεθέντα καὶ ἐλευθερωθέντα: ἢ οὐχ οὗτος ὁ βίος τοῦ τοιούτου;","st":"575a"},{"sp":"N","t":"οὗτος μὲν οὖν, ἔφη.","st":"575a"},{"sp":"N","t":"καὶ ἂν μέν γε, ἦν δ᾽ ἐγώ, ὀλίγοι οἱ τοιοῦτοι ἐν πόλει","st":"575a"},{"sp":"N","t":"ὦσι καὶ τὸ ἄλλο πλῆθος σωφρονῇ, ἐξελθόντες ἄλλον τινὰ δορυφοροῦσι τύραννον ἢ μισθοῦ ἐπικουροῦσιν, ἐάν που πόλεμος ᾖ: ἐὰν δ᾽ ἐν εἰρήνῃ τε καὶ ἡσυχίᾳ γένωνται, αὐτοῦ δὴ ἐν τῇ πόλει κακὰ δρῶσι σμικρὰ πολλά.","st":"575b"},{"sp":"N","t":"τὰ ποῖα δὴ λέγεις;","st":"575b"},{"sp":"N","t":"οἷα κλέπτουσι, τοιχωρυχοῦσι, βαλλαντιοτομοῦσι, λωποδυτοῦσιν, ἱεροσυλοῦσιν, ἀνδραποδίζονται: ἔστι δ᾽ ὅτε συκοφαντοῦσιν, ἐὰν δυνατοὶ ὦσι λέγειν, καὶ ψευδομαρτυροῦσι καὶ δωροδοκοῦσιν.","st":"575b"},{"sp":"N","t":"σμικρά γ᾽, ἔφη, κακὰ λέγεις, ἐὰν ὀλίγοι ὦσιν οἱ τοιοῦτοι.","st":"575c"},{"sp":"N","t":"τὰ γὰρ σμικρά, ἦν δ᾽ ἐγώ, πρὸς τὰ μεγάλα σμικρά ἐστιν, καὶ ταῦτα δὴ πάντα πρὸς τύραννον πονηρίᾳ τε καὶ ἀθλιότητι πόλεως, τὸ λεγόμενον, οὐδ᾽ ἵκταρ βάλλει. ὅταν γὰρ δὴ πολλοὶ ἐν πόλει γένωνται οἱ τοιοῦτοι καὶ ἄλλοι οἱ συνεπόμενοι αὐτοῖς, καὶ αἴσθωνται ἑαυτῶν τὸ πλῆθος, τότε οὗτοί εἰσιν οἱ τὸν τύραννον γεννῶντες μετὰ δήμου ἀνοίας ἐκεῖνον, ὃς ἂν αὐτῶν μάλιστα αὐτὸς ἐν αὑτῷ μέγιστον καὶ πλεῖστον","st":"575c"},{"sp":"N","t":"ἐν τῇ ψυχῇ τύραννον ἔχῃ.","st":"575d"},{"sp":"N","t":"εἰκότως γ᾽, ἔφη: τυραννικώτατος γὰρ ἂν εἴη.","st":"575d"},{"sp":"N","t":"οὐκοῦν ἐὰν μὲν ἑκόντες ὑπείκωσιν: ἐὰν δὲ μὴ ἐπιτρέπῃ ἡ πόλις, ὥσπερ τότε μητέρα καὶ πατέρα ἐκόλαζεν, οὕτω πάλιν τὴν πατρίδα, ἐὰν οἷός τ᾽ ᾖ, κολάσεται ἐπεισαγόμενος νέους ἑταίρους, καὶ ὑπὸ τούτοις δὴ δουλεύουσαν τὴν πάλαι φίλην μητρίδα τε, Κρῆτές φασι, καὶ πατρίδα ἕξει τε καὶ θρέψει. καὶ τοῦτο δὴ τὸ τέλος ἂν εἴη τῆς ἐπιθυμίας τοῦ τοιούτου ἀνδρός.","st":"575d"},{"sp":"N","t":"τοῦτο, ἦ δ᾽ ὅς, παντάπασί γε.","st":"575e"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, οὗτοί γε τοιοίδε γίγνονται ἰδίᾳ καὶ πρὶν ἄρχειν: πρῶτον μὲν οἷς ἂν συνῶσιν, ἢ κόλαξιν ἑαυτῶν συνόντες καὶ πᾶν ἑτοίμοις ὑπηρετεῖν, ἢ ἐάν τού τι δέωνται,","st":"575e"},{"sp":"N","t":"αὐτοὶ ὑποπεσόντες, πάντα σχήματα τολμῶντες ποιεῖν ὡς οἰκεῖοι, διαπραξάμενοι δὲ ἀλλότριοι;","st":"576a"},{"sp":"N","t":"καὶ σφόδρα γε.","st":"576a"},{"sp":"N","t":"ἐν παντὶ ἄρα τῷ βίῳ ζῶσι φίλοι μὲν οὐδέποτε οὐδενί, ἀεὶ δέ του δεσπόζοντες ἢ δουλεύοντες ἄλλῳ, ἐλευθερίας δὲ καὶ φιλίας ἀληθοῦς τυραννικὴ φύσις ἀεὶ ἄγευστος.","st":"576a"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"576a"},{"sp":"N","t":"ἆρ᾽ οὖν οὐκ ὀρθῶς ἂν τοὺς τοιούτους ἀπίστους καλοῖμεν;","st":"576a"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"576a"},{"sp":"N","t":"καὶ μὴν ἀδίκους γε ὡς οἷόν τε μάλιστα, εἴπερ ὀρθῶς","st":"576a"},{"sp":"N","t":"ἐν τοῖς πρόσθεν ὡμολογήσαμεν περὶ δικαιοσύνης οἷόν ἐστιν.","st":"576b"},{"sp":"N","t":"ἀλλὰ μήν, ἦ δ᾽ ὅς, ὀρθῶς γε.","st":"576b"},{"sp":"N","t":"κεφαλαιωσώμεθα τοίνυν, ἦν δ᾽ ἐγώ, τὸν κάκιστον. ἔστιν δέ που, οἷον ὄναρ διήλθομεν, ὃς ἂν ὕπαρ τοιοῦτος ᾖ.","st":"576b"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"576b"},{"sp":"N","t":"οὐκοῦν οὗτος γίγνεται ὃς ἂν τυραννικώτατος φύσει ὢν μοναρχήσῃ, καὶ ὅσῳ ἂν πλείω χρόνον ἐν τυραννίδι βιῷ, τοσούτῳ μᾶλλον τοιοῦτος.","st":"576b"},{"sp":"N","t":"ἀνάγκη, ἔφη διαδεξάμενος τὸν λόγον ὁ Γλαύκων.","st":"576b"},{"sp":"N","t":"ἆρ᾽ οὖν, ἦν δ᾽ ἐγώ, ὃς ἂν φαίνηται πονηρότατος, καὶ","st":"576b"},{"sp":"N","t":"ἀθλιώτατος φανήσεται; καὶ ὃς ἂν πλεῖστον χρόνον καὶ μάλιστα τυραννεύσῃ, μάλιστά τε καὶ πλεῖστον χρόνον τοιοῦτος γεγονὼς τῇ ἀληθείᾳ; τοῖς δὲ πολλοῖς πολλὰ καὶ δοκεῖ.","st":"576c"},{"sp":"N","t":"ἀνάγκη, ἔφη, ταῦτα γοῦν οὕτως ἔχειν.","st":"576c"},{"sp":"N","t":"ἄλλο τι οὖν, ἦν δ᾽ ἐγώ, ὅ γε τυραννικὸς κατὰ τὴν τυραννουμένην πόλιν ἂν εἴη ὁμοιότητι, δημοτικὸς δὲ κατὰ δημοκρατουμένην, καὶ οἱ ἄλλοι οὕτω;","st":"576c"},{"sp":"N","t":"τί μήν;","st":"576c"},{"sp":"N","t":"οὐκοῦν, ὅτι πόλις πρὸς πόλιν ἀρετῇ καὶ εὐδαιμονίᾳ, τοῦτο καὶ ἀνὴρ πρὸς ἄνδρα;","st":"576c"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"576d"},{"sp":"N","t":"τί οὖν ἀρετῇ τυραννουμένη πόλις πρὸς βασιλευομένην οἵαν τὸ πρῶτον διήλθομεν;","st":"576d"},{"sp":"N","t":"πᾶν τοὐναντίον, ἔφη: ἡ μὲν γὰρ ἀρίστη, ἡ δὲ κακίστη.","st":"576d"},{"sp":"N","t":"οὐκ ἐρήσομαι, εἶπον, ὁποτέραν λέγεις: δῆλον γάρ. ἀλλ᾽ εὐδαιμονίας τε αὖ καὶ ἀθλιότητος ὡσαύτως ἢ ἄλλως κρίνεις; καὶ μὴ ἐκπληττώμεθα πρὸς τὸν τύραννον ἕνα ὄντα βλέποντες, μηδ᾽ εἴ τινες ὀλίγοι περὶ ἐκεῖνον, ἀλλ᾽ ὡς χρὴ ὅλην","st":"576d"},{"sp":"N","t":"τὴν πόλιν εἰσελθόντας θεάσασθαι, καταδύντες εἰς ἅπασαν καὶ ἰδόντες, οὕτω δόξαν ἀποφαινώμεθα.","st":"576e"},{"sp":"N","t":"ἀλλ᾽ ὀρθῶς, ἔφη, προκαλῇ: καὶ δῆλον παντὶ ὅτι τυραννουμένης μὲν οὐκ ἔστιν ἀθλιωτέρα, βασιλευομένης δὲ οὐκ εὐδαιμονεστέρα.","st":"576e"},{"sp":"N","t":"ἆρ᾽ οὖν, ἦν δ᾽ ἐγώ, καὶ περὶ τῶν ἀνδρῶν τὰ αὐτὰ ταῦτα","st":"576e"},{"sp":"N","t":"προκαλούμενος ὀρθῶς ἂν προκαλοίμην, ἀξιῶν κρίνειν περὶ αὐτῶν ἐκεῖνον, ὃς δύναται τῇ διανοίᾳ εἰς ἀνδρὸς ἦθος ἐνδὺς διιδεῖν καὶ μὴ καθάπερ παῖς ἔξωθεν ὁρῶν ἐκπλήττεται ὑπὸ τῆς τῶν τυραννικῶν προστάσεως ἣν πρὸς τοὺς ἔξω σχηματίζονται, ἀλλ᾽ ἱκανῶς διορᾷ; εἰ οὖν οἰοίμην δεῖν ἐκείνου πάντας ἡμᾶς ἀκούειν, τοῦ δυνατοῦ μὲν κρῖναι, συνῳκηκότος δὲ ἐν τῷ αὐτῷ καὶ παραγεγονότος ἔν τε ταῖς κατ᾽ οἰκίαν πράξεσιν, ὡς πρὸς ἑκάστους τοὺς οἰκείους ἔχει, ἐν οἷς","st":"577a"},{"sp":"N","t":"μάλιστα γυμνὸς ἂν ὀφθείη τῆς τραγικῆς σκευῆς, καὶ ἐν αὖ τοῖς δημοσίοις κινδύνοις, καὶ ταῦτα πάντα ἰδόντα κελεύοιμεν ἐξαγγέλλειν πῶς ἔχει εὐδαιμονίας καὶ ἀθλιότητος ὁ τύραννος πρὸς τοὺς ἄλλους;","st":"577b"},{"sp":"N","t":"ὀρθότατ᾽ ἄν, ἔφη, καὶ ταῦτα προκαλοῖο.","st":"577b"},{"sp":"N","t":"βούλει οὖν, ἦν δ᾽ ἐγώ, προσποιησώμεθα ἡμεῖς εἶναι τῶν δυνατῶν ἂν κρῖναι καὶ ἤδη ἐντυχόντων τοιούτοις, ἵνα ἔχωμεν ὅστις ἀποκρινεῖται ἃ ἐρωτῶμεν;","st":"577b"},{"sp":"N","t":"πάνυ γε.","st":"577b"},{"sp":"N","t":"ἴθι δή μοι, ἔφην, ὧδε σκόπει. τὴν ὁμοιότητα ἀναμιμνῃσκόμενος τῆς τε πόλεως καὶ τοῦ ἀνδρός, οὕτω καθ᾽ ἕκαστον ἐν μέρει ἀθρῶν, τὰ παθήματα ἑκατέρου λέγε.","st":"577c"},{"sp":"N","t":"τὰ ποῖα; ἔφη.","st":"577c"},{"sp":"N","t":"πρῶτον μέν, ἦν δ᾽ ἐγώ, ὡς πόλιν εἰπεῖν, ἐλευθέραν ἢ δούλην τὴν τυραννουμένην ἐρεῖς;","st":"577c"},{"sp":"N","t":"ὡς οἷόν τ᾽, ἔφη, μάλιστα δούλην.","st":"577c"},{"sp":"N","t":"καὶ μὴν ὁρᾷς γε ἐν αὐτῇ δεσπότας καὶ ἐλευθέρους.","st":"577c"},{"sp":"N","t":"ὁρῶ, ἔφη, σμικρόν γέ τι τοῦτο: τὸ δὲ ὅλον, ὡς ἔπος εἰπεῖν, ἐν αὐτῇ καὶ τὸ ἐπιεικέστατον ἀτίμως τε καὶ ἀθλίως δοῦλον.","st":"577c"},{"sp":"N","t":"εἰ οὖν, εἶπον, ὅμοιος ἀνὴρ τῇ πόλει, οὐ καὶ ἐν ἐκείνῳ ἀνάγκη τὴν αὐτὴν τάξιν ἐνεῖναι, καὶ πολλῆς μὲν δουλείας τε καὶ ἀνελευθερίας γέμειν τὴν ψυχὴν αὐτοῦ, καὶ ταῦτα αὐτῆς τὰ μέρη δουλεύειν, ἅπερ ἦν ἐπιεικέστατα, μικρὸν δὲ καὶ τὸ μοχθηρότατον καὶ μανικώτατον δεσπόζειν;","st":"577d"},{"sp":"N","t":"ἀνάγκη, ἔφη.","st":"577d"},{"sp":"N","t":"τί οὖν; δούλην ἢ ἐλευθέραν τὴν τοιαύτην φήσεις εἶναι ψυχήν;","st":"577d"},{"sp":"N","t":"δούλην δήπου ἔγωγε.","st":"577d"},{"sp":"N","t":"οὐκοῦν ἥ γε αὖ δούλη καὶ τυραννουμένη πόλις ἥκιστα ποιεῖ ἃ βούλεται;","st":"577d"},{"sp":"N","t":"πολύ γε.","st":"577d"},{"sp":"N","t":"καὶ ἡ τυραννουμένη ἄρα ψυχὴ ἥκιστα ποιήσει ἃ ἂν βουληθῇ, ὡς περὶ ὅλης εἰπεῖν ψυχῆς: ὑπὸ δὲ οἴστρου ἀεὶ ἑλκομένη βίᾳ ταραχῆς καὶ μεταμελείας μεστὴ ἔσται.","st":"577e"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"577e"},{"sp":"N","t":"πλουσίαν δὲ ἢ πενομένην ἀνάγκη τὴν τυραννουμένην πόλιν εἶναι;","st":"577e"},{"sp":"N","t":"πενομένην.","st":"577e"},{"sp":"N","t":"καὶ ψυχὴν ἄρα τυραννικὴν πενιχρὰν καὶ ἄπληστον ἀνάγκη ἀεὶ εἶναι.","st":"578a"},{"sp":"N","t":"οὕτως, ἦ δ᾽ ὅς.","st":"578a"},{"sp":"N","t":"τί δέ; φόβου γέμειν ἆρ᾽ οὐκ ἀνάγκη τήν τε τοιαύτην πόλιν τόν τε τοιοῦτον ἄνδρα;","st":"578a"},{"sp":"N","t":"πολλή γε.","st":"578a"},{"sp":"N","t":"ὀδυρμούς τε καὶ στεναγμοὺς καὶ θρήνους καὶ ἀλγηδόνας οἴει ἔν τινι ἄλλῃ πλείους εὑρήσειν;","st":"578a"},{"sp":"N","t":"οὐδαμῶς.","st":"578a"},{"sp":"N","t":"ἐν ἀνδρὶ δὲ ἡγῇ τὰ τοιαῦτα ἐν ἄλλῳ τινὶ πλείω εἶναι ἢ ἐν τῷ μαινομένῳ ὑπὸ ἐπιθυμιῶν τε καὶ ἐρώτων τούτῳ τῷ τυραννικῷ;","st":"578a"},{"sp":"N","t":"πῶς γὰρ ἄν; ἔφη.","st":"578a"},{"sp":"N","t":"εἰς πάντα δὴ οἶμαι ταῦτά τε καὶ ἄλλα τοιαῦτα ἀποβλέψας τήν τε πόλιν τῶν πόλεων ἀθλιωτάτην ἔκρινας-","st":"578b"},{"sp":"N","t":"οὐκοῦν ὀρθῶς; ἔφη.","st":"578b"},{"sp":"N","t":"καὶ μάλα, ἦν δ᾽ ἐγώ. ἀλλὰ περὶ τοῦ ἀνδρὸς αὖ τοῦ τυραννικοῦ τί λέγεις εἰς ταὐτὰ ταῦτα ἀποβλέπων;","st":"578b"},{"sp":"N","t":"μακρῷ, ἔφη, ἀθλιώτατον εἶναι τῶν ἄλλων ἁπάντων.","st":"578b"},{"sp":"N","t":"τοῦτο, ἦν δ᾽ ἐγώ, οὐκέτ᾽ ὀρθῶς λέγεις.","st":"578b"},{"sp":"N","t":"πῶς; ἦ δ᾽ ὅς.","st":"578b"},{"sp":"N","t":"οὔπω, ἔφην, οἶμαι, οὗτός ἐστιν ὁ τοιοῦτος μάλιστα.","st":"578b"},{"sp":"N","t":"ἀλλὰ τίς μήν;","st":"578b"},{"sp":"N","t":"ὅδε ἴσως σοι ἔτι δόξει εἶναι τούτου ἀθλιώτερος.","st":"578b"},{"sp":"N","t":"ποῖος;","st":"578b"},{"sp":"N","t":"ὃς ἄν, ἦν δ᾽ ἐγώ, τυραννικὸς ὢν μὴ ἰδιώτην βίον καταβιῷ, ἀλλὰ δυστυχὴς ᾖ καὶ αὐτῷ ὑπό τινος συμφορᾶς ἐκπορισθῇ ὥστε τυράννῳ γενέσθαι.","st":"578c"},{"sp":"N","t":"τεκμαίρομαί σε, ἔφη, ἐκ τῶν προειρημένων ἀληθῆ λέγειν.","st":"578c"},{"sp":"N","t":"ναί, ἦν δ᾽ ἐγώ, ἀλλ᾽ οὐκ οἴεσθαι χρὴ τὰ τοιαῦτα, ἀλλ᾽ εὖ μάλα τῷ τοιούτῳ λόγῳ σκοπεῖν: περὶ γάρ τοι τοῦ μεγίστου ἡ σκέψις, ἀγαθοῦ τε βίου καὶ κακοῦ.","st":"578c"},{"sp":"N","t":"ὀρθότατα, ἦ δ᾽ ὅς.","st":"578c"},{"sp":"N","t":"σκόπει δὴ εἰ ἄρα τι λέγω. δοκεῖ γάρ μοι δεῖν ἐννοῆσαι","st":"578c"},{"sp":"N","t":"ἐκ τῶνδε περὶ αὐτοῦ σκοποῦντας.","st":"578d"},{"sp":"N","t":"ἐκ τίνων;","st":"578d"},{"sp":"N","t":"ἐξ ἑνὸς ἑκάστου τῶν ἰδιωτῶν, ὅσοι πλούσιοι ἐν πόλεσιν ἀνδράποδα πολλὰ κέκτηνται. οὗτοι γὰρ τοῦτό γε προσόμοιον ἔχουσιν τοῖς τυράννοις, τὸ πολλῶν ἄρχειν: διαφέρει δὲ τὸ ἐκείνου πλῆθος.","st":"578d"},{"sp":"N","t":"διαφέρει γάρ.","st":"578d"},{"sp":"N","t":"οἶσθ᾽ οὖν ὅτι οὗτοι ἀδεῶς ἔχουσιν καὶ οὐ φοβοῦνται τοὺς οἰκέτας;","st":"578d"},{"sp":"N","t":"τί γὰρ ἂν φοβοῖντο;","st":"578d"},{"sp":"N","t":"οὐδέν, εἶπον: ἀλλὰ τὸ αἴτιον ἐννοεῖς;","st":"578d"},{"sp":"N","t":"ναί, ὅτι γε πᾶσα ἡ πόλις ἑνὶ ἑκάστῳ βοηθεῖ τῶν ἰδιωτῶν.","st":"578d"},{"sp":"N","t":"καλῶς, ἦν δ᾽ ἐγώ, λέγεις. τί δέ; εἴ τις θεῶν ἄνδρα ἕνα, ὅτῳ ἔστιν ἀνδράποδα πεντήκοντα ἢ καὶ πλείω, ἄρας ἐκ τῆς πόλεως αὐτόν τε καὶ γυναῖκα καὶ παῖδας θείη εἰς ἐρημίαν μετὰ τῆς ἄλλης οὐσίας τε καὶ τῶν οἰκετῶν, ὅπου αὐτῷ μηδεὶς τῶν ἐλευθέρων μέλλοι βοηθήσειν, ἐν ποίῳ ἄν τινι καὶ ὁπόσῳ φόβῳ οἴει γενέσθαι αὐτὸν περί τε αὑτοῦ καὶ παίδων καὶ γυναικός, μὴ ἀπόλοιντο ὑπὸ τῶν οἰκετῶν;","st":"578e"},{"sp":"N","t":"ἐν παντί, ἦ δ᾽ ὅς, ἔγωγε.","st":"578e"},{"sp":"N","t":"οὐκοῦν ἀναγκάζοιτο ἄν τινας ἤδη θωπεύειν αὐτῶν τῶν δούλων καὶ ὑπισχνεῖσθαι πολλὰ καὶ ἐλευθεροῦν οὐδὲν δεόμενος, καὶ κόλαξ αὐτὸς ἂν θεραπόντων ἀναφανείη;","st":"579a"},{"sp":"N","t":"πολλὴ ἀνάγκη, ἔφη, αὐτῷ, ἢ ἀπολωλέναι.","st":"579a"},{"sp":"N","t":"τί δ᾽, εἰ καὶ ἄλλους, ἦν δ᾽ ἐγώ, ὁ θεὸς κύκλῳ κατοικίσειεν γείτονας πολλοὺς αὐτῷ, οἳ μὴ ἀνέχοιντο εἴ τις ἄλλος ἄλλου δεσπόζειν ἀξιοῖ, ἀλλ᾽ εἴ πού τινα τοιοῦτον λαμβάνοιεν, ταῖς ἐσχάταις τιμωροῖντο τιμωρίαις;","st":"579a"},{"sp":"N","t":"ἔτι ἄν, ἔφη, οἶμαι, μᾶλλον ἐν παντὶ κακοῦ εἴη, κύκλῳ φρουρούμενος ὑπὸ πάντων πολεμίων.","st":"579b"},{"sp":"N","t":"ἆρ᾽ οὖν οὐκ ἐν τοιούτῳ μὲν δεσμωτηρίῳ δέδεται ὁ τύραννος, φύσει ὢν οἷον διεληλύθαμεν, πολλῶν καὶ παντοδαπῶν φόβων καὶ ἐρώτων μεστός: λίχνῳ δὲ ὄντι αὐτῷ τὴν ψυχὴν μόνῳ τῶν ἐν τῇ πόλει οὔτε ἀποδημῆσαι ἔξεστιν οὐδαμόσε, οὔτε θεωρῆσαι ὅσων δὴ καὶ οἱ ἄλλοι ἐλεύθεροι ἐπιθυμηταί εἰσιν, καταδεδυκὼς δὲ ἐν τῇ οἰκίᾳ τὰ πολλὰ ὡς γυνὴ ζῇ,","st":"579b"},{"sp":"N","t":"φθονῶν καὶ τοῖς ἄλλοις πολίταις, ἐάν τις ἔξω ἀποδημῇ καί τι ἀγαθὸν ὁρᾷ;","st":"579c"},{"sp":"N","t":"παντάπασιν μὲν οὖν, ἔφη.","st":"579c"},{"sp":"N","t":"οὐκοῦν τοῖς τοιούτοις κακοῖς πλείω καρποῦται ἀνὴρ ὃς ἂν κακῶς ἐν ἑαυτῷ πολιτευόμενος, ὃν νυνδὴ σὺ ἀθλιώτατον ἔκρινας, τὸν τυραννικόν, ὡς μὴ ἰδιώτης καταβιῷ, ἀλλὰ ἀναγκασθῇ ὑπό τινος τύχης τυραννεῦσαι καὶ ἑαυτοῦ ὢν ἀκράτωρ ἄλλων ἐπιχειρήσῃ ἄρχειν, ὥσπερ εἴ τις κάμνοντι σώματι καὶ ἀκράτορι ἑαυτοῦ μὴ ἰδιωτεύων ἀλλ᾽ ἀγωνιζόμενος","st":"579c"},{"sp":"N","t":"πρὸς ἄλλα σώματα καὶ μαχόμενος ἀναγκάζοιτο διάγειν τὸν βίον.","st":"579d"},{"sp":"N","t":"παντάπασιν, ἔφη, ὁμοιότατά τε καὶ ἀληθέστατα λέγεις, ὦ Σώκρατες.","st":"579d"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, ὦ φίλε Γλαύκων, παντελῶς τὸ πάθος ἄθλιον, καὶ τοῦ ὑπὸ σοῦ κριθέντος χαλεπώτατα ζῆν χαλεπώτερον ἔτι ζῇ ὁ τυραννῶν;","st":"579d"},{"sp":"N","t":"κομιδῇ γ᾽, ἔφη.","st":"579d"},{"sp":"N","t":"ἔστιν ἄρα τῇ ἀληθείᾳ, κἂν εἰ μή τῳ δοκεῖ, ὁ τῷ ὄντι τύραννος τῷ ὄντι δοῦλος τὰς μεγίστας θωπείας καὶ δουλείας","st":"579d"},{"sp":"N","t":"καὶ κόλαξ τῶν πονηροτάτων, καὶ τὰς ἐπιθυμίας οὐδ᾽ ὁπωστιοῦν ἀποπιμπλάς, ἀλλὰ πλείστων ἐπιδεέστατος καὶ πένης τῇ ἀληθείᾳ φαίνεται, ἐάν τις ὅλην ψυχὴν ἐπίστηται θεάσασθαι, καὶ φόβου γέμων διὰ παντὸς τοῦ βίου, σφαδᾳσμῶν τε καὶ ὀδυνῶν πλήρης, εἴπερ τῇ τῆς πόλεως διαθέσει ἧς ἄρχει ἔοικεν. ἔοικεν δέ: ἦ γάρ;","st":"579e"},{"sp":"N","t":"καὶ μάλα, ἔφη.","st":"579e"},{"sp":"N","t":"οὐκοῦν καὶ πρὸς τούτοις ἔτι ἀποδώσομεν τῷ ἀνδρὶ καὶ ἃ τὸ πρότερον εἴπομεν, ὅτι ἀνάγκη καὶ εἶναι καὶ ἔτι μᾶλλον γίγνεσθαι αὐτῷ ἢ πρότερον διὰ τὴν ἀρχὴν φθονερῷ, ἀπίστῳ, ἀδίκῳ, ἀφίλῳ, ἀνοσίῳ καὶ πάσης κακίας πανδοκεῖ τε καὶ τροφεῖ, καὶ ἐξ ἁπάντων τούτων μάλιστα μὲν αὐτῷ δυστυχεῖ εἶναι, ἔπειτα δὲ καὶ τοὺς πλησίον αὑτῷ τοιούτους ἀπεργάζεσθαι.","st":"580a"},{"sp":"N","t":"οὐδείς σοι, ἔφη, τῶν νοῦν ἐχόντων ἀντερεῖ.","st":"580a"},{"sp":"N","t":"ἴθι δή μοι, ἔφην ἐγώ, νῦν ἤδη ὥσπερ ὁ διὰ πάντων","st":"580a"},{"sp":"N","t":"κριτὴς ἀποφαίνεται, καὶ σὺ οὕτω, τίς πρῶτος κατὰ τὴν σὴν δόξαν εὐδαιμονίᾳ καὶ τίς δεύτερος, καὶ τοὺς ἄλλους ἑξῆς πέντε ὄντας κρῖνε, βασιλικόν, τιμοκρατικόν, ὀλιγαρχικόν, δημοκρατικόν, τυραννικόν.","st":"580b"},{"sp":"N","t":"ἀλλὰ ῥᾳδία, ἔφη, ἡ κρίσις. καθάπερ γὰρ εἰσῆλθον ἔγωγε ὥσπερ χοροὺς κρίνω ἀρετῇ καὶ κακίᾳ καὶ εὐδαιμονίᾳ καὶ τῷ ἐναντίῳ.","st":"580b"},{"sp":"N","t":"μισθωσώμεθα οὖν κήρυκα, ἦν δ᾽ ἐγώ, ἢ αὐτὸς ἀνείπω ὅτι ὁ Ἀρίστωνος ὑὸς τὸν ἄριστόν τε καὶ δικαιότατον εὐδαιμονέστατον","st":"580b"},{"sp":"N","t":"ἔκρινε, τοῦτον δ᾽ εἶναι τὸν βασιλικώτατον καὶ βασιλεύοντα αὑτοῦ, τὸν δὲ κάκιστόν τε καὶ ἀδικώτατον ἀθλιώτατον, τοῦτον δὲ αὖ τυγχάνειν ὄντα ὃς ἂν τυραννικώτατος ὢν ἑαυτοῦ τε ὅτι μάλιστα τυραννῇ καὶ τῆς πόλεως;","st":"580c"},{"sp":"N","t":"ἀνειρήσθω σοι, ἔφη.","st":"580c"},{"sp":"N","t":"ἦ οὖν προσαναγορεύω, εἶπον, ἐάντε λανθάνωσιν τοιοῦτοι ὄντες ἐάντε μὴ πάντας ἀνθρώπους τε καὶ θεούς;","st":"580c"},{"sp":"N","t":"προσαναγόρευε, ἔφη.","st":"580c"},{"sp":"N","t":"εἶεν δή, εἶπον: αὕτη μὲν ἡμῖν ἡ ἀπόδειξις μία ἂν εἴη,","st":"580c"},{"sp":"N","t":"δευτέραν δὲ ἰδὲ τήνδε, ἐάν τι δόξῃ εἶναι.","st":"580d"},{"sp":"N","t":"τίς αὕτη;","st":"580d"},{"sp":"N","t":"ἐπειδή, ὥσπερ πόλις, ἦν δ᾽ ἐγώ, διῄρηται κατὰ τρία εἴδη, οὕτω καὶ ψυχὴ ἑνὸς ἑκάστου τριχῇ, [λογιστικὸν] δέξεται, ὡς ἐμοὶ δοκεῖ, καὶ ἑτέραν ἀπόδειξιν.","st":"580d"},{"sp":"N","t":"τίνα ταύτην;","st":"580d"},{"sp":"N","t":"τήνδε. τριῶν ὄντων τριτταὶ καὶ ἡδοναί μοι φαίνονται, ἑνὸς ἑκάστου μία ἰδία: ἐπιθυμίαι τε ὡσαύτως καὶ ἀρχαί.","st":"580d"},{"sp":"N","t":"πῶς λέγεις; ἔφη.","st":"580d"},{"sp":"N","t":"τὸ μέν, φαμέν, ἦν ᾧ μανθάνει ἄνθρωπος, τὸ δὲ ᾧ θυμοῦται, τὸ δὲ τρίτον διὰ πολυειδίαν ἑνὶ οὐκ ἔσχομεν ὀνόματι προσειπεῖν","st":"580d"},{"sp":"N","t":"ἰδίῳ αὐτοῦ, ἀλλὰ ὃ μέγιστον καὶ ἰσχυρότατον εἶχεν ἐν αὑτῷ, τούτῳ ἐπωνομάσαμεν: ἐπιθυμητικὸν γὰρ αὐτὸ κεκλήκαμεν διὰ σφοδρότητα τῶν τε περὶ τὴν ἐδωδὴν ἐπιθυμιῶν καὶ πόσιν καὶ ἀφροδίσια καὶ ὅσα ἄλλα τούτοις ἀκόλουθα, καὶ φιλοχρήματον δή, ὅτι διὰ χρημάτων μάλιστα ἀποτελοῦνται","st":"580e"},{"sp":"N","t":"αἱ τοιαῦται ἐπιθυμίαι.","st":"581a"},{"sp":"N","t":"καὶ ὀρθῶς γ᾽, ἔφη.","st":"581a"},{"sp":"N","t":"ἆρ᾽ οὖν καὶ τὴν ἡδονὴν αὐτοῦ καὶ φιλίαν εἰ φαῖμεν εἶναι τοῦ κέρδους, μάλιστ᾽ ἂν εἰς ἓν κεφάλαιον ἀπερειδοίμεθα τῷ λόγῳ, ὥστε τι ἡμῖν αὐτοῖς δηλοῦν, ὁπότε τοῦτο τῆς ψυχῆς τὸ μέρος λέγοιμεν, καὶ καλοῦντες αὐτὸ φιλοχρήματον καὶ φιλοκερδὲς ὀρθῶς ἂν καλοῖμεν;","st":"581a"},{"sp":"N","t":"ἐμοὶ γοῦν δοκεῖ, ἔφη.","st":"581a"},{"sp":"N","t":"τί δέ; τὸ θυμοειδὲς οὐ πρὸς τὸ κρατεῖν μέντοι φαμὲν καὶ νικᾶν καὶ εὐδοκιμεῖν ἀεὶ ὅλον ὡρμῆσθαι;","st":"581a"},{"sp":"N","t":"καὶ μάλα.","st":"581b"},{"sp":"N","t":"εἰ οὖν φιλόνικον αὐτὸ καὶ φιλότιμον προσαγορεύοιμεν, ἦ ἐμμελῶς ἂν ἔχοι;","st":"581b"},{"sp":"N","t":"ἐμμελέστατα μὲν οὖν.","st":"581b"},{"sp":"N","t":"ἀλλὰ μὴν ᾧ γε μανθάνομεν, παντὶ δῆλον ὅτι πρὸς τὸ εἰδέναι τὴν ἀλήθειαν ὅπῃ ἔχει πᾶν ἀεὶ τέταται, καὶ χρημάτων τε καὶ δόξης ἥκιστα τούτων τούτῳ μέλει.","st":"581b"},{"sp":"N","t":"πολύ γε.","st":"581b"},{"sp":"N","t":"φιλομαθὲς δὴ καὶ φιλόσοφον καλοῦντες αὐτὸ κατὰ τρόπον ἂν καλοῖμεν;","st":"581b"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"581b"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, καὶ ἄρχει ἐν ταῖς ψυχαῖς τῶν μὲν","st":"581b"},{"sp":"N","t":"τοῦτο, τῶν δὲ τὸ ἕτερον ἐκείνων, ὁπότερον ἂν τύχῃ;","st":"581c"},{"sp":"N","t":"οὕτως, ἔφη.","st":"581c"},{"sp":"N","t":"διὰ ταῦτα δὴ καὶ ἀνθρώπων λέγομεν τὰ πρῶτα τριττὰ γένη εἶναι, φιλόσοφον, φιλόνικον, φιλοκερδές;","st":"581c"},{"sp":"N","t":"κομιδῇ γε.","st":"581c"},{"sp":"N","t":"καὶ ἡδονῶν δὴ τρία εἴδη, ὑποκείμενον ἓν ἑκάστῳ τούτων;","st":"581c"},{"sp":"N","t":"πάνυ γε.","st":"581c"},{"sp":"N","t":"οἶσθ᾽ οὖν, ἦν δ᾽ ἐγώ, ὅτι εἰ ‘θέλοις τρεῖς τοιούτους ἀνθρώπους ἐν μέρει ἕκαστον ἀνερωτᾶν τίς τούτων τῶν βίων ἥδιστος, τὸν ἑαυτοῦ ἕκαστος μάλιστα ἐγκωμιάσεται; ὅ τε","st":"581c"},{"sp":"N","t":"χρηματιστικὸς πρὸς τὸ κερδαίνειν τὴν τοῦ τιμᾶσθαι ἡδονὴν ἢ τὴν τοῦ μανθάνειν οὐδενὸς ἀξίαν φήσει εἶναι, εἰ μὴ εἴ τι αὐτῶν ἀργύριον ποιεῖ; ἀληθῆ, ἔφη.","st":"581d"},{"sp":"N","t":"τί δὲ ὁ φιλότιμος; ἦν δ᾽ ἐγώ: οὐ τὴν μὲν ἀπὸ τῶν χρημάτων ἡδονὴν φορτικήν τινα ἡγεῖται, καὶ αὖ τὴν ἀπὸ τοῦ μανθάνειν, ὅτι μὴ μάθημα τιμὴν φέρει, καπνὸν καὶ φλυαρίαν;","st":"581d"},{"sp":"N","t":"οὕτως, ἔφη, ἔχει.","st":"581d"},{"sp":"N","t":"τὸν δὲ φιλόσοφον, ἦν δ᾽ ἐγώ, τί οἰώμεθα τὰς ἄλλας","st":"581d"},{"sp":"N","t":"ἡδονὰς νομίζειν πρὸς τὴν τοῦ εἰδέναι τἀληθὲς ὅπῃ ἔχει καὶ ἐν τοιούτῳ τινὶ ἀεὶ εἶναι μανθάνοντα; [τῆς ἡδονῆς] οὐ πάνυ πόρρω; καὶ καλεῖν τῷ ὄντι ἀναγκαίας, ὡς οὐδὲν τῶν ἄλλων δεόμενον, εἰ μὴ ἀνάγκη ἦν;","st":"581e"},{"sp":"N","t":"εὖ, ἔφη, δεῖ εἰδέναι;","st":"581e"},{"sp":"N","t":"ὅτε δὴ οὖν, εἶπον, ἀμφισβητοῦνται ἑκάστου τοῦ εἴδους αἱ ἡδοναὶ καὶ αὐτὸς ὁ βίος, μὴ ὅτι πρὸς τὸ κάλλιον καὶ αἴσχιον ζῆν μηδὲ τὸ χεῖρον καὶ ἄμεινον, ἀλλὰ πρὸς αὐτὸ τὸ","st":"581e"},{"sp":"N","t":"ἥδιον καὶ ἀλυπότερον, πῶς ἂν εἰδεῖμεν τίς αὐτῶν ἀληθέστατα λέγει;","st":"582a"},{"sp":"N","t":"οὐ πάνυ, ἔφη, ἔγωγε ἔχω εἰπεῖν.","st":"582a"},{"sp":"N","t":"ἀλλ᾽ ὧδε σκόπει: τίνι χρὴ κρίνεσθαι τὰ μέλλοντα καλῶς κριθήσεσθαι; ἆρ᾽ οὐκ ἐμπειρίᾳ τε καὶ φρονήσει καὶ λόγῳ; ἢ τούτων ἔχοι ἄν τις βέλτιον κριτήριον;","st":"582a"},{"sp":"N","t":"καὶ πῶς ἄν; ἔφη.","st":"582a"},{"sp":"N","t":"σκόπει δή: τριῶν ὄντων τῶν ἀνδρῶν τίς ἐμπειρότατος πασῶν ὧν εἴπομεν ἡδονῶν; πότερον ὁ φιλοκερδής, μανθάνων αὐτὴν τὴν ἀλήθειαν οἷόν ἐστιν, ἐμπειρότερος δοκεῖ σοι εἶναι τῆς","st":"582a"},{"sp":"N","t":"ἀπὸ τοῦ εἰδέναι ἡδονῆς, ἢ ὁ φιλόσοφος τῆς ἀπὸ τοῦ κερδαίνειν;","st":"582b"},{"sp":"N","t":"πολύ, ἔφη, διαφέρει. τῷ μὲν γὰρ ἀνάγκη γεύεσθαι τῶν ἑτέρων ἐκ παιδὸς ἀρξαμένῳ: τῷ δὲ φιλοκερδεῖ, ὅπῃ πέφυκε τὰ ὄντα μανθάνοντι, τῆς ἡδονῆς ταύτης, ὡς γλυκεῖά ἐστιν, οὐκ ἀνάγκη γεύεσθαι οὐδ᾽ ἐμπείρῳ γίγνεσθαι, μᾶλλον δὲ καὶ προθυμουμένῳ οὐ ῥᾴδιον.","st":"582b"},{"sp":"N","t":"πολὺ ἄρα, ἦν δ᾽ ἐγώ, διαφέρει τοῦ γε φιλοκερδοῦς ὁ φιλόσοφος ἐμπειρίᾳ ἀμφοτέρων τῶν ἡδονῶν.","st":"582b"},{"sp":"N","t":"πολὺ μέντοι.","st":"582c"},{"sp":"N","t":"τί δὲ τοῦ φιλοτίμου; ἆρα μᾶλλον ἄπειρός ἐστι τῆς ἀπὸ τοῦ τιμᾶσθαι ἡδονῆς ἢ ἐκεῖνος τῆς ἀπὸ τοῦ φρονεῖν;","st":"582c"},{"sp":"N","t":"ἀλλὰ τιμὴ μέν, ἔφη, ἐάνπερ ἐξεργάζωνται ἐπὶ ὃ ἕκαστος ὥρμηκε, πᾶσιν αὐτοῖς ἕπεται — καὶ γὰρ ὁ πλούσιος ὑπὸ πολλῶν τιμᾶται καὶ ὁ ἀνδρεῖος καὶ σοφός — ὥστε ἀπό γε τοῦ τιμᾶσθαι, οἷόν ἐστιν, πάντες τῆς ἡδονῆς ἔμπειροι: τῆς δὲ τοῦ ὄντος θέας, οἵαν ἡδονὴν ἔχει, ἀδύνατον ἄλλῳ γεγεῦσθαι πλὴν τῷ φιλοσόφῳ.","st":"582c"},{"sp":"N","t":"ἐμπειρίας μὲν ἄρα, εἶπον, ἕνεκα κάλλιστα τῶν ἀνδρῶν κρίνει οὗτος.","st":"582d"},{"sp":"N","t":"πολύ γε.","st":"582d"},{"sp":"N","t":"καὶ μὴν μετά γε φρονήσεως μόνος ἔμπειρος γεγονὼς ἔσται.","st":"582d"},{"sp":"N","t":"τί μήν;","st":"582d"},{"sp":"N","t":"ἀλλὰ μὴν καὶ δι᾽ οὗ γε δεῖ ὀργάνου κρίνεσθαι, οὐ τοῦ φιλοκερδοῦς τοῦτο ὄργανον οὐδὲ τοῦ φιλοτίμου, ἀλλὰ τοῦ φιλοσόφου.","st":"582d"},{"sp":"N","t":"τὸ ποῖον;","st":"582d"},{"sp":"N","t":"διὰ λόγων που ἔφαμεν δεῖν κρίνεσθαι. ἦ γάρ;","st":"582d"},{"sp":"N","t":"ναί.","st":"582d"},{"sp":"N","t":"λόγοι δὲ τούτου μάλιστα ὄργανον.","st":"582d"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"582d"},{"sp":"N","t":"οὐκοῦν εἰ μὲν πλούτῳ καὶ κέρδει ἄριστα ἐκρίνετο τὰ","st":"582d"},{"sp":"N","t":"κρινόμενα, ἃ ἐπῄνει ὁ φιλοκερδὴς καὶ ἔψεγεν, ἀνάγκη ἂν ἦν ταῦτα ἀληθέστατα εἶναι.","st":"582e"},{"sp":"N","t":"πολλή γε.","st":"582e"},{"sp":"N","t":"εἰ δὲ τιμῇ τε καὶ νίκῃ καὶ ἀνδρείᾳ, ἆρ᾽ οὐχ ἃ ὁ φιλότιμός τε καὶ φιλόνικος;","st":"582e"},{"sp":"N","t":"δῆλον.","st":"582e"},{"sp":"N","t":"ἐπειδὴ δ᾽ ἐμπειρίᾳ καὶ φρονήσει καὶ λόγῳ;","st":"582e"},{"sp":"N","t":"ἀνάγκη, ἔφη, ἃ ὁ φιλόσοφός τε καὶ ὁ φιλόλογος ἐπαινεῖ, ἀληθέστατα εἶναι.","st":"582e"},{"sp":"N","t":"τριῶν ἄρ᾽ οὐσῶν τῶν ἡδονῶν ἡ τούτου τοῦ μέρους τῆς ψυχῆς ᾧ μανθάνομεν ἡδίστη ἂν εἴη, καὶ ἐν ᾧ ἡμῶν τοῦτο ἄρχει, ὁ τούτου βίος ἥδιστος;","st":"583a"},{"sp":"N","t":"πῶς δ᾽ οὐ μέλλει; ἔφη: κύριος γοῦν ἐπαινέτης ὢν ἐπαινεῖ τὸν ἑαυτοῦ βίον ὁ φρόνιμος.","st":"583a"},{"sp":"N","t":"τίνα δὲ δεύτερον, εἶπον, βίον καὶ τίνα δευτέραν ἡδονήν φησιν ὁ κριτὴς εἶναι;","st":"583a"},{"sp":"N","t":"δῆλον ὅτι τὴν τοῦ πολεμικοῦ τε καὶ φιλοτίμου: ἐγγυτέρω γὰρ αὐτοῦ ἐστιν ἢ ἡ τοῦ χρηματιστοῦ.","st":"583a"},{"sp":"N","t":"ὑστάτην δὴ τὴν τοῦ φιλοκερδοῦς, ὡς ἔοικεν.","st":"583a"},{"sp":"N","t":"τί μήν; ἦ δ᾽ ὅς.","st":"583a"},{"sp":"N","t":"ταῦτα μὲν τοίνυν οὕτω δύ᾽ ἐφεξῆς ἂν εἴη καὶ δὶς νενικηκὼς ὁ δίκαιος τὸν ἄδικον: τὸ δὲ τρίτον Ὀλυμπικῶς τῷ σωτῆρί τε καὶ τῷ Ὀλυμπίῳ Διί, ἄθρει ὅτι οὐδὲ παναληθής ἐστιν ἡ τῶν ἄλλων ἡδονὴ πλὴν τῆς τοῦ φρονίμου οὐδὲ καθαρά, ἀλλ᾽ ἐσκιαγραφημένη τις, ὡς ἐγὼ δοκῶ μοι τῶν σοφῶν τινος ἀκηκοέναι. καίτοι τοῦτ᾽ ἂν εἴη μέγιστόν τε καὶ κυριώτατον τῶν πτωμάτων.","st":"583b"},{"sp":"N","t":"πολύ γε: ἀλλὰ πῶς λέγεις;","st":"583b"},{"sp":"N","t":"ὧδ᾽, εἶπον, ἐξευρήσω, σοῦ ἀποκρινομένου ζητῶν ἅμα.","st":"583c"},{"sp":"N","t":"Ἐρώτα δή, ἔφη.","st":"583c"},{"sp":"N","t":"λέγε δή, ἦν δ᾽ ἐγώ: οὐκ ἐναντίον φαμὲν λύπην ἡδονῇ;","st":"583c"},{"sp":"N","t":"καὶ μάλα.","st":"583c"},{"sp":"N","t":"οὐκοῦν καὶ τὸ μήτε χαίρειν μήτε λυπεῖσθαι εἶναί τι;","st":"583c"},{"sp":"N","t":"εἶναι μέντοι.","st":"583c"},{"sp":"N","t":"μεταξὺ τούτοιν ἀμφοῖν ἐν μέσῳ ὂν ἡσυχίαν τινὰ περὶ ταῦτα τῆς ψυχῆς; ἢ οὐχ οὕτως αὐτὸ λέγεις;","st":"583c"},{"sp":"N","t":"οὕτως, ἦ δ᾽ ὅς.","st":"583c"},{"sp":"N","t":"ἆρ᾽ οὖν μνημονεύεις, ἦν δ᾽ ἐγώ, τοὺς τῶν καμνόντων λόγους, οὓς λέγουσιν ὅταν κάμνωσιν;","st":"583c"},{"sp":"N","t":"ποίους;","st":"583c"},{"sp":"N","t":"ὡς οὐδὲν ἄρα ἐστὶν ἥδιον τοῦ ὑγιαίνειν, ἀλλὰ σφᾶς","st":"583c"},{"sp":"N","t":"ἐλελήθει, πρὶν κάμνειν, ἥδιστον ὄν.","st":"583d"},{"sp":"N","t":"μέμνημαι, ἔφη.","st":"583d"},{"sp":"N","t":"οὐκοῦν καὶ τῶν περιωδυνίᾳ τινὶ ἐχομένων ἀκούεις λεγόντων ὡς οὐδὲν ἥδιον τοῦ παύσασθαι ὀδυνώμενον;","st":"583d"},{"sp":"N","t":"ἀκούω.","st":"583d"},{"sp":"N","t":"καὶ ἐν ἄλλοις γε οἶμαι πολλοῖς τοιούτοις αἰσθάνῃ γιγνομένους τοὺς ἀνθρώπους, ἐν οἷς, ὅταν λυπῶνται, τὸ μὴ λυπεῖσθαι καὶ τὴν ἡσυχίαν τοῦ τοιούτου ἐγκωμιάζουσιν ὡς ἥδιστον, οὐ τὸ χαίρειν.","st":"583d"},{"sp":"N","t":"τοῦτο γάρ, ἔφη, τότε ἡδὺ ἴσως καὶ ἀγαπητὸν γίγνεται, ἡσυχία.","st":"583d"},{"sp":"N","t":"καὶ ὅταν παύσηται ἄρα, εἶπον, χαίρων τις, ἡ τῆς ἡδονῆς ἡσυχία λυπηρὸν ἔσται.","st":"583e"},{"sp":"N","t":"ἴσως, ἔφη.","st":"583e"},{"sp":"N","t":"ὃ μεταξὺ ἄρα νυνδὴ ἀμφοτέρων ἔφαμεν εἶναι, τὴν ἡσυχίαν, τοῦτό ποτε ἀμφότερα ἔσται, λύπη τε καὶ ἡδονή.","st":"583e"},{"sp":"N","t":"ἔοικεν.","st":"583e"},{"sp":"N","t":"ἦ καὶ δυνατὸν τὸ μηδέτερα ὂν ἀμφότερα γίγνεσθαι;","st":"583e"},{"sp":"N","t":"οὔ μοι δοκεῖ.","st":"583e"},{"sp":"N","t":"καὶ μὴν τό γε ἡδὺ ἐν ψυχῇ γιγνόμενον καὶ τὸ λυπηρὸν κίνησίς τις ἀμφοτέρω ἐστόν: ἢ οὔ;","st":"583e"},{"sp":"N","t":"ναί.","st":"583e"},{"sp":"N","t":"τὸ δὲ μήτε λυπηρὸν μήτε ἡδὺ οὐχὶ ἡσυχία μέντοι καὶ ἐν μέσῳ τούτοιν ἐφάνη ἄρτι;","st":"584a"},{"sp":"N","t":"ἐφάνη γάρ.","st":"584a"},{"sp":"N","t":"πῶς οὖν ὀρθῶς ἔστι τὸ μὴ ἀλγεῖν ἡδὺ ἡγεῖσθαι ἢ τὸ μὴ χαίρειν ἀνιαρόν;","st":"584a"},{"sp":"N","t":"οὐδαμῶς.","st":"584a"},{"sp":"N","t":"οὐκ ἔστιν ἄρα τοῦτο, ἀλλὰ φαίνεται, ἦν δ᾽ ἐγώ, παρὰ τὸ ἀλγεινὸν ἡδὺ καὶ παρὰ τὸ ἡδὺ ἀλγεινὸν τότε ἡ ἡσυχία, καὶ οὐδὲν ὑγιὲς τούτων τῶν φαντασμάτων πρὸς ἡδονῆς ἀλήθειαν, ἀλλὰ γοητεία τις.","st":"584a"},{"sp":"N","t":"ὡς γοῦν ὁ λόγος, ἔφη, σημαίνει.","st":"584a"},{"sp":"N","t":"ἰδὲ τοίνυν, ἔφην ἐγώ, ἡδονάς, αἳ οὐκ ἐκ λυπῶν εἰσίν, ἵνα μὴ πολλάκις οἰηθῇς ἐν τῷ παρόντι οὕτω τοῦτο πεφυκέναι, ἡδονὴν μὲν παῦλαν λύπης εἶναι, λύπην δὲ ἡδονῆς.","st":"584b"},{"sp":"N","t":"ποῦ δή, ἔφη, καὶ ποίας λέγεις;","st":"584b"},{"sp":"N","t":"πολλαὶ μέν, εἶπον, καὶ ἄλλαι, μάλιστα δ᾽ εἰ ‘θέλεις ἐννοῆσαι τὰς περὶ τὰς ὀσμὰς ἡδονάς. αὗται γὰρ οὐ προλυπηθέντι ἐξαίφνης ἀμήχανοι τὸ μέγεθος γίγνονται, παυσάμεναί τε λύπην οὐδεμίαν καταλείπουσιν.","st":"584b"},{"sp":"N","t":"ἀληθέστατα, ἔφη.","st":"584b"},{"sp":"N","t":"μὴ ἄρα πειθώμεθα καθαρὰν ἡδονὴν εἶναι τὴν λύπης ἀπαλλαγήν, μηδὲ λύπην τὴν ἡδονῆς.","st":"584c"},{"sp":"N","t":"μὴ γάρ.","st":"584c"},{"sp":"N","t":"ἀλλὰ μέντοι, εἶπον, αἵ γε διὰ τοῦ σώματος ἐπὶ τὴν ψυχὴν τείνουσαι καὶ λεγόμεναι ἡδοναί, σχεδὸν αἱ πλεῖσταί τε καὶ μέγισται, τούτου τοῦ εἴδους εἰσί, λυπῶν τινες ἀπαλλαγαί.","st":"584c"},{"sp":"N","t":"εἰσὶ γάρ.","st":"584c"},{"sp":"N","t":"οὐκοῦν καὶ αἱ πρὸ μελλόντων τούτων ἐκ προσδοκίας γιγνόμεναι προησθήσεις τε καὶ προλυπήσεις κατὰ ταὐτὰ ἔχουσιν;","st":"584c"},{"sp":"N","t":"κατὰ ταὐτά.","st":"584c"},{"sp":"N","t":"οἶσθ᾽ οὖν, ἦν δ᾽ ἐγώ, οἷαί εἰσιν καὶ ᾧ μάλιστα ἐοίκασιν;","st":"584d"},{"sp":"N","t":"τῷ; ἔφη.","st":"584d"},{"sp":"N","t":"νομίζεις τι, εἶπον, ἐν τῇ φύσει εἶναι τὸ μὲν ἄνω, τὸ δὲ κάτω, τὸ δὲ μέσον;","st":"584d"},{"sp":"N","t":"ἔγωγε.","st":"584d"},{"sp":"N","t":"οἴει οὖν ἄν τινα ἐκ τοῦ κάτω φερόμενον πρὸς μέσον ἄλλο τι οἴεσθαι ἢ ἄνω φέρεσθαι; καὶ ἐν μέσῳ στάντα, ἀφορῶντα ὅθεν ἐνήνεκται, ἄλλοθί που ἂν ἡγεῖσθαι εἶναι ἢ ἐν τῷ ἄνω, μὴ ἑωρακότα τὸ ἀληθῶς ἄνω;","st":"584d"},{"sp":"N","t":"μὰ Δί᾽, οὐκ ἔγωγε, ἔφη, ἄλλως οἶμαι οἰηθῆναι ἂν τὸν τοιοῦτον.","st":"584d"},{"sp":"N","t":"ἀλλ᾽ εἰ πάλιν γ᾽, ἔφην, φέροιτο, κάτω τ᾽ ἂν οἴοιτο φέρεσθαι καὶ ἀληθῆ οἴοιτο;","st":"584e"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"584e"},{"sp":"N","t":"οὐκοῦν ταῦτα πάσχοι ἂν πάντα διὰ τὸ μὴ ἔμπειρος εἶναι τοῦ ἀληθινῶς ἄνω τε ὄντος καὶ ἐν μέσῳ καὶ κάτω;","st":"584e"},{"sp":"N","t":"δῆλον δή.","st":"584e"},{"sp":"N","t":"θαυμάζοις ἂν οὖν εἰ καὶ οἱ ἄπειροι ἀληθείας περὶ πολλῶν τε ἄλλων μὴ ὑγιεῖς δόξας ἔχουσιν, πρός τε ἡδονὴν καὶ λύπην καὶ τὸ μεταξὺ τούτων οὕτω διάκεινται, ὥστε, ὅταν μὲν ἐπὶ τὸ","st":"584e"},{"sp":"N","t":"λυπηρὸν φέρωνται, ἀληθῆ τε οἴονται καὶ τῷ ὄντι λυποῦνται, ὅταν δὲ ἀπὸ λύπης ἐπὶ τὸ μεταξύ, σφόδρα μὲν οἴονται πρὸς πληρώσει τε καὶ ἡδονῇ γίγνεσθαι, ὥσπερ πρὸς μέλαν φαιὸν ἀποσκοποῦντες ἀπειρίᾳ λευκοῦ, καὶ πρὸς τὸ ἄλυπον οὕτω λύπην ἀφορῶντες ἀπειρίᾳ ἡδονῆς ἀπατῶνται;","st":"585a"},{"sp":"N","t":"μὰ Δία, ἦ δ᾽ ὅς, οὐκ ἂν θαυμάσαιμι, ἀλλὰ πολὺ μᾶλλον, εἰ μὴ οὕτως ἔχει.","st":"585a"},{"sp":"N","t":"ὧδέ γ᾽ οὖν, εἶπον, ἐννόει: οὐχὶ πεῖνα καὶ δίψα καὶ τὰ","st":"585a"},{"sp":"N","t":"τοιαῦτα κενώσεις τινές εἰσιν τῆς περὶ τὸ σῶμα ἕξεως;","st":"585b"},{"sp":"N","t":"τί μήν;","st":"585b"},{"sp":"N","t":"ἄγνοια δὲ καὶ ἀφροσύνη ἆρ᾽ οὐ κενότης ἐστὶ γῆς περὶ ψυχὴν αὖ ἕξεως;","st":"585b"},{"sp":"N","t":"μάλα γε.","st":"585b"},{"sp":"N","t":"οὐκοῦν πληροῖτ᾽ ἂν ὅ τε τροφῆς μεταλαμβάνων καὶ ὁ νοῦν ἴσχων;","st":"585b"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"585b"},{"sp":"N","t":"πλήρωσις δὲ ἀληθεστέρα τοῦ ἧττον ἢ τοῦ μᾶλλον ὄντος;","st":"585b"},{"sp":"N","t":"δῆλον ὅτι τοῦ μᾶλλον.","st":"585b"},{"sp":"N","t":"πότερα οὖν ἡγῇ τὰ γένη μᾶλλον καθαρᾶς οὐσίας μετέχειν, τὰ οἷον σίτου τε καὶ ποτοῦ καὶ ὄψου καὶ συμπάσης τροφῆς, ἢ τὸ δόξης τε ἀληθοῦς εἶδος καὶ ἐπιστήμης καὶ νοῦ καὶ","st":"585b"},{"sp":"N","t":"συλλήβδην αὖ πάσης ἀρετῆς; ὧδε δὲ κρῖνε: τὸ τοῦ ἀεὶ ὁμοίου ἐχόμενον καὶ ἀθανάτου καὶ ἀληθείας, καὶ αὐτὸ τοιοῦτον ὂν καὶ ἐν τοιούτῳ γιγνόμενον, μᾶλλον εἶναί σοι δοκεῖ, ἢ τὸ μηδέποτε ὁμοίου καὶ θνητοῦ, καὶ αὐτὸ τοιοῦτον καὶ ἐν τοιούτῳ γιγνόμενον;","st":"585c"},{"sp":"N","t":"πολύ, ἔφη, διαφέρει τὸ τοῦ ἀεὶ ὁμοίου.","st":"585c"},{"sp":"N","t":"ἡ οὖν ἀεὶ ὁμοίου οὐσία οὐσίας τι μᾶλλον ἢ ἐπιστήμης μετέχει;","st":"585c"},{"sp":"N","t":"οὐδαμῶς.","st":"585c"},{"sp":"N","t":"τί δ᾽; ἀληθείας;","st":"585c"},{"sp":"N","t":"οὐδὲ τοῦτο.","st":"585c"},{"sp":"N","t":"εἰ δὲ ἀληθείας ἧττον, οὐ καὶ οὐσίας;","st":"585c"},{"sp":"N","t":"ἀνάγκη.","st":"585c"},{"sp":"N","t":"οὐκοῦν ὅλως τὰ περὶ τὴν τοῦ σώματος θεραπείαν γένη τῶν γενῶν αὖ τῶν περὶ τὴν τῆς ψυχῆς θεραπείαν ἧττον ἀληθείας τε καὶ οὐσίας μετέχει;","st":"585d"},{"sp":"N","t":"πολύ γε.","st":"585d"},{"sp":"N","t":"σῶμα δὲ αὐτὸ ψυχῆς οὐκ οἴει οὕτως;","st":"585d"},{"sp":"N","t":"ἔγωγε.","st":"585d"},{"sp":"N","t":"οὐκοῦν τὸ τῶν μᾶλλον ὄντων πληρούμενον καὶ αὐτὸ μᾶλλον ὂν ὄντως μᾶλλον πληροῦται ἢ τὸ τῶν ἧττον ὄντων καὶ αὐτὸ ἧττον ὄν;","st":"585d"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"585d"},{"sp":"N","t":"εἰ ἄρα τὸ πληροῦσθαι τῶν φύσει προσηκόντων ἡδύ ἐστι, τὸ τῷ ὄντι καὶ τῶν ὄντων πληρούμενον μᾶλλον μᾶλλον","st":"585d"},{"sp":"N","t":"ὄντως τε καὶ ἀληθεστέρως χαίρειν ἂν ποιοῖ ἡδονῇ ἀληθεῖ, τὸ δὲ τῶν ἧττον ὄντων μεταλαμβάνον ἧττόν τε ἂν ἀληθῶς καὶ βεβαίως πληροῖτο καὶ ἀπιστοτέρας ἂν ἡδονῆς καὶ ἧττον ἀληθοῦς μεταλαμβάνοι.","st":"585e"},{"sp":"N","t":"ἀναγκαιότατα, ἔφη.","st":"585e"},{"sp":"N","t":"οἱ ἄρα φρονήσεως καὶ ἀρετῆς ἄπειροι, εὐωχίαις δὲ καὶ τοῖς τοιούτοις ἀεὶ συνόντες, κάτω, ὡς ἔοικεν, καὶ μέχρι πάλιν πρὸς τὸ μεταξὺ φέρονταί τε καὶ ταύτῃ πλανῶνται διὰ βίου, ὑπερβάντες δὲ τοῦτο πρὸς τὸ ἀληθῶς ἄνω οὔτε ἀνέβλεψαν πώποτε οὔτε ἠνέχθησαν, οὐδὲ τοῦ ὄντος τῷ ὄντι ἐπληρώθησαν, οὐδὲ βεβαίου τε καὶ καθαρᾶς ἡδονῆς ἐγεύσαντο, ἀλλὰ βοσκημάτων δίκην κάτω ἀεὶ βλέποντες καὶ κεκυφότες εἰς γῆν καὶ εἰς τραπέζας βόσκονται χορταζόμενοι καὶ ὀχεύοντες,","st":"586a"},{"sp":"N","t":"καὶ ἕνεκα τῆς τούτων πλεονεξίας λακτίζοντες καὶ κυρίττοντες ἀλλήλους σιδηροῖς κέρασί τε καὶ ὁπλαῖς ἀποκτεινύασι δι᾽ ἀπληστίαν, ἅτε οὐχὶ τοῖς οὖσιν οὐδὲ τὸ ὂν οὐδὲ τὸ στέγον ἑαυτῶν πιμπλάντες.","st":"586b"},{"sp":"N","t":"παντελῶς, ἔφη ὁ Γλαύκων, τὸν τῶν πολλῶν, ὦ Σώκρατες, χρησμῳδεῖς βίον.","st":"586b"},{"sp":"N","t":"ἆρ᾽ οὖν οὐκ ἀνάγκη καὶ ἡδοναῖς συνεῖναι μεμειγμέναις λύπαις, εἰδώλοις τῆς ἀληθοῦς ἡδονῆς καὶ ἐσκιαγραφημέναις,","st":"586b"},{"sp":"N","t":"ὑπὸ τῆς παρ᾽ ἀλλήλας θέσεως ἀποχραινομέναις, ὥστε σφοδροὺς ἑκατέρας φαίνεσθαι, καὶ ἔρωτας ἑαυτῶν λυττῶντας τοῖς ἄφροσιν ἐντίκτειν καὶ περιμαχήτους εἶναι, ὥσπερ τὸ τῆς Ἑλένης εἴδωλον ὑπὸ τῶν ἐν Τροίᾳ Στησίχορός φησι γενέσθαι περιμάχητον ἀγνοίᾳ τοῦ ἀληθοῦς;","st":"586c"},{"sp":"N","t":"πολλὴ ἀνάγκη, ἔφη, τοιοῦτόν τι αὐτὸ εἶναι.","st":"586c"},{"sp":"N","t":"τί δέ; περὶ τὸ θυμοειδὲς οὐχ ἕτερα τοιαῦτα ἀνάγκη γίγνεσθαι, ὃς ἂν αὐτὸ τοῦτο διαπράττηται ἢ φθόνῳ διὰ φιλοτιμίαν ἢ βίᾳ διὰ φιλονικίαν ἢ θυμῷ διὰ δυσκολίαν,","st":"586c"},{"sp":"N","t":"πλησμονὴν τιμῆς τε καὶ νίκης καὶ θυμοῦ διώκων ἄνευ λογισμοῦ τε καὶ νοῦ;","st":"586d"},{"sp":"N","t":"τοιαῦτα, ἦ δ᾽ ὅς, ἀνάγκη καὶ περὶ τοῦτο εἶναι.","st":"586d"},{"sp":"N","t":"τί οὖν, ἦν δ᾽ ἐγώ: θαρροῦντες λέγωμεν ὅτι καὶ περὶ τὸ φιλοκερδὲς καὶ τὸ φιλόνικον ὅσαι ἐπιθυμίαι εἰσίν, αἳ μὲν ἂν τῇ ἐπιστήμῃ καὶ λόγῳ ἑπόμεναι καὶ μετὰ τούτων τὰς ἡδονὰς διώκουσαι, ἃς ἂν τὸ φρόνιμον ἐξηγῆται, λαμβάνωσι, τὰς ἀληθεστάτας τε λήψονται, ὡς οἷόν τε αὐταῖς ἀληθεῖς","st":"586d"},{"sp":"N","t":"λαβεῖν, ἅτε ἀληθείᾳ ἑπομένων, καὶ τὰς ἑαυτῶν οἰκείας, εἴπερ τὸ βέλτιστον ἑκάστῳ, τοῦτο καὶ οἰκειότατον;","st":"586e"},{"sp":"N","t":"ἀλλὰ μήν, ἔφη, οἰκειότατόν γε.","st":"586e"},{"sp":"N","t":"τῷ φιλοσόφῳ ἄρα ἑπομένης ἁπάσης τῆς ψυχῆς καὶ μὴ στασιαζούσης ἑκάστῳ τῷ μέρει ὑπάρχει εἴς τε τἆλλα τὰ ἑαυτοῦ πράττειν καὶ δικαίῳ εἶναι, καὶ δὴ καὶ τὰς ἡδονὰς τὰς ἑαυτοῦ ἕκαστον καὶ τὰς βελτίστας καὶ εἰς τὸ δυνατὸν τὰς","st":"586e"},{"sp":"N","t":"ἀληθεστάτας καρποῦσθαι.","st":"587a"},{"sp":"N","t":"κομιδῇ μὲν οὖν.","st":"587a"},{"sp":"N","t":"ὅταν δὲ ἄρα τῶν ἑτέρων τι κρατήσῃ, ὑπάρχει αὐτῷ μήτε τὴν ἑαυτοῦ ἡδονὴν ἐξευρίσκειν, τά τε ἄλλ᾽ ἀναγκάζειν ἀλλοτρίαν καὶ μὴ ἀληθῆ ἡδονὴν διώκειν.","st":"587a"},{"sp":"N","t":"οὕτως, ἔφη.","st":"587a"},{"sp":"N","t":"οὐκοῦν ἃ πλεῖστον φιλοσοφίας τε καὶ λόγου ἀφέστηκεν, μάλιστ᾽ ἂν τοιαῦτα ἐξεργάζοιτο;","st":"587a"},{"sp":"N","t":"πολύ γε.","st":"587a"},{"sp":"N","t":"πλεῖστον δὲ λόγου ἀφίσταται οὐχ ὅπερ νόμου τε καὶ τάξεως;","st":"587a"},{"sp":"N","t":"δῆλον δή.","st":"587a"},{"sp":"N","t":"ἐφάνησαν δὲ πλεῖστον ἀφεστῶσαι οὐχ αἱ ἐρωτικαί τε","st":"587a"},{"sp":"N","t":"καὶ τυραννικαὶ ἐπιθυμίαι;","st":"587b"},{"sp":"N","t":"πολύ γε.","st":"587b"},{"sp":"N","t":"ἐλάχιστον δὲ αἱ βασιλικαί τε καὶ κόσμιαι;","st":"587b"},{"sp":"N","t":"ναί.","st":"587b"},{"sp":"N","t":"πλεῖστον δὴ οἶμαι ἀληθοῦς ἡδονῆς καὶ οἰκείας ὁ τύραννος ἀφεστήξει, ὁ δὲ ὀλίγιστον.","st":"587b"},{"sp":"N","t":"ἀνάγκη.","st":"587b"},{"sp":"N","t":"καὶ ἀηδέστατα ἄρα, εἶπον, ὁ τύραννος βιώσεται, ὁ δὲ βασιλεὺς ἥδιστα.","st":"587b"},{"sp":"N","t":"πολλὴ ἀνάγκη.","st":"587b"},{"sp":"N","t":"οἶσθ᾽ οὖν, ἦν δ᾽ ἐγώ, ὅσῳ ἀηδέστερον ζῇ τύραννος βασιλέως;","st":"587b"},{"sp":"N","t":"ἂν εἴπῃς, ἔφη.","st":"587b"},{"sp":"N","t":"τριῶν ἡδονῶν, ὡς ἔοικεν, οὐσῶν, μιᾶς μὲν γνησίας, δυοῖν","st":"587b"},{"sp":"N","t":"δὲ νόθαιν, τῶν νόθων εἰς τὸ ἐπέκεινα ὑπερβὰς ὁ τύραννος, φυγὼν νόμον τε καὶ λόγον, δούλαις τισὶ δορυφόροις ἡδοναῖς συνοικεῖ, καὶ ὁπόσῳ ἐλαττοῦται οὐδὲ πάνυ ῥᾴδιον εἰπεῖν, πλὴν ἴσως ὧδε.","st":"587c"},{"sp":"N","t":"πῶς; ἔφη.","st":"587c"},{"sp":"N","t":"ἀπὸ τοῦ ὀλιγαρχικοῦ τρίτος που ὁ τύραννος ἀφειστήκει: ἐν μέσῳ γὰρ αὐτῶν ὁ δημοτικὸς ἦν.","st":"587c"},{"sp":"N","t":"ναί.","st":"587c"},{"sp":"N","t":"οὐκοῦν καὶ ἡδονῆς τρίτῳ εἰδώλῳ πρὸς ἀλήθειαν ἀπ᾽ ἐκείνου συνοικοῖ ἄν, εἰ τὰ πρόσθεν ἀληθῆ;","st":"587c"},{"sp":"N","t":"οὕτω.","st":"587c"},{"sp":"N","t":"ὁ δέ γε ὀλιγαρχικὸς ἀπὸ τοῦ βασιλικοῦ αὖ τρίτος, ἐὰν","st":"587c"},{"sp":"N","t":"εἰς ταὐτὸν ἀριστοκρατικὸν καὶ βασιλικὸν τιθῶμεν.","st":"587d"},{"sp":"N","t":"τρίτος γάρ.","st":"587d"},{"sp":"N","t":"τριπλασίου ἄρα, ἦν δ᾽ ἐγώ, τριπλάσιον ἀριθμῷ ἀληθοῦς ἡδονῆς ἀφέστηκεν τύραννος.","st":"587d"},{"sp":"N","t":"φαίνεται.","st":"587d"},{"sp":"N","t":"ἐπίπεδον ἄρ᾽, ἔφην, ὡς ἔοικεν, τὸ εἴδωλον κατὰ τὸν τοῦ μήκους ἀριθμὸν ἡδονῆς τυραννικῆς ἂν εἴη.","st":"587d"},{"sp":"N","t":"κομιδῇ γε.","st":"587d"},{"sp":"N","t":"κατὰ δὲ δύναμιν καὶ τρίτην αὔξην δῆλον δὴ ἀπόστασιν ὅσην ἀφεστηκὼς γίγνεται.","st":"587d"},{"sp":"N","t":"δῆλον, ἔφη, τῷ γε λογιστικῷ.","st":"587d"},{"sp":"N","t":"οὐκοῦν ἐάν τις μεταστρέψας ἀληθείᾳ ἡδονῆς τὸν βασιλέα","st":"587d"},{"sp":"N","t":"τοῦ τυράννου ἀφεστηκότα λέγῃ ὅσον ἀφέστηκεν, ἐννεακαιεικοσικαιεπτακοσιοπλασιάκις ἥδιον αὐτὸν ζῶντα εὑρήσει τελειωθείσῃ τῇ πολλαπλασιώσει, τὸν δὲ τύραννον ἀνιαρότερον τῇ αὐτῇ ταύτῃ ἀποστάσει.","st":"587e"},{"sp":"N","t":"ἀμήχανον, ἔφη, λογισμὸν καταπεφόρηκας τῆς διαφορότητος","st":"587e"},{"sp":"N","t":"τοῖν ἀνδροῖν, τοῦ τε δικαίου καὶ τοῦ ἀδίκου, πρὸς ἡδονήν τε καὶ λύπην.","st":"588a"},{"sp":"N","t":"καὶ μέντοι καὶ ἀληθῆ καὶ προσήκοντά γε, ἦν δ᾽ ἐγώ, βίοις ἀριθμόν, εἴπερ αὐτοῖς προσήκουσιν ἡμέραι καὶ νύκτες καὶ μῆνες καὶ ἐνιαυτοί.","st":"588a"},{"sp":"N","t":"ἀλλὰ μήν, ἔφη, προσήκουσιν.","st":"588a"},{"sp":"N","t":"οὐκοῦν εἰ τοσοῦτον ἡδονῇ νικᾷ ὁ ἀγαθός τε καὶ δίκαιος τὸν κακόν τε καὶ ἄδικον, ἀμηχάνῳ δὴ ὅσῳ πλείονι νικήσει εὐσχημοσύνῃ τε βίου καὶ κάλλει καὶ ἀρετῇ;","st":"588a"},{"sp":"N","t":"ἀμηχάνῳ μέντοι νὴ Δία, ἔφη.","st":"588a"},{"sp":"N","t":"εἶεν δή, εἶπον: ἐπειδὴ ἐνταῦθα λόγου γεγόναμεν, ἀναλάβωμεν τὰ πρῶτα λεχθέντα, δι᾽ ἃ δεῦρ᾽ ἥκομεν. ἦν δέ που λεγόμενον λυσιτελεῖν ἀδικεῖν τῷ τελέως μὲν ἀδίκῳ, δοξαζομένῳ δὲ δικαίῳ: ἢ οὐχ οὕτως ἐλέχθη;","st":"588b"},{"sp":"N","t":"οὕτω μὲν οὖν.","st":"588b"},{"sp":"N","t":"νῦν δή, ἔφην, αὐτῷ διαλεγώμεθα, ἐπειδὴ διωμολογησάμεθα τό τε ἀδικεῖν καὶ τὸ δίκαια πράττειν ἣν ἑκάτερον ἔχει δύναμιν.","st":"588b"},{"sp":"N","t":"πῶς; ἔφη.","st":"588b"},{"sp":"N","t":"εἰκόνα πλάσαντες τῆς ψυχῆς λόγῳ, ἵνα εἰδῇ ὁ ἐκεῖνα λέγων οἷα ἔλεγεν.","st":"588b"},{"sp":"N","t":"ποίαν τινά; ἦ δ᾽ ὅς.","st":"588c"},{"sp":"N","t":"τῶν τοιούτων τινά, ἦν δ᾽ ἐγώ, οἷαι μυθολογοῦνται παλαιαὶ γενέσθαι φύσεις, ἥ τε Χιμαίρας καὶ ἡ Σκύλλης καὶ Κερβέρου, καὶ ἄλλαι τινὲς συχναὶ λέγονται συμπεφυκυῖαι ἰδέαι πολλαὶ εἰς ἓν γενέσθαι.","st":"588c"},{"sp":"N","t":"λέγονται γάρ, ἔφη.","st":"588c"},{"sp":"N","t":"πλάττε τοίνυν μίαν μὲν ἰδέαν θηρίου ποικίλου καὶ πολυκεφάλου, ἡμέρων δὲ θηρίων ἔχοντος κεφαλὰς κύκλῳ καὶ ἀγρίων, καὶ δυνατοῦ μεταβάλλειν καὶ φύειν ἐξ αὑτοῦ πάντα ταῦτα.","st":"588c"},{"sp":"N","t":"δεινοῦ πλάστου, ἔφη, τὸ ἔργον: ὅμως δέ, ἐπειδὴ εὐπλαστότερον κηροῦ καὶ τῶν τοιούτων λόγος, πεπλάσθω.","st":"588d"},{"sp":"N","t":"μίαν δὴ τοίνυν ἄλλην ἰδέαν λέοντος, μίαν δὲ ἀνθρώπου: πολὺ δὲ μέγιστον ἔστω τὸ πρῶτον καὶ δεύτερον τὸ δεύτερον.","st":"588d"},{"sp":"N","t":"ταῦτα, ἔφη, ῥᾴω, καὶ πέπλασται.","st":"588d"},{"sp":"N","t":"σύναπτε τοίνυν αὐτὰ εἰς ἓν τρία ὄντα, ὥστε πῃ συμπεφυκέναι ἀλλήλοις.","st":"588d"},{"sp":"N","t":"συνῆπται, ἔφη.","st":"588d"},{"sp":"N","t":"περίπλασον δὴ αὐτοῖς ἔξωθεν ἑνὸς εἰκόνα, τὴν τοῦ ἀνθρώπου, ὥστε τῷ μὴ δυναμένῳ τὰ ἐντὸς ὁρᾶν, ἀλλὰ τὸ","st":"588d"},{"sp":"N","t":"ἔξω μόνον ἔλυτρον ὁρῶντι, ἓν ζῷον φαίνεσθαι, ἄνθρωπον.","st":"588e"},{"sp":"N","t":"περιπέπλασται, ἔφη.","st":"588e"},{"sp":"N","t":"λέγωμεν δὴ τῷ λέγοντι ὡς λυσιτελεῖ τούτῳ ἀδικεῖν τῷ ἀνθρώπῳ, δίκαια δὲ πράττειν οὐ συμφέρει, ὅτι οὐδὲν ἄλλο φησὶν ἢ λυσιτελεῖν αὐτῷ τὸ παντοδαπὸν θηρίον εὐωχοῦντι ποιεῖν ἰσχυρὸν καὶ τὸν λέοντα καὶ τὰ περὶ τὸν λέοντα, τὸν","st":"588e"},{"sp":"N","t":"δὲ ἄνθρωπον λιμοκτονεῖν καὶ ποιεῖν ἀσθενῆ, ὥστε ἕλκεσθαι ὅπῃ ἂν ἐκείνων ὁπότερον ἄγῃ, καὶ μηδὲν ἕτερον ἑτέρῳ συνεθίζειν μηδὲ φίλον ποιεῖν, ἀλλ᾽ ἐᾶν αὐτὰ ἐν αὑτοῖς δάκνεσθαί τε καὶ μαχόμενα ἐσθίειν ἄλληλα.","st":"589a"},{"sp":"N","t":"παντάπασι γάρ, ἔφη, ταῦτ᾽ ἂν λέγοι ὁ τὸ ἀδικεῖν ἐπαινῶν.","st":"589a"},{"sp":"N","t":"οὐκοῦν αὖ ὁ τὰ δίκαια λέγων λυσιτελεῖν φαίη ἂν δεῖν ταῦτα πράττειν καὶ ταῦτα λέγειν, ὅθεν τοῦ ἀνθρώπου ὁ ἐντὸς","st":"589a"},{"sp":"N","t":"ἄνθρωπος ἔσται ἐγκρατέστατος, καὶ τοῦ πολυκεφάλου θρέμματος ἐπιμελήσεται ὥσπερ γεωργός, τὰ μὲν ἥμερα τρέφων καὶ τιθασεύων, τὰ δὲ ἄγρια ἀποκωλύων φύεσθαι, σύμμαχον ποιησάμενος τὴν τοῦ λέοντος φύσιν, καὶ κοινῇ πάντων κηδόμενος, φίλα ποιησάμενος ἀλλήλοις τε καὶ αὑτῷ, οὕτω θρέψει;","st":"589b"},{"sp":"N","t":"κομιδῇ γὰρ αὖ λέγει ταῦτα ὁ τὸ δίκαιον ἐπαινῶν.","st":"589b"},{"sp":"N","t":"κατὰ πάντα τρόπον δὴ ὁ μὲν τὰ δίκαια ἐγκωμιάζων ἀληθῆ","st":"589b"},{"sp":"N","t":"ἂν λέγοι, ὁ δὲ τὰ ἄδικα ψεύδοιτο. πρός τε γὰρ ἡδονὴν καὶ πρὸς εὐδοξίαν καὶ ὠφελίαν σκοπουμένῳ ὁ μὲν ἐπαινέτης τοῦ δικαίου ἀληθεύει, ὁ δὲ ψέκτης οὐδὲν ὑγιὲς οὐδ᾽ εἰδὼς ψέγει ὅτι ψέγει.","st":"589c"},{"sp":"N","t":"οὔ μοι δοκεῖ, ἦ δ᾽ ὅς, οὐδαμῇ γε.","st":"589c"},{"sp":"N","t":"πείθωμεν τοίνυν αὐτὸν πρᾴως — οὐ γὰρ ἑκὼν ἁμαρτάνει -ἐρωτῶντες: ὦ μακάριε, οὐ καὶ τὰ καλὰ καὶ αἰσχρὰ νόμιμα διὰ τὰ τοιαῦτ᾽ ἂν φαῖμεν γεγονέναι: τὰ μὲν καλὰ τὰ ὑπὸ","st":"589c"},{"sp":"N","t":"τῷ ἀνθρώπῳ, μᾶλλον δὲ ἴσως τὰ ὑπὸ τῷ θείῳ τὰ θηριώδη ποιοῦντα τῆς φύσεως, αἰσχρὰ δὲ τὰ ὑπὸ τῷ ἀγρίῳ τὸ ἥμερον δουλούμενα; συμφήσει: ἢ πῶς;","st":"589d"},{"sp":"N","t":"ἐάν μοι, ἔφη, πείθηται.","st":"589d"},{"sp":"N","t":"ἔστιν οὖν, εἶπον, ὅτῳ λυσιτελεῖ ἐκ τούτου τοῦ λόγου χρυσίον λαμβάνειν ἀδίκως, εἴπερ τοιόνδε τι γίγνεται, λαμβάνων τὸ χρυσίον ἅμα καταδουλοῦται τὸ βέλτιστον ἑαυτοῦ","st":"589d"},{"sp":"N","t":"τῷ μοχθηροτάτῳ; ἢ εἰ μὲν λαβὼν χρυσίον ὑὸν ἢ θυγατέρα ἐδουλοῦτο, καὶ ταῦτ᾽ εἰς ἀγρίων τε καὶ κακῶν ἀνδρῶν, οὐκ ἂν αὐτῷ ἐλυσιτέλει οὐδ᾽ ἂν πάμπολυ ἐπὶ τούτῳ λαμβάνειν, εἰ δὲ τὸ ἑαυτοῦ θειότατον ὑπὸ τῷ ἀθεωτάτῳ τε καὶ μιαρωτάτῳ δουλοῦται καὶ μηδὲν ἐλεεῖ, οὐκ ἄρα ἄθλιός ἐστι καὶ πολὺ","st":"589e"},{"sp":"N","t":"ἐπὶ δεινοτέρῳ ὀλέθρῳ χρυσὸν δωροδοκεῖ ἢ Ἐριφύλη ἐπὶ τῇ τοῦ ἀνδρὸς ψυχῇ τὸν ὅρμον δεξαμένη;","st":"590a"},{"sp":"N","t":"πολὺ μέντοι, ἦ δ᾽ ὃς ὁ Γλαύκων: ἐγὼ γάρ σοι ὑπὲρ ἐκείνου ἀποκρινοῦμαι.","st":"590a"},{"sp":"N","t":"οὐκοῦν καὶ τὸ ἀκολασταίνειν οἴει διὰ τοιαῦτα πάλαι ψέγεσθαι, ὅτι ἀνίεται ἐν τῷ τοιούτῳ τὸ δεινόν, τὸ μέγα ἐκεῖνο καὶ πολυειδὲς θρέμμα, πέρα τοῦ δέοντος;","st":"590a"},{"sp":"N","t":"δῆλον, ἔφη.","st":"590a"},{"sp":"N","t":"ἡ δ᾽ αὐθάδεια καὶ δυσκολία ψέγεται οὐχ ὅταν τὸ λεοντῶδές","st":"590a"},{"sp":"N","t":"τε καὶ ὀφεῶδες αὔξηται καὶ συντείνηται ἀναρμόστως;","st":"590b"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"590b"},{"sp":"N","t":"τρυφὴ δὲ καὶ μαλθακία οὐκ ἐπὶ τῇ αὐτοῦ τούτου χαλάσει τε καὶ ἀνέσει ψέγεται, ὅταν ἐν αὐτῷ δειλίαν ἐμποιῇ;","st":"590b"},{"sp":"N","t":"τί μήν;","st":"590b"},{"sp":"N","t":"κολακεία δὲ καὶ ἀνελευθερία οὐχ ὅταν τις τὸ αὐτὸ τοῦτο, τὸ θυμοειδές, ὑπὸ τῷ ὀχλώδει θηρίῳ ποιῇ καὶ ἕνεκα χρημάτων καὶ τῆς ἐκείνου ἀπληστίας προπηλακιζόμενον ἐθίζῃ ἐκ νέου ἀντὶ λέοντος πίθηκον γίγνεσθαι;","st":"590b"},{"sp":"N","t":"καὶ μάλα, ἔφη.","st":"590c"},{"sp":"N","t":"βαναυσία δὲ καὶ χειροτεχνία διὰ τί οἴει ὄνειδος φέρει; ἢ δι᾽ ἄλλο τι φήσομεν ἢ ὅταν τις ἀσθενὲς φύσει ἔχῃ τὸ τοῦ βελτίστου εἶδος, ὥστε μὴ ἂν δύνασθαι ἄρχειν τῶν ἐν αὑτῷ θρεμμάτων, ἀλλὰ θεραπεύειν ἐκεῖνα, καὶ τὰ θωπεύματα αὐτῶν μόνον δύνηται μανθάνειν;","st":"590c"},{"sp":"N","t":"ἔοικεν, ἔφη.","st":"590c"},{"sp":"N","t":"οὐκοῦν ἵνα καὶ ὁ τοιοῦτος ὑπὸ ὁμοίου ἄρχηται οἵουπερ ὁ βέλτιστος, δοῦλον αὐτόν φαμεν δεῖν εἶναι ἐκείνου τοῦ βελτίστου","st":"590c"},{"sp":"N","t":"καὶ ἔχοντος ἐν αὑτῷ τὸ θεῖον ἄρχον, οὐκ ἐπὶ βλάβῃ τῇ τοῦ δούλου οἰόμενοι δεῖν ἄρχεσθαι αὐτόν, ὥσπερ Θρασύμαχος ᾤετο τοὺς ἀρχομένους, ἀλλ᾽ ὡς ἄμεινον ὂν παντὶ ὑπὸ θείου καὶ φρονίμου ἄρχεσθαι, μάλιστα μὲν οἰκεῖον ἔχοντος ἐν αὑτῷ, εἰ δὲ μή, ἔξωθεν ἐφεστῶτος, ἵνα εἰς δύναμιν πάντες ὅμοιοι ὦμεν καὶ φίλοι, τῷ αὐτῷ κυβερνώμενοι;","st":"590d"},{"sp":"N","t":"καὶ ὀρθῶς γ᾽, ἔφη.","st":"590d"},{"sp":"N","t":"δηλοῖ δέ γε, ἦν δ᾽ ἐγώ, καὶ ὁ νόμος ὅτι τοιοῦτον βούλεται, πᾶσι τοῖς ἐν τῇ πόλει σύμμαχος ὤν: καὶ ἡ τῶν παίδων ἀρχή, τὸ μὴ ἐᾶν ἐλευθέρους εἶναι, ἕως ἂν ἐν αὐτοῖς ὥσπερ ἐν πόλει πολιτείαν καταστήσωμεν, καὶ τὸ βέλτιστον","st":"590e"},{"sp":"N","t":"θεραπεύσαντες τῷ παρ᾽ ἡμῖν τοιούτῳ ἀντικαταστήσωμεν φύλακα ὅμοιον καὶ ἄρχοντα ἐν αὐτῷ, καὶ τότε δὴ ἐλεύθερον ἀφίεμεν.","st":"591a"},{"sp":"N","t":"δηλοῖ γάρ, ἦ δ᾽ ὅς.","st":"591a"},{"sp":"N","t":"πῇ δὴ οὖν φήσομεν, ὦ Γλαύκων, καὶ κατὰ τίνα λόγον λυσιτελεῖν ἀδικεῖν, ἢ ἀκολασταίνειν ἤ τι αἰσχρὸν ποιεῖν, ἐξ ὧν πονηρότερος μὲν ἔσται, πλείω δὲ χρήματα ἢ ἄλλην τινὰ δύναμιν κεκτήσεται;","st":"591a"},{"sp":"N","t":"οὐδαμῇ, ἦ δ᾽ ὅς.","st":"591a"},{"sp":"N","t":"πῇ δ᾽ ἀδικοῦντα λανθάνειν καὶ μὴ διδόναι δίκην λυσιτελεῖν;","st":"591a"},{"sp":"N","t":"ἢ οὐχὶ ὁ μὲν λανθάνων ἔτι πονηρότερος γίγνεται, τοῦ δὲ μὴ λανθάνοντος καὶ κολαζομένου τὸ μὲν θηριῶδες κοιμίζεται καὶ ἡμεροῦται, τὸ δὲ ἥμερον ἐλευθεροῦται, καὶ ὅλη ἡ ψυχὴ εἰς τὴν βελτίστην φύσιν καθισταμένη τιμιωτέραν ἕξιν λαμβάνει, σωφροσύνην τε καὶ δικαιοσύνην μετὰ φρονήσεως κτωμένη, ἢ σῶμα ἰσχύν τε καὶ κάλλος μετὰ ὑγιείας λαμβάνον, τοσούτῳ ὅσῳπερ ψυχὴ σώματος τιμιωτέρα;","st":"591b"},{"sp":"N","t":"παντάπασιν μὲν οὖν, ἔφη.","st":"591b"},{"sp":"N","t":"οὐκοῦν ὅ γε νοῦν ἔχων πάντα τὰ αὑτοῦ εἰς τοῦτο συντείνας βιώσεται, πρῶτον μὲν τὰ μαθήματα τιμῶν, ἃ τοιαύτην αὐτοῦ τὴν ψυχὴν ἀπεργάσεται, τὰ δὲ ἄλλα ἀτιμάζων;","st":"591c"},{"sp":"N","t":"δῆλον, ἔφη.","st":"591c"},{"sp":"N","t":"ἔπειτά γ᾽, εἶπον, τὴν τοῦ σώματος ἕξιν καὶ τροφὴν οὐχ ὅπως τῇ θηριώδει καὶ ἀλόγῳ ἡδονῇ ἐπιτρέψας ἐνταῦθα τετραμμένος ζήσει, ἀλλ᾽ οὐδὲ πρὸς ὑγίειαν βλέπων, οὐδὲ τοῦτο πρεσβεύων, ὅπως ἰσχυρὸς ἢ ὑγιὴς ἢ καλὸς ἔσται, ἐὰν μὴ","st":"591c"},{"sp":"N","t":"καὶ σωφρονήσειν μέλλῃ ἀπ᾽ αὐτῶν, ἀλλ᾽ ἀεὶ τὴν ἐν τῷ σώματι ἁρμονίαν τῆς ἐν τῇ ψυχῇ ἕνεκα συμφωνίας ἁρμοττόμενος φανεῖται.","st":"591d"},{"sp":"N","t":"παντάπασι μὲν οὖν, ἔφη, ἐάνπερ μέλλῃ τῇ ἀληθείᾳ μουσικὸς εἶναι.","st":"591d"},{"sp":"N","t":"οὐκοῦν, εἶπον, καὶ τὴν ἐν τῇ τῶν χρημάτων κτήσει σύνταξίν τε καὶ συμφωνίαν; καὶ τὸν ὄγκον τοῦ πλήθους οὐκ ἐκπληττόμενος ὑπὸ τοῦ τῶν πολλῶν μακαρισμοῦ ἄπειρον αὐξήσει, ἀπέραντα κακὰ ἔχων;","st":"591d"},{"sp":"N","t":"οὐκ οἴομαι, ἔφη.","st":"591d"},{"sp":"N","t":"ἀλλ᾽ ἀποβλέπων γε, εἶπον, πρὸς τὴν ἐν αὑτῷ πολιτείαν, καὶ φυλάττων μή τι παρακινῇ αὑτοῦ τῶν ἐκεῖ διὰ πλῆθος οὐσίας ἢ δι᾽ ὀλιγότητα, οὕτως κυβερνῶν προσθήσει καὶ ἀναλώσει τῆς οὐσίας καθ᾽ ὅσον ἂν οἷός τ᾽ ᾖ.","st":"591e"},{"sp":"N","t":"κομιδῇ μὲν οὖν, ἔφη.","st":"591e"},{"sp":"N","t":"ἀλλὰ μὴν καὶ τιμάς γε, εἰς ταὐτὸν ἀποβλέπων, τῶν μὲν μεθέξει καὶ γεύσεται ἑκών, ἃς ἂν ἡγῆται ἀμείνω αὑτὸν ποιήσειν, ἃς δ᾽ ἂν λύσειν τὴν ὑπάρχουσαν ἕξιν, φεύξεται ἰδίᾳ καὶ δημοσίᾳ.","st":"592a"},{"sp":"N","t":"οὐκ ἄρα, ἔφη, τά γε πολιτικὰ ἐθελήσει πράττειν, ἐάνπερ τούτου κήδηται.","st":"592a"},{"sp":"N","t":"νὴ τὸν κύνα, ἦν δ᾽ ἐγώ, ἔν γε τῇ ἑαυτοῦ πόλει καὶ μάλα, οὐ μέντοι ἴσως ἔν γε τῇ πατρίδι, ἐὰν μὴ θεία τις συμβῇ τύχη.","st":"592a"},{"sp":"N","t":"μανθάνω, ἔφη: ἐν ᾗ νῦν διήλθομεν οἰκίζοντες πόλει λέγεις, τῇ ἐν λόγοις κειμένῃ, ἐπεὶ γῆς γε οὐδαμοῦ οἶμαι","st":"592a"},{"sp":"N","t":"αὐτὴν εἶναι.","st":"592b"},{"sp":"N","t":"ἀλλ᾽, ἦν δ᾽ ἐγώ, ἐν οὐρανῷ ἴσως παράδειγμα ἀνάκειται τῷ βουλομένῳ ὁρᾶν καὶ ὁρῶντι ἑαυτὸν κατοικίζειν. διαφέρει δὲ οὐδὲν εἴτε που ἔστιν εἴτε ἔσται: τὰ γὰρ ταύτης μόνης ἂν πράξειεν, ἄλλης δὲ οὐδεμιᾶς.","st":"592b"},{"sp":"N","t":"εἰκός γ᾽, ἔφη.","st":"592b"},{"sp":"N","t":"ΣΩΚΡΆΤΗς, ΓΛΑΎΚΩΝ","st":"592b"},{"sp":"N","t":"καὶ μήν, ἦν δ᾽ ἐγώ, πολλὰ μὲν καὶ ἄλλα περὶ αὐτῆς ἐννοῶ, ὡς παντὸς ἄρα μᾶλλον ὀρθῶς ᾠκίζομεν τὴν πόλιν, οὐχ ἥκιστα δὲ ἐνθυμηθεὶς περὶ ποιήσεως λέγω.","st":"595a"},{"sp":"N","t":"τὸ ποῖον; ἔφη.","st":"595a"},{"sp":"N","t":"τὸ μηδαμῇ παραδέχεσθαι αὐτῆς ὅση μιμητική: παντὸς γὰρ μᾶλλον οὐ παραδεκτέα νῦν καὶ ἐναργέστερον, ὡς ἐμοὶ δοκεῖ, φαίνεται, ἐπειδὴ χωρὶς ἕκαστα διῄρηται τὰ τῆς ψυχῆς","st":"595a"},{"sp":"N","t":"εἴδη.","st":"595b"},{"sp":"N","t":"πῶς λέγεις;","st":"595b"},{"sp":"N","t":"ὡς μὲν πρὸς ὑμᾶς εἰρῆσθαι — οὐ γάρ μου κατερεῖτε πρὸς τοὺς τῆς τραγῳδίας ποιητὰς καὶ τοὺς ἄλλους ἅπαντας τοὺς μιμητικούς — λώβη ἔοικεν εἶναι πάντα τὰ τοιαῦτα τῆς τῶν ἀκουόντων διανοίας, ὅσοι μὴ ἔχουσι φάρμακον τὸ εἰδέναι αὐτὰ οἷα τυγχάνει ὄντα.","st":"595b"},{"sp":"N","t":"πῇ δή, ἔφη, διανοούμενος λέγεις;","st":"595b"},{"sp":"N","t":"ῥητέον, ἦν δ᾽ ἐγώ: καίτοι φιλία γέ τίς με καὶ αἰδὼς ἐκ παιδὸς ἔχουσα περὶ Ὁμήρου ἀποκωλύει λέγειν. ἔοικε μὲν","st":"595b"},{"sp":"N","t":"γὰρ τῶν καλῶν ἁπάντων τούτων τῶν τραγικῶν πρῶτος διδάσκαλός τε καὶ ἡγεμὼν γενέσθαι. ἀλλ᾽ οὐ γὰρ πρό γε τῆς ἀληθείας τιμητέος ἀνήρ, ἀλλ᾽, ὃ λέγω, ῥητέον.","st":"595c"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη.","st":"595c"},{"sp":"N","t":"ἄκουε δή, μᾶλλον δὲ ἀποκρίνου.","st":"595c"},{"sp":"N","t":"Ἐρώτα.","st":"595c"},{"sp":"N","t":"μίμησιν ὅλως ἔχοις ἄν μοι εἰπεῖν ὅτι ποτ᾽ ἐστίν; οὐδὲ γάρ τοι αὐτὸς πάνυ τι συννοῶ τί βούλεται εἶναι.","st":"595c"},{"sp":"N","t":"ἦ που ἄρ᾽, ἔφη, ἐγὼ συννοήσω.","st":"595c"},{"sp":"N","t":"οὐδέν γε, ἦν δ᾽ ἐγώ, ἄτοπον, ἐπεὶ πολλά τοι ὀξύτερον","st":"595c"},{"sp":"N","t":"βλεπόντων ἀμβλύτερον ὁρῶντες πρότεροι εἶδον.","st":"596a"},{"sp":"N","t":"ἔστιν, ἔφη, οὕτως: ἀλλὰ σοῦ παρόντος οὐδ᾽ ἂν προθυμηθῆναι οἷός τε εἴην εἰπεῖν, εἴ τί μοι καταφαίνεται, ἀλλ᾽ αὐτὸς ὅρα.","st":"596a"},{"sp":"N","t":"βούλει οὖν ἐνθένδε ἀρξώμεθα ἐπισκοποῦντες, ἐκ τῆς εἰωθυίας μεθόδου; εἶδος γάρ πού τι ἓν ἕκαστον εἰώθαμεν τίθεσθαι περὶ ἕκαστα τὰ πολλά, οἷς ταὐτὸν ὄνομα ἐπιφέρομεν. ἢ οὐ μανθάνεις;","st":"596a"},{"sp":"N","t":"μανθάνω.","st":"596a"},{"sp":"N","t":"θῶμεν δὴ καὶ νῦν ὅτι βούλει τῶν πολλῶν. οἷον, εἰ","st":"596a"},{"sp":"N","t":"‘θέλεις, πολλαί πού εἰσι κλῖναι καὶ τράπεζαι.","st":"596b"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"596b"},{"sp":"N","t":"ἀλλὰ ἰδέαι γέ που περὶ ταῦτα τὰ σκεύη δύο, μία μὲν κλίνης, μία δὲ τραπέζης.","st":"596b"},{"sp":"N","t":"ναί.","st":"596b"},{"sp":"N","t":"οὐκοῦν καὶ εἰώθαμεν λέγειν ὅτι ὁ δημιουργὸς ἑκατέρου τοῦ σκεύους πρὸς τὴν ἰδέαν βλέπων οὕτω ποιεῖ ὁ μὲν τὰς κλίνας, ὁ δὲ τὰς τραπέζας, αἷς ἡμεῖς χρώμεθα, καὶ τἆλλα κατὰ ταὐτά; οὐ γάρ που τήν γε ἰδέαν αὐτὴν δημιουργεῖ οὐδεὶς τῶν δημιουργῶν: πῶς γάρ;","st":"596b"},{"sp":"N","t":"οὐδαμῶς.","st":"596b"},{"sp":"N","t":"ἀλλ᾽ ὅρα δὴ καὶ τόνδε τίνα καλεῖς τὸν δημιουργόν.","st":"596b"},{"sp":"N","t":"τὸν ποῖον;","st":"596c"},{"sp":"N","t":"ὃς πάντα ποιεῖ, ὅσαπερ εἷς ἕκαστος τῶν χειροτεχνῶν.","st":"596c"},{"sp":"N","t":"δεινόν τινα λέγεις καὶ θαυμαστὸν ἄνδρα.","st":"596c"},{"sp":"N","t":"οὔπω γε, ἀλλὰ τάχα μᾶλλον φήσεις. ὁ αὐτὸς γὰρ οὗτος χειροτέχνης οὐ μόνον πάντα οἷός τε σκεύη ποιῆσαι, ἀλλὰ καὶ τὰ ἐκ τῆς γῆς φυόμενα ἅπαντα ποιεῖ καὶ ζῷα πάντα ἐργάζεται, τά τε ἄλλα καὶ ἑαυτόν, καὶ πρὸς τούτοις γῆν καὶ οὐρανὸν καὶ θεοὺς καὶ πάντα τὰ ἐν οὐρανῷ καὶ τὰ ἐν Ἅιδου ὑπὸ γῆς ἅπαντα ἐργάζεται.","st":"596c"},{"sp":"N","t":"πάνυ θαυμαστόν, ἔφη, λέγεις σοφιστήν.","st":"596d"},{"sp":"N","t":"ἀπιστεῖς; ἦν δ᾽ ἐγώ. καί μοι εἰπέ, τὸ παράπαν οὐκ ἄν σοι δοκεῖ εἶναι τοιοῦτος δημιουργός, ἢ τινὶ μὲν τρόπῳ γενέσθαι ἂν τούτων ἁπάντων ποιητής, τινὶ δὲ οὐκ ἄν; ἢ οὐκ αἰσθάνῃ ὅτι κἂν αὐτὸς οἷός τ᾽ εἴης πάντα ταῦτα ποιῆσαι τρόπῳ γέ τινι;","st":"596d"},{"sp":"N","t":"καὶ τίς, ἔφη, ὁ τρόπος οὗτος;","st":"596d"},{"sp":"N","t":"οὐ χαλεπός, ἦν δ᾽ ἐγώ, ἀλλὰ πολλαχῇ καὶ ταχὺ δημιουργούμενος, τάχιστα δέ που, εἰ ‘θέλεις λαβὼν κάτοπτρον","st":"596d"},{"sp":"N","t":"περιφέρειν πανταχῇ: ταχὺ μὲν ἥλιον ποιήσεις καὶ τὰ ἐν τῷ οὐρανῷ, ταχὺ δὲ γῆν, ταχὺ δὲ σαυτόν τε καὶ τἆλλα ζῷα καὶ σκεύη καὶ φυτὰ καὶ πάντα ὅσα νυνδὴ ἐλέγετο.","st":"596e"},{"sp":"N","t":"ναί, ἔφη, φαινόμενα, οὐ μέντοι ὄντα γέ που τῇ ἀληθείᾳ.","st":"596e"},{"sp":"N","t":"καλῶς, ἦν δ᾽ ἐγώ, καὶ εἰς δέον ἔρχῃ τῷ λόγῳ. τῶν τοιούτων γὰρ οἶμαι δημιουργῶν καὶ ὁ ζωγράφος ἐστίν. ἦ γάρ;","st":"596e"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"596e"},{"sp":"N","t":"ἀλλὰ φήσεις οὐκ ἀληθῆ οἶμαι αὐτὸν ποιεῖν ἃ ποιεῖ. καίτοι τρόπῳ γέ τινι καὶ ὁ ζωγράφος κλίνην ποιεῖ: ἢ οὔ;","st":"596e"},{"sp":"N","t":"ναί, ἔφη, φαινομένην γε καὶ οὗτος.","st":"596e"},{"sp":"N","t":"τί δὲ ὁ κλινοποιός; οὐκ ἄρτι μέντοι ἔλεγες ὅτι οὐ τὸ εἶδος ποιεῖ, ὃ δή φαμεν εἶναι ὃ ἔστι κλίνη, ἀλλὰ κλίνην τινά;","st":"597a"},{"sp":"N","t":"ἔλεγον γάρ.","st":"597a"},{"sp":"N","t":"οὐκοῦν εἰ μὴ ὃ ἔστιν ποιεῖ, οὐκ ἂν τὸ ὂν ποιοῖ, ἀλλά τι τοιοῦτον οἷον τὸ ὄν, ὂν δὲ οὔ: τελέως δὲ εἶναι ὂν τὸ τοῦ κλινουργοῦ ἔργον ἢ ἄλλου τινὸς χειροτέχνου εἴ τις φαίη, κινδυνεύει οὐκ ἂν ἀληθῆ λέγειν;","st":"597a"},{"sp":"N","t":"οὔκουν, ἔφη, ὥς γ᾽ ἂν δόξειεν τοῖς περὶ τοὺς τοιούσδε λόγους διατρίβουσιν.","st":"597a"},{"sp":"N","t":"μηδὲν ἄρα θαυμάζωμεν εἰ καὶ τοῦτο ἀμυδρόν τι τυγχάνει ὂν πρὸς ἀλήθειαν.","st":"597a"},{"sp":"N","t":"μὴ γάρ.","st":"597b"},{"sp":"N","t":"βούλει οὖν, ἔφην, ἐπ᾽ αὐτῶν τούτων ζητήσωμεν τὸν μιμητὴν τοῦτον, τίς ποτ᾽ ἐστίν;","st":"597b"},{"sp":"N","t":"εἰ βούλει, ἔφη.","st":"597b"},{"sp":"N","t":"οὐκοῦν τριτταί τινες κλῖναι αὗται γίγνονται: μία μὲν ἡ ἐν τῇ φύσει οὖσα, ἣν φαῖμεν ἄν, ὡς ἐγᾦμαι, θεὸν ἐργάσασθαι. ἢ τίν᾽ ἄλλον;","st":"597b"},{"sp":"N","t":"οὐδένα, οἶμαι.","st":"597b"},{"sp":"N","t":"μία δέ γε ἣν ὁ τέκτων.","st":"597b"},{"sp":"N","t":"ναί, ἔφη.","st":"597b"},{"sp":"N","t":"μία δὲ ἣν ὁ ζωγράφος. ἦ γάρ;","st":"597b"},{"sp":"N","t":"ἔστω.","st":"597b"},{"sp":"N","t":"ζωγράφος δή, κλινοποιός, θεός, τρεῖς οὗτοι ἐπιστάται τρισὶν εἴδεσι κλινῶν.","st":"597b"},{"sp":"N","t":"ναὶ τρεῖς.","st":"597b"},{"sp":"N","t":"ὁ μὲν δὴ θεός, εἴτε οὐκ ἐβούλετο, εἴτε τις ἀνάγκη ἐπῆν μὴ πλέον ἢ μίαν ἐν τῇ φύσει ἀπεργάσασθαι αὐτὸν κλίνην, οὕτως ἐποίησεν μίαν μόνον αὐτὴν ἐκείνην ὃ ἔστιν κλίνη: δύο δὲ τοιαῦται ἢ πλείους οὔτε ἐφυτεύθησαν ὑπὸ τοῦ θεοῦ οὔτε μὴ φυῶσιν.","st":"597c"},{"sp":"N","t":"πῶς δή; ἔφη.","st":"597c"},{"sp":"N","t":"ὅτι, ἦν δ᾽ ἐγώ, εἰ δύο μόνας ποιήσειεν, πάλιν ἂν μία ἀναφανείη ἧς ἐκεῖναι ἂν αὖ ἀμφότεραι τὸ εἶδος ἔχοιεν, καὶ εἴη ἂν ὃ ἔστιν κλίνη ἐκείνη ἀλλ᾽ οὐχ αἱ δύο.","st":"597c"},{"sp":"N","t":"ὀρθῶς, ἔφη.","st":"597c"},{"sp":"N","t":"ταῦτα δὴ οἶμαι εἰδὼς ὁ θεός, βουλόμενος εἶναι ὄντως κλίνης ποιητὴς ὄντως οὔσης, ἀλλὰ μὴ κλίνης τινὸς μηδὲ κλινοποιός τις, μίαν φύσει αὐτὴν ἔφυσεν.","st":"597d"},{"sp":"N","t":"ἔοικεν.","st":"597d"},{"sp":"N","t":"βούλει οὖν τοῦτον μὲν φυτουργὸν τούτου προσαγορεύωμεν, ἤ τι τοιοῦτον;","st":"597d"},{"sp":"N","t":"δίκαιον γοῦν, ἔφη, ἐπειδήπερ φύσει γε καὶ τοῦτο καὶ τἆλλα πάντα πεποίηκεν.","st":"597d"},{"sp":"N","t":"τί δὲ τὸν τέκτονα; ἆρ᾽ οὐ δημιουργὸν κλίνης;","st":"597d"},{"sp":"N","t":"ναί.","st":"597d"},{"sp":"N","t":"ἦ καὶ τὸν ζωγράφον δημιουργὸν καὶ ποιητὴν τοῦ τοιούτου;","st":"597d"},{"sp":"N","t":"οὐδαμῶς.","st":"597d"},{"sp":"N","t":"ἀλλὰ τί αὐτὸν κλίνης φήσεις εἶναι;","st":"597d"},{"sp":"N","t":"τοῦτο, ἦ δ᾽ ὅς, ἔμοιγε δοκεῖ μετριώτατ᾽ ἂν προσαγορεύεσθαι, μιμητὴς οὗ ἐκεῖνοι δημιουργοί.","st":"597e"},{"sp":"N","t":"εἶεν, ἦν δ᾽ ἐγώ: τὸν τοῦ τρίτου ἄρα γεννήματος ἀπὸ τῆς φύσεως μιμητὴν καλεῖς;","st":"597e"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη.","st":"597e"},{"sp":"N","t":"τοῦτ᾽ ἄρα ἔσται καὶ ὁ τραγῳδοποιός, εἴπερ μιμητής ἐστι, τρίτος τις ἀπὸ βασιλέως καὶ τῆς ἀληθείας πεφυκώς, καὶ πάντες οἱ ἄλλοι μιμηταί.","st":"597e"},{"sp":"N","t":"κινδυνεύει.","st":"597e"},{"sp":"N","t":"τὸν μὲν δὴ μιμητὴν ὡμολογήκαμεν. εἰπὲ δέ μοι περὶ","st":"597e"},{"sp":"N","t":"τοῦ ζωγράφου τόδε: πότερα ἐκεῖνο αὐτὸ τὸ ἐν τῇ φύσει ἕκαστον δοκεῖ σοι ἐπιχειρεῖν μιμεῖσθαι ἢ τὰ τῶν δημιουργῶν ἔργα;","st":"598a"},{"sp":"N","t":"τὰ τῶν δημιουργῶν, ἔφη.","st":"598a"},{"sp":"N","t":"ἆρα οἷα ἔστιν ἢ οἷα φαίνεται; τοῦτο γὰρ ἔτι διόρισον.","st":"598a"},{"sp":"N","t":"πῶς λέγεις; ἔφη.","st":"598a"},{"sp":"N","t":"ὧδε: κλίνη, ἐάντε ἐκ πλαγίου αὐτὴν θεᾷ ἐάντε καταντικρὺ ἢ ὁπῃοῦν, μή τι διαφέρει αὐτὴ ἑαυτῆς, ἢ διαφέρει μὲν οὐδέν, φαίνεται δὲ ἀλλοία; καὶ τἆλλα ὡσαύτως;","st":"598a"},{"sp":"N","t":"οὕτως, ἔφη: φαίνεται, διαφέρει δ᾽ οὐδέν.","st":"598a"},{"sp":"N","t":"τοῦτο δὴ αὐτὸ σκόπει: πρὸς πότερον ἡ γραφικὴ πεποίηται περὶ ἕκαστον; πότερα πρὸς τὸ ὄν, ὡς ἔχει, μιμήσασθαι, ἢ πρὸς τὸ φαινόμενον, ὡς φαίνεται, φαντάσματος ἢ ἀληθείας οὖσα μίμησις;","st":"598b"},{"sp":"N","t":"φαντάσματος, ἔφη.","st":"598b"},{"sp":"N","t":"πόρρω ἄρα που τοῦ ἀληθοῦς ἡ μιμητική ἐστιν καί, ὡς ἔοικεν, διὰ τοῦτο πάντα ἀπεργάζεται, ὅτι σμικρόν τι ἑκάστου ἐφάπτεται, καὶ τοῦτο εἴδωλον. οἷον ὁ ζωγράφος, φαμέν, ζωγραφήσει ἡμῖν σκυτοτόμον, τέκτονα, τοὺς ἄλλους δημιουργούς,","st":"598b"},{"sp":"N","t":"περὶ οὐδενὸς τούτων ἐπαΐων τῶν τεχνῶν: ἀλλ᾽ ὅμως παῖδάς γε καὶ ἄφρονας ἀνθρώπους, εἰ ἀγαθὸς εἴη ζωγράφος, γράψας ἂν τέκτονα καὶ πόρρωθεν ἐπιδεικνὺς ἐξαπατῷ ἂν τῷ δοκεῖν ὡς ἀληθῶς τέκτονα εἶναι.","st":"598c"},{"sp":"N","t":"τί δ᾽ οὔ;","st":"598c"},{"sp":"N","t":"ἀλλὰ γὰρ οἶμαι ὦ φίλε, τόδε δεῖ περὶ πάντων τῶν τοιούτων διανοεῖσθαι: ἐπειδάν τις ἡμῖν ἀπαγγέλλῃ περί του, ὡς ἐνέτυχεν ἀνθρώπῳ πάσας ἐπισταμένῳ τὰς δημιουργίας καὶ τἆλλα πάντα ὅσα εἷς ἕκαστος οἶδεν, οὐδὲν ὅτι οὐχὶ","st":"598c"},{"sp":"N","t":"ἀκριβέστερον ὁτουοῦν ἐπισταμένῳ, ὑπολαμβάνειν δεῖ τῷ τοιούτῳ ὅτι εὐήθης τις ἄνθρωπος, καί, ὡς ἔοικεν, ἐντυχὼν γόητί τινι καὶ μιμητῇ ἐξηπατήθη, ὥστε ἔδοξεν αὐτῷ πάσσοφος εἶναι, διὰ τὸ αὐτὸς μὴ οἷός τ᾽ εἶναι ἐπιστήμην καὶ ἀνεπιστημοσύνην καὶ μίμησιν ἐξετάσαι.","st":"598d"},{"sp":"N","t":"ἀληθέστατα, ἔφη.","st":"598d"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, μετὰ τοῦτο ἐπισκεπτέον τήν τε τραγῳδίαν καὶ τὸν ἡγεμόνα αὐτῆς Ὅμηρον, ἐπειδή τινων","st":"598d"},{"sp":"N","t":"ἀκούομεν ὅτι οὗτοι πάσας μὲν τέχνας ἐπίστανται, πάντα δὲ τὰ ἀνθρώπεια τὰ πρὸς ἀρετὴν καὶ κακίαν, καὶ τά γε θεῖα: ἀνάγκη γὰρ τὸν ἀγαθὸν ποιητήν, εἰ μέλλει περὶ ὧν ἂν ποιῇ καλῶς ποιήσειν, εἰδότα ἄρα ποιεῖν, ἢ μὴ οἷόν τε εἶναι ποιεῖν. δεῖ δὴ ἐπισκέψασθαι πότερον μιμηταῖς τούτοις οὗτοι ἐντυχόντες ἐξηπάτηνται καὶ τὰ ἔργα αὐτῶν ὁρῶντες","st":"598e"},{"sp":"N","t":"οὐκ αἰσθάνονται τριττὰ ἀπέχοντα τοῦ ὄντος καὶ ῥᾴδια ποιεῖν μὴ εἰδότι τὴν ἀλήθειαν — φαντάσματα γὰρ ἀλλ᾽ οὐκ ὄντα ποιοῦσιν — ἤ τι καὶ λέγουσιν καὶ τῷ ὄντι οἱ ἀγαθοὶ ποιηταὶ ἴσασιν περὶ ὧν δοκοῦσιν τοῖς πολλοῖς εὖ λέγειν.","st":"599a"},{"sp":"N","t":"πάνυ μὲν οὖν, ἔφη, ἐξεταστέον.","st":"599a"},{"sp":"N","t":"οἴει οὖν, εἴ τις ἀμφότερα δύναιτο ποιεῖν, τό τε μιμηθησόμενον καὶ τὸ εἴδωλον, ἐπὶ τῇ τῶν εἰδώλων δημιουργίᾳ ἑαυτὸν ἀφεῖναι ἂν σπουδάζειν καὶ τοῦτο προστήσασθαι τοῦ","st":"599a"},{"sp":"N","t":"ἑαυτοῦ βίου ὡς βέλτιστον ἔχοντα;","st":"599b"},{"sp":"N","t":"οὐκ ἔγωγε.","st":"599b"},{"sp":"N","t":"ἀλλ᾽ εἴπερ γε οἶμαι ἐπιστήμων εἴη τῇ ἀληθείᾳ τούτων πέρι ἅπερ καὶ μιμεῖται, πολὺ πρότερον ἐν τοῖς ἔργοις ἂν σπουδάσειεν ἢ ἐπὶ τοῖς μιμήμασι, καὶ πειρῷτο ἂν πολλὰ καὶ καλὰ ἔργα ἑαυτοῦ καταλιπεῖν μνημεῖα, καὶ εἶναι προθυμοῖτ᾽ ἂν μᾶλλον ὁ ἐγκωμιαζόμενος ἢ ὁ ἐγκωμιάζων.","st":"599b"},{"sp":"N","t":"οἶμαι, ἔφη: οὐ γὰρ ἐξ ἴσου ἥ τε τιμὴ καὶ ἡ ὠφελία.","st":"599b"},{"sp":"N","t":"τῶν μὲν τοίνυν ἄλλων πέρι μὴ ἀπαιτῶμεν λόγον Ὅμηρον","st":"599b"},{"sp":"N","t":"ἢ ἄλλον ὁντινοῦν τῶν ποιητῶν, ἐρωτῶντες εἰ ἰατρικὸς ἦν τις αὐτῶν ἀλλὰ μὴ μιμητὴς μόνον ἰατρικῶν λόγων, τίνας ὑγιεῖς ποιητής τις τῶν παλαιῶν ἢ τῶν νέων λέγεται πεποιηκέναι, ὥσπερ Ἀσκληπιός, ἢ τίνας μαθητὰς ἰατρικῆς κατελίπετο, ὥσπερ ἐκεῖνος τοὺς ἐκγόνους, μηδ᾽ αὖ περὶ τὰς ἄλλας τέχνας αὐτοὺς ἐρωτῶμεν, ἀλλ᾽ ἐῶμεν: περὶ δὲ ὧν μεγίστων τε καὶ καλλίστων ἐπιχειρεῖ λέγειν Ὅμηρος, πολέμων τε πέρι καὶ στρατηγιῶν καὶ διοικήσεων πόλεων, καὶ","st":"599c"},{"sp":"N","t":"παιδείας πέρι ἀνθρώπου, δίκαιόν που ἐρωτᾶν αὐτὸν πυνθανομένους: ὦ φίλε Ὅμηρε, εἴπερ μὴ τρίτος ἀπὸ τῆς ἀληθείας εἶ ἀρετῆς πέρι, εἰδώλου δημιουργός, ὃν δὴ μιμητὴν ὡρισάμεθα, ἀλλὰ καὶ δεύτερος, καὶ οἷός τε ἦσθα γιγνώσκειν ποῖα ἐπιτηδεύματα βελτίους ἢ χείρους ἀνθρώπους ποιεῖ ἰδίᾳ καὶ δημοσίᾳ, λέγε ἡμῖν τίς τῶν πόλεων διὰ σὲ βέλτιον ᾤκησεν, ὥσπερ διὰ Λυκοῦργον Λακεδαίμων καὶ δι᾽ ἄλλους πολλοὺς","st":"599d"},{"sp":"N","t":"πολλαὶ μεγάλαι τε καὶ σμικραί; σὲ δὲ τίς αἰτιᾶται πόλις νομοθέτην ἀγαθὸν γεγονέναι καὶ σφᾶς ὠφεληκέναι; Χαρώνδαν μὲν γὰρ Ἰταλία καὶ Σικελία, καὶ ἡμεῖς Σόλωνα: σὲ δὲ τίς; ἕξει τινὰ εἰπεῖν;","st":"599e"},{"sp":"N","t":"οὐκ οἶμαι, ἔφη ὁ Γλαύκων: οὔκουν λέγεταί γε οὐδ᾽ ὑπ᾽ αὐτῶν Ὁμηριδῶν.","st":"599e"},{"sp":"N","t":"ἀλλὰ δή τις πόλεμος ἐπὶ Ὁμήρου ὑπ᾽ ἐκείνου ἄρχοντος ἢ συμβουλεύοντος εὖ πολεμηθεὶς μνημονεύεται;","st":"600a"},{"sp":"N","t":"οὐδείς.","st":"600a"},{"sp":"N","t":"ἀλλ᾽ οἷα δὴ εἰς τὰ ἔργα σοφοῦ ἀνδρὸς πολλαὶ ἐπίνοιαι καὶ εὐμήχανοι εἰς τέχνας ἤ τινας ἄλλας πράξεις λέγονται, ὥσπερ αὖ Θάλεώ τε πέρι τοῦ Μιλησίου καὶ Ἀναχάρσιος τοῦ Σκύθου;","st":"600a"},{"sp":"N","t":"οὐδαμῶς τοιοῦτον οὐδέν.","st":"600a"},{"sp":"N","t":"ἀλλὰ δὴ εἰ μὴ δημοσίᾳ, ἰδίᾳ τισὶν ἡγεμὼν παιδείας αὐτὸς ζῶν λέγεται Ὅμηρος γενέσθαι, οἳ ἐκεῖνον ἠγάπων ἐπὶ","st":"600a"},{"sp":"N","t":"συνουσίᾳ καὶ τοῖς ὑστέροις ὁδόν τινα παρέδοσαν βίου Ὁμηρικήν, ὥσπερ Πυθαγόρας αὐτός τε διαφερόντως ἐπὶ τούτῳ ἠγαπήθη, καὶ οἱ ὕστεροι ἔτι καὶ νῦν Πυθαγόρειον τρόπον ἐπονομάζοντες τοῦ βίου διαφανεῖς πῃ δοκοῦσιν εἶναι ἐν τοῖς ἄλλοις;","st":"600b"},{"sp":"N","t":"οὐδ᾽ αὖ, ἔφη, τοιοῦτον οὐδὲν λέγεται. ὁ γὰρ Κρεώφυλος, ὦ Σώκρατες, ἴσως, ὁ τοῦ Ὁμήρου ἑταῖρος, τοῦ ὀνόματος ἂν γελοιότερος ἔτι πρὸς παιδείαν φανείη, εἰ τὰ λεγόμενα περὶ Ὁμήρου ἀληθῆ. λέγεται γὰρ ὡς πολλή τις ἀμέλεια περὶ","st":"600b"},{"sp":"N","t":"αὐτὸν ἦν ἐπ᾽ αὐτοῦ ἐκείνου, ὅτε ἔζη.","st":"600c"},{"sp":"N","t":"λέγεται γὰρ οὖν, ἦν δ᾽ ἐγώ. ἀλλ᾽ οἴει, ὦ Γλαύκων, εἰ τῷ ὄντι οἷός τ᾽ ἦν παιδεύειν ἀνθρώπους καὶ βελτίους ἀπεργάζεσθαι Ὅμηρος, ἅτε περὶ τούτων οὐ μιμεῖσθαι ἀλλὰ γιγνώσκειν δυνάμενος, οὐκ ἄρ᾽ ἂν πολλοὺς ἑταίρους ἐποιήσατο καὶ ἐτιμᾶτο καὶ ἠγαπᾶτο ὑπ᾽ αὐτῶν, ἀλλὰ Πρωταγόρας μὲν ἄρα ὁ Ἀβδηρίτης καὶ Πρόδικος ὁ Κεῖος καὶ ἄλλοι πάμπολλοι δύνανται τοῖς ἐφ᾽ ἑαυτῶν παριστάναι ἰδίᾳ συγγιγνόμενοι","st":"600c"},{"sp":"N","t":"ὡς οὔτε οἰκίαν οὔτε πόλιν τὴν αὑτῶν διοικεῖν οἷοί τ᾽ ἔσονται, ἐὰν μὴ σφεῖς αὐτῶν ἐπιστατήσωσιν τῆς παιδείας, καὶ ἐπὶ ταύτῃ τῇ σοφίᾳ οὕτω σφόδρα φιλοῦνται, ὥστε μόνον οὐκ ἐπὶ ταῖς κεφαλαῖς περιφέρουσιν αὐτοὺς οἱ ἑταῖροι: Ὅμηρον δ᾽ ἄρα οἱ ἐπ᾽ ἐκείνου, εἴπερ οἷός τ᾽ ἦν πρὸς ἀρετὴν ὀνῆσαι ἀνθρώπους, ἢ Ἡσίοδον ῥαψῳδεῖν ἂν περιιόντας εἴων, καὶ οὐχὶ μᾶλλον ἂν αὐτῶν ἀντείχοντο ἢ τοῦ χρυσοῦ καὶ","st":"600d"},{"sp":"N","t":"ἠνάγκαζον παρὰ σφίσιν οἴκοι εἶναι, ἢ εἰ μὴ ἔπειθον, αὐτοὶ ἂν ἐπαιδαγώγουν ὅπῃ ᾖσαν, ἕως ἱκανῶς παιδείας μεταλάβοιεν;","st":"600e"},{"sp":"N","t":"παντάπασιν, ἔφη, δοκεῖς μοι, ὦ Σώκρατες, ἀληθῆ λέγειν.","st":"600e"},{"sp":"N","t":"οὐκοῦν τιθῶμεν ἀπὸ Ὁμήρου ἀρξαμένους πάντας τοὺς ποιητικοὺς μιμητὰς εἰδώλων ἀρετῆς εἶναι καὶ τῶν ἄλλων περὶ ὧν ποιοῦσιν, τῆς δὲ ἀληθείας οὐχ ἅπτεσθαι, ἀλλ᾽ ὥσπερ νυνδὴ ἐλέγομεν, ὁ ζωγράφος σκυτοτόμον ποιήσει δοκοῦντα","st":"600e"},{"sp":"N","t":"εἶναι, αὐτός τε οὐκ ἐπαΐων περὶ σκυτοτομίας καὶ τοῖς μὴ ἐπαΐουσιν, ἐκ τῶν χρωμάτων δὲ καὶ σχημάτων θεωροῦσιν;","st":"601a"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"601a"},{"sp":"N","t":"οὕτω δὴ οἶμαι καὶ τὸν ποιητικὸν φήσομεν χρώματα ἄττα ἑκάστων τῶν τεχνῶν τοῖς ὀνόμασι καὶ ῥήμασιν ἐπιχρωματίζειν αὐτὸν οὐκ ἐπαΐοντα ἀλλ᾽ ἢ μιμεῖσθαι, ὥστε ἑτέροις τοιούτοις ἐκ τῶν λόγων θεωροῦσι δοκεῖν, ἐάντε περὶ σκυτοτομίας τις λέγῃ ἐν μέτρῳ καὶ ῥυθμῷ καὶ ἁρμονίᾳ, πάνυ εὖ δοκεῖν λέγεσθαι, ἐάντε περὶ στρατηγίας ἐάντε περὶ ἄλλου","st":"601a"},{"sp":"N","t":"ὁτουοῦν: οὕτω φύσει αὐτὰ ταῦτα μεγάλην τινὰ κήλησιν ἔχειν. ἐπεὶ γυμνωθέντα γε τῶν τῆς μουσικῆς χρωμάτων τὰ τῶν ποιητῶν, αὐτὰ ἐφ᾽ αὑτῶν λεγόμενα, οἶμαί σε εἰδέναι οἷα φαίνεται. τεθέασαι γάρ που.","st":"601b"},{"sp":"N","t":"ἔγωγ᾽, ἔφη.","st":"601b"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, ἔοικεν τοῖς τῶν ὡραίων προσώποις, καλῶν δὲ μή, οἷα γίγνεται ἰδεῖν ὅταν αὐτὰ τὸ ἄνθος προλίπῃ;","st":"601b"},{"sp":"N","t":"παντάπασιν, ἦ δ᾽ ὅς.","st":"601b"},{"sp":"N","t":"ἴθι δή, τόδε ἄθρει: ὁ τοῦ εἰδώλου ποιητής, ὁ μιμητής, φαμέν, τοῦ μὲν ὄντος οὐδὲν ἐπαΐει, τοῦ δὲ φαινομένου: οὐχ","st":"601b"},{"sp":"N","t":"οὕτως;","st":"601c"},{"sp":"N","t":"ναί.","st":"601c"},{"sp":"N","t":"μὴ τοίνυν ἡμίσεως αὐτὸ καταλίπωμεν ῥηθέν, ἀλλ᾽ ἱκανῶς ἴδωμεν.","st":"601c"},{"sp":"N","t":"λέγε, ἔφη.","st":"601c"},{"sp":"N","t":"ζωγράφος, φαμέν, ἡνίας τε γράψει καὶ χαλινόν;","st":"601c"},{"sp":"N","t":"ναί.","st":"601c"},{"sp":"N","t":"ποιήσει δέ γε σκυτοτόμος καὶ χαλκεύς;","st":"601c"},{"sp":"N","t":"πάνυ γε.","st":"601c"},{"sp":"N","t":"ἆρ᾽ οὖν ἐπαΐει οἵας δεῖ τὰς ἡνίας εἶναι καὶ τὸν χαλινὸν ὁ γραφεύς; ἢ οὐδ᾽ ὁ ποιήσας, ὅ τε χαλκεὺς καὶ ὁ σκυτεύς, ἀλλ᾽ ἐκεῖνος ὅσπερ τούτοις ἐπίσταται χρῆσθαι, μόνος ὁ ἱππικός;","st":"601c"},{"sp":"N","t":"ἀληθέστατα.","st":"601c"},{"sp":"N","t":"ἆρ᾽ οὖν οὐ περὶ πάντα οὕτω φήσομεν ἔχειν;","st":"601c"},{"sp":"N","t":"πῶς;","st":"601c"},{"sp":"N","t":"περὶ ἕκαστον ταύτας τινὰς τρεῖς τέχνας εἶναι, χρησομένην, ποιήσουσαν, μιμησομένην;","st":"601d"},{"sp":"N","t":"ναί.","st":"601d"},{"sp":"N","t":"οὐκοῦν ἀρετὴ καὶ κάλλος καὶ ὀρθότης ἑκάστου σκεύους καὶ ζῴου καὶ πράξεως οὐ πρὸς ἄλλο τι ἢ τὴν χρείαν ἐστίν, πρὸς ἣν ἂν ἕκαστον ᾖ πεποιημένον ἢ πεφυκός;","st":"601d"},{"sp":"N","t":"οὕτως.","st":"601d"},{"sp":"N","t":"πολλὴ ἄρα ἀνάγκη τὸν χρώμενον ἑκάστῳ ἐμπειρότατόν τε εἶναι καὶ ἄγγελον γίγνεσθαι τῷ ποιητῇ οἷα ἀγαθὰ ἢ κακὰ ποιεῖ ἐν τῇ χρείᾳ ᾧ χρῆται: οἷον αὐλητής που αὐλοποιῷ","st":"601d"},{"sp":"N","t":"ἐξαγγέλλει περὶ τῶν αὐλῶν, οἳ ἂν ὑπηρετῶσιν ἐν τῷ αὐλεῖν, καὶ ἐπιτάξει οἵους δεῖ ποιεῖν, ὁ δ᾽ ὑπηρετήσει.","st":"601e"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"601e"},{"sp":"N","t":"οὐκοῦν ὁ μὲν εἰδὼς ἐξαγγέλλει περὶ χρηστῶν καὶ πονηρῶν αὐλῶν, ὁ δὲ πιστεύων ποιήσει;","st":"601e"},{"sp":"N","t":"ναί.","st":"601e"},{"sp":"N","t":"τοῦ αὐτοῦ ἄρα σκεύους ὁ μὲν ποιητὴς πίστιν ὀρθὴν ἕξει περὶ κάλλους τε καὶ πονηρίας, συνὼν τῷ εἰδότι καὶ ἀναγκαζόμενος","st":"601e"},{"sp":"N","t":"ἀκούειν παρὰ τοῦ εἰδότος, ὁ δὲ χρώμενος ἐπιστήμην.","st":"602a"},{"sp":"N","t":"πάνυ γε.","st":"602a"},{"sp":"N","t":"ὁ δὲ μιμητὴς πότερον ἐκ τοῦ χρῆσθαι ἐπιστήμην ἕξει περὶ ὧν ἂν γράφῃ, εἴτε καλὰ καὶ ὀρθὰ εἴτε μή, ἢ δόξαν ὀρθὴν διὰ τὸ ἐξ ἀνάγκης συνεῖναι τῷ εἰδότι καὶ ἐπιτάττεσθαι οἷα χρὴ γράφειν;","st":"602a"},{"sp":"N","t":"οὐδέτερα.","st":"602a"},{"sp":"N","t":"οὔτε ἄρα εἴσεται οὔτε ὀρθὰ δοξάσει ὁ μιμητὴς περὶ ὧν ἂν μιμῆται πρὸς κάλλος ἢ πονηρίαν.","st":"602a"},{"sp":"N","t":"οὐκ ἔοικεν.","st":"602a"},{"sp":"N","t":"χαρίεις ἂν εἴη ὁ ἐν τῇ ποιήσει μιμητικὸς πρὸς σοφίαν περὶ ὧν ἂν ποιῇ.","st":"602a"},{"sp":"N","t":"οὐ πάνυ.","st":"602a"},{"sp":"N","t":"ἀλλ᾽ οὖν δὴ ὅμως γε μιμήσεται, οὐκ εἰδὼς περὶ ἑκάστου ὅπῃ πονηρὸν ἢ χρηστόν: ἀλλ᾽, ὡς ἔοικεν, οἷον φαίνεται καλὸν εἶναι τοῖς πολλοῖς τε καὶ μηδὲν εἰδόσιν, τοῦτο μιμήσεται.","st":"602b"},{"sp":"N","t":"τί γὰρ ἄλλο;","st":"602b"},{"sp":"N","t":"ταῦτα μὲν δή, ὥς γε φαίνεται, ἐπιεικῶς ἡμῖν διωμολόγηται, τόν τε μιμητικὸν μηδὲν εἰδέναι ἄξιον λόγου περὶ ὧν μιμεῖται, ἀλλ᾽ εἶναι παιδιάν τινα καὶ οὐ σπουδὴν τὴν μίμησιν, τούς τε τῆς τραγικῆς ποιήσεως ἁπτομένους ἐν ἰαμβείοις καὶ ἐν ἔπεσι πάντας εἶναι μιμητικοὺς ὡς οἷόν τε μάλιστα.","st":"602b"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"602b"},{"sp":"N","t":"πρὸς Διός, ἦν δ᾽ ἐγώ, τὸ δὲ δὴ μιμεῖσθαι τοῦτο οὐ περὶ τρίτον μέν τί ἐστιν ἀπὸ τῆς ἀληθείας; ἦ γάρ;","st":"602c"},{"sp":"N","t":"ναί.","st":"602c"},{"sp":"N","t":"πρὸς δὲ δὴ ποῖόν τί ἐστιν τῶν τοῦ ἀνθρώπου ἔχον τὴν δύναμιν ἣν ἔχει;","st":"602c"},{"sp":"N","t":"τοῦ ποίου τινὸς πέρι λέγεις;","st":"602c"},{"sp":"N","t":"τοῦ τοιοῦδε: ταὐτόν που ἡμῖν μέγεθος ἐγγύθεν τε καὶ πόρρωθεν διὰ τῆς ὄψεως οὐκ ἴσον φαίνεται.","st":"602c"},{"sp":"N","t":"οὐ γάρ.","st":"602c"},{"sp":"N","t":"καὶ ταὐτὰ καμπύλα τε καὶ εὐθέα ἐν ὕδατί τε θεωμένοις καὶ ἔξω, καὶ κοῖλά τε δὴ καὶ ἐξέχοντα διὰ τὴν περὶ τὰ χρώματα αὖ πλάνην τῆς ὄψεως, καὶ πᾶσά τις ταραχὴ δήλη","st":"602c"},{"sp":"N","t":"ἡμῖν ἐνοῦσα αὕτη ἐν τῇ ψυχῇ: ᾧ δὴ ἡμῶν τῷ παθήματι τῆς φύσεως ἡ σκιαγραφία ἐπιθεμένη γοητείας οὐδὲν ἀπολείπει, καὶ ἡ θαυματοποιία καὶ αἱ ἄλλαι πολλαὶ τοιαῦται μηχαναί.","st":"602d"},{"sp":"N","t":"ἀληθῆ.","st":"602d"},{"sp":"N","t":"ἆρ᾽ οὖν οὐ τὸ μετρεῖν καὶ ἀριθμεῖν καὶ ἱστάναι βοήθειαι χαριέσταται πρὸς αὐτὰ ἐφάνησαν, ὥστε μὴ ἄρχειν ἐν ἡμῖν τὸ φαινόμενον μεῖζον ἢ ἔλαττον ἢ πλέον ἢ βαρύτερον, ἀλλὰ τὸ λογισάμενον καὶ μετρῆσαν ἢ καὶ στῆσαν;","st":"602d"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"602d"},{"sp":"N","t":"ἀλλὰ μὴν τοῦτό γε τοῦ λογιστικοῦ ἂν εἴη τοῦ ἐν ψυχῇ ἔργον.","st":"602e"},{"sp":"N","t":"τούτου γὰρ οὖν.","st":"602e"},{"sp":"N","t":"τούτῳ δὲ πολλάκις μετρήσαντι καὶ σημαίνοντι μείζω ἄττα εἶναι ἢ ἐλάττω ἕτερα ἑτέρων ἢ ἴσα τἀναντία φαίνεται ἅμα περὶ ταὐτά.","st":"602e"},{"sp":"N","t":"ναί.","st":"602e"},{"sp":"N","t":"οὐκοῦν ἔφαμεν τῷ αὐτῷ ἅμα περὶ ταὐτὰ ἐναντία δοξάζειν ἀδύνατον εἶναι;","st":"602e"},{"sp":"N","t":"καὶ ὀρθῶς γ᾽ ἔφαμεν.","st":"602e"},{"sp":"N","t":"τὸ παρὰ τὰ μέτρα ἄρα δοξάζον τῆς ψυχῆς τῷ κατὰ τὰ μέτρα οὐκ ἂν εἴη ταὐτόν.","st":"603a"},{"sp":"N","t":"οὐ γὰρ οὖν.","st":"603a"},{"sp":"N","t":"ἀλλὰ μὴν τὸ μέτρῳ γε καὶ λογισμῷ πιστεῦον βέλτιστον ἂν εἴη τῆς ψυχῆς.","st":"603a"},{"sp":"N","t":"τί μήν;","st":"603a"},{"sp":"N","t":"τὸ ἄρα τούτῳ ἐναντιούμενον τῶν φαύλων ἄν τι εἴη ἐν ἡμῖν.","st":"603a"},{"sp":"N","t":"ἀνάγκη.","st":"603a"},{"sp":"N","t":"τοῦτο τοίνυν διομολογήσασθαι βουλόμενος ἔλεγον ὅτι ἡ γραφικὴ καὶ ὅλως ἡ μιμητικὴ πόρρω μὲν τῆς ἀληθείας ὂν τὸ αὑτῆς ἔργον ἀπεργάζεται, πόρρω δ᾽ αὖ φρονήσεως ὄντι τῷ","st":"603a"},{"sp":"N","t":"ἐν ἡμῖν προσομιλεῖ τε καὶ ἑταίρα καὶ φίλη ἐστὶν ἐπ᾽ οὐδενὶ ὑγιεῖ οὐδ᾽ ἀληθεῖ.","st":"603b"},{"sp":"N","t":"παντάπασιν, ἦ δ᾽ ὅς.","st":"603b"},{"sp":"N","t":"φαύλη ἄρα φαύλῳ συγγιγνομένη φαῦλα γεννᾷ ἡ μιμητική.","st":"603b"},{"sp":"N","t":"ἔοικεν.","st":"603b"},{"sp":"N","t":"πότερον, ἦν δ᾽ ἐγώ, ἡ κατὰ τὴν ὄψιν μόνον, ἢ καὶ κατὰ τὴν ἀκοήν, ἣν δὴ ποίησιν ὀνομάζομεν;","st":"603b"},{"sp":"N","t":"εἰκός γ᾽, ἔφη, καὶ ταύτην.","st":"603b"},{"sp":"N","t":"μὴ τοίνυν, ἦν δ᾽ ἐγώ, τῷ εἰκότι μόνον πιστεύσωμεν ἐκ τῆς γραφικῆς, ἀλλὰ καὶ ἐπ᾽ αὐτὸ αὖ ἔλθωμεν τῆς διανοίας","st":"603b"},{"sp":"N","t":"τοῦτο ᾧ προσομιλεῖ ἡ τῆς ποιήσεως μιμητική, καὶ ἴδωμεν φαῦλον ἢ σπουδαῖόν ἐστιν.","st":"603c"},{"sp":"N","t":"ἀλλὰ χρή.","st":"603c"},{"sp":"N","t":"ὧδε δὴ προθώμεθα: πράττοντας, φαμέν, ἀνθρώπους μιμεῖται ἡ μιμητικὴ βιαίους ἢ ἑκουσίας πράξεις, καὶ ἐκ τοῦ πράττειν ἢ εὖ οἰομένους ἢ κακῶς πεπραγέναι, καὶ ἐν τούτοις δὴ πᾶσιν ἢ λυπουμένους ἢ χαίροντας. μή τι ἄλλο ἦν παρὰ ταῦτα;","st":"603c"},{"sp":"N","t":"οὐδέν.","st":"603c"},{"sp":"N","t":"ἆρ᾽ οὖν ἐν ἅπασι τούτοις ὁμονοητικῶς ἄνθρωπος διάκειται;","st":"603c"},{"sp":"N","t":"ἢ ὥσπερ κατὰ τὴν ὄψιν ἐστασίαζεν καὶ ἐναντίας εἶχεν ἐν ἑαυτῷ δόξας ἅμα περὶ τῶν αὐτῶν, οὕτω καὶ ἐν ταῖς πράξεσι στασιάζει τε καὶ μάχεται αὐτὸς αὑτῷ; ἀναμιμνῄσκομαι δὲ ὅτι τοῦτό γε νῦν οὐδὲν δεῖ ἡμᾶς διομολογεῖσθαι: ἐν γὰρ τοῖς ἄνω λόγοις ἱκανῶς πάντα ταῦτα διωμολογησάμεθα, ὅτι μυρίων τοιούτων ἐναντιωμάτων ἅμα γιγνομένων ἡ ψυχὴ γέμει ἡμῶν.","st":"603d"},{"sp":"N","t":"ὀρθῶς, ἔφη.","st":"603d"},{"sp":"N","t":"ὀρθῶς γάρ, ἦν δ᾽ ἐγώ: ἀλλ᾽ ὃ τότε ἀπελίπομεν, νῦν μοι","st":"603d"},{"sp":"N","t":"δοκεῖ ἀναγκαῖον εἶναι διεξελθεῖν.","st":"603e"},{"sp":"N","t":"τὸ ποῖον; ἔφη.","st":"603e"},{"sp":"N","t":"ἀνήρ, ἦν δ᾽ ἐγώ, ἐπιεικὴς τοιᾶσδε τύχης μετασχών, ὑὸν ἀπολέσας ἤ τι ἄλλο ὧν περὶ πλείστου ποιεῖται, ἐλέγομέν που καὶ τότε ὅτι ῥᾷστα οἴσει τῶν ἄλλων.","st":"603e"},{"sp":"N","t":"πάνυ γε.","st":"603e"},{"sp":"N","t":"νῦν δέ γε τόδ᾽ ἐπισκεψώμεθα, πότερον οὐδὲν ἀχθέσεται, ἢ τοῦτο μὲν ἀδύνατον, μετριάσει δέ πως πρὸς λύπην.","st":"603e"},{"sp":"N","t":"οὕτω μᾶλλον, ἔφη, τό γε ἀληθές.","st":"603e"},{"sp":"N","t":"τόδε νῦν μοι περὶ αὐτοῦ εἰπέ: πότερον μᾶλλον αὐτὸν οἴει τῇ λύπῃ μαχεῖσθαί τε καὶ ἀντιτείνειν, ὅταν ὁρᾶται ὑπὸ τῶν ὁμοίων, ἢ ὅταν ἐν ἐρημίᾳ μόνος αὐτὸς καθ᾽ αὑτὸν γίγνηται;","st":"604a"},{"sp":"N","t":"πολύ που, ἔφη, διοίσει, ὅταν ὁρᾶται.","st":"604a"},{"sp":"N","t":"μονωθεὶς δέ γε οἶμαι πολλὰ μὲν τολμήσει φθέγξασθαι, ἃ εἴ τις αὐτοῦ ἀκούοι αἰσχύνοιτ᾽ ἄν, πολλὰ δὲ ποιήσει, ἃ οὐκ ἂν δέξαιτό τινα ἰδεῖν δρῶντα.","st":"604a"},{"sp":"N","t":"οὕτως ἔχει, ἔφη.","st":"604a"},{"sp":"N","t":"οὐκοῦν τὸ μὲν ἀντιτείνειν διακελευόμενον λόγος καὶ νόμος","st":"604a"},{"sp":"N","t":"ἐστίν, τὸ δὲ ἕλκον ἐπὶ τὰς λύπας αὐτὸ τὸ πάθος;","st":"604b"},{"sp":"N","t":"ἀληθῆ.","st":"604b"},{"sp":"N","t":"ἐναντίας δὲ ἀγωγῆς γιγνομένης ἐν τῷ ἀνθρώπῳ περὶ τὸ αὐτὸ ἅμα, δύο φαμὲν αὐτὼ ἀναγκαῖον εἶναι.","st":"604b"},{"sp":"N","t":"πῶς δ᾽ οὔ;","st":"604b"},{"sp":"N","t":"οὐκοῦν τὸ μὲν ἕτερον τῷ νόμῳ ἕτοιμον πείθεσθαι, ᾗ ὁ νόμος ἐξηγεῖται;","st":"604b"},{"sp":"N","t":"πῶς;","st":"604b"},{"sp":"N","t":"λέγει που ὁ νόμος ὅτι κάλλιστον ὅτι μάλιστα ἡσυχίαν ἄγειν ἐν ταῖς συμφοραῖς καὶ μὴ ἀγανακτεῖν, ὡς οὔτε δήλου ὄντος τοῦ ἀγαθοῦ τε καὶ κακοῦ τῶν τοιούτων, οὔτε εἰς τὸ πρόσθεν οὐδὲν προβαῖνον τῷ χαλεπῶς φέροντι, οὔτε τι τῶν","st":"604b"},{"sp":"N","t":"ἀνθρωπίνων ἄξιον ὂν μεγάλης σπουδῆς, ὅ τε δεῖ ἐν αὐτοῖς ὅτι τάχιστα παραγίγνεσθαι ἡμῖν, τούτῳ ἐμποδὼν γιγνόμενον τὸ λυπεῖσθαι.","st":"604c"},{"sp":"N","t":"τίνι, ἦ δ᾽ ὅς, λέγεις;","st":"604c"},{"sp":"N","t":"τῷ βουλεύεσθαι, ἦν δ᾽ ἐγώ, περὶ τὸ γεγονὸς καὶ ὥσπερ ἐν πτώσει κύβων πρὸς τὰ πεπτωκότα τίθεσθαι τὰ αὑτοῦ πράγματα, ὅπῃ ὁ λόγος αἱρεῖ βέλτιστ᾽ ἂν ἔχειν, ἀλλὰ μὴ προσπταίσαντας καθάπερ παῖδας ἐχομένους τοῦ πληγέντος ἐν τῷ βοᾶν διατρίβειν, ἀλλ᾽ ἀεὶ ἐθίζειν τὴν ψυχὴν ὅτι","st":"604c"},{"sp":"N","t":"τάχιστα γίγνεσθαι πρὸς τὸ ἰᾶσθαί τε καὶ ἐπανορθοῦν τὸ πεσόν τε καὶ νοσῆσαν, ἰατρικῇ θρηνῳδίαν ἀφανίζοντα.","st":"604d"},{"sp":"N","t":"ὀρθότατα γοῦν ἄν τις, ἔφη, πρὸς τὰς τύχας οὕτω προσφέροιτο.","st":"604d"},{"sp":"N","t":"οὐκοῦν, φαμέν, τὸ μὲν βέλτιστον τούτῳ τῷ λογισμῷ ἐθέλει ἕπεσθαι.","st":"604d"},{"sp":"N","t":"δῆλον δή.","st":"604d"},{"sp":"N","t":"τὸ δὲ πρὸς τὰς ἀναμνήσεις τε τοῦ πάθους καὶ πρὸς τοὺς ὀδυρμοὺς ἄγον καὶ ἀπλήστως ἔχον αὐτῶν ἆρ᾽ οὐκ ἀλόγιστόν τε φήσομεν εἶναι καὶ ἀργὸν καὶ δειλίας φίλον;","st":"604d"},{"sp":"N","t":"φήσομεν μὲν οὖν.","st":"604d"},{"sp":"N","t":"οὐκοῦν τὸ μὲν πολλὴν μίμησιν καὶ ποικίλην ἔχει, τὸ ἀγανακτητικόν, τὸ δὲ φρόνιμόν τε καὶ ἡσύχιον ἦθος, παραπλήσιον ὂν ἀεὶ αὐτὸ αὑτῷ, οὔτε ῥᾴδιον μιμήσασθαι οὔτε μιμουμένου εὐπετὲς καταμαθεῖν, ἄλλως τε καὶ πανηγύρει καὶ παντοδαποῖς ἀνθρώποις εἰς θέατρα συλλεγομένοις: ἀλλοτρίου γάρ που πάθους ἡ μίμησις αὐτοῖς γίγνεται.","st":"604e"},{"sp":"N","t":"παντάπασι μὲν οὖν.","st":"605a"},{"sp":"N","t":"ὁ δὴ μιμητικὸς ποιητὴς δῆλον ὅτι οὐ πρὸς τὸ τοιοῦτον τῆς ψυχῆς πέφυκέ τε καὶ ἡ σοφία αὐτοῦ τούτῳ ἀρέσκειν πέπηγεν, εἰ μέλλει εὐδοκιμήσειν ἐν τοῖς πολλοῖς, ἀλλὰ πρὸς τὸ ἀγανακτητικόν τε καὶ ποικίλον ἦθος διὰ τὸ εὐμίμητον εἶναι.","st":"605a"},{"sp":"N","t":"δῆλον.","st":"605a"},{"sp":"N","t":"οὐκοῦν δικαίως ἂν αὐτοῦ ἤδη ἐπιλαμβανοίμεθα, καὶ τιθεῖμεν ἀντίστροφον αὐτὸν τῷ ζωγράφῳ: καὶ γὰρ τῷ φαῦλα ποιεῖν πρὸς ἀλήθειαν ἔοικεν αὐτῷ, καὶ τῷ πρὸς ἕτερον τοιοῦτον","st":"605a"},{"sp":"N","t":"ὁμιλεῖν τῆς ψυχῆς ἀλλὰ μὴ πρὸς τὸ βέλτιστον, καὶ ταύτῃ ὡμοίωται. καὶ οὕτως ἤδη ἂν ἐν δίκῃ οὐ παραδεχοίμεθα εἰς μέλλουσαν εὐνομεῖσθαι πόλιν, ὅτι τοῦτο ἐγείρει τῆς ψυχῆς καὶ τρέφει καὶ ἰσχυρὸν ποιῶν ἀπόλλυσι τὸ λογιστικόν, ὥσπερ ἐν πόλει ὅταν τις μοχθηροὺς ἐγκρατεῖς ποιῶν παραδιδῷ τὴν πόλιν, τοὺς δὲ χαριεστέρους φθείρῃ: ταὐτὸν καὶ τὸν μιμητικὸν ποιητὴν φήσομεν κακὴν πολιτείαν ἰδίᾳ ἑκάστου τῇ ψυχῇ ἐμποιεῖν, τῷ ἀνοήτῳ αὐτῆς","st":"605b"},{"sp":"N","t":"χαριζόμενον καὶ οὔτε τὰ μείζω οὔτε τὰ ἐλάττω διαγιγνώσκοντι, ἀλλὰ τὰ αὐτὰ τοτὲ μὲν μεγάλα ἡγουμένῳ, τοτὲ δὲ σμικρά, εἴδωλα εἰδωλοποιοῦντα, τοῦ δὲ ἀληθοῦς πόρρω πάνυ ἀφεστῶτα.","st":"605c"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"605c"},{"sp":"N","t":"οὐ μέντοι πω τό γε μέγιστον κατηγορήκαμεν αὐτῆς. τὸ γὰρ καὶ τοὺς ἐπιεικεῖς ἱκανὴν εἶναι λωβᾶσθαι, ἐκτὸς πάνυ τινῶν ὀλίγων, πάνδεινόν που.","st":"605c"},{"sp":"N","t":"τί δ᾽ οὐ μέλλει, εἴπερ γε δρᾷ αὐτό;","st":"605c"},{"sp":"N","t":"ἀκούων σκόπει. οἱ γάρ που βέλτιστοι ἡμῶν ἀκροώμενοι Ὁμήρου ἢ ἄλλου τινὸς τῶν τραγῳδοποιῶν μιμουμένου","st":"605c"},{"sp":"N","t":"τινὰ τῶν ἡρώων ἐν πένθει ὄντα καὶ μακρὰν ῥῆσιν ἀποτείνοντα ἐν τοῖς ὀδυρμοῖς ἢ καὶ ᾄδοντάς τε καὶ κοπτομένους, οἶσθ᾽ ὅτι χαίρομέν τε καὶ ἐνδόντες ἡμᾶς αὐτοὺς ἑπόμεθα συμπάσχοντες καὶ σπουδάζοντες ἐπαινοῦμεν ὡς ἀγαθὸν ποιητήν, ὃς ἂν ἡμᾶς ὅτι μάλιστα οὕτω διαθῇ.","st":"605d"},{"sp":"N","t":"οἶδα: πῶς δ᾽ οὔ;","st":"605d"},{"sp":"N","t":"ὅταν δὲ οἰκεῖόν τινι ἡμῶν κῆδος γένηται, ἐννοεῖς αὖ ὅτι ἐπὶ τῷ ἐναντίῳ καλλωπιζόμεθα, ἂν δυνώμεθα ἡσυχίαν ἄγειν","st":"605d"},{"sp":"N","t":"καὶ καρτερεῖν, ὡς τοῦτο μὲν ἀνδρὸς ὄν, ἐκεῖνο δὲ γυναικός, ὃ τότε ἐπῃνοῦμεν.","st":"605e"},{"sp":"N","t":"ἐννοῶ, ἔφη.","st":"605e"},{"sp":"N","t":"ἦ καλῶς οὖν, ἦν δ᾽ ἐγώ, οὗτος ὁ ἔπαινος ἔχει, τὸ ὁρῶντα τοιοῦτον ἄνδρα, οἷον ἑαυτόν τις μὴ ἀξιοῖ εἶναι ἀλλ᾽ αἰσχύνοιτο ἄν, μὴ βδελύττεσθαι ἀλλὰ χαίρειν τε καὶ ἐπαινεῖν;","st":"605e"},{"sp":"N","t":"οὐ μὰ τὸν Δί᾽, ἔφη, οὐκ εὐλόγῳ ἔοικεν.","st":"605e"},{"sp":"N","t":"ναί, ἦν δ᾽ ἐγώ, εἰ ἐκείνῃ γ᾽ αὐτὸ σκοποίης.","st":"606a"},{"sp":"N","t":"πῇ;","st":"606a"},{"sp":"N","t":"εἰ ἐνθυμοῖο ὅτι τὸ βίᾳ κατεχόμενον τότε ἐν ταῖς οἰκείαις συμφοραῖς καὶ πεπεινηκὸς τοῦ δακρῦσαί τε καὶ ἀποδύρασθαι ἱκανῶς καὶ ἀποπλησθῆναι, φύσει ὂν τοιοῦτον οἷον τούτων ἐπιθυμεῖν, τότ᾽ ἐστὶν τοῦτο τὸ ὑπὸ τῶν ποιητῶν πιμπλάμενον καὶ χαῖρον: τὸ δὲ φύσει βέλτιστον ἡμῶν, ἅτε οὐχ ἱκανῶς πεπαιδευμένον λόγῳ οὐδὲ ἔθει, ἀνίησιν τὴν φυλακὴν τοῦ","st":"606a"},{"sp":"N","t":"θρηνώδους τούτου, ἅτε ἀλλότρια πάθη θεωροῦν καὶ ἑαυτῷ οὐδὲν αἰσχρὸν ὂν εἰ ἄλλος ἀνὴρ ἀγαθὸς φάσκων εἶναι ἀκαίρως πενθεῖ, τοῦτον ἐπαινεῖν καὶ ἐλεεῖν, ἀλλ᾽ ἐκεῖνο κερδαίνειν ἡγεῖται, τὴν ἡδονήν, καὶ οὐκ ἂν δέξαιτο αὐτῆς στερηθῆναι καταφρονήσας ὅλου τοῦ ποιήματος. λογίζεσθαι γὰρ οἶμαι ὀλίγοις τισὶν μέτεστιν ὅτι ἀπολαύειν ἀνάγκη ἀπὸ τῶν ἀλλοτρίων εἰς τὰ οἰκεῖα: θρέψαντα γὰρ ἐν ἐκείνοις ἰσχυρὸν τὸ ἐλεινὸν οὐ ῥᾴδιον ἐν τοῖς αὑτοῦ πάθεσι κατέχειν.","st":"606b"},{"sp":"N","t":"ἀληθέστατα, ἔφη.","st":"606c"},{"sp":"N","t":"ἆρ᾽ οὖν οὐχ ὁ αὐτὸς λόγος καὶ περὶ τοῦ γελοίου; ὅτι, ἃν αὐτὸς αἰσχύνοιο γελωτοποιῶν, ἐν μιμήσει δὲ κωμῳδικῇ ἢ καὶ ἰδίᾳ ἀκούων σφόδρα χαρῇς καὶ μὴ μισῇς ὡς πονηρά, ταὐτὸν ποιεῖς ὅπερ ἐν τοῖς ἐλέοις; ὃ γὰρ τῷ λόγῳ αὖ κατεῖχες ἐν σαυτῷ βουλόμενον γελωτοποιεῖν, φοβούμενος δόξαν βωμολοχίας, τότ᾽ αὖ ἀνιεῖς, καὶ ἐκεῖ νεανικὸν ποιήσας ἔλαθες πολλάκις ἐν τοῖς οἰκείοις ἐξενεχθεὶς ὥστε κωμῳδοποιὸς γενέσθαι.","st":"606c"},{"sp":"N","t":"καὶ μάλα, ἔφη.","st":"606c"},{"sp":"N","t":"καὶ περὶ ἀφροδισίων δὴ καὶ θυμοῦ καὶ περὶ πάντων τῶν ἐπιθυμητικῶν τε καὶ λυπηρῶν καὶ ἡδέων ἐν τῇ ψυχῇ, ἃ δή φαμεν πάσῃ πράξει ἡμῖν ἕπεσθαι, ὅτι τοιαῦτα ἡμᾶς ἡ ποιητικὴ μίμησις ἐργάζεται: τρέφει γὰρ ταῦτα ἄρδουσα, δέον αὐχμεῖν, καὶ ἄρχοντα ἡμῖν καθίστησιν, δέον ἄρχεσθαι αὐτὰ ἵνα βελτίους τε καὶ εὐδαιμονέστεροι ἀντὶ χειρόνων καὶ ἀθλιωτέρων γιγνώμεθα.","st":"606d"},{"sp":"N","t":"οὐκ ἔχω ἄλλως φάναι, ἦ δ᾽ ὅς.","st":"606d"},{"sp":"N","t":"οὐκοῦν, εἶπον, ὦ Γλαύκων, ὅταν Ὁμήρου ἐπαινέταις ἐντύχῃς λέγουσιν ὡς τὴν Ἑλλάδα πεπαίδευκεν οὗτος ὁ ποιητὴς καὶ πρὸς διοίκησίν τε καὶ παιδείαν τῶν ἀνθρωπίνων πραγμάτων ἄξιος ἀναλαβόντι μανθάνειν τε καὶ κατὰ τοῦτον τὸν ποιητὴν πάντα τὸν αὑτοῦ βίον κατασκευασάμενον ζῆν,","st":"606e"},{"sp":"N","t":"φιλεῖν μὲν χρὴ καὶ ἀσπάζεσθαι ὡς ὄντας βελτίστους εἰς ὅσον δύνανται, καὶ συγχωρεῖν Ὅμηρον ποιητικώτατον εἶναι καὶ πρῶτον τῶν τραγῳδοποιῶν, εἰδέναι δὲ ὅτι ὅσον μόνον ὕμνους θεοῖς καὶ ἐγκώμια τοῖς ἀγαθοῖς ποιήσεως παραδεκτέον εἰς πόλιν: εἰ δὲ τὴν ἡδυσμένην Μοῦσαν παραδέξῃ ἐν μέλεσιν ἢ ἔπεσιν, ἡδονή σοι καὶ λύπη ἐν τῇ πόλει βασιλεύσετον ἀντὶ νόμου τε καὶ τοῦ κοινῇ ἀεὶ δόξαντος εἶναι βελτίστου λόγου.","st":"607a"},{"sp":"N","t":"ἀληθέστατα, ἔφη.","st":"607a"},{"sp":"N","t":"ταῦτα δή, ἔφην, ἀπολελογήσθω ἡμῖν ἀναμνησθεῖσιν περὶ ποιήσεως, ὅτι εἰκότως ἄρα τότε αὐτὴν ἐκ τῆς πόλεως ἀπεστέλλομεν τοιαύτην οὖσαν: ὁ γὰρ λόγος ἡμᾶς ᾕρει. προσείπωμεν δὲ αὐτῇ, μὴ καί τινα σκληρότητα ἡμῶν καὶ ἀγροικίαν καταγνῷ, ὅτι παλαιὰ μέν τις διαφορὰ φιλοσοφίᾳ τε καὶ ποιητικῇ: καὶ γὰρ ἡ ““λακέρυζα πρὸς δεσπόταν κύων” ἐκείνη ““κραυγάζουσα” “ καὶ ““μέγας ἐν ἀφρόνων κενεαγορίαισι”“","st":"607b"},{"sp":"N","t":"καὶ ὁ ““τῶν διασόφων ὄχλος κρατῶν”“ καὶ οἱ ““λεπτῶς μεριμνῶντες”,” ὅτι ἄρα ““πένονται”,” καὶ ἄλλα μυρία σημεῖα παλαιᾶς ἐναντιώσεως τούτων. ὅμως δὲ εἰρήσθω ὅτι ἡμεῖς γε, εἴ τινα ἔχοι λόγον εἰπεῖν ἡ πρὸς ἡδονὴν ποιητικὴ καὶ ἡ μίμησις, ὡς χρὴ αὐτὴν εἶναι ἐν πόλει εὐνομουμένῃ, ἅσμενοι ἂν καταδεχοίμεθα, ὡς σύνισμέν γε ἡμῖν αὐτοῖς κηλουμένοις ὑπ᾽ αὐτῆς: ἀλλὰ γὰρ τὸ δοκοῦν ἀληθὲς οὐχ ὅσιον προδιδόναι. ἦ γάρ, ὦ φίλε, οὐ κηλῇ ὑπ᾽ αὐτῆς","st":"607c"},{"sp":"N","t":"καὶ σύ, καὶ μάλιστα ὅταν δι᾽ Ὁμήρου θεωρῇς αὐτήν;","st":"607d"},{"sp":"N","t":"πολύ γε.","st":"607d"},{"sp":"N","t":"οὐκοῦν δικαία ἐστὶν οὕτω κατιέναι, ἀπολογησαμένη ἐν μέλει ἤ τινι ἄλλῳ μέτρῳ;","st":"607d"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"607d"},{"sp":"N","t":"δοῖμεν δέ γέ που ἂν καὶ τοῖς προστάταις αὐτῆς, ὅσοι μὴ ποιητικοί, φιλοποιηταὶ δέ, ἄνευ μέτρου λόγον ὑπὲρ αὐτῆς εἰπεῖν, ὡς οὐ μόνον ἡδεῖα ἀλλὰ καὶ ὠφελίμη πρὸς τὰς πολιτείας καὶ τὸν βίον τὸν ἀνθρώπινόν ἐστιν: καὶ εὐμενῶς ἀκουσόμεθα.","st":"607d"},{"sp":"N","t":"κερδανοῦμεν γάρ που ἐὰν μὴ μόνον ἡδεῖα φανῇ ἀλλὰ καὶ ὠφελίμη.","st":"607e"},{"sp":"N","t":"πῶς δ᾽ οὐ μέλλομεν, ἔφη, κερδαίνειν;","st":"607e"},{"sp":"N","t":"εἰ δέ γε μή, ὦ φίλε ἑταῖρε, ὥσπερ οἱ ποτέ του ἐρασθέντες, ἐὰν ἡγήσωνται μὴ ὠφέλιμον εἶναι τὸν ἔρωτα, βίᾳ μέν, ὅμως δὲ ἀπέχονται, καὶ ἡμεῖς οὕτως, διὰ τὸν ἐγγεγονότα μὲν ἔρωτα τῆς τοιαύτης ποιήσεως ὑπὸ τῆς τῶν καλῶν πολιτειῶν","st":"607e"},{"sp":"N","t":"τροφῆς, εὖνοι μὲν ἐσόμεθα φανῆναι αὐτὴν ὡς βελτίστην καὶ ἀληθεστάτην, ἕως δ᾽ ἂν μὴ οἵα τ᾽ ᾖ ἀπολογήσασθαι, ἀκροασόμεθ᾽ αὐτῆς ἐπᾴδοντες ἡμῖν αὐτοῖς τοῦτον τὸν λόγον, ὃν λέγομεν, καὶ ταύτην τὴν ἐπῳδήν, εὐλαβούμενοι πάλιν ἐμπεσεῖν εἰς τὸν παιδικόν τε καὶ τὸν τῶν πολλῶν ἔρωτα. ᾀσόμεθα δ᾽ οὖν ὡς οὐ σπουδαστέον ἐπὶ τῇ τοιαύτῃ ποιήσει ὡς ἀληθείας τε ἁπτομένῃ καὶ σπουδαίᾳ, ἀλλ᾽ εὐλαβητέον","st":"608a"},{"sp":"N","t":"αὐτὴν ὂν τῷ ἀκροωμένῳ, περὶ τῆς ἐν αὑτῷ πολιτείας δεδιότι, καὶ νομιστέα ἅπερ εἰρήκαμεν περὶ ποιήσεως.","st":"608b"},{"sp":"N","t":"παντάπασιν, ἦ δ᾽ ὅς, σύμφημι.","st":"608b"},{"sp":"N","t":"μέγας γάρ, ἔφην, ὁ ἀγών, ὦ φίλε Γλαύκων, μέγας, οὐχ ὅσος δοκεῖ, τὸ χρηστὸν ἢ κακὸν γενέσθαι, ὥστε οὔτε τιμῇ ἐπαρθέντα οὔτε χρήμασιν οὔτε ἀρχῇ οὐδεμιᾷ οὐδέ γε ποιητικῇ ἄξιον ἀμελῆσαι δικαιοσύνης τε καὶ τῆς ἄλλης ἀρετῆς.","st":"608b"},{"sp":"N","t":"σύμφημί σοι, ἔφη, ἐξ ὧν διεληλύθαμεν: οἶμαι δὲ καὶ ἄλλον ὁντινοῦν.","st":"608b"},{"sp":"N","t":"καὶ μήν, ἦν δ᾽ ἐγώ, τά γε μέγιστα ἐπίχειρα ἀρετῆς καὶ προκείμενα ἆθλα οὐ διεληλύθαμεν.","st":"608c"},{"sp":"N","t":"ἀμήχανόν τι, ἔφη, λέγεις μέγεθος, εἰ τῶν εἰρημένων μείζω ἐστὶν ἄλλα.","st":"608c"},{"sp":"N","t":"τί δ᾽ ἄν, ἦν δ᾽ ἐγώ, ἔν γε ὀλίγῳ χρόνῳ μέγα γένοιτο; πᾶς γὰρ οὗτός γε ὁ ἐκ παιδὸς μέχρι πρεσβύτου χρόνος πρὸς πάντα ὀλίγος πού τις ἂν εἴη.","st":"608c"},{"sp":"N","t":"οὐδὲν μὲν οὖν, ἔφη.","st":"608c"},{"sp":"N","t":"τί οὖν; οἴει ἀθανάτῳ πράγματι ὑπὲρ τοσούτου δεῖν","st":"608c"},{"sp":"N","t":"χρόνου ἐσπουδακέναι, ἀλλ᾽ οὐχ ὑπὲρ τοῦ παντός;","st":"608d"},{"sp":"N","t":"οἶμαι ἔγωγ᾽, ἔφη: ἀλλὰ τί τοῦτο λέγεις;","st":"608d"},{"sp":"N","t":"οὐκ ᾔσθησαι, ἦν δ᾽ ἐγώ, ὅτι ἀθάνατος ἡμῶν ἡ ψυχὴ καὶ οὐδέποτε ἀπόλλυται;","st":"608d"},{"sp":"N","t":"καὶ ὃς ἐμβλέψας μοι καὶ θαυμάσας εἶπε: μὰ Δί᾽, οὐκ ἔγωγε: σὺ δὲ τοῦτ᾽ ἔχεις λέγειν;","st":"608d"},{"sp":"N","t":"εἰ μὴ ἀδικῶ γ᾽, ἔφην. οἶμαι δὲ καὶ σύ: οὐδὲν γὰρ χαλεπόν.","st":"608d"},{"sp":"N","t":"ἔμοιγ᾽, ἔφη: σοῦ δ᾽ ἂν ἡδέως ἀκούσαιμι τὸ οὐ χαλεπὸν τοῦτο.","st":"608d"},{"sp":"N","t":"ἀκούοις ἄν, ἦν δ᾽ ἐγώ.","st":"608d"},{"sp":"N","t":"λέγε μόνον, ἔφη.","st":"608d"},{"sp":"N","t":"ἀγαθόν τι, εἶπον, καὶ κακὸν καλεῖς;","st":"608d"},{"sp":"N","t":"ἔγωγε.","st":"608d"},{"sp":"N","t":"ἆρ᾽ οὖν ὥσπερ ἐγὼ περὶ αὐτῶν διανοῇ;","st":"608e"},{"sp":"N","t":"τὸ ποῖον;","st":"608e"},{"sp":"N","t":"τὸ μὲν ἀπολλύον καὶ διαφθεῖρον πᾶν τὸ κακὸν εἶναι, τὸ δὲ σῷζον καὶ ὠφελοῦν τὸ ἀγαθόν.","st":"608e"},{"sp":"N","t":"ἔγωγ᾽, ἔφη.","st":"608e"},{"sp":"N","t":"τί δέ; κακὸν ἑκάστῳ τι καὶ ἀγαθὸν λέγεις; οἷον ὀφθαλμοῖς","st":"608e"},{"sp":"N","t":"ὀφθαλμίαν καὶ σύμπαντι τῷ σώματι νόσον, σίτῳ τε ἐρυσίβην, σηπεδόνα τε ξύλοις, χαλκῷ δὲ καὶ σιδήρῳ ἰόν, καί, ὅπερ λέγω, σχεδὸν πᾶσι σύμφυτον ἑκάστῳ κακόν τε καὶ νόσημα;","st":"609a"},{"sp":"N","t":"ἔγωγ᾽, ἔφη.","st":"609a"},{"sp":"N","t":"οὐκοῦν ὅταν τῴ τι τούτων προσγένηται, πονηρόν τε ποιεῖ ᾧ προσεγένετο, καὶ τελευτῶν ὅλον διέλυσεν καὶ ἀπώλεσεν;","st":"609a"},{"sp":"N","t":"πῶς γὰρ οὔ;","st":"609a"},{"sp":"N","t":"τὸ σύμφυτον ἄρα κακὸν ἑκάστου καὶ ἡ πονηρία ἕκαστον ἀπόλλυσιν, ἢ εἰ μὴ τοῦτο ἀπολεῖ, οὐκ ἂν ἄλλο γε αὐτὸ ἔτι","st":"609a"},{"sp":"N","t":"διαφθείρειεν. οὐ γὰρ τό γε ἀγαθὸν μή ποτέ τι ἀπολέσῃ, οὐδὲ αὖ τὸ μήτε κακὸν μήτε ἀγαθόν.","st":"609b"},{"sp":"N","t":"πῶς γὰρ ἄν; ἔφη.","st":"609b"},{"sp":"N","t":"ἐὰν ἄρα τι εὑρίσκωμεν τῶν ὄντων, ᾧ ἔστι μὲν κακὸν ὃ ποιεῖ αὐτὸ μοχθηρόν, τοῦτο μέντοι οὐχ οἷόν τε αὐτὸ λύειν ἀπολλύον, οὐκ ἤδη εἰσόμεθα ὅτι τοῦ πεφυκότος οὕτως ὄλεθρος οὐκ ἦν;","st":"609b"},{"sp":"N","t":"οὕτως, ἔφη, εἰκός.","st":"609b"},{"sp":"N","t":"τί οὖν; ἦν δ᾽ ἐγώ: ψυχῇ ἆρ᾽ οὐκ ἔστιν ὃ ποιεῖ αὐτὴν αὐτὴν κακήν;","st":"609b"},{"sp":"N","t":"καὶ μάλα, ἔφη: ἃ νυνδὴ διῇμεν πάντα, ἀδικία τε καὶ","st":"609b"},{"sp":"N","t":"ἀκολασία καὶ δειλία καὶ ἀμαθία.","st":"609c"},{"sp":"N","t":"ἦ οὖν τι τούτων αὐτὴν διαλύει τε καὶ ἀπόλλυσι; καὶ ἐννόει μὴ ἐξαπατηθῶμεν οἰηθέντες τὸν ἄδικον ἄνθρωπον καὶ ἀνόητον, ὅταν ληφθῇ ἀδικῶν, τότε ἀπολωλέναι ὑπὸ τῆς ἀδικίας, πονηρίας οὔσης ψυχῆς. ἀλλ᾽ ὧδε ποίει: ὥσπερ σῶμα ἡ σώματος πονηρία νόσος οὖσα τήκει καὶ διόλλυσι καὶ ἄγει εἰς τὸ μηδὲ σῶμα εἶναι, καὶ ἃ νυνδὴ ἐλέγομεν","st":"609c"},{"sp":"N","t":"ἅπαντα ὑπὸ τῆς οἰκείας κακίας, τῷ προσκαθῆσθαι καὶ ἐνεῖναι διαφθειρούσης, εἰς τὸ μὴ εἶναι ἀφικνεῖται — οὐχ οὕτω;","st":"609d"},{"sp":"N","t":"ναί.","st":"609d"},{"sp":"N","t":"ἴθι δή, καὶ ψυχὴν κατὰ τὸν αὐτὸν τρόπον σκόπει. ἆρα ἐνοῦσα ἐν αὐτῇ ἀδικία καὶ ἡ ἄλλη κακία τῷ ἐνεῖναι καὶ προσκαθῆσθαι φθείρει αὐτὴν καὶ μαραίνει, ἕως ἂν εἰς θάνατον ἀγαγοῦσα τοῦ σώματος χωρίσῃ;","st":"609d"},{"sp":"N","t":"οὐδαμῶς, ἔφη, τοῦτό γε.","st":"609d"},{"sp":"N","t":"ἀλλὰ μέντοι ἐκεῖνό γε ἄλογον, ἦν δ᾽ ἐγώ, τὴν μὲν ἄλλου πονηρίαν ἀπολλύναι τι, τὴν δὲ αὑτοῦ μή.","st":"609d"},{"sp":"N","t":"ἄλογον.","st":"609d"},{"sp":"N","t":"ἐννόει γάρ, ἦν δ᾽ ἐγώ, ὦ Γλαύκων, ὅτι οὐδ᾽ ὑπὸ τῆς τῶν σιτίων πονηρίας, ἣ ἂν ᾖ αὐτῶν ἐκείνων, εἴτε παλαιότης εἴτε σαπρότης εἴτε ἡτισοῦν οὖσα, οὐκ οἰόμεθα δεῖν σῶμα ἀπόλλυσθαι: ἀλλ᾽ ἐὰν μὲν ἐμποιῇ ἡ αὐτῶν πονηρία τῶν σιτίων τῷ σώματι σώματος μοχθηρίαν, φήσομεν αὐτὸ δι᾽ ἐκεῖνα ὑπὸ τῆς αὑτοῦ κακίας νόσου οὔσης ἀπολωλέναι: ὑπὸ","st":"609e"},{"sp":"N","t":"δὲ σιτίων πονηρίας ἄλλων ὄντων ἄλλο ὂν τὸ σῶμα, ὑπ᾽ ἀλλοτρίου κακοῦ μὴ ἐμποιήσαντος τὸ ἔμφυτον κακόν, οὐδέποτε ἀξιώσομεν διαφθείρεσθαι.","st":"610a"},{"sp":"N","t":"ὀρθότατ᾽ αὖ, ἔφη, λέγεις.","st":"610a"},{"sp":"N","t":"κατὰ τὸν αὐτὸν τοίνυν λόγον, ἦν δ᾽ ἐγώ, ἐὰν μὴ σώματος πονηρία ψυχῇ ψυχῆς πονηρίαν ἐμποιῇ, μή ποτε ἀξιῶμεν ὑπὸ ἀλλοτρίου κακοῦ ἄνευ τῆς ἰδίας πονηρίας ψυχὴν ἀπόλλυσθαι, τῷ ἑτέρου κακῷ ἕτερον.","st":"610a"},{"sp":"N","t":"ἔχει γάρ, ἔφη, λόγον.","st":"610a"},{"sp":"N","t":"ἢ τοίνυν ταῦτα ἐξελέγξωμεν ὅτι οὐ καλῶς λέγομεν, ἢ","st":"610a"},{"sp":"N","t":"ἕως ἂν ᾖ ἀνέλεγκτα, μή ποτε φῶμεν ὑπὸ πυρετοῦ μηδ᾽ αὖ ὑπ᾽ ἄλλης νόσου μηδ᾽ αὖ ὑπὸ σφαγῆς, μηδ᾽ εἴ τις ὅτι σμικρότατα ὅλον τὸ σῶμα κατατέμοι, ἕνεκα τούτων μηδὲν μᾶλλόν ποτε ψυχὴν ἀπόλλυσθαι, πρὶν ἄν τις ἀποδείξῃ ὡς διὰ ταῦτα τὰ παθήματα τοῦ σώματος αὐτὴ ἐκείνη ἀδικωτέρα καὶ ἀνοσιωτέρα γίγνεται: ἀλλοτρίου δὲ κακοῦ ἐν ἄλλῳ γιγνομένου, τοῦ δὲ ἰδίου ἑκάστῳ μὴ ἐγγιγνομένου,","st":"610b"},{"sp":"N","t":"μήτε ψυχὴν μήτε ἄλλο μηδὲν ἐῶμεν φάναι τινὰ ἀπόλλυσθαι.","st":"610c"},{"sp":"N","t":"ἀλλὰ μέντοι, ἔφη, τοῦτό γε οὐδείς ποτε δείξει, ὡς τῶν ἀποθνῃσκόντων ἀδικώτεραι αἱ ψυχαὶ διὰ τὸν θάνατον γίγνονται.","st":"610c"},{"sp":"N","t":"ἐὰν δέ γέ τις, ἔφην ἐγώ, ὁμόσε τῷ λόγῳ τολμᾷ ἰέναι καὶ λέγειν ὡς πονηρότερος καὶ ἀδικώτερος γίγνεται ὁ ἀποθνῄσκων, ἵνα δὴ μὴ ἀναγκάζηται ἀθανάτους τὰς ψυχὰς ὁμολογεῖν, ἀξιώσομέν που, εἰ ἀληθῆ λέγει ὁ ταῦτα λέγων, τὴν ἀδικίαν εἶναι θανάσιμον τῷ ἔχοντι ὥσπερ νόσον, καὶ ὑπ᾽","st":"610c"},{"sp":"N","t":"αὐτοῦ, τοῦ ἀποκτεινύντος τῇ ἑαυτοῦ φύσει, ἀποθνῄσκειν τοὺς λαμβάνοντας αὐτό, τοὺς μὲν μάλιστα θᾶττον, τοὺς δ᾽ ἧττον σχολαίτερον, ἀλλὰ μὴ ὥσπερ νῦν διὰ τοῦτο ὑπ᾽ ἄλλων δίκην ἐπιτιθέντων ἀποθνῄσκουσιν οἱ ἄδικοι.","st":"610d"},{"sp":"N","t":"μὰ Δί᾽, ἦ δ᾽ ὅς, οὐκ ἄρα πάνδεινον φανεῖται ἡ ἀδικία, εἰ θανάσιμον ἔσται τῷ λαμβάνοντι — ἀπαλλαγὴ γὰρ ἂν εἴη κακῶν — ἀλλὰ μᾶλλον οἶμαι αὐτὴν φανήσεσθαι πᾶν τοὐναντίον","st":"610d"},{"sp":"N","t":"τοὺς ἄλλους ἀποκτεινῦσαν, εἴπερ οἷόν τε, τὸν δ᾽ ἔχοντα καὶ μάλα ζωτικὸν παρέχουσαν, καὶ πρός γ᾽ ἔτι τῷ ζωτικῷ ἄγρυπνον: οὕτω πόρρω που, ὡς ἔοικεν, ἐσκήνηται τοῦ θανάσιμος εἶναι.","st":"610e"},{"sp":"N","t":"καλῶς, ἦν δ᾽ ἐγώ, λέγεις. ὁπότε γὰρ δὴ μὴ ἱκανὴ ἥ γε οἰκεία πονηρία καὶ τὸ οἰκεῖον κακὸν ἀποκτεῖναι καὶ ἀπολέσαι ψυχήν, σχολῇ τό γε ἐπ᾽ ἄλλου ὀλέθρῳ τεταγμένον κακὸν ψυχὴν ἤ τι ἄλλο ἀπολεῖ, πλὴν ἐφ᾽ ᾧ τέτακται.","st":"610e"},{"sp":"N","t":"σχολῇ γ᾽, ἔφη, ὥς γε τὸ εἰκός.","st":"610e"},{"sp":"N","t":"οὐκοῦν ὁπότε μηδ᾽ ὑφ᾽ ἑνὸς ἀπόλλυται κακοῦ, μήτε","st":"610e"},{"sp":"N","t":"οἰκείου μήτε ἀλλοτρίου, δῆλον ὅτι ἀνάγκη αὐτὸ ἀεὶ ὂν εἶναι: εἰ δ᾽ ἀεὶ ὄν, ἀθάνατον.","st":"611a"},{"sp":"N","t":"ἀνάγκη, ἔφη.","st":"611a"},{"sp":"N","t":"τοῦτο μὲν τοίνυν, ἦν δ᾽ ἐγώ, οὕτως ἐχέτω: εἰ δ᾽ ἔχει, ἐννοεῖς ὅτι ἀεὶ ἂν εἶεν αἱ αὐταί. οὔτε γὰρ ἄν που ἐλάττους γένοιντο μηδεμιᾶς ἀπολλυμένης, οὔτε αὖ πλείους: εἰ γὰρ ὁτιοῦν τῶν ἀθανάτων πλέον γίγνοιτο, οἶσθ᾽ ὅτι ἐκ τοῦ θνητοῦ ἂν γίγνοιτο καὶ πάντα ἂν εἴη τελευτῶντα ἀθάνατα.","st":"611a"},{"sp":"N","t":"ἀληθῆ λέγεις.","st":"611a"},{"sp":"N","t":"ἀλλ᾽, ἦν δ᾽ ἐγώ, μήτε τοῦτο οἰώμεθα — ὁ γὰρ λόγος οὐκ","st":"611a"},{"sp":"N","t":"ἐάσει — μήτε γε αὖ τῇ ἀληθεστάτῃ φύσει τοιοῦτον εἶναι ψυχήν, ὥστε πολλῆς ποικιλίας καὶ ἀνομοιότητός τε καὶ διαφορᾶς γέμειν αὐτὸ πρὸς αὑτό.","st":"611b"},{"sp":"N","t":"πῶς λέγεις; ἔφη.","st":"611b"},{"sp":"N","t":"οὐ ῥᾴδιον, ἦν δ᾽ ἐγώ, ἀίδιον εἶναι σύνθετόν τε ἐκ πολλῶν καὶ μὴ τῇ καλλίστῃ κεχρημένον συνθέσει, ὡς νῦν ἡμῖν ἐφάνη ἡ ψυχή.","st":"611b"},{"sp":"N","t":"οὔκουν εἰκός γε.","st":"611b"},{"sp":"N","t":"ὅτι μὲν τοίνυν ἀθάνατον ψυχή, καὶ ὁ ἄρτι λόγος καὶ οἱ ἄλλοι ἀναγκάσειαν ἄν: οἷον δ᾽ ἐστὶν τῇ ἀληθείᾳ, οὐ λελωβημένον","st":"611b"},{"sp":"N","t":"δεῖ αὐτὸ θεάσασθαι ὑπό τε τῆς τοῦ σώματος κοινωνίας καὶ ἄλλων κακῶν, ὥσπερ νῦν ἡμεῖς θεώμεθα, ἀλλ᾽ οἷόν ἐστιν καθαρὸν γιγνόμενον, τοιοῦτον ἱκανῶς λογισμῷ διαθεατέον, καὶ πολύ γε κάλλιον αὐτὸ εὑρήσει καὶ ἐναργέστερον δικαιοσύνας τε καὶ ἀδικίας διόψεται καὶ πάντα ἃ νῦν διήλθομεν. νῦν δὲ εἴπομεν μὲν ἀληθῆ περὶ αὐτοῦ, οἷον ἐν τῷ παρόντι φαίνεται: τεθεάμεθα μέντοι διακείμενον αὐτό, ὥσπερ οἱ τὸν","st":"611c"},{"sp":"N","t":"θαλάττιον Γλαῦκον ὁρῶντες οὐκ ἂν ἔτι ῥᾳδίως αὐτοῦ ἴδοιεν τὴν ἀρχαίαν φύσιν, ὑπὸ τοῦ τά τε παλαιὰ τοῦ σώματος μέρη τὰ μὲν ἐκκεκλάσθαι, τὰ δὲ συντετρῖφθαι καὶ πάντως λελωβῆσθαι ὑπὸ τῶν κυμάτων, ἄλλα δὲ προσπεφυκέναι, ὄστρεά τε καὶ φυκία καὶ πέτρας, ὥστε παντὶ μᾶλλον θηρίῳ ἐοικέναι ἢ οἷος ἦν φύσει, οὕτω καὶ τὴν ψυχὴν ἡμεῖς θεώμεθα διακειμένην ὑπὸ μυρίων κακῶν. ἀλλὰ δεῖ, ὦ Γλαύκων, ἐκεῖσε βλέπειν.","st":"611d"},{"sp":"N","t":"ποῖ; ἦ δ᾽ ὅς.","st":"611d"},{"sp":"N","t":"εἰς τὴν φιλοσοφίαν αὐτῆς, καὶ ἐννοεῖν ὧν ἅπτεται καὶ οἵων ἐφίεται ὁμιλιῶν, ὡς συγγενὴς οὖσα τῷ τε θείῳ καὶ ἀθανάτῳ καὶ τῷ ἀεὶ ὄντι, καὶ οἵα ἂν γένοιτο τῷ τοιούτῳ πᾶσα ἐπισπομένη καὶ ὑπὸ ταύτης τῆς ὁρμῆς ἐκκομισθεῖσα ἐκ τοῦ πόντου ἐν ᾧ νῦν ἐστίν, καὶ περικρουσθεῖσα πέτρας","st":"611e"},{"sp":"N","t":"τε καὶ ὄστρεα ἃ νῦν αὐτῇ, ἅτε γῆν ἑστιωμένῃ, γεηρὰ καὶ πετρώδη πολλὰ καὶ ἄγρια περιπέφυκεν ὑπὸ τῶν εὐδαιμόνων λεγομένων ἑστιάσεων. καὶ τότ᾽ ἄν τις ἴδοι αὐτῆς τὴν ἀληθῆ φύσιν, εἴτε πολυειδὴς εἴτε μονοειδής, εἴτε ὅπῃ ἔχει καὶ ὅπως: νῦν δὲ τὰ ἐν τῷ ἀνθρωπίνῳ βίῳ πάθη τε καὶ εἴδη, ὡς ἐγᾦμαι, ἐπιεικῶς αὐτῆς διεληλύθαμεν.","st":"612a"},{"sp":"N","t":"παντάπασι μὲν οὖν, ἔφη.","st":"612a"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, τά τε ἄλλα ἀπελυσάμεθα ἐν τῷ λόγῳ,","st":"612a"},{"sp":"N","t":"καὶ οὐ τοὺς μισθοὺς οὐδὲ τὰς δόξας δικαιοσύνης ἐπῃνέκαμεν, ὥσπερ Ἡσίοδόν τε καὶ Ὅμηρον ὑμεῖς ἔφατε, ἀλλ᾽ αὐτὸ δικαιοσύνην αὐτῇ ψυχῇ ἄριστον ηὕρομεν, καὶ ποιητέον εἶναι αὐτῇ τὰ δίκαια, ἐάντ᾽ ἔχῃ τὸν Γύγου δακτύλιον, ἐάντε μή, καὶ πρὸς τοιούτῳ δακτυλίῳ τὴν Ἄιδος κυνῆν;","st":"612b"},{"sp":"N","t":"ἀληθέστατα, ἔφη, λέγεις.","st":"612b"},{"sp":"N","t":"ἆρ᾽ οὖν, ἦν δ᾽ ἐγώ, ὦ Γλαύκων, νῦν ἤδη ἀνεπίφθονόν ἐστιν πρὸς ἐκείνοις καὶ τοὺς μισθοὺς τῇ δικαιοσύνῃ καὶ τῇ","st":"612b"},{"sp":"N","t":"ἄλλῃ ἀρετῇ ἀποδοῦναι, ὅσους τε καὶ οἵους τῇ ψυχῇ παρέχει παρ᾽ ἀνθρώπων τε καὶ θεῶν, ζῶντός τε ἔτι τοῦ ἀνθρώπου καὶ ἐπειδὰν τελευτήσῃ;","st":"612c"},{"sp":"N","t":"παντάπασι μὲν οὖν, ἦ δ᾽ ὅς.","st":"612c"},{"sp":"N","t":"ἆρ᾽ οὖν ἀποδώσετέ μοι ἃ ἐδανείσασθε ἐν τῷ λόγῳ;","st":"612c"},{"sp":"N","t":"τί μάλιστα;","st":"612c"},{"sp":"N","t":"ἔδωκα ὑμῖν τὸν δίκαιον δοκεῖν ἄδικον εἶναι καὶ τὸν ἄδικον δίκαιον: ὑμεῖς γὰρ ᾐτεῖσθε, κἂν εἰ μὴ δυνατὸν εἴη ταῦτα λανθάνειν καὶ θεοὺς καὶ ἀνθρώπους, ὅμως δοτέον εἶναι τοῦ λόγου ἕνεκα, ἵνα αὐτὴ δικαιοσύνη πρὸς ἀδικίαν αὐτὴν","st":"612c"},{"sp":"N","t":"κριθείη. ἢ οὐ μνημονεύεις;","st":"612d"},{"sp":"N","t":"ἀδικοίην μεντἄν, ἔφη, εἰ μή.","st":"612d"},{"sp":"N","t":"ἐπειδὴ τοίνυν, ἦν δ᾽ ἐγώ, κεκριμέναι εἰσί, πάλιν ἀπαιτῶ ὑπὲρ δικαιοσύνης, ὥσπερ ἔχει δόξης καὶ παρὰ θεῶν καὶ παρ᾽ ἀνθρώπων, καὶ ἡμᾶς ὁμολογεῖν περὶ αὐτῆς δοκεῖσθαι οὕτω, ἵνα καὶ τὰ νικητήρια κομίσηται, ἀπὸ τοῦ δοκεῖν κτωμένη ἃ δίδωσι τοῖς ἔχουσιν αὐτήν, ἐπειδὴ καὶ τὰ ἀπὸ τοῦ εἶναι ἀγαθὰ διδοῦσα ἐφάνη καὶ οὐκ ἐξαπατῶσα τοὺς τῷ ὄντι λαμβάνοντας αὐτήν.","st":"612d"},{"sp":"N","t":"δίκαια, ἔφη, αἰτῇ.","st":"612e"},{"sp":"N","t":"οὐκοῦν, ἦν δ᾽ ἐγώ, πρῶτον μὲν τοῦτο ἀποδώσετε, ὅτι θεούς γε οὐ λανθάνει ἑκάτερος αὐτῶν οἷός ἐστιν;","st":"612e"},{"sp":"N","t":"ἀποδώσομεν, ἔφη.","st":"612e"},{"sp":"N","t":"εἰ δὲ μὴ λανθάνετον, ὁ μὲν θεοφιλὴς ἂν εἴη, ὁ δὲ θεομισής, ὥσπερ καὶ κατ᾽ ἀρχὰς ὡμολογοῦμεν.","st":"612e"},{"sp":"N","t":"ἔστι ταῦτα.","st":"612e"},{"sp":"N","t":"τῷ δὲ θεοφιλεῖ οὐχ ὁμολογήσομεν, ὅσα γε ἀπὸ θεῶν","st":"612e"},{"sp":"N","t":"γίγνεται, πάντα γίγνεσθαι ὡς οἷόν τε ἄριστα, εἰ μή τι ἀναγκαῖον αὐτῷ κακὸν ἐκ προτέρας ἁμαρτίας ὑπῆρχεν;","st":"613a"},{"sp":"N","t":"πάνυ μὲν οὖν.","st":"613a"},{"sp":"N","t":"οὕτως ἄρα ὑποληπτέον περὶ τοῦ δικαίου ἀνδρός, ἐάντ᾽ ἐν πενίᾳ γίγνηται ἐάντ᾽ ἐν νόσοις ἤ τινι ἄλλῳ τῶν δοκούντων κακῶν, ὡς τούτῳ ταῦτα εἰς ἀγαθόν τι τελευτήσει ζῶντι ἢ καὶ ἀποθανόντι. οὐ γὰρ δὴ ὑπό γε θεῶν ποτε ἀμελεῖται ὃς ἂν προθυμεῖσθαι ἐθέλῃ δίκαιος γίγνεσθαι καὶ ἐπιτηδεύων","st":"613a"},{"sp":"N","t":"ἀρετὴν εἰς ὅσον δυνατὸν ἀνθρώπῳ ὁμοιοῦσθαι θεῷ.","st":"613b"},{"sp":"N","t":"εἰκός γ᾽, ἔφη, τὸν τοιοῦτον μὴ ἀμελεῖσθαι ὑπὸ τοῦ ὁμοίου.","st":"613b"},{"sp":"N","t":"οὐκοῦν περὶ τοῦ ἀδίκου τἀναντία τούτων δεῖ διανοεῖσθαι;","st":"613b"},{"sp":"N","t":"σφόδρα γε.","st":"613b"},{"sp":"N","t":"τὰ μὲν δὴ παρὰ θεῶν τοιαῦτ᾽ ἄττ᾽ ἂν εἴη νικητήρια τῷ δικαίῳ.","st":"613b"},{"sp":"N","t":"κατὰ γοῦν ἐμὴν δόξαν, ἔφη.","st":"613b"},{"sp":"N","t":"τί δέ, ἦν δ᾽ ἐγώ, παρ᾽ ἀνθρώπων; ἆρ᾽ οὐχ ὧδε ἔχει, εἰ δεῖ τὸ ὂν τιθέναι; οὐχ οἱ μὲν δεινοί τε καὶ ἄδικοι δρῶσιν ὅπερ οἱ δρομῆς ὅσοι ἂν θέωσιν εὖ ἀπὸ τῶν κάτω, ἀπὸ δὲ τῶν ἄνω μή; τὸ μὲν πρῶτον ὀξέως ἀποπηδῶσιν, τελευτῶντες","st":"613b"},{"sp":"N","t":"δὲ καταγέλαστοι γίγνονται, τὰ ὦτα ἐπὶ τῶν ὤμων ἔχοντες καὶ ἀστεφάνωτοι ἀποτρέχοντες: οἱ δὲ τῇ ἀληθείᾳ δρομικοὶ εἰς τέλος ἐλθόντες τά τε ἆθλα λαμβάνουσιν καὶ στεφανοῦνται. οὐχ οὕτω καὶ περὶ τῶν δικαίων τὸ πολὺ συμβαίνει; πρὸς τὸ τέλος ἑκάστης πράξεως καὶ ὁμιλίας καὶ τοῦ βίου εὐδοκιμοῦσί τε καὶ τὰ ἆθλα παρὰ τῶν ἀνθρώπων φέρονται;","st":"613c"},{"sp":"N","t":"καὶ μάλα.","st":"613c"},{"sp":"N","t":"ἀνέξῃ ἄρα λέγοντος ἐμοῦ περὶ τούτων ἅπερ αὐτὸς ἔλεγες","st":"613c"},{"sp":"N","t":"περὶ τῶν ἀδίκων; ἐρῶ γὰρ δὴ ὅτι οἱ μὲν δίκαιοι, ἐπειδὰν πρεσβύτεροι γένωνται, ἐν τῇ αὑτῶν πόλει ἄρχουσί τε ἂν βούλωνται τὰς ἀρχάς, γαμοῦσί τε ὁπόθεν ἂν βούλωνται, ἐκδιδόασί τε εἰς οὓς ἂν ἐθέλωσι: καὶ πάντα ἃ σὺ περὶ ἐκείνων, ἐγὼ νῦν λέγω περὶ τῶνδε. καὶ αὖ καὶ περὶ τῶν ἀδίκων, ὅτι οἱ πολλοὶ αὐτῶν, καὶ ἐὰν νέοι ὄντες λάθωσιν, ἐπὶ τέλους τοῦ δρόμου αἱρεθέντες καταγέλαστοί εἰσιν καὶ γέροντες γιγνόμενοι ἄθλιοι προπηλακίζονται ὑπὸ ξένων τε","st":"613d"},{"sp":"N","t":"καὶ ἀστῶν, μαστιγούμενοι καὶ ἃ ἄγροικα ἔφησθα σὺ εἶναι, ἀληθῆ λέγων — εἶτα στρεβλώσονται καὶ ἐκκαυθήσονται- πάντα ἐκεῖνα οἴου καὶ ἐμοῦ ἀκηκοέναι ὡς πάσχουσιν. ἀλλ᾽ ὃ λέγω, ὅρα εἰ ἀνέξῃ.","st":"613e"},{"sp":"N","t":"καὶ πάνυ, ἔφη: δίκαια γὰρ λέγεις.","st":"613e"},{"sp":"N","t":"ἃ μὲν τοίνυν, ἦν δ᾽ ἐγώ, ζῶντι τῷ δικαίῳ παρὰ θεῶν τε","st":"613e"},{"sp":"N","t":"καὶ ἀνθρώπων ἆθλά τε καὶ μισθοὶ καὶ δῶρα γίγνεται πρὸς ἐκείνοις τοῖς ἀγαθοῖς οἷς αὐτὴ παρείχετο ἡ δικαιοσύνη, τοιαῦτ᾽ ἂν εἴη.","st":"614a"},{"sp":"N","t":"καὶ μάλ᾽, ἔφη, καλά τε καὶ βέβαια.","st":"614a"},{"sp":"N","t":"ταῦτα τοίνυν, ἦν δ᾽ ἐγώ, οὐδέν ἐστι πλήθει οὐδὲ μεγέθει πρὸς ἐκεῖνα ἃ τελευτήσαντα ἑκάτερον περιμένει: χρὴ δ᾽ αὐτὰ ἀκοῦσαι, ἵνα τελέως ἑκάτερος αὐτῶν ἀπειλήφῃ τὰ ὑπὸ τοῦ λόγου ὀφειλόμενα ἀκοῦσαι.","st":"614a"},{"sp":"N","t":"λέγοις ἄν, ἔφη, ὡς οὐ πολλὰ ἄλλ᾽ ἥδιον ἀκούοντι.","st":"614b"},{"sp":"N","t":"ἀλλ᾽ οὐ μέντοι σοι, ἦν δ᾽ ἐγώ, Ἀλκίνου γε ἀπόλογον ἐρῶ, ἀλλ᾽ ἀλκίμου μὲν ἀνδρός, Ἠρὸς τοῦ Ἀρμενίου, τὸ γένος Παμφύλου: ὅς ποτε ἐν πολέμῳ τελευτήσας, ἀναιρεθέντων δεκαταίων τῶν νεκρῶν ἤδη διεφθαρμένων, ὑγιὴς μὲν ἀνῃρέθη, κομισθεὶς δ᾽ οἴκαδε μέλλων θάπτεσθαι δωδεκαταῖος ἐπὶ τῇ πυρᾷ κείμενος ἀνεβίω, ἀναβιοὺς δ᾽ ἔλεγεν ἃ ἐκεῖ ἴδοι. ἔφη δέ, ἐπειδὴ οὗ ἐκβῆναι, τὴν ψυχὴν πορεύεσθαι","st":"614b"},{"sp":"N","t":"μετὰ πολλῶν, καὶ ἀφικνεῖσθαι σφᾶς εἰς τόπον τινὰ δαιμόνιον, ἐν ᾧ τῆς τε γῆς δύ᾽ εἶναι χάσματα ἐχομένω ἀλλήλοιν καὶ τοῦ οὐρανοῦ αὖ ἐν τῷ ἄνω ἄλλα καταντικρύ. δικαστὰς δὲ μεταξὺ τούτων καθῆσθαι, οὕς, ἐπειδὴ διαδικάσειαν, τοὺς μὲν δικαίους κελεύειν πορεύεσθαι τὴν εἰς δεξιάν τε καὶ ἄνω διὰ τοῦ οὐρανοῦ, σημεῖα περιάψαντας τῶν δεδικασμένων ἐν τῷ πρόσθεν, τοὺς δὲ ἀδίκους τὴν εἰς ἀριστεράν τε καὶ κάτω, ἔχοντας καὶ τούτους ἐν τῷ ὄπισθεν σημεῖα πάντων ὧν","st":"614c"},{"sp":"N","t":"ἔπραξαν. ἑαυτοῦ δὲ προσελθόντος εἰπεῖν ὅτι δέοι αὐτὸν ἄγγελον ἀνθρώποις γενέσθαι τῶν ἐκεῖ καὶ διακελεύοιντό οἱ ἀκούειν τε καὶ θεᾶσθαι πάντα τὰ ἐν τῷ τόπῳ. ὁρᾶν δὴ ταύτῃ μὲν καθ᾽ ἑκάτερον τὸ χάσμα τοῦ οὐρανοῦ τε καὶ τῆς γῆς ἀπιούσας τὰς ψυχάς, ἐπειδὴ αὐταῖς δικασθείη, κατὰ δὲ τὼ ἑτέρω ἐκ μὲν τοῦ ἀνιέναι ἐκ τῆς γῆς μεστὰς αὐχμοῦ τε καὶ κόνεως, ἐκ δὲ τοῦ ἑτέρου καταβαίνειν ἑτέρας ἐκ τοῦ","st":"614d"},{"sp":"N","t":"οὐρανοῦ καθαράς. καὶ τὰς ἀεὶ ἀφικνουμένας ὥσπερ ἐκ πολλῆς πορείας φαίνεσθαι ἥκειν, καὶ ἁσμένας εἰς τὸν λειμῶνα ἀπιούσας οἷον ἐν πανηγύρει κατασκηνᾶσθαι, καὶ ἀσπάζεσθαί τε ἀλλήλας ὅσαι γνώριμαι, καὶ πυνθάνεσθαι τάς τε ἐκ τῆς γῆς ἡκούσας παρὰ τῶν ἑτέρων τὰ ἐκεῖ καὶ τὰς ἐκ τοῦ οὐρανοῦ τὰ παρ᾽ ἐκείναις. διηγεῖσθαι δὲ ἀλλήλαις τὰς","st":"614e"},{"sp":"N","t":"μὲν ὀδυρομένας τε καὶ κλαούσας, ἀναμιμνῃσκομένας ὅσα τε καὶ οἷα πάθοιεν καὶ ἴδοιεν ἐν τῇ ὑπὸ γῆς πορείᾳ — εἶναι δὲ τὴν πορείαν χιλιέτη — τὰς δ᾽ αὖ ἐκ τοῦ οὐρανοῦ εὐπαθείας διηγεῖσθαι καὶ θέας ἀμηχάνους τὸ κάλλος. τὰ μὲν οὖν πολλά, ὦ Γλαύκων, πολλοῦ χρόνου διηγήσασθαι: τὸ δ᾽ οὖν κεφάλαιον ἔφη τόδε εἶναι, ὅσα πώποτέ τινα ἠδίκησαν καὶ ὅσους ἕκαστοι, ὑπὲρ ἁπάντων δίκην δεδωκέναι ἐν μέρει, ὑπὲρ ἑκάστου δεκάκις — τοῦτο δ᾽ εἶναι κατὰ ἑκατονταετηρίδα","st":"615a"},{"sp":"N","t":"ἑκάστην, ὡς βίου ὄντος τοσούτου τοῦ ἀνθρωπίνου — ἵνα δεκαπλάσιον τὸ ἔκτεισμα τοῦ ἀδικήματος ἐκτίνοιεν, καὶ οἷον εἴ τινες πολλοῖς θανάτων ἦσαν αἴτιοι, ἢ πόλεις προδόντες ἢ στρατόπεδα, καὶ εἰς δουλείας ἐμβεβληκότες ἤ τινος ἄλλης κακουχίας μεταίτιοι, πάντων τούτων δεκαπλασίας ἀλγηδόνας ὑπὲρ ἑκάστου κομίσαιντο, καὶ αὖ εἴ τινας εὐεργεσίας εὐεργετηκότες καὶ δίκαιοι καὶ ὅσιοι γεγονότες εἶεν, κατὰ ταὐτὰ","st":"615b"},{"sp":"N","t":"τὴν ἀξίαν κομίζοιντο. τῶν δὲ εὐθὺς γενομένων καὶ ὀλίγον χρόνον βιούντων πέρι ἄλλα ἔλεγεν οὐκ ἄξια μνήμης. εἰς δὲ θεοὺς ἀσεβείας τε καὶ εὐσεβείας καὶ γονέας καὶ αὐτόχειρος φόνου μείζους ἔτι τοὺς μισθοὺς διηγεῖτο.","st":"615c"},{"sp":"N","t":"ἔφη γὰρ δὴ παραγενέσθαι ἐρωτωμένῳ ἑτέρῳ ὑπὸ ἑτέρου ὅπου εἴη Ἀρδιαῖος ὁ μέγας. ὁ δὲ Ἀρδιαῖος οὗτος τῆς Παμφυλίας ἔν τινι πόλει τύραννος ἐγεγόνει, ἤδη χιλιοστὸν ἔτος εἰς ἐκεῖνον τὸν χρόνον, γέροντά τε πατέρα ἀποκτείνας","st":"615c"},{"sp":"N","t":"καὶ πρεσβύτερον ἀδελφόν, καὶ ἄλλα δὴ πολλά τε καὶ ἀνόσια εἰργασμένος, ὡς ἐλέγετο. ἔφη οὖν τὸν ἐρωτώμενον εἰπεῖν, “οὐχ ἥκει,” φάναι, “οὐδ᾽ ἂν ἥξει δεῦρο. ἐθεασάμεθα γὰρ οὖν δὴ καὶ τοῦτο τῶν δεινῶν θεαμάτων: ἐπειδὴ ἐγγὺς τοῦ στομίου ἦμεν μέλλοντες ἀνιέναι καὶ τἆλλα πάντα πεπονθότες, ἐκεῖνόν τε κατείδομεν ἐξαίφνης καὶ ἄλλους — σχεδόν τι αὐτῶν τοὺς πλείστους τυράννους: ἦσαν δὲ καὶ ἰδιῶταί τινες τῶν","st":"615d"},{"sp":"N","t":"μεγάλα ἡμαρτηκότων — οὓς οἰομένους ἤδη ἀναβήσεσθαι οὐκ ἐδέχετο τὸ στόμιον, ἀλλ᾽ ἐμυκᾶτο ὁπότε τις τῶν οὕτως ἀνιάτως ἐχόντων εἰς πονηρίαν ἢ μὴ ἱκανῶς δεδωκὼς δίκην ἐπιχειροῖ ἀνιέναι. ἐνταῦθα δὴ ἄνδρες, ἔφη, ἄγριοι, διάπυροι ἰδεῖν, παρεστῶτες καὶ καταμανθάνοντες τὸ φθέγμα, τοὺς μὲν διαλαβόντες ἦγον, τὸν δὲ Ἀρδιαῖον καὶ ἄλλους συμποδίσαντες","st":"615e"},{"sp":"N","t":"χεῖράς τε καὶ πόδας καὶ κεφαλήν, καταβαλόντες καὶ ἐκδείραντες, εἷλκον παρὰ τὴν ὁδὸν ἐκτὸς ἐπ᾽ ἀσπαλάθων κνάμπτοντες, καὶ τοῖς ἀεὶ παριοῦσι σημαίνοντες ὧν ἕνεκά τε καὶ ὅτι εἰς τὸν Τάρταρον ἐμπεσούμενοι ἄγοιντο.” ἔνθα δὴ φόβων, ἔφη, πολλῶν καὶ παντοδαπῶν σφίσι γεγονότων, τοῦτον ὑπερβάλλειν, μὴ γένοιτο ἑκάστῳ τὸ φθέγμα ὅτε ἀναβαίνοι, καὶ ἁσμενέστατα ἕκαστον σιγήσαντος ἀναβῆναι. καὶ τὰς μὲν δὴ δίκας τε καὶ τιμωρίας τοιαύτας τινὰς","st":"616a"},{"sp":"N","t":"εἶναι, καὶ αὖ τὰς εὐεργεσίας ταύταις ἀντιστρόφους. ἐπειδὴ δὲ τοῖς ἐν τῷ λειμῶνι ἑκάστοις ἑπτὰ ἡμέραι γένοιντο, ἀναστάντας ἐντεῦθεν δεῖν τῇ ὀγδόῃ πορεύεσθαι, καὶ ἀφικνεῖσθαι τεταρταίους ὅθεν καθορᾶν ἄνωθεν διὰ παντὸς τοῦ οὐρανοῦ καὶ γῆς τεταμένον φῶς εὐθύ, οἷον κίονα, μάλιστα τῇ ἴριδι προσφερῆ, λαμπρότερον δὲ καὶ καθαρώτερον: εἰς ὃ ἀφικέσθαι προελθόντες ἡμερησίαν ὁδόν, καὶ ἰδεῖν αὐτόθι κατὰ","st":"616b"},{"sp":"N","t":"μέσον τὸ φῶς ἐκ τοῦ οὐρανοῦ τὰ ἄκρα αὐτοῦ τῶν δεσμῶν τεταμένα — εἶναι γὰρ τοῦτο τὸ φῶς σύνδεσμον τοῦ οὐρανοῦ, οἷον τὰ ὑποζώματα τῶν τριήρων, οὕτω πᾶσαν συνέχον τὴν περιφοράν — ἐκ δὲ τῶν ἄκρων τεταμένον ἀνάγκης ἄτρακτον, δι᾽ οὗ πάσας ἐπιστρέφεσθαι τὰς περιφοράς: οὗ τὴν μὲν ἠλακάτην τε καὶ τὸ ἄγκιστρον εἶναι ἐξ ἀδάμαντος, τὸν δὲ σφόνδυλον μεικτὸν ἔκ τε τούτου καὶ ἄλλων γενῶν. τὴν δὲ","st":"616c"},{"sp":"N","t":"τοῦ σφονδύλου φύσιν εἶναι τοιάνδε: τὸ μὲν σχῆμα οἵαπερ ἡ τοῦ ἐνθάδε, νοῆσαι δὲ δεῖ ἐξ ὧν ἔλεγεν τοιόνδε αὐτὸν εἶναι, ὥσπερ ἂν εἰ ἐν ἑνὶ μεγάλῳ σφονδύλῳ κοίλῳ καὶ ἐξεγλυμμένῳ διαμπερὲς ἄλλος τοιοῦτος ἐλάττων ἐγκέοιτο ἁρμόττων, καθάπερ οἱ κάδοι οἱ εἰς ἀλλήλους ἁρμόττοντες, καὶ οὕτω δὴ τρίτον ἄλλον καὶ τέταρτον καὶ ἄλλους τέτταρας. ὀκτὼ γὰρ εἶναι τοὺς σύμπαντας σφονδύλους, ἐν ἀλλήλοις ἐγκειμένους,","st":"616d"},{"sp":"N","t":"κύκλους ἄνωθεν τὰ χείλη φαίνοντας, νῶτον συνεχὲς ἑνὸς σφονδύλου ἀπεργαζομένους περὶ τὴν ἠλακάτην: ἐκείνην δὲ διὰ μέσου τοῦ ὀγδόου διαμπερὲς ἐληλάσθαι. τὸν μὲν οὖν πρῶτόν τε καὶ ἐξωτάτω σφόνδυλον πλατύτατον τὸν τοῦ χείλους κύκλον ἔχειν, τὸν δὲ τοῦ ἕκτου δεύτερον, τρίτον δὲ τὸν τοῦ τετάρτου, τέταρτον δὲ τὸν τοῦ ὀγδόου, πέμπτον δὲ τὸν τοῦ ἑβδόμου, ἕκτον δὲ τὸν τοῦ πέμπτου, ἕβδομον δὲ τὸν τοῦ τρίτου, ὄγδοον δὲ τὸν τοῦ δευτέρου. καὶ τὸν μὲν τοῦ μεγίστου ποικίλον, τὸν δὲ τοῦ ἑβδόμου λαμπρότατον, τὸν δὲ","st":"616e"},{"sp":"N","t":"τοῦ ὀγδόου τὸ χρῶμα ἀπὸ τοῦ ἑβδόμου ἔχειν προσλάμποντος, τὸν δὲ τοῦ δευτέρου καὶ πέμπτου παραπλήσια ἀλλήλοις, ξανθότερα ἐκείνων, τρίτον δὲ λευκότατον χρῶμα ἔχειν, τέταρτον δὲ ὑπέρυθρον, δεύτερον δὲ λευκότητι τὸν ἕκτον. κυκλεῖσθαι δὲ δὴ στρεφόμενον τὸν ἄτρακτον ὅλον μὲν τὴν αὐτὴν φοράν, ἐν δὲ τῷ ὅλῳ περιφερομένῳ τοὺς μὲν ἐντὸς ἑπτὰ κύκλους τὴν ἐναντίαν τῷ ὅλῳ ἠρέμα περιφέρεσθαι, αὐτῶν δὲ τούτων τάχιστα μὲν ἰέναι τὸν ὄγδοον, δευτέρους δὲ καὶ ἅμα","st":"617a"},{"sp":"N","t":"ἀλλήλοις τόν τε ἕβδομον καὶ ἕκτον καὶ πέμπτον: [τὸν] τρίτον δὲ φορᾷ ἰέναι, ὡς σφίσι φαίνεσθαι, ἐπανακυκλούμενον τὸν τέταρτον, τέταρτον δὲ τὸν τρίτον καὶ πέμπτον τὸν δεύτερον. στρέφεσθαι δὲ αὐτὸν ἐν τοῖς τῆς ἀνάγκης γόνασιν. ἐπὶ δὲ τῶν κύκλων αὐτοῦ ἄνωθεν ἐφ᾽ ἑκάστου βεβηκέναι Σειρῆνα συμπεριφερομένην, φωνὴν μίαν ἱεῖσαν, ἕνα τόνον: ἐκ πασῶν δὲ ὀκτὼ οὐσῶν μίαν ἁρμονίαν συμφωνεῖν. ἄλλας δὲ καθημένας","st":"617b"},{"sp":"N","t":"πέριξ δι᾽ ἴσου τρεῖς, ἐν θρόνῳ ἑκάστην, θυγατέρας τῆς ἀνάγκης, Μοίρας, λευχειμονούσας, στέμματα ἐπὶ τῶν κεφαλῶν ἐχούσας, Λάχεσίν τε καὶ Κλωθὼ καὶ Ἄτροπον, ὑμνεῖν πρὸς τὴν τῶν Σειρήνων ἁρμονίαν, Λάχεσιν μὲν τὰ γεγονότα, Κλωθὼ δὲ τὰ ὄντα, Ἄτροπον δὲ τὰ μέλλοντα. καὶ τὴν μὲν Κλωθὼ τῇ δεξιᾷ χειρὶ ἐφαπτομένην συνεπιστρέφειν τοῦ ἀτράκτου τὴν ἔξω περιφοράν, διαλείπουσαν χρόνον, τὴν δὲ Ἄτροπον τῇ ἀριστερᾷ τὰς ἐντὸς αὖ ὡσαύτως: τὴν δὲ Λάχεσιν","st":"617c"},{"sp":"N","t":"ἐν μέρει ἑκατέρας ἑκατέρᾳ τῇ χειρὶ ἐφάπτεσθαι. σφᾶς οὖν, ἐπειδὴ ἀφικέσθαι, εὐθὺς δεῖν ἰέναι πρὸς τὴν Λάχεσιν. προφήτην οὖν τινα σφᾶς πρῶτον μὲν ἐν τάξει διαστῆσαι, ἔπειτα λαβόντα ἐκ τῶν τῆς Λαχέσεως γονάτων κλήρους τε καὶ βίων παραδείγματα, ἀναβάντα ἐπί τι βῆμα ὑψηλὸν εἰπεῖν-","st":"617d"},{"sp":"N","t":"“ἀνάγκης θυγατρὸς κόρης Λαχέσεως λόγος. Ψυχαὶ ἐφήμεροι, ἀρχὴ ἄλλης περιόδου θνητοῦ γένους θανατηφόρου.","st":"617d"},{"sp":"N","t":"οὐχ ὑμᾶς δαίμων λήξεται, ἀλλ᾽ ὑμεῖς δαίμονα αἱρήσεσθε. πρῶτος δ᾽ ὁ λαχὼν πρῶτος αἱρείσθω βίον ᾧ συνέσται ἐξ ἀνάγκης. ἀρετὴ δὲ ἀδέσποτον, ἣν τιμῶν καὶ ἀτιμάζων πλέον καὶ ἔλαττον αὐτῆς ἕκαστος ἕξει. αἰτία ἑλομένου: θεὸς ἀναίτιος.”","st":"617e"},{"sp":"N","t":"ταῦτα εἰπόντα ῥῖψαι ἐπὶ πάντας τοὺς κλήρους, τὸν δὲ παρ᾽ αὑτὸν πεσόντα ἕκαστον ἀναιρεῖσθαι πλὴν οὗ, ἓ δὲ οὐκ ἐᾶν: τῷ δὲ ἀνελομένῳ δῆλον εἶναι ὁπόστος εἰλήχει.","st":"617e"},{"sp":"N","t":"μετὰ δὲ τοῦτο αὖθις τὰ τῶν βίων παραδείγματα εἰς τὸ πρόσθεν σφῶν θεῖναι ἐπὶ τὴν γῆν, πολὺ πλείω τῶν παρόντων. εἶναι δὲ παντοδαπά: ζῴων τε γὰρ πάντων βίους καὶ δὴ καὶ τοὺς ἀνθρωπίνους ἅπαντας. τυραννίδας τε γὰρ ἐν αὐτοῖς εἶναι, τὰς μὲν διατελεῖς, τὰς δὲ καὶ μεταξὺ διαφθειρομένας καὶ εἰς πενίας τε καὶ φυγὰς καὶ εἰς πτωχείας τελευτώσας: εἶναι δὲ καὶ δοκίμων ἀνδρῶν βίους, τοὺς μὲν ἐπὶ εἴδεσιν καὶ κατὰ κάλλη καὶ τὴν ἄλλην ἰσχύν","st":"618a"},{"sp":"N","t":"τε καὶ ἀγωνίαν, τοὺς δ᾽ ἐπὶ γένεσιν καὶ προγόνων ἀρεταῖς, καὶ ἀδοκίμων κατὰ ταῦτα, ὡσαύτως δὲ καὶ γυναικῶν. ψυχῆς δὲ τάξιν οὐκ ἐνεῖναι διὰ τὸ ἀναγκαίως ἔχειν ἄλλον ἑλομένην βίον ἀλλοίαν γίγνεσθαι: τὰ δ᾽ ἄλλα ἀλλήλοις τε καὶ πλούτοις καὶ πενίαις, τὰ δὲ νόσοις, τὰ δ᾽ ὑγιείαις μεμεῖχθαι, τὰ δὲ καὶ μεσοῦν τούτων. ἔνθα δή, ὡς ἔοικεν, ὦ φίλε Γλαύκων, ὁ πᾶς κίνδυνος ἀνθρώπῳ, καὶ διὰ ταῦτα μάλιστα","st":"618b"},{"sp":"N","t":"ἐπιμελητέον ὅπως ἕκαστος ἡμῶν τῶν ἄλλων μαθημάτων ἀμελήσας τούτου τοῦ μαθήματος καὶ ζητητὴς καὶ μαθητὴς ἔσται, ἐάν ποθεν οἷός τ᾽ ᾖ μαθεῖν καὶ ἐξευρεῖν τίς αὐτὸν ποιήσει δυνατὸν καὶ ἐπιστήμονα, βίον καὶ χρηστὸν καὶ πονηρὸν διαγιγνώσκοντα, τὸν βελτίω ἐκ τῶν δυνατῶν ἀεὶ πανταχοῦ αἱρεῖσθαι: ἀναλογιζόμενον πάντα τὰ νυνδὴ ῥηθέντα καὶ συντιθέμενα ἀλλήλοις καὶ διαιρούμενα πρὸς ἀρετὴν βίου πῶς ἔχει, εἰδέναι τί κάλλος πενίᾳ ἢ πλούτῳ κραθὲν καὶ","st":"618c"},{"sp":"N","t":"μετὰ ποίας τινὸς ψυχῆς ἕξεως κακὸν ἢ ἀγαθὸν ἐργάζεται, καὶ τί εὐγένειαι καὶ δυσγένειαι καὶ ἰδιωτεῖαι καὶ ἀρχαὶ καὶ ἰσχύες καὶ ἀσθένειαι καὶ εὐμαθίαι καὶ δυσμαθίαι καὶ πάντα τὰ τοιαῦτα τῶν φύσει περὶ ψυχὴν ὄντων καὶ τῶν ἐπικτήτων τί συγκεραννύμενα πρὸς ἄλληλα ἐργάζεται, ὥστε ἐξ ἁπάντων αὐτῶν δυνατὸν εἶναι συλλογισάμενον αἱρεῖσθαι, πρὸς τὴν τῆς ψυχῆς φύσιν ἀποβλέποντα, τόν τε χείρω καὶ τὸν ἀμείνω","st":"618d"},{"sp":"N","t":"βίον, χείρω μὲν καλοῦντα ὃς αὐτὴν ἐκεῖσε ἄξει, εἰς τὸ ἀδικωτέραν γίγνεσθαι, ἀμείνω δὲ ὅστις εἰς τὸ δικαιοτέραν. τὰ δὲ ἄλλα πάντα χαίρειν ἐάσει: ἑωράκαμεν γὰρ ὅτι ζῶντί τε καὶ τελευτήσαντι αὕτη κρατίστη αἵρεσις. ἀδαμαντίνως δὴ","st":"618e"},{"sp":"N","t":"δεῖ ταύτην τὴν δόξαν ἔχοντα εἰς Ἅιδου ἰέναι, ὅπως ἂν ᾖ καὶ ἐκεῖ ἀνέκπληκτος ὑπὸ πλούτων τε καὶ τῶν τοιούτων κακῶν, καὶ μὴ ἐμπεσὼν εἰς τυραννίδας καὶ ἄλλας τοιαύτας πράξεις πολλὰ μὲν ἐργάσηται καὶ ἀνήκεστα κακά, ἔτι δὲ αὐτὸς μείζω πάθῃ, ἀλλὰ γνῷ τὸν μέσον ἀεὶ τῶν τοιούτων βίον αἱρεῖσθαι καὶ φεύγειν τὰ ὑπερβάλλοντα ἑκατέρωσε καὶ ἐν τῷδε τῷ βίῳ κατὰ τὸ δυνατὸν καὶ ἐν παντὶ τῷ ἔπειτα: οὕτω γὰρ","st":"619a"},{"sp":"N","t":"εὐδαιμονέστατος γίγνεται ἄνθρωπος.","st":"619b"},{"sp":"N","t":"καὶ δὴ οὖν καὶ τότε ὁ ἐκεῖθεν ἄγγελος ἤγγελλε τὸν μὲν προφήτην οὕτως εἰπεῖν: “καὶ τελευταίῳ ἐπιόντι, ξὺν νῷ ἑλομένῳ, συντόνως ζῶντι κεῖται βίος ἀγαπητός, οὐ κακός. μήτε ὁ ἄρχων αἱρέσεως ἀμελείτω μήτε ὁ τελευτῶν ἀθυμείτω.”","st":"619b"},{"sp":"N","t":"εἰπόντος δὲ ταῦτα τὸν πρῶτον λαχόντα ἔφη εὐθὺς ἐπιόντα τὴν μεγίστην τυραννίδα ἑλέσθαι, καὶ ὑπὸ ἀφροσύνης τε καὶ λαιμαργίας οὐ πάντα ἱκανῶς ἀνασκεψάμενον ἑλέσθαι, ἀλλ᾽","st":"619b"},{"sp":"N","t":"αὐτὸν λαθεῖν ἐνοῦσαν εἱμαρμένην παίδων αὑτοῦ βρώσεις καὶ ἄλλα κακά: ἐπειδὴ δὲ κατὰ σχολὴν σκέψασθαι, κόπτεσθαί τε καὶ ὀδύρεσθαι τὴν αἵρεσιν, οὐκ ἐμμένοντα τοῖς προρρηθεῖσιν ὑπὸ τοῦ προφήτου: οὐ γὰρ ἑαυτὸν αἰτιᾶσθαι τῶν κακῶν, ἀλλὰ τύχην τε καὶ δαίμονας καὶ πάντα μᾶλλον ἀνθ᾽ ἑαυτοῦ. εἶναι δὲ αὐτὸν τῶν ἐκ τοῦ οὐρανοῦ ἡκόντων, ἐν τεταγμένῃ πολιτείᾳ ἐν τῷ προτέρῳ βίῳ βεβιωκότα, ἔθει","st":"619c"},{"sp":"N","t":"ἄνευ φιλοσοφίας ἀρετῆς μετειληφότα. ὡς δὲ καὶ εἰπεῖν, οὐκ ἐλάττους εἶναι ἐν τοῖς τοιούτοις ἁλισκομένους τοὺς ἐκ τοῦ οὐρανοῦ ἥκοντας, ἅτε πόνων ἀγυμνάστους: τῶν δ᾽ ἐκ τῆς γῆς τοὺς πολλούς, ἅτε αὐτούς τε πεπονηκότας ἄλλους τε ἑωρακότας, οὐκ ἐξ ἐπιδρομῆς τὰς αἱρέσεις ποιεῖσθαι. διὸ δὴ καὶ μεταβολὴν τῶν κακῶν καὶ τῶν ἀγαθῶν ταῖς πολλαῖς τῶν ψυχῶν γίγνεσθαι καὶ διὰ τὴν τοῦ κλήρου τύχην: ἐπεὶ εἴ τις ἀεί, ὁπότε εἰς τὸν ἐνθάδε βίον ἀφικνοῖτο, ὑγιῶς φιλοσοφοῖ","st":"619d"},{"sp":"N","t":"καὶ ὁ κλῆρος αὐτῷ τῆς αἱρέσεως μὴ ἐν τελευταίοις πίπτοι, κινδυνεύει ἐκ τῶν ἐκεῖθεν ἀπαγγελλομένων οὐ μόνον ἐνθάδε εὐδαιμονεῖν ἄν, ἀλλὰ καὶ τὴν ἐνθένδε ἐκεῖσε καὶ δεῦρο πάλιν πορείαν οὐκ ἂν χθονίαν καὶ τραχεῖαν πορεύεσθαι, ἀλλὰ λείαν τε καὶ οὐρανίαν.","st":"619e"},{"sp":"N","t":"ταύτην γὰρ δὴ ἔφη τὴν θέαν ἀξίαν εἶναι ἰδεῖν, ὡς ἕκασται","st":"619e"},{"sp":"N","t":"αἱ ψυχαὶ ᾑροῦντο τοὺς βίους: ἐλεινήν τε γὰρ ἰδεῖν εἶναι καὶ γελοίαν καὶ θαυμασίαν. κατὰ συνήθειαν γὰρ τοῦ προτέρου βίου τὰ πολλὰ αἱρεῖσθαι. ἰδεῖν μὲν γὰρ ψυχὴν ἔφη τήν ποτε Ὀρφέως γενομένην κύκνου βίον αἱρουμένην, μίσει τοῦ γυναικείου γένους διὰ τὸν ὑπ᾽ ἐκείνων θάνατον οὐκ ἐθέλουσαν ἐν γυναικὶ γεννηθεῖσαν γενέσθαι: ἰδεῖν δὲ τὴν Θαμύρου ἀηδόνος ἑλομένην: ἰδεῖν δὲ καὶ κύκνον μεταβάλλοντα εἰς ἀνθρωπίνου βίου αἵρεσιν, καὶ ἄλλα ζῷα μουσικὰ ὡσαύτως.","st":"620a"},{"sp":"N","t":"εἰκοστὴν δὲ λαχοῦσαν ψυχὴν ἑλέσθαι λέοντος βίον: εἶναι δὲ τὴν Αἴαντος τοῦ Τελαμωνίου, φεύγουσαν ἄνθρωπον γενέσθαι, μεμνημένην τῆς τῶν ὅπλων κρίσεως. τὴν δ᾽ ἐπὶ τούτῳ Ἀγαμέμνονος: ἔχθρᾳ δὲ καὶ ταύτην τοῦ ἀνθρωπίνου γένους διὰ τὰ πάθη ἀετοῦ διαλλάξαι βίον. ἐν μέσοις δὲ λαχοῦσαν τὴν Ἀταλάντης ψυχήν, κατιδοῦσαν μεγάλας τιμὰς ἀθλητοῦ ἀνδρός, οὐ δύνασθαι παρελθεῖν, ἀλλὰ λαβεῖν. μετὰ","st":"620b"},{"sp":"N","t":"δὲ ταύτην ἰδεῖν τὴν Ἐπειοῦ τοῦ Πανοπέως εἰς τεχνικῆς γυναικὸς ἰοῦσαν φύσιν: πόρρω δ᾽ ἐν ὑστάτοις ἰδεῖν τὴν τοῦ γελωτοποιοῦ Θερσίτου πίθηκον ἐνδυομένην. κατὰ τύχην δὲ τὴν Ὀδυσσέως λαχοῦσαν πασῶν ὑστάτην αἱρησομένην ἰέναι, μνήμῃ δὲ τῶν προτέρων πόνων φιλοτιμίας λελωφηκυῖαν ζητεῖν περιιοῦσαν χρόνον πολὺν βίον ἀνδρὸς ἰδιώτου ἀπράγμονος, καὶ μόγις εὑρεῖν κείμενόν που καὶ παρημελημένον","st":"620c"},{"sp":"N","t":"ὑπὸ τῶν ἄλλων, καὶ εἰπεῖν ἰδοῦσαν ὅτι τὰ αὐτὰ ἂν ἔπραξεν καὶ πρώτη λαχοῦσα, καὶ ἁσμένην ἑλέσθαι. καὶ ἐκ τῶν ἄλλων δὴ θηρίων ὡσαύτως εἰς ἀνθρώπους ἰέναι καὶ εἰς ἄλληλα, τὰ μὲν ἄδικα εἰς τὰ ἄγρια, τὰ δὲ δίκαια εἰς τὰ ἥμερα μεταβάλλοντα, καὶ πάσας μείξεις μείγνυσθαι.","st":"620d"},{"sp":"N","t":"ἐπειδὴ δ᾽ οὖν πάσας τὰς ψυχὰς τοὺς βίους ᾑρῆσθαι, ὥσπερ ἔλαχον ἐν τάξει προσιέναι πρὸς τὴν Λάχεσιν: ἐκείνην δ᾽ ἑκάστῳ ὃν εἵλετο δαίμονα, τοῦτον φύλακα συμπέμπειν","st":"620d"},{"sp":"N","t":"τοῦ βίου καὶ ἀποπληρωτὴν τῶν αἱρεθέντων. ὃν πρῶτον μὲν ἄγειν αὐτὴν πρὸς τὴν Κλωθὼ ὑπὸ τὴν ἐκείνης χεῖρά τε καὶ ἐπιστροφὴν τῆς τοῦ ἀτράκτου δίνης, κυροῦντα ἣν λαχὼν εἵλετο μοῖραν: ταύτης δ᾽ ἐφαψάμενον αὖθις ἐπὶ τὴν τῆς Ἀτρόπου ἄγειν νῆσιν, ἀμετάστροφα τὰ ἐπικλωσθέντα ποιοῦντα: ἐντεῦθεν δὲ δὴ ἀμεταστρεπτὶ ὑπὸ τὸν τῆς","st":"620e"},{"sp":"N","t":"ἀνάγκης ἰέναι θρόνον, καὶ δι᾽ ἐκείνου διεξελθόντα, ἐπειδὴ καὶ οἱ ἄλλοι διῆλθον, πορεύεσθαι ἅπαντας εἰς τὸ τῆς Λήθης πεδίον διὰ καύματός τε καὶ πνίγους δεινοῦ: καὶ γὰρ εἶναι αὐτὸ κενὸν δένδρων τε καὶ ὅσα γῆ φύει. σκηνᾶσθαι οὖν σφᾶς ἤδη ἑσπέρας γιγνομένης παρὰ τὸν Ἀμέλητα ποταμόν, οὗ τὸ ὕδωρ ἀγγεῖον οὐδὲν στέγειν. μέτρον μὲν οὖν τι τοῦ ὕδατος πᾶσιν ἀναγκαῖον εἶναι πιεῖν, τοὺς δὲ φρονήσει μὴ σῳζομένους πλέον πίνειν τοῦ μέτρου: τὸν δὲ ἀεὶ πιόντα","st":"621a"},{"sp":"N","t":"πάντων ἐπιλανθάνεσθαι. ἐπειδὴ δὲ κοιμηθῆναι καὶ μέσας νύκτας γενέσθαι, βροντήν τε καὶ σεισμὸν γενέσθαι, καὶ ἐντεῦθεν ἐξαπίνης ἄλλον ἄλλῃ φέρεσθαι ἄνω εἰς τὴν γένεσιν, ᾁττοντας ὥσπερ ἀστέρας. αὐτὸς δὲ τοῦ μὲν ὕδατος κωλυθῆναι πιεῖν: ὅπῃ μέντοι καὶ ὅπως εἰς τὸ σῶμα ἀφίκοιτο, οὐκ εἰδέναι, ἀλλ᾽ ἐξαίφνης ἀναβλέψας ἰδεῖν ἕωθεν αὑτὸν κείμενον ἐπὶ τῇ πυρᾷ.","st":"621b"},{"sp":"N","t":"καὶ οὕτως, ὦ Γλαύκων, μῦθος ἐσώθη καὶ οὐκ ἀπώλετο,","st":"621b"},{"sp":"N","t":"καὶ ἡμᾶς ἂν σώσειεν, ἂν πειθώμεθα αὐτῷ, καὶ τὸν τῆς Λήθης ποταμὸν εὖ διαβησόμεθα καὶ τὴν ψυχὴν οὐ μιανθησόμεθα. ἀλλ᾽ ἂν ἐμοὶ πειθώμεθα, νομίζοντες ἀθάνατον ψυχὴν καὶ δυνατὴν πάντα μὲν κακὰ ἀνέχεσθαι, πάντα δὲ ἀγαθά, τῆς ἄνω ὁδοῦ ἀεὶ ἑξόμεθα καὶ δικαιοσύνην μετὰ φρονήσεως παντὶ τρόπῳ ἐπιτηδεύσομεν, ἵνα καὶ ἡμῖν αὐτοῖς φίλοι ὦμεν καὶ τοῖς θεοῖς, αὐτοῦ τε μένοντες ἐνθάδε, καὶ ἐπειδὰν τὰ ἆθλα","st":"621c"},{"sp":"N","t":"αὐτῆς κομιζώμεθα, ὥσπερ οἱ νικηφόροι περιαγειρόμενοι, καὶ ἐνθάδε καὶ ἐν τῇ χιλιέτει πορείᾳ, ἣν διεληλύθαμεν, εὖ πράττωμεν.","st":"621d"}],[]);})();
